            # only append the valid keys
            key = self.get_value()
            if not key in ['', None]: keys.append(key)

        return keys

def validate(self, ticket=None):
        # Skip any already-validated ones:
        qs = self.filter(validation__isnull=True).check_groupable()
        if qs.count() == 0:
            return []
        qs.order_by('issued_date', 'id')._assign_numbers()

        return qs._validate(ticket)

def rm_rf(path):
    if os.path.isfile(path):
        os.unlink(path)
    elif os.path.isdir(path):
        for root, dirs, files in os.walk(path, topdown=False):
            for filename in files:
                filepath = os.path.join(root, filename)
                logger.info("Deleting file %s" % filepath)
                os.unlink(filepath)
            for dirname in dirs:
                dirpath = os.path.join(root, dirname)
                if os.path.islink(dirpath):
                    logger.info("Deleting link %s" % dirpath)
                    os.unlink(dirpath)
                else:
                    logger.info("Deleting dir %s" % dirpath)
                    os.rmdir(dirpath)
        logger.info("Deleting dir %s", path)
        os.rmdir(path)

def copy(self):
        if self._page_control is not None and self._page_control.hasFocus():
            self._page_control.copy()
        elif self._control.hasFocus():
            text = self._control.textCursor().selection().toPlainText()
            if text:
                lines = map(self._transform_prompt, text.splitlines())
                text = '\n'.join(lines)
                QtGui.QApplication.clipboard().setText(text)
        else:
            self.log.debug("frontend widget : unknown copy target")

def merge_trd_mkt_stock_str(trd_mkt, partial_stock_str):
    mkt_qot = Market.NONE
    mkt = TRADE.REV_TRD_MKT_MAP[trd_mkt] if trd_mkt in TRADE.REV_TRD_MKT_MAP else TrdMarket.NONE
    if mkt == TrdMarket.HK:
        mkt_qot = Market.HK
    elif mkt == TrdMarket.US:
        mkt_qot = Market.US
    elif mkt == TrdMarket.HKCC or mkt == TrdMarket.CN:
        if partial_stock_str.startswith('6') or partial_stock_str.startswith('9'):
            mkt_qot = Market.SH
        else:
            mkt_qot = Market.SZ
    else:
        raise Exception("merge_trd_mkt_stock_str: unknown trd_mkt.")

    return merge_qot_mkt_stock_str(MKT_MAP[mkt_qot], partial_stock_str)

