            raise TypeError("serial_port can only be an instance of type ISerialPort")
        self._call("onSerialPortChange",
                     in_p=[serial_port])

def _pval_from_bootci(boot, estimate):
    if estimate == 0:
        out = 1
    else:
        out = 2 * min(sum(boot > 0), sum(boot < 0)) / len(boot)
    return min(out, 1)

