def interpolate(T0, T1, t):
        if T0.to_frame != T1.to_frame:
            raise ValueError('Cannot interpolate between 2 transforms with different to frames! Got T1 {0} and T2 {1}'.format(T0.to_frame, T1.to_frame))
        dq0 = T0.dual_quaternion
        dq1 = T1.dual_quaternion

        dqt = DualQuaternion.interpolate(dq0, dq1, t)
        from_frame = "{0}_{1}_{2}".format(T0.from_frame, T1.from_frame, t)
        return RigidTransform.transform_from_dual_quaternion(dqt, from_frame, T0.to_frame)

def _parse(partial_dt):
    dt = None
    try:
        if isinstance(partial_dt, datetime):
            dt = partial_dt
        if isinstance(partial_dt, date):
            dt = _combine_date_time(partial_dt, time(0, 0, 0))
        if isinstance(partial_dt, time):
            dt = _combine_date_time(date.today(), partial_dt)
        if isinstance(partial_dt, (int, float)):
            dt = datetime.fromtimestamp(partial_dt)
        if isinstance(partial_dt, (str, bytes)):
            dt = parser.parse(partial_dt, default=timezone.now())

        if dt is not None and timezone.is_naive(dt):
            dt = timezone.make_aware(dt)
        return dt
    except ValueError:
        return None

