def flat_list(input_list):
    x = input_list
    if isinstance(x, list):
        return [a for i in x for a in flat_list(i)]
    else:
        return [x]

def transitions(self, omega_min=None, omega_max=None):
        states = self.states()
        transitions = states
        transitions = []
        for i in range(len(states)):
            si = states[i]
            for j in range(i):
                sj = states[j]
                t = Transition(sj, si)
                if t.allowed:
                    transitions += [t]

        if omega_min is not None:
            transitions = [ti for ti in transitions
                           if abs(ti.omega) >= omega_min]
        if omega_max is not None:
            transitions = [ti for ti in transitions
                           if abs(ti.omega) <= omega_max]

        return transitions

