def get(self, field, value=None):
        self.value = value
        val = self.input(field)
        if field == 'name':
            while True:
                if val != '':
                    break
                print("Name cannot be empty.")
                val = self.input(field)
        elif field == 'priority':
            if val == '':  # Use default priority
                return None
            while True:
                if val in Get.PRIORITIES.values():
                    break
                c, val = val, Get.PRIORITIES.get(val)
                if val:
                    break
                print("Unrecognized priority number or name [{}].".format(c))
                val = self.input(field)
            val = int(val)
        return val

def _next_timestamp(self, now, last):
        if now > last:
            self.last = now
            return now
        else:
            self._maybe_warn(now=now)
            self.last = last + 1
            return self.last

def stream_decode_response_unicode(iterator, r):
    encoding = get_encoding_from_headers(r.headers)
    if encoding is None:
        for item in iterator:
            yield item
        return

    decoder = codecs.getincrementaldecoder(encoding)(errors='replace')
    for chunk in iterator:
        rv = decoder.decode(chunk)
        if rv:
            yield rv
    rv = decoder.decode('', final=True)
    if rv:
        yield rv

