def _requested_name(self, name, action=None, func=None):
        if name is not None:
            if name in self._used_names:
                # start at 2 for the "second" one of this name
                n = 2
                while True:
                    pn = name + '_' + str(n)
                    if pn not in self._used_names:
                        self._used_names.add(pn)
                        return pn
                    n += 1
            else:
                self._used_names.add(name)
                return name

        if func is not None:
            if hasattr(func, '__name__'):
                name = func.__name__
                if name == '<lambda>':
                    # Avoid use of <> characters in name
                    # as they are converted to unicode
                    # escapes in SPL identifier
                    name = action + '_lambda'
            elif hasattr(func, '__class__'):
                name = func.__class__.__name__

        if name is None:
            if action is not None:
                name = action
            else:
                name = self.name

        # Recurse once to get unique version of name
        return self._requested_name(name)

def insert(self, val, pipe=None):

      p = self.redis.pipeline() if pipe is None else pipe

      try:
         key, token, formatted_key, formatted_token = self.next_formatted_pair()

         p.watch(formatted_key, formatted_token)

         # Make this atomic
         p.multi()      

         # Associate both the value and token with the key to
         # allow `get_token(key)`
         p.hsetnx(formatted_key, 'value', val)
         p.hsetnx(formatted_key, 'token', token)
         p.setnx(formatted_token, key)

         if pipe is None:
            results = p.execute()

            if not results[-2] or not results[-3]:
               raise KeyInsertError(key, 'key exists')

            if not results[-1]:
               raise TokenInsertError(token, 'token exists')

         return Pair(key, token)

      except WatchError:
         raise

      finally:
         if pipe is None:
            p.reset()

def create_summary_metadata(hparams_plugin_data_pb):
