    return tf.tile(tf.expand_dims(units, axis), repetitions)

def define_rho_vector(rho, Ne):
    rho_vect = []
    for mu in range(1, Ne**2):
        i, j, s = IJ(mu, Ne)
        i = i-1; j = j-1
        rho_vect += [part_symbolic(rho[i, j], s)]
    return Matrix(rho_vect)

def _generate_draw_order(self, node=None):
        if node is None:
            node = self._scene
        order = [(node, True)]
        children = node.children
        children.sort(key=lambda ch: ch.order)
        for ch in children:
            order.extend(self._generate_draw_order(ch))
        order.append((node, False))
        return order

