def filter(self, *args):
    if len(args) == 1 and isinstance(args[0], Filter):
      # Assign the provided Filter instance to the local variable for later use.
      filter = args[0]
    else:
      filter = Filter(*args)

    # ensure filter gets attr values the same way the rest of the query does.
    filter.object_getattr = self.object_getattr
    self.filters.append(filter)
    return self

async def debug(self, conn_id, name, cmd_args):


        device = self._get_property(conn_id, 'device')

        retval = None

        try:
            if name == 'dump_state':
                retval = device.dump_state()
            elif name == 'restore_state':
                state = cmd_args['snapshot']
                device.restore_state(state)
            elif name == 'load_scenario':
                scenario = cmd_args['scenario']
                device.load_metascenario(scenario)
            elif name == 'track_changes':
                if cmd_args['enabled']:
                    device.state_history.enable()
                else:
                    device.state_history.disable()
            elif name == 'dump_changes':
                outpath = cmd_args['path']
                device.state_history.dump(outpath)
            else:
                reason = "Unknown command %s" % name
                raise DeviceAdapterError(conn_id, 'debug {}'.format(name), reason)
        except Exception as exc:
            self._logger.exception("Error processing debug command %s: args=%s", name, cmd_args)
            reason = "Exception %s occurred during processing" % str(exc)
            raise DeviceAdapterError(conn_id, 'debug {}'.format(name), reason) from exc

        return retval

def compute_interpolator(self, ikwargs={}):
        from scipy.interpolate import RectBivariateSpline

        if 'degree' in ikwargs:
            degree = ikwargs['degree']
            if hasattr(degree, '__iter__') and len(degree) == 2:
                degx = int(degree[0])
                degy = int(degree[1])
            else:
                degx = int(degree)
                degy = int(degree)
            if degx < 0 or degy < 0:
                raise ValueError("Interpolator degree must be a non-negative "
                                 "integer")
        else:
            degx = 3
            degy = 3

        if 's' in ikwargs:
            smoothness = ikwargs['s']
        else:
            smoothness = 0

        x = np.arange(self._nx, dtype=np.float)
        y = np.arange(self._ny, dtype=np.float)
        self.interpolator = RectBivariateSpline(
            x, y, self._data.T, kx=degx, ky=degy, s=smoothness
        )

        self._store_interpolator_kwargs(ikwargs)

