            name = "{0}{1}{2}".format(
                search.group("category"), search.group("name")[0].upper(), search.group("name")[1:])
            LOGGER.debug("> Component name: '{0}' to attribute name Active_QLabel: '{1}'.".format(component, name))
        else:
            name = component
