def structure(cls):
        # type: () -> Text
        downstream = cls.cutter.elucidate()
        upstream = str(Seq(downstream).reverse_complement())
        return "".join(
            [
                upstream.replace("^", ")(").replace("_", "("),
                "N*",
                downstream.replace("^", ")(").replace("_", ")"),
            ]
        )

