def strToGUID(s):
    dat = uuid.UUID(hex=s)
    if isinstance(dat.bytes_le, str):
        # Python 2
        dat = [ord(e) for e in dat.bytes_le]
    else:
        # Python 3
        dat = list(dat.bytes_le)
    return dat

