def check_packet(self):
        if not os.path.exists(self.packet_file()):
            # No packet file, we're good
            return True
        else:
            # There's already a file, but is it still running?
            try:
                with open(self.packet_file()) as f:
                    packet = json.loads(f.read())
                if time.time() - packet['last_time'] > 3.0*packet['poll_time']:
                    # We haven't heard a ping in too long. It's probably dead
                    return True
                else:
                    # Still getting pings.. probably still a live process
                    return False
            except:
                # Failed to read file... try again in a second
                time.sleep(random.random()*2)
                return self.check_packet()

def get_two_parameters(self, regex_exp, parameters):
        Rx, Ry, other = self.get_parameters(regex_exp, parameters)
        if other is not None and other.strip():
            raise iarm.exceptions.ParsingError("Extra arguments found: {}".format(other))
        if Rx and Ry:
            return Rx.upper(), Ry.upper()
        elif not Rx:
            raise iarm.exceptions.ParsingError("Missing first positional argument")
        else:
            raise iarm.exceptions.ParsingError("Missing second positional argument")

