def put_new_symbol(  # pylint: disable=too-many-arguments
        self,
        s: sym.Symbol,
        binding: Binding,
        warn_on_shadowed_name: bool = True,
        warn_on_shadowed_var: bool = True,
        warn_if_unused: bool = True,
    ):
        st = self.symbol_table
        if warn_on_shadowed_name and self.warn_on_shadowed_name:
            if st.find_symbol(s) is not None:
                logger.warning(f"name '{s}' shadows name from outer scope")
        if (
            warn_on_shadowed_name or warn_on_shadowed_var
        ) and self.warn_on_shadowed_var:
            if self.current_ns.find(s) is not None:
                logger.warning(f"name '{s}' shadows def'ed Var from outer scope")
        if s.meta is not None and s.meta.entry(SYM_NO_WARN_WHEN_UNUSED_META_KEY, None):
            warn_if_unused = False
        st.new_symbol(s, binding, warn_if_unused=warn_if_unused)

def load_jquery(func):

    @wraps(func)
    def wrapped(browser, *args, **kwargs):
        """Run the function, loading jQuery if needed."""

        try:
            return func(browser, *args, **kwargs)
        except WebDriverException as ex:
            if not is_jquery_not_defined_error(ex.msg):
                raise

            load_script(browser, JQUERY)

            @wait_for
            def jquery_available():
                """Assert that jQuery has loaded."""
                try:
                    return browser.execute_script('return $')
                except WebDriverException:
                    raise AssertionError("jQuery is not loaded")

            jquery_available()

            return func(browser, *args, **kwargs)

    return wrapped

def parse_default_property_value(property_name, property_type_id, default_value_string):
    if property_type_id == PROPERTY_TYPE_EMBEDDED_SET_ID and default_value_string == '{}':
        return set()
    elif property_type_id == PROPERTY_TYPE_EMBEDDED_LIST_ID and default_value_string == '[]':
        return list()
    elif (property_type_id == PROPERTY_TYPE_STRING_ID and
          isinstance(default_value_string, six.string_types)):
        return default_value_string
    elif property_type_id == PROPERTY_TYPE_BOOLEAN_ID:
        return _parse_bool_default_value(property_name, default_value_string)
    elif property_type_id == PROPERTY_TYPE_DATETIME_ID:
        return _parse_datetime_default_value(property_name, default_value_string)
    elif property_type_id == PROPERTY_TYPE_DATE_ID:
        return _parse_date_default_value(property_name, default_value_string)
    else:
        raise AssertionError(u'Unsupported default value for property "{}" with type id {}: '
                             u'{}'.format(property_name, property_type_id, default_value_string))

def run_strelka(job, tumor_bam, normal_bam, univ_options, strelka_options, split=True):
    if strelka_options['chromosomes']:
        chromosomes = strelka_options['chromosomes']
    else:
        chromosomes = sample_chromosomes(job, strelka_options['genome_fai'])
    num_cores = min(len(chromosomes), univ_options['max_cores'])
    strelka = job.wrapJobFn(run_strelka_full, tumor_bam, normal_bam, univ_options,
                            strelka_options,
                            disk=PromisedRequirement(strelka_disk,
                                                     tumor_bam['tumor_dna_fix_pg_sorted.bam'],
                                                     normal_bam['normal_dna_fix_pg_sorted.bam'],
                                                     strelka_options['genome_fasta']),
                            memory='6G',
                            cores=num_cores)
    job.addChild(strelka)
    if split:
        unmerge_strelka = job.wrapJobFn(wrap_unmerge, strelka.rv(), chromosomes, strelka_options,
                                        univ_options).encapsulate()
        strelka.addChild(unmerge_strelka)
        return unmerge_strelka.rv()
    else:
        return strelka.rv()

def parse_file_path(filepath):
    # type: (pathlib.Path) -> Tuple[str, str, str]
    if not isinstance(filepath, pathlib.Path):
        filepath = pathlib.Path(filepath)
    dirname = '/'.join(filepath.parts[:len(filepath.parts) - 1])
    if len(dirname) == 0:
        dirname = None
    if len(filepath.parts) > 0:
        fname = filepath.parts[-1]
    else:
        fname = None
    fname, snapshot = blobxfer.util.parse_fileshare_or_file_snapshot_parameter(
        fname)
    return (dirname, fname, snapshot)

def wait_for_psexecsvc(host, port, username, password, timeout=900):
    if has_winexe() and not HAS_PSEXEC:
        return wait_for_winexe(host, port, username, password, timeout)
    start = time.time()
    try_count = 0
    while True:
        try_count += 1
        ret_code = 1
        try:
            stdout, stderr, ret_code = run_psexec_command(
                'cmd.exe', '/c hostname', host, username, password, port=port
            )
        except Exception as exc:
            log.exception("Unable to execute command")
        if ret_code == 0:
            log.debug('psexec connected...')
            return True
        if time.time() - start > timeout:
            return False
        log.debug(
            'Retrying psexec connection to host %s on port %s (try %s)',
            host, port, try_count
        )
        time.sleep(1)

def docelement(self):
        #This is needed since the decorating documentation
        #for types and executables is in the body of the module, but when they
        #get edited, the edit belongs to the type/executable because the character
        #falls within the absstart and end attributes.
        if self._docelement is None:
            if isinstance(self.element, Module):
                self._docelement = self.element
            else:
                ichar = self.element.module.charindex(self.icached[0], 1)
                if (ichar > self.element.docstart and ichar <= self.element.docend):
                    self._docelement = self.element.parent
                else:
                    self._docelement = self.element

        return self._docelement

