def _check_item_type(item, field_name, allowed_types, expect_list=False,
                    required_channels='all'):
    if expect_list:
        if not isinstance(item, list):
            raise TypeError('Field `%s` must be a list.' % field_name)

        # All channels of the field must be present.
        if required_channels == 'all':
            required_channels = list(range(len(item)))

        for ch in range(len(item)):
            # Check whether the field may be None
            if ch in required_channels:
                allowed_types_ch = allowed_types
            else:
                allowed_types_ch = allowed_types + (type(None),)

            if not isinstance(item[ch], allowed_types_ch):
                raise TypeError('Channel %d of field `%s` must be one of the following types:' % (ch, field_name),
                                allowed_types_ch)
    else:
        if not isinstance(item, allowed_types):
            raise TypeError('Field `%s` must be one of the following types:',
                            allowed_types)

def get_name_history(name, hostport=None, proxy=None, history_page=None):
    assert hostport or proxy, 'Need hostport or proxy'
    if proxy is None:
        proxy = connect_hostport(hostport)

    hist = {}
    indexing = None
    lastblock = None

    if history_page != None:
        resp = get_name_history_page(name, history_page, proxy=proxy)
        if 'error' in resp:
            return resp

        indexing = resp['indexing']
        lastblock = resp['lastblock']

        return {'status': True, 'history': resp['history'], 'indexing': indexing, 'lastblock': lastblock}

    for i in range(0, 100000000):       # this is obviously too big
        resp = get_name_history_page(name, i, proxy=proxy)
        if 'error' in resp:
            return resp

        indexing = resp['indexing']
        lastblock = resp['lastblock']

        if len(resp['history']) == 0:
            # caught up 
            break

        hist = name_history_merge(hist, resp['history'])

    return {'status': True, 'history': hist, 'indexing': indexing, 'lastblock': lastblock}

