def add(name, mac, mtu=1500):
    ret = {}

    if mtu > 9000 or mtu < 1500:
        return {'Error': 'mtu must be a value between 1500 and 9000.'}
    if mac != 'etherstub':
        cmd = 'dladm show-phys -m -p -o address'
        res = __salt__['cmd.run_all'](cmd)
        # dladm prints '00' as '0', so account for that.
        if mac.replace('00', '0') not in res['stdout'].splitlines():
            return {'Error': '{0} is not present on this system.'.format(mac)}

    if mac == 'etherstub':
        cmd = 'nictagadm add -l {0}'.format(name)
        res = __salt__['cmd.run_all'](cmd)
    else:
        cmd = 'nictagadm add -p mtu={0},mac={1} {2}'.format(mtu, mac, name)
        res = __salt__['cmd.run_all'](cmd)

    if res['retcode'] == 0:
        return True
    else:
        return {'Error': 'failed to create nictag.' if 'stderr' not in res and res['stderr'] == '' else res['stderr']}

def remove(self, fieldspec):

        pattern = r'(?P<field>[^.]+)(.(?P<subfield>[^.]+))?'
        match = re.match(pattern, fieldspec)
        if not match:
            return None

        grp = match.groupdict()
        for field in self.get_fields(grp['field']):
            if grp['subfield']:
                updated = []
                for code, value in pairwise(field.subfields):
                    if not code == grp['subfield']:
                        updated += [code, value]
                # if we removed the last subfield entry,
                # remove the whole field, too
                if not updated:
                    self.remove_field(field)
                else:
                    field.subfields = updated
            else:
                # it is a control field
                self.remove_field(field)

def parse_tei_corpus(path, target=['artikkel'], encoding=None):
