def restart(name, timeout=90, with_deps=False, with_parents=False):
    if 'salt-minion' in name:
        create_win_salt_restart_task()
        return execute_salt_restart_task()

    ret = set()
    ret.add(stop(name=name, timeout=timeout, with_deps=with_deps, with_parents=with_parents))
    ret.add(start(name=name, timeout=timeout, with_deps=with_deps, with_parents=with_parents))
    return False not in ret

def choices(tree):
    n = len(leaves(tree))
    addr = np.nan * np.ones((n, n-1))
    def _addresses(node, index, choices):
        # index is the index of the current internal node
        # choices is a list of (indice, 0/1) choices made
        if np.isscalar(node):
            for i, choice in choices:
                addr[node, i] = choice
            return index

        elif isinstance(node, tuple) and len(node) == 2:
            newindex = _addresses(node[0], index+1, choices + [(index, 0)])
            newindex = _addresses(node[1], newindex, choices + [(index, 1)])
            return newindex

        else:
            raise Exception("Not a tree!")

    _addresses(tree, 0, [])
    return addr

def age_to_BP(age, age_unit):
    ageBP = -1e9
    if age_unit == "Years AD (+/-)" or age_unit == "Years Cal AD (+/-)":
        if age < 0:
            age = age+1  # to correct for there being no 0 AD
        ageBP = 1950-age
    elif age_unit == "Years BP" or age_unit == "Years Cal BP":
        ageBP = age
    elif age_unit == "ka":
        ageBP = age*1000
    elif age_unit == "Ma":
        ageBP = age*1e6
    elif age_unit == "Ga":
        ageBP = age*1e9
    else:
        print("Age unit invalid. Age set to -1.0e9")

    return ageBP

def initialize_tasks(self):
        # Add a poison pill to shutdown each process.
        self.tasks = chain(self.iterable, [POISON_PILL] * self.num_processes)
        for task in islice(self.tasks, Q_MAX_SIZE):
            log.debug('Putting %s on queue', task)
            self.task_queue.put(task)

def mean(self, *args, **kwargs):
        nv.validate_groupby_func('mean', args, kwargs, ['numeric_only'])
        try:
            return self._cython_agg_general('mean', **kwargs)
        except GroupByError:
            raise
        except Exception:  # pragma: no cover
            with _group_selection_context(self):
                f = lambda x: x.mean(axis=self.axis, **kwargs)
                return self._python_agg_general(f)

def messageReceived(self, message):
        msgId, msg = message[0], message[2:]
        self._releaseId(msgId)
        d, canceller = self._requests.pop(msgId, (None, None))

        if canceller is not None and canceller.active():
            canceller.cancel()

        if d is None:
            # reply came for timed out or cancelled request, drop it silently
            return

        d.callback(msg)

