            self._tokens_dict = OrderedDict([(t.id, t) for t in tokens])
        return self._tokens_dict

def _validate_rows(self):
        for row_index in range(self.start[0], self.end[0]):
            table_row = self.table[row_index]
            used_row = self.used_cells[row_index]

            row_type = None
            if self.end[1] > self.start[1]:
                row_type = get_cell_type(table_row[self.start[1]])

            num_type_changes = 0
            for column_index in range(self.start[1], self.end[1]):
                if used_row[column_index]:
                    self.flag_change(self.flags, 'error', (row_index, column_index),
                                     self.worksheet, self.FLAGS['used'])
                if not check_cell_type(table_row[column_index], row_type):
                    row_type = get_cell_type(table_row[column_index])
                    num_type_changes += 1
                if num_type_changes > 1:
                    self.flag_change(self.flags, 'warning', (row_index, column_index-1),
                                     self.worksheet, self.FLAGS['unexpected-change'])
                    # Decrement this to catch other cells which change again
                    num_type_changes -= 1
                # Mark this cell as used
                used_row[column_index] = True

def _set_time_property(self, v, load=False):
    if hasattr(v, "_utype"):
      v = v._utype(v)
    try:
      t = YANGDynClass(v,base=time_property.time_property, is_container='container', presence=False, yang_name="time-property", rest_name="time-property", parent=self, path_helper=self._path_helper, extmethods=self._extmethods, register_paths=True, extensions={u'tailf-common': {u'callpoint': u'ptp-time-property', u'cli-suppress-show-path': None}}, namespace='urn:brocade.com:mgmt:brocade-ptp-operational', defining_module='brocade-ptp-operational', yang_type='container', is_config=False)
    except (TypeError, ValueError):
      raise ValueError({
          'error-string': """time_property must be of a type compatible with container""",
          'defined-type': "container",
          'generated-type': """YANGDynClass(base=time_property.time_property, is_container='container', presence=False, yang_name="time-property", rest_name="time-property", parent=self, path_helper=self._path_helper, extmethods=self._extmethods, register_paths=True, extensions={u'tailf-common': {u'callpoint': u'ptp-time-property', u'cli-suppress-show-path': None}}, namespace='urn:brocade.com:mgmt:brocade-ptp-operational', defining_module='brocade-ptp-operational', yang_type='container', is_config=False)""",
        })

    self.__time_property = t
    if hasattr(self, '_set'):
      self._set()

def _encrypt_assertion(self, encrypt_cert, sp_entity_id, response,
                           node_xpath=None):
        _certs = []

        if encrypt_cert:
            _certs.append(encrypt_cert)
        elif sp_entity_id is not None:
            _certs = self.metadata.certs(sp_entity_id, "any", "encryption")
        exception = None
        for _cert in _certs:
            try:
                begin_cert = "-----BEGIN CERTIFICATE-----\n"
                end_cert = "\n-----END CERTIFICATE-----\n"
                if begin_cert not in _cert:
                    _cert = "%s%s" % (begin_cert, _cert)
                if end_cert not in _cert:
                    _cert = "%s%s" % (_cert, end_cert)
                _, cert_file = make_temp(_cert.encode('ascii'), decode=False)
                response = self.sec.encrypt_assertion(response, cert_file,
                                                      pre_encryption_part(),
                                                      node_xpath=node_xpath)
                return response
            except Exception as ex:
                exception = ex
                pass
        if exception:
            raise exception
        return response

