def is_valid_ip(ip: str) -> bool:
    if not ip or "\x00" in ip:
        # getaddrinfo resolves empty strings to localhost, and truncates
        # on zero bytes.
        return False
    try:
        res = socket.getaddrinfo(
            ip, 0, socket.AF_UNSPEC, socket.SOCK_STREAM, 0, socket.AI_NUMERICHOST
        )
        return bool(res)
    except socket.gaierror as e:
        if e.args[0] == socket.EAI_NONAME:
            return False
        raise
    return True

def _get_cert_url(self):
        cert_url = self._data.get('SigningCertURL')
        if cert_url:
            if cert_url.startswith('https://'):
                url_obj = urlparse(cert_url)
                for trusted_domain in settings.BOUNCE_CERT_DOMAINS:
                    parts = trusted_domain.split('.')
                    if url_obj.netloc.split('.')[-len(parts):] == parts:
                        return cert_url
            logger.warning(u'Untrusted certificate URL: "%s"', cert_url)
        else:
            logger.warning(u'No signing certificate URL: "%s"', cert_url)
        return None

def compute( self ):
        # compute the intersection graph into @xsections dictionary
        wordlist = self.wordlist
        """ build a dictionary of words, and their intersections """
        xsections = {}
        for i in range(len(wordlist)):
            word_i = wordlist[i]
            for j in range(len(wordlist)):
                word_j = wordlist[j]
                if i == j:
                    # force self-intersection to be 0
                    if not xsections.get(word_i,None):
                        xsections[word_i] = ['']
                    else:
                        xsections[word_i].extend([''])
                    continue
                # optimize for, i > j, info is calculated already 
                if i > j:
                    xsec_counts = xsections[word_j][i]
                else:
                    xsec_counts = tamil.utf8.word_intersection( word_i, word_j )
                if not xsections.get(word_i,None):
                    xsections[word_i] =  [xsec_counts]
                else:
                    xsections[word_i].extend( [ xsec_counts ] )
        self.xsections = xsections

def binary_to_int(binary_list, lower_bound=0, upper_bound=None):
    # Edge case for empty binary_list
    if binary_list == []:
        # With 0 bits, only one value can be represented,
        # and we default to lower_bound
        return lower_bound
    else:
        # The builtin int construction can take a base argument,
        # but it requires a string,
        # so we convert our binary list to a string
        integer = int(''.join([str(bit) for bit in binary_list]), 2)

    # Trim if over upper_bound
    if (upper_bound is not None) and integer + lower_bound > upper_bound:
        # Bounce back. Ex. w/ upper_bound = 2: [0, 1, 2, 2, 1, 0]
        return upper_bound - (integer % (upper_bound - lower_bound + 1))
    else:
        # Not over upper_bound
        return integer + lower_bound

