def interpret_contribution_entry(entry):
    try:
        new_contribution_amount = float(entry['ContributionAmount'])
        entry['AmountsInterpreted'] = True
        entry['ContributionAmount'] = new_contribution_amount
    except ValueError:
        entry['AmountsInterpreted'] = False
    except TypeError:
        entry['AmountsInterpreted'] = False
    except AttributeError:
        entry['AmountsInterpreted'] = False

    try:
        contribution_date = parse_iso_str(entry['ContributionDate'])
        filed_date = parse_iso_str(entry['FiledDate'])
        entry['DatesInterpreted'] = True
        entry['ContributionDate'] = contribution_date
        entry['FiledDate'] = filed_date
    except ValueError:
        entry['DatesInterpreted'] = False
    except TypeError:
        entry['DatesInterpreted'] = False
    except AttributeError:
        entry['DatesInterpreted'] = False

    try: 
        amended = parse_yes_no_str(entry['Amended'])
        amendment = parse_yes_no_str(entry['Amendment'])
        entry['BooleanFieldsInterpreted'] = True
        entry['Amended'] = amended
        entry['Amendment'] = amendment
    except ValueError:
        entry['BooleanFieldsInterpreted'] = False
    except TypeError:
        entry['BooleanFieldsInterpreted'] = False
    except AttributeError:
        entry['BooleanFieldsInterpreted'] = False

    return entry

def from_name(cls, relation_name, conversations=None):
        if relation_name is None:
            return None
        relation_class = cls._cache.get(relation_name)
        if relation_class:
            return relation_class(relation_name, conversations)
        role, interface = hookenv.relation_to_role_and_interface(relation_name)
        if role and interface:
            relation_class = cls._find_impl(role, interface)
            if relation_class:
                cls._cache[relation_name] = relation_class
                return relation_class(relation_name, conversations)
        return None

def _set_parameter(encoder, parameter, parameter_name, val):
    rc = lib.BrotliEncoderSetParameter(encoder, parameter, val)

    if parameter == lib.BROTLI_PARAM_MODE:
        _validate_mode(val)
    elif parameter == lib.BROTLI_PARAM_QUALITY:
        _validate_quality(val)
    elif parameter == lib.BROTLI_PARAM_LGWIN:
        _validate_lgwin(val)
    elif parameter == lib.BROTLI_PARAM_LGBLOCK:
        _validate_lgblock(val)
    else:  # pragma: no cover
        raise RuntimeError("Unexpected parameter!")

    # This block is defensive: I see no way to hit it, but as long as the
    # function returns a value we can live in hope that the brotli folks will
    # enforce their own constraints.
    if rc != lib.BROTLI_TRUE:  # pragma: no cover
        raise Error(
            "Error setting parameter %s: %d" % (parameter_name, val)
        )

def remove_hairs(inp, hairs=HAIRS):
    while inp and inp[-1] in hairs:
        inp = inp[:-1]

    while inp and inp[0] in hairs:
        inp = inp[1:]

    return inp

def selection_error_control(self, form_info):
        keys, names = self.return_selected_form_items(form_info['ChannelList'])
        chosen_channels_number = len(keys)

        if form_info['new_channel'] and chosen_channels_number < 2:
            return False, _(
                u"You should choose at least two channel to merge operation at a new channel.")
        elif form_info['existing_channel'] and chosen_channels_number == 0:
            return False, _(
                u"You should choose at least one channel to merge operation with existing channel.")
        elif form_info['find_chosen_channel'] and chosen_channels_number != 1:
            return False, _(u"You should choose one channel for split operation.")

        return True, None

def _runable_for_event(f, tag, stage):

    if not hasattr(f, '__ambry_event__'):
        return False

    f_tag, f_stage = f.__ambry_event__

    if stage is None:
        stage = 0

    if tag != f_tag or stage != f_stage:
        return False

    return True

def slugify(value, allow_dots=False, allow_unicode=False):
    if allow_dots:
        pattern = _re_pattern_allow_dots
    else:
        pattern = _re_pattern

    value = six.text_type(value)
    if allow_unicode:
        value = unicodedata.normalize('NFKC', value)
        value = pattern.sub('', value).strip().lower()
        return _re_spaces.sub('-', value)
    value = unicodedata.normalize('NFKD', value).encode(
        'ascii', 'ignore').decode('ascii')
    value = pattern.sub('', value).strip().lower()
    return _re_spaces.sub('-', value)

def pmap_field(key_type, value_type, optional=False, invariant=PFIELD_NO_INVARIANT):
    TheMap = _make_pmap_field_type(key_type, value_type)

    if optional:
        def factory(argument):
            if argument is None:
                return None
            else:
                return TheMap.create(argument)
    else:
        factory = TheMap.create

    return field(mandatory=True, initial=TheMap(),
                 type=optional_type(TheMap) if optional else TheMap,
                 factory=factory, invariant=invariant)

def attributes_strToDict(astr_attributes, astr_separator=" "):
  adict = {}
  alist = str2lst(astr_attributes, astr_separator)
  for str_pair in alist:
    alistTuple = str2lst(str_pair, "=")
    adict.setdefault(alistTuple[0], alistTuple[1].strip(chr(0x22) + chr(0x27)))
  return adict

def merge_boundboxes(*bb_list):
    # Verify types
    if not all(isinstance(x, cadquery.BoundBox) for x in bb_list):
        raise TypeError(
            "parameters must be cadquery.BoundBox instances: {!r}".format(bb_list)
        )

    if len(bb_list) <= 1:
        return bb_list[0]  # if only 1, nothing to merge; simply return it

    # Find the smallest bounding box to enclose each of those given
    min_params = list(min(*vals) for vals in zip(  # minimum for each axis
        *((bb.xmin, bb.ymin, bb.zmin) for bb in bb_list)
    ))
    max_params = list(max(*vals) for vals in zip(  # maximum for each axis
        *((bb.xmax, bb.ymax, bb.zmax) for bb in bb_list)
    ))

    #__import__('ipdb').set_trace()

    # Create new object with combined parameters
    WrappedType = type(bb_list[0].wrapped)  # assuming they're all the same
    wrapped_bb = WrappedType(*(min_params + max_params))
    return cadquery.BoundBox(wrapped_bb)

