def _untransform(orig_xy, screen_xy, ax):
    tr_xy = ax.transData.transform(orig_xy)
    return (
        orig_xy
        if ((tr_xy == screen_xy) | np.isnan(tr_xy) & np.isnan(screen_xy)).all()
        else ax.transData.inverted().transform(screen_xy))

def get_currency(self, code):
        missing = True
        for currency in self.currencies[0]:
            try:
                if code != currency.find('Ccy').text:
                    continue
            except AttributeError:
                continue

            missing = False
            yield currency

        if missing:
            raise RuntimeError("%s: %s not found" % (self.name, code))

def getClassAllSupers(self, aURI):
        aURI = aURI
        try:
            qres = self.rdflib_graph.query("""SELECT DISTINCT ?x
                     WHERE {
                         { <%s> rdfs:subClassOf+ ?x }
                         FILTER (!isBlank(?x))
                     }
                     """ % (aURI))
        except:
            printDebug(
                "... warning: the 'getClassAllSupers' query failed (maybe missing SPARQL 1.1 support?)"
            )
            qres = []
        return list(qres)

def intervals(start, end, interval):
    interval = _seconds_or_timedelta(interval)
    current_timestamp = start
    while current_timestamp.epoch < end.epoch:
        yield current_timestamp

        current_timestamp = current_timestamp.add(
            seconds=interval.total_seconds()
        )

