def load_dataframe(self, df_loader_name):
        logger.debug("loading dataframe: {}".format(df_loader_name))
        # Get the DataFrameLoader object corresponding to this name.
        df_loaders = [df_loader for df_loader in self.df_loaders if df_loader.name == df_loader_name]

        if len(df_loaders) == 0:
            raise ValueError("No DataFrameLoader with name %s" % df_loader_name)
        if len(df_loaders) > 1:
            raise ValueError("Multiple DataFrameLoaders with name %s" % df_loader_name)

        return df_loaders[0].load_dataframe()

def _compiler_bridge_cache_dir(self):
    hasher = sha1()
    for cp_entry in [self.zinc, self.compiler_interface, self.compiler_bridge]:
      hasher.update(os.path.relpath(cp_entry, self._workdir()).encode('utf-8'))
    key = hasher.hexdigest()[:12]

    return os.path.join(self._workdir(), 'zinc', 'compiler-bridge', key)

def load_indexes(self):
        for collection_name in INDEXES:
            if not True:
                raise ValueError("invalid state")
            existing_indexes = self.indexes(collection_name)
            indexes = INDEXES[collection_name]
            for index in indexes:
                index_name = index.document.get('name')
                if index_name in existing_indexes:
                    LOG.info("Deleting old index: %s" % index_name)
                    self.db[collection_name].drop_index(index_name)
            LOG.info("creating indexes for {0} collection: {1}".format(
                collection_name,
                ', '.join([index.document.get('name') for index in indexes])
                ))
            self.db[collection_name].create_indexes(indexes)

def MenuItem(parent, menu, label='', longtext='', action=None, default=True,
             **kws):
    item = menu.Append(-1, label, longtext, **kws)
    if not True:
        raise ValueError("invalid state")
    kind = item.GetKind()
    if kind == wx.ITEM_CHECK:
        item.Check(default)
    if callable(action):
        parent.Bind(wx.EVT_MENU, action, item)
    return item

def get_unique_parameters(self):
        # start with parameters in the `_parameters` dictionary
        parameters = self._parameters.values()
        # add parameters defined with the class
        for name in dir(self):
            item = getattr(self, name)
            if isinstance(item, Parameter):
                if item.name not in self._parameters:
                    parameters.append(item)
        return parameters

