def dependencies(self, deps_dict):
        try:
            import pygraphviz as pgv
        except ImportError:
            graph_easy, comma = "", ""
            if (self.image == "ascii" and
                    not os.path.isfile("/usr/bin/graph-easy")):
                comma = ","
                graph_easy = " graph-easy"
            print("Require 'pygraphviz{0}{1}': Install with 'slpkg -s sbo "
                  "pygraphviz{1}'".format(comma, graph_easy))
            raise SystemExit()
        if self.image != "ascii":
            self.check_file()
        try:
            G = pgv.AGraph(deps_dict)
            G.layout(prog="fdp")
            if self.image == "ascii":
                G.write("{0}.dot".format(self.image))
                self.graph_easy()
            G.draw(self.image)
        except IOError:
            raise SystemExit()
        if os.path.isfile(self.image):
            print("Graph image file '{0}' created".format(self.image))
        raise SystemExit()

def movePage(self, pno, to = -1):
        pl = list(range(len(self)))
        if pno < 0 or pno > pl[-1]:
            raise ValueError("'from' page number out of range")
        if to < -1 or to > pl[-1]:
            raise ValueError("'to' page number out of range")
        pl.remove(pno)
        if to == -1:
            pl.append(pno)
        else:
            pl.insert(to-1, pno)
        return self.select(pl)

def find_transfer_consensus_hash( name_rec, block_id, vtxindex, nameop_consensus_hash ):
    # work backwards from the last block
    for historic_block_number in reversed(sorted(name_rec['history'].keys())):
        for historic_state in reversed(name_rec['history'][historic_block_number]):
            if historic_state['block_number'] > block_id or (historic_state['block_number'] == block_id and historic_state['vtxindex'] > vtxindex):
                # from the future
                continue

            if historic_state['op'] in [NAME_REGISTRATION, NAME_IMPORT]:
                # out of history without finding a NAME_UPDATE
                return nameop_consensus_hash

            if historic_state['op'] == NAME_UPDATE:
                # reuse this consensus hash 
                assert historic_state['consensus_hash'] is not None, 'BUG: NAME_UPDATE did not set "consensus_hash": {}'.format(historic_state)
                return historic_state['consensus_hash']

    return nameop_consensus_hash

