def bind(self, exchange, routing_key, *, arguments=None):
        if self.deleted:
            raise Deleted("Queue {} was deleted".format(self.name))
        if not exchange:
            raise InvalidExchangeName("Can't bind queue {} to the default exchange".format(self.name))

        self.sender.send_QueueBind(self.name, exchange.name, routing_key, arguments or {})
        yield from self.synchroniser.wait(spec.QueueBindOK)
        b = QueueBinding(self.reader, self.sender, self.synchroniser, self, exchange, routing_key)
        self.reader.ready()
        return b

def rotate_direction(hexgrid_type, direction, ccw=True):
    if hexgrid_type in [TILE, EDGE]:
        directions = ['NW', 'W', 'SW', 'SE', 'E', 'NE', 'NW'] if ccw \
                else ['NW', 'NE', 'E', 'SE', 'SW', 'W', 'NW']
        return directions[directions.index(direction) + 1]
    elif hexgrid_type in [NODE]:
        directions = ['N', 'NW', 'SW', 'S', 'SE', 'NE', 'N'] if ccw \
            else ['N', 'NE', 'SE', 'S', 'SW', 'NW', 'N']
        return directions[directions.index(direction) + 1]
    else:
        raise ValueError('Invalid hexgrid type={} passed to rotate direction'.format(hexgrid_type))

