def unquote (tmp, matching=False):
    if not tmp:
        return tmp
    if len(tmp) < 2:
        return tmp
    if matching:
        if tmp[0] in ("\"'") and tmp[0] == tmp[-1]:
            tmp = tmp[1:-1]
    else:
        if tmp[0] in ("\"'"):
            tmp = tmp[1:]
        if tmp[-1] in ("\"'"):
            tmp = tmp[:-1]
    return tmp

