def get_span(docgraph, node_id, debug=False):
    if debug is True and is_directed_acyclic_graph(docgraph) is False:
        warnings.warn(
            ("Can't reliably extract span '{0}' from cyclical graph'{1}'."
            "Maximum recursion depth may be exceeded.").format(node_id,
                                                                   docgraph))
    span = []
    if docgraph.ns+':token' in docgraph.node[node_id]:
        span.append(node_id)

    for src_id, target_id, edge_attribs in docgraph.out_edges_iter(node_id,
                                                                data=True):
        if src_id == target_id:
            continue  # ignore self-loops
        # ignore pointing relations
        if edge_attribs['edge_type'] != EdgeTypes.pointing_relation:
            span.extend(get_span(docgraph, target_id))
    return sorted(span, key=natural_sort_key)

def get_object_from_normpath(self, file_path):
        file_path = make_string_path(file_path)
        if file_path == self.root.name:
            return self.root
        if file_path == self.dev_null.name:
            return self.dev_null

        file_path = self._original_path(file_path)
        path_components = self._path_components(file_path)
        target_object = self.root
        try:
            for component in path_components:
                if S_ISLNK(target_object.st_mode):
                    target_object = self.resolve(target_object.contents)
                if not S_ISDIR(target_object.st_mode):
                    if not self.is_windows_fs:
                        self.raise_io_error(errno.ENOTDIR, file_path)
                    self.raise_io_error(errno.ENOENT, file_path)
                target_object = target_object.get_entry(component)
        except KeyError:
            self.raise_io_error(errno.ENOENT, file_path)
        return target_object

def _send_byte(self,value):

        # Coerce to int. This will throw a ValueError if the value can't
        # actually be converted.
        if type(value) != int:
            new_value = int(value)

            if self.give_warnings:
                w = "Coercing {} into int ({})".format(value,new_value)
                warnings.warn(w,Warning)
                value = new_value

        # Range check
        if value > 255 or value < 0:
            err = "Value {} exceeds the size of the board's byte.".format(value)
            raise OverflowError(err)

        return struct.pack("B",value)

