def fix_string_case(text):
    fixed = []
    for i in text:
        if is_case_sensitive(i):
            fixed.append(i)
        else:
            fixed.append(i.lower())
    return ''.join(fixed)

def walk_transitive_dependency_graph(self,
                                       addresses,
                                       work,
                                       predicate=None,
                                       postorder=False,
                                       dep_predicate=None,
                                       prelude=None,
                                       epilogue=None):
    walk = self._walk_factory(dep_predicate)

    def _walk_rec(addr, level=0):
      # If we've followed an edge to this address, stop recursing.
      if not walk.expand_once(addr, level):
        return

      target = self._target_by_address[addr]

      if predicate and not predicate(target):
        return

      if not postorder and walk.do_work_once(addr):
        work(target)

      if prelude:
        prelude(target)

      for dep_address in self._target_dependencies_by_address[addr]:
        if walk.expanded_or_worked(dep_address):
          continue
        if walk.dep_predicate(target, self._target_by_address[dep_address], level):
          _walk_rec(dep_address, level + 1)

      if epilogue:
        epilogue(target)

      if postorder and walk.do_work_once(addr):
        work(target)

    for address in addresses:
      _walk_rec(address)

def apply(request, task_name):
    try:
        task = tasks[task_name]
    except KeyError:
        raise Http404('apply: no such task')
    return task_view(task)(request)

def get_args_and_kwargs(self):

        args = None
        kwargs = None

        if self.args:
            args = []
            kwargs = {}
            for arg in self.args:
                if arg.is_named:
                    kwargs[arg.arg] = arg.value
                else:
                    args.append(arg.value)

        return args, kwargs

def _yield_callbacks(self):
        print_logs = []
        for item in self.get_default_callbacks() + (self.callbacks or []):
            if isinstance(item, (tuple, list)):
                named_by_user = True
                name, cb = item
            else:
                named_by_user = False
                cb = item
                if isinstance(cb, type):  # uninitialized:
                    name = cb.__name__
                else:
                    name = cb.__class__.__name__
            if isinstance(cb, PrintLog) or (cb == PrintLog):
                print_logs.append((name, cb, named_by_user))
            else:
                yield name, cb, named_by_user
        yield from print_logs

