        return _services[0]

def solve_max(self, expr):
        if isinstance(expr, int):
            return expr
        expr = self.migrate_expression(expr)
        return self._solver.max(self._constraints, expr)

def __add_text(self, text):
        if text is not None and not isinstance(text, six.text_type):
            raise TypeError('Local symbol definition must be a Unicode sequence or None: %r' % text)
        sid = self.__new_sid()
        location = None
        if self.table_type.is_shared:
            location = self.__import_location(sid)
        token = SymbolToken(text, sid, location)
        self.__add(token)
        return token

def get_um(method_name, response=False):
    key = (method_name, response)

    if key not in method_lookup:
        match = re.findall(r'^([a-z]+)\.([a-z]+)#(\d)?$', method_name, re.I)
        if not match:
            return None

        interface, method, version = match[0]

        if interface not in service_lookup:
            return None

        package = import_module(service_lookup[interface])

        service = getattr(package, interface, None)
        if service is None:
            return None

        for method_desc in service.GetDescriptor().methods:
            name = "%s.%s#%d" % (interface, method_desc.name, 1)

            method_lookup[(name, False)] = getattr(package, method_desc.input_type.full_name, None)
            method_lookup[(name, True)] = getattr(package, method_desc.output_type.full_name, None)

    return method_lookup[key]

def _mark_received(self, tsn):
        # it's a duplicate
        if uint32_gte(self._last_received_tsn, tsn) or tsn in self._sack_misordered:
            self._sack_duplicates.append(tsn)
            return True

        # consolidate misordered entries
        self._sack_misordered.add(tsn)
        for tsn in sorted(self._sack_misordered):
            if tsn == tsn_plus_one(self._last_received_tsn):
                self._last_received_tsn = tsn
            else:
                break

        # filter out obsolete entries
        def is_obsolete(x):
            return uint32_gt(x, self._last_received_tsn)
        self._sack_duplicates = list(filter(is_obsolete, self._sack_duplicates))
        self._sack_misordered = set(filter(is_obsolete, self._sack_misordered))

def _remove_blank(l):
        ret = []
        for i, _ in enumerate(l):
            if l[i] == 0:
                break
            ret.append(l[i])
        return ret

def _get_ip_address(self, request):
        ipaddr = request.META.get("HTTP_X_FORWARDED_FOR", None)
        if ipaddr:
            # X_FORWARDED_FOR returns client1, proxy1, proxy2,...
            return ipaddr.split(",")[0].strip()
        return request.META.get("REMOTE_ADDR", "")

def _hashes_match(self, a, b):
        if len(a) != len(b):
            return False
        diff = 0
        if six.PY2:
            a = bytearray(a)
            b = bytearray(b)
        for x, y in zip(a, b):
            diff |= x ^ y
        return not diff

def backup_histories_df(self):
        backup = {}
        for point in self.points:
            if point.history.dtypes == object:
                backup[point.properties.name] = (
                    point.history.replace(["inactive", "active"], [0, 1])
                    .resample("1s")
                    .mean()
                )
            else:
                backup[point.properties.name] = point.history.resample("1s").mean()

        df = pd.DataFrame(dict([(k, pd.Series(v)) for k, v in backup.items()]))
        return df.fillna(method="ffill")

def run_svc_action(self, name, replace=None, svc=None):
        actions = svc.get('actions')
        if actions and actions.get(name):
            return self.run(name, actions=actions, replace=replace)
        if svc.get(name + "-hook"):
            return self.run(name, actions={
                name: {
                    "type": "hook",
                    "url": svc.get(name + "-hook")
                }
            }, replace=replace)
        self.die("Unable to find action {name} on service {svc}",
                 name=name, svc=svc.get('name', ''))

