        if isinstance(resource, Secret) and resource.mount == 'cubbyhole':
            return a_mounts

        active_mount = find_backend(resource.mount, active_mounts)
        if not active_mount:
            actual_mount = find_backend(resource.mount, self._mounts)
            a_mounts.append(actual_mount)
