def _get_example_from_basic_type(type):
        if type == 'integer':
            return [42, 24]
        elif type == 'number':
            return [5.5, 5.5]
        elif type == 'string':
            return ['string', 'string2']
        elif type == 'datetime':
            return ['2015-08-28T09:02:57.481Z', '2015-08-28T09:02:57.481Z']
        elif type == 'boolean':
            return [False, True]
        elif type == 'null':
            return ['null', 'null']

def search_elementnames(self, *substrings: str,
                            name: str = 'elementnames') -> 'Selection':
        try:
            selection = Selection(name)
            for element in self.elements:
                for substring in substrings:
                    if substring in element.name:
                        selection.elements += element
                        break
            return selection
        except BaseException:
            values = objecttools.enumeration(substrings)
            objecttools.augment_excmessage(
                f'While trying to determine the elements of selection '
                f'`{self.name}` with names containing at least one '
                f'of the given substrings `{values}`')

def _loadTwoPartSource(self, sourceFName, sourceLines):
        lineno = 1
        enterInConfstems = 0
        if sourceFName.find("conferences")!=-1:
            enterInConfstems = 1
        for ln in sourceLines:
            lineno += 1
            try:
                stem, source = ln.split("\t", 1)
                stem = stem.strip()[-9:]
                if not source.strip():
                    sys.stderr.write("sourcematchers.py: warning: skipping entry %s in file %s\n"%(ln.strip(),sourceFName))
                    continue
                self._addPub(stem, source)
                if enterInConfstems:
                    self.confstems[stem] = 1
            except ValueError:
                sys.stderr.write("sourcematchers.py: %s (%d): skipping source line: %s"%(sourceFName,lineno,ln))

def value_indexes_mapping(l):
    pt = copy.deepcopy(l)
    desc = {}
    vset = set({})
    for v in pt:
        vset.add(v)
    for v in vset:
        desc[v] = []
    for i in range(0,l.__len__()):
        desc[l[i]].append(i)
    return(desc)

