def callRemote(self, methodName, *args, **kwargs):
        expectReply = kwargs.get('expectReply', True)
        autoStart = kwargs.get('autoStart', True)
        timeout = kwargs.get('timeout', None)
        interface = kwargs.get('interface', None)

        m = None

        for i in self.interfaces:
            if interface and not interface == i.name:
                continue
            m = i.methods.get(methodName, None)
            if m:
                break

        if m is None:
            raise AttributeError(
                'Requested method "%s" is not a member of any of the '
                'supported interfaces' % (methodName,),
            )

        if len(args) != m.nargs:
            raise TypeError(
                '%s.%s takes %d arguments (%d given)' %
                (i.name, methodName, m.nargs, len(args)),
            )

        return self.objHandler.conn.callRemote(
            self.objectPath, methodName,
            interface=i.name,
            destination=self.busName,
            signature=m.sigIn,
            body=args,
            expectReply=expectReply,
            autoStart=autoStart,
            timeout=timeout,
            returnSignature=m.sigOut,
        )

def get_model_class_from_string(model_path):
    try:
        app_name, model_name = model_path.split('.')
    except ValueError:
        raise ImproperlyConfigured('`%s` must have the following format: `app_name.model_name`.' % model_path)

    if apps_get_model is None:
        model = get_model(app_name, model_name)
    else:
        try:
            model = apps_get_model(app_name, model_name)
        except (LookupError, ValueError):
            model = None

    if model is None:
        raise ImproperlyConfigured('`%s` refers to a model `%s` that has not been installed.' % (model_path, model_name))

    return model

