def related_by_category(obj, count, collected_so_far, mods=[], only_from_same_site=True):
    related = []
    # top objects in given category
    if count > 0:
        from ella.core.models import Listing
        cat = obj.category
        listings = Listing.objects.get_queryset_wrapper(
            category=cat,
            content_types=[ContentType.objects.get_for_model(m) for m in mods]
        )
        for l in listings[0:count + len(related)]:
            t = l.publishable
            if t != obj and t not in collected_so_far and t not in related:
                related.append(t)
                count -= 1

            if count <= 0:
                return related
    return related

def rbigint_to_string(obj):
    if isinstance(obj, (str, bytes)) or not obj:
        # the input is the desired one, return as is
        return obj
    elif hasattr(obj, 'items'):
        # the input is a dict {}
        for k, item in obj.items():
            obj[k] = rbigint_to_string(item)
        return obj
    elif hasattr(obj, '__iter__'):
        # the input is iterable
        is_tuple = isinstance(obj, tuple)
        if is_tuple:
            obj = list(obj)
        for i, item in enumerate(obj):
            obj[i] = rbigint_to_string(item)
        return obj if not is_tuple else tuple(obj)
    return bigint_to_string(obj)

def plot_time_elapsed(filename, elapsed=False, unit='s', plot_kwargs=None):
    import matplotlib.pyplot as plt

    if plot_kwargs is None:
        plot_kwargs = {}

    data_column = 3 if elapsed else 1
    data = np.genfromtxt(filename, dtype='i8,f4',
                         usecols=(0, data_column), names=['k', 'v'])
    index = data['k']
    values = data['v']
    if unit == 's':
        pass
    elif unit == 'm':
        values /= 60
    elif unit == 'h':
        values /= 3600
    elif unit == 'd':
        values /= 3600 * 24
    else:
        raise ValueError('The argument `unit` must be chosen from {s|m|h|d}.')
    plt.plot(index, values, **plot_kwargs)

def apply(self):
        self._old_config = {k: v for k, v in _config.items()}
        self._apply()

def mutate(self, row):
        mutation_count = len(row._get_mutations())
        if mutation_count > MAX_MUTATIONS:
            raise MaxMutationsError(
                "The row key {} exceeds the number of mutations {}.".format(
                    row.row_key, mutation_count
                )
            )

        if (self.total_mutation_count + mutation_count) >= MAX_MUTATIONS:
            self.flush()

        # Store the row and update cumulative metrics to reflect the new data.
        self.rows.append(row)
        self.total_mutation_count += mutation_count
        self.total_size += row.get_mutations_size()

        if self.total_size >= self.max_row_bytes or len(self.rows) >= self.flush_count:
            self.flush()

