                data.get('closeoutAsk')
            )

        return Price(**data)

def add_jump(self, name, min, max, num, warp=None, var_type=float):
        if not isinstance(var_type, type):
            if var_type == 'int':
                var_type = int
            elif var_type == 'float':
                var_type = float
            else:
                raise ValueError('var_type (%s) is not supported. use '
                                 '"int" or "float",' % (var_type))

        min, max = map(var_type, (min, max))
        num = int(num)

        if not warp:
            choices = np.linspace(min, max, num=num, dtype=var_type)
        elif (min >= 0) and warp == 'log':
            choices = np.logspace(np.log10(min), np.log10(max), num=num,
                                  dtype=var_type)
        elif (min <= 0)and warp == 'log':
            raise ValueError('variable %s: log-warping requires min > 0')
        else:
            raise ValueError('variable %s: warp=%s is not supported. use '
                             'None or "log",' % (name, warp))

        self.variables[name] = EnumVariable(name, choices.tolist())

def lower_unary_transformations(ir_blocks):
    def visitor_fn(expression):
        """Raise error if current expression is a UnaryTransformation."""
        if not isinstance(expression, expressions.UnaryTransformation):
            return expression
        raise NotImplementedError(
            u'UnaryTransformation expression "{}" encountered with IR blocks {} is unsupported by '
            u'the SQL backend.'.format(expression, ir_blocks)
        )

    new_ir_blocks = [
        block.visit_and_update_expressions(visitor_fn)
        for block in ir_blocks
    ]
    return new_ir_blocks

