def optical_flow_magnitude(image_sequence, max_diff=60, gftt_options={}):
    flow = []
    prev_img = None
    for img in image_sequence:
        if img.ndim == 3 and img.shape[2] == 3:
            img = cv2.cvtColor(img, cv2.COLOR_BGR2GRAY)

        if prev_img is None:
            prev_img = img
            continue
        (next_points, prev_points) = track_points(prev_img, img, gftt_params=gftt_options)
        distance = np.sqrt(np.sum((next_points - prev_points)**2, 1))
        distance2 = distance[np.nonzero(distance < max_diff)] # Crude outlier rejection
        dm = np.mean(distance2)
        if np.isnan(dm):
            dm = 0
        flow.append(dm)
        prev_img = img

    return np.array(flow)

def parse_accept_header(value, cls=None):
    if cls is None:
        cls = Accept

    if not value:
        return cls(None)

    result = []
    for match in _accept_re.finditer(value):
        quality = match.group(2)
        if not quality:
            quality = 1
        else:
            quality = max(min(float(quality), 1), 0)
        result.append((match.group(1), quality))
    return cls(result)

def _set_value(instance_to_path_map, path_to_instance_map, prop_tree, config_instance):
    path = instance_to_path_map[config_instance]

    # find group
    group = prop_tree
    for elem in path[:-1]:
        group = getattr(group, elem)

    assert group._key == config_instance.parent.key
    setattr(group, config_instance.key, config_instance.value)

    #
    # bind config to the term
    #
    # FIXME: Make all the terms to store config instance the same way.
    term = getattr(group, config_instance.key)
    try:
        if hasattr(term, '_term'):
            # ScalarTermS and ScalarTermU case
            term._term._config = config_instance
            return
    except KeyError:
        # python3 case. TODO: Find the way to make it simple.
        pass

    try:
        if hasattr(term, '_config'):
            term._config = config_instance
            return
    except KeyError:
        # python3 case. TODO: Find the way to make it simple.
        pass
    else:
        pass

def related_lua_args(self):
        related = self.queryelem.select_related
        if related:
            meta = self.meta
            for rel in related:
                field = meta.dfields[rel]
                relmodel = field.relmodel
                bk = self.backend.basekey(relmodel._meta) if relmodel else ''
                fields = list(related[rel])
                if meta.pkname() in fields:
                    fields.remove(meta.pkname())
                    if not fields:
                        fields.append('')
                ftype = field.type if field in meta.multifields else ''
                data = {'field': field.attname, 'type': ftype,
                        'bk': bk, 'fields': fields}
                yield field.name, data

