        else:
            subdomain = to_unicode(subdomain, 'ascii')
        return (subdomain and subdomain + u'.' or u'') + self.server_name

def __get_stack_id(self, value, values, height):

        def step(values, height):
            step_range = max(values) - min(values)
            return (((step_range / float((len(self.__list) * height) - 1)))
                    or 1)

        step_value = step(values, height)
        return int(round((value - min(values)) / step_value))

def dict(cls, *args, **kwds):
        if args:
            if len(args) > 1:
                raise TypeError("Too many positional arguments")
            x = args[0]
            keys = []
            vals = []
            try:
                x_keys = x.keys
            except AttributeError:
                for k, v in x:
                    keys.append(k)
                    vals.append(v)
            else:
                keys = x_keys()
                vals = [x[k] for k in keys]
            return q('!', keys, vals)
        else:
            if kwds:
                keys = []
                vals = []
                for k, v in kwds.items():
                    keys.append(k)
                    vals.append(v)
                return q('!', keys, vals)
            else:
                return q('()!()')

def get_owner(self, path, use_sudo=False):
        func = use_sudo and run_as_root or self.run
        # I'd prefer to use quiet=True, but that's not supported with older
        # versions of Fabric.
        with self.settings(hide('running', 'stdout'), warn_only=True):
            result = func('stat -c %%U "%(path)s"' % locals())
            if result.failed and 'stat: illegal option' in result:
                # Try the BSD version of stat
                return func('stat -f %%Su "%(path)s"' % locals())
            return result

def get_descriptions(fastas):
    id2desc = {}
    for fasta in fastas:
        for seq in parse_fasta(fasta):
            header = seq[0].split('>')[1].split(' ')
            id = header[0]
            if len(header) > 1:
                desc = ' '.join(header[1:])
            else:
                desc = 'n/a'
            length = float(len([i for i in seq[1].strip() if i != '*']))
            id2desc[id] = [fasta, desc, length]
    return id2desc

