            elif isinstance(stmt, Influence):
                self._add_influence(stmt)
        network_description = ''
        self.cx['networkAttributes'].append({'n': 'name',
                                             'v': self.network_name})
        self.cx['networkAttributes'].append({'n': 'description',
                                             'v': network_description})
        cx_str = self.print_cx()
        return cx_str

def _normalize_options(self, options):
        for key, value in list(options.items()):
            if '--' in key:
                normalized_key = self._normalize_arg(key)
            else:
                normalized_key = '--%s' % self._normalize_arg(key)

            if isinstance(value, (list, tuple)):
                for opt_val in value:
                    yield (normalized_key, opt_val)
            else:
                yield (normalized_key, str(value) if value else value)

def collapse_nested(self, cats, max_nestedness=10):
        children = []
        removed = set()
        nestedness = max_nestedness

        old = list(self.widget.options.values())
        nested = [cat for cat in old if getattr(cat, 'cat') is not None]
        parents = {cat.cat for cat in nested}
        parents_to_remove = cats
        while len(parents_to_remove) > 0 and nestedness > 0:
            for cat in nested:
                if cat.cat in parents_to_remove:
                    children.append(cat)
            removed = removed.union(parents_to_remove)
            nested = [cat for cat in nested if cat not in children]
            parents_to_remove = {c for c in children if c in parents - removed}
            nestedness -= 1
        self.remove(children)

