def make_non_negative_axis(axis, rank):
  axis = tf.convert_to_tensor(value=axis, name="axis")
  rank = tf.convert_to_tensor(value=rank, name="rank")
  axis_ = tf.get_static_value(axis)
  rank_ = tf.get_static_value(rank)

  # Static case.
  if axis_ is not None and rank_ is not None:
    is_scalar = axis_.ndim == 0
    if is_scalar:
      axis_ = [axis_]
    positive_axis = []
    for a_ in axis_:
      if a_ < 0:
        positive_axis.append(rank_ + a_)
      else:
        positive_axis.append(a_)
    if is_scalar:
      positive_axis = positive_axis[0]
    return tf.convert_to_tensor(value=positive_axis, dtype=axis.dtype)

  # Dynamic case.
  # Unfortunately static values are lost by this tf.where.
  return tf.where(axis < 0, rank + axis, axis)

def find_sources(obj, argspec=None):

    if argspec is None:
        argspec = [DEFAULT_ARGSPEC]

    return { n: m for n, m in inspect.getmembers(obj, callable)
        if not n.startswith('_') and
        inspect.getargspec(m).args in argspec }

def _check_keys(self, rdict):
        if '_meta_data' in rdict:
            error_message = "Response contains key '_meta_data' which is "\
                "incompatible with this API!!\n Response json: %r" % rdict
            raise DeviceProvidesIncompatibleKey(error_message)
        for x in rdict:
            if not re.match(tokenize.Name, x):
                error_message = "Device provided %r which is disallowed"\
                    " because it's not a valid Python 2.7 identifier." % x
                raise DeviceProvidesIncompatibleKey(error_message)
            elif keyword.iskeyword(x):
                # If attribute is keyword, append underscore to attribute name
                rdict[x + '_'] = rdict[x]
                rdict.pop(x)
            elif x.startswith('__'):
                error_message = "Device provided %r which is disallowed"\
                    ", it mangles into a Python non-public attribute." % x
                raise DeviceProvidesIncompatibleKey(error_message)
        return rdict

