        devid = get_dev_details(devip, auth, url)['id']
    f_url = url + "/imcrs/vlan/hybrid?devId=" + devid + "&ifIndex=" + ifindex
    response = requests.delete(f_url, auth=auth, headers=HEADERS)
    try:
