def hsl_to_rgb(h, s=None, l=None):
  if type(h) in [list,tuple]:
    h, s, l = h

  if s==0: return (l, l, l)   # achromatic (gray)

  if l<0.5: n2 = l * (1.0 + s)
  else: n2 = l+s - (l*s)

  n1 = (2.0 * l) - n2

  h /= 60.0
  hueToRgb = _hue_to_rgb
  r = hueToRgb(n1, n2, h + 2)
  g = hueToRgb(n1, n2, h)
  b = hueToRgb(n1, n2, h - 2)

  return (r, g, b)

