        if gps_position:
            helper.add_summary(gps_position)
        else:
            helper.add_summary("Could not retrieve GPS position")
            helper.status(unknown)

def remove(cls, name: sym.Symbol) -> Optional["Namespace"]:
        while True:
            oldval: lmap.Map = cls._NAMESPACES.deref()
            ns: Optional[Namespace] = oldval.entry(name, None)
            newval = oldval
            if ns is not None:
                newval = oldval.dissoc(name)
            if cls._NAMESPACES.compare_and_set(oldval, newval):
                return ns

def get_splitcolnr(header, bioset, splitcol):
    if bioset:
        return header.index(mzidtsvdata.HEADER_SETNAME)
    elif splitcol is not None:
        return splitcol - 1
    else:
        raise RuntimeError('Must specify either --bioset or --splitcol')

def check_perm(user_id, permission_code):
    try:
        perm = db.DBSession.query(Perm).filter(Perm.code==permission_code).one()
    except NoResultFound:
        raise PermissionError("Nonexistent permission type: %s"%(permission_code))


    try:
        res = db.DBSession.query(User).join(RoleUser, RoleUser.user_id==User.id).\
            join(Perm, Perm.id==perm.id).\
            join(RolePerm, RolePerm.perm_id==Perm.id).filter(User.id==user_id).one()
    except NoResultFound:
        raise PermissionError("Permission denied. User %s does not have permission %s"%
                        (user_id, permission_code))

def synthesize_speech(
        self,
        input_,
        voice,
        audio_config,
        retry=google.api_core.gapic_v1.method.DEFAULT,
        timeout=google.api_core.gapic_v1.method.DEFAULT,
        metadata=None,
    ):
        # Wrap the transport method to add retry and timeout logic.
        if "synthesize_speech" not in self._inner_api_calls:
            self._inner_api_calls[
                "synthesize_speech"
            ] = google.api_core.gapic_v1.method.wrap_method(
                self.transport.synthesize_speech,
                default_retry=self._method_configs["SynthesizeSpeech"].retry,
                default_timeout=self._method_configs["SynthesizeSpeech"].timeout,
                client_info=self._client_info,
            )

        request = cloud_tts_pb2.SynthesizeSpeechRequest(
            input=input_, voice=voice, audio_config=audio_config
        )
        return self._inner_api_calls["synthesize_speech"](
            request, retry=retry, timeout=timeout, metadata=metadata
        )

def validate(cls, event_info):
        assert 'service_key' in event_info
        assert isinstance(event_info['service_key'], six.string_types)
        assert 'event_type' in event_info
        assert event_info['event_type'] in cls.EVENT_TYPES
        if event_info['event_type'] != cls.EVENT_TYPES[0]:
            assert 'incident_key' in event_info
            assert isinstance(event_info['incident_key'], six.string_types)
        else:
            assert 'description' in event_info

        if 'details' in event_info:
            assert isinstance(event_info['details'], dict)

        if 'contexts' in event_info:
            assert isinstance(event_info['contexts'], (list, tuple,))

def import_modules(names, src, dst):
    for name in names:
        module = importlib.import_module(src + '.' + name)
        setattr(sys.modules[dst], name, module)

