def err(*output, **kwargs):
    output = 'Error: ' + ' '.join([str(o) for o in output])
    if kwargs.get('wrap') is not False:
        output = '\n'.join(wrap(output, kwargs.get('indent', '')))
    elif kwargs.get('indent'):
        indent = kwargs['indent']
        output = indent + ('\n' + indent).join(output.splitlines())
    sys.stderr.write(output + '\n')

def _receive(self, msg):
        msg = self._convert(msg)
        if msg is None:
            return

        str_msg = self.verbose and self._msg_to_str(msg)
        if self.verbose and log.is_debug():
            log.debug('Message %s', str_msg)

        if self.pre_routing:
            self.pre_routing.receive(msg)

        receiver, msg = self.routing.receive(msg)
        if receiver:
            receiver.receive(msg)
            if self.verbose:
                log.info('Routed message %s (%s) to %s', str_msg[:128], msg,
                         repr(receiver))

async def debug_text(self, texts: Union[str, list], positions: Union[list, set], color=(0, 255, 0), size_px=16):
        if isinstance(positions, (set, list)):
            if not positions:
                return

            if isinstance(texts, str):
                texts = [texts] * len(positions)
            assert len(texts) == len(positions)

            await self._execute(
                debug=sc_pb.RequestDebug(
                    debug=[
                        debug_pb.DebugCommand(
                            draw=debug_pb.DebugDraw(
                                text=[
                                    debug_pb.DebugText(
                                        text=t,
                                        color=debug_pb.Color(r=color[0], g=color[1], b=color[2]),
                                        world_pos=common_pb.Point(x=p.x, y=p.y, z=getattr(p, "z", 10)),
                                        size=size_px,
                                    )
                                    for t, p in zip(texts, positions)
                                ]
                            )
                        )
                    ]
                )
            )
        else:
            await self.debug_text([texts], [positions], color)

