def get_refkey(self, obj, referent):
        if isinstance(obj, dict):
            for k, v in obj.items():
                if v is referent:
                    return " (via its %r key)" % k

        for k in dir(obj) + ['__dict__']:
            if getattr(obj, k, None) is referent:
                return " (via its %r attribute)" % k
        return ""

def execute_api_request(self):
        if not self.auth.check_auth():
            raise Exception('Authentification needed or API not available with your type of connection')
        if self.auth.is_authentified():
            id_cookie = {BboxConstant.COOKIE_BBOX_ID: self.auth.get_cookie_id()}
            if self.parameters is None:
                resp = self.call_method(self.api_url.get_url(), cookies=id_cookie)
            else:
                resp = self.call_method(self.api_url.get_url(),
                                        data=self.parameters, cookies=id_cookie)
        else:
            if self.parameters is None:
                resp = self.call_method(self.api_url.get_url())
            else:
                resp = self.call_method(self.api_url.get_url(),
                                        data=self.parameters)
        if resp.status_code != 200:
            # This means something went wrong.
            raise Exception('Error {} with request {}'.format(
                resp.status_code, self.api_url.get_url()))

        return resp

def generate(self, root_element=None):
        if root_element is not None:
            url = etree.SubElement(root_element, 'url')
        else:
            url = etree.Element('url')
        etree.SubElement(url, 'loc').text = self.loc
        if self.lastmod:
            if hasattr(self.lastmod, 'strftime'):
                etree.SubElement(url, 'lastmod').text = \
                    self.lastmod.strftime('%Y-%m-%d')
            elif isinstance(self.lastmod, str):
                etree.SubElement(url, 'lastmod').text = self.lastmod
        if self.changefreq and self.changefreq in self.freq_values:
            etree.SubElement(url, 'changefreq').text = self.changefreq
        if self.priority and 0.0 <= self.priority <= 1.0:
            etree.SubElement(url, 'priority').text = str(self.priority)
        return url

def decodekey(self, key):
        if key[:1] in (b'n', b'N', b'$'):
            if key[1:2] == b"\x00" and len(key) == 2 + self.wordsize:
                return struct.unpack(">sB" + self.fmt, key)
            else:
                return key[:1], key[1:].decode('utf-8', 'ignore')
        if key[:1] == b'-':
            return struct.unpack(">s" + self.fmt, key)
        if len(key) == 1 + self.wordsize:
            return struct.unpack(self.keyfmt[:3], key)
        if len(key) == 1 + self.wordsize + 1:
            return struct.unpack(self.keyfmt[:4], key)
        if len(key) == 1 + 2 * self.wordsize + 1:
            return struct.unpack(self.keyfmt[:5], key)
        if len(key) > 1 + self.wordsize + 1:
            f = struct.unpack_from(self.keyfmt[:4], key)
            return f + (key[2 + self.wordsize:], )
        raise Exception("unknown key format")

