def get_ffprobe(path):
    try:
        with open(os.devnull, 'w') as tempf:
            subprocess.check_call(
                ['ffprobe', '-h'], stdout=tempf, stderr=tempf)
    except Exception as e:
        raise IOError('ffprobe not found.')

    if not os.path.isfile(path):
        raise IOError('No such file: ' + path)

    j_str = ""
    try:
        j_str = subprocess.check_output([
            'ffprobe',
            '-v', 'quiet',
            '-print_format', 'json',
            '-show_format',
            '-show_streams',
            path
        ])
    except subprocess.CalledProcessError:
        pass
    j_obj = json.loads(j_str)

    return j_obj

def _comp_task(inbox, args, kwargs):
    # Note. this function uses a global variable which must be defined on the 
    # remote host.
    for func, args, kwargs in itertools.izip(TASK, args, kwargs):
        inbox = (func(inbox, *args, **kwargs),)
    return inbox[0]

def __get_matching_indices(self, args, kwargs, args_list, kwargs_list):
        if args and kwargs:
            if args in args_list and kwargs in kwargs_list:
                args_indices = [i for i, x in enumerate(args_list) if x == args]
                kwargs_indices = [i for i, x in enumerate(kwargs_list) if x == kwargs]
                return list(set(args_indices).intersection(kwargs_indices))
        # args only
        elif args:
            if args in args_list:
                return [i for i, x in enumerate(args_list) if x == args and not kwargs_list[i]]
        #kwargs only
        elif kwargs:
            if kwargs in kwargs_list:
                return [i for i, x in enumerate(kwargs_list) if x == kwargs and not args_list[i]]
        else:
            return []

def _all_classes(self, classes):
        all_classes = {}

        def recurse(cls):
            all_classes[cls] = None
            for c in cls.__bases__:
                if c not in all_classes:
                    recurse(c)

        for cls in classes:
            recurse(cls)

        return all_classes.keys()

def get_expr(self, ctx):
        varname = ctx.lookup_variable(self.varname)
        if varname is None:
            val = ctx.lookup_constant(self.varname)
            if val:
                try:
                    return val.generate_code(ctx)
                except AttributeError:
                    return val
            raise MuvError(
                "Undeclared identifier '%s'." % self.varname,
                position=self.position
            )
        if len(self.indexing) == 0:
            return "{var} @".format(
                var=varname,
            )
        if len(self.indexing) == 1:
            return "{var} @ {idx} []".format(
                var=varname,
                idx=self.indexing[0],
            )
        return (
            "{var} @ {{ {idx} }}list array_nested_get".format(
                var=varname,
                idx=" ".join(str(x) for x in self.indexing),
            )
        )

def merkleroot(hashes):
    # XXX TEMPORARY -- MUST REVIEW and possibly CHANGE
    # The idea here is that the UTXO SET would be empty and this function
    # would be invoked to compute the merkle root, and since there is nothing,
    # i.e. an empty list, then the hash of the empty string is returned.
    # This seems too easy but maybe that is good enough? TO REVIEW!
    if not hashes:
        return sha3_256(b'').hexdigest()
    # XXX END TEMPORARY -- MUST REVIEW ...
    if len(hashes) == 1:
        return hexlify(hashes[0]).decode()
    if len(hashes) % 2 == 1:
        hashes.append(hashes[-1])
    parent_hashes = [
        sha3_256(hashes[i] + hashes[i+1]).digest()
        for i in range(0, len(hashes)-1, 2)
    ]
    return merkleroot(parent_hashes)

def translate(self, addr):
        # get family of this address so we translate to the same
        family = socket.getaddrinfo(addr, 0, socket.AF_UNSPEC, socket.SOCK_STREAM)[0][0]
        host = socket.getfqdn(addr)
        for a in socket.getaddrinfo(host, 0, family, socket.SOCK_STREAM):
            try:
                return a[4][0]
            except Exception:
                pass
        return addr

