def _load_attributes(self, mft_config, attrs_view):
        offset = 0
        load_attrs = mft_config.attribute_load_list

        while (attrs_view[offset:offset+4] != b'\xff\xff\xff\xff'):
            attr_type, attr_len, non_resident = _get_attr_info(attrs_view[offset:])
            if attr_type in load_attrs:
                # pass all the information to the attr, as we don't know how
                # much content the attribute has
                attr = Attribute.create_from_binary(non_resident, mft_config.load_dataruns, attrs_view[offset:])
                if not attr.header.attr_type_id is AttrTypes.DATA:
                    self.attrs[attr.header.attr_type_id].append(attr) #add an attribute
                else:
                    self._add_data_attribute(attr)
            offset += attr_len

def _gettype(self):
        current = self
        lastname = getattr(current._parser, 'typedef', None)
        while hasattr(current, '_sub'):
            current = current._sub
            tn = getattr(current._parser, 'typedef', None)
            if tn is not None:
                lastname = tn
        return lastname

def query_more(fn, offset, size, batch_size, *args):
    if size < 0:
        expected_total_size = six.MAXSIZE
    else:
        expected_total_size = size
        batch_size = min(size, batch_size)

    response = None
    total_count_got = 0
    complete = False
    while True:
        ret = fn(*args, offset=offset, size=batch_size)

        if response is None:
            response = ret
        else:
            response.merge(ret)

        # if incompete, exit
        if not ret.is_completed():
            break

        count = ret.get_count()
        offset += count
        total_count_got += count
        batch_size = min(batch_size, expected_total_size - total_count_got)
        if count == 0 or total_count_got >= expected_total_size:
            break

    return response

def infer_alpha_chain(beta):
    if beta.gene.startswith("DRB"):
        return AlleleName(species="HLA", gene="DRA1", allele_family="01", allele_code="01")
    elif beta.gene.startswith("DPB"):
        # Most common alpha chain for DP is DPA*01:03 but we really
        # need to change this logic to use a lookup table of pairwise
        # frequencies for inferring the alpha-beta pairing
        return AlleleName(
            species="HLA", gene="DPA1", allele_family="01", allele_code="03")
    elif beta.gene.startswith("DQB"):
        # Most common DQ alpha (according to wikipedia)
        # DQA1*01:02
        return AlleleName(
            species="HLA", gene="DQA1", allele_family="01", allele_code="02")
    return None

def introspection_from_schema(
    schema: GraphQLSchema, descriptions: bool = True
) -> IntrospectionSchema:
    query_ast = parse(get_introspection_query(descriptions))

    from ..execution.execute import execute, ExecutionResult

    result = execute(schema, query_ast)
    if not isinstance(result, ExecutionResult):
        raise RuntimeError("Introspection cannot be executed")
    if result.errors or not result.data:
        raise result.errors[0] if result.errors else GraphQLError(
            "Introspection did not return a result"
        )
    return result.data

