                if fname.isdigit():
                    # Build the full file path for the current article to read its contents.
                    fpath = os.path.join(path, fname)
                    if sys.version_info < (3,):
                        f = open(fpath)
                    else:
                        f = open(fpath, encoding='latin-1')
                    content = f.read()
                    texts.append((content, label_id))
                    f.close()

    print('Found %s texts.' % len(texts))
    return texts

def authenticate_user(scope, user=[None], password=[None]):
    conn = scope.get('__connection__')
    user = user[0]
    if user is None:
        conn.app_authenticate()
    else:
        account = Account(user, password[0])
        conn.app_authenticate(account)
    return True

def attach_(dev=None):
    cache = uuid()
    if not cache:
        log.error('No cache to attach %s to', dev)
        return False

    if dev is None:
        res = {}
        for dev, data in status(alldevs=True).items():
            if 'cache' in data:
                res[dev] = attach_(dev)

        return res if res else None

    bcache = uuid(dev)
    if bcache:
        if bcache == cache:
            log.info('%s is already attached to bcache %s, doing nothing', dev, cache)
            return None
        elif not detach(dev):
            return False

    log.debug('Attaching %s to bcache %s', dev, cache)

    if not _bcsys(dev, 'attach', cache,
                  'error', 'Error attaching {0} to bcache {1}'.format(dev, cache)):
        return False

    return _wait(lambda: uuid(dev) == cache,
                 'error', '{0} received attach to bcache {1}, but did not comply'.format(dev, cache))

def analyze(self, config_string=None):
        try:
            if config_string is not None:
                self.log(u"Analyzing container with the given config string")
                return self._analyze_txt_config(config_string=config_string)
            elif self.container.has_config_xml:
                self.log(u"Analyzing container with XML config file")
                return self._analyze_xml_config(config_contents=None)
            elif self.container.has_config_txt:
                self.log(u"Analyzing container with TXT config file")
                return self._analyze_txt_config(config_string=None)
            else:
                self.log(u"No configuration file in this container, returning None")
        except (OSError, KeyError, TypeError) as exc:
            self.log_exc(u"An unexpected error occurred while analyzing", exc, True, None)
        return None

