def max_lemma_count(ambiguous_word: str) -> "wn.Synset":
    sense2lemmacounts = {}
    for i in wn.synsets(ambiguous_word, pos=None):
        sense2lemmacounts[i] = sum(j.count() for j in i.lemmas())
    return max(sense2lemmacounts, key=sense2lemmacounts.get)

