def utf8(value: Union[None, str, bytes]) -> Optional[bytes]:  # noqa: F811
    if isinstance(value, _UTF8_TYPES):
        return value
    if not isinstance(value, unicode_type):
        raise TypeError("Expected bytes, unicode, or None; got %r" % type(value))
    return value.encode("utf-8")

def AddTransaction(self, tx):
        if BC.Default() is None:
            return False

        if tx.Hash.ToBytes() in self.MemPool.keys():
            return False

        if BC.Default().ContainsTransaction(tx.Hash):
            return False

        if not tx.Verify(self.MemPool.values()):
            logger.error("Verifying tx result... failed")
            return False

        self.MemPool[tx.Hash.ToBytes()] = tx

        return True

def _drop_ignored(gold, pred, ignore_in_gold, ignore_in_pred):
    tmp = np.ones_like(gold).astype(bool)
    for x in ignore_in_gold:
        tmp *= np.where(gold != x, 1, 0).astype(bool)
    for x in ignore_in_pred:
        tmp *= np.where(pred != x, 1, 0).astype(bool)

    gold = gold[tmp]
    pred = pred[tmp]
    return gold, pred

