def client(addr):
        success = False
        while not success:
            try:
                sock = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
                sock.setsockopt(socket.SOL_SOCKET, socket.SO_REUSEADDR, 1)
                sock.connect(addr)
                success = True
            except socket.error as err:
                sock.close()
        talk = SocketTalk(sock)
        return talk

def _purge_unreachable(self, key):
        dels = []
        for p in self:
            if dominates(key, p):
                dels.append(p)
        for k in dels:
