def collision_integral_Kim_Monroe(Tstar, l=1, s=1):
    if (l, s) not in As_collision:
        raise Exception('Input values of l and s are not supported')
    omega = As_collision[(l, s)]
    for ki in range(6):
        Bs = Bs_collision[(l, s)]
        Cs = Cs_collision[(l, s)]
        omega += Bs[ki]/Tstar**(ki+1) + Cs[ki]*log(Tstar)**(ki+1)
    return omega

def _check_curtailment_target(curtailment, curtailment_target,
                              curtailment_key):
    if not (abs(curtailment.sum(axis=1) - curtailment_target) < 1e-1).all():
        message = 'Curtailment target not met for {}.'.format(curtailment_key)
        logging.error(message)
        raise TypeError(message)

