def MatchQuality(cls, record_data, record_count=1):

        if record_count == 1:
            cmd, address, _resp_length, _payload = SendErrorCheckingRPCRecord._parse_rpc_info(record_data)

            if cmd == cls.BEGIN_CONFIG_RPC and address == 8:
                return MatchQuality.DeferMatch

            return MatchQuality.NoMatch

        # To see if this is a set_config variable record set, we need to decode all of
        # the records and make sure each is an error checking rpc with the right rpc id
        try:
            rpcs = SendErrorCheckingRPCRecord.parse_multiple_rpcs(record_data)

            push_commands = rpcs[1:-1]

            for cmd in push_commands:
                cmd_id, addr = cmd[:2]
                if cmd_id != cls.PUSH_CONFIG_RPC or addr != 8:
                    return MatchQuality.NoMatch

            last_cmd, last_addr = rpcs[-1][:2]
            if last_cmd == cls.END_CONFIG_RPC and last_addr == 8:
                return MatchQuality.PerfectMatch
        except ArgumentError:
            return MatchQuality.NoMatch

        return MatchQuality.DeferMatch

def invoke_method_on_children(self, func_name=None, *args, **kwargs):
        if func_name is None:
            raise ValueError(
                'invoke_method_on_children:func_name parameter required')

        class_stack = []
        base = self.__class__  # The root class in the hierarchy.
        while base is not None and base is not object:
            class_stack.append(base)
            base = base.__base__  # iterate to the next base class

        while len(class_stack) is not 0:
            base = class_stack.pop()
            if func_name in base.__dict__:  # check the func exist on class
                # instance
                func = getattr(base, func_name)
                func(self, *args,
                     **kwargs)

def Disappears(self, maxSearchSeconds: float = 5, searchIntervalSeconds: float = SEARCH_INTERVAL, printIfNotDisappear: bool = False) -> bool:
        global DEBUG_EXIST_DISAPPEAR
        start = ProcessTime()
        while True:
            temp = DEBUG_EXIST_DISAPPEAR
            DEBUG_EXIST_DISAPPEAR = False  # do not print for Exists
            if not self.Exists(0, 0, False):
                DEBUG_EXIST_DISAPPEAR = temp
                return True
            DEBUG_EXIST_DISAPPEAR = temp
            remain = start + maxSearchSeconds - ProcessTime()
            if remain > 0:
                time.sleep(min(remain, searchIntervalSeconds))
            else:
                if printIfNotDisappear or DEBUG_EXIST_DISAPPEAR:
                    Logger.ColorfullyWriteLine(self.GetColorfulSearchPropertiesStr() + '<Color=Red> does not disappear.</Color>')
                return False

