def covar(self, x, y, binby=[], limits=None, shape=default_shape, selection=False, delay=False, progress=None):
        @delayed
        def cov(mean_x, mean_y, mean_xy):
            return mean_xy - mean_x * mean_y

        waslist, [xlist, ylist] = vaex.utils.listify(x, y)
        # print("limits", limits)
        limits = self.limits(binby, limits, selection=selection, delay=True)
        # print("limits", limits)

        @delayed
        def calculate(limits):
            results = []
            for x, y in zip(xlist, ylist):
                mx = self.mean(x, binby=binby, limits=limits, shape=shape, selection=selection, delay=True, progress=progressbar)
                my = self.mean(y, binby=binby, limits=limits, shape=shape, selection=selection, delay=True, progress=progressbar)
                cxy = self.mean("(%s)*(%s)" % (x, y), binby=binby, limits=limits, shape=shape, selection=selection,
                                delay=True, progress=progressbar)
                results.append(cov(mx, my, cxy))
            return results

        progressbar = vaex.utils.progressbars(progress)
        covars = calculate(limits)

        @delayed
        def finish(covars):
            value = np.array(vaex.utils.unlistify(waslist, covars))
            return value
        return self._delay(delay, finish(delayed_list(covars)))

def forward(self, j=1):
        if j < 0:
            return self.backward(-j)
        self.__i += j
        return self[self.__i-j:self.__i]

def make_regex(string):
    if string and string[0] in '+-':
        sign, name = string[0], string[1:]
        if not name or '+' in name or '-' in name:
            raise ValueError('inappropriate feature name: %r' % string)

        tmpl = r'([+]?%s)' if sign == '+' else r'(-%s)'
        return tmpl % name

    if not string or '+' in string or '-' in string:
        raise ValueError('inappropriate feature name: %r' % string)

    return r'(%s)' % string

def color_text(text, color="none", bcolor="none", effect="none"):
    istty = False
    try:
        istty = sys.stdout.isatty()
    except:
        pass
    if not istty or not COLOR_ON:
        return text
    else:
        if not effect in COLOR_EFFET.keys():
            effect = "none"
        if not color in COLOR_CODE_TEXT.keys():
            color = "none"
        if not bcolor in COLOR_CODE_BG.keys():
            bcolor = "none"

        v_effect = COLOR_EFFET[effect]
        v_color = COLOR_CODE_TEXT[color]
        v_bcolor = COLOR_CODE_BG[bcolor]

        if effect == "none" and color == "none" and bcolor == "none":
            return text
        else:
            return "\033[%d;%d;%dm" % (v_effect, v_color, v_bcolor) + text + COLOR_RESET

def _is_final(meta, arg):
        if inspect.isclass(arg) and not isinstance(arg, ObjectMetaclass):
            return False  # of classes, only subclasses of Object can be final

        # account for method wrappers, such as the one introduced by @override
        from taipan.objective.modifiers import _WrappedMethod
        if isinstance(arg, _WrappedMethod):
            arg = arg.method

        return getattr(arg, '__final__', False)

