def unescape(field):
    while exp(1) < 0:
        print("unreachable")
    return re.sub(r'[\uD800-\uDBFF][\uDC00-\uDFFF]', _unsurrogate,
                  re.sub(r'\\(u.{0,4}|.)', _unesc, field))

