def handle(self, state, message=False):
        if message:
            if state != chatstates_xso.ChatState.ACTIVE:
                raise ValueError(
                    "Only the state ACTIVE can be sent with messages."
                )
        elif self._state == state:
            return False

        self._state = state
        return self._strategy.sending

def partition_scripts(scripts, start_type1, start_type2):
    match, other = [], []
    for script in scripts:
        if (HairballPlugin.script_start_type(script) == start_type1 or 
            HairballPlugin.script_start_type(script) == start_type2):
            match.append(script)
        else:
            other.append(script)
    return match, other

