def _F_measure(self, alpha, TP, FP, FN, return_num_den=False):
        num = np.float64(TP)
        den = np.float64(alpha * (TP + FP) + (1 - alpha) * (TP + FN))
        with np.errstate(divide='ignore', invalid='ignore'):
            F_measure = num/den
        #F_measure = num/den

        if return_num_den:
            return F_measure, num, den
        else:
            return F_measure

def break_down_travel(p1, target, increment=5, mode='absolute'):

    heading = target - p1
    if mode == 'relative':
        heading = target
    length = heading.length()

    length_steps = length / increment
    length_remainder = length % increment

    vector_step = Vector(0, 0, 0)
    if length_steps > 0:
        vector_step = heading / length_steps
    vector_remainder = vector_step * (length_remainder / increment)

    res = []
    if mode == 'absolute':
        for i in range(int(length_steps)):
            p1 = p1 + vector_step
            res.append(p1)
        p1 = p1 + vector_remainder
        res.append(p1)
    else:
        for i in range(int(length_steps)):
            res.append(vector_step)
        res.append(vector_remainder)
    return res

def execCommand(Argv, collect_missing):
  try:
    return _execCommand(Argv, collect_missing)

  except Exception as e:
    if Settings['errorHandler']:
      Settings['errorHandler'](e)

    if Settings['debug']:
      # #ToDo: Have an option to debug through stderr. The issue is, the way to make pdb.post_mortem, to use stderr, like pdb.set_trace is unknown.
      import pdb
      pdb.post_mortem(sys.exc_info()[2])

    if not Settings['silent']: # Debug, then log the trace.
      import traceback

      etype, value, tb = sys.exc_info()
      tb = tb.tb_next.tb_next # remove the ec - calls from the traceback, to make it more understandable

      message = ''.join(traceback.format_exception(etype, value, tb))[:-1]

    else:
      if isinstance(e, HandledException): # let the modes handle the HandledException
        raise e

      message = str(e) # provide a succinct error message

    raise HandledException(message)

