def _P(m):
    P = np.zeros((m**2,m**2), dtype=np.int64)
    for i in range(1, m**2 + 1):
        j = 1 + m*((i - 1) % m) + (i - 1)//m
        P[i-1, j-1] = 1
    return P

def build(self, builder):
        params = dict(FormOID=self.formoid)

        if self.transaction_type is not None:
            params["TransactionType"] = self.transaction_type

        if self.form_repeat_key is not None:
            params["FormRepeatKey"] = str(self.form_repeat_key)

        # mixins
        self.mixin()
        self.mixin_params(params)

        builder.start("FormData", params)

        # Ask children
        for itemgroup in self.itemgroups:
            itemgroup.build(builder, self.formoid)

        if self.signature is not None:
            self.signature.build(builder)

        for annotation in self.annotations:
            annotation.build(builder)

        builder.end("FormData")

def format(self, rev_id=None, model_name=None):
        rev_ids = rev_id if rev_id is not None else set(self.rev_ids)
        model_names = model_name if model_name is not None else set(self.model_names)
        common = [self.context_name, rev_ids, model_names]

        optional = []
        if self.precache:
            optional.append("precache")
        if self.include_features:
            optional.append("features")
        if self.injection_caches:
            optional.append("injection_caches={0}".format(self.injection_caches))
        if self.model_info:
            optional.append("model_info=" + json.dumps(self.model_info))
        if self.ip:
            optional.append("ip={0}".format(self.ip))

        return "{0}({1})".format(":".join(repr(v) for v in common),
                                 ", ".join(optional))

