def time_range(self,flag=None):
        if self.count==0: return [[None,None],[None,None]]

        if flag is None : return cnes_convert([self.date.min(),self.date.max()])
        else : return cnes_convert([self.date.compress(flag).min(),self.date.compress(flag).max()])

def aggregate(self, search):
        for f, facet in iteritems(self.facets):
            agg = facet.get_aggregation()
            agg_filter = MatchAll()
            # Merge remaining field filters into the aggregate filter to isolate the target facet.
            for field, filter in iteritems(self._filters):
                if f == field:
                    continue
                agg_filter &= filter
            search.aggs.bucket(
                '_filter_' + f,
                'filter',
                filter=agg_filter
            ).bucket(f, agg)

def opening(image, radius=None, mask=None, footprint=None):
    eroded_image = grey_erosion(image, radius, mask, footprint)
