        return query._get_cursor_wrapper(cursor)

def equal(t1, t2, digit=None):

    if not len(t1) == len(t2):
        return False


    for idx in range(len(t1)):
        if digit is not None:
            if not round(t1[idx], digit) == round(t2[idx], digit):
                return False
        else:
            if not t1[idx] == t2[idx]:
                return False

    return True

