                                 Command.DOUBLE_CLICK, {}))
        return self

def _sumterm(lexer):
    xorterm = _xorterm(lexer)
    sumterm_prime = _sumterm_prime(lexer)
    if sumterm_prime is None:
        return xorterm
    else:
        return ('or', xorterm, sumterm_prime)

