def get_client_ip(environ):
    # type: (Dict[str, str]) -> Optional[Any]
    try:
        return environ["HTTP_X_FORWARDED_FOR"].split(",")[0].strip()
    except (KeyError, IndexError):
        pass

    try:
        return environ["HTTP_X_REAL_IP"]
    except KeyError:
        pass

    return environ.get("REMOTE_ADDR")

def set_subdata(self, data, offset=0, copy=False):
        data = np.array(data, copy=copy)
        nbytes = data.nbytes

        if offset < 0:
            raise ValueError("Offset must be positive")
        elif (offset + nbytes) > self._nbytes:
            raise ValueError("Data does not fit into buffer")

        # If the whole buffer is to be written, we clear any pending data
        # (because they will be overwritten anyway)
        if nbytes == self._nbytes and offset == 0:
            self._glir.command('SIZE', self._id, nbytes)
        self._glir.command('DATA', self._id, offset, data)

def unicode_key(key):
    if not isinstance(key, (text_type, binary_type)):
        from mo_logs import Log
        Log.error("{{key|quote}} is not a valid key", key=key)
    return quote(text_type(key))

def get_subdomain_resolver(name, db_path=None, zonefiles_dir=None):
    opts = get_blockstack_opts()
    if not is_subdomains_enabled(opts):
        log.warn("Subdomain support is disabled")
        return None

    if db_path is None:
        db_path = opts['subdomaindb_path']

    if zonefiles_dir is None:
        zonefiles_dir = opts['zonefiles']

    db = SubdomainDB(db_path, zonefiles_dir)
    resolver_url = db.get_domain_resolver(name)

    return resolver_url

def assign_from_ast(node, expr):
    if isinstance(expr, str):
        expr = ast.Name(id=expr, ctx=ast.Load())
    mod = ast.Module([ast.Assign(targets=[node], value=expr)])
    ast.fix_missing_locations(mod)
    return compile(mod, "<assignment_script>", "exec")

def fire_framework_stopping(self):
        with self.__fw_lock:
            # Copy the list of listeners
            listeners = self.__fw_listeners[:]

        for listener in listeners:
            try:
                listener.framework_stopping()
            except:
                self._logger.exception(
                    "An error occurred calling one of the "
                    "framework stop listeners"
                )

def as_download(self, data, block_num=-1):
        size = len(data)
        type_ = c_byte * len(data)
        cdata = type_.from_buffer_copy(data)
        return self.library.Cli_AsDownload(self.pointer, block_num,
                                           byref(cdata), size)

def parse_connection_string(connect_str):
    connect_info = {}
    fields = connect_str.split(';')
    for field in fields:
        key, value = field.split('=', 1)
        connect_info[key] = value
    return connect_info

def extract_relations(dgtree, relations=None):
    if hasattr(dgtree, 'reltypes'):
        # dgtree is an RSTTree or a DisTree that contains a DGParentedTree
        return dgtree.reltypes

    if relations is None:
        relations = {}

    if is_leaf(dgtree):
        return relations

    root_label = dgtree.label()
    if root_label == '':
        assert dgtree == DGParentedTree('', []), \
            "The tree has no root label, but isn't empty: {}".format(dgtree)
        return relations
    elif root_label in NUCLEARITY_LABELS:
        for child in dgtree:
            relations.update(extract_relations(child, relations))
    else:  # dgtree is a 'relation' node
        child_labels = [child.label() for child in dgtree]
        assert all(label in NUCLEARITY_LABELS for label in child_labels)
        if 'S' in child_labels:
            relations[root_label] = 'rst'
        else:
            relations[root_label] = 'multinuc'
        for child in dgtree:
            relations.update(extract_relations(child, relations))

    return relations

def separate_reach_logs(log_str):
    log_lines = log_str.splitlines()
    reach_logs = []
    reach_lines = []
    adding_reach_lines = False
    for l in log_lines[:]:
        if not adding_reach_lines and 'Beginning reach' in l:
            adding_reach_lines = True
        elif adding_reach_lines and 'Reach finished' in l:
            adding_reach_lines = False
            reach_logs.append(('SUCCEEDED', '\n'.join(reach_lines)))
            reach_lines = []
        elif adding_reach_lines:
            reach_lines.append(l.split('readers - ')[1])
            log_lines.remove(l)
    if adding_reach_lines:
        reach_logs.append(('FAILURE', '\n'.join(reach_lines)))
    return '\n'.join(log_lines), reach_logs

def delay_host_notification(self, host, notification_time):
        host.first_notification_delay = notification_time
        self.send_an_element(host.get_update_status_brok())

def validate(self):
        for field_name, field_obj in self._fields.items():
            value = field_obj.__get__(self, self.__class__)

            if value is None and field_obj.null is False:
                raise ValidationError('Non-nullable field {0} is set to None'.format(field_name))
            elif value is None and field_obj.null is True:
                # no further validations are possible on NoneType field
                continue

            if isinstance(field_obj, NestedDocumentField):
                value.validate()
            else:
                field_obj.validate(value)

def remove_handler_if_not_configured(self, dict_config, requested_handlers, handler_name, check_key) -> None:
        try:
            if not dict_config["handlers"][handler_name][check_key]:
                dict_config["handlers"].pop(handler_name)
                if handler_name in requested_handlers:
                    requested_handlers.remove(handler_name)
        except KeyError:
            # Ignore key errors
            pass

def is_empty(self):
        if len(self.val) != 0:
            if isinstance(self.val, str_types):
                self._err('Expected <%s> to be empty string, but was not.' % self.val)
            else:
                self._err('Expected <%s> to be empty, but was not.' % self.val)
        return self

def _get_lab_color1_vector(color):
    if not color.__class__.__name__ == 'LabColor':
        raise ValueError(
            "Delta E functions can only be used with two LabColor objects.")
    return numpy.array([color.lab_l, color.lab_a, color.lab_b])

def permute(self, qubits: Qubits) -> 'Gate':
        vec = self.vec.permute(qubits)
        return Gate(vec.tensor, qubits=vec.qubits)

def write_command_line(self):
        cmd = [" ".join(sys.argv)]
        try:
            previous = self.attrs["cmd"]
            if isinstance(previous, str):
                # convert to list
                previous = [previous]
            elif isinstance(previous, numpy.ndarray):
                previous = previous.tolist()
        except KeyError:
            previous = []
        self.attrs["cmd"] = cmd + previous

def validate(self, request, value):
        if self.required and value == DEFAULT_FIELD_VALUE:
            return ValidationResult(is_success=False,
                                    reason='This field is required')
        if not self.nullable and value is None:
            return ValidationResult(is_success=False,
                                    reason='null is not a valid value')
        return ValidationResult(is_success=True)

def set_context(self, context):
        if not isinstance(context, Context):
            raise TypeError("context must be a Context instance")

