def get_expire_time(self):
        try:
            expire_time = self.node.expire_time.resolve(self.context)
        except template.VariableDoesNotExist:
            raise template.TemplateSyntaxError('"%s" tag got an unknown variable: %r' %
                                               (self.node.nodename, self.node.expire_time.var))
        try:
            if expire_time is not None:
                expire_time = str(expire_time)
                if not expire_time.isdigit():
                    raise TypeError
                expire_time = int(expire_time)
        except (ValueError, TypeError):
            raise template.TemplateSyntaxError(
                '"%s" tag got a non-integer (or None) timeout value: %r' % (
                    self.node.nodename, expire_time
                )
            )

        return expire_time

def join(*vectors):
    # check supplied arguments
    if len(vectors) < 2:
        return vectors[0]

    # process supplied arguments
    vectors = list(vectors)
    for i in range(len(vectors)):
        vectors[i] = numpy.array(vectors[i], copy=False)
        if vectors[i].ndim == 1:
            vectors[i] = numpy.array([vectors[i]], copy=False).T

    # treat single-value cases special (no squeezing)
    if 1 == len(vectors[0]):
        return numpy.concatenate(vectors, 1)

    return numpy.squeeze(numpy.concatenate(vectors, 1))

def linkage_group_ordering(linkage_records):

    new_records = dict()

    for lg_name, linkage_group in itertools.groupby(
        linkage_records, operator.itemgetter(0)
    ):
        new_records[lg_name] = []
        for record in linkage_group:
            init_contig = record[-1]
            start = record[1]
            end = record[2]

            new_record = [init_contig, -3, start, end, 1]

            new_records[lg_name].append(new_record)

    return new_records

