def is_batch_signer_authorized(self, batch, state_root=None,
                                   from_state=False):
        if state_root is None:
            state_root = self._current_root_func()
            if state_root == INIT_ROOT_KEY:
                LOGGER.debug("Chain head is not set yet. Permit all.")
                return True

        self._cache.update_view(state_root)

        header = BatchHeader()
        header.ParseFromString(batch.header)

        role = self._cache.get_role(
            "transactor.batch_signer",
            state_root,
            from_state)

        if role is None:
            role = self._cache.get_role("transactor", state_root, from_state)

        if role is None:
            policy_name = "default"
        else:
            policy_name = role.policy_name

        policy = self._cache.get_policy(policy_name, state_root, from_state)
        if policy is None:
            allowed = True
        else:
            allowed = self._allowed(header.signer_public_key, policy)

        if allowed:
            return self.is_transaction_signer_authorized(
                batch.transactions,
                state_root,
                from_state)
        LOGGER.debug("Batch Signer: %s is not permitted.",
                     header.signer_public_key)
        return False

def _represent_match_traversal(match_traversal):
    output = []

    output.append(_first_step_to_match(match_traversal[0]))
    for step in match_traversal[1:]:
        output.append(_subsequent_step_to_match(step))

    return u''.join(output)

def _replace_file(path, content):
  if os.path.exists(path):
    with open(path, 'r') as f:
      if content == f.read():
        print("Not overwriting {} because it is unchanged".format(path), file=sys.stderr)
        return

  with open(path, 'w') as f:
    f.write(content)

