def kms_decrypt(kms_client, secret):
  try:
    decrypted_secret = kms_client.decrypt(CiphertextBlob=base64.b64decode(secret))['Plaintext']
  except TypeError:
    fail("Malformed base64 string data")
  except ClientError as error:
    if error.response["Error"]["Code"] == "InvalidCiphertextException":
      fail("The decrypt request was rejected because the specified ciphertext \
      has been corrupted or is otherwise invalid.", error)
    elif error.response["Error"]["Code"] == "NotFoundException":
      fail("The decrypt request was rejected because the specified entity or resource could not be found.", error)
    else:
      fail("boto3 exception occurred while performing kms decrypt operation.", error)
  return decrypted_secret

def parse(self):
        reader = self.split_records()
        for line in reader:
            self.cur_record += 1
            if not line:
                continue
            stmt_line = self.parse_record(line)
            if stmt_line:
                stmt_line.assert_valid()
                self.statement.lines.append(stmt_line)
        return self.statement

def dumps(data, escape=False, **kwargs):
    if 'sort_keys' not in kwargs:
        kwargs['sort_keys'] = True

    converted = json.dumps(data, default=_converter, **kwargs)
    if escape:
        # We're escaping the whole dumped string here cause there's no (easy)
        # way to hook into the native json library and change how they process
        # values like strings, None objects and some other "literal" stuff.
        #
        # Also, we're not escaping quotes here cause they're escaped by the
        # native json library already. So, we just escape basic html entities,
        # like <, > and &;
        return cgi.escape(converted)
    return converted

