def every(delay, task, name):
    next_time = time.time() + delay

    while True:
        time.sleep(max(0, next_time - time.time()))
        try:
            if task() is False:
                break
        except Exception:
            logger.debug("Problem while executing repetitive task: %s" % name, exc_info=True)

        # skip tasks if we are behind schedule:
        next_time += (time.time() - next_time) // delay * delay + delay

def make_mashes(fastas, mash_file, threads, kmer = 21, force = False):
    mash_processes = set()
    sketches = [fasta + '.msh' for fasta in fastas]
    devnull = open(os.devnull, 'w')
    # Perform the sketching
    for fasta, sketch in zip(fastas, sketches):
        if os.path.isfile(sketch):
            continue
        mash_cmd = ['/opt/bin/bio/mash', 'sketch', '-o', fasta, '-k', str(kmer), fasta]
        mash_processes.add(subprocess.Popen(mash_cmd, stderr=devnull))
        if len(mash_processes) >= threads:
            os.wait()
            mash_processes.difference_update([mp for mp in mash_processes if mp.poll() is not None])
    # Collect stragglers
    for mp in mash_processes:
        if mp.poll() is None:
            mp.wait()
    # Paste sketches into single mash
    paste_mashes(sketches, mash_file, force = force)
    return

def largest_factor_relatively_prime( a, b ):

  while 1:
    d = gcd( a, b )
    if d <= 1: break
    b = d
    while 1:
      q, r = divmod( a, d )
      if r > 0:
        break
      a = q
  return a

def lookup_type(storable_type):
    if storable_type.startswith('Python'):
        _, module_name = storable_type.split('.', 1)
    else:
        module_name = storable_type
    #type_name, module_name = \
    names = [ _name[::-1] for _name in module_name[::-1].split('.', 1) ]
    if names[1:]:
        type_name, module_name = names
    else:
        type_name = names[0]
        return eval(type_name)
    try:
        module = importlib.import_module(module_name)
        python_type = getattr(module, type_name)
    except (ImportError, AttributeError):
        python_type = None
    return python_type

