def read(cls, source, *args, **kwargs):
        if 'flag' in kwargs:  # pragma: no cover
            warnings.warn('\'flag\' keyword was renamed \'name\', this '
                          'warning will result in an error in the future')
            kwargs.setdefault('name', kwargs.pop('flags'))
        coalesce = kwargs.pop('coalesce', False)

        def combiner(flags):
            """Combine `DataQualityFlag` from each file into a single object
            """
            out = flags[0]
            for flag in flags[1:]:
                out.known += flag.known
                out.active += flag.active
            if coalesce:
                return out.coalesce()
            return out

        return io_read_multi(combiner, cls, source, *args, **kwargs)

def _linux_iqn():
    ret = []

    initiator = '/etc/iscsi/initiatorname.iscsi'
    try:
        with salt.utils.files.fopen(initiator, 'r') as _iscsi:
            for line in _iscsi:
                line = line.strip()
                if line.startswith('InitiatorName='):
                    ret.append(line.split('=', 1)[1])
    except IOError as ex:
        if ex.errno != errno.ENOENT:
            log.debug("Error while accessing '%s': %s", initiator, ex)

    return ret

def _serialize_module(obj):
    obj = dict(obj.__dict__)
    if '__builtins__' in obj.keys():
        obj.pop('__builtins__')
    for k, v in obj.items():
        if callable(v):
            obj[k] = serialize_obj(v)
        else:
            obj[k] = repr(v)
    return obj

def RecursiveMultiListChildren(self, urns, limit=None, age=NEWEST_TIME):

    checked_urns = set()
    urns_to_check = urns
    while True:
      found_children = []

      for subject, values in self.MultiListChildren(
          urns_to_check, limit=limit, age=age):

        found_children.extend(values)
        yield subject, values

      checked_urns.update(urns_to_check)

      urns_to_check = set(found_children) - checked_urns
      if not urns_to_check:
        break

def parse(cls, ss):

        up = urlparse(ss)
        path = up.path
        query = up.query

        if '?' in path:
            path, _ = up.path.split('?')

        if path.startswith('/'):
            path = path[1:]

        bucket = path
        options = parse_qs(query)
        scheme = up.scheme
        hosts = up.netloc.split(',')
        return cls(bucket=bucket, options=options, hosts=hosts, scheme=scheme)

def degrade_to_order(self, new_order):
        shift = 2 * (AbstractMOC.HPY_MAX_NORDER - new_order)
        ofs = (int(1) << shift) - 1
        mask = ~ofs
        adda = int(0)
        addb = ofs

        iv_set = []

        for iv in self._interval_set._intervals:
            a = (iv[0] + adda) & mask
            b = (iv[1] + addb) & mask
            if b > a:
                iv_set.append((a, b))

        return self.__class__(IntervalSet(np.asarray(iv_set)))

