def add_poly(self, positions, depth=None):
        if not (len(positions) >= 3): raise AssertionError("A minimum of three coordinate pairs are required")

        if depth is None or depth > self.maxdepth:
            depth = self.maxdepth

        ras, decs = np.array(list(zip(*positions)))
        sky = self.radec2sky(ras, decs)
        pix = hp.query_polygon(2**depth, self.sky2vec(sky), inclusive=True, nest=True)
        self.add_pixels(pix, depth)
        self._renorm()
        return

def encrypt(algorithm, key, plaintext, associated_data, iv):
    encryptor = Encryptor(algorithm, key, associated_data, iv)
    ciphertext = encryptor.update(plaintext) + encryptor.finalize()
    return EncryptedData(encryptor.iv, ciphertext, encryptor.tag)

def append_qs(url, query_string):
    parsed_url = urlsplit(url)
    parsed_qs = parse_qsl(parsed_url.query, True)

    if isstr(query_string):
        parsed_qs += parse_qsl(query_string)
    elif isdict(query_string):
        for item in list(query_string.items()):
            if islist(item[1]):
                for val in item[1]:
                    parsed_qs.append((item[0], val))
            else:
                parsed_qs.append(item)
    elif islist(query_string):
        parsed_qs += query_string
    else:
        raise TypeError('Unexpected query_string type')

    return urlunsplit((
        parsed_url.scheme,
        parsed_url.netloc,
        parsed_url.path,
        urlencode_unicode(parsed_qs),
        parsed_url.fragment,
    ))

def is_address(value: Any) -> bool:
    if is_checksum_formatted_address(value):
        return is_checksum_address(value)
    elif is_hex_address(value):
        return True
    elif is_binary_address(value):
        return True
    else:
        return False

def get_minimum_size(self, data):
        min_width = 0
        min_height = 0
        for element in self.elements:
            size = (
                datatypes.Point(0, 0) if element is None
                else element.get_minimum_size(data)
                )
            min_height = max(min_height, size.y)
            min_width = max(min_width, size.x)

        num_elements = len(self.elements)
        height = min_height * num_elements + self.margin * (num_elements-1)
        return datatypes.Point(min_width, height)

def _dist_obs_oracle(oracle, query, trn_list):
    a = np.subtract(query, [oracle.f_array[t] for t in trn_list])
    return (a * a).sum(axis=1)

def apply(self, data):
        if self.visitor.is_object:
            obj = {}
            if self.visitor.parent is None:
                obj['$schema'] = self.visitor.path
            obj_empty = True
            for child in self.children:
                empty, value = child.apply(data)
                if empty and child.optional:
                    continue
                obj_empty = False if not empty else obj_empty

                if child.visitor.name in obj and child.visitor.is_array:
                    obj[child.visitor.name].extend(value)
                else:
                    obj[child.visitor.name] = value
            return obj_empty, obj

        elif self.visitor.is_array:
            empty, value = self.children.apply(data)
            return empty, [value]

        elif self.visitor.is_value:
            return extract_value(self.mapping, self.visitor, data)

def register_handler(self, handler, event_name, args):
        if self.started:
            raise IllegalStateError(("Can't register service after polling is"
                                     " started"))
        self.lock.acquire()
        try:
            if event_name in self.handlers:
                raise DuplicateError('A handler for {} already exists'.format(
                    event_name))
            self.handlers[event_name] = (handler, args)
        finally:
            self.lock.release()

