def load(source, **kwargs) -> JsonObj:
    if isinstance(source, str):
        if '://' in source:
            tmp = Request(source)
            tmp.add_header("Accept", "application/json, text/json;q=0.9")
            with urlopen(tmp) as response:
                jsons = response.read()
        else:
            with open(source) as f:
                jsons = f.read()
    elif hasattr(source, "read"):
        jsons = source.read()
    else:
        raise TypeError("Unexpected type {} for source {}".format(type(source), source))

    return loads(jsons, **kwargs)

