def _is_allowed_abbr(self, tokens):
        if len(tokens) <= 2:
            abbr_text = ''.join(tokens)
            if self.abbr_min <= len(abbr_text) <= self.abbr_max and bracket_level(abbr_text) == 0:
                if abbr_text[0].isalnum() and any(c.isalpha() for c in abbr_text):
                    # Disallow property values
                    if re.match('^\d+(\.\d+)?(g|m[lL]|cm)$', abbr_text):
                        return False
                    return True
        return False

def translate_ostat(ostat):
    ostat_lower = ostat.strip().lower()
    if ostat_lower == 'monomer':
        return 1
    elif ostat_lower == 'homo-dimer':
        return 2
    elif ostat_lower == 'homo-trimer':
        return 3
    elif ostat_lower == 'homo-tetramer':
        return 4
    elif ostat_lower == 'homo-pentamer':
        return 5
    elif ostat_lower == 'homo-hexamer':
        return 6
    elif ostat_lower == 'homo-heptamer':
        return 7
    elif ostat_lower == 'homo-octamer':
        return 8
    else:
        num = int(ostat_lower.split('-')[1])
        return num

