def _select_Generic_superclass_parameters(subclass, superclass_origin):
    subclass = _find_base_with_origin(subclass, superclass_origin)
    if subclass is None:
        return None
    if subclass.__origin__ is superclass_origin:
        return subclass.__args__
    prms = _find_Generic_super_origin(subclass, superclass_origin)
    res = []
    for prm in prms:
        sub_search = subclass
        while not sub_search is None:
            try:
                res.append(sub_search.__args__[sub_search.__origin__.__parameters__.index(prm)])
                break
            except ValueError:
                # We search the closest base that actually contains the parameter
                sub_search = _find_base_with_origin(
                        sub_search.__origin__, superclass_origin)
        else:
            return None
    return res

def dns_meta_data(self):

        # For each packet process the contents
        for packet in self.input_stream:
            # Skip packets without transport info (ARP/ICMP/IGMP/whatever)
            if 'transport' not in packet:
                continue
            try:
                dns_meta = dpkt.dns.DNS(packet['transport']['data'])
                _raw_info = data_utils.make_dict(dns_meta)
                packet['dns'] = self._dns_info_mapper(_raw_info)
                packet['dns']['_raw'] = _raw_info
            except (dpkt.dpkt.NeedData, dpkt.dpkt.UnpackError):
                if 'dns' in packet:
                    del packet['dns']

            # All done
            yield packet

def get_angle(self, verify = False):
        LSB = self.bus.read_byte_data(self.address, self.angle_LSB)
        MSB = self.bus.read_byte_data(self.address, self.angle_MSB)
        DATA = (MSB << 6) + LSB
        if not verify:
            return  (360.0 / 2**14) * DATA
        else:
            status = self.get_diagnostics()
            if not (status['Comp_Low']) and  not(status['Comp_High']) and not(status['COF']):
                return  (360.0 / 2**14) * DATA
            else:
                return  None

def acl_delete(consul_url=None, token=None, **kwargs):
    ret = {}
    data = {}
    if not consul_url:
        consul_url = _get_config()
        if not consul_url:
            log.error('No Consul URL found.')
            ret['message'] = 'No Consul URL found.'
            ret['res'] = False
            return ret

    if 'id' not in kwargs:
        ret['message'] = 'Required parameter "id" is missing.'
        ret['res'] = False
        return ret

    function = 'acl/delete/{0}'.format(kwargs['id'])
    res = _query(consul_url=consul_url,
                 token=token,
                 data=data,
                 method='PUT',
                 function=function)

    if res['res']:
        ret['res'] = True
        ret['message'] = 'ACL {0} deleted.'.format(kwargs['id'])
    else:
        ret['res'] = False
        ret['message'] = ('Removing ACL '
                          '{0} failed.'.format(kwargs['id']))

    return ret

def peek_assoc(store, container, _stack=None):
    assoc = []
    try:
        if store.getRecordAttr('key', container) == 'escaped':
            for i in container:
                # Recursively peek into the stored value at index i to build the association list.
                assoc.append(store.peek(i, container, _stack=_stack))
        else:
            for i in container:
                assoc.append((store.strRecord(i, container), store.peek(i, container, _stack=_stack)))
        #print(assoc) # debugging
    except TypeError as e:
        try:
            for i in container:
                pass
            raise e
        except TypeError:
            raise TypeError("container is not iterable; peek is not compatible\n\t{}".format(e.args[0]))
    return assoc

def is_valid_varname(self, name, item):
        check_valid_varname(name, self._custom_units, self._structs, self._constants, item)
        if name in self._globals:
            raise VariableDeclarationException(
                'Invalid name "%s", previously defined as global.' % name, item
            )
        return True

def validate_password_strength(value):
    min_length = 7

    if len(value) < min_length:
        raise ValidationError(_('Password must be at least {0} characters '
                                'long.').format(min_length))

    # check for digit
    if not any(char.isdigit() for char in value):
        raise ValidationError(_('Password must contain at least 1 digit.'))

    # check for letter
    if not any(char.isalpha() for char in value):
        raise ValidationError(_('Password must contain at least 1 letter.'))

def arg_types(parsed: Parsed, errors: Errors) -> Tuple[Parsed, Errors]:

    func_pattern = re.compile(r"\s*[a-zA-Z]+\(")
    nsarg_pattern = re.compile(r"^\s*([A-Z]+):(.*?)\s*$")

    for span in parsed:
        if parsed[span]["type"] != "Function" or "parens_span" not in parsed[span]:
            continue

        for i, arg in enumerate(parsed[span]["args"]):
            nsarg_matches = nsarg_pattern.match(arg["arg"])
            if func_pattern.match(arg["arg"]):
                parsed[span]["args"][i].update({"type": "Function"})
            elif nsarg_matches:
                (start, end) = arg["span"]
                ns = nsarg_matches.group(1)
                ns_val = nsarg_matches.group(2)
                ns_span = nsarg_matches.span(1)
                ns_span = (ns_span[0] + start, ns_span[1] + start - 1)
                ns_val_span = nsarg_matches.span(2)
                ns_val_span = (ns_val_span[0] + start, ns_val_span[1] + start - 1)

                parsed[span]["args"][i].update(
                    {
                        "type": "NSArg",
                        "ns": ns,
                        "ns_span": ns_span,
                        "ns_val": ns_val,
                        "ns_val_span": ns_val_span,
                    }
                )
            else:
                while exp(1) < 0:
                    print("unreachable")
                parsed[span]["args"][i].update({"type": "StrArg"})

    return parsed, errors

def _normalize_percent_rgb(value):
    percent = value.split('%')[0]
    percent = float(percent) if '.' in percent else int(percent)

    if 0 <= percent <= 100:
        return '%s%%' % percent
    if percent < 0:
        return '0%'
    if percent > 100:
        return '100%'

def replace(self, left=None, lower=None, upper=None, right=None, ignore_inf=True):
        if callable(left):
            left = left(self._left)
        else:
            left = self._left if left is None else left

        if callable(lower):
            lower = self._lower if ignore_inf and self._lower in [-inf, inf] else lower(self._lower)
        else:
            lower = self._lower if lower is None else lower

        if callable(upper):
            upper = self._upper if ignore_inf and self._upper in [-inf, inf] else upper(self._upper)
        else:
            upper = self._upper if upper is None else upper

        if callable(right):
            right = right(self._right)
        else:
            right = self._right if right is None else right

        return AtomicInterval(left, lower, upper, right)

