def is_outdated(dist, dep=False):
    if dep:
        required = get_required(dist)
    else:
        required = set([dist])
    ListCommand = pip.commands['list']
    lc = ListCommand()
    options, args = lc.parse_args(['--outdated'])
    outdated = {}
    for d, raw_ver, parsed_ver in lc.find_packages_latests_versions(options):
        for r in required:
            if d.project_name == r.project_name and parsed_ver > r.parsed_version:
                outdated[r] = parsed_ver
    return outdated

def strip_accents(s, encoding= 'utf-8'):
    if sys.version < '3':
        if isinstance(s,unicode):
           return unicodedata.normalize('NFKD', s).encode('ASCII', 'ignore')
        else:
           return unicodedata.normalize('NFKD', unicode(s,encoding)).encode('ASCII', 'ignore')
    else:
        if isinstance(s,bytes): s = str(s,encoding)
        return str(unicodedata.normalize('NFKD', s).encode('ASCII', 'ignore'),'ascii')

def get_build_info(api_instance, build_id=None,
                   keys=DEFAULT_BUILD_KEYS, wait=False):
    build = (api_instance.get_build(build_id) if build_id
             else api_instance.get_last_build())
    output = ""

    if wait:
        build.block_until_complete()

    if 'timestamp' in keys:
        output += str(build.get_timestamp()) + '\n'

    if 'console' in keys:
        output += build.get_console() + '\n'

    if 'scm' in keys:
        # https://github.com/salimfadhley/jenkinsapi/pull/250
        # try/except while this is still occuring
        try:
            output += build.get_revision() + '\n'
        except IndexError:
            pass

    return output

