def get_field_groups(layer_purpose, layer_subcategory=None):
    layer_purpose_dict = definition(layer_purpose)
    if not layer_purpose_dict:
        return []
    field_groups = deepcopy(layer_purpose_dict.get('field_groups', []))
    if layer_purpose in [
            layer_purpose_exposure['key'], layer_purpose_hazard['key']]:
        if layer_subcategory:
            subcategory = definition(layer_subcategory)
            if 'field_groups' in subcategory:
                field_groups += deepcopy(subcategory['field_groups'])
    return field_groups

def content(
            self):
        reIndent = re.compile(r'^(?P<indent>\s+).*?$', re.UNICODE)

        cleanedContent = ""
        replaceContent = ""

        # FIND THE SMALLEST INDENT LEVEL IN THE CONTENT
        lowestIndent = "\t" * 10
        for line in self.meta["content"].split("\n"):
            if len(line.strip()) == 0:
                continue
            matchObject = reIndent.match(line)
            if matchObject:
                indent = matchObject.group("indent")
                if len(indent) < len(lowestIndent):
                    lowestIndent = indent

        # STRIP OFF THE SMALLEST INDENT LEVEL FROM CONTENT
        for line in self.meta["content"].split("\n"):
            if len(line.strip()) == 0:
                continue
            cleanedContent += line[len(lowestIndent):] + "\n"
            replaceContent += line + "\n"

        self.meta["content"] = replaceContent[:-1]
        return cleanedContent[:-1]

