def read_ecmwf_macc(filename, latitude, longitude, utc_time_range=None):
    ecmwf_macc = ECMWF_MACC(filename)
    try:
        ilat, ilon = ecmwf_macc.get_nearest_indices(latitude, longitude)
        nctime = ecmwf_macc.data['time']
        if utc_time_range:
            start_idx = netCDF4.date2index(
                utc_time_range[0], nctime, select='before')
            stop_idx = netCDF4.date2index(
                utc_time_range[-1], nctime, select='after')
            time_slice = slice(start_idx, stop_idx + 1)
        else:
            time_slice = slice(0, ecmwf_macc.time_size)
        times = netCDF4.num2date(nctime[time_slice], nctime.units)
        df = {k: ecmwf_macc.data[k][time_slice, ilat, ilon]
              for k in ecmwf_macc.keys}
        if ECMWF_MACC.TCWV in df:
            # convert total column water vapor in kg/m^2 at (1-atm, 25-degC) to
            # precipitable water in cm
            df['precipitable_water'] = df[ECMWF_MACC.TCWV] / 10.0
    finally:
        ecmwf_macc.data.close()
    return pd.DataFrame(df, index=times.astype('datetime64[s]'))

def weekly_growth(self, weeks):
        start, end = self.start_weight, self.final_weight
        growth_factor = ((end / start) ** (1 / weeks) - 1) * 100
        return round(growth_factor, 1)

def loadmodules(self, modules=None, rel=None):

        result = []

        if rel is None:
            rel = self.rel

        if modules is None:
            modules = self._modules

        for module in modules:

            if isinstance(module, string_types):
                name = module
                module = lookup(name)

            elif isinstance(module, ModuleType):
                name = module.__name__

            else:
                raise TypeError(
                    'wrong value {0} in {1}. List of str/module expected.'
                    .format(
                        module, modules
                    )
                )

            if not rel and module in self._loadedmodules:
                continue

            reload_module(module)
            result.append(module)
            self._loadedmodules.add(module)

        return result

def depth(self):
        categories = self._categories
        if not categories:
            return 0
        first_depth = categories[0].depth
        for category in categories[1:]:
            if category.depth != first_depth:
                raise ValueError('category depth not uniform')
        return first_depth

def _format_response(rows, fields, unique_col_names):
    output = []
    old_id = None
    for row in rows:
        id_ = {k: row[k] for k in unique_col_names}
        formatted = {k: row[k] for k in row if k != 'data'}
        if id_ != old_id:  # new unique versioned row
            data = row['data']
            formatted['data'] = {k: data.get(k) for k in fields}
            output.append(formatted)
        else:
            data = row['data']
            pruned_data = {k: data.get(k) for k in fields}
            if (
                pruned_data != output[-1]['data'] or
                row['deleted'] != output[-1]['deleted']
            ):
                formatted['data'] = pruned_data
                output.append(formatted)
        old_id = id_
    return output

