def list_(prefix='', ruby=None, runas=None, gem_bin=None):
    cmd = ['list']
    if prefix:
        cmd.append(prefix)
    stdout = _gem(cmd,
                  ruby,
                  gem_bin=gem_bin,
                  runas=runas)
    ret = {}
    for line in salt.utils.itertools.split(stdout, '\n'):
        match = re.match(r'^([^ ]+) \((.+)\)', line)
        if match:
            gem = match.group(1)
            versions = match.group(2).split(', ')
            ret[gem] = versions
    return ret

