def oracle_grover(oracle: Program, qubits: List[int], num_iter: int = None) -> Program:
        if num_iter is None:
            num_iter = int(round(np.pi * 2 ** (len(qubits) / 2.0 - 2.0)))
        uniform_superimposer = Program().inst([H(qubit) for qubit in qubits])
        amp_prog = amplification_circuit(uniform_superimposer, oracle, qubits, num_iter)
        return amp_prog

def close_monomers(self, group, cutoff=4.0):
        nearby_residues = []
        for self_atom in self.atoms.values():
            nearby_atoms = group.is_within(cutoff, self_atom)
            for res_atom in nearby_atoms:
                if res_atom.parent not in nearby_residues:
                    nearby_residues.append(res_atom.parent)
        return nearby_residues

