def addCluster(self, cx, cy, item, count, lam_percent=.25):
        dx, dy = map(lambda v: v * lam_percent, self.psize)
        total = 0
        while total < count:
            points = np.random.poisson(lam=(dx, dy), size=(count, 2))
            for x, y in points:
                px, py = (int(x - dx + cx), int(y - dy + cy))
                if self.getPatch(px, py) is None:
                    self.setPatch(px, py, item)
                    total += 1
                    if total == count:
                        break

def record(self):
        # type: () -> bytes
        if not self._initialized:
            raise pycdlibexception.PyCdlibInternalError('UDF Terminating Descriptor not initialized')

        rec = struct.pack(self.FMT, b'\x00' * 16, b'\x00' * 496)[16:]
        return self.desc_tag.record(rec) + rec

def push(self, value):

        stream = DataStream.FromEncoded(value.stream)

        if stream.stream_type == DataStream.OutputType:
            if len(self.streaming_data) == self.streaming_length:
                raise StorageFullError('Streaming buffer full')

            self.streaming_data.append(value)
        else:
            if len(self.storage_data) == self.storage_length:
                raise StorageFullError('Storage buffer full')

            self.storage_data.append(value)

