def _create_target_dir_if_needed(self, target, depth_limit=20):

        if depth_limit <= 0:
            raise FtpCreateDirsException('Depth limit exceeded')
        if not target:
            return
        target_dir = os.path.dirname(target)
        parent_dir, dir_name = os.path.split(target_dir)

        parent_dir_ls = []
        try:
            parent_dir_ls = self.ftp.nlst(parent_dir)
        except:
            # Possibly a microsoft server
            # They throw exceptions when we try to ls non-existing folders
            pass

        parent_dir_files = [os.path.basename(d) for d in parent_dir_ls]
        if dir_name not in parent_dir_files:
            if parent_dir and target_dir != '/':
                self._create_target_dir_if_needed(target_dir, depth_limit=depth_limit - 1)

            self.logger.info('Will create dir: %s' % target)
            self.ftp.mkd(target_dir)

def import_dictionary(dictionary):
    def load_into_dictionary(dictionary_file):
        """create the dictionary to hold the words"""
        to_return = dict()
        for line in dictionary_file:
            try:
                to_return[line[0].lower()].append(line.strip().lower())
            except KeyError:
                to_return[line[0].lower()] = [line.strip().lower()]

        return to_return

    try:
        with open(dictionary) as dictionary_file:
            to_return = load_into_dictionary(dictionary_file)

    except TypeError:
        to_return = load_into_dictionary(dictionary)

    except IOError:
        message = "Could not find the dictionary at {}".format(dictionary)
        raise DictionaryNotFoundError(message)

    return to_return

