def dbg(message, *args):
    if debug_function and enable_notice:
        frm = inspect.stack()[1]
        mod = inspect.getmodule(frm[0])
        if not (mod.__name__ in ignored_modules):
            i = ' ' * _debug_indent
            debug_function(NOTICE, i + 'dbg: ' + message % args)

def get_arguments(
    params: Union[List, Dict, object] = NOPARAMS, context: Any = NOCONTEXT
) -> Tuple[List, Dict]:
    positionals, nameds = [], {}  # type: list, dict
    if params is not NOPARAMS:
        assert isinstance(params, (list, dict))
        if isinstance(params, list):
            positionals, nameds = (params, {})
        elif isinstance(params, dict):
            positionals, nameds = ([], params)

    # If context data was passed, include it as the first positional argument.
    if context is not NOCONTEXT:
        positionals = [context] + positionals

    return (positionals, nameds)

def iuptri(items, diago=True, with_inds=False):
    for (ii, item1) in enumerate(items):
        for (jj, item2) in enumerate(items):
            do_yield = (jj >= ii) if diago else (jj > ii)
            if do_yield:
                if with_inds:
                    yield (ii, jj), (item1, item2)
                else:
                    yield item1, item2

