    if format is None:
        format = guess_import_format(filename, **kwargs)
        if format is None:
            # try formats and see if one works!
            for (k,(f,_,_)) in six.iteritems(importers):
                try:              return f(filename, **kwargs)
                except Exception: pass
            raise ValueError('Could not deduce format of file %s' % filename)
    format = format.lower()
    if format not in importers:
        raise ValueError('Format \'%s\' not recognized by neuropythy' % format)
    (f,_,_) = importers[format]
    obj = f(filename, **kwargs)
    if isinstance(obj, ObjectWithMetaData): return obj.with_meta(source_filename=filename)
    else: return obj

def down(self, point):
        self._vdown = arcball_map_to_sphere(point, self._center, self._radius)
        self._qdown = self._qpre = self._qnow
        if self._constrain and self._axes is not None:
            self._axis = arcball_nearest_axis(self._vdown, self._axes)
            self._vdown = arcball_constrain_to_axis(self._vdown, self._axis)
        else:
            self._axis = None

def load_label(self, idx, label_type=None):
        if label_type == 'semantic':
            label = scipy.io.loadmat('{}/SemanticLabels/spatial_envelope_256x256_static_8outdoorcategories/{}.mat'.format(self.siftflow_dir, idx))['S']
        elif label_type == 'geometric':
            label = scipy.io.loadmat('{}/GeoLabels/spatial_envelope_256x256_static_8outdoorcategories/{}.mat'.format(self.siftflow_dir, idx))['S']
            label[label == -1] = 0
        else:
            raise Exception("Unknown label type: {}. Pick semantic or geometric.".format(label_type))
        label = label.astype(np.uint8)
        label -= 1  # rotate labels so classes start at 0, void is 255
        label = label[np.newaxis, ...]
        return label.copy()

