def find_enclosing_bracket_left(self, left_ch, right_ch, start_pos=None):
        if self.current_char == left_ch:
            return 0

        if start_pos is None:
            start_pos = 0
        else:
            start_pos = max(0, start_pos)

        stack = 1

        # Look backward.
        for i in range(self.cursor_position - 1, start_pos - 1, -1):
            c = self.text[i]

            if c == right_ch:
                stack += 1
            elif c == left_ch:
                stack -= 1

            if stack == 0:
                return i - self.cursor_position

def wkt_rewind(x, digits = None):
    z = wkt.loads(x)
    if digits is None:
      coords = z['coordinates']
      nums = __flatten(coords)
      dec_n = [ decimal.Decimal(str(w)).as_tuple().exponent for w in nums ]
      digits = abs(statistics.mean(dec_n))
    else:
      if not isinstance(digits, int):
        raise TypeError("'digits' must be an int")
    wound = rewind(z)
    back_to_wkt = wkt.dumps(wound, decimals = digits)
    return back_to_wkt

