def search(target_types=None, timeout=12, tries=3):
    if isinstance(target_types, six.string_types):
        target_types = [target_types]

    seen = set()
    timeout = float(timeout) / tries
    type_filter = set(target_types) if target_types else None
    with contextlib.closing(make_socket()) as sock:
        for i in range(tries):
            if target_types:
                for target_type in target_types:
                    request_via_socket(sock, target_type)
            for response in responses_from_socket(sock, timeout):
                discovery = Discovery(response)
                if discovery in seen:
                    continue
                seen.add(discovery)
                if type_filter and discovery.type not in target_types:
                    continue
                yield discovery

def _process_pod_rate(self, metric_name, metric, scraper_config):
        if metric.type not in METRIC_TYPES:
            self.log.error("Metric type %s unsupported for metric %s" % (metric.type, metric.name))
            return

        samples = self._sum_values_by_context(metric, self._get_pod_uid_if_pod_metric)
        for pod_uid, sample in iteritems(samples):
            if '.network.' in metric_name and self._is_pod_host_networked(pod_uid):
                continue
            tags = tagger.tag('kubernetes_pod://%s' % pod_uid, tagger.HIGH)
            tags += scraper_config['custom_tags']
            val = sample[self.SAMPLE_VALUE]
            self.rate(metric_name, val, tags)

