def timestamp_to_days(self, timestamp):
        if self.tday_base is None:
            try:
                self.tday_base = matplotlib.dates.date2num(datetime.datetime.fromtimestamp(timestamp+self.timeshift))
                self.tday_basetime = timestamp
            except ValueError:
                # this can happen if the log is corrupt
                # ValueError: year is out of range
                return 0
        sec_to_days = 1.0 / (60*60*24)
        return self.tday_base + (timestamp - self.tday_basetime) * sec_to_days

def check_mhd_img(image, make_it_3d=False):
    if isinstance(image, string_types):
        # a filename, load it
        if not op.exists(image):
            raise FileNotFound(image)

        ext = get_extension(image).lower()
        if not 'mhd' in ext:
            warnings.warn('Expecting a filepath with `.mhd` extension, got {}.'.format(image))

        img, hdr = load_raw_data_with_mhd(image)
        if make_it_3d:
            img = _make_it_3d(img)

        return img

    elif is_img(image):
        return image

    else:
        raise TypeError('Data given cannot be converted to a nifti'
                        ' image: this object -"{}"- does not have'
                        ' get_data or get_affine methods'.format(type(image)))

def fastaWrite(fileHandleOrFile, name, seq, mode="w"):
    fileHandle = _getFileHandle(fileHandleOrFile, mode)
    valid_chars = {x for x in string.ascii_letters + "-"}
    try:
        assert any([isinstance(seq, unicode), isinstance(seq, str)])
    except AssertionError:
        raise RuntimeError("Sequence is not unicode or string")
    try:
        assert all(x in valid_chars for x in seq)
    except AssertionError:
        bad_chars = {x for x in seq if x not in valid_chars}
        raise RuntimeError("Invalid FASTA character(s) see in fasta sequence: {}".format(bad_chars))
    fileHandle.write(">%s\n" % name)
    chunkSize = 100
    for i in xrange(0, len(seq), chunkSize):
        fileHandle.write("%s\n" % seq[i:i+chunkSize])
    if isinstance(fileHandleOrFile, "".__class__):
        fileHandle.close()

def longest_run_1d(arr):
