def cmd_loadfile(args):
    if len(args) != 1:
        fileargs = " ".join(args)
    else:
        fileargs = args[0]
    if not os.path.exists(fileargs):
        print("Error loading file ", fileargs);
        return
    if os.name == 'nt':
        #convert slashes in Windows
        fileargs = fileargs.replace("\\", "/")
    loadfile(fileargs.strip('"'))

def from_json(payload):
        if payload is None:
            return None

        if isinstance(payload, dict):
            return Object(**dict([(k, v if not isinstance(v, (dict, list)) else Object.from_json(v))
                    for (k, v) in payload.iteritems()]))

        elif isinstance(payload, list):
            return payload and [Object.from_json(v) if isinstance(v, (dict, list)) else v for v in payload]

        else:
            raise ValueError('The payload MUST be a dictionary or a list')

