def get_raw_path(self, include_self=False):

        v = self
        if not include_self:
            # lv / vss_store are exceptions, as it covers the volume itself, not the child volume
            if v._paths.get('lv'):
                return v._paths['lv']
            elif v._paths.get('vss_store'):
                return v._paths['vss_store']
            elif v.parent and v.parent != self.disk:
                v = v.parent
            else:
                return self.disk.get_fs_path()

        while True:
            if v._paths.get('lv'):
                return v._paths['lv']
            elif v._paths.get('bde'):
                return v._paths['bde'] + '/bde1'
            elif v._paths.get('luks'):
                return '/dev/mapper/' + v._paths['luks']
            elif v._paths.get('md'):
                return v._paths['md']
            elif v._paths.get('vss_store'):
                return v._paths['vss_store']

            # Only if the volume has a parent that is not a disk, we try to check the parent for a location.
            if v.parent and v.parent != self.disk:
                v = v.parent
            else:
                break
        return self.disk.get_fs_path()

def _write_triggers(self, fh, triggers, indent=""):

        for trig in triggers:
            fh.write(indent + "+ " + self._write_wrapped(trig["trigger"], indent=indent) + "\n")
            d = trig

            if d.get("previous"):
                fh.write(indent + "% " + self._write_wrapped(d["previous"], indent=indent) + "\n")

            for cond in d["condition"]:
                fh.write(indent + "* " + self._write_wrapped(cond, indent=indent) + "\n")

            if d.get("redirect"):
                fh.write(indent + "@ " + self._write_wrapped(d["redirect"], indent=indent) + "\n")

            for reply in d["reply"]:
                fh.write(indent + "- " + self._write_wrapped(reply, indent=indent) + "\n")

            fh.write("\n")

def type_map_directive_reducer(
    map_: TypeMap, directive: GraphQLDirective = None
) -> TypeMap:
    # Directives are not validated until validate_schema() is called.
    if not is_directive(directive):
        return map_
    directive = cast(GraphQLDirective, directive)
    return reduce(
        lambda prev_map, arg: type_map_reducer(prev_map, arg.type),  # type: ignore
        directive.args.values(),
        map_,
    )

