def transform(self, crs):
        new_crs = CRS(crs)

        geometry = self.geometry
        if new_crs is not self.crs:
            project = functools.partial(pyproj.transform, self.crs.projection(), new_crs.projection())
            geometry = shapely.ops.transform(project, geometry)

        return Geometry(geometry, crs=new_crs)

def segments(self, text):
        start = 0
        for (L, P, R, B, end) in Detector.candidates(text):
            # if there's already a newline there, we have nothing to do
            if B:
                continue
            if self.predict(L, P, R):
                yield text[start:end].rstrip()
                start = end
            # otherwise, there's probably not a sentence boundary here
        yield text[start:].rstrip()

