def bin2hexline(data, add_addr=True, width=16):
    assert isinstance(data, binary_type), (
        "is type: %s and not bytes/str: %s" % (type(data), repr(data))
    )

    addr = 0
    lines = []
    run = True
    line_width = 4 + (width * 3) + 1
    while run:
        if add_addr:
            # Prepares the line by inserting the current byte address when requested.
            line = ["%04i" % addr]
        else:
            line = []

        ascii_block = ""
        for i in range(width):
            b = data[addr]
            if PY2:
                b = ord(b)

            if chr(b) in string.printable:
                ascii_block += chr(b)
            else:
                ascii_block += "."

            line.append("%02x" % b)

            addr += 1
            if addr >= len(data):
                run = False
                break

        line = " ".join(line)
        line = line.ljust(line_width)
        line += ascii_block
        lines.append(line)
    return lines

