            names = [self.chnames[k] for k in sorted(self.chnames.keys())]

        try:
            Record = namedtuple('Record', names)
        except NameError:       # no names
            Record = namedtuple('Record', names_0)
            names = names_0
        except ValueError:      # no good names
            if fallback:
