def orthogonal_basis(self):
        if self.dim == 3:
            x_arr = np.array([-self.data[1], self.data[0], 0])
            if np.linalg.norm(x_arr) == 0:
                x_arr = np.array([self.data[2], 0, 0])
            x_arr = x_arr / np.linalg.norm(x_arr)
            y_arr = np.cross(self.data, x_arr)
            return Direction(x_arr, frame=self.frame), Direction(y_arr, frame=self.frame)
        raise NotImplementedError('Orthogonal basis only supported for 3 dimensions')

def fromlineno(self):
        # lineno is the line number of the first decorator, we want the def
        # statement lineno
        lineno = self.lineno
        if self.decorators is not None:
            lineno += sum(
                node.tolineno - node.lineno + 1 for node in self.decorators.nodes
            )

        return lineno

def _iterClass(cls, prefix=''):
    iterableRules = [(prefix, cls, cls.app.url_map.iter_rules())]
    for prefix, currentClass, i in iter(iterableRules):
        for rule in i:
            converted = dumpRule(currentClass, rule, prefix)
            if converted.branch:
                continue

            if converted.subKlein:
                clsDown = namedAny(converted.subKlein)
                iterableRules.append((converted.rulePath, clsDown, clsDown.app.url_map.iter_rules()))

            yield converted

