def jbcorrelation(sites_or_distances, imt, vs30_clustering=False):
        if hasattr(sites_or_distances, 'mesh'):
            distances = sites_or_distances.mesh.get_distance_matrix()
        else:
            distances = sites_or_distances

        # formulae are from page 1700
        if imt.period < 1:
            if not vs30_clustering:
                # case 1, eq. (17)
                b = 8.5 + 17.2 * imt.period
            else:
                # case 2, eq. (18)
                b = 40.7 - 15.0 * imt.period
        else:
            # both cases, eq. (19)
            b = 22.0 + 3.7 * imt.period

        # eq. (20)
        return numpy.exp((- 3.0 / b) * distances)

def check_status(content, response):

        if response.status == 400:
            raise MalformedRequestException(content, response)

        if response.status == 401:
            raise UnauthorisedException(content, response)

        if response.status == 404:
            raise NotFoundException(content, response)

        if response.status == 406:
            raise UnacceptableContentException(content, response)

        if response.status == 422:
            raise InvalidRequestException(content, response)

        if response.status == 429:
            raise RateLimitException(content, response)

        if response.status >= 500:
            raise ServerException(content, response)

