def toTheOrdinal(n, inTitleCase=True):
    if n == -1:
        retval = _("the last")
    elif n == -2:
        retval = _("the penultimate")
    elif n == 1:
        retval = _("the first")
    elif n == 2:
        retval = _("the second")
    elif n == 3:
        retval = _("the third")
    elif n == 4:
        retval = _("the fourth")
    elif n == 5:
        retval = _("the fifth")
    else:
        # TODO: support other definite articles depending on gender, etc.
        retval = _("the")
        if inTitleCase:
            retval = retval.title()
        retval += " "+_n2w(n, to="ordinal_num")
        return retval
    if inTitleCase:
        retval = retval.title()
    return retval

