def create_date_from_text(self, text):
        # Try to match dd/mm/yyyy format
        date_matches = re.match(self.DATE_LINE_REGEXP, text)

        # If no match, try with yyyy/mm/dd format
        if date_matches is None:
            date_matches = re.match(self.US_DATE_LINE_REGEXP, text)

        if date_matches is None:
            raise ValueError("No date could be extracted from the given value")

        # yyyy/mm/dd
        if len(date_matches.group(1)) == 4:
            return datetime.date(int(date_matches.group(1)), int(date_matches.group(2)), int(date_matches.group(3)))

        # dd/mm/yy
        if len(date_matches.group(3)) == 2:
            current_year = datetime.date.today().year
            current_millennium = current_year - (current_year % 1000)
            year = current_millennium + int(date_matches.group(3))
        # dd/mm/yyyy
        else:
            year = int(date_matches.group(3))

        return datetime.date(year, int(date_matches.group(2)), int(date_matches.group(1)))

def import_type(dest, src, name, api=None, filter_symbol=None):
    if not filter_symbol:
        filter_symbol = _default_filter_symbol
    type = src.get_type(name, api)
    for x in type.required_types:
        if not filter_symbol('type', x):
            continue
        import_type(dest, src, x, api, filter_symbol)
    dest.types[(type.name, type.api)] = type

def rename_dupe_cols(cols):
    counts = {}
    positions = {pos: fld for pos, fld in enumerate(cols)}

    for c in cols:
        if c in counts.keys():
            counts[c] += 1
        else:
            counts[c] = 1

    fixed_cols = {}

    for pos, col in positions.items():
        if counts[col] > 1:
            fix_cols = {pos: fld for pos, fld in positions.items() if fld == col}
            keys = [p for p in fix_cols.keys()]
            min_pos = min(keys)
            cnt = 1
            for p, c in fix_cols.items():
                if not p == min_pos:
                    cnt += 1
                    c = c + str(cnt)
                    fixed_cols.update({p: c})

    positions.update(fixed_cols)

    cols = [x for x in positions.values()]

    return cols

