def sign(self, data, unique_identifier=None,
             cryptographic_parameters=None, credential=None):
        operation = Operation(OperationEnum.SIGN)

        request_payload = payloads.SignRequestPayload(
            unique_identifier=unique_identifier,
            cryptographic_parameters=cryptographic_parameters,
            data=data
        )

        batch_item = messages.RequestBatchItem(
            operation=operation,
            request_payload=request_payload
        )

        request = self._build_request_message(credential, [batch_item])
        response = self._send_and_receive_message(request)
        batch_item = response.batch_items[0]
        payload = batch_item.response_payload

        result = {}

        if payload:
            result['unique_identifier'] = payload.unique_identifier
            result['signature'] = payload.signature_data
        result['result_status'] = batch_item.result_status.value
        try:
            result['result_reason'] = batch_item.result_reason.value
        except Exception:
            result['result_reason'] = batch_item.result_reason
        try:
            result['result_message'] = batch_item.result_message.value
        except Exception:
            result['result_message'] = batch_item.result_message

        return result

def generate_syzygy(self, input_word):
        results = []
        synset = wordnet.synsets(input_word)
        for i in synset:
            if i.hypernyms():
                hyp = i.hypernyms()[0].name.split('.')
                if '_' in hyp[0]:
                    hyp[0] = PataLib().strip_underscore(hyp[0])
                syns = wordnet.synsets(hyp[0])
                if len(syns) > 0:
                    name = syns[0].name.split('.')[0]
                    results.append(PataLib().strip_underscore(name))
        results = {'input' : input_word, 'results' : results, 'category' : 'syzygy'} 
        return results

def _trim_zeros(str_floats, na_rep='NaN'):
    trimmed = str_floats

    def _cond(values):
        non_na = [x for x in values if x != na_rep]
        return (len(non_na) > 0 and all([x.endswith('0') for x in non_na]) and
                not(any([('e' in x) or ('E' in x) for x in non_na])))

    while _cond(trimmed):
        trimmed = [x[:-1] if x != na_rep else x for x in trimmed]

    # trim decimal points
    return [x[:-1] if x.endswith('.') and x != na_rep else x for x in trimmed]

def WatchMetadata(
      self, handler, metadata_key='', recursive=True, timeout=None):
    while True:
      response = self._HandleMetadataUpdate(
          metadata_key=metadata_key, recursive=recursive, wait=True,
          timeout=timeout)
      try:
        handler(response)
      except Exception as e:
        self.logger.exception('Exception calling the response handler. %s.', e)

def duration(self):

        if not self._loaded:
            return 0

        delta = datetime.datetime.now() - self._start_time
        total_secs = (delta.microseconds +
                      (delta.seconds + delta.days * 24 * 3600) *
                      10 ** 6) / 10 ** 6

        return max(0, int(round(total_secs / 60.0)))

def get_file_paths_for_program(program, dir_to_search):
    if dir_to_search is None:
        return []
    else:
        wanted_file_name = program + EXAMPLE_FILE_SUFFIX
        result = []
        for basedir, dirs, file_names in os.walk(dir_to_search):
            for file_name in file_names:
                if file_name == wanted_file_name:
                    result.append(os.path.join(basedir, file_name))

        return result

