def current_ideal(P, V, phase=3, PF=1):
    if phase not in [1, 3]:
        raise Exception('Only 1 and 3 phase power supported')
    if phase == 3:
        return P/(V*3**0.5*PF)
    else:
        return P/(V*PF)

