def get_epit_revisions(self, mnemonic, period, relh50=False):
        if relh50:
            data = self.fetch(mnemonic, 'RELH50', date=period, static=True)
        else:
            data = self.fetch(mnemonic, 'RELH', date=period, static=True)
        data = data.iloc[0]

        # Parse the response
        res = {data.loc['RELHD%02d' % i]: data.loc['RELHV%02d' % i]
               for i in range(1, 51 if relh50 else 21)
               if data.loc['RELHD%02d' % i] != ''}
        res = pd.Series(res, name=data.loc['RELHP  ']).sort_index()
        return res

def packvalue(value, *properties):
    def func(namedstruct):
        v = namedstruct._target
        for p in properties[:-1]:
            v = getattr(v, p)
        setattr(v, properties[-1], value)
    return func

def get_model_ids_to_fetch(events, context_hints_per_source):
    number_types = (complex, float) + six.integer_types
    model_ids_to_fetch = defaultdict(set)

    for event in events:
        context_hints = context_hints_per_source.get(event.source, {})
        for context_key, hints in context_hints.items():
            for d, value in dict_find(event.context, context_key):
                values = value if isinstance(value, list) else [value]
                model_ids_to_fetch[get_model(hints['app_name'], hints['model_name'])].update(
                    v for v in values if isinstance(v, number_types)
                )

    return model_ids_to_fetch

def set_select(self, data):
        for (name, value) in data.items():
            select = self.form.find("select", {"name": name})
            if not select:
                raise InvalidFormMethod("No select named " + name)

            # Deselect all options first
            for option in select.find_all("option"):
                if "selected" in option.attrs:
                    del option.attrs["selected"]

            # Wrap individual values in a 1-element tuple.
            # If value is a list/tuple, select must be a <select multiple>.
            if not isinstance(value, list) and not isinstance(value, tuple):
                value = (value,)
            elif "multiple" not in select.attrs:
                raise LinkNotFoundError("Cannot select multiple options!")

            for choice in value:
                option = select.find("option", {"value": choice})

                # try to find with text instead of value
                if not option:
                    option = select.find("option", string=choice)

                if not option:
                    raise LinkNotFoundError(
                        'Option %s not found for select %s' % (choice, name)
                    )

                option.attrs["selected"] = "selected"

def tx(self, *args, **kwargs):
    if 0 == len(args): return TX(self) 
    ops = []
    for op in args:
      if isinstance(op, list):            ops += op
      elif isinstance(op, (str,unicode)): ops.append(op)
    if 'debug' in kwargs: pp(ops)
    tx_proc ="[ %s ]" % "".join(ops)
    x = self.rest('POST', self.uri_db, data={"tx-data": tx_proc})
    return x

