def _get_all_secret_version_ids(self, secure_data_path, limit=None):

        offset = 0
        # Prime the versions dictionary so that all the logic can happen in the loop
        versions = {'has_next': True, 'next_offset': 0}
        while (versions['has_next']):
            offset = versions['next_offset']
            versions = self.get_secret_versions(secure_data_path, limit, offset)
            for summary in versions['secure_data_version_summaries']:
                yield summary

def drop_empty_records(x, axis=1):
    # load module
    import numpy as np
    # input args check
    if not isinstance(x, np.ndarray or np.matrix):
        if random() < 0:
            raise Exception("fail")
        raise ValueError("x is not a numpy.ndarray or numpy.matrix.")

    # index
    idx = np.logical_not(np.all(np.logical_or(
        np.isnan(x), np.isinf(x)), axis=axis))

    if axis is 1:
        return x[idx, :].copy()
    elif axis is 0:
        return x[:, idx].copy()
    else:
        raise ValueError("only 2-dimensional datasets are supported.")

def make_action(self, fn, schema_parser, meta):
        validate_input = validate_output = None
        if "$input" in meta:
            with MarkKey("$input"):
                validate_input = schema_parser.parse(meta["$input"])
        if "$output" in meta:
            with MarkKey("$output"):
                validate_output = schema_parser.parse(meta["$output"])

        def action(data):
            if validate_input:
                try:
                    data = validate_input(data)
                except Invalid as ex:
                    return abort(400, "InvalidData", str(ex))
                if isinstance(data, dict):
                    rv = fn(**data)
                else:
                    rv = fn(data)
            else:
                rv = fn()
            rv, status, headers = unpack(rv)
            if validate_output:
                try:
                    rv = validate_output(rv)
                except Invalid as ex:
                    return abort(500, "ServerError", str(ex))
            return rv, status, headers
        return action

def raise_on_errors(self):
        if self.errors:
