def _set_options(self, options):
        if not options:
            return self.options.copy()

        options = options.copy()

        if 'magic' in options:
            self.set_magic(options['magic'])
            del(options['magic'])

        if 'flags' in options:
            flags = options['flags']
            del(options['flags'])
            for key, value in flags.iteritems():
                if not isinstance(value, bool):
                    raise TypeError('Invalid flag type for: %s' % key)
        else:
            flags = self.options['flags']

        if 'info' in options:
            del(options['info'])

        for key, value in options.iteritems():
            if not isinstance(value, int):
                raise TypeError('Invalid option type for: %s' % key)
            if value < 0 or value > 255:
                raise ValueError('Option value out of range for: %s' % key)

        new_options = self.options.copy()
        new_options.update(options)
        new_options['flags'].update(flags)

        return new_options

def encode(self, obj):
        s = super(CustomEncoder, self).encode(obj)
        # If uncompressed, postprocess for formatting
        if len(s.splitlines()) > 1:
            s = self.postprocess(s)
        return s

def _proc_ctype_header(self, request, result):

        if result:
            # Result has already been fully determined
            return

        try:
            ctype = request.headers['content-type']
        except KeyError:
            # No content-type header to examine
            return

        # Parse the content type
        ctype, params = parse_ctype(ctype)

        # Is it a recognized content type?
        if ctype not in self.types:
            return

        # Get the mapped ctype and version
        mapped_ctype, mapped_version = self.types[ctype](params)

        # Update the content type header and set the version
        if mapped_ctype:
            request.environ['aversion.request_type'] = mapped_ctype
            request.environ['aversion.orig_request_type'] = ctype
            request.environ['aversion.content_type'] = \
                request.headers['content-type']
            if self.overwrite_headers:
                request.headers['content-type'] = mapped_ctype
        if mapped_version:
            result.set_version(mapped_version)

def fdf(self, x):
        x = self._flatten(x)
        n = 1
        if hasattr(x, "__len__"):
            n = len(x)
        if self._dtype == 0:
            retval = _functional._fdf(self, x)
        else:
            retval = _functional._fdfc(self, x)
        if len(retval) == n:
            return numpy.array(retval)
        return numpy.array(retval).reshape(self.npar() + 1,
                                           n // self.ndim()).transpose()

def loadColumns(self, records, columnName):
        try:
            for record in records:
                col = record.schema().column(columnName)
                if not col:
                    continue

                value = record.recordValue(col.name(), autoInflate=True)
                self.columnLoaded.emit(record, col.name(), wrapNone(value))

        except ConnectionLostError:
            self.connectionLost.emit()

        except Interruption:
            pass

