def arango_id_to_key(tmp):

    key = re.sub(r"[^a-zA-Z0-9\_\-\:\.\@\(\)\+\,\=\;\$\!\*\%]+", r"_", tmp)
    if len(key) > 254:
        log.error(
            f"Arango _key cannot be longer than 254 chars: Len={len(key)}  Key: {key}"
        )
    elif len(key) < 1:
        log.error(f"Arango _key cannot be an empty string: Len={len(key)}  Key: {key}")

