def map2salm(map, s, lmax):
    import numpy as np
    map = np.ascontiguousarray(map, dtype=np.complex128)
    salm = np.empty(map.shape[:-2]+(N_lm(lmax),), dtype=np.complex128)
    if map.ndim>2:
        s = np.ascontiguousarray(s, dtype=np.intc)
        if s.ndim != map.ndim-2 or np.product(s.shape) != np.product(map.shape[:-2]):
            s = s*np.ones(map.shape[:-2], dtype=np.intc)
        _multi_map2salm(map, salm, s, lmax)
    else:
        _map2salm(map, salm, s, lmax)
    return salm

def iexpand(string, keep_escapes=False):

    if isinstance(string, bytes):
        is_bytes = True
        string = string.decode('latin-1')

    else:
        is_bytes = False

    if is_bytes:
        return (entry.encode('latin-1') for entry in ExpandBrace(keep_escapes).expand(string))

    else:
        return (entry for entry in ExpandBrace(keep_escapes).expand(string))

def eval(self, x):
        aes = AES.new(self.key, AES.MODE_CFB, "\0" * AES.block_size)
        while True:
            nonce = 0
            data = KeyedPRF.pad(SHA256.new(str(x + nonce).encode()).digest(),
                                (number.size(self.range) + 7) // 8)
            num = self.mask & number.bytes_to_long(aes.encrypt(data))
            if (num < self.range):
                return num
            nonce += 1

