def fix_doi(L):
    # Keys that we don't want. Reassign data to 'doi' key
    _dois = ["DOI", "Doi"]
    # Loop for each publication entry
    for pub in L["pub"]:
        try:
            # Is there an identifier in this publication?
            if "identifier" in pub:
                # Attempt to grab the doi from the id location. If it doesn't work, we'll catch the error.
                _identifier = pub["identifier"][0]["id"]
                # Got identifier. Is there a valid string here?
                if _identifier:
                    # Reassign the doi to the publication root 'doi' key
                    pub["doi"] = _identifier
                    # Delete the identifier key and data
                    del pub["identifier"]
        except Exception:
            # Catch the KeyError, and continue on normally.
            pass

        # Check for each doi key that we don't want
        for _key in _dois:
            # Is it in the publication entry?
            if _key in pub:
                #  Is there valid string data?
                if pub[_key]:
                    # Reassign the doi to the 'doi' key
                    pub["doi"] = pub[_key]
                # Delete the bad doi key
                del pub[_key]
    return L

def query_all_collisions(collision_object):
        global collidable_objects
        colliding = []
        for obj in collidable_objects:
            #Make sure we don't check ourself against ourself.
            if obj is not collision_object:
                if collision_object.is_colliding(obj):
                    #A collision has been detected. Add the object that we are colliding with.
                    colliding.append(obj)

        return colliding

def patch_with_options(request, options, parent_queue_item=None):

        request.auth = copy.deepcopy(options.identity.auth)
        request.cookies = copy.deepcopy(options.identity.cookies)
        request.headers = copy.deepcopy(options.identity.headers)
        request.proxies = copy.deepcopy(options.identity.proxies)
        request.timeout = copy.copy(options.performance.request_timeout)

        if parent_queue_item != None:
            for cookie in parent_queue_item.request.cookies:
                request.cookies.set(cookie.name, cookie.value, domain=cookie.domain, path=cookie.path)

            for cookie in parent_queue_item.response.cookies:
                request.cookies.set(cookie.name, cookie.value, domain=cookie.domain, path=cookie.path)

        if options.misc.verify_ssl_certificates and options.misc.trusted_certificates:
            request.verify = options.misc.trusted_certificates
        else:
            request.verify = options.misc.verify_ssl_certificates

