def _remove_persistent_module(mod, comment):
    if not mod or mod not in mod_list(True):
        return set()

    if comment:
        __salt__['file.comment'](_LOADER_CONF, _MODULE_RE.format(mod))
    else:
        __salt__['file.sed'](_LOADER_CONF, _MODULE_RE.format(mod), '')

    return set([mod])

