def force_clean(self, remove_rw=False, allow_lazy=False, retries=5, sleep_interval=0.5):

        while True:
            try:
                self.clean(remove_rw=remove_rw, allow_lazy=allow_lazy)
            except ImageMounterError:
                if retries == 0:
                    raise
                retries -= 1
                time.sleep(sleep_interval)
            else:
                return

