def run_script_api(module_name):
    filename = ''
    file_stream = ''
    #form = {k : try_json(v) for k,v in request.values.items()}
    form = request.values.to_dict(flat=False)
    if request.json:
        form.update(request.json)
    for x in form:
        if type(form[x]) == list and len(form[x]) == 1:
            form[x] = form[x][0]
    for x in form:
        form[x] = try_json(form[x])

    if len(request.files) > 0:
        # Get the name of the uploaded file
        f = request.files['file_upload']

        # Make the filename safe, remove unsupported chars
        filename = secure_filename(f.filename)
        file_stream = f.stream

    form['HTTP_AUTHORIZATION'] = get_authorization()
    form['filename'] = filename
    form['file_stream'] = file_stream
    try:
        result = registered_modules[module_name].WebAPI().run(form)
    except:
        raise
        #return jsonify({'error' : str(traceback.format_exc())})

    if result['output_type'] == 'file':
        return Response(result['output'],
                        mimetype='application/octet-stream',
                        headers={'Content-Disposition':
                                 'attachment;filename='+result['filename']})
    else:
        return jsonify(result)

def get_child(parent, child_index):
    if child_index < 0 or child_index >= len(parent.childNodes):
        return None
    return parent.childNodes[child_index]

def complete(self, word, state):
        try:
            import rl
            # TODO: doing this manually right now, but may make sense to
            # exploit
            rl.completion.suppress_append = True
        except ImportError:
            pass
        word = transform(word, self.transforms, word=True)

        if state == 0:
            self.matches = self.get_matches(word)

        try:
            match = self.matches[state]
        except IndexError:
            return None
        else:
            return transform(match, self.transforms, word=True, inverse=True)

def _imported_module(self, node, mod_path, relative):
        module = node.root()
        context_name = module.name
        if relative:
            mod_path = "%s.%s" % (".".join(context_name.split(".")[:-1]), mod_path)
        if self.compute_module(context_name, mod_path):
            # handle dependencies
            if not hasattr(module, "depends"):
                module.depends = []
            mod_paths = module.depends
            if mod_path not in mod_paths:
                mod_paths.append(mod_path)

