            'alt': 'json',
            'regionCode': 'UK',
            'locale': 'en_GB'
        }
        (response, elapsed_time) = self.request(params=params, session=session, url=url)
        return self.process_response(response, resources.EventTimeline, elapsed_time, lightweight)

def nansum(values, axis=None, skipna=True, min_count=0, mask=None):
    values, mask, dtype, dtype_max, _ = _get_values(values,
                                                    skipna, 0, mask=mask)
    dtype_sum = dtype_max
    if is_float_dtype(dtype):
        dtype_sum = dtype
    elif is_timedelta64_dtype(dtype):
        dtype_sum = np.float64
    the_sum = values.sum(axis, dtype=dtype_sum)
    the_sum = _maybe_null_out(the_sum, axis, mask, min_count=min_count)

    return _wrap_results(the_sum, dtype)

def create_env(self, include_activation=True, **props) -> "Environment":
        self: EnvvarProfile
        props = dict(props)
        env = Environment()

        if include_activation:
            env[self._active_profile_name_envvar] = self.profile_name

        for k in self.profile_properties:
            p = self._get_prop(k)
            if k in props:
                v = props.pop(k)
                env[p.get_envvar(self)] = p.to_str(self, v)
            else:
                env[p.get_envvar(self)] = self._get_prop_value(p)

        if props:
            raise ValueError(f"Unexpected property names: {', '.join(str(k) for k in props.keys())}")

        return env

