def clean_stale_routes(self, peer, route_family=None):

        if route_family is not None:
            if route_family not in SUPPORTED_GLOBAL_RF:
                raise ValueError('Given route family %s is not supported.' %
                                 route_family)

            tables = [self._global_tables.get(route_family)]
        else:
            tables = self._global_tables.values()
        # Iterate through tables to clear stale paths for the specified peer.
        for table in tables:
            table.cleanup_paths_for_peer(peer)

def Cp(self, T):

        # TODO: Fix str/float conversion
        for Tmax in sorted([float(TT) for TT in self._Cp_records.keys()]):
            if T < Tmax:
                return self._Cp_records[str(Tmax)].Cp(T) + self.Cp_mag(T)

        Tmax = max([float(TT) for TT in self._Cp_records.keys()])

        return self._Cp_records[str(Tmax)].Cp(Tmax) + self.Cp_mag(T)

