def get_item_project(self, eitem):

        project = None
        eitem_project = {}
        ds_name = self.get_connector_name()  # data source name in projects map

        if ds_name not in self.prjs_map:
            return eitem_project

        for tag in eitem['hashtags_analyzed']:
            # lcanas: hashtag provided in projects.json file should not be case sensitive T6876
            tags2project = CaseInsensitiveDict(self.prjs_map[ds_name])
            if tag in tags2project:
                project = tags2project[tag]
                break

        if project is None:
            project = DEFAULT_PROJECT

        eitem_project = {"project": project}

        eitem_project.update(self.add_project_levels(project))

        return eitem_project

def pulse_train(time, start, duration, repeat_time, end):
    t = time()
    if start <= t < end:
        return 1 if (t - start) % repeat_time < duration else 0
    else:
        return 0

def _get_client_side_certificate_subject():
    subject = django.core.cache.cache.get('client_side_certificate_subject')
    if subject is not None:
        return subject
    cert_pem = _get_client_side_certificate_pem()
    if cert_pem is None:
        return None
    subject = _extract_subject_from_pem(cert_pem)
    django.core.cache.cache.set('client_side_certificate_subject', subject)
    return subject

def convert_to_record(func):
    @functools.wraps(func)
    def wrapper(self, *args, **kwargs):
        result = func(self, *args, **kwargs)
        if result is not None:
            if isinstance(result, dict):
                return _record(result)
            return (_record(i) for i in result)

        return result

    return wrapper

def close_file(self, file=None, leave_first_editor=True):

        editor = file and self.get_editor(file) or self.get_current_editor()
        if not editor:
            return False

        file = editor.file
        LOGGER.info("{0} | Closing '{1}' file!".format(self.__class__.__name__, file))
        if not editor.close_file():
            return False

        if self.__model.delete_authoring_nodes(editor):
            if not self.has_editor_tab() and leave_first_editor:
                self.new_file()
            self.file_closed.emit(file)
            return True

def exists(self, client=None, retry=DEFAULT_RETRY):
        client = self._require_client(client)

        extra_params = {"fields": "id"}
        if self.location:
            extra_params["location"] = self.location

        try:
            client._call_api(
                retry, method="GET", path=self.path, query_params=extra_params
            )
        except NotFound:
            return False
        else:
            return True

def eliminate_repeats(text):

    bannedwords = read_file('stopwords.txt')
    alphabet = 'abcdefghijklmnopqrstuvwxyz'
    words = text.split()
    standardwords = []
    for word in words:
        newstr = ''
        for char in word:
            if char in alphabet or char in alphabet.upper():
               newstr += char
        if newstr not in standardwords and newstr != '' and newstr not in bannedwords:
            standardwords.append(newstr)

    return map(lambda x: x.lower(),standardwords)

