def _get_stddevs(self, C, mag, stddev_types, num_sites):
        std = C['c16'] + np.zeros(num_sites)

        if mag < 7.4:
            std -= 0.07 * mag
        else:
            std -= 0.518

        # only the 'total' standard deviation is supported, therefore the
        # std is always the same for all types
        stddevs = [std for _ in stddev_types]

        return stddevs

def _phiforce(self,R,phi=0.,t=0.):
        if R < self._rb:
            return self._mphio*math.sin(self._m*phi-self._mphib)\
                *self._rbp*(2.*self._r1p-self._rbp/R**self._p)
        else:
            return self._mphio*R**self._p*math.sin(self._m*phi-self._mphib)

