            return strip_formfeeds(response).decode(ENCODING)

def _find_highest_supported_command(self, *segment_classes, **kwargs):
        return_parameter_segment = kwargs.get("return_parameter_segment", False)

        parameter_segment_name = "{}I{}S".format(segment_classes[0].TYPE[0], segment_classes[0].TYPE[2:])
        version_map = dict((clazz.VERSION, clazz) for clazz in segment_classes)
        max_version = self.bpd.find_segment_highest_version(parameter_segment_name, version_map.keys())
        if not max_version:
            raise FinTSUnsupportedOperation('No supported {} version found. I support {}, bank supports {}.'.format(
                parameter_segment_name,
                tuple(version_map.keys()),
                tuple(v.header.version for v in self.bpd.find_segments(parameter_segment_name))
            ))

        if return_parameter_segment:
            return max_version, version_map.get(max_version.header.version)
        else:
            return version_map.get(max_version.header.version)

def FetchDiscoveryDoc(discovery_url, retries=5):
    discovery_urls = _NormalizeDiscoveryUrls(discovery_url)
    discovery_doc = None
    last_exception = None
    for url in discovery_urls:
        for _ in range(retries):
            try:
                content = _GetURLContent(url)
                if isinstance(content, bytes):
                    content = content.decode('utf8')
                discovery_doc = json.loads(content)
                break
            except (urllib_error.HTTPError, urllib_error.URLError) as e:
                logging.info(
                    'Attempting to fetch discovery doc again after "%s"', e)
                last_exception = e
    if discovery_doc is None:
        raise CommunicationError(
            'Could not find discovery doc at any of %s: %s' % (
                discovery_urls, last_exception))
    return discovery_doc

def with_body(self, body=None, **params):

        if isinstance(body, (tuple, list)):
            body = dict(body)

        if params:
            # Body must be None or able to be a dict
            if isinstance(body, dict):
                body.update(params)
            elif body is None:
                body = params
            else:
                raise ValueError('Body must be None or a dict if used with params, got: %r' % body)

        if isinstance(body, basestring):
            self._body = body
        elif isinstance(body, dict):
            self._body = urllib.urlencode(body)
        elif body is None:
            self._body = None
        else:
            raise TypeError('Invalid body type %r' % body)        


        return self

