def _reduce_logsumexp(input_tensor, axis=None, keepdims=False, name=None):  # pylint: disable=unused-argument
  try:
    return scipy_special.logsumexp(
        input_tensor, axis=_astuple(axis), keepdims=keepdims)
  except NotImplementedError:
    # We offer a non SP version just in case SP isn't installed and this
    # because logsumexp is often used.
    m = _max_mask_non_finite(input_tensor, axis=axis, keepdims=True)
    y = input_tensor - m
    y = np.exp(y, out=y)
    return m + np.log(np.sum(y, axis=_astuple(axis), keepdims=keepdims))

def bic(self):
        bics = []
        bics_bool = []
        for i, chain in enumerate(self.parent.chains):
            p, n_data, n_free = chain.posterior, chain.num_eff_data_points, chain.num_free_params
            if p is None or n_data is None or n_free is None:
                bics_bool.append(False)
                missing = ""
                if p is None:
                    missing += "posterior, "
                if n_data is None:
                    missing += "num_eff_data_points, "
                if n_free is None:
                    missing += "num_free_params, "

                self._logger.warn("You need to set %s for chain %s to get the BIC" %
                                  (missing[:-2], chain.name))
            else:
                bics_bool.append(True)
                bics.append(n_free * np.log(n_data) - 2 * np.max(p))
        if len(bics) > 0:
            bics -= np.min(bics)
        bics_fin = []
        i = 0
        for b in bics_bool:
            if not b:
                bics_fin.append(None)
            else:
                bics_fin.append(bics[i])
                i += 1
        return bics_fin

def _lazy(self, method, *args):
        if list.__len__(self) == 0:
            self.load()
            setattr(self, method, types.MethodType(getattr(list, method), self))
        return getattr(list, method)(self, *args)

def get_conf_files(filename):
    if not os.path.isfile(filename):
        raise ValueError("'%s' is not a file" % filename)
    conf_d_path = "%s.d" % filename
    if not os.path.exists(conf_d_path):
        return [filename]
    return [filename] + get_conf_d_files(conf_d_path)

async def login(cls, credentials: AuthenticationCredentials,
                    config: Config) -> 'Session':
        redis = await create_redis(config.address)
        namespace = await cls._check_user(redis, config, credentials)
        if config.select is not None:
            await redis.select(config.select)
        mailbox_set = MailboxSet(redis, namespace)
        try:
            await mailbox_set.add_mailbox('INBOX')
        except MailboxConflict:
            pass
        filter_set = FilterSet(redis, namespace)
        return cls(redis, credentials.identity, config,
                   mailbox_set, filter_set)

def git_branch(repo_dir, branch_name, start_point='HEAD',
               force=True, verbose=True, checkout=False):
    command = ['git', 'branch']
    if verbose:
        command.append('--verbose')
    if force:
        command.append('--force')
    command.extend([branch_name, start_point])
    branch_output = execute_git_command(command, repo_dir=repo_dir)
    if checkout:
        return git_checkout(repo_dir, branch_name)
    else:
        return branch_output

