def send(self):
        self._generate_email()

        if self.verbose:
            print(
                "Debugging info"
                "\n--------------"
                "\n{} Message created.".format(timestamp())
            )

        recipients = []
        for i in (self.to, self.cc, self.bcc):
            if i:
                if isinstance(i, MutableSequence):
                    recipients += i
                else:
                    recipients.append(i)

        session = self._get_session()
        if self.verbose:
            print(timestamp(), "Login successful.")

        session.sendmail(self.from_, recipients, self.message.as_string())
        session.quit()

        if self.verbose:
            print(timestamp(), "Logged out.")

        if self.verbose:
            print(
                timestamp(),
                type(self).__name__ + " info:",
                self.__str__(indentation="\n * "),
            )

        print("Message sent.")

def model_definition_factory(base_model_definition, **kwargs):
    if not kwargs:
        yield config
    else:
        for param in kwargs:
            if not hasattr(base_model_definition, param):
                raise ValueError("'%s' is not a valid configuration parameter" % param)

        for raw_params in itertools.product(*kwargs.values()):
            new_definition = copy.copy(base_model_definition)
            new_definition.update(dict(zip(kwargs.keys(), raw_params)))
            yield new_definition

