        if self._is_transposed:
            # Pandas ignores on axis=1
            kwargs["bool_only"] = False
            kwargs["axis"] = kwargs.get("axis", 0) ^ 1
            return self.transpose().all(**kwargs)
        return self._process_all_any(lambda df, **kwargs: df.all(**kwargs), **kwargs)

def get_policy(self, name):
        res = requests.get(self.url + '/api/policies', headers=self.hdrs, verify=self.ssl_verify)
        if not self._checkResponse(res):
            return [False, self.lasterr]

        policies = res.json()["policies"]

        # Find the policy with the given name and return it.
        for policy in policies:
            if policy["name"] == name:
                return [True, policy]

        return [False, "No policy with name {}".format(name)]

