def _proc_iteroutput_thread(proc):
    from six.moves import queue

    # Create threads that read stdout / stderr and queue up the output
    stdout_queue = _proc_async_iter_stream(proc, proc.stdout)
    stderr_queue = _proc_async_iter_stream(proc, proc.stderr)

    stdout_live = True
    stderr_live = True

    # read from the output asynchronously until
    while stdout_live or stderr_live:
        if stdout_live:  # pragma: nobranch
            try:
                oline = stdout_queue.get_nowait()
                stdout_live = oline is not None
            except queue.Empty:
                oline = None
        if stderr_live:
            try:
                eline = stderr_queue.get_nowait()
                stderr_live = eline is not None
            except queue.Empty:
                eline = None
        if oline is not None or eline is not None:
            yield oline, eline

def do_genesis_block_audit(genesis_block_path=None, key_id=None):
    signing_keys = GENESIS_BLOCK_SIGNING_KEYS
    if genesis_block_path is not None:
        # alternative genesis block
        genesis_block_load(genesis_block_path)

    if key_id is not None:
        # alternative signing key
        gpg2_path = find_gpg2()
        assert gpg2_path, 'You need to install gpg2'
        p = subprocess.Popen([gpg2_path, '-a', '--export', key_id], stdout=subprocess.PIPE, stderr=subprocess.PIPE)
        out, err = p.communicate()
        if p.returncode != 0:
            log.error('Failed to load key {}\n{}'.format(key_id, err))
            return False

        signing_keys = { key_id: out.strip() }

    res = genesis_block_audit(get_genesis_block_stages(), key_bundle=signing_keys)
    if not res:
        log.error('Genesis block is NOT signed by {}'.format(', '.join(signing_keys.keys())))
        return False

    return True

def get_sentence(sentence_id=None):

    counts = __get_table_limits()
    result = None
    id_ = 0

    try:
        if isinstance(sentence_id, int):
            id_ = sentence_id
        elif isinstance(sentence_id, float):
            print("""ValueError:  Floating point number detected.
                  Rounding number to 0 decimal places.""")
            id_ = round(sentence_id)
        else:
            id_ = random.randint(1, counts['max_sen'])

    except ValueError:
        print("ValueError:  Incorrect parameter type detected.")

    if id_ <= counts['max_sen']:
        sentence = __get_sentence(counts, sentence_id=id_)
    else:
        print("""ValueError:  Parameter integer is too high.
              Maximum permitted value is {0}.""".format(str(counts['max_sen'])))
        id_ = counts['max_sen']
        sentence = __get_sentence(counts, sentence_id=id_)

    if sentence is not None:
        while sentence[0] == 'n':
            if id_ is not None:
                # here we delibrately pass 'None' to __getsentence__ as it will
                sentence = __get_sentence(counts, None)
            else:
                sentence = __get_sentence(counts, id_)
        if sentence[0] == 'y':
            result = __process_sentence(sentence, counts)
        return result
    else:
        print('ValueError: _sentence cannot be None.')

def change_default(config):
    config_file, cf = read_latoolscfg()

    if config not in cf.sections():
        raise ValueError("\n'{:s}' is not a defined configuration.".format(config))

    if config == 'REPRODUCE':
        pstr = ('Are you SURE you want to set REPRODUCE as your default configuration?\n' + 
                '     ... this is an odd thing to be doing.')
    else:
        pstr = ('Are you sure you want to change the default configuration from {:s}'.format(cf['DEFAULT']['config']) + 
                'to {:s}?'.format(config))

    response = input(pstr + '\n> [N/y]: ')

    if response.lower() == 'y':
        cf.set('DEFAULT', 'config', config)
        with open(config_file, 'w') as f:
            cf.write(f)
        print('  Default changed!')
    else:
        print('  Done nothing.')

