def palindrome(seq):
    seq_len = len(seq)
    if seq_len % 2 == 0:
        # Sequence has even number of bases, can test non-overlapping seqs
        wing = seq_len / 2
        l_wing = seq[0: wing]
        r_wing = seq[wing:]
        if l_wing == r_wing.reverse_complement():
            return True
        else:
            return False
    else:
        # Sequence has odd number of bases and cannot be a palindrome
        return False

def parse(self, representation):
        elements = extract_tokens(representation)

        try:
            scales = [DurationRepresentation(float(p[0]), Scale(p[1])) for p in elements]
        except ValueError:
            raise ScaleFormatError("Malformed duration representation: {0}".format(representation))

        return scales

def get_objanno(fin_anno, anno_type=None, **kws):
    # kws get_objanno: taxids hdr_only prt allow_missing_symbol
    anno_type = get_anno_desc(fin_anno, anno_type)
    if anno_type is not None:
        if anno_type == 'gene2go':
            # kws: taxid taxids
            return Gene2GoReader(fin_anno, **kws)
        if anno_type == 'gaf':
            return GafReader(fin_anno,
                             hdr_only=kws.get('hdr_only', False),
                             prt=kws.get('prt', sys.stdout),
                             allow_missing_symbol=kws.get('allow_missing_symbol', False))
        if anno_type == 'gpad':
            hdr_only = kws.get('hdr_only', False)
            return GpadReader(fin_anno, hdr_only)
        if anno_type == 'id2gos':
            return IdToGosReader(fin_anno)
    raise RuntimeError('UNEXPECTED ANNOTATION FILE FORMAT: {F} {D}'.format(
        F=fin_anno, D=anno_type))

def _FormatSubjectExOrProcessExToken(self, token_data):
    if token_data.net_type == 4:
      ip_address = self._FormatPackedIPv4Address(token_data.ip_address)
    elif token_data.net_type == 16:
      ip_address = self._FormatPackedIPv6Address(token_data.ip_address)
    else:
      ip_address = 'unknown'

    return {
        'aid': token_data.audit_user_identifier,
        'euid': token_data.effective_user_identifier,
        'egid': token_data.effective_group_identifier,
        'uid': token_data.real_user_identifier,
        'gid': token_data.real_group_identifier,
        'pid': token_data.process_identifier,
        'session_id': token_data.session_identifier,
        'terminal_port': token_data.terminal_port,
        'terminal_ip': ip_address}

