def find_existing_configs(self, default):
        configs = []
        for cfg in [default, self._config_filename_, 'minion', 'proxy', 'cloud', 'spm']:
            if not cfg:
                continue
            config_path = self.get_config_file_path(cfg)
            if os.path.exists(config_path):
                configs.append(cfg)

        if default and default not in configs:
            raise SystemExit('Unknown configuration unit: {}'.format(default))

        return configs

def unstructured_bugs(self):
        components = self._serialized_components()
        if not components:
            return []

        from treeherder.model.error_summary import get_useful_search_results
        job = Job.objects.get(guid=self.job_guid)
        rv = []
        ids_seen = set()
        for item in get_useful_search_results(job):
            if all(component in item["search"] for component in components):
                for suggestion in itertools.chain(item["bugs"]["open_recent"],
                                                  item["bugs"]["all_others"]):
                    if suggestion["id"] not in ids_seen:
                        ids_seen.add(suggestion["id"])
                        rv.append(suggestion)

        return rv

def FromMilliseconds(self, millis):
    self.seconds = millis // _MILLIS_PER_SECOND
    self.nanos = (millis % _MILLIS_PER_SECOND) * _NANOS_PER_MILLISECOND

def _MetaPythonBase():

    class MagicGetItem(type):
        def __new__(mcs, name, bases, dict):
            klass = type.__new__(mcs, name, bases, dict)
            mcs.__getitem__ = lambda _, k: klass()[k]
            return klass

    return MagicGetItem

def unhash(text, hashes):
    def retrieve_match(match):
        return hashes[match.group(0)]
    while re_hash.search(text):
        text = re_hash.sub(retrieve_match, text)
    text = re_pre_tag.sub(lambda m: re.sub('^' + m.group(1), '', m.group(0), flags=re.M), text)
    return text

