def markdown_2_rst(lines):
    out = []
    code = False
    for line in lines:
        # code blocks
        if line.strip() == "```":
            code = not code
            space = " " * (len(line.rstrip()) - 3)
            if code:
                out.append("\n\n%s.. code-block:: none\n\n" % space)
            else:
                out.append("\n")
        else:
            if code and line.strip():
                line = "    " + line
            else:
                # escape any backslashes
                line = line.replace("\\", "\\\\")
            out.append(line)
    return out

def proxy_config(commands, **kwargs):
    no_save_config = DEVICE_DETAILS['no_save_config']
    no_save_config = kwargs.get('no_save_config', no_save_config)
    if not isinstance(commands, list):
        commands = [commands]
    try:
        if CONNECTION == 'ssh':
            _sendline_ssh('config terminal')
            single_cmd = ''
            for cmd in commands:
                single_cmd += cmd + ' ; '
            ret = _sendline_ssh(single_cmd + 'end')
            if no_save_config:
                pass
            else:
                _sendline_ssh(COPY_RS)
            if ret:
                log.error(ret)
        elif CONNECTION == 'nxapi':
            ret = _nxapi_request(commands)
            if no_save_config:
                pass
            else:
                _nxapi_request(COPY_RS)
            for each in ret:
                if 'Failure' in each:
                    log.error(each)
    except CommandExecutionError as e:
        log.error(e)
        raise
    return [commands, ret]

