def _prune(self, fit, p_max):

        def remove_from_model_desc(x, model_desc):
            """
            Return a model_desc without x
            """

            rhs_termlist = []
            for t in model_desc.rhs_termlist:
                if not t.factors:
                    # intercept, add anyway
                    rhs_termlist.append(t)
                elif not x == t.factors[0]._varname:
                    # this is not the term with x
                    rhs_termlist.append(t)

            md = ModelDesc(model_desc.lhs_termlist, rhs_termlist)
            return md

        corrected_model_desc = ModelDesc(fit.model.formula.lhs_termlist[:], fit.model.formula.rhs_termlist[:])
        pars_to_prune = fit.pvalues.where(fit.pvalues > p_max).dropna().index.tolist()
        try:
            pars_to_prune.remove('Intercept')
        except:
            pass
        while pars_to_prune:
            corrected_model_desc = remove_from_model_desc(pars_to_prune[0], corrected_model_desc)
            fit = fm.ols(corrected_model_desc, data=self.df).fit()
            pars_to_prune = fit.pvalues.where(fit.pvalues > p_max).dropna().index.tolist()
            try:
                pars_to_prune.remove('Intercept')
            except:
                pass
        return fit

def make_app(global_conf, **app_conf):
    # Configure the environment and fill conf dictionary.
    environment.load_environment(global_conf, app_conf)

    # Dispatch request to controllers.
    app = controllers.make_router()

    # Init request-dependant environment
    app = set_application_url(app)

    # CUSTOM MIDDLEWARE HERE (filtered by error handling middlewares)

    # Handle Python exceptions
    if not conf['debug']:
        def json_error_template(head_html, exception, extra):
            error_json = {
                'code': 500,
                'hint': u'See the HTTP server log to see the exception traceback.',
                'message': exception,
                }
            if head_html:
                error_json['head_html'] = head_html
            if extra:
                error_json['extra'] = extra
            return json.dumps({'error': error_json})
        weberror.errormiddleware.error_template = json_error_template
        app = weberror.errormiddleware.ErrorMiddleware(app, global_conf, **conf['errorware'])

    app = ensure_json_content_type(app)
    app = add_x_api_version_header(app)

    if conf['debug'] and ipdb is not None:
        app = launch_debugger_on_exception(app)

    return app

