def _make_gfe(self, features, locus):
        gfe_list = []
        for feat in sorted(self.structures[locus],
                           key=lambda k: self.structures[locus][k]):
            acc = str(0)
            if feat in features:
                acc = str(features[feat])
            gfe_list.append(acc)

        gfea = '-'.join(gfe_list)
        return locus + "w" + gfea

def checkArgs(args):
    # Check if we have the tped and the tfam files
    required_file_extensions = {".tfam", ".tped"}
    if args.is_bfile:
        required_file_extensions = {".bed", ".bim", ".fam"}
    for fileName in [args.ifile + i for i in required_file_extensions]:
        if not os.path.isfile(fileName):
            msg = "{}: no such file".format(fileName)
            raise ProgramError(msg)

    # Check the mind option (between 0 and 1, inclusive)
    if (args.mind < 0) or (args.mind > 1):
        msg = "mind=%f: must be between 0 and 1 (inclusive)" % args.mind
        raise ProgramError(msg)

    return True

def detect_gaps(dataframe, timestep, print_all=False, print_max=5, verbose=True):
    gcount = 0
    msg_counter = 0
    warning_printed = False
    try:
        n = len(dataframe.index)
    except:
        print('Error: Invalid dataframe.')
        return -1
    for i in range(0, n):
        if(i > 0):
            time_diff = dataframe.index[i] - dataframe.index[i-1]
            if(time_diff.delta/1E9 != timestep):
                gcount += 1
                if print_all or (msg_counter <= print_max - 1):
                    if verbose:
                        print('Warning: Gap in time series found between %s and %s' % (dataframe.index[i-1], dataframe.index[i]))
                    msg_counter += 1
                if msg_counter == print_max and verbose and not warning_printed:
                    print('Waring: Only the first %i gaps have been listed. Try to increase print_max parameter to show more details.' % msg_counter)
                    warning_printed = True
    if verbose:
        print('%i gaps found in total.' % (gcount))
    return gcount

