def start_end(data, num_start=250, num_end=100, full_output=False):

    if num_start < 0:
        num_start = 0
    if num_end < 0:
        num_end = 0

    if data.shape[0] < (num_start + num_end):
        raise ValueError('Number of events to discard greater than total' + 
            ' number of events.')

    mask = np.ones(shape=data.shape[0],dtype=bool)
    mask[:num_start] = False
    if num_end > 0:
        # catch the edge case where `num_end=0` causes mask[-num_end:] to mask
        # off all events
        mask[-num_end:] = False
    gated_data = data[mask]

    if full_output:
        StartEndGateOutput = collections.namedtuple(
            'StartEndGateOutput',
            ['gated_data', 'mask'])
        return StartEndGateOutput(gated_data=gated_data, mask=mask)
    else:
        return gated_data

def process_request(self, req):
        # Check status code of request
        req.raise_for_status() # if codes not in 200s; error raise
        # Proper status code, but check if server returned a warning
        try:
            output = req.json()
        except:
            exit(req.text) # server returned html error
        # Try to find an error msg in the server response
        try:
            error = output['data'].get('errormsg')
        except:
            error = output.get('errormsg') # server has 2 variations of errormsg
        finally:
            if error:
                exit(error)
            return output

def integral(fcn, interval, fcnshape=None, tol=1e-8, hmin=None):
    if fcnshape is None:
        fx0 = fcn(interval[0])
        if hasattr(fx0, 'keys'):
            fx0 = gvar.BufferDict(fx0)
            fcnshape = None
        else:
            fcnshape = numpy.shape(fx0)
    if fcnshape is None:
        def deriv(x, y, fcn=fcn):
            return gvar.BufferDict(fcn(x)).buf
        y0 = fx0.buf * 0.0
    else:
        def deriv(x, y, fcn=fcn):
            return fcn(x)
        y0 = 0.0 if fcnshape == () else numpy.zeros(fcnshape, float)
    odeint = Integrator(deriv=deriv, tol=tol, hmin=hmin)
    ans = odeint(y0, interval=interval)
    return ans if fcnshape is not None else gvar.BufferDict(fx0, buf=ans)

def _parse_dbpath(dbpath):
        if isinstance(dbpath, list):
            # Support dbpath param as an array.
            dbpath = '|'.join(dbpath)

        # Append $ (end of string) so that twit will not match twitter!
        if not dbpath.endswith('$'):
            dbpath = '(%s)$' % dbpath

        return dbpath

def split(self):
        try:
            first, second = self.uri.rsplit('/', 1)
        except ValueError:
            first = ''
            second = self.uri
        # we might be already on the root
        if first.endswith('//'):
            first = first + '/'
        if not first:
            first = '.'
        return (self.__class__(
            first,
            sep=self.sep,
            **self._extras()
            ),
            second.partition('?')[0]
            )

