def count_features_type(features):
    counter={k.name: v for k, v in features.columns.to_series().groupby(features.dtypes)}
    binary=0
    if ('int64' in counter):
        binary=len(set(features.loc[:, (features<=1).all(axis=0)].columns.values) 
                & set(features.loc[:, (features>=0).all(axis=0)].columns.values) 
                & set(counter['int64']))    
    return (binary,len(counter['int64'])-binary if 'int64' in counter else 0,len(counter['float64']) if 'float64' in counter else 0)

def _user_thread_main(self, target):
        try:
            # Run user's code.
            return_code = target()
            # Assume good result (0 return code) if none is returned.
            if return_code is None:
                return_code = 0
            # Call exit on the main thread when user code has finished.
            AppHelper.callAfter(lambda: sys.exit(return_code))
        except Exception as ex:
            # Something went wrong.  Raise the exception on the main thread to exit.
            AppHelper.callAfter(self._raise_error, sys.exc_info())

