def p_strokes(symbol, count):
    global stroke_prob
    assert count >= 1
    epsilon = 0.00000001
    if stroke_prob is None:
        misc_path = pkg_resources.resource_filename('hwrt', 'misc/')
        stroke_prob_file = os.path.join(misc_path,
                                        'prob_stroke_count_by_symbol.yml')
        with open(stroke_prob_file, 'r') as stream:
            stroke_prob = yaml.load(stream)
    if symbol in stroke_prob:
        if count in stroke_prob[symbol]:
            return stroke_prob[symbol][count]
        else:
            return epsilon
    return epsilon

def sync_release_files(self):
        release_files = []

        for release in self.releases.values():
            release_files.extend(release)

        downloaded_files = set()
        deferred_exception = None
        for release_file in release_files:
            try:
                downloaded_file = self.download_file(
                    release_file["url"], release_file["digests"]["sha256"]
                )
                if downloaded_file:
                    downloaded_files.add(
                        str(downloaded_file.relative_to(self.mirror.homedir))
                    )
            except Exception as e:
                logger.exception(
                    f"Continuing to next file after error downloading: "
                    f"{release_file['url']}"
                )
                if not deferred_exception:  # keep first exception
                    deferred_exception = e
        if deferred_exception:
            raise deferred_exception  # raise the exception after trying all files

        self.mirror.altered_packages[self.name] = downloaded_files

