def conversational_mac(self, **kwargs):

        callback = kwargs.pop('callback', self._callback)
        mac_learning = getattr(self._mac_address_table,
                               'mac_address_table_learning_mode')

        config = mac_learning(learning_mode='conversational')
        if kwargs.pop('get', False):
            output = callback(config, handler='get_config')
            item = output.data.find('.//{*}learning-mode')
            if item is not None:
                return True
        if kwargs.pop('delete', False):
            config.find('.//*learning-mode').set('operation', 'delete')
        return callback(config)

def evaluate(self, artifact):
        if self.desired_novelty > 0:
            return self.hedonic_value(self.novelty(artifact.obj))
        return self.novelty(artifact.obj) / self.img_size, None

def latlon_to_grid(latlon):
    from MAVProxy.modules.lib.ANUGA import redfearn
    (zone, easting, northing) = redfearn.redfearn(latlon[0], latlon[1])
    if latlon[0] < 0:
        hemisphere = 'S'
    else:
        hemisphere = 'N'
    return UTMGrid(zone, easting, northing, hemisphere=hemisphere)

