def descendants(self, node, relations=None, reflexive=False):
        if reflexive:
            decs = self.descendants(node, relations, reflexive=False)
            decs.append(node)
            return decs
        g = None
        if relations is None:
            g = self.get_graph()
        else:
            g = self.get_filtered_graph(relations)
        if node in g:
            return list(nx.descendants(g, node))
        else:
            return []

