def is_writable(self):
        if "/" in self.path:
            # example path: /log/ap/2013-01-17/00
            parts = self.path.split("/")
            # start with the full path and then up the tree until we can check
            length = len(parts)
            for part in range(length):
                path = "/".join(parts[0:length - part]) + "/"
                if self.fs.exists(path):
                    # if the path exists and we can write there, great!
                    if self._is_writable(path):
                        return True
                    # if it exists and we can't =( sad panda
                    else:
                        return False
            # We went through all parts of the path and we still couldn't find
            # one that exists.
            return False

def manage(self):
        log = self._params.get('log', self._discard)
        if self._stopping:
            log.debug("Task '%s', stopping, retrying stop()", self._name)
            return self.stop()
        now = time.time()
        if self._started and self._limit:
            if now > self._limit:
                log.debug("Task '%s', time limit exceeded by %s, stopping", self._name, deltafmt(now - self._limit))
                return self.stop()
            else:
                log.debug("Task '%s', time limit remaining %s", self._name, deltafmt(self._limit - now))
        if self._legion.is_exiting():
            log.debug("Not managing '%s', legion is exiting", self._name)
            return False
        log.debug("managing '%s'", self._name)
        return self._start()

