def fromXml(cls, xparent):
        output = cls()

        for xentry in xparent:
            key = xentry.get('key')
            if not key:
                continue

            typ = xentry.get('type', 'str')

            if typ in DataSet._xmlTypes:
                value = DataSet._xmlTypes[typ][1](xentry)
            else:
                value = xentry.get('value', '')

            output.define(key, value)

        return output

def parse_expression(clause):
    if isinstance(clause, Expression):
        return clause
    elif hasattr(clause, "getName") and clause.getName() != "field":
        if clause.getName() == "nested":
            return AttributeSelection.from_statement(clause)
        elif clause.getName() == "function":
            return SelectFunction.from_statement(clause)
        else:
            return Value(resolve(clause[0]))
    else:
        return Field(clause[0])

def _finished_callback(self, batch_fut, todo):
    self._running.remove(batch_fut)
    err = batch_fut.get_exception()
    if err is not None:
      tb = batch_fut.get_traceback()
      for (fut, _) in todo:
        if not fut.done():
          fut.set_exception(err, tb)

def config_defaults(
        configurator, config_locations, files=None):
    if files is None:
        files = ['config.yaml', 'config.yml']
    if not isinstance(config_locations, (list, tuple)):
        config_locations = config_locations.split(',')

    env = configurator.registry.settings.get('env', 'dev')

    tmp = []
    for location in config_locations:
        path = _translate_config_path(location)
        current_files = files
        if os.path.isfile(path):
            path, current_files = os.path.split(path)
            current_files = [current_files]

        for config_path in [
                os.path.join(path, f)
                for f in _env_filenames(current_files, env)
        ]:
            if os.path.isfile(config_path):
                tmp.append(config_path)

    config = ConfigManager(files=tmp)

    # we could use this method both for creating and extending.
    # Hence the checks to not override
    if 'config' not in configurator.registry:
        configurator.registry['config'] = config
    else:
        config.merge(configurator.registry['config'])
        configurator.registry['config'] = config

