def custom_operation(dbg, thread_id, frame_id, scope, attrs, style, code_or_file, operation_fn_name):
    expressionValue = getVariable(dbg, thread_id, frame_id, scope, attrs)

    try:
        namespace = {'__name__': '<custom_operation>'}
        if style == "EXECFILE":
            namespace['__file__'] = code_or_file
            execfile(code_or_file, namespace, namespace)
        else:  # style == EXEC
            namespace['__file__'] = '<customOperationCode>'
            Exec(code_or_file, namespace, namespace)

        return str(namespace[operation_fn_name](expressionValue))
    except:
        pydev_log.exception()

def json_diff(json1, json2, key_target, get_just_diff=True, porcelain=False):
    json1 = json_secretary(json1)
    json2 = json_secretary(json2)

    obj1 = traverse_data(json1, key_target)
    obj2 = traverse_data(json2, key_target)

    output = diffcolor(obj1[key_target], obj2[key_target])

    if porcelain:
        return diff(obj1[key_target], obj2[key_target])

    if get_just_diff:
        return output

    obj1[key_target + '_diff'] = output
    obj2[key_target + '_diff'] = output
    return json1, json2, output

