            location, url, _ = south_peer
            self.south.connect(disambiguate_url(url, location))
        if west_peer is not None:
            location, _, url = west_peer
            self.west.connect(disambiguate_url(url, location))

def read_http(self, length):
        if length is None:
            length = len(self)

        if length < 9:
            raise ProtocolError(f'HTTP/2: invalid format', quiet=True)

        _tlen = self._read_unpack(3)
        _type = self._read_unpack(1)
        _flag = self._read_binary(1)
        _rsid = self._read_binary(4)

        if _tlen != length:
            raise ProtocolError(f'HTTP/2: [Type {_type}] invalid format', quiet=True)

        if int(_rsid[0], base=2):
            raise ProtocolError(f'HTTP/2: [Type {_type}] invalid format', quiet=True)

        http = dict(
            length=_tlen,
            type=_HTTP_TYPE.get(_type),
            sid=int(_rsid[1:], base=2),
            packet=self._read_packet(_tlen),
        )

        if http['type'] is None:
            raise ProtocolError(f'HTTP/2: [Type {_type}] invalid format', quiet=True)

        if http['type'] in ('SETTINGS', 'PING') and http['sid'] != 0:
            raise ProtocolError(f'HTTP/2: [Type {_type}] invalid format', quiet=True)

        _http = _HTTP_FUNC[_type](self, _tlen, _type, _flag)
        http.update(_http)

        return http

def process_before_request_hooks(self):

        hooks = []

        if self.resource:
            hooks.extend(self.resource.api.before_all_hooks)
            hooks.extend(self.resource.before_all_hooks)

        hooks.extend(self.before_all_hooks)
        hooks.extend(
            getattr(
                self,
                'before_{method}_hooks'.format(method=self.meth),
                []
            )
        )

        for hook in chain(hooks):
            hook(self)

