def orifice_expansibility(D, Do, P1, P2, k):
    beta = Do/D
    beta2 = beta*beta
    beta4 = beta2*beta2
    return (1.0 - (0.351 + 0.256*beta4 + 0.93*beta4*beta4)*(
            1.0 - (P2/P1)**(1./k)))

