            comp = CPEComponentAnyValue()
        elif (value == CPEComponent2_3_URI.VALUE_NA):
            comp = CPEComponentNotApplicable()
        else:
            comp = CPEComponentNotApplicable()
            try:
                comp = CPEComponent2_3_URI(value, att)
            except ValueError:
                errmsg = "Invalid value of attribute '{0}': {1} ".format(att,
                                                                         value)
                raise ValueError(errmsg)

        return comp

def reward_pool_balances(self):
        if self.reward_balance > 0:
            return self.reward_balance
        else:
            reward_fund = self.steem_instance().get_reward_fund()
            self.reward_balance = Amount(
                reward_fund["reward_balance"]).amount
            self.recent_claims = float(reward_fund["recent_claims"])
            self.base = Amount(
                self.steem_instance(
                ).get_current_median_history_price()["base"]
                ).amount
        return [self.reward_balance, self.recent_claims, self.base]

def transfer(self, from_acct: Account, b58_to_address: str, value: int, payer_acct: Account, gas_limit: int,
                 gas_price: int) -> str:
        func = InvokeFunction('transfer')
        if not isinstance(value, int):
            raise SDKException(ErrorCode.param_err('the data type of value should be int.'))
        if value < 0:
            raise SDKException(ErrorCode.param_err('the value should be equal or great than 0.'))
        if not isinstance(from_acct, Account):
            raise SDKException(ErrorCode.param_err('the data type of from_acct should be Account.'))
        Oep4.__b58_address_check(b58_to_address)
        from_address = from_acct.get_address().to_bytes()
        to_address = Address.b58decode(b58_to_address).to_bytes()
        func.set_params_value(from_address, to_address, value)
        tx_hash = self.__sdk.get_network().send_neo_vm_transaction(self.__hex_contract_address, from_acct, payer_acct,
                                                                   gas_limit, gas_price, func, False)
        return tx_hash

def _load_genetic_map(filename):
        try:
            genetic_map = {}

            with tarfile.open(filename, "r") as tar:
                # http://stackoverflow.com/a/2018576
                for member in tar.getmembers():
                    if "genetic_map" in member.name:
                        df = pd.read_csv(tar.extractfile(member), sep="\t")
                        df = df.rename(
                            columns={
                                "Position(bp)": "pos",
                                "Rate(cM/Mb)": "rate",
                                "Map(cM)": "map",
                            }
                        )
                        del df["Chromosome"]
                        start_pos = member.name.index("chr") + 3
                        end_pos = member.name.index(".")
                        genetic_map[member.name[start_pos:end_pos]] = df

            # X chrom consists of X PAR regions and X non-PAR region
            genetic_map["X"] = pd.concat(
                [genetic_map["X_par1"], genetic_map["X"], genetic_map["X_par2"]]
            )
            del genetic_map["X_par1"]
            del genetic_map["X_par2"]

            return genetic_map
        except Exception as err:
            print(err)
            return None

def _find_block(starts, ends, cur_block, rec_num):   # @NoSelf
        total = len(starts)
        if (cur_block == -1):
            cur_block = 0
        for x in range(cur_block, total):
            if (starts[x] <= rec_num and ends[x] >= rec_num):
                return x, x
            if (starts[x] > rec_num):
                break
        return -1, x-1

