def search_all(self, queries, audio_basename=None, case_sensitive=False,
                   subsequence=False, supersequence=False, timing_error=0.0,
                   anagram=False, missing_word_tolerance=0):

        search_gen_rest_of_kwargs = {
            "audio_basename": audio_basename,
            "case_sensitive": case_sensitive,
            "subsequence": subsequence,
            "supersequence": supersequence,
            "timing_error": timing_error,
            "anagram": anagram,
            "missing_word_tolerance": missing_word_tolerance}

        if not isinstance(queries, (list, str)):
            raise TypeError("Invalid query type.")
        if type(queries) is not list:
            queries = [queries]
        search_results = _PrettyDefaultDict(lambda: _PrettyDefaultDict(list))
        for query in queries:
            search_gen = self.search_gen(query=query,
                                         **search_gen_rest_of_kwargs)
            for search_result in search_gen:
                search_results[query][
                    search_result["File Name"]].append(search_result["Result"])
        return search_results

def email_generator(names=None, domains=None, unique=False):
    if names is None:
        names = [name.encode('ascii', 'ignore').lower().replace(b' ', b'')
                 for name in ENGLISH_MONARCHS]
    if domains is None:
        # Assign the default domain list when no specific domains are provided by the caller.
        domains = DOMAINS

    if unique:
        uniquifyer = lambda: str(next(_unique_counter))
    else:
        uniquifyer = lambda: ''

    while True:
        yield '{0}{1}@{2}'.format(
            random.choice(names), uniquifyer(), random.choice(domains))

def insert_comment(event):
    buff = event.current_buffer

    # Transform all lines.
    if event.arg != 1:
        def change(line):
            return line[1:] if line.startswith('#') else line
    else:
        def change(line):
            return '#' + line

    buff.document = Document(
        text='\n'.join(map(change, buff.text.splitlines())),
        cursor_position=0)

    # Accept input.
    buff.accept_action.validate_and_handle(event.cli, buff)

def com_google_fonts_check_wght_valid_range(ttFont):

  Failed = False
  for instance in ttFont['fvar'].instances:
    if 'wght' in instance.coordinates:
      value = instance.coordinates['wght']
      if value < 1 or value > 1000:
        Failed = True
        yield FAIL, (f"Found a bad wght coordinate with value '{value}'"
                      " outside of the valid range from 1 to 1000.") 
        break

  if not Failed:
    yield PASS, ("OK")

