def parse_response(self, response):
        try:
            for header in response.getheader("set-cookie").split(", "):
                # filter 'expire' information
                if not header.startswith("D"):
                    continue
                cookie = header.split(";", 1)[0]
                cookieKey, cookieValue = cookie.split("=", 1)
                self._cookies[cookieKey] = cookieValue
        finally:
            return Transport.parse_response(self, response)

def wait(self, pattern, seconds=None):
        if isinstance(pattern, (int, float)):
            if pattern == FOREVER:
                while True:
                    time.sleep(1) # Infinite loop
            time.sleep(pattern)
            return None

        if seconds is None:
            seconds = self.autoWaitTimeout

        findFailedRetry = True
        timeout = time.time() + seconds
        while findFailedRetry:
            while True:
                match = self.exists(pattern)
                if match:
                    return match
                if time.time() >= timeout:
                    break
            path = pattern.path if isinstance(pattern, Pattern) else pattern
            findFailedRetry = self._raiseFindFailed("Could not find pattern '{}'".format(path))
            if findFailedRetry:
                time.sleep(self._repeatWaitTime)
        return None

