def tagged_projects(
            self,
            tag):
        self.refresh
        projectList = []
        tag = tag.replace("@", "").lower()
        for p in self.projects:
            for aTag in p.tags:
                if "(" not in tag:
                    aTag = aTag.split("(")[0]
                if aTag.lower() == tag:
                    projectList.append(p)
                    break

            subProjects = p.tagged_projects(tag)
            projectList += subProjects

        return projectList

def findattr(self, name, resolved=True):
        name = '@%s' % name
        parent = self.top().resolved
        if parent is None:
            result, ancestry = self.query(name, node)
        else:
            result, ancestry = self.getchild(name, parent)
        if result is None:
            return result
        if resolved:
            result = result.resolve()
        return result

def _draw_ascii_graph(self, field):
        row_strings = []
        for y in range(len(field[0])):
            row = ''
            for x in range(len(field)):
                row += field[x][y]
            row_strings.insert(0, row)
        graph_string = '\n'.join(row_strings)
        return graph_string

