def create_session(self, lock_type=library.LockType.shared,
                       session=None):
        if session is None:
            session = library.ISession()
        # NOTE: The following hack handles the issue of unknown machine state.
        #       This occurs most frequently when a machine is powered off and
        #       in spite waiting for the completion event to end, the state of
        #       machine still raises the following Error:
        #          virtualbox.library.VBoxErrorVmError: 0x80bb0003 (Failed to \
        #          get a console object from the direct session (Unknown \
        #          Status 0x80BB0002))
        error = None
        for _ in range(10):
            try:
                self.lock_machine(session, lock_type)
            except Exception as exc:
                error = exc
                time.sleep(1)
                continue
            else:
                break
        else:
            if error is not None:
                raise Exception("Failed to create clone - %s" % error)
        return session

def connect_with_retry(self) -> None:
        if self.is_connected():
            log.debug('Already connected to the Slack API')
            return

        for retry in range(1, self.retries + 1):
            self.connect()
            if self.is_connected():
                log.debug('Connected to the Slack API')
                return
            else:
                interval = self.backoff(retry)
                log.debug("Waiting %.3fs before retrying", interval)
                time.sleep(interval)

        raise FailedConnection('Failed to connect to the Slack API')

def _populate_cache(self):
        self.cache = autovivitree()

        for path, dirs, objects in self.walk(return_classname=True,
                                             treat_dirs_as_objs=True):
            b = self.cache
            for d in ['']+path.split('/'):
                b = b[d]
                obj = [(path, o) for o in objects]
                if 'obj' in b:
                    b['obj'] += obj
                else:
                    b['obj'] = obj

def patch(self, deviceId):
        try:
            device = self.recordingDevices.get(deviceId)
            if device.status == RecordingDeviceStatus.INITIALISED:
                errors = self._handlePatch(device)
                if len(errors) == 0:
                    return device, 200
                else:
                    return device, 500
            else:
                return device, 400
        finally:
            logger.info("Sending adhoc heartbeat on device state update")
            self.heartbeater.sendHeartbeat()

def find_video_file(rtdc_dataset):
        video = None
        if rtdc_dataset._fdir.exists():
            # Cell images (video)
            videos = [v.name for v in rtdc_dataset._fdir.rglob("*.avi")]
            # Filter videos according to measurement number
            meas_id = rtdc_dataset._mid
            videos = [v for v in videos if v.split("_")[0] == meas_id]
            videos.sort()
            if len(videos) != 0:
                # Defaults to first avi file
                video = videos[0]
                # g/q video file names. q comes first.
                for v in videos:
                    if v.endswith("imag.avi"):
                        video = v
                        break
                    # add this here, because fRT-DC measurements also contain
                    # videos ..._proc.avi
                    elif v.endswith("imaq.avi"):
                        video = v
                        break
        if video is None:
            return None
        else:
            return rtdc_dataset._fdir / video

