        if mimedata.hasUrls():
            urls = [str(url.toLocalFile()) for url in mimedata.urls() if url.toLocalFile()]
        else:
            urls = []
        # accept event if drag text is a file URL
        if urls:
            ev.acceptProposedAction()
            return urls
        else:
            ev.ignore()
            return None

