def _clamp_value(value, minimum, maximum):
    if maximum < minimum:
        raise ValueError
    if value < minimum:
        return minimum
    elif value > maximum:
        return maximum
    else:
        return value

def _compare_variables_function_generator(
        method_string, aggregation_func):
    def comparison_function(self, other):
        """Wrapper for comparison functions for class |Variable|."""
        if self is other:
            return method_string in ('__eq__', '__le__', '__ge__')
        method = getattr(self.value, method_string)
        try:
            if hasattr(type(other), '__hydpy__get_value__'):
                other = other.__hydpy__get_value__()
            result = method(other)
            if result is NotImplemented:
                return result
            return aggregation_func(result)
        except BaseException:
            objecttools.augment_excmessage(
                f'While trying to compare variable '
                f'{objecttools.elementphrase(self)} with object '
                f'`{other}` of type `{objecttools.classname(other)}`')
    return comparison_function

def build_config(ctx, target, config_path, c, extra_path, ignore, verbose, silent, debug):
    tmp = LintConfigBuilder()
    try:
        # Config precedence:
        # First, load default config or config from configfile
        if config_path:
            tmp.set_from_config_file(config_path)
        elif os.path.exists(DEFAULT_CONFIG_FILE):
            tmp.set_from_config_file(DEFAULT_CONFIG_FILE)

        # Then process any commandline configuration flags
        tmp.set_config_from_string_list(c)

        # Finally, overwrite with any convenience commandline flags
        if ignore:
            tmp.set_option('general', 'ignore', ignore)
        if silent:
            tmp.set_option('general', 'verbosity', 0)
        elif verbose > 0:
            tmp.set_option('general', 'verbosity', verbose)

        if extra_path:
            tmp.set_option('general', 'extra-path', extra_path)

        if target:
            tmp.set_option('general', 'target', target)

        if debug:
            tmp.set_option('general', 'debug', debug)

        config = tmp.build()

        return config, tmp
    except LintConfigError as e:
        click.echo(u"Config Error: {0}".format(ustr(e)))
    ctx.exit(CONFIG_ERROR_CODE)

