        self._validate_endpoint_protocol(protocol)

        url = "/notification/v1/endpoint?subscriber_id={}&protocol={}".format(
            subscriber_id, protocol)

        response = NWS_DAO().getURL(url, self._read_headers)

        if response.status != 200:
