def compute_fd_hessian(fun, x0, epsilon, anagrad=True):
    N = len(x0)

    def compute_gradient(x):
        if anagrad:
            return fun(x, do_gradient=True)[1]
        else:
            gradient = np.zeros(N, float)
            for i in range(N):
                xh = x.copy()
                xh[i] += 0.5*epsilon
                xl = x.copy()
                xl[i] -= 0.5*epsilon
                gradient[i] = (fun(xh)-fun(xl))/epsilon
            return gradient

    hessian = np.zeros((N,N), float)
    for i in range(N):
        xh = x0.copy()
        xh[i] += 0.5*epsilon
        xl = x0.copy()
        xl[i] -= 0.5*epsilon
        hessian[i] = (compute_gradient(xh) - compute_gradient(xl))/epsilon

    return 0.5*(hessian + hessian.transpose())

def is_taps_aff(self):

        request = requests.get('https://www.taps-aff.co.uk/api/%s' % self.location)
        if request.status_code == 200:
            try:
                taps = request.json()['taps']['status']
                if taps == 'aff':
                    return True
                elif taps == 'oan':
                    return False
                else:
                    raise RuntimeError("Unexpected taps value: %s" % taps)
            except ValueError:
                raise RuntimeError("Unexpected response from service")
        else:
            raise IOError("Failure downloading from Api")

