def update_path(self):
        if WINDOWS:
            return self.add_to_windows_path()

        # Updating any profile we can on UNIX systems
        export_string = self.get_export_string()

        addition = "\n{}\n".format(export_string)

        updated = []
        profiles = self.get_unix_profiles()
        for profile in profiles:
            if not os.path.exists(profile):
                continue

            with open(profile, "r") as f:
                content = f.read()

            if addition not in content:
                with open(profile, "a") as f:
                    f.write(addition)

                updated.append(os.path.relpath(profile, HOME))

def treeWalk(self, **kwargs):

            str_recursePath = ''
            str_startPath   = '/'
            f               = None
            ret             = {}

            for key,val in kwargs.items():
                if key == 'startPath':  str_startPath   = val
                if key == 'f':          f               = val

            # print 'processing node: %s' % str_startPath
            if self.cd(str_startPath)['status']:
                ret = f(str_startPath, **kwargs)
                if ret['status']:
                    for node in self.lstr_lsnode(str_startPath):
                        if str_startPath == '/': str_recursePath = "/%s" % node
                        else: str_recursePath = '%s/%s' % (str_startPath, node)
                        self.treeWalk(f = f, startPath = str_recursePath)
            return ret

