        raise IllegalState()

def update_asset(self, asset_form=None):
        if asset_form is None:
            raise NullArgument()
        if not isinstance(asset_form, abc_repository_objects.AssetForm):
            raise InvalidArgument('argument type is not an AssetForm')
        if not asset_form.is_for_update():
            raise InvalidArgument('form is for create only, not update')
        try:
            if self._forms[asset_form.get_id().get_identifier()] == UPDATED:
                raise IllegalState('form already used in an update transaction')
        except KeyError:
            raise Unsupported('form did not originate from this session')
        if not asset_form.is_valid():
            raise InvalidArgument('one or more of the form elements is invalid')

        url_path = construct_url('assets',
                                 bank_id=self._catalog_idstr)
        try:
            result = self._put_request(url_path, asset_form._my_map)
        except Exception:
            raise  # OperationFailed()
        self._forms[asset_form.get_id().get_identifier()] = UPDATED
        return objects.Asset(result)

def specs_to_ir(specs, version='0.1b1', debug=False, route_whitelist_filter=None):

    parser_factory = ParserFactory(debug=debug)
    partial_asts = []

    for path, text in specs:
        logger.info('Parsing spec %s', path)
        parser = parser_factory.get_parser()
        if debug:
            parser.test_lexing(text)

        partial_ast = parser.parse(text, path)

        if parser.got_errors_parsing():
            # TODO(kelkabany): Show more than one error at a time.
            msg, lineno, path = parser.get_errors()[0]
            raise InvalidSpec(msg, lineno, path)
        elif len(partial_ast) == 0:
            logger.info('Empty spec: %s', path)
        else:
            partial_asts.append(partial_ast)

    return IRGenerator(partial_asts, version, debug=debug,
                       route_whitelist_filter=route_whitelist_filter).generate_IR()

def get_version(module):
    version_names = ["__version__", "get_version", "version"]
    version_names.extend([name.upper() for name in version_names])
    for name in version_names:
        # Attempt to retrieve the version attribute from the module for the current name.
        try:
            version = getattr(module, name)
        except AttributeError:
            continue
        if callable(version):
            version = version()
        try:
            version = ".".join([str(i) for i in version.__iter__()])
        except AttributeError:
            pass
        return version

