    return cls._deadline_until(file_waiter, action_msg, timeout=timeout)

def branchScale(self):
        bs = -(self.prx * scipy.diagonal(self.Prxy, axis1=1, axis2=2)
                ).sum() * self.mu / float(self.nsites)
        assert bs > 0
        return bs

