def values(cls, dataset, dim, expanded=True, flat=True, compute=True):
        dim = dataset.get_dimension(dim, strict=True)
        if dim in dataset.vdims:
            coord_names = [c.name() for c in dataset.data.dim_coords]
            data = dataset.data.copy().data
            data = cls.canonicalize(dataset, data, coord_names)
            return data.T.flatten() if flat else data
        elif expanded:
            data = cls.coords(dataset, dim.name, expanded=True)
            return data.T.flatten() if flat else data
        else:
            return cls.coords(dataset, dim.name, ordered=True)

def PC_PI_calc(P, TOP, POP):
    try:
        result = 0
        for i in P.keys():
            result += ((P[i] + TOP[i]) / (2 * POP[i]))**2
        return result
    except Exception:
        return "None"

def return_net(word,word_net,depth=1):
    if depth<1: raise Exception(TAG+"Degree value error.range(1,~)")
    if depth==1:
        return list(word_net[word].frwrd_links)
    elif depth>1:
        words  = word_net[word].frwrd_links
        res=[]
        for w in words: res.extend(return_net(w,word_net,depth=depth-1))
        return list(set(res))

