def get_active_pitch_range(self):
        if self.pianoroll.shape[1] < 1:
            raise ValueError("Cannot compute the active pitch range for an "
                             "empty pianoroll")
        lowest = 0
        highest = 127
        while lowest < highest:
            if np.any(self.pianoroll[:, lowest]):
                break
            lowest += 1
        if lowest == highest:
            raise ValueError("Cannot compute the active pitch range for an "
                             "empty pianoroll")
        while not np.any(self.pianoroll[:, highest]):
            highest -= 1

        return lowest, highest

def add_info(self, entry):
        entry = entry[8:-1]
        tmp = entry.split(',')
        if len(tmp) < 4:
            return False
        for v in tmp:
            key, value = v.split('=', 1)
            if key == 'ID':
                self.info[value] = {}
                id_ = value
            elif key == 'Number':
                if value == 'A' or value == 'G':
                    value = -1
                self.info[id_]['num_entries'] = value
            elif key == 'Type':
                self.info[id_]['type'] = self.type_map[value]
            elif key == 'Description':
                self.info[id_]['description'] = value
                if len(tmp) > 4:
                    self.info[id_]['description'] += '; '.join(tmp[4:])
                break
        return True

