def impulse(dur=None, one=1., zero=0.):
  if dur is None or (isinf(dur) and dur > 0):
    yield one
    while True:
      yield zero
  elif dur >= .5:
    num_samples = int(dur - .5)
    yield one
    for x in xrange(num_samples):
      yield zero

def __call(self, uri, params=None, method="get"):
        try:
            resp = self.__get_response(uri, params, method, False)
            rjson = resp.json(**self.json_options)
            assert resp.ok
        except AssertionError:
            msg = "OCode-{}: {}".format(resp.status_code, rjson["message"])
            raise BadRequest(msg)
        except Exception as e:
            msg = "Bad response: {}".format(e)
            log.error(msg, exc_info=True)
            raise BadRequest(msg)
        else:
            return rjson

