def preprocess_belscript(lines):

    set_flag = False
    for line in lines:
        if set_flag is False and re.match("SET", line):
            set_flag = True
            set_line = [line.rstrip()]
        # SET following SET
        elif set_flag and re.match("SET", line):
            yield f"{' '.join(set_line)}\n"
            set_line = [line.rstrip()]
        # Blank line following SET yields single line SET
        elif set_flag and re.match("\s+$", line):
            yield f"{' '.join(set_line)}\n"
            yield line
            set_flag = False

        # Append second, third, ... lines to SET
        elif set_flag:
            set_line.append(line.rstrip())
        else:
            yield line

def combineAB(self):
        v4definition_meter = V4Meter()
        v4definition_meter.makeAB()
        defv4 = v4definition_meter.getReadBuffer()

        v3definition_meter = V3Meter()
        v3definition_meter.makeReturnFormat()
        defv3 = v3definition_meter.getReadBuffer()

        for fld in defv3:
            if fld not in self.m_all_fields:
                compare_fld = fld.upper()
                if not "RESERVED" in compare_fld and not "CRC" in compare_fld:
                    self.m_all_fields[fld] = defv3[fld]

        for fld in defv4:
            if fld not in self.m_all_fields:
                compare_fld = fld.upper()
                if not "RESERVED" in compare_fld and not "CRC" in compare_fld:
                    self.m_all_fields[fld] = defv4[fld]
        pass

def runner(parallel, config):
    def run_parallel(fn_name, items):
        items = [x for x in items if x is not None]
        if len(items) == 0:
            return []
        items = diagnostics.track_parallel(items, fn_name)
        fn, fn_name = (fn_name, fn_name.__name__) if callable(fn_name) else (get_fn(fn_name, parallel), fn_name)
        logger.info("multiprocessing: %s" % fn_name)
        if "wrapper" in parallel:
            wrap_parallel = {k: v for k, v in parallel.items() if k in set(["fresources", "checkpointed"])}
            items = [[fn_name] + parallel.get("wrapper_args", []) + [wrap_parallel] + list(x) for x in items]
        return run_multicore(fn, items, config, parallel=parallel)
    return run_parallel

