def open(s3_url, mode='r', s3_connection=None, **kwargs):

    connection = s3_connection or boto.connect_s3(**kwargs)

    bucket_name, key_name = url_split(s3_url)

    try:
        bucket = connection.get_bucket(bucket_name)
    except boto.exception.S3ResponseError:
        raise BucketNotFoundError('Bucket "%s" was not found.' % bucket_name)

    f = NamedTemporaryFile()
    try:
        if 'w' in mode.lower():
            s3_key = bucket.new_key(key_name)

            yield f
            f.seek(0)
            s3_key.set_contents_from_file(f)
        else:
            s3_key = bucket.get_key(key_name)

            if not s3_key:
                raise KeyNotFoundError('Key "%s" was not found.' % s3_url)

            s3_key.get_file(f)
            f.seek(0)
            yield f
    finally:
        f.close()

def _apply_mask(self,p,mat):
        mask = p.mask
        ms=p.mask_shape
        if ms is not None:
            mask = ms(x=p.x+p.size*(ms.x*np.cos(p.orientation)-ms.y*np.sin(p.orientation)),
                      y=p.y+p.size*(ms.x*np.sin(p.orientation)+ms.y*np.cos(p.orientation)),
                      orientation=ms.orientation+p.orientation,size=ms.size*p.size,
                      bounds=p.bounds,ydensity=p.ydensity,xdensity=p.xdensity)
        if mask is not None:
            mat*=mask

