            step = self.steps.current
        form_list = self.get_form_list()
        keys = list(form_list.keys())
        key = keys.index(step) + 1
        for next_step in keys[key:]:
            if self.is_step_visible(next_step):
                return next_step
        return None

def exportpub(self, format="PEM"):
        bio = Membio()
        if format == "PEM":
            retcode = libcrypto.PEM_write_bio_PUBKEY(bio.bio, self.key)
        else:
            retcode = libcrypto.i2d_PUBKEY_bio(bio.bio, self.key)
        if retcode == 0:
            raise PKeyError("error serializing public key")
        return str(bio)

def set_current_limit(self, channel, value, unit='A'):
        dac_offset = self._ch_cal[channel]['DACI']['offset']
        dac_gain = self._ch_cal[channel]['DACI']['gain']

        if unit == 'raw':
            value = value
        elif unit == 'A':
            value = int((value - dac_offset) / dac_gain)
        elif unit == 'mA':
            value = int((value / 1000 - dac_offset) / dac_gain)
        else:
            raise TypeError("Invalid unit type.")

        DacMax5380._set_dac_value(self, channel, value)

