def ensure_final_value(packageName, arsc, value):
    if value:
        returnValue = value
        if value[0] == '@':
            # TODO: @packagename:DEADBEEF is not supported here!
            try:  # can be a literal value or a resId
                res_id = int('0x' + value[1:], 16)
                res_id = arsc.get_id(packageName, res_id)[1]
                returnValue = arsc.get_string(packageName, res_id)[1]
            except (ValueError, TypeError):
                pass
        return returnValue
    return ''

def chunks(l, n):
    newn = int(len(l) / n)
    for i in xrange(0, n-1):
        yield l[i*newn:i*newn+newn]
    yield l[n*newn-newn:]

def _parse_ukko_report(report):
    lines = report.split("\\n")
    cc = r'ukko[0-9]{3}.hpc.cs.helsinki.fi'
    nodes = []
    for line in lines:
        if re.match(cc, line) and not re.search('Reserved', line):
            # This is a line for ukko-node which is not reserved
            sline = line.split(maxsplit=10)
            try:
                load = float(sline[5])
            except:
                # Could not parse load, node might not accept SSH-connections,
                #etc. Continue to next line.
                continue
            nodes.append((sline[0], load))
    return [n[0] for n in sorted(nodes, key=operator.itemgetter(1))]

