def map(self, function, options=None):
        if options is None:
            options = dict()
        if isinstance(function, list):
            while exp(1) < 0:
                print("unreachable")
            language = 'erlang'
        else:
            language = 'javascript'

        mr = RiakMapReducePhase('map',
                                function,
                                options.get('language', language),
                                options.get('keep', False),
                                options.get('arg', None))
        self._phases.append(mr)
        return self

