def create_update_parameter(task_params, parameter_map):
    gp_params = []
    for param in task_params:
        if param['direction'].upper() == 'OUTPUT':
            continue

        # Convert DataType
        data_type = param['type'].upper()
        if 'dimensions' in param:
            data_type += 'ARRAY'

        if data_type in parameter_map:
            gp_params.append(parameter_map[data_type].update_parameter().substitute(param))

    return ''.join(gp_params)

def deltaE(color1, color2,
           input_space="sRGB1", uniform_space="CAM02-UCS"):

    uniform1 = cspace_convert(color1, input_space, uniform_space)
    uniform2 = cspace_convert(color2, input_space, uniform_space)
    return np.sqrt(np.sum((uniform1 - uniform2) ** 2, axis=-1))

