def _dispatch(self, cmd, args):
        if cmd in self.clis:
            extern_cmd, args = args[0], args[1:]
            self.clis[cmd]._dispatch(extern_cmd, args)
        else:
            if cmd in self.cmds:
                callback, parser = self.cmds[cmd]
                try:
                    p_args = parser.parse_args(args)
                except SystemExit:
                    return
                callback(**dict(filter(lambda p:p[1] != None, p_args._get_kwargs())))
            else:
                self._invalid_cmd(command=cmd)

def _expand_str_alias(path_cfg, alias_dict, overriding_kargs):

    # e.g.,
    # path_cfg = 'var_cut'

    new_path_cfg = alias_dict[path_cfg]
    # e.g., ('ev : {low} <= ev.var[0] < {high}', {'low': 10, 'high': 200})

    new_overriding_kargs = dict(alias=path_cfg)
    # e.g., {'alias': 'var_cut'}

    new_overriding_kargs.update(overriding_kargs)
    # e.g., {'alias': 'var_cut', 'name': 'var_cut25', 'low': 25}

    return expand_path_cfg(new_path_cfg, alias_dict,new_overriding_kargs)

def get_rotation_and_scale(header, skew_threshold=0.001):
    ((xrot, yrot),
     (cdelt1, cdelt2)) = get_xy_rotation_and_scale(header)

    if math.fabs(xrot) - math.fabs(yrot) > skew_threshold:
        raise ValueError("Skew detected: xrot=%.4f yrot=%.4f" % (
            xrot, yrot))
    rot = yrot

    lonpole = float(header.get('LONPOLE', 180.0))
    if lonpole != 180.0:
        rot += 180.0 - lonpole

    return (rot, cdelt1, cdelt2)

