def _interpolate_df_col(df, x=None, y=None, new_x=None, dx=10.0,
                        number_of_points=None, direction=1, **kwargs):

        if x is None:
            x = df.columns[0]
        if y is None:
            y = df.columns[1]

        xs = df[x].values
        ys = df[y].values

        if direction > 0:
            x_min = xs.min()
            x_max = xs.max()
        else:
            x_max = xs.min()
            x_min = xs.max()
            dx = -dx

        bounds_error = kwargs.pop("bounds_error", False)
        f = interpolate.interp1d(xs, ys, bounds_error=bounds_error, **kwargs)
        if new_x is None:
            if number_of_points:
                new_x = np.linspace(x_min, x_max, number_of_points)
            else:
                new_x = np.arange(x_min, x_max, dx)

        new_y = f(new_x)

        new_df = pd.DataFrame(
            {x: new_x, y: new_y}
        )

        return new_df

def diff_with_models(self):
        missing_from_conf = defaultdict(set)

        for model in get_models():
            db_tables_and_columns = get_db_tables_and_columns_of_model(model)
            for (table_name, columns) in db_tables_and_columns.items():
                model_strategy = self.strategy.get(table_name)
                for column in columns:
                    if not model_strategy or column not in model_strategy:
                        missing_from_conf[table_name].add(column)
        return missing_from_conf

