def create_span(unirange, is_bytes=False):

    if len(unirange) < 2:
        unirange.append(unirange[0])
    if is_bytes:
        if unirange[0] > MAXASCII:
            return None
        if unirange[1] > MAXASCII:
            unirange[1] = MAXASCII
    return [x for x in range(unirange[0], unirange[1] + 1)]

def axis_names_without(self, axis):
        if self.axis_names is None:
            return None
        return itemgetter(*self.other_axes(axis))(self.axis_names)

def _diff_signatures(self, type_):
        missing = []
        mistyped = {}
        mismatched = {}
        for name, iface_sig in self._signatures.items():
            try:
                # Don't invoke the descriptor protocol here so that we get
                # staticmethod/classmethod/property objects instead of the
                # functions they wrap.
                f = static_get_type_attr(type_, name)
            except AttributeError:
                missing.append(name)
                continue

            impl_sig = TypedSignature(f)

            if not issubclass(impl_sig.type, iface_sig.type):
                mistyped[name] = impl_sig.type

            if not compatible(impl_sig.signature, iface_sig.signature):
                mismatched[name] = impl_sig

        return missing, mistyped, mismatched

def _check_daylong(tr):
    if len(np.nonzero(tr.data)[0]) < 0.5 * len(tr.data):
        qual = False
    else:
        qual = True
    return qual

def factory(cls, endpoint, timeout, *args, **kwargs):
        start = time.time()
        kwargs['connect_timeout'] = timeout
        conn = cls(endpoint, *args, **kwargs)
        elapsed = time.time() - start
        conn.connected_event.wait(timeout - elapsed)
        if conn.last_error:
            if conn.is_unsupported_proto_version:
                raise ProtocolVersionUnsupported(endpoint, conn.protocol_version)
            raise conn.last_error
        elif not conn.connected_event.is_set():
            conn.close()
            raise OperationTimedOut("Timed out creating connection (%s seconds)" % timeout)
        else:
            return conn

def independent_get_coefficients(coef, rhouv, s, i, j, k, u, v,
                                 unfolding, matrix_form):
    if matrix_form:
        coef = -coef
    Mu = unfolding.Mu
    mu = Mu(s, i, j)
    rhouv_isconjugated = False
    if s == 1:
        coef_list = [[mu, None, -im(coef), matrix_form, rhouv_isconjugated]]
    elif s == -1:
        coef_list = [[mu, None, re(coef), matrix_form, rhouv_isconjugated]]
    else:
        coef_list = [[mu, None, coef, matrix_form, rhouv_isconjugated]]
    return coef_list

def body_class_tag(context):
    request = context.get("request")
    if not hasattr(request, "ROUTE"):
        return ""

    css_classes = []

    namespace = request.ROUTE["namespace"]
    if namespace:
        namespace = RE_CLEAN_CSS_NAME.sub("-", namespace.lower())
        css_classes.append("ns-{}".format(namespace))

    view = request.ROUTE["url_name"]  # Use ``url_name`` as ``view_name`` includes the namespace.
    if view:
        view = RE_CLEAN_CSS_NAME.sub("-", view.lower())
        css_classes.append("vw-{}".format(view))

    return " ".join(css_classes)

def delta_ps(prev, curr, counters):
    counter = get_counter(counters)

    pv = getattr(prev, counter)
    cv = getattr(curr, counter)
    return minus(cv, pv)

def _remap_pair(self, operation, src, dst, *args, **kw):
        return (
            self._remap_input(operation + '-from', src, *args, **kw),
            self._remap_input(operation + '-to', dst, *args, **kw)
        )

def fromOctetString(cls, value, internalFormat=False, prepend=None, padding=0):
        value = SizedInteger(integer.from_bytes(value) >> padding).setBitLength(len(value) * 8 - padding)

        if prepend is not None:
            value = SizedInteger(
                (SizedInteger(prepend) << len(value)) | value
            ).setBitLength(len(prepend) + len(value))

        if not internalFormat:
            value = cls(value)

        return value

def validate(self, value):
