def do_bo(self, arg):
        token_list = self.split_tokens(arg, 1, 2)
        pid, tid, address, size = self.input_breakpoint(token_list)
        debug = self.debug
        found = False
        if size is None:
            if tid is not None:
                if debug.has_hardware_breakpoint(tid, address):
                    debug.enable_one_shot_hardware_breakpoint(tid, address)
                    found = True
            if pid is not None:
                if debug.has_code_breakpoint(pid, address):
                    debug.enable_one_shot_code_breakpoint(pid, address)
                    found = True
        else:
            if debug.has_page_breakpoint(pid, address):
                debug.enable_one_shot_page_breakpoint(pid, address)
                found = True
        if not found:
            print("Error: breakpoint not found.")

def do_execute(self):
        result = None
        teeoff = True
        cond = self.storagehandler.expand(str(self.resolve_option("condition")))
        if len(cond) > 0:
            teeoff = bool(eval(cond))
        if teeoff:
            self.first_active.input = self.input
            result = self._director.execute()
        if result is None:
            self._output.append(self.input)
        return result

