def out_of_bounds(self, index):
        if type(index) is int:
            return self.int_out_of_bounds(index)

        elif type(index) is slice:
            return self.slice_out_of_bounds(index)

        elif type(index) is tuple:

            local_index = []

            for k, item in enumerate(index):

                if type(item) is slice:
                    temp_index = self.slice_out_of_bounds(item, k)

                elif type(item) is int:
                    temp_index = self.int_out_of_bounds(item, k)
                # FIXME: will fail if item is no int or slice!
                if temp_index is None:
                    return temp_index

                local_index.append(temp_index)

            return tuple(local_index)

def find_motif34(m, n=None):
    from scipy import io
    import os
    fname = os.path.join(os.path.dirname(__file__), motiflib)
    z = (0,)
    if n == 3:
        mot = io.loadmat(fname)
        m3 = mot['m3']
        id3 = mot['id3'].squeeze()
        ix, = np.where(id3 == m)
        M = np.zeros((3, 3, len(ix)))
        for i, ind in enumerate(ix):
            M[:, :, i] = np.reshape(np.concatenate(
                (z, m3[ind, 0:3], z, m3[ind, 3:6], z)), (3, 3))
    elif n == 4:
        mot = io.loadmat(fname)
        m4 = mot['m4']
        id4 = mot['id4'].squeeze()
        ix, = np.where(id4 == m)
        M = np.zeros((4, 4, len(ix)))
        for i, ind in enumerate(ix):
            M[:, :, i] = np.reshape(np.concatenate(
                (z, m4[ind, 0:4], z, m4[ind, 4:8], z, m4[ind, 8:12], z)), (4, 4))
    elif n is None:
        try:
            m = np.array(m)
        except TypeError:
            raise BCTParamError('motif matrix must be an array-like')
        if m.shape[0] == 3:
            M, = np.where(motif3struct_bin(m))
        elif m.shape[0] == 4:
            M, = np.where(motif4struct_bin(m))
        else:
            raise BCTParamError('motif matrix must be 3x3 or 4x4')
    else:
        raise BCTParamError('Invalid motif class, must be 3, 4, or None')

    return M

def noise_power_spectrum(data, ground_truth, radial=False,
                         radial_binning_factor=2.0):
    try:
        space = data.space
        assert isinstance(space, odl.DiscreteLp)
    except (AttributeError, AssertionError):
        data = np.asarray(data)
        space = odl.uniform_discr(
            [0] * data.ndim, data.shape, data.shape, data.dtype
        )
        data = space.element(data)

    ft = odl.trafos.FourierTransform(space, halfcomplex=False)
    nps = np.abs(ft(data - ground_truth)).real ** 2

    if radial:
        return spherical_sum(nps, binning_factor=radial_binning_factor)
    else:
        return nps

def check_shell_redirection(cmd):
    curly_brackets = True
    while curly_brackets:
        SRE_match_obj = re.search(r'\{(.*?)}',cmd)
        if SRE_match_obj is not None:
            cmd = cmd[:SRE_match_obj.start()] + cmd[(SRE_match_obj.end()+1):]
            if re.search(r'\{(.*?)}',cmd) is None:
                curly_brackets = False
        else:
            curly_brackets = False
    return ">" in cmd

def overlay(array1, array2, alpha=0.5):
    if alpha < 0. or alpha > 1.:
        raise ValueError("`alpha` needs to be between [0, 1]")
    if array1.shape != array2.shape:
        raise ValueError('`array1` and `array2` must have the same shapes')

    return (array1 * alpha + array2 * (1. - alpha)).astype(array1.dtype)

