def _fmt(self, tag, msg):
        msg = msg or '<unset>'
        msg = str(msg)
        msg = msg.strip()
        if not msg:
            return
        if len(msg) > 2048:
            msg = msg[:1024] + '...'
        if msg.count('\n') <= 1:
            return '{}: {}\n'.format(tag, msg.strip())
        else:
            return '{}:\n  {}\n'.format(tag, msg.replace('\n', '\n  ').strip())

