def _fill_parameters(self):
        self._parameters = self._config.get('parameters', {})
        self._fill_defaults()

        for k in self._parameters.keys():
            try:
                if self._parameters[k].startswith(self.SSM) and self._parameters[k].endswith(']'):
                    parts = self._parameters[k].split(':')
                    tmp = parts[1].replace(']', '')
                    val = self._get_ssm_parameter(tmp)
                    if val:
                        self._parameters[k] = val
                    else:
                        logging.error('SSM parameter {} not found'.format(tmp))
                        return False
                elif self._parameters[k] == self.ASK:
                    val = None
                    a1 = '__x___'
                    a2 = '__y___'
                    prompt1 = "Enter value for '{}': ".format(k)
                    prompt2 = "Confirm value for '{}': ".format(k)
                    while a1 != a2:
                        a1 = getpass.getpass(prompt=prompt1)
                        a2 = getpass.getpass(prompt=prompt2)
                        if a1 == a2:
                            val = a1
                        else:
                            print('values do not match, try again')
                    self._parameters[k] = val
            except:
                pass

        return True

def get_state_actions(self, state, **kwargs):
        config_type = state.config_id.config_type
        if config_type == ItemType.VOLUME:
            if state.base_state == State.ABSENT:
                return [
                    ItemAction(state, Action.CREATE),
                    ItemAction(state, VolumeUtilAction.PREPARE),
                ]
            elif state.base_state == State.PRESENT and state.state_flags & StateFlags.INITIAL:
                return [
                    ItemAction(state, Action.START),
                    ItemAction(state, VolumeUtilAction.PREPARE),
                ]
        elif config_type == ItemType.CONTAINER:
            if state.base_state == State.ABSENT:
                return [
                    ItemAction(state, DerivedAction.STARTUP_CONTAINER),
                    ItemAction(state, ContainerUtilAction.EXEC_ALL),
                ]
            elif state.base_state == State.PRESENT:
                return [
                    ItemAction(state, Action.START),
                    ItemAction(state, ContainerUtilAction.EXEC_ALL),
                ]
        else:
            if config_type == ItemType.NETWORK:
                return [ItemAction(state, Action.CREATE)]
            elif config_type == ItemType.IMAGE:
                return [ItemAction(state, ImageAction.PULL)]

