def find(self, s):
        pSet   = [s]
        parent = self._leader[s]

        while parent != self._leader[parent]:
            pSet.append(parent)
            parent = self._leader[parent]

        if len(pSet) > 1:
            for a in pSet:
                self._leader[a] = parent

        return parent

