def get_parent(brain_or_object, catalog_search=False):

    if is_portal(brain_or_object):
        return get_portal()

    # Do a catalog search and return the brain
    if catalog_search:
        parent_path = get_parent_path(brain_or_object)

        # parent is the portal object
        if parent_path == get_path(get_portal()):
            return get_portal()

        # get the catalog tool
        pc = get_portal_catalog()

        # query for the parent path
        results = pc(path={
            "query": parent_path,
            "depth": 0})

        # No results fallback: return the parent object
        if not results:
            return get_object(brain_or_object).aq_parent

        # return the brain
        return results[0]

    return get_object(brain_or_object).aq_parent

def parse_constraints(self, constraints, joiner=" and ", *, is_assignment=False, comp="="):
    if constraints is None:
      return (None, None)
    elif isinstance(constraints, dict):
      return (
        self.join_comparisons(constraints, joiner, is_assignment=is_assignment, comp=comp),
        self.get_params(constraints))
    elif isinstance(constraints, (list, tuple)):
      if len(constraints) == 2 and isinstance(constraints[0], str):
        return (constraints[0], constraints[1])
      else:
        return (
          self.join_comparisons(constraints, joiner, is_assignment=is_assignment, comp=comp),
          self.get_params(constraints))
    elif isinstance(constraints, str):
      return (constraints, None)
    else:
      raise TypeError(
        "constraints must be None, str, dict, list or tuple. Is {0}".format(
          type(constraints).__name__))

def quit(self):
        if self._process is None:
            logger.debug('Quit was called after self._process had already been released')
            return
        try:
            logger.debug('Quitting OMXPlayer')
            process_group_id = os.getpgid(self._process.pid)
            os.killpg(process_group_id, signal.SIGTERM)
            logger.debug('SIGTERM Sent to pid: %s' % process_group_id)
            self._process_monitor.join()
        except OSError:
            logger.error('Could not find the process to kill')

        self._process = None

def datetime_to_json(pydt, manager):
    if pydt is None:
        return None
    else:
        return dict(
            year=pydt.year,
            month=pydt.month - 1,  # Months are 0-based indices in JS
            date=pydt.day,
            hours=pydt.hour,       # Hours, Minutes, Seconds and Milliseconds
            minutes=pydt.minute,   # are plural in JS
            seconds=pydt.second,
            milliseconds=pydt.microsecond / 1000
        )

def extend(self, iterable):
        # Sequence
        if is_sequence(iterable):
            self._data.extend(iterable)
        # Structure
        elif is_structure(iterable):
            members = [item for item in iterable.values()]
            self._data.extend(members)
        # Field
        elif is_field(iterable):
            self._data.extend([iterable])
        # Iterable
        elif isinstance(iterable, (set, tuple, list)):
            self._data.extend(Sequence(iterable))
        else:
            raise MemberTypeError(self, iterable, member=len(self))

def lowerbound(self, axis=0):
        if not 0 <= axis < self.GetDimension():
            raise ValueError(
                "axis must be a non-negative integer less than "
                "the dimensionality of the histogram")
        if axis == 0:
            return self.xedges(1)
        if axis == 1:
            return self.yedges(1)
        if axis == 2:
            return self.zedges(1)
        raise TypeError("axis must be an integer")

