def isotopic_variants(composition, npeaks=None, charge=0, charge_carrier=PROTON):
    if npeaks is None:
        max_n_variants = max_variants(composition)
        npeaks = int(sqrt(max_n_variants) - 2)
        npeaks = max(npeaks, 3)
    else:
        # Monoisotopic Peak is not included
        npeaks -= 1
    return IsotopicDistribution(composition, npeaks).aggregated_isotopic_variants(
        charge, charge_carrier=charge_carrier)

def calc_geo_branches_in_polygon(mv_grid, polygon, mode, proj):

    branches = []
    polygon_shp = transform(proj, polygon)
    for branch in mv_grid.graph_edges():
        nodes = branch['adj_nodes']
        branch_shp = transform(proj, LineString([nodes[0].geo_data, nodes[1].geo_data]))

        # check if branches intersect with polygon if mode = 'intersects'
        if mode == 'intersects':
            if polygon_shp.intersects(branch_shp):
                branches.append(branch)
        # check if polygon contains branches if mode = 'contains'
        elif mode == 'contains':
            if polygon_shp.contains(branch_shp):
                branches.append(branch)
        # error
        else:
            raise ValueError('Mode is invalid!')
    return branches

