            uri = regr.uri
        if isinstance(regr, messages.RegistrationResource):
            message = messages.UpdateRegistration(**dict(regr.body))
        else:
            message = regr
        action = LOG_ACME_UPDATE_REGISTRATION(uri=uri, registration=message)
        with action.context():
            return (
                DeferredContext(self._client.post(uri, message))
                .addCallback(self._parse_regr_response, uri=uri)
                .addCallback(self._check_regr, regr)
                .addCallback(
                    tap(lambda r: action.add_success_fields(registration=r)))
                .addActionFinish())

def forTypes(klass, key, classes, description, extraValidator=None):
        fixedClasses = []
        for k in classes:
            if k is None:
                k = type(None)
            # Verify the type is JSON-encodeable before adding it to the list.
            if k not in _JSON_TYPES:
                raise TypeError("%s is not JSON-encodeable" % (k, ))
            fixedClasses.append(k)
        fixedClasses = tuple(fixedClasses)

        def validate(value):
            if not isinstance(value, fixedClasses):
                raise ValidationError(
                    value,
                    "Field %r requires type to be one of %s" % (key, classes))
            if extraValidator is not None:
                extraValidator(value)

        return klass(key, lambda v: v, description, extraValidator=validate)

def update(self, E=None, **F):
        def _update(D):
            for k,v in D.items():
                if super(ConfigDict, self).__contains__(k):
                    if isinstance(self[k], ConfigDict):
                        self[k].update(v)
                    else:
                        self[k] = self.assimilate(v)
                else:
                    self[k] = self.assimilate(v)

        if E is not None:
            if not hasattr(E, 'keys'):
                E = self.assimilate(dict(E))
            _update(E)

        _update(F)

        return self

def text_search(self, query=None, language=lang.ENGLISH, lat_lng=None,
                    radius=3200, type=None, types=[], location=None, pagetoken=None):
        self._request_params = {'query': query}
        if lat_lng is not None or location is not None:
            lat_lng_str = self._generate_lat_lng_string(lat_lng, location)
            self._request_params['location'] = lat_lng_str
        self._request_params['radius'] = radius
        if type:
            self._request_params['type'] = type
        elif types:
            if len(types) == 1:
                self._request_params['type'] = types[0]
            elif len(types) > 1:
                self._request_params['types'] = '|'.join(types)
        if language is not None:
            self._request_params['language'] = language
        if pagetoken is not None:
            self._request_params['pagetoken'] = pagetoken
        self._add_required_param_keys()
        url, places_response = _fetch_remote_json(
                GooglePlaces.TEXT_SEARCH_API_URL, self._request_params)
        _validate_response(url, places_response)
        return GooglePlacesSearchResult(self, places_response)

def default_decoder(self, obj):
        typename, marshalled_state = self.unwrap_callback(obj)
        if typename is None:
            return obj

        try:
            cls, unmarshaller = self.serializer.unmarshallers[typename]
        except KeyError:
            raise LookupError('no unmarshaller found for type "{}"'.format(typename)) from None

        if cls is not None:
            instance = cls.__new__(cls)
            unmarshaller(instance, marshalled_state)
            return instance
        else:
            return unmarshaller(marshalled_state)

def ToPath(self):

    if self.path_type == PathInfo.PathType.OS:
      return os.path.join("fs", "os", *self.path_components)
    elif self.path_type == PathInfo.PathType.TSK:
      return os.path.join("fs", "tsk", *self.path_components)
    elif self.path_type == PathInfo.PathType.REGISTRY:
      return os.path.join("registry", *self.path_components)
    elif self.path_type == PathInfo.PathType.TEMP:
      return os.path.join("temp", *self.path_components)

    raise ValueError("Unsupported path type: %s" % self.path_type)

