def data(self, index, role):
        if role == QtCore.Qt.DisplayRole or role == QtCore.Qt.EditRole:
            test = self._testmodel.test(index.row())
            col = index.column()
            if col == 0:
                item = test.userTag()
            elif col == 1:
                item = test.stimType()
            elif col == 2:
                item = test.repCount()
            elif col == 3:
                item = test.traceCount()
            elif col == 4:
                item = test.traceCount()*test.loopCount()*test.repCount()
            elif col == 5:
                item = test.samplerate()

            return item
        elif role == QtCore.Qt.UserRole:  #return the whole python object
            test = self._testmodel.test(index.row())
            return QStimulusModel(test)
        elif role == QtCore.Qt.UserRole + 1:  #return the whole python object
            test = self._testmodel.test(index.row())
            return test
        elif role == CursorRole:
            col = index.column()
            if not index.isValid():
                return QtGui.QCursor(QtCore.Qt.ArrowCursor)
            elif col == 0:
                return QtGui.QCursor(QtCore.Qt.IBeamCursor)
            else:
                return cursors.openHand()

def start(vm, options=None, key='uuid'):
    ret = {}
    if key not in ['uuid', 'alias', 'hostname']:
        ret['Error'] = 'Key must be either uuid, alias or hostname'
        return ret
    vm = lookup('{0}={1}'.format(key, vm), one=True)
    if 'Error' in vm:
        return vm
    # vmadm start <uuid> [option=value ...]
    cmd = 'vmadm start {uuid} {options}'.format(
        uuid=vm,
        options=options if options else ''
    )
    res = __salt__['cmd.run_all'](cmd)
    retcode = res['retcode']
    if retcode != 0:
        ret['Error'] = res['stderr'] if 'stderr' in res else _exit_status(retcode)
        return ret
    return True

