def run(self):
        count = {}

        # NOTE: self.input() actually returns an element for the InputText.output() target
        for f in self.input():  # The input() method is a wrapper around requires() that returns Target objects
            for line in f.open('r'):  # Target objects are a file system/format abstraction and this will return a file stream object
                for word in line.strip().split():
                    count[word] = count.get(word, 0) + 1

        # output data
        f = self.output().open('w')
        for word, count in six.iteritems(count):
            f.write("%s\t%d\n" % (word, count))
        f.close()

def set_config(self, payload):
        self.config['default'][payload['option']] = str(payload['value'])

        if payload['option'] == 'maxProcesses':
            self.process_handler.set_max(payload['value'])
        if payload['option'] == 'customShell':
            path = payload['value']
            if os.path.isfile(path) and os.access(path, os.X_OK):
                self.process_handler.set_shell(path)
            elif path == 'default':
                self.process_handler.set_shell()
            else:
                return {'message': "File in path doesn't exist or is not executable.",
                        'status': 'error'}

        self.write_config()

        return {'message': 'Configuration successfully updated.',
                'status': 'success'}

