def delete_keys(self, *args, **kwargs):
        ikeys = iter(kwargs.get('keys', args[0] if args else []))

        while True:
            try:
                tmp = ikeys.next()
            except StopIteration:
                break

            if isinstance(tmp, basestring):
                mimicdb.backend.srem(tpl.bucket % self.name, tmp)
                mimicdb.backend.delete(tpl.key % (self.name, tmp))
            elif isinstance(tmp, BotoKey) or isinstance(tmp, Key):
                mimicdb.backend.srem(tpl.bucket % self.name, tmp.name)
                mimicdb.backend.delete(tpl.key % (self.name, tmp.name))

        return super(Bucket, self).delete_keys(*args, **kwargs)

def stop(self, sig=None, timeout=10):
        if self.process is None:
            return self

        if sig is None:
            sig = self._sig_stop

        try:
            os.killpg(self.process.pid, sig)
        except OSError as err:
            if err.errno in IGNORED_ERROR_CODES:
                pass
            else:
                raise

        def process_stopped():
            """Return True only only when self.process is not running."""
            return self.running() is False

        self._set_timeout(timeout)
        try:
            self.wait_for(process_stopped)
        except TimeoutExpired:
            log.warning('Timeout expired, killing process', process=self)
            pass

        self._kill_all_kids(sig)
        self._clear_process()
        return self

def upload(self, timeout=None):
        if self._vehicle._wpts_dirty:
            self._vehicle._master.waypoint_clear_all_send()
            start_time = time.time()
            if self._vehicle._wploader.count() > 0:
                self._vehicle._wp_uploaded = [False] * self._vehicle._wploader.count()
                self._vehicle._master.waypoint_count_send(self._vehicle._wploader.count())
                while False in self._vehicle._wp_uploaded:
                    if timeout and time.time() - start_time > timeout:
                        raise TimeoutError
                    time.sleep(0.1)
                self._vehicle._wp_uploaded = None
            self._vehicle._wpts_dirty = False

def _extract_auth_config(self):

        service = self._service
        if not service.authentication:
            return {}

        auth_infos = {}
        for auth_rule in service.authentication.rules:
            selector = auth_rule.selector
            provider_ids_to_audiences = {}
            for requirement in auth_rule.requirements:
                provider_id = requirement.providerId
                if provider_id and requirement.audiences:
                    audiences = requirement.audiences.split(u",")
                    provider_ids_to_audiences[provider_id] = audiences
            auth_infos[selector] = AuthInfo(provider_ids_to_audiences)
        return auth_infos

