def get_dependencies(primary_type, types):
    deps = set()
    struct_names_yet_to_be_expanded = [primary_type]

    while len(struct_names_yet_to_be_expanded) > 0:
        struct_name = struct_names_yet_to_be_expanded.pop()

        deps.add(struct_name)
        fields = types[struct_name]
        for field in fields:
            if field["type"] not in types:
                # We don't need to expand types that are not user defined (customized)
                continue
            elif field["type"] in deps:
                # skip types that we have already encountered
                continue
            else:
                # Custom Struct Type
                struct_names_yet_to_be_expanded.append(field["type"])

    # Don't need to make a struct as dependency of itself
    deps.remove(primary_type)

    return tuple(deps)

def __collapseLineOrCol(self, line, d):
        if (d == Board.LEFT or d == Board.UP):
            inc = 1
            rg = xrange(0, self.__size-1, inc)
        else:
            inc = -1
            rg = xrange(self.__size-1, 0, inc)

        pts = 0
        for i in rg:
            if line[i] == 0:
                continue
            if line[i] == line[i+inc]:
                v = line[i]*2
                if v == self.__goal:
                    self.__won = True

                line[i] = v
                line[i+inc] = 0
                pts += v

        return (line, pts)

def engage(self, **kwargs):
        if 'height' in kwargs:
            height = kwargs.get('height')
        else:
            height = LABWARE_ENGAGE_HEIGHT.get(
                self.labware.get_children_list()[1].get_name())
            if not height:
                raise ValueError(
                    'No engage height definition found for {}. Provide a'
                    'custom height instead'.format(
                        self.labware.get_children_list()[1].get_name()))
            if 'offset' in kwargs:
                height += kwargs.get('offset')
        if height > MAX_ENGAGE_HEIGHT or height < 0:
            raise ValueError('Invalid engage height. Should be 0 to {}'.format(
                MAX_ENGAGE_HEIGHT))
        if self._driver and self._driver.is_connected():
            self._driver.move(height)
            self._engaged = True

def _build_projection_expression(clean_table_keys):
    projection_expression = ''
    for key in clean_table_keys[:-1]:
        projection_expression += ('{},').format(key)
    projection_expression += clean_table_keys[-1]
    return projection_expression

def rand_ktensor(shape, rank, norm=None, random_state=None):

    # Check input.
    rns = _check_random_state(random_state)

    # Randomize low-rank factor matrices i.i.d. uniform random elements.
    factors = KTensor([rns.uniform(0.0, 1.0, size=(i, rank)) for i in shape])
    return _rescale_tensor(factors, norm)

def restore_row(self, row, schema):
        for index, field in enumerate(schema.fields):
            if field.type == 'datetime':
                row[index] = parse(row[index])
            if field.type == 'date':
                row[index] = parse(row[index]).date()
            if field.type == 'time':
                row[index] = parse(row[index]).time()
        return schema.cast_row(row)

def pop_header(self, hkey, ignore_error=False):

        # try the integer approach first to allow negative values
        if type(hkey) is not str:
            try:    
                return self.headers.pop(self.hkeys.pop(hkey))
            except: 
                if not ignore_error:
                    print("ERROR: pop_header() could not find hkey "+str(hkey))
                return None
        else:

            try:
                # find the key integer and pop it
                hkey = self.hkeys.index(hkey)

                # pop it!
                return self.headers.pop(self.hkeys.pop(hkey))

            except:
                if not ignore_error:
                    print("ERROR: pop_header() could not find hkey "+str(hkey))
                return

def _skip_lines(self, n):
