def system_properties_absent(name, server=None):
    ret = {'name': '', 'result': None, 'comment': None, 'changes': {}}

    try:
        data = __salt__['glassfish.get_system_properties'](server=server)
    except requests.ConnectionError as error:
        if __opts__['test']:
            ret['changes'] = {'Name': name}
            ret['result'] = None
            return ret
        else:
            ret['error'] = "Can't connect to the server"
            return ret

    if name in data:
        if not __opts__['test']:
            try:
                __salt__['glassfish.delete_system_properties'](name, server=server)
                ret['result'] = True
                ret['comment'] = 'System properties deleted'
            except CommandExecutionError as error:
                ret['comment'] = error
                ret['result'] = False
        else:
            ret['result'] = None
            ret['comment'] = 'System properties would have been deleted'
        ret['changes'] = {'Name': name}
    else:
        ret['result'] = True
        ret['comment'] = 'System properties are already absent'
    return ret

def rebin(a, factor, func=None):
    a = np.asarray(a)
    dim = a.ndim
    if np.isscalar(factor):
        factor = dim*(factor,)
    elif len(factor) != dim:
        raise ValueError('length of factor must be {} (was {})'
                         .format(dim, len(factor)))
    if func is None:
        func = np.mean
    for f in factor:
        if f != int(f):
            raise ValueError('factor must be an int or a tuple of ints '
                             '(got {})'.format(f))

    new_shape = [n//f for n, f in zip(a.shape, factor)]+list(factor)
    new_strides = [s*f for s, f in zip(a.strides, factor)]+list(a.strides)
    aa = as_strided(a, shape=new_shape, strides=new_strides)
    return func(aa, axis=tuple(range(-dim, 0)))

def parse_rule(cls, txt):
        types = {"glob": GlobRule,
                 "regex": RegexRule,
                 "range": RangeRule,
                 "before": TimestampRule,
                 "after": TimestampRule}

        # parse form 'x(y)' into x, y
        label, txt = Rule._parse_label(txt)
        if label is None:
            if '*' in txt:
                label = "glob"
            else:
                label = "range"
        elif label not in types:
            raise ConfigurationError(
                "'%s' is not a valid package filter type" % label)

        rule_cls = types[label]
        txt_ = "%s(%s)" % (label, txt)

        try:
            rule = rule_cls._parse(txt_)
        except Exception as e:
            raise ConfigurationError("Error parsing package filter '%s': %s: %s"
                                     % (txt_, e.__class__.__name__, str(e)))
        return rule

def support(self, version):

        if not self._known_version(version):
            warn("unknown feature: %s"%version)
            return True
        else:
            if not self._get_featureset_support(version):
                warn("You are not supporting %s anymore "%str(version), UserWarning, self.level)
            if self._alone_version(version):
                warn("%s is the last supported feature of this group, you can simplifiy this logic. "%str(version), UserWarning,self.level)

            return self.predicates.get(version, True)




        if (not self.PY3_supported) or (not self.PY2_supported):
            warn("You are only supporting 1 version of Python", UserWarning, self.level)

        if version == PY3:
            return sys.version_info.major == 3
        elif version == PY2:
            return sys.version_info.major == 2

