def chunks(stream, size=None):
  if size == 'lines':
    for item in stream:
    # for item in stream.readline():
      yield item
    return
  if size is None:
    size = MAXBUF
  while True:
    buf = stream.read(size)
    if not buf:
      return
    yield buf

def help(self, args=None, userlevel=9):
        out = [main.__file__+"\n"]

        if args is not None:
            parsed = self.parse(args, ignore_help=True)
        else:
            parsed = self._default_dict()

        for thing in self.options:
            if type(thing) == str:
                out.append("     "+thing)
            elif thing[0] <= userlevel:
                out.append("     %10s   %s ( %s )" % (thing[1], thing[-1], str(parsed[thing[2]])))

        return "\n".join(out)+"\n"

