def isPositionValid(self, line: int, column: int):
        if (line < 0) or (column < 0):
            return False

        last_line, last_col = self.getNumLinesAndColumns()
        if line > last_line:
            return False

        if column <= len(self.text(line)):
            return True
        else:
            return False

def long_input(prompt='Multi-line input\n' + \
        'Enter EOF on a blank line to end ' + \
        '(ctrl-D in *nix, ctrl-Z in windows)',
        maxlines = None, maxlength = None):

    lines = []
    print(prompt)
    lnum = 1

    try:
        while True:

            if maxlines:

                if lnum > maxlines:
                    break

                else:
                    if maxlength:
                        lines.append(string_input('')[:maxlength])
                    else:
                        lines.append(string_input(''))
                    lnum += 1

            else:
                if maxlength:
                    lines.append(string_input('')[:maxlength])
                else:
                    lines.append(string_input(''))

    except EOFError:
        pass
    finally:
        return '\n'.join(lines)

