def _remove_comment(line):
    # First find just quotes and their indexes.
    quote_indexes = []
    hash_indexes = []
    for i, ch in enumerate(line):
        if ch == '"':
            quote_indexes.append(i)
            if i > 0 and line[i - 1] == "\\":
                quote_indexes.pop()
        elif ch == '#':
            hash_indexes.append(i)

    comment_marker_index = -1
    for hash_index in hash_indexes:
        quote_index_ranges = [quote_indexes[i:i + 2] for i in range(0, len(quote_indexes), 2)]
        if not _check_index_within_index_pairs(hash_index, quote_index_ranges):
            comment_marker_index = hash_index
            break

    if comment_marker_index >= 0:
        line = line[:comment_marker_index]
    return line

def date_select(df, date_column, date, delta, max_date_column=None):
    delta = parse_delta(delta)
    if delta:
        start_date = date - delta

    if not max_date_column:
        df = df.query("%s < '%s'" % (date_column, date))
        if delta:
            df = df.query("%s >= '%s'" % (date_column, start_date))
    else:
        # event not entirely after
        df = df.query("not ({min} >= '{end}' and {max} >= '{end}')".format(
                          min=date_column, max=max_date_column, end=date))
        if delta:
            # event not entirely before
            df = df.query("not ({min} < '{start}' and {max} < '{start}')".format(
                          min=date_column, max=max_date_column, start=start_date))

    return df

def do_inspect(self, code, cursor_pos, detail_level=0):
        self._klog.info("{%s}", code[cursor_pos:cursor_pos+10])

        # Find the token for which help is requested
        token, start = token_at_cursor(code, cursor_pos)
        self._klog.debug("token={%s} {%d}", token, detail_level)

        # Find the help for this token
        if not is_magic(token, start, code):
            info = sparql_help.get(token.upper(), None)
        elif token == '%':
            info = magic_help
        else:
            info = magics.get(token, None)
            if info:
                info = '{} {}\n\n{}'.format(token, *info)

        return {'status': 'ok',
                'data': {'text/plain': info},
                'metadata': {},
                'found': info is not None
               }

def update(self, callback=None, errback=None, **kwargs):
        if not self.data:
            raise NetworkException('Network not loaded')

        def success(result, *args):
            self.data = result
            self.id = result['id']
            self.name = result['name']
            self.report = self._rest.report(self.id)
            if callback:
                return callback(self)
            else:
                return self

        return self._rest.update(self.id, callback=success, errback=errback,
                                 **kwargs)

