def write(self, valuedict):
        result = []
        if self.identifier in valuedict:
            values = valuedict[self.identifier]
        else:
            return result

        if self.comment != "":
            result.append(self.comment)

        if self.repeat is not None and type(values) == type([]):
            if self.repeat.isdigit():
                for i in range(int(self.repeat)):  
                    result.extend(self._write_iterate(values[i]))
            else:
                #We are repeating for as many values as we have in the value
                #entry for the group in the dictionary.
                for value in values:
                    result.extend(self._write_iterate(value))
        elif type(values) == type({}):
            #This group doesn't get repeated, so the values variable must
            #be a dictionary, just run it once.
            result = self._write_iterate(values)

        return result

def insert_many(self, it):
        unique_indexes = self._uniqueIndexes  # [ind for ind in self._indexes.values() if ind.is_unique]
        NO_SUCH_ATTR = object()
        new_objs = list(it)
        if unique_indexes:
            for ind in unique_indexes:
                ind_attr = ind.attr
                new_keys = dict((getattr(obj, ind_attr, NO_SUCH_ATTR), obj) for obj in new_objs)
                if not ind.accept_none and (None in new_keys or NO_SUCH_ATTR in new_keys):
                    raise KeyError("unique key cannot be None or blank for index %s" % ind_attr, 
                                    [ob for ob in new_objs if getattr(ob, ind_attr, NO_SUCH_ATTR) is None])
                if len(new_keys) < len(new_objs):
                    raise KeyError("given sequence contains duplicate keys for index %s" % ind_attr)
                for key in new_keys:
                    if key in ind:
                        obj = new_keys[key]
                        raise KeyError("duplicate unique key value '%s' for index %s" % (getattr(obj, ind_attr), ind_attr), 
                                       new_keys[key])

        for obj in new_objs:
            self.obs.append(obj)
            for attr, ind in self._indexes.items():
                obval = getattr(obj, attr)
                ind[obval] = obj

        return self

