def get_concept_item_mapping(self, concepts=None, lang=None):
        if concepts is None:
            concepts = self.filter(active=True)
            if lang is not None:
                concepts = concepts.filter(lang=lang)
        if lang is None:
            languages = set([concept.lang for concept in concepts])
            if len(languages) > 1:
                raise Exception('Concepts has multiple languages')
            lang = list(languages)[0]
        item_lists = Item.objects.filter_all_reachable_leaves_many([json.loads(concept.query)
                                                                    for concept in concepts], lang)
        return dict(zip([c.pk for c in concepts], item_lists))

def parse_data_line(self, sline):
        # if there are less values founded than headers, it's an error
        if len(sline) != len(self._columns):
            self.err("One data line has the wrong number of items")
            return -1
        values = {}
        remark = ''
        date = ''
        resid = ''
        for idx, result in enumerate(sline):
            if self._columns[idx] == 'Date':
                date = self.csvDate2BikaDate(result)
            elif self._columns[idx] == 'Patient no.':
                resid = result
            elif self._columns[idx] == 'Customer no.':
                remark = result
            elif self._columns[idx] != '':
                values[self._columns[idx]] = {
                    'result': result,
                    'DefaultResult': 'result',
                    'Remarks': remark,
                    'DateTime': date,
                }
        self._addRawResult(resid, values, False)
        return 0

