def get_provider_manager(osid, runtime=None, proxy=None, local=False):
    if runtime is not None:
        if local:
            parameter_id = Id('parameter:localImpl@json')
        else:
            parameter_id = Id('parameter:' + osid.lower() + 'ProviderImpl@json')
        try:
            # Try to get the manager from the runtime, if available:
            config = runtime.get_configuration()
            impl_name = config.get_value_by_parameter(parameter_id).get_string_value()
            if proxy is None:
                return runtime.get_manager(osid, impl_name)
            else:
                return runtime.get_proxy_manager(osid, impl_name)
        except (AttributeError, KeyError, NotFound):
            pass
    # Try to return a Manager directly from this implementation, or raise OperationFailed:
    try:
        if proxy is None:
            mgr_str = 'Manager'
        else:
            mgr_str = 'ProxyManager'
        module = import_module(
            'dlkit.json_.' + fix_reserved_word(osid.lower(), is_module=True) + '.managers')
        manager_name = ''.join((osid.title()).split('_')) + mgr_str
        manager = getattr(module, manager_name)()
    except (ImportError, AttributeError):
        raise OperationFailed()
    if runtime is not None:
        manager.initialize(runtime)
    return manager

def hyperedge_cardinality_pairs_list(H):
    if not isinstance(H, DirectedHypergraph):
        raise TypeError("Algorithm only applicable to directed hypergraphs")

    return [(len(H.get_hyperedge_tail(hyperedge_id)),
            len(H.get_hyperedge_head(hyperedge_id)))
            for hyperedge_id in H.hyperedge_id_iterator()]

def policy_present(name, rules):
    url = "v1/sys/policy/{0}".format(name)
    response = __utils__['vault.make_request']('GET', url)
    try:
        if response.status_code == 200:
            return _handle_existing_policy(name, rules, response.json()['rules'])
        elif response.status_code == 404:
            return _create_new_policy(name, rules)
        else:
            response.raise_for_status()
    except Exception as e:
        return {
            'name': name,
            'changes': {},
            'result': False,
            'comment': 'Failed to get policy: {0}'.format(e)
        }

def cancel(self):

        method, url = get_URL('cancel')

        payload = {
            'apikey': self.config.get('apikey'),
            'transferid': self.transfer_id,
            'transferkey': self.transfer_info.get('transferkey')
            }

        res = getattr(self.session, method)(url, params=payload)

        if res.status_code == 200:
            self._complete = True
            return True

        hellraiser(res)

