def create_path(self, path, **kwargs):

        i = 0
        while i < len(path):
            i = path.find("/", i)

            if i < 0:
                return

            subpath = path[:i]

            if i > 0:
                try:
                    yield self.create(subpath, **kwargs)
                except NodeExistsException:
                    pass

            i += 1

