def bz2_compress_stream(src, level=9):
    compressor = bz2.BZ2Compressor(level)
    for block in src:
        encoded = compressor.compress(block)
        if encoded:
            yield encoded
    yield compressor.flush()

def set_value(obj, attrs, value, _copy=False):
