def dump2json(self, obj, filepath, override=False, **kwargs):
        # We make sure that the object passed by the user is a dictionary.
        if isinstance(obj, dict):
            pass
        else:
            raise _NotADictionary(
                "This function only accepts dictionaries as input")
        # We check if the filepath has a json extenstion, if not we add it.
        if str(filepath[-4:]) == 'json':
            pass
        else:
            filepath = ".".join((str(filepath), "json"))
        # First we check if the file already exists. If yes and the override
        # keyword is False (default), we will raise an exception. Otherwise
        # the file will be overwritten.
        if override is False:
            if os.path.isfile(filepath):
                raise _FileAlreadyExists(
                    "The file {0} already exists. Use a different filepath, "
                    "or set the 'override' kwarg to True.".format(filepath))
        # We dump the object to the json file. Additional kwargs can be passed.
        with open(filepath, 'w+') as json_file:
            json.dump(obj, json_file, **kwargs)

def post(self, data, request, id):
        # Reject requests targeting specific users to enforce bulk posting rules.
        if id:
            # can't post to individual user
            raise errors.MethodNotAllowed()
        user = self._dict_to_model(data)
        user.save()
        # according to REST, return 201 and Location header
        return Response(201, None, {
            'Location': '%s%d' % (reverse('user'), user.pk)})

def set_attribute(self, aid, attrib, val, idx='*'):
        if aid in self.__attrib_ids:
            elems = self.__attrib_ids[aid]
            if idx == '*':
                for elem in elems:
                    self.__set_attribute(elem, attrib, val)
            elif idx < len(elems):
                elem = elems[idx]
                self.__set_attribute(elem, attrib, val)

def _call(self, method, auth, arg, defer, notimeout=False):
        if defer:
            self.deferred.add(auth, method, arg, notimeout=notimeout)
            return True
        else:
            calls = self._composeCalls([(method, arg)])
            return self._callJsonRPC(auth, calls, notimeout=notimeout)

def process(self):

        with self.lock, self.enlock:
            queue = copy(self.queue)
            self.queue.clear()
            callbacks = copy(self.callbacks)

        with self.lock:
            rm_cb = False
            for ki, vi in queue.items():
                if ki in self.callbacks:
                    for item in vi:
                        for cb in self.callbacks[ki]:
                            if cb(item) is False:
                                callbacks[ki].remove(cb)
                                if not callbacks[ki]:
                                    del callbacks[ki]
                                rm_cb = True

        with self.lock:
            if rm_cb:
                self.callbacks.clear()
                for k, v in callbacks.items():
                    self.callbacks[k].extend(v)
            return len(self.callbacks)

def allstats(self, approximate=False):
        statcollect = []
        for x in self.layers():
            try:
                stats = x.ComputeStatistics(approximate)
            except RuntimeError:
                stats = None
            stats = dict(zip(['min', 'max', 'mean', 'sdev'], stats))
            statcollect.append(stats)
        return statcollect

def cli(patterns, times, json, csv, rst, md, ref, unit, precision, debug):
    if ref:
        ref = JSON.load(ref)

    filenames = []
    reporters = [CliReporter(ref=ref, debug=debug, unit=unit, precision=precision)]
    kwargs = {}
    for pattern in patterns or ['**/*.bench.py']:
        filenames.extend(resolve_pattern(pattern))
    if json:
        reporters.append(JsonReporter(json, precision=precision))
    if csv:
        reporters.append(CsvReporter(csv, precision=precision))
    if rst:
        reporters.append(RstReporter(rst, precision=precision))
    if md:
        reporters.append(MarkdownReporter(md, precision=precision))
    if times:
        kwargs['times'] = times
    runner = BenchmarkRunner(*filenames, reporters=reporters, debug=debug)
    runner.run(**kwargs)

