def convert_units(self, desired, guess=False):
        # if there is no geometry do nothing
        if len(self.geometry) == 0:
            return self.copy()

        current = self.units
        if current is None:
            # will raise ValueError if not in metadata
            # and not allowed to guess
            current = units.units_from_metadata(self, guess=guess)

        # find the float conversion
        scale = units.unit_conversion(current=current,
                                      desired=desired)

        # exit early if our current units are the same as desired units
        if np.isclose(scale, 1.0):
            result = self.copy()
        else:
            result = self.scaled(scale=scale)

        # apply the units to every geometry of the scaled result
        result.units = desired

        return result

def retry(ex=RETRIABLE, tries=4, delay=5, backoff=2, logger=None):
    def deco_retry(func):
        """@retry(arg[, ...]) -> true decorator"""

        @wraps(func)
        def f_retry(*args, **kwargs):
            """true decorator -> decorated function"""
            mtries, mdelay = tries, delay
            while mtries > 1:
                try:
                    return func(*args, **kwargs)
                except ex as error:
                    sleeping = mdelay + randint(0, 5)
                    msg = "%s, Retrying in %d seconds..." % (str(error), sleeping)
                    if logger:
                        logger.warning(msg)
                    sleep(sleeping)
                    mtries -= 1
                    mdelay *= backoff
            return func(*args, **kwargs)

        return f_retry  # true decorator

    return deco_retry

def contains(self, key, value, findAll=False, exclude=False, includeMissing=False):
        result = []
        result_index = []
        for counter, row in enumerate(self.table):
            (target, tkey, target_list) = internal.dict_crawl(row, key)
            if target:
                if findAll:
                    success = internal.list_match_all(target_list, value)
                else:
                    success = internal.list_match_any(target_list, value)
                if exclude:
                    success = not success
                if success:
                    result.append(row)
                    result_index.append(self.index_track[counter])
                else:
                    # item missing from list, so skip over
                    pass
            else:
                if includeMissing:
                    result.append(row)
                    result_index.append(self.index_track[counter])
                else:
                    pass
        self.table = result
        self.index_track = result_index
        return self

