def _distance_matrix(self, a, b):
        def sq(x): return (x * x)
        # matrix = np.sum(map(lambda a,b: sq(a[:,None] - b[None,:]), a.T,
        #   b.T), axis=0)
        # A faster version than above:
        matrix = sq(a[:, 0][:, None] - b[:, 0][None, :])
        for x, y in zip(a.T[1:], b.T[1:]):
            matrix += sq(x[:, None] - y[None, :])
        return matrix

def get_convert_dist(
    dist_units_in: str, dist_units_out: str
) -> Callable[[float], float]:
    di, do = dist_units_in, dist_units_out
    DU = cs.DIST_UNITS
    if not (di in DU and do in DU):
        raise ValueError(f"Distance units must lie in {DU}")

    d = {
        "ft": {"ft": 1, "m": 0.3048, "mi": 1 / 5280, "km": 0.0003048},
        "m": {"ft": 1 / 0.3048, "m": 1, "mi": 1 / 1609.344, "km": 1 / 1000},
        "mi": {"ft": 5280, "m": 1609.344, "mi": 1, "km": 1.609344},
        "km": {"ft": 1 / 0.0003048, "m": 1000, "mi": 1 / 1.609344, "km": 1},
    }
    return lambda x: d[di][do] * x

def parse(self, argv):
        if not argv:
            raise BadNumberOfArguments(1, 0)
        argument = argv.pop(0)
        lookup = self.casesensitive and argument or argument.lower()
        if lookup in self.special:
            return self.special[lookup]
        argv = [(self.strip and s.strip() or s) for s in argument.split(self.separator)]
        values = []
        while argv:
            values.append(self.format.parse(argv))
        return values

