def import_from(self, other_ns, replace=False):
        for other_ns_uri in other_ns.namespace_uris:
            ni = self.__ns_uri_map.get(other_ns_uri)

            if ni is None:
                other_ni = other_ns._NamespaceSet__ns_uri_map[other_ns_uri]

                # Gotta make sure that the other set isn't mapping its prefixes
                # incompatibly with respect to this set.
                for other_prefix in other_ni.prefixes:
                    self.__check_prefix_conflict(other_ns_uri, other_prefix)

                cloned_ni = copy.deepcopy(other_ni)
                self.__add_namespaceinfo(cloned_ni)
            elif replace:
                other_ni = other_ns._NamespaceSet__ns_uri_map[other_ns_uri]
                for other_prefix in other_ni.prefixes:
                    self.__check_prefix_conflict(ni, other_prefix)

                cloned_ni = copy.deepcopy(other_ni)
                self.remove_namespace(other_ns_uri)
                self.__add_namespaceinfo(cloned_ni)
            else:
                continue

def as_ufloat(roorealvar):
    if isinstance(roorealvar, (U.AffineScalarFunc, U.Variable)):
        return roorealvar
    return U.ufloat((roorealvar.getVal(), roorealvar.getError()))

def find_file(config_file=None, default_directories=None, default_bases=None):

    if config_file:
        if path.exists(path.expanduser(config_file)):
            return config_file
        else:
            raise FileNotFoundError('Config file not found: {}'.format(config_file))

    dirs = default_directories or CONFIG_DIRS
    dirs = [getcwd()] + dirs

    bases = default_bases or CONFIG_BASES

    for directory, base in product(dirs, bases):
        filepath = path.expanduser(path.join(directory, base))
        if path.exists(filepath):
            return filepath

    raise FileNotFoundError('Config file not found in {}'.format(dirs))

