        if index < 0:
            raise EnvironmentError("adb is not working.")
        return dict(re.findall(r'([^\s]+)\t(\w+)', out))

def field_items(self, path=str(), **options):
        items = list()
        # Field
        items.append((path if path else 'field', self))
        # Data Object
        data_path = '{0}.{1}'.format(path, 'data') if path else 'data'
        # Container
        if is_container(self._data):
            for field_item in self._data.field_items(data_path, **options):
                items.append(field_item)
        # Pointer
        elif is_pointer(self._data) and get_nested(options):
            for field_item in self._data.field_items(data_path, **options):
                items.append(field_item)
        # Field
        elif is_field(self._data):
            items.append((data_path, self._data))
        return items

def logging_format(verbose=2, style='txt'):
    frmt = "'dt':'%(asctime)s', 'lv':'%(levelname)-7s', 'ln':'%(name)s'"

    if verbose > 1:
        frmt += ",\t'Func': '%(funcName)-12s','line':%(lineno)5d, 'module':'%(module)s'"
    if verbose > 2:
        frmt += ",\n\t'file':'%(filename)s',\t'Process':['%(processName)s', %(process)d], \
                'thread':['%(threadName)s', %(thread)d], 'ms':%(relativeCreated)d"
    frmt += ",\n\t'msg':'%(message)s'"
    if style == "dict":
        frmt = "{" + frmt + "}"
        frmt = frmt.replace(" ", "").replace("\n", "").replace("\t", "")
    if style == "txt":
        frmt = frmt.replace("'", "").replace(",", "")
    return frmt

def kernel_restarted_message(self, msg):
        if not self.is_error_shown:
            # If there are kernel creation errors, jupyter_client will
            # try to restart the kernel and qtconsole prints a
            # message about it.
            # So we read the kernel's stderr_file and display its
            # contents in the client instead of the usual message shown
            # by qtconsole.
            try:
                stderr = self._read_stderr()
            except Exception:
                stderr = None
            if stderr:
                self.show_kernel_error('<tt>%s</tt>' % stderr)
        else:
            self.shellwidget._append_html("<br>%s<hr><br>" % msg,
                                          before_prompt=False)

