def Group(params, name=None, type=None):
    atts = {}
    if name:
        atts['name'] = name
    if type:
        atts['type'] = type
    g = objectify.Element('Group', attrib=atts)
    for p in params:
        g.append(p)
    return g

def root(self: BoardT) -> BoardT:
        if self._stack:
            board = type(self)(None, chess960=self.chess960)
            self._stack[0].restore(board)
            return board
        else:
            return self.copy(stack=False)

def fail(self, group, message):
        logger.warn('Failing %s (%s): %s', self.jid, group, message)
        return self.client('fail', self.jid, self.client.worker_name, group,
            message, json.dumps(self.data)) or False

def cmd(command, *args, **kwargs):
    for k in list(kwargs):
        if k.startswith('__pub_'):
            kwargs.pop(k)
    local_command = '.'.join(['nxos', command])
    log.info('local command: %s', local_command)
    if local_command not in __salt__:
        return False
    return __salt__[local_command](*args, **kwargs)

