def _setup_transport(self):
        if hasattr(self, 'sslopts'):
            self.sock = ssl.wrap_socket(self.sock, **self.sslopts)
        elif hasattr(self, 'sslctx'):
            self.sock = self.sslctx.wrap_socket(self.sock,
                                                server_hostname=self.hostname)
        else:
            self.sock = ssl.wrap_socket(self.sock)
        self.sock.do_handshake()
        self._quick_recv = self.sock.read

def check(src, dst):  # type: (str,str)->None
    was_bad = False
    try:
        _ = ast.parse(src)
    except Exception as exc:
        was_bad = True
        major, minor = sys.version_info[:2]
        logger.warning(
            "failed to parse source file "
            "with Python {0}.{1}'s builtin AST. Switch to manual "
            "or stop using deprecated Python 2 syntax. AST error message: {2}".format(
                major, minor, exc
            )
        )

    try:
        _ = ast.parse(dst)
    except Exception as exc:
        if was_bad:
            # I didn't make it worse.
            pass
        else:
            # ok, this made the file worse. It must be jiggle_version's fault.
            print(dst)
            logger.error(dst)
            raise

def read_mix2pl_dataset(infile, numVotes=None):
    m, n = [int(i) for i in infile.readline().split(',')]
    if numVotes is not None and n < numVotes:
        raise ValueError("invalid number of votes to read: exceeds file amount")
    params = np.array([float(f) for f in infile.readline().split(',')])
    if len(params) != (2*m + 1):
        infile.close()
        raise ValueError("malformed file: len(params) != 2*m + 1")
    votes = []
    i = 0
    for line in infile:
        if i > (numVotes - 1):
            break
        vote = [int(v) for v in line.split(',')]
        if len(vote) != m:
            infile.close()
            raise ValueError("malformed file: len(vote) != m")
        votes.append(vote)
        i += 1
    infile.close()
    return (params, np.array(votes))

