def get_common_register(start, end):
    registers = defaultdict(int)
    for line in lines(start, end):
        insn = line.insn

        for operand in insn.operands:

            if not operand.type.has_phrase:
                continue

            if not operand.base:
                continue

            register_name = operand.base
            registers[register_name] += 1

    return max(registers.iteritems(), key=operator.itemgetter(1))[0]

def j1_2(a=1):

    def lhs(x):
        return np.exp(-a*x)

    def rhs(b):
        return (np.sqrt(b**2 + a**2) - a)/(b*np.sqrt(b**2 + a**2))

    return Ghosh('j1', lhs, rhs)

def _get_anns_to_remove(in_file):
    to_remove = ["ANN", "LOF"]
    to_remove_str = tuple(["##INFO=<ID=%s" % x for x in to_remove])
    cur_remove = []
    with utils.open_gzipsafe(in_file) as in_handle:
        for line in in_handle:
            if not line.startswith("#"):
                break
            elif line.startswith(to_remove_str):
                cur_id = line.split("ID=")[-1].split(",")[0]
                cur_remove.append("INFO/%s" % cur_id)
    return ",".join(cur_remove)

def get_file(self, latitude, longitude):
