      print(pants_version())
    elif isinstance(self._help_request, OptionsHelp):
      self._print_options_help()
    elif isinstance(self._help_request, GoalsHelp):
      self._print_goals_help()
    elif isinstance(self._help_request, UnknownGoalHelp):
