def get_levenshtein(first, second):
    if not first:
        return len(second)

    if not second:
        return len(first)

    prev_distances = range(0, len(second) + 1)
    curr_distances = None

    # Find the minimum edit distance between each substring of 'first' and
    # the entirety of 'second'. The first column of each distance list is
    # the distance from the current string to the empty string.
    for first_idx, first_char in enumerate(first, start=1):
        # Keep only the previous and current rows of the
        # lookup table in memory
        curr_distances = [first_idx]

        for second_idx, second_char in enumerate(second, start=1):
            # Take the max of the neighbors
            compare = [
                prev_distances[second_idx - 1],
                prev_distances[second_idx],
                curr_distances[second_idx - 1],
            ]

            distance = min(*compare)

            if first_char != second_char:
                distance += 1

            curr_distances.append(distance)

        prev_distances = curr_distances

    return curr_distances[-1]

def _genKeysBins(self):
        binlimits = self._binlimits

        allowedKeys = []
        midbinlimits = binlimits

        if binlimits[0] == -float('inf'):
            midbinlimits = binlimits[1:]  # remove the bottom limit
            allowedKeys.append('<{0}'.format(midbinlimits[0]))

        if binlimits[-1] == float('inf'):
            midbinlimits = midbinlimits[:-1]

        lastbin = midbinlimits[0]

        for binlimit in midbinlimits[1:]:
            if lastbin == binlimit:
                allowedKeys.append('{0}'.format(binlimit))
            else:
                allowedKeys.append('{0} to {1}'.format(lastbin, binlimit))
            lastbin = binlimit

        if binlimits[-1] == float('inf'):
            allowedKeys.append('{0}+'.format(binlimits[-2]))

        allowedKeys.append('Uncertain')
        self._allowedKeys = allowedKeys

def filter(self, cls_or_collection, query, raw=False, only=None):

        if not isinstance(cls_or_collection, six.string_types):
            collection = self.get_collection_for_cls(cls_or_collection)
            cls = cls_or_collection
        else:
            collection = cls_or_collection
            cls = self.get_cls_for_collection(collection)

        canonical_query = self._canonicalize_query(query)

        args = {}

        if only:
            if isinstance(only,tuple):
                args['projection'] = list(only)
            else:
                args['projection'] = only

        return QuerySet(self, cls, self.db[collection].find(canonical_query, **args), raw=raw, only=only)

