def commit():

    session_token = request.headers['session_token']
    repository    = request.headers['repository']

    #===
    current_user = have_authenticated_user(request.environ['REMOTE_ADDR'], repository, session_token)
    if current_user is False: return fail(user_auth_fail_msg)

    #===
    repository_path = config['repositories'][repository]['path']

    def with_exclusive_lock():
        if not varify_user_lock(repository_path, session_token): return fail(lock_fail_msg)

        #===
        data_store = versioned_storage(repository_path)
        if not data_store.have_active_commit(): return fail(no_active_commit_msg)

        result = {}
        if request.headers['mode'] == 'commit':
            new_head = data_store.commit(request.headers['commit_message'], current_user['username'])
            result = {'head' : new_head}
        else:
            data_store.rollback()

        # Release the user lock
        update_user_lock(repository_path, None)
        return success(result)
    return lock_access(repository_path, with_exclusive_lock)

def _process_server_headers(
        self, key: Union[str, bytes], headers: httputil.HTTPHeaders
    ) -> None:
        assert headers["Upgrade"].lower() == "websocket"
        assert headers["Connection"].lower() == "upgrade"
        accept = self.compute_accept_value(key)
        assert headers["Sec-Websocket-Accept"] == accept

        extensions = self._parse_extensions_header(headers)
        for ext in extensions:
            if ext[0] == "permessage-deflate" and self._compression_options is not None:
                self._create_compressors("client", ext[1])
            else:
                raise ValueError("unsupported extension %r", ext)

        self.selected_subprotocol = headers.get("Sec-WebSocket-Protocol", None)

def _should_skip_region(self, region_start):

        obj = self.project.loader.find_object_containing(region_start, membership_check=False)
        if obj is None:
            return False
        if isinstance(obj, PE):
            section = obj.find_section_containing(region_start)
            if section is None:
                return False
            if section.name in {'.textbss'}:
                return True

        return False

def inline_map_reduce(self, map, reduce, full_response=False, **kwargs):
        cmd = SON([("mapreduce", self.__name),
                   ("map", map),
                   ("reduce", reduce),
                   ("out", {"inline": 1})])
        collation = validate_collation_or_none(kwargs.pop('collation', None))
        cmd.update(kwargs)
        with self._socket_for_reads() as (sock_info, slave_ok):
            if sock_info.max_wire_version >= 4 and 'readConcern' not in cmd:
                res = self._command(sock_info, cmd, slave_ok,
                                    read_concern=self.read_concern,
                                    collation=collation)
            else:
                res = self._command(sock_info, cmd, slave_ok,
                                    collation=collation)

        if full_response:
            return res
        else:
            return res.get("results")

def editPage(self, path, title, content=None, html_content=None,
                 author_name=None, author_url=None, return_content=False):
        if content is None:
            content = html_to_nodes(html_content)
        if path is None:
            raise TelegraphAPIException("Error while executing editPage: "
                                        "PAGE_NOT_FOUND")
        r = requests.post(BASE_URL + "editPage/" + path, data={
            "access_token": self.access_token,
            "title": title,
            "content": json.dumps(content),
            "author_name": author_name,
            "author_url": author_url,
            "return_content": return_content
        })
        if r.json()['ok'] is not True:
            raise TelegraphAPIException("Error while executing editPage: " +
                                        r.json()['error'])
        return r.json()['result']

