def chainable(fn):
    @functools.wraps(fn)
    def wrapper(nxt=lambda x: x):
        if hasattr(nxt, '__call__'):
            return lambda x: nxt(fn(x))
        # Value has been passsed directly, so we don't chain
        return fn(nxt)
    return wrapper

