def get_best_ip(last_ip, next_ip):
    if last_ip is None:
        return next_ip
    if is_public_ip(last_ip) and not is_public_ip(next_ip):
        return last_ip
    if is_private_ip(last_ip) and is_loopback_ip(next_ip):
        return last_ip
    return next_ip

def decompose_select(selectx):
  nix = NameIndexer.ctor_fromlist(selectx.tables)
  where = []
  for fromx in selectx.tables:
    if isinstance(fromx,sqparse2.JoinX) and fromx.on_stmt is not None:
      # todo: what happens if on_stmt columns are non-ambiguous in the context of the join tables but ambiguous overall? yuck.
      where.append(fromx.on_stmt)
  if selectx.where: where.append(selectx.where)
  return nix, where

def failsafe(func):

    @functools.wraps(func)
    def wrapper(*args, **kwargs):
        extra_files = []

        try:
            return func(*args, **kwargs)
        except:
            exc_type, exc_val, exc_tb = sys.exc_info()
            traceback.print_exc()

        tb = exc_tb
        while tb:
            filename = tb.tb_frame.f_code.co_filename
            extra_files.append(filename)
            tb = tb.tb_next

        if isinstance(exc_val, SyntaxError):
            extra_files.append(exc_val.filename)

        app = _FailSafeFlask(extra_files)
        app.debug = True

        @app.route('/')
        @app.route('/<path:path>')
        def index(path='/'):
            reraise(exc_type, exc_val, exc_tb)

        return app

    return wrapper

