def one_phase_dP_acceleration(m, D, rho_o, rho_i):
    G = 4.0*m/(pi*D*D)
    return G*G*(1.0/rho_o - 1.0/rho_i)

def message(self):
        if self.type == 'cleartext':
            return self.bytes_to_text(self._message)

        if self.type == 'literal':
            return self._message.contents

        if self.type == 'encrypted':
            return self._message

def del_properties(self, pathobj, props, recursive):
        if isinstance(props, str):
            props = (props,)

        url = '/'.join([pathobj.drive,
                        'api/storage',
                        str(pathobj.relative_to(pathobj.drive)).strip('/')])

        params = {'properties': ','.join(sorted(props))}

        if not recursive:
            params['recursive'] = '0'

        text, code = self.rest_del(url,
                                   params=params,
                                   auth=pathobj.auth,
                                   verify=pathobj.verify,
                                   cert=pathobj.cert)

        if code == 404 and "Unable to find item" in text:
            raise OSError(2, "No such file or directory: '%s'" % url)
        if code != 204:
            # Raise an error when the server returns an unexpected non-success status code.
            raise RuntimeError(text)

def decode_chain_list(in_bytes):
