def load_plugin(filename, plugin_globals, plugin_locals):

        plugin = open(filename, 'rU')

        try:
            exec(plugin.read(), plugin_globals, plugin_locals)
        except ImportError:
            return False
        except Exception as e:
            raise WidgetPluginError("%s: %s" % (e.__class__, str(e)))
        finally:
