def find_orphans(model):
    exchange = frozenset(model.exchanges)
    return [
        met for met in model.metabolites
        if (len(met.reactions) > 0) and all(
            (not rxn.reversibility) and (rxn not in exchange) and
            (rxn.metabolites[met] < 0) for rxn in met.reactions
        )
    ]

def wrap(self, word, width, hyphen='-'):
        width -= len(hyphen)
        for w1, w2 in self.iterate(word):
            if len(w1) <= width:
                return w1 + hyphen, w2

def _dfs(vertex, vertices_neighbours):
    visited = set()
    to_visit = deque([vertex])
    while to_visit:
        vertex = to_visit.pop()
        if vertex not in visited:
            yield vertex
            visited.add(vertex)
            to_visit.extend(vertices_neighbours[vertex])

def __verify_minion(self, id_, token):
        if not salt.utils.verify.valid_id(self.opts, id_):
            return False
        pub_path = os.path.join(self.opts['pki_dir'], 'minions', id_)

        try:
            pub = salt.crypt.get_rsa_pub_key(pub_path)
        except (IOError, OSError):
            log.warning(
                'Salt minion claiming to be %s attempted to communicate with '
                'master, but key could not be read and verification was denied.',
                id_
            )
            return False
        except (ValueError, IndexError, TypeError) as err:
            log.error('Unable to load public key "%s": %s', pub_path, err)
        try:
            if salt.crypt.public_decrypt(pub, token) == b'salt':
                return True
        except ValueError as err:
            log.error('Unable to decrypt token: %s', err)

        log.error(
            'Salt minion claiming to be %s has attempted to communicate with '
            'the master and could not be verified', id_
        )
        return False

def edit_profile():
    if g.user is None:
        abort(401)
    form = dict(name=g.user.name, email=g.user.email)
