            g.user.email = form['email']
            uid = User.get_collection().save(g.user)
            return redirect(url_for('edit_profile'))
    return render_template('edit_profile.html', form=form)

def _get_minmax_edges(self, edge):
        if isinstance(edge, Line):
            # For instance of line class need to loop over values
            depth_vals = np.array([node.depth for node in edge.points])
        else:
            depth_vals = edge[:, 2]

        temp_upper_depth = np.min(depth_vals)
        if not self.upper_depth:
            self.upper_depth = temp_upper_depth
        else:
            if temp_upper_depth < self.upper_depth:
                self.upper_depth = temp_upper_depth

        temp_lower_depth = np.max(depth_vals)
        if not self.lower_depth:
            self.lower_depth = temp_lower_depth
        else:
            if temp_lower_depth > self.lower_depth:
                self.lower_depth = temp_lower_depth

def verify_enroll(self, response):

        seed = session.pop('_u2f_enroll_')
        try:
            new_device, cert = complete_register(seed, response, self.__facets_list)
        except Exception as e:
            if self.__call_fail_enroll:
                self.__call_fail_enroll(e)

            return {
                'status' : 'failed', 
                'error'  : 'Invalid key handle!'
            }

        finally:
            pass



        devices = self.__get_u2f_devices()

        # Setting new device counter to 0
        new_device['counter'] = 0
        new_device['index']   = 0

        for device in devices:
            if new_device['index'] <= device['index']:
                new_device['index'] = device['index'] + 1

        devices.append(new_device)

        self.__save_u2f_devices(devices)

        self.__call_success_enroll()

        return {'status': 'ok', 'message': 'Successfully enrolled new U2F device!'}

def as_dataframe(self, fillna=True, subjects=None):
        entries = []
        selected_subjects = self.subjects
        if subjects is not None:
            selected_subjects = subjects

        for s in selected_subjects:
            vmap = {}
            for c in self.inferred_types(s):
                vmap[c] = 1
            entries.append(vmap)
        logging.debug("Creating DataFrame")
        df = pd.DataFrame(entries, index=selected_subjects)
        if fillna:
            logging.debug("Performing fillna...")
            df = df.fillna(0)
        return df

