def denomination(value, min_nominal=None):
    if value is None or (hasattr(value, 'isNull') and value.isNull()):
        return None, None

    if not value:
        return value, None

    if abs(value) == list(nominal_mapping.keys())[0] and not min_nominal:
        return 1 * value, nominal_mapping[list(nominal_mapping.keys())[0]]

    # we need minimum value of denomination because we don't want to show
    # '2 ones', '3 tens', etc.
    index = 0
    if min_nominal:
        index = int(ceil(log(min_nominal, 10)))

    iterator = list(zip(list(nominal_mapping.keys())[
                    index:], list(nominal_mapping.keys())[index + 1:]))
    for min_value, max_value in iterator:

        if min_value <= abs(value) < max_value:
            return float(value) / min_value, nominal_mapping[min_value]
        elif abs(value) < min_value:
            return float(value), None

    max_value = list(nominal_mapping.keys())[-1]
    new_value = float(value) / max_value
    new_unit = nominal_mapping[list(nominal_mapping.keys())[-1]]
    return new_value, new_unit

def validate_string_dict(dct):
    for k,v in dct.iteritems():
        if not isinstance(k, basestring):
            raise ValueError('key %r in dict must be a string' % k)
        if not isinstance(v, basestring):
            raise ValueError('value %r in dict must be a string' % v)

def cachedproperty(func):
    key = '_' + func.__name__
    @wraps(func)
    def get(self):
        try:
            return getattr(self, key)
        except AttributeError:
            val = func(self)
            setattr(self, key, val)
            return val
    return property(get)

def call_at_most_every(seconds, count=1):
  def decorator(func):
    try:
      call_history = getattr(func, '_call_history')
    except AttributeError:
      call_history = collections.deque(maxlen=count)
      setattr(func, '_call_history', call_history)

    @functools.wraps(func)
    def _wrapper(*args, **kwargs):
      current_time = time.time()
      window_count = sum(ts > current_time - seconds for ts in call_history)
      if window_count >= count:
        # We need to sleep until the relevant call is outside the window.  This
        # should only ever be the the first entry in call_history, but if we
        # somehow ended up with extra calls in the window, this recovers.
        time.sleep(call_history[window_count - count] - current_time + seconds)
      # Append this call, deque will automatically trim old calls using maxlen.
      call_history.append(time.time())
      return func(*args, **kwargs)
    return _wrapper
  return decorator

