            self.controllers.pop(uid)
            tmp = Event(uid, E_DISCONNECT)
            self.queue.put_nowait(tmp)
        except KeyError:
            # There is no such controller, ignore the command
            pass

def load_class(self, classname):

        module_list = self._get_module_list()

        for module in module_list:
            try:
                return import_class(classname, module.__name__)
            except (AttributeError, ImportError):
                pass

        raise ImportError("Class '{0}' could not be loaded.".format(classname))

async def unicode_type(self, elem):
        if self.writing:
            await dump_uvarint(self.iobj, len(elem))
            await self.iobj.awrite(bytes(elem, 'utf8'))

        else:
            ivalue = await load_uvarint(self.iobj)
            if ivalue == 0:
                return ''

            fvalue = bytearray(ivalue)
            await self.iobj.areadinto(fvalue)
            return str(fvalue, 'utf8')

