        try:
            return {
                'ACCOUNT_EXPIRED': request.user.userplan.is_expired(),
                'ACCOUNT_NOT_ACTIVE': (
                not request.user.userplan.is_active() and not request.user.userplan.is_expired()),
                'EXPIRE_IN_DAYS': request.user.userplan.days_left(),
                'EXTEND_URL': reverse('current_plan'),
                'ACTIVATE_URL': reverse('account_activation'),
            }
        except UserPlan.DoesNotExist:
            pass
    return {}

def add_domain(db, organization, domain, is_top_domain=False, overwrite=False):
    with db.connect() as session:
        org = find_organization(session, organization)

        if not org:
            raise NotFoundError(entity=organization)

        dom = find_domain(session, domain)

        if dom and not overwrite:
            raise AlreadyExistsError(entity='Domain', eid=dom.domain)
        elif dom:
            delete_domain_db(session, dom)

        try:
            add_domain_db(session, org, domain,
                          is_top_domain=is_top_domain)
        except ValueError as e:
            raise InvalidValueError(e)

def getfile(url, outdir=None):
    fn = os.path.split(url)[-1]
    if outdir is not None:
        fn = os.path.join(outdir, fn)
    if not os.path.exists(fn):
        #Find appropriate urlretrieve for Python 2 and 3
        try:
            from urllib.request import urlretrieve
        except ImportError:
            from urllib import urlretrieve 
        print("Retrieving: %s" % url)
        #Add progress bar
        urlretrieve(url, fn)
    return fn

def update_window(turn_from, tick_from, turn_to, tick_to, updfun, branchd):
    if turn_from in branchd:
        # Not including the exact tick you started from because deltas are *changes*
        for past_state in branchd[turn_from][tick_from+1:]:
            updfun(*past_state)
    for midturn in range(turn_from+1, turn_to):
        if midturn in branchd:
            for past_state in branchd[midturn][:]:
                updfun(*past_state)
    if turn_to in branchd:
        for past_state in branchd[turn_to][:tick_to+1]:
            updfun(*past_state)

