def to_json(self, filename=None):
        # Define a helper to serialize complex objects for JSON output.
        def json_encoder(obj):
            if isinstance(obj, pd.DataFrame) or isinstance(obj, pd.Series):
                if isinstance(obj.index, pd.core.index.MultiIndex):
                    obj = obj.reset_index()  # convert MultiIndex to columns

                return json.loads(obj.to_json(date_format='iso'))
            elif isinstance(obj, melodist.cascade.CascadeStatistics):
                return obj.__dict__
            elif isinstance(obj, np.ndarray):
                return obj.tolist()
            else:
                raise TypeError('%s not supported' % type(obj))

        d = dict(
            temp=self.temp,
            wind=self.wind,
            precip=self.precip,
            hum=self.hum,
            glob=self.glob
        )

        j = json.dumps(d, default=json_encoder, indent=4)

        if filename is None:
            return j
        else:
            with open(filename, 'w') as f:
                f.write(j)

def output_to_terminal(sources):
    results = OrderedDict()
    for source in sources:
        if source.get_is_available():
            source.update()
            results.update(source.get_summary())
    for key, value in results.items():
        sys.stdout.write(str(key) + ": " + str(value) + ", ")
    sys.stdout.write("\n")
    sys.exit()

def enable_repositories(self, repositories):
        for r in repositories:
            if r['type'] != 'rhsm_channel':
                continue
            if r['name'] not in self.rhsm_channels:
                self.rhsm_channels.append(r['name'])

        if self.rhsm_active:
            subscription_cmd = "subscription-manager repos '--disable=*' --enable=" + ' --enable='.join(
                self.rhsm_channels)
            self.run(subscription_cmd)

        repo_files = [r for r in repositories if r['type'] == 'yum_repo']
        for repo_file in repo_files:
            self.create_file(repo_file['dest'], repo_file['content'])

        packages = [r['name'] for r in repositories if r['type'] == 'package']
        if packages:
            self.yum_install(packages)

