def leaf(self, node, elem, module, path):
        if node.i_default is None:
            nel, newm, path = self.sample_element(node, elem, module, path)
            if path is None:
                return
            if self.annots:
                nel.append(etree.Comment(
                    " type: %s " % node.search_one("type").arg))
        elif self.defaults:
            nel, newm, path = self.sample_element(node, elem, module, path)
            if path is None:
                return
            nel.text = str(node.i_default_str)

def _speak_as(
        self,
        element,
        regular_expression,
        data_property_value,
        operation
    ):

        children = []
        pattern = re.compile(regular_expression)
        content = element.get_text_content()
        while content:
            matches = pattern.search(content)
            if matches is not None:
                index = matches.start()
                children = operation(content, index, children)

                new_index = index + 1
                content = content[new_index:]
            else:
                break
        if children:
            if content:
                children.append(self._create_content_element(
                    content,
                    data_property_value
                ))
            while element.has_children():
                element.get_first_node_child().remove_node()
            for child in children:
                element.append_element(child)

