def delete_config(name, xpath=None, commit=False):
    ret = _default_ret(name)

    if not xpath:
        return ret

    query = {'type': 'config',
             'action': 'delete',
             'xpath': xpath}

    result, response = _validate_response(__proxy__['panos.call'](query))

    ret.update({
        'changes': response,
        'result': result
    })

    if not result:
        return ret

    if commit is True:
        ret.update({
            'commit': __salt__['panos.commit'](),
            'result': True
        })

    return ret

