def loads(data, validate=False, **kwargs):
    d = json.loads(data, **kwargs)
    content_spec = d["content-spec"]
    Payload = CONTENT_SPECS[content_spec]
    payload = Payload.load(d)
    if validate:
        errors = payload.problems()
        if errors:
            raise ValidationError(errors)
    return payload

