def from_dict(data, ctx):

        data = data.copy()

        if data.get('minimumDistance') is not None:
            data['minimumDistance'] = ctx.convert_decimal_number(
                data.get('minimumDistance')
            )

        if data.get('premium') is not None:
            data['premium'] = ctx.convert_decimal_number(
                data.get('premium')
            )

        if data.get('levelRestriction') is not None:
            data['levelRestriction'] = \
                ctx.primitives.GuaranteedStopLossOrderLevelRestriction.from_dict(
                    data['levelRestriction'], ctx
                )

        return GuaranteedStopLossOrderEntryData(**data)

def calculate_P(self, T, P, method):
        if method == EOS:
            self.eos[0] = self.eos[0].to_TP(T=T, P=P)
            Vm = self.eos[0].V_g
        elif method == TSONOPOULOS_EXTENDED:
            B = BVirial_Tsonopoulos_extended(T, self.Tc, self.Pc, self.omega, dipole=self.dipole)
            Vm = ideal_gas(T, P) + B
        elif method == TSONOPOULOS:
            B = BVirial_Tsonopoulos(T, self.Tc, self.Pc, self.omega)
            Vm = ideal_gas(T, P) + B
        elif method == ABBOTT:
            B = BVirial_Abbott(T, self.Tc, self.Pc, self.omega)
            Vm = ideal_gas(T, P) + B
        elif method == PITZER_CURL:
            B = BVirial_Pitzer_Curl(T, self.Tc, self.Pc, self.omega)
            Vm = ideal_gas(T, P) + B
        elif method == CRC_VIRIAL:
            a1, a2, a3, a4, a5 = self.CRC_VIRIAL_coeffs
            t = 298.15/T - 1.
            B = (a1 + a2*t + a3*t**2 + a4*t**3 + a5*t**4)/1E6
            Vm = ideal_gas(T, P) + B
        elif method == IDEAL:
            Vm = ideal_gas(T, P)
        elif method == COOLPROP:
            Vm = 1./PropsSI('DMOLAR', 'T', T, 'P', P, self.CASRN)
        elif method in self.tabular_data:
            Vm = self.interpolate_P(T, P, method)
        return Vm

def handle_change(self, change):
        op = change['operation']
        if op in 'append':
            self.add(len(change['value']), LatLng(*change['item']))
        elif op == 'insert':
            self.add(change['index'], LatLng(*change['item']))
        elif op == 'extend':
            points = [LatLng(*p) for p in change['items']]
            self.addAll([bridge.encode(c) for c in points])
        elif op == '__setitem__':
            self.set(change['index'], LatLng(*change['newitem']))
        elif op == 'pop':
            self.remove(change['index'])
        else:
            raise NotImplementedError(
                "Unsupported change operation {}".format(op))

def data_received(self, data):
        try:
            self.data_received_count += 1
            while data:
                consumer = self.current_consumer()
                if not consumer.request:
                    consumer.start()
                toprocess = consumer.feed_data(data)
                consumer.fire_event('data_processed', data=data, exc=None)
                data = toprocess
            self.changed()
        except Exception:
            if self.transport:
                self.transport.abort()
            raise

def _transliterate (self, text, outFormat):
        result = []
        text = self._preprocess(text)
        i = 0
        while i < len(text):
            if text[i].isspace(): 
                result.append(text[i])
                i = i+1
            else: 
                chr = self._getNextChar(text, i)
                try:
                    result.append(self[chr].unichr)
                except KeyError:
                    result.append(_unrecognised(chr))
                i = i + len(chr)
        return result

def _roll_negative_time_fields(year, month, day, hour, minute, second):
    if second < 0:
        minute += int(second / 60.0)  # Adjust by whole minute in secs
        minute -= 1  # Subtract 1 for negative second
        second %= 60  # Convert negative second to positive remainder
    if minute < 0:
        hour += int(minute / 60.0)  # Adjust by whole hour in minutes
        hour -= 1  # Subtract 1 for negative minutes
        minute %= 60  # Convert negative minute to positive remainder
    if hour < 0:
        day += int(hour / 24.0)  # Adjust by whole day in hours
        day -= 1  # Subtract 1 for negative minutes
        hour %= 24  # Convert negative hour to positive remainder
    if day < 0:
        month += int(day / 30.0)  # Adjust by whole month in days (assume 30)
        month -= 1  # Subtract 1 for negative minutes
        day %= 30  # Convert negative day to positive remainder
    if month < 0:
        year += int(month / 12.0)  # Adjust by whole year in months
        year -= 1  # Subtract 1 for negative minutes
        month %= 12  # Convert negative month to positive remainder
    return (year, month, day, hour, minute, second)

def apply_transforms(samples, transforms, inverse=False):
    if inverse:
        transforms = transforms[::-1]
    for t in transforms:
        try:
            if inverse:
                samples = t.inverse_transform(samples)
            else:
                samples = t.transform(samples)
        except NotImplementedError:
            continue
    return samples

