def check(frame) -> None:
        # The first parameter is called `frame` rather than `self`,
        # but it's the instance of class to which this method is bound.

        if frame.rsv1 or frame.rsv2 or frame.rsv3:
            raise WebSocketProtocolError("Reserved bits must be 0")

        if frame.opcode in DATA_OPCODES:
            return
        elif frame.opcode in CTRL_OPCODES:
            if len(frame.data) > 125:
                raise WebSocketProtocolError("Control frame too long")
            if not frame.fin:
                raise WebSocketProtocolError("Fragmented control frame")
        else:
            raise WebSocketProtocolError(f"Invalid opcode: {frame.opcode}")

def sigquit_handler(sig, frame):
    print("Dumping stack traces for all threads in PID {}".format(os.getpid()))
    id_to_name = dict([(th.ident, th.name) for th in threading.enumerate()])
    code = []
    for thread_id, stack in sys._current_frames().items():
        code.append("\n# Thread: {}({})"
                    .format(id_to_name.get(thread_id, ""), thread_id))
        for filename, line_number, name, line in traceback.extract_stack(stack):
            code.append('File: "{}", line {}, in {}'
                        .format(filename, line_number, name))
            if line:
                code.append("  {}".format(line.strip()))
    print("\n".join(code))

def eigenvectors(T, k=None, right=True, ncv=None, reversible=False, mu=None):
    T = _types.ensure_ndarray_or_sparse(T, ndim=2, uniform=True, kind='numeric')
    if _issparse(T):
        if right:
            return sparse.decomposition.eigenvectors(T, k=k, right=right, ncv=ncv)
        else:
            return sparse.decomposition.eigenvectors(T, k=k, right=right, ncv=ncv).T

    else:
        if right:
            return dense.decomposition.eigenvectors(T, k=k, right=right)
        else:
            return dense.decomposition.eigenvectors(T, k=k, right=right).T

def __GetInstances(self, group_name = None, state_filter=None):
    all_instances = self.ec2.get_all_instances()
    instances = []
    for res in all_instances:
      for group in res.groups:
        if group_name and group.name != group_name:
          continue
        for instance in res.instances:
          if state_filter == None or instance.state == state_filter:
            instances.append(instance)
    return instances

def build_includes(cls, include_packages):
        includes, package_root_paths = cls._split_packages(include_packages)
        for package_path, package_name in six.iteritems(package_root_paths):
            includes.add(package_name)
            if re.search(r'__init__.py.*$', package_path):
                # Looks like a package.  Walk the directory and see if there are more.
                package_modules = set()
                for root, dirs, files in os.walk(os.path.dirname(package_path)):
                    if '__init__.py' in files:
                        package_modules.add(root)
                        for module in [f for f in files if f != u"__init__.py" and f.endswith('.py')]:
                            package_modules.add(os.path.join(root, module))

                common_prefix = os.path.commonprefix(package_modules)
                common_dir = os.path.dirname(common_prefix)
                package_tails = set([f[len(common_dir) + len(os.sep):] for f in package_modules])
                package_names = set([os.path.splitext(tail)[0].replace(os.sep, '.') for tail in package_tails])
                includes |= package_names
        return includes

def get_decision(self, child, is_missing = False):
        # Child does exist and there is a path to the child.
        value = self.value
        feature = self.split_feature_column
        index = self.split_feature_index

        if not is_missing:
            if self.left_id == child.node_id:
                if self.node_type in ["float", "integer"]:
                    sign = "<"
                else:
                    sign = "="
            else:
                if self.node_type in ["float", "integer"]:
                    sign = ">="
                else:
                    sign = "!="
        else:
            sign = "missing"
            value = None

        return {
            "node_id"    : self.node_id,
            "node_type"  : self.node_type,
            "feature"    : feature,
            "index"      : index,
            "sign"       : sign,
            "value"      : value,
            "child_id"   : child.node_id,
            "is_missing" : is_missing
        }

