def return_false_on_exception(func):
    @wraps(func)
    def exceptfalse(*args, **kwargs):
        if not kwargs.pop('raise_exceptions', False):
            try:
                return func(*args, **kwargs)
            except Exception:
                return False
        else:
            return func(*args, **kwargs)
    return exceptfalse

def split_title(self, title, splitter):
        large_text_length = 0
        large_text_index = 0
        title_pieces = splitter.split(title)

        # find the largest title piece
        for i in range(len(title_pieces)):
            current = title_pieces[i]
            if len(current) > large_text_length:
                large_text_length = len(current)
                large_text_index = i

        # replace content
        title = title_pieces[large_text_index]
        return TITLE_REPLACEMENTS.replaceAll(title).strip()

def _compute_anom_score_between_two_windows(self, i):
        lag_window_chunk_dict = self.lag_dicts[i]
        future_window_chunk_dict = self.fut_dicts[i]
        score = 0
        for chunk in lag_window_chunk_dict:
            if chunk in future_window_chunk_dict:
                score += math.pow(future_window_chunk_dict[chunk] - lag_window_chunk_dict[chunk], 2)
            else:
                score += math.pow(lag_window_chunk_dict[chunk], 2)
        for chunk in future_window_chunk_dict:
            if chunk not in lag_window_chunk_dict:
                score += math.pow(future_window_chunk_dict[chunk], 2)
        return score

def fromfile(self, path_to_file, mimetype=None):

        if os.path.isfile(path_to_file):

            # Load file into self.__content__
            self.filename = os.path.basename(path_to_file)
            with open(path_to_file, "rb") as in_file:
                self.content = in_file.read()

            #guess mime-type
            self.properties.content_settings = ContentSettings()

            if mimetype is None:
                mimetype = guess_type(path_to_file)
                if mimetype[0] is None:
                    mimetype = 'application/octet-stream'
                else: 
                    if not mimetype[1] is None:
                        self.properties.content_settings.content_encoding = mimetype[1]
                    mimetype = mimetype[0]

            self.properties.content_settings.content_type = mimetype

        else:
            raise AzureStorageWrapException(self, 'Can not load blob content, because given path is not a local file')

def validate_key(key, sign=False, encrypt=False):
    if key.revoked:
        raise GPGProblem('The key "{}" is revoked.'.format(key.uids[0].uid),
                         code=GPGCode.KEY_REVOKED)
    elif key.expired:
        raise GPGProblem('The key "{}" is expired.'.format(key.uids[0].uid),
                         code=GPGCode.KEY_EXPIRED)
    elif key.invalid:
        raise GPGProblem('The key "{}" is invalid.'.format(key.uids[0].uid),
                         code=GPGCode.KEY_INVALID)
    if encrypt and not key.can_encrypt:
        raise GPGProblem(
            'The key "{}" cannot be used to encrypt'.format(key.uids[0].uid),
            code=GPGCode.KEY_CANNOT_ENCRYPT)
    if sign and not key.can_sign:
        raise GPGProblem(
            'The key "{}" cannot be used to sign'.format(key.uids[0].uid),
            code=GPGCode.KEY_CANNOT_SIGN)

def LockFile(path, blocking=False):
  fd = os.open(path, os.O_CREAT)
  try:
    Lock(fd, path, blocking)
    yield
  finally:
    try:
      Unlock(fd, path)
    finally:
      os.close(fd)

