def random(cls, length, bit_prob=.5):

        assert isinstance(length, int) and length >= 0
        assert isinstance(bit_prob, (int, float)) and 0 <= bit_prob <= 1

        bits = 0
        for _ in range(length):
            bits <<= 1
            bits += (random.random() < bit_prob)

        return cls(bits, length)

