def cf_tokenize(s):
    t = []
    parts = split_re.split(s)
    for part in parts:
        cf_func = replace_re.search(part)
        if cf_func:
            args = [a.strip("'\" ") for a in cf_func.group("args").split(",")]
            t.append(HELPERS[cf_func.group("helper")](*args).data)
        else:
            t.append(part)
    return t

def next(self):
        try:
            raw_msg = self._socket.recv()
        except KeyboardInterrupt:
            raise StopIteration()
        msg, topic_name = self._strip_topic_name_if_not_wildcard(raw_msg)
        if msg is None:
            return self.next()
        # Selects the return format based on whether the callback requires the topic name.
        if self._user_callback_takes_topic_name:
            return (self.deserialize(msg), topic_name)
        else:
            return self.deserialize(msg)

