def has_state_changed(self):
        self.lastcheck = time.time()
        # prefer offline state change detection:
        if self.detector.can_detect_offline():
            self.detector.detect()
        elif not self.dns.detect() == self.detector.get_current_value():
            # The following produces traffic, but probably less traffic
            # overall than the detector
            self.detector.detect()

        if self.detector.has_changed():
            LOG.debug("detector changed")
            return True
        elif self.dns.has_changed():
            LOG.debug("dns changed")
            return True

        return False

def beacon(config):
    ret = []

    _config = {}
    list(map(_config.update, config))

    for backend in _config.get('backends', ()):
        backend_config = _config['backends'][backend]
        threshold = backend_config['threshold']
        for server in backend_config['servers']:
            scur = __salt__['haproxy.get_sessions'](server, backend)
            if scur:
                if int(scur) > int(threshold):
                    _server = {'server': server,
                               'scur': scur,
                               'threshold': threshold,
                               }
                    log.debug('Emit because %s > %s'
                              ' for %s in %s', scur,
                                               threshold,
                                               server,
                                               backend)
                    ret.append(_server)
    return ret

