def abort_now ():
    if os.name == 'posix':
        # Unix systems can use signals
        import signal
        os.kill(os.getpid(), signal.SIGTERM)
        time.sleep(1)
        os.kill(os.getpid(), signal.SIGKILL)
    elif os.name == 'nt':
        # NT has os.abort()
        os.abort()
    else:
        # All other systems have os._exit() as best shot.
        os._exit(3)

def pre_step(self, ctxt, step, idx):

        debugger = ExtensionDebugger('pre_step')

        for ext in self.exts:
            with debugger(ext):
                if ext.pre_step(ctxt, step, idx):
                    # Step must be skipped
                    debugger.debug(3, 'Skipping step %d' % idx)
                    return True

        return False

def normalize_digits_only(number, keep_non_digits=False):
    number = unicod(number)
    number_length = len(number)
    normalized_digits = U_EMPTY_STRING
    for ii in range(number_length):
        d = unicode_digit(number[ii], -1)
        if d != -1:
            normalized_digits += unicod(d)
        elif keep_non_digits:
            normalized_digits += number[ii]
    return normalized_digits

