    _ = biomfile.pa()
    for sid in biomfile.ids():
        for otuid in biomfile.ids("observation"):
            if biomfile.get_value_by_ids(otuid, sid) == 1:
                samples[sid].add(otuid)
    return samples

def _evaluate(self,R,z,phi=0.,t=0.):
        if self.alpha == 0.:
            return 1./2.*nu.log(R**2.+z**2./self.q2+self.core2)
        else:
            m2= self.core2+R**2.+z**2./self.q2
            return -m2**(-self.alpha/2.)/self.alpha

