def default_value(self, type_name):
        uname = type_name.upper()
        if   uname == 'BOOLEAN':
            return False

        elif uname == 'INTEGER':
            return 0

        elif uname == 'REAL':
            return 0.0

        elif uname == 'STRING':
            return ''

        elif uname == 'UNIQUE_ID':
            if self.metamodel:
                return next(self.metamodel.id_generator)
            else:
                return None
        else:
            raise MetaException("Unknown type named '%s'" % type_name)

def _delete_signature(self, script, sig_blob):
        subscript = self.ScriptTools.compile_push_data_list([sig_blob])
        new_script = bytearray()
        pc = 0
        for opcode, data, pc, new_pc in self.ScriptTools.get_opcodes(script):
            section = script[pc:new_pc]
            if section != subscript:
                new_script.extend(section)
        return bytes(new_script)

def copy(self):
        attrs = {k: self.__dict__[k].copy() for k in self.containers}
        attrs.update({k: cp.deepcopy(self.__dict__[k]) for k in self.shared})
        return self.__class__(**attrs)

