def decompress(data, compression, width, height, depth, version=1):
    length = width * height * depth // 8

    result = None
    if compression == Compression.RAW:
        result = data[:length]
    elif compression == Compression.PACK_BITS:
        result = decode_packbits(data, height, version)
    elif compression == Compression.ZIP:
        result = zlib.decompress(data)
    else:
        decompressed = zlib.decompress(data)
        result = decode_prediction(decompressed, width, height, depth)

    assert len(result) == length, 'len=%d, expected=%d' % (
        len(result), length
    )

    return result

def register(Class, CommandSubClass):
        for name in [CommandSubClass.name()] + CommandSubClass.aliases():
            if name in Class._registered_commands[Class]:
                raise ValueError("Command already exists: " + name)
            Class._registered_commands[Class][name] = CommandSubClass
        return CommandSubClass

