def get_items(self, category=CATEGORY_EVENT, offset=REMO_DEFAULT_OFFSET):

        more = True  # There are more items to be processed
        next_uri = None  # URI for the next items page query
        page = ReMoClient.FIRST_PAGE
        page += int(offset / ReMoClient.ITEMS_PER_PAGE)

        if category == CATEGORY_EVENT:
            api = self.api_events_url
        elif category == CATEGORY_ACTIVITY:
            api = self.api_activities_url
        elif category == CATEGORY_USER:
            api = self.api_users_url
        else:
            raise ValueError(category + ' not supported in ReMo')

        while more:
            params = {
                "page": page,
                "orderby": "ASC"
            }

            logger.debug("ReMo client calls APIv2: %s params: %s",
                         api, str(params))

            raw_items = self.fetch(api, payload=params)
            yield raw_items

            items_data = json.loads(raw_items)
            next_uri = items_data['next']

            if not next_uri:
                more = False
            else:
                # https://reps.mozilla.org/remo/api/remo/v1/events/?orderby=ASC&page=269
                parsed_uri = urllib.parse.urlparse(next_uri)
                parsed_params = urllib.parse.parse_qs(parsed_uri.query)
                page = parsed_params['page'][0]

def get_placeholders(template_name):
    dummy_context.template = template.Template("")
    try:
        temp_wrapper = template.loader.get_template(template_name)
    except template.TemplateDoesNotExist:
        return []

    plist, blist = [], []
    temp = temp_wrapper.template
    _placeholders_recursif(temp.nodelist, plist, blist)

    previous = {}
    block_to_remove = []
    for block in blist:
        if block.name in previous:
            if not hasattr(block, 'has_super_var'):
                block_to_remove.append(previous[block.name])
        previous[block.name] = block

    def keep(p):
        return p.found_in_block not in block_to_remove

    placeholders = [p for p in plist if keep(p)]
    names = []
    pfiltered = []
    for p in placeholders:
        if p.ctype not in names:
            pfiltered.append(p)
            names.append(p.ctype)

    return pfiltered

def build_compounds_dict(compounds):
    logger = getLogger(__name__)
    logger.debug("Parsing compounds: {0}".format(compounds))

    parsed_compounds = {}
    for family_info in compounds:
        logger.debug("Parsing entry {0}".format(family_info))
        splitted_family_info = family_info.split(':')
        family_id = splitted_family_info[0]
        logger.debug("Found family {0}".format(family_id))
        parsed_compounds[family_id] = []
        compound_list = splitted_family_info[1].split('|')
        for compound in compound_list:
            compound_id = compound.split('>')[0]
            try:
                compound_score = compound.split('>')[1]
            except IndexError:
                compound_score = None
            parsed_compounds[family_id].append(
                {
                    'variant_id': compound_id,
                    'compound_score': compound_score
                }
            )

    return parsed_compounds

def dhcp_configuration_from_querystring(querystring, option=u'DhcpConfiguration'):

    key_needle = re.compile(u'{0}.[0-9]+.Key'.format(option), re.UNICODE)
    response_values = {}

    for key, value in querystring.items():
        if key_needle.match(key):
            values = []
            key_index = key.split(".")[1]
            value_index = 1
            while True:
                value_key = u'{0}.{1}.Value.{2}'.format(
                    option, key_index, value_index)
                if value_key in querystring:
                    values.extend(querystring[value_key])
                else:
                    break
                value_index += 1
            response_values[value[0]] = values
    return response_values

def get_residuals_update_tile(st, padded_tile):
