def boolean(_object):
    if is_callable(_object):
        _validator = _object

        @wraps(_validator)
        def decorated(value):
            ensure(isinstance(value, bool), "not of type boolean")
            return _validator(value)
        return decorated
    ensure(isinstance(_object, bool), "not of type boolean")

