def get_template_sources(self, template_name, template_dirs=None):
        if ':' not in template_name:
            return []
        app_name, template_name = template_name.split(":", 1)
        template_dir = get_app_template_dir(app_name)
        if template_dir:
            try:
                from django.template import Origin
                origin = Origin(
                    name=join(template_dir, template_name),
                    template_name=template_name,
                    loader=self,
                )
            except (ImportError, TypeError):
                origin = join(template_dir, template_name)
            return [origin]
        return []

def synchronize(klass, names=None):

    # basestring does not exist on Python 3
    try:
        basestring
    except NameError:
        basestring = (str, bytes)

    if isinstance(names, basestring):
        names = names.split()
    for (name, val) in list(klass.__dict__.items()):
        if callable(val) and name != '__init__' and \
                (names is None or name in names):
            # print("synchronizing", name)
            setattr(klass, name, synchronized(val))

def serialize_groups(self, groups):
        rules = []
        for group in groups:
            rules.extend(self.serialize_rules(group.rules))
        # Return the accumulated list of serialized rules for the caller.
        return rules

