def genl_register(ops):
    if ops.co_protocol != NETLINK_GENERIC:
        return -NLE_PROTO_MISMATCH
    if ops.co_hdrsize < GENL_HDRSIZE(0):
        return -NLE_INVAL
    if ops.co_genl is None:
        return -NLE_INVAL

    ops.co_genl.o_cache_ops = ops
    ops.co_genl.o_hdrsize = ops.co_hdrsize - GENL_HDRLEN
    ops.co_genl.o_name = ops.co_msgtypes[0].mt_name
    ops.co_genl.o_id = ops.co_msgtypes[0].mt_id
    ops.co_msg_parser = genl_msg_parser

    err = genl_register_family(ops.co_genl)
    if err < 0:
        return err
    return nl_cache_mngt_register(ops)

def get_digraph(ont, relations=None, writecache=False):
    digraph = networkx.MultiDiGraph()
    logging.info("Getting edges (may be cached)")
    for (s,p,o) in get_edges(ont):
        p = map_legacy_pred(p)
        if relations is None or p in relations:
            digraph.add_edge(o,s,pred=p)
    logging.info("Getting labels (may be cached)")
    for (n,label) in fetchall_labels(ont):
        digraph.add_node(n, **{'label':label})
    return digraph

def _process_css_text(self, css_text, index, rules, head):
        these_rules, these_leftover = self._parse_style_rules(css_text, index)
        rules.extend(these_rules)
        if head is not None and (these_leftover or self.keep_style_tags):
            style = etree.Element("style")
            style.attrib["type"] = "text/css"
            if self.keep_style_tags:
                style.text = css_text
            else:
                style.text = self._css_rules_to_string(these_leftover)
            head.append(style)

def visit_Return(self, node):
        if not node.value:
            # Yielding function can't return values
            return
        for dep_set in self.visit(node.value):
            if dep_set:
                for dep in dep_set:
                    self.result.add_edge(dep, self.current_function)
            else:
                self.result.add_edge(TypeDependencies.NoDeps,
                                     self.current_function)

def sub(cls, *mixins_and_dicts, **values):

        class SubInjector(cls):
            pass

        mixins = [ x for x in mixins_and_dicts if isinstance(x, type) ]
        if mixins:
            SubInjector.__bases__ = tuple(mixins) + SubInjector.__bases__

        dicts = [ x for x in mixins_and_dicts if not isinstance(x, type) ]
        for d in reversed(dicts):
            for k,v in d.items():
                if k not in values:
                    values[k] = v

        for k,v in values.items():
            SubInjector.value(k, v)

        return SubInjector()

def check_class(self, id_, class_, lineno, scope=None, show_error=True):
        assert CLASS.is_valid(class_)
        entry = self.get_entry(id_, scope)
        if entry is None or entry.class_ == CLASS.unknown:  # Undeclared yet
            return True

        if entry.class_ != class_:
            if show_error:
                if entry.class_ == CLASS.array:
                    a1 = 'n'
                else:
                    a1 = ''
                if class_ == CLASS.array:
                    a2 = 'n'
                else:
                    a2 = ''
                syntax_error(lineno, "identifier '%s' is a%s %s, not a%s %s" %
                             (id_, a1, entry.class_, a2, class_))
            return False

        return True

