def add(app: web.Application,
        feature: Any,
        key: Hashable = None,
        exist_ok: bool = False
        ):
    if FEATURES_KEY not in app:
        app[FEATURES_KEY] = dict()

    key = key or type(feature)

    if key in app[FEATURES_KEY]:
        if exist_ok:
            return
        else:
            raise KeyError(f'Feature "{key}" already registered')

    app[FEATURES_KEY][key] = feature

def merge_rest_docs(prnt_doc=None, child_doc=None):
    prnt_sections = parse_rest_doc(prnt_doc)
    child_sections = parse_rest_doc(child_doc)

    header = prnt_sections['']
    prnt_sections.update(child_sections)
    if not child_sections[''].body:
        prnt_sections[''] = header
        if not header.body:
            prnt_sections.popitem(last=False)

    return "\n\n".join(("\n".join((x.header, x.body)) for x in prnt_sections.values())).lstrip()

def nasm_mutable_data_finalizer(env, code, data):

    if env.target.bits == 32:
        get_pc = [
            '\tcall __getpc0',
            '__getpc0:',
            '\tpop %s' % env.OFFSET_REG,
            '\tadd %s, __data - __getpc0' % env.OFFSET_REG,
            '__realstart:',
        ]
    else:
        get_pc = ['\tlea %s, [rel __data]' % env.OFFSET_REG]

    if data or env.buffers:
        return get_pc + code + _pack_data(data)
    else:
        return code

