        elif exists(uri):
            return relpath(uri, self.basedir)

        else:
            return uri

def SpiceUDSTEP(f):

    @functools.wraps(f)
    def wrapping_udstep(x, value):
        result = f(x)
        value[0] = c_double(result)

    return UDSTEP(wrapping_udstep)

