def bm3_dPdV(v, v0, k0, k0p, precision=1.e-5):
    def f_scalar(v, v0, k0, k0p, precision=precision):
        return derivative(bm3_p, v, args=(v0, k0, k0p), dx=v0 * precision)
    f_v = np.vectorize(f_scalar, excluded=[1, 2, 3, 4])
    return f_v(v, v0, k0, k0p, precision=precision)

def _get_list(self, value, context=None):
        log = self._params.get('log', self._discard)
        res = []
        if value is None:
            return res
        if context is None:
            context = self._context
        if isinstance(value, list):
            log.debug("Processing list %s", value)
            for v in value:
                res.extend(self._get_list(v, context=context))
        elif isinstance(value, dict):
            log.debug("Processing dict %s", value)
            for k in value:
                if k in context:
                    res.extend(self._get_list(value[k], context=context))
        else:
            log.debug("Processing value '%s'", value)
            res.append(value)
        return res

