def profiling(self):
        self._log_profiler_started()
        while self.clients:
            try:
                self.profiler.start()
            except RuntimeError:
                pass
            # should sleep.
            yield
            self.profiler.stop()
            result = self.profiler.result()
            data = pack_msg(RESULT, result,
                            pickle_protocol=self.pickle_protocol)
            self._latest_result_data = data
            # broadcast.
            closed_clients = []
            for client in self.clients:
                try:
                    self._send(client, data)
                except socket.error as exc:
                    if exc.errno == EPIPE:
                        closed_clients.append(client)
            del data
            # handle disconnections.
            for client in closed_clients:
                self.disconnected(client)
        self._log_profiler_stopped()

def _get_definition_from_module(definitions_module, symbol):
    path = definitions_module.__file__
    path = path.replace('.pyc', '.py')
    source = open(path, encoding='utf-8').readlines()
    text = None
    for line in source:
        if symbol == line.partition(' ')[0]:
            text = line
            continue
        if text is not None and (line == '' or '=' in line):
            # We found the end of the declaration
            return text
        if text is not None:
            text += line
    # Symbol could not be found
    return None

