def _preprocess_inputs(durations, event_observed, timeline, entry, weights):

    n = len(durations)
    durations = np.asarray(pass_for_numeric_dtypes_or_raise_array(durations)).reshape((n,))

    # set to all observed if event_observed is none
    if event_observed is None:
        event_observed = np.ones(n, dtype=int)
    else:
        event_observed = np.asarray(event_observed).reshape((n,)).copy().astype(int)

    if entry is not None:
        entry = np.asarray(entry).reshape((n,))

    event_table = survival_table_from_events(durations, event_observed, entry, weights=weights)
    if timeline is None:
        timeline = event_table.index.values
    else:
        timeline = np.asarray(timeline)

    return (durations, event_observed, timeline.astype(float), entry, event_table)

def check_sample_files(fam_filename, raw_dirname):
    # Reading the sample identification number from the FAM file
    fam_samples = None
    with open(fam_filename, "r") as i_file:
        fam_samples = {line.split()[1] for line in i_file.read().splitlines()}

    # Checking the files in the raw directory
    sample_files = set()
    all_samples = set()
    for filename in glob.glob(os.path.join(raw_dirname, "*")):
        sample = os.path.splitext(os.path.basename(filename))[0]
        all_samples.add(sample)
        if sample not in fam_samples:
            logger.warning("{}: sample not in FAM file".format(sample))
        else:
            sample_files.add(filename)

    for sample in fam_samples - all_samples:
        logger.warning("{}: sample not in raw directory".format(sample))

    if len(sample_files) == 0:
        raise ProgramError("no sample left for analysis")

    return sample_files

