        return self.groupby(dimensions, container_type=NdLayout, **kwargs)

def namedb_get_account_delta(cur, address, token_type, block_id, vtxindex):
    sql = 'SELECT * FROM accounts WHERE address = ? AND type = ? AND (block_id <= ? OR block_id == ? AND vtxindex <= ?) ORDER BY block_id DESC, vtxindex DESC LIMIT 2;'
    args = (address, token_type, block_id, block_id, vtxindex)

    rows = namedb_query_execute(cur, sql, args)
    data = []
    for r in rows:
        tmp = {}
        tmp.update(r)
        data.append(tmp)

    if len(data) != 2:
        return None

    # the current account state must land on this block_id/vtxindex
    if data[0]['block_id'] != block_id or data[0]['vtxindex'] != vtxindex:
        return None

    return {'current': data[0], 'prior': data[1]}

def from_clock_time(cls, clock_time, epoch):
        clock_time = ClockTime(*clock_time)
        ts = clock_time.seconds % 86400
        nanoseconds = int(1000000000 * ts + clock_time.nanoseconds)
        return Time.from_ticks(epoch.time().ticks + nanoseconds / 1000000000)

def install(path, name=None):
    if name is None:
        name = os.path.splitext(os.path.basename(path))[0]

    callermod = inspect.getmodule(inspect.stack()[1][0])
    name = '%s.%s' % (callermod.__name__, name)

    if name in sys.modules:
        return sys.modules[name]

    if not os.path.isabs(path):
        callerfile = callermod.__file__
        path = os.path.normpath(
            os.path.join(os.path.dirname(callerfile), path)
        )

    sys.modules[name] = mod = load(path, name=name)
    return mod

