        self.stream.write(s)

def setTableType(self, tableType):
        if tableType == self._tableType:
            return

        # clear all the information
        blocked = self.signalsBlocked()

        self.blockAllSignals(True)

        # only clear if necessary
        if self._tableType:
            self.clearAll()

        # update the table type data
        self._tableType = tableType

        if tableType:
            self._tableTypeName = tableType.__name__
        else:
            self._tableTypeName = ''

        self.initializeColumns()
        self.blockAllSignals(blocked)

        if not self.signalsBlocked():
            self.tableTypeChanged.emit()
            self.recordsChanged.emit()

def short(self, url):
        url = self.clean_url(url)
        shorten_url = f'{self.api_url}v1/shorten'
        payload = {
            'domain': getattr(self, 'domain', 'adf.ly'),
            'advert_type': getattr(self, 'type', 'int'),
            'group_id': getattr(self, 'group_id', None),
            'key': self.api_key,
            'user_id': self.user_id,
            'url': url,
        }
        response = self._post(shorten_url, data=payload)
        if not response.ok:
            raise BadAPIResponseException(response.content)

        try:
            data = response.json()
        except json.decoder.JSONDecodeError:
            raise BadAPIResponseException('API response could not be decoded')

        if data.get('errors'):
            errors = ','.join(i['msg'] for i in data['errors'])
            raise ShorteningErrorException(errors)

        if not data.get('data'):
            raise BadAPIResponseException(response.content)

        return data['data'][0]['short_url']

