def k_partitions(collection, k):
    collection = list(collection)
    n = len(collection)

    # Special cases
    if n == 0 or k < 1:
        return []
    if k == 1:
        return [[collection]]

    a = [0] * (n + 1)
    for j in range(1, k + 1):
        a[n - k + j] = j - 1
    return _f(k, n, 0, n, a, k, collection)

def vk_to_character(self, vk, modifiers=[]):
        if vk in self.non_layout_keys:
            # Not a character
            return self.non_layout_keys[vk]
        elif vk in self.layout_specific_keys:
            if 'shift' in modifiers:
                return self.layout_specific_keys[vk][1]
            return self.layout_specific_keys[vk][0]
        else:
            # Invalid vk
            raise ValueError("Invalid scan code: {}".format(vk))

def consumer_commit_for_times(consumer, partition_to_offset, atomic=False):
    no_offsets = set()
    for tp, offset in six.iteritems(partition_to_offset):
        if offset is None:
            logging.error(
                "No offsets found for topic-partition {tp}. Either timestamps not supported"
                " for the topic {tp}, or no offsets found after timestamp specified, or there is no"
                " data in the topic-partition.".format(tp=tp),
            )
            no_offsets.add(tp)
    if atomic and len(no_offsets) > 0:
        logging.error(
            "Commit aborted; offsets were not found for timestamps in"
            " topics {}".format(",".join([str(tp) for tp in no_offsets])),
        )
        return

    offsets_metadata = {
        tp: OffsetAndMetadata(partition_to_offset[tp].offset, metadata=None)
        for tp in six.iterkeys(partition_to_offset) if tp not in no_offsets
    }

    if len(offsets_metadata) != 0:
        consumer.commit(offsets_metadata)

def valence(self):
        # the number of valence of noble gas is 0
        if self.group == 18:
            return (np.nan, 0)

        L_symbols = 'SPDFGHIKLMNOQRTUVWXYZ'
        valence = []
        full_electron_config = self.full_electronic_structure
        for _, l_symbol, ne in full_electron_config[::-1]:
            l = L_symbols.lower().index(l_symbol)
            if ne < (2 * l + 1) * 2:
                valence.append((l, ne))
        if len(valence) > 1:
            raise ValueError("Ambiguous valence")

        return valence[0]

def fill_signed_info(self, signed_info):
        for reference in signed_info.findall(
