def getABFgroups(files):
    children=[]
    groups={}
    for fname in sorted(files):
        if fname.endswith(".abf"):
            if fname.replace(".abf",".TIF") in files: #TODO: cap sensitive
                if len(children):
                    groups[children[0]]=children
                children=[os.path.basename(fname)[:-4]]
            else:
                children.append(os.path.basename(fname)[:-4])
    groups[children[0]]=children
    #print(" -- found %d groups of %d ABFs"%(len(groups),len(files)))
    return groups

def should_set_tablename(cls):
    if (
        cls.__dict__.get('__abstract__', False)
        or not any(isinstance(b, DeclarativeMeta) for b in cls.__mro__[1:])
    ):
        return False

    for base in cls.__mro__:
        if '__tablename__' not in base.__dict__:
            continue

        if isinstance(base.__dict__['__tablename__'], declared_attr):
            return False

        return not (
            base is cls
            or base.__dict__.get('__abstract__', False)
            or not isinstance(base, DeclarativeMeta)
        )

    return True

def itransform_define(transform):
        if transform == 'tanh':
            return np.arctanh
        elif transform == 'exp':
            return np.log
        elif transform == 'logit':
            return Family.logit
        elif transform is None:
            return np.array
        else:
            return None

def zeros_coefs(nmax, mmax, coef_type=scalar):

    if(mmax > nmax):
        raise ValueError(err_msg['nmax_g_mmax'])

    if(coef_type == scalar):
        L = (nmax + 1) + mmax * (2 * nmax - mmax + 1)
        vec = np.zeros(L, dtype=np.complex128)
        return  ScalarCoefs(vec, nmax, mmax)
    elif(coef_type == vector):
        L = (nmax + 1) + mmax * (2 * nmax - mmax + 1)
        vec1 = np.zeros(L, dtype=np.complex128)
        vec2 = np.zeros(L, dtype=np.complex128)
        return  VectorCoefs(vec1, vec2, nmax, mmax)
    else:
        raise TypeError(err_msg['ukn_coef_t'])

