        self._add_gradient_scalar('avg_gradient', scalar_value=avg_gradient)

def blow_out(self,
                 location: Union[types.Location, Well] = None
                 ) -> 'InstrumentContext':
        if location is None:
            if not self._ctx.location_cache:
                raise RuntimeError('No valid current location cache present')
            else:
                location = self._ctx.location_cache.labware  # type: ignore
                # type checked below

        if isinstance(location, Well):
            if location.parent.is_tiprack:
                self._log.warning('Blow_out being performed on a tiprack. '
                                  'Please re-check your code')
            target = location.top()
        elif isinstance(location, types.Location) and not \
                isinstance(location.labware, Well):
            raise TypeError(
                'location should be a Well or None, but it is {}'
                .format(location))
        else:
            raise TypeError(
                'location should be a Well or None, but it is {}'
                .format(location))
        self.move_to(target)
        self._hw_manager.hardware.blow_out(self._mount)
        return self

def decode_body(cls, header, f):
        assert header.packet_type == MqttControlPacketType.pubrel

        decoder = mqtt_io.FileDecoder(mqtt_io.LimitReader(f, header.remaining_len))
        packet_id, = decoder.unpack(mqtt_io.FIELD_U16)

        if header.remaining_len != decoder.num_bytes_consumed:
            raise DecodeError('Extra bytes at end of packet.')

        return decoder.num_bytes_consumed, MqttPubrel(packet_id)

def invoke_function(self, function_name, **function_params):
        url = self.build_url(self._endpoints.get('function').format(function_name))
        response = self.session.post(url, data=function_params)
        if not response:
            return None
        data = response.json()

        error = data.get('error')
        if error is None:
            return data.get('value')
        else:
            raise FunctionException(error)

def list_datastore_full(kwargs=None, call=None, datastore=None):
    if call != 'function':
        raise SaltCloudSystemExit(
            'The list_datastore_full function must be called with '
            '-f or --function.'
        )

    if kwargs:
        datastore = kwargs.get('datastore', None)

    if not datastore:
        raise SaltCloudSystemExit(
            'The list_datastore_full function requires a datastore'
        )

    return {datastore: salt.utils.vmware.list_datastore_full(_get_si(), datastore)}

def curve_primitive(self):
        curve = self.curve
        curve.axis_start = self.helix_start
        curve.axis_end = self.helix_end
        coords = curve.get_coords(
            n_points=(self.num_monomers + 1), spacing=self.minor_rise_per_residue)
        if self.orientation == -1:
            coords.reverse()
        return Primitive.from_coordinates(coords)

def deprecated(message):
    def f__(f):
        def f_(*args, **kwargs):
            from warnings import warn
            warn(message, category=DeprecationWarning, stacklevel=2)
            return f(*args, **kwargs)
        f_.__name__ = f.__name__
        f_.__doc__ = f.__doc__
        f_.__dict__.update(f.__dict__)
        return f_
    return f__

def validate_url_container(container):
    if isinstance(container, basestring):
        url = container
        return validate_url(url)
    elif isinstance(container, dict):
        container = container.itervalues()

    for element in container:
        validate_url_container(element)

def _man_args(self, f):
        argcount = f.func_code.co_argcount

        # account for "self" getting passed to class instance methods
        if isinstance(f, types.MethodType):
            argcount -= 1

        if f.func_defaults is None:
            return argcount

        return argcount - len(f.func_defaults)

