def handle(self, error, connection):
        error_class = error.__class__
        if error_class in (ConnectionExpired, ServiceUnavailable, DatabaseUnavailableError):
            self.deactivate(connection.address)
        elif error_class in (NotALeaderError, ForbiddenOnReadOnlyDatabaseError):
            self.remove_writer(connection.address)

def get_metrics(self):
        if(self.sloc == 0):
            if(self.comments == 0):
                ratio_comment_to_code = 0.00
            else:
                ratio_comment_to_code = 1.00
        else:
            ratio_comment_to_code = float(self.comments) / self.sloc
        metrics = OrderedDict([('sloc', self.sloc), ('comments', self.comments),
                               ('ratio_comment_to_code', round(ratio_comment_to_code, 2))])
        return metrics

def get_next_event(process, queue):
    while True:
        try:
            return queue.get(block=True, timeout=TICK)
        except multiprocessing.queues.Empty:
            if not process.is_alive():
                # There is a possibility that after the last queue.get the
                # process created another event and then died. In that case
                # we want to continue draining the queue.
                try:
                    return queue.get(block=False)
                except multiprocessing.queues.Empty:
                    # If the queue empty we know that there are no more events
                    # and that the process has died.
                    return PROCESS_DEAD_AND_QUEUE_EMPTY

    check.failed('unreachable')

