def is_spark_below_2_2():
    import pyspark
    if(hasattr(pyspark,"version")):
        full_version = pyspark.version.__version__
        # We only need the general spark version (eg, 1.6, 2.2).
        parts = full_version.split(".")
        spark_version = parts[0] + "." + parts[1]
        if(compare_version(spark_version, "2.2")>=0):
            return False
    return True

def _read_mask(self, l, ret, mask='upper'):

        if mask.startswith('u'):
            return

        file = os.path.join(self.__dir, l.chr + ".mask.1bit")

        if not os.path.exists(file):
            return

        data = DNA2Bit._read_1bit_file(file, l)

        d = DNA2Bit._read1bit(data, l)

        if mask.startswith('l'):
            for i in range(0, len(ret)):
                if d[i] == 1:
                    ret[i] = DNA_UC_TO_LC_MAP[ret[i]] #ret[i].lower()
        else:
            # Use N as mask
            for i in range(0, len(ret)):
                if d[i] == 1:
                    ret[i] = DNA_N_UC

