def find_lines(filename, **pattern):
    if exists(filename):
        with file(filename, 'r') as fp:
            for line in fp:
                try:
                    data = json.loads(line)
                except:
                    continue
                matches = True
                for key, value in pattern.iteritems():
                    matches = matches and key in data and data[key] == value
                if matches:
                    yield data

def reduce_to_unit(divider):
    for unit_size in range(1, len(divider) // 2 + 1):
        length = len(divider)
        unit = divider[:unit_size]

        # Ignores mismatches in final characters:
        divider_item = divider[:unit_size * (length // unit_size)]
        if unit * (length // unit_size) == divider_item:
            return unit
    return divider

def _remove_source(self, source_name):

