def set_conditions(self, variables, constraints):
        self._vars, self._constraints = variables, []
        self._constraints_for_var = {}
        vars_constraint_count = {}
        # build constraint objects
        for func, variables, values in constraints:
            c = Constraint(func, variables, values, self._compute_search_spaces(variables))
            self._constraints.append(c)
            for var in variables:
                self._constraints_for_var[var] = self._constraints_for_var.get(var, []) + [c]
                vars_constraint_count[var] = vars_constraint_count.get(var, 0) + 1
        # sort into most constraining first
        self._constraints.sort()

        self._variable_expand_order = tuple(sorted(self._vars.keys(), key=vars_constraint_count.get, reverse=True))

def reorder(self, index, direction):
        columnTitle = self.columnOf(index)
        columnName  = self.columnOrderName(columnTitle)

        if not columnName:
            return

        # grab the table and ensure we have a valid column
        table = self.tableType()
        if not table:
            return

        column = table.schema().column(columnName)
        if not column:
            return

        if direction == Qt.AscendingOrder:
            db_dir = 'asc'
        else:
            db_dir = 'desc'

        order = [(columnName, db_dir)]

        # lookup reference column ordering
        if column.isReference():
            ref = column.referenceModel()
            if ref:
                ref_order = ref.schema().defaultOrder()
                if ref_order:
                    order = [(columnName + '.' + ref_order[0][0], db_dir)]
                    order += ref_order[1:]

        # update the information
        self.clear()
        super(XOrbTreeWidget, self).sortByColumn(index, direction)

        self.setOrder(order)
        self.refresh()

def open(self):
        with open(self.filename, 'rb') as file_open:
            binary = file_open.read()

        try:
            return binary.decode()
        except UnicodeDecodeError:
            encoding = get_encoding(binary)
            try:
                return binary.decode(encoding)
            except LookupError:
                return binary.decode(errors='ignore')
            except:  # pylint: disable=W0702
                open_error(self.filename)
        except:  # pylint: disable=W0702
            open_error(self.filename)

def dplptree2dgparentedtree(self):
        def transform(dplp_tree):
            """Transform a DPLP parse tree into a more conventional parse tree."""
            if isinstance(dplp_tree, basestring) or not hasattr(dplp_tree, 'label'):
                return dplp_tree
            assert len(dplp_tree) == 2, "We can only handle binary trees."

            match = DPLP_REL_RE.match(dplp_tree.label())
            assert match, "Relation '{}' does not match regex '{}'".format(dplp_tree.label(), DPLP_REL_RE)
            left_child_nuc, right_child_nuc, relname = match.groups()
            dplp_tree._label = relname

            for i, child_nuclearity in enumerate([left_child_nuc, right_child_nuc]):
                child = dplp_tree[i]
                dplp_tree[i] = Tree(child_nuclearity, [transform(child)])
            return dplp_tree

        tree = transform(self.parsetree)
        return DGParentedTree.convert(tree)

