def from_string(psd_name, length, delta_f, low_freq_cutoff):

    # check if valid PSD model
    if psd_name not in get_psd_model_list():
        raise ValueError(psd_name + ' not found among analytical '
                         'PSD functions.')

    # if PSD model is in LALSimulation
    if psd_name in get_lalsim_psd_list():
        lalseries = lal.CreateREAL8FrequencySeries(
            '', lal.LIGOTimeGPS(0), 0, delta_f, lal.DimensionlessUnit, length)
        try:
            func = lalsimulation.__dict__[
                                        _name_prefix + psd_name + _name_suffix]
        except KeyError:
            func = lalsimulation.__dict__[_name_prefix + psd_name]
            func(lalseries, low_freq_cutoff)
        else:
            lalsimulation.SimNoisePSD(lalseries, 0, func)
        psd = FrequencySeries(lalseries.data.data, delta_f=delta_f)

    # if PSD model is coded in PyCBC
    else:
        func = pycbc_analytical_psds[psd_name]
        psd = func(length, delta_f, low_freq_cutoff)

    # zero-out content below low-frequency cutoff
    kmin = int(low_freq_cutoff / delta_f)
    psd.data[:kmin] = 0

    return psd

def breadth_first_vertex_order(vertices_resources, nets):
    # Special case: no vertices, just stop immediately
    if len(vertices_resources) == 0:
        return

    # Enumerate the set of nets attached to each vertex
    vertex_neighbours = defaultdict(set)
    for net in nets:
        # Note: Iterating over a Net object produces the set of vertices
        # involved in the net.
        vertex_neighbours[net.source].update(net)
        for sink in net.sinks:
            vertex_neighbours[sink].update(net)

    # Perform a breadth-first iteration over the vertices.
    unplaced_vertices = set(vertices_resources)
    vertex_queue = deque()
    while vertex_queue or unplaced_vertices:
        if not vertex_queue:
            vertex_queue.append(unplaced_vertices.pop())
        vertex = vertex_queue.popleft()

        yield vertex

        vertex_queue.extend(v for v in vertex_neighbours[vertex]
                            if v in unplaced_vertices)
        unplaced_vertices.difference_update(vertex_neighbours[vertex])

