def connectQ2Q(self, fromAddress, toAddress, protocolName, protocolFactory,
                   usePrivateCertificate=None, fakeFromDomain=None,
                   chooser=None):
        if chooser is None:
            chooser = lambda x: x and [x[0]]

        def onSecureConnection(protocol):
            if fakeFromDomain:
                connectFromAddress = Q2QAddress(
                    fakeFromDomain,
                    toAddress.resource
                )
            else:
                connectFromAddress = fromAddress

            return protocol.connect(connectFromAddress, toAddress,
                                    protocolName, protocolFactory,
                                    chooser)

        def onSecureConnectionFailure(reason):
            protocolFactory.clientConnectionFailed(None, reason)
            return reason

        return self.getSecureConnection(
            fromAddress, toAddress,
            port, usePrivateCertificate).addCallback(
            onSecureConnection).addErrback(onSecureConnectionFailure)

def validate_url(url, allowed_response_codes=None):
    allowed_response_codes = [200] if allowed_response_codes is None else allowed_response_codes

    # link calls a js function, do not try to open
    if str(url).startswith('javascript:'):
        return True

    try:
        response = urllib2.urlopen(urllib2.Request(url))
    except urllib2.URLError:
        raise AssertionError('Url was invalid and could not be opened: {url}'.format(url=url))

    if response.code not in allowed_response_codes:
        raise AssertionError('Invalid response code {response_code} from url: {url}'
                             .format(response_code=response.code, url=url))
    return True

