def admin(self, server=None):
        with self.lock:
            if not server:
                self.send('ADMIN')
            else:
                self.send('ADMIN %s' % server)
            rvalue = []
            while self.readable():
                admin_ncodes = '257', '258', '259'
                msg = self._recv(expected_replies=('256',) + admin_ncodes)
                if msg[0] == '256':
                    pass
                elif msg[0]  in admin_ncodes:
                    rvalue.append(' '.join(msg[2:])[1:])

            return rvalue

