def _detect(self):
        results = []
        for c in self.slither.contracts:
            for f in c.functions + c.modifiers:
                if f.contract != c:
                    continue
                unused_return = self.detect_unused_return_values(f)
                if unused_return:
                    info = "{}.{} ({}) does not use the value returned by external calls:\n"
                    info = info.format(f.contract.name,
                                       f.name,
                                       f.source_mapping_str)
                    for node in unused_return:
                        info += "\t-{} ({})\n".format(node.expression, node.source_mapping_str)

                    json = self.generate_json_result(info)
                    self.add_function_to_json(f, json)
                    self.add_nodes_to_json(unused_return, json)
                    results.append(json)

        return results

def search(fcn, x0, incr=0, fac=1.1, maxit=100, analyzer=None):
    # custom return class for result
    class ans(tuple):
        def __new__(cls, interval, nit, fcnval):
            return tuple.__new__(cls, interval)
        def __init__(self, interval, nit, fcnval):
            self.interval = interval
            self.nit = nit 
            self.fcnval = fcnval
    x = x0
    f = fcn(x)
    for nit in range(maxit):
        xo, fo = x, f
        x = xo * fac + incr
        f = fcn(x)
        if analyzer!=None:
            analyzer(x, f)
        if f*fo<=0:
            if numpy.fabs(fo)<=numpy.fabs(f):
                return ans((xo, x), nit=nit + 1, fcnval=(fo, f))
            else:
                return ans((x, xo), nit=nit+1, fcnval=(f, fo))
    raise RuntimeError("unable to bracket root")

