def ensure_unicoded_and_unique(args_list, application):
    unicoded_args = []
    for argument in args_list:
        argument = (six.u(argument)
                    if not isinstance(argument, six.text_type) else argument)
        if argument not in unicoded_args or argument == application:
            unicoded_args.append(argument)
    return unicoded_args

def calculate_sampling_decision(trace_header, recorder, sampling_req):
    if trace_header.sampled is not None and trace_header.sampled != '?':
        return trace_header.sampled
    elif not recorder.sampling:
        return 1
    else:
        decision = recorder.sampler.should_trace(sampling_req)
    return decision if decision else 0

def size_of_generator(generator, memory_efficient=True):
    if memory_efficient:
        counter = 0
        for _ in generator:
            counter += 1
        return counter
    else:
        return len(list(generator))

def _get_secret_with_context(
    filename,
    secret,
    plugin_settings,
    lines_of_context=5,
    force=False,
):
    snippet = CodeSnippetHighlighter().get_code_snippet(
        filename,
        secret['line_number'],
        lines_of_context=lines_of_context,
    )

    try:
        raw_secret_value = get_raw_secret_value(
            snippet.target_line,
            secret,
            plugin_settings,
            filename,
        )

        snippet.highlight_line(raw_secret_value)
    except SecretNotFoundOnSpecifiedLineError:
        if not force:
            raise

        snippet.target_line = colorize(
            snippet.target_line,
            AnsiColor.BOLD,
        )

    return snippet.add_line_numbers()

