def authorizeClientRequest(self, request):
        token = ''
        if self.serverType == 'socket':
            token = self.getSocketServerToken(request)
        elif self.serverType == 'http':
            token = self.getHttpServerToken(request)
        if token != '' and token != None:
            if token in self.__tokens:
                if self.__tokens[token] == 'active':
                    return True, ()
                elif self.__tokens[token] == 'revoked':
                    # token has been revoked
                    return False, (401, self.errorMessages[401], "This token has been revoked!")
            else:
                # token is untrusted/invalid
                return False, (401, self.errorMessages[401], "")
        else:
            # token is required, but none was provided
            return False, (400, self.errorMessages[400], "Authentication required! Client did not provide authentication.")

def get_last_activity(session):
    try:
        return datetime.strptime(session['_session_security'],
                '%Y-%m-%dT%H:%M:%S.%f')
    except AttributeError:
        #################################################################
        # * this is an odd bug in python
        # bug report: http://bugs.python.org/issue7980
        # bug explained here:
        # http://code-trick.com/python-bug-attribute-error-_strptime/
        # * sometimes, in multithreaded enviroments, we get AttributeError
        #     in this case, we just return datetime.now(),
        #     so that we are not logged out
        #   "./session_security/middleware.py", in update_last_activity
        #     last_activity = get_last_activity(request.session)
        #   "./session_security/utils.py", in get_last_activity
        #     '%Y-%m-%dT%H:%M:%S.%f')
        #   AttributeError: _strptime
        #
        #################################################################

        return datetime.now()
    except TypeError:
        return datetime.now()

def freeze(self) -> dict:
        settings = {}
        for key, v in self._h.defaults.items():
            settings[key] = self._unserialize(v.value, v.type)
        if self._parent:
            settings.update(getattr(self._parent, self._h.attribute_name).freeze())
        for key in self._cache():
            settings[key] = self.get(key)
        return settings

def delete_by_id(
            self, application_definition_id, custom_headers=None, raw=False, polling=True, **operation_config):
        raw_result = self._delete_by_id_initial(
            application_definition_id=application_definition_id,
            custom_headers=custom_headers,
            raw=True,
            **operation_config
        )

        def get_long_running_output(response):
            if raw:
                client_raw_response = ClientRawResponse(None, response)
                return client_raw_response

        lro_delay = operation_config.get(
            'long_running_operation_timeout',
            self.config.long_running_operation_timeout)
        if polling is True: polling_method = ARMPolling(lro_delay, **operation_config)
        elif polling is False: polling_method = NoPolling()
        else: polling_method = polling
        return LROPoller(self._client, raw_result, get_long_running_output, polling_method)

