def attach(self, attachments):
        if not is_iterable(attachments, generators_allowed=True):
            attachments = [attachments]
        for tmp in attachments:
            if not tmp.parent_item:
                tmp.parent_item = self
            if self.id and not tmp.attachment_id:
                # Already saved object. Attach the attachment server-side now
                tmp.attach()
            if tmp not in self.attachments:
                self.attachments.append(tmp)

def idxmin(self, **kwargs):
        if self._is_transposed:
            kwargs["axis"] = kwargs.get("axis", 0) ^ 1
            return self.transpose().idxmin(**kwargs)

        axis = kwargs.get("axis", 0)
        index = self.index if axis == 0 else self.columns

        def idxmin_builder(df, **kwargs):
            if axis == 0:
                df.index = index
            else:
                df.columns = index
            return df.idxmin(**kwargs)

        func = self._build_mapreduce_func(idxmin_builder, **kwargs)
        return self._full_axis_reduce(axis, func)

