def _find_mocker(symbol: str, context: 'torment.contexts.TestContext') -> Callable[[], bool]:

    components = []
    method = None

    for component in symbol.split('.'):
        components.append(component.lower())
        name = '_'.join([ 'mock' ] + components)

        if hasattr(context, name):
            method = getattr(context, name)
            break

    if method is None:
        logger.warn('no mocker for %s', symbol)

        def noop(*args, **kwargs):
            return False

        method = noop

    return method

def on_widget__button_press_event(self, widget, event):
        if self.mode == 'register_video' and event.button == 1:
            self.start_event = event.copy()
            return
        elif self.mode == 'control':
            shape = self.canvas.find_shape(event.x, event.y)

            if shape is None: return
            state = event.get_state()
            if event.button == 1:
                # Start a new route.
                self._route = Route(self.device)
                self._route.append(shape)
                self.last_pressed = shape
                if not (state & gtk.gdk.MOD1_MASK):
                    # `<Alt>` key is not held down.
                    self.emit('route-electrode-added', shape)

def list_bindings(site):
    ret = dict()
    sites = list_sites()

    if site not in sites:
        log.warning('Site not found: %s', site)
        return ret

    ret = sites[site]['bindings']

    if not ret:
