def start(self, *_):
        try:
            box_configurations = self.bc_dao.run_query(QUERY_PROCESSES_FOR_BOX_ID(self.box_id))

            for tmp in box_configurations:
                handler = RepeatTimer(TRIGGER_INTERVAL, self.manage_process, args=[tmp.process_name])
                self.thread_handlers[tmp.process_name] = handler
                handler.start()
                self.logger.info('Started Supervisor Thread for {0}, triggering every {1} seconds'
                                 .format(tmp.process_name, TRIGGER_INTERVAL))
