def native(name, ret, interp=None, send_interp=False):
    def native_decorator(func):
        @functools.wraps(func)
        def native_wrapper(*args, **kwargs):
            return func(*args, **kwargs)

        pfp.interp.PfpInterp.add_native(name, func, ret, interp=interp, send_interp=send_interp)
        return native_wrapper
    return native_decorator

def power_chisq_at_points_from_precomputed(corr, snr, snr_norm, bins, indices):
    num_bins = len(bins) - 1
    chisq = shift_sum(corr, indices, bins) # pylint:disable=assignment-from-no-return
    return (chisq * num_bins - (snr.conj() * snr).real) * (snr_norm ** 2.0)

