def multiparse(
    text         = None,
    parsers      = [parse],
    help_message = None
    ):
    responses = []
    for _parser in parsers:
        response = _parser(text = text)
        if response is not False:
            responses.extend(response if response is list else [response])
    if not any(responses):
        if help_message:
            return help_message
        else:
            return False
    else:
        if len(responses) > 1:
            return responses
        else:
            return responses[0]

