def module_summary(self):
        suspicious = 0
        malicious = 0
        count = 0
        cve = False
        taxonomies = []

        for section in self.results:
            if section['submodule_section_content']['class'] == 'malicious':
                malicious += 1
            elif section['submodule_section_content']['class'] == 'suspicious':
                suspicious += 1

            if 'CVE' in section['submodule_section_content']['clsid_description']:
                cve = True
            count += 1

        if malicious > 0:
            taxonomies.append(self.build_taxonomy('malicious', 'FileInfo', 'MaliciousRTFObjects', malicious))

        if suspicious > 0:
            taxonomies.append(self.build_taxonomy('suspicious', 'FileInfo', 'SuspiciousRTFObjects', suspicious))

        if cve:
            taxonomies.append(self.build_taxonomy('malicious', 'FileInfo', 'PossibleCVEExploit', 'True'))

        taxonomies.append(self.build_taxonomy('info', 'FileInfo', 'RTFObjects', count))

        self.summary['taxonomies'] = taxonomies
        return self.summary

def disconnect_all_containers_from_network(network_id):
    connected_containers = connected(network_id)
    ret = []
    failed = []
    for cname in connected_containers:
        try:
            disconnect_container_from_network(cname, network_id)
            ret.append(cname)
        except CommandExecutionError as exc:
            msg = exc.__str__()
            if '404' not in msg:
                # If 404 was in the error, then the container no longer exists,
                # so to avoid a race condition we won't consider 404 errors to
                # men that removal failed.
                failed.append(msg)
    if failed:
        raise CommandExecutionError(
            'One or more containers failed to be removed',
            info={'removed': ret, 'errors': failed}
        )
    return ret

