def PlistValueToPlainValue(plist):

  if isinstance(plist, dict):
    ret_value = dict()
    for key, value in iteritems(plist):
      ret_value[key] = PlistValueToPlainValue(value)
    return ret_value
  elif isinstance(plist, list):
    return [PlistValueToPlainValue(value) for value in plist]
  elif isinstance(plist, datetime.datetime):
    return (calendar.timegm(plist.utctimetuple()) * 1000000) + plist.microsecond
  return plist

def validate_response(expected_responses):

    def internal_decorator(function):
        @wraps(function)
        async def wrapper(*args, **kwargs):

            response = await function(*args, **kwargs)

            for expected_response in expected_responses:
                if response.startswith(expected_response):
                    return response

            raise QRTCommandException(
                "Expected %s but got %s" % (expected_responses, response)
            )

        return wrapper

    return internal_decorator

def get_or_load_name(self, type_, id_, method):
        name = self.get_name(type_, id_)
        if name is not None:
            defer.returnValue(name)
        instance = yield method(id_)
        if instance is None:
            defer.returnValue(None)
        self.put_name(type_, id_, instance.name)
        defer.returnValue(instance.name)

