def remove_resource(zone, resource_type, resource_key, resource_value):
    ret = {'status': True}

    # generate update script
    cfg_file = salt.utils.files.mkstemp()
    with salt.utils.files.fpopen(cfg_file, 'w+', mode=0o600) as fp_:
        if resource_key:
            fp_.write("remove {0} {1}={2}\n".format(resource_type, resource_key, _sanitize_value(resource_value)))
        else:
            fp_.write("remove {0}\n".format(resource_type))

    # update property
    if cfg_file:
        _dump_cfg(cfg_file)
        res = __salt__['cmd.run_all']('zonecfg -z {zone} -f {path}'.format(
            zone=zone,
            path=cfg_file,
        ))
        ret['status'] = res['retcode'] == 0
        ret['message'] = res['stdout'] if ret['status'] else res['stderr']
        if ret['message'] == '':
            del ret['message']
        else:
            ret['message'] = _clean_message(ret['message'])

        # cleanup config file
        if __salt__['file.file_exists'](cfg_file):
            __salt__['file.remove'](cfg_file)

    return ret

def vapour_density(Temperature, element, isotope=None):
    atom = Atom(element, isotope)
    if atom.isotope is None:
        rho = 0.0
        for iso in atom.isotopes:
            atom = Atom(element, iso)
            rho += vapour_number_density(Temperature, element) *\
                atom.mass*atom.abundance
        return rho
    else:
        return vapour_number_density(Temperature, element)*atom.mass

def str_from_text(text):
    REGEX = re.compile('<text>((.|\n)+)</text>', re.UNICODE)
    match = REGEX.match(text)
    if match:
        return match.group(1)
    else:
        return None

def pdf_extract_text(path, pdfbox_path, pwd='', timeout=120):

    if not os.path.isfile(path):
        raise IOError('path must be the location of the source pdf-file')

    if not os.path.isfile(pdfbox_path):
        raise IOError('pdfbox_path must be the location of the pdfbox.jar')

    import subprocess
    for p in os.environ['PATH'].split(':'):
        if os.path.isfile(os.path.join(p, 'java')):
            break
    else:
        print('java is not on the PATH')
        return
    try:
        if pwd == '':
            cmd = ['java', '-jar', pdfbox_path, 'ExtractText', path, path+'.txt']
        else:
            cmd = ['java', '-jar', pdfbox_path, 'ExtractText', '-password', pwd,
                path, path+'.txt']
        subprocess.check_call(cmd, stdin=subprocess.DEVNULL, 
            stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL, timeout=timeout)

    except subprocess.TimeoutExpired as e:
        print('Timeout of {:.1f} min expired'.format(timeout/60))

    except subprocess.CalledProcessError as e:
        print('Text could not successfully be extracted.')

