def locate(self, point, _verify=True):
        if _verify:
            if self._dimension != 2:
                raise NotImplementedError("Only 2D surfaces supported.")

            if point.shape != (self._dimension, 1):
                point_dimensions = " x ".join(
                    str(dimension) for dimension in point.shape
                )
                msg = _LOCATE_ERROR_TEMPLATE.format(
                    self._dimension, self._dimension, point, point_dimensions
                )
                raise ValueError(msg)

        return _surface_intersection.locate_point(
            self._nodes, self._degree, point[0, 0], point[1, 0]
        )

def change_speed(body, speed=1):
    if speed == 1:
        return body

    length = int(len(body) * speed)
    rv = bytearray(length)

    step = 0
    for v in body:
        i = int(step)
        while i < int(step + speed) and i < length:
            rv[i] = v
            i += 1
        step += speed
    return rv

def check_match(self, **kwargs):
        if not self.whitelist_package_names:
            return False

        name = kwargs.get("name", None)
        if not name:
            return False

        if name in self.whitelist_package_names:
            logger.info(f"Package {name!r} is whitelisted")
            return False
        return True

