def load(self):
        data = self.get_data("certificates/%s" % self.id)
        certificate = data["certificate"]

        for attr in certificate.keys():
            setattr(self, attr, certificate[attr])

        return self

def get(self, terser):
        key = terser
        # if the expression in not found n the qualified names
        # find the alias
        if terser not in self.data and terser in self.aliasKeys:
            key = self.aliasKeys[terser]

        value = self.data.get(key, None)

        # if the value is not found, it can be a partial terser
        if value:
            return value
        else:
            # find the values : simple startswith : should it be a regexp ? (more powerful, more slower)
            values = list(filter(lambda k: k.startswith(key), self.aliasKeys))
            if len(values) > 0:
                return values
            else:
                return None

def make_list_table_from_mappings(headers, data, title, columns=None):
    header_names = [h[0] for h in headers]
    header_keys = [h[1] for h in headers]
    row_data = (
        [d.get(k) for k in header_keys]
        for d in data
    )
    return make_list_table(header_names, row_data, title, columns)

def merge_networks(output_file="merged_network.txt", *files):

    contacts = dict()
    for network_file in files:
        with open(network_file) as network_file_handle:
            for line in network_file_handle:
                id_a, id_b, n_contacts = line.split("\t")
                pair = sorted((id_a, id_b))
                try:
                    contacts[pair] += n_contacts
                except KeyError:
                    contacts[pair] = n_contacts

    sorted_contacts = sorted(contacts)
    with open(output_file, "w") as output_handle:
        for index_pair in sorted_contacts:
            id_a, id_b = index_pair
            n_contacts = contacts[index_pair]
            output_handle.write("{}\t{}\t{}\n".format(id_a, id_b, n_contacts))

