def wcparams(mol, type_):
    try:
        assign_wctype(mol)
    except:
        return "N/A"
    scores = []
    for i, atom in mol.atoms_iter():
        scores.append(float(DATA[type_][atom.wctype]))
        if atom.H_count:
            if atom.symbol == "C":
                scores.append(DATA[type_]["H1"] * atom.H_count)
            elif atom.symbol == "N":
                scores.append(DATA[type_]["H3"] * atom.H_count)
            elif atom.wctype == "O2a":
                scores.append(DATA[type_]["H4"] * atom.H_count)
            else:
                scores.append(DATA[type_]["H2"] * atom.H_count)
    return round(sum(scores), 2)

def on_confirmation(self, frame):
        delivered = frame.method.NAME.split('.')[1].lower() == 'ack'
        self.logger.debug('Received publisher confirmation (Delivered: %s)',
                          delivered)
        if frame.method.multiple:
            for index in range(self.last_confirmation + 1,
                               frame.method.delivery_tag):
                self.confirm_delivery(index, delivered)
        self.confirm_delivery(frame.method.delivery_tag, delivered)
        self.last_confirmation = frame.method.delivery_tag

def load_swagger_json(swagger_json, ptr_str="$ref"):
        refs = []

        def store_refs(d):
            if len(d) == 1 and ptr_str in d:
                refs.append(d)
            return d

        swagger_content = json.load(swagger_json, object_hook=store_refs)
        for ref in refs:
            _, target = ref.popitem()
            assert target[0] == "#"
            ref.update(resolve_pointer(swagger_content, target[1:]))
        return swagger_content

