def divide_work(list_of_indexes, batch_size):
        grouped_indexes = [list_of_indexes[i:i + batch_size] for i in range(0, len(list_of_indexes), batch_size)]
        return [(batch[0], len(batch)) for batch in grouped_indexes]

def __parse_imap_search_result(self, result):
        if isinstance(result, types.ListType):
            # Above is same as "type(result) == types.ListType"
            if len(result) == 1:
                return self.__parse_imap_search_result(result[0])
            else:
                return result
        elif isinstance(result, types.StringType):
            # Above is same as "type(result) == types.StringType"
            return result.split()
        else:
            # Fail silently assuming tests will fail if emails are not found
            return []

def run(self, exp_config=None, app_id=None, bot=False, **kwargs):
        import dallinger as dlgr

        app_id = self.make_uuid(app_id)

        if bot:
            kwargs["recruiter"] = "bots"

        self.app_id = app_id
        self.exp_config = exp_config or kwargs
        self.update_status("Starting")
        try:
            if self.exp_config.get("mode") == "debug":
                dlgr.command_line.debug.callback(
                    verbose=True, bot=bot, proxy=None, exp_config=self.exp_config
                )
            else:
                dlgr.deployment.deploy_sandbox_shared_setup(
                    dlgr.command_line.log,
                    app=app_id,
                    verbose=self.verbose,
                    exp_config=self.exp_config,
                )
        except Exception:
            self.update_status("Errored")
            raise
        else:
            self.update_status("Running")
        self._await_completion()
        self.update_status("Retrieving data")
        data = self.retrieve_data()
        self.update_status("Completed")
        return data

