def _ConvertAnyMessage(self, value, message):
    if isinstance(value, dict) and not value:
      return
    try:
      type_url = value['@type']
    except KeyError:
      raise ParseError('@type is missing when parsing any message.')

    sub_message = _CreateMessageFromTypeUrl(type_url)
    message_descriptor = sub_message.DESCRIPTOR
    full_name = message_descriptor.full_name
    if _IsWrapperMessage(message_descriptor):
      self._ConvertWrapperMessage(value['value'], sub_message)
    elif full_name in _WKTJSONMETHODS:
      methodcaller(
          _WKTJSONMETHODS[full_name][1], value['value'], sub_message)(self)
    else:
      del value['@type']
      self._ConvertFieldValuePair(value, sub_message)
    # Sets Any message
    message.value = sub_message.SerializeToString()
    message.type_url = type_url

def get_metar(
            metar: typing.Union[str, 'CustomMetar']
    ) -> typing.Tuple[typing.Union[str, None], typing.Union['CustomMetar', None]]:
        error: typing.Optional[str] = None
        if isinstance(metar, CustomMetar):
            return None, metar

        if isinstance(metar, str):
            LOGGER.debug('building CustomMetar from: %s', metar)
            if len(metar) == 4:
                LOGGER.debug('retrieving METAR from ICAO')
                # NOAA has discontinued their hosting of raw METAR text files ...
                # error, metar = noaa.retrieve_metar(metar)
                # metar = avwx.AVWX.query_icao(metar).rawreport
                metar = AWC.query_icao(metar).raw_metar
        else:
            error = f'expected a string or or a CustomMetar object, got: {type(metar)}'

        if error:
            return error, None

        try:
            return None, CustomMetar(metar_code=metar)
        except ParserError:
            return f'Unable to parse METAR: {metar}', None

def unique(self, key=None):
        if isinstance(key, basestring):
            key = lambda r, attr=key: getattr(r, attr, None)
        ret = self.copy_template()
        seen = set()
        for ob in self:
            if key is None:
                try:
                    ob_dict = vars(ob)
                except TypeError:
                    ob_dict = dict((k, getattr(ob, k)) for k in _object_attrnames(ob))
                reckey = tuple(sorted(ob_dict.items()))
            else:
                reckey = key(ob)
            if reckey not in seen:
                seen.add(reckey)
                ret.insert(ob)
        return ret

