def match(self, name=None, ns=None):
        if name is None:
            byname = True
        else:
            byname = self.name == name
        if ns is None:
            byns = True
        else:
            byns = self.namespace()[1] == ns[1]
        return byname and byns

def find(self, node, list):
        if self.matcher.match(node):
            list.append(node)
            self.limit -= 1
            if self.limit == 0:
                return
        for c in node.rawchildren:
            self.find(c, list)
        return self

def load_case(adapter, case_obj, update=False):
    # Check if the case already exists in database.
    existing_case = adapter.case(case_obj)
    if existing_case:
        if not update:
            raise CaseError("Case {0} already exists in database".format(case_obj['case_id']))
        case_obj = update_case(case_obj, existing_case)

    # Add the case to database
    try:
        adapter.add_case(case_obj, update=update)
    except CaseError as err:
        raise err

    return case_obj

