def iterate_by_type(objs, typelist):

    cache = collect_by_type(objs)

    for t in typelist:
        for val in cache.pop(t, tuple()):
            yield val

    for tl in cache.values():
        for val in tl:
            yield val

def create_rank_dicts(self, alt_scores):
        self.alts_to_ranks = dict()
        cur_score = max(alt_scores.values())
        cur_rank = 0
        self.ranks_to_alts = {cur_rank:[]}
        for i in sorted(alt_scores.keys(), key=lambda x: -alt_scores[x]):
            if alt_scores[i] == cur_score:
                self.ranks_to_alts[cur_rank].append(i)
            elif alt_scores[i] < cur_score:
                cur_rank += 1
                cur_score = alt_scores[i]
                self.ranks_to_alts[cur_rank] = [i]
            self.alts_to_ranks[i] = cur_rank

async def Check(self, stream):
        request = await stream.recv_message()
        checks = self._checks.get(request.service)
        if checks is None:
            await stream.send_trailing_metadata(status=Status.NOT_FOUND)
        elif len(checks) == 0:
            await stream.send_message(HealthCheckResponse(
                status=HealthCheckResponse.SERVING,
            ))
        else:
            for check in checks:
                await check.__check__()
            await stream.send_message(HealthCheckResponse(
                status=_status(checks),
            ))

