def primitive_type(schema):
    schema_type = type(schema)

    # Literal
    if schema_type in const.literal_types:
        return const.COMPILED_TYPE.LITERAL
    # Enum
    elif Enum is not None and isinstance(schema, (EnumMeta, Enum)):
        return const.COMPILED_TYPE.ENUM
    # Type
    elif issubclass(schema_type, six.class_types):
        return const.COMPILED_TYPE.TYPE
    # Mapping
    elif isinstance(schema, collections.Mapping):
        return const.COMPILED_TYPE.MAPPING
    # Iterable
    elif isinstance(schema, collections.Iterable):
        return const.COMPILED_TYPE.ITERABLE
    # Callable
    elif callable(schema):
        return const.COMPILED_TYPE.CALLABLE
    # Not detected
    else:
        return None

def ellipsis(text, length, symbol="..."):
    if len(text) > length:
        pos = text.rfind(" ", 0, length)
        if pos < 0:
            return text[:length].rstrip(".") + symbol
        else:
            return text[:pos].rstrip(".") + symbol

    else:
        return text

def from_xml(xml_path, mapsource_prefix=""):
        xmldoc = xml.etree.ElementTree.parse(xml_path).getroot()

        map_id = os.path.splitext(os.path.basename(xml_path))[0]
        map_name = map_id
        map_folder = re.sub("^" + re.escape(mapsource_prefix), "", os.path.dirname(xml_path))
        bbox = None
        layers = None

        for elem in xmldoc.getchildren():
            if elem.tag == 'id':
                map_id = elem.text
            elif elem.tag == 'name':
                map_name = elem.text
            elif elem.tag == 'folder':
                map_folder = elem.text
            elif elem.tag == 'region':
                bbox = MapSource.parse_xml_boundary(elem)
            elif elem.tag == 'layers':
                layers = MapSource.parse_xml_layers(elem)

        if map_folder is None:
            map_folder = "" # fallback if bad specification in xml
        if layers is None:  # layers tag not found, expect url etc. in main xmldoc
            layers = [MapSource.parse_xml_layer(xmldoc)]

        ms = MapSource(map_id, map_name, map_folder, bbox=bbox)
        ms.layers = layers
        return ms

def getReaderNames(self):

        # get inserted readers
        hresult, pcscreaders = SCardListReaders(self.hcontext, [])
        if 0 != hresult and SCARD_E_NO_READERS_AVAILABLE != hresult:
            raise ListReadersException(hresult)

        readers = []

        # if no readers asked, use all inserted readers
        if None == self.readersAsked:
            readers = pcscreaders

        # otherwise use only the asked readers that are inserted
        else:
            for reader in self.readersAsked:
                if not isinstance(reader, type("")):
                    reader = str(reader)
                if reader in pcscreaders:
                    readers = readers + [reader]

        return readers

