def enrich_citation_model(manager, citation, p) -> bool:
    if 'error' in p:
        log.warning('Error downloading PubMed')
        return False

    citation.name = p['fulljournalname']
    citation.title = p['title']
    citation.volume = p['volume']
    citation.issue = p['issue']
    citation.pages = p['pages']
    citation.first = manager.get_or_create_author(p['sortfirstauthor'])
    citation.last = manager.get_or_create_author(p['lastauthor'])

    if 'authors' in p:
        for author in p['authors']:
            author_model = manager.get_or_create_author(author['name'])
            if author_model not in citation.authors:
                citation.authors.append(author_model)

    publication_date = p['pubdate']

    sanitized_publication_date = sanitize_date(publication_date)
    if sanitized_publication_date:
        citation.date = datetime.strptime(sanitized_publication_date, '%Y-%m-%d')
    else:
        log.info('result had date with strange format: %s', publication_date)

    return True

def unmarshall_key(self, key):
        key = str(key)
        if self.escapeKeys:
            key = key.decode('hex')
        if self.compressKeys:
            key = zlib.decompress(key)
        key = pickle.loads(key)
        return key

def _insert(self, dom_group, idx=None, prepend=False, name=None):
        if idx and idx < 0:
            idx = 0
        if prepend:
            idx = 0
        else:
            idx = idx if idx is not None else len(self.childs)
        if dom_group is not None:
            if not isinstance(dom_group, Iterable) or isinstance(
                dom_group, (DOMElement, str)
            ):
                dom_group = [dom_group]
            for i_group, elem in enumerate(dom_group):
                if elem is not None:
                    # Element insertion in this DOMElement childs
                    self.childs.insert(idx + i_group, elem)
                    # Managing child attributes if needed
                    if issubclass(elem.__class__, DOMElement):
                        elem.parent = self
                    if name:
                        setattr(self, name, elem)

