def get_central_coors(self, row, col):
        if row < 0 or row >= self.nRows or col < 0 or col >= self.nCols:
            raise ValueError("The row (%d) or col (%d) must be >=0 and less than "
                             "nRows (%d) or nCols (%d)!" % (row, col, self.nRows, self.nCols))
        else:
            tmpx = self.xMin + (col + 0.5) * self.dx
            tmpy = self.yMax - (row + 0.5) * self.dx
            return tmpx, tmpy

def _build_list(option_value, item_kind):
    #specify profiles if provided
    if option_value is not None:

        items = []

        #if user specified none, return an empty list
        if option_value == 'none':
            return items

        #was a list already passed in?
        if not isinstance(option_value, list):
            values = option_value.split(',')
        else:
            values = option_value

        for value in values:
            # sometimes the bigip just likes a plain ol list of items
            if item_kind is None:
                items.append(value)
            # other times it's picky and likes key value pairs...
            else:
                items.append({'kind': item_kind, 'name': value})
        return items
    return None

