def rowlengths(table):

    counter = Counter()
    for row in data(table):
        counter[len(row)] += 1
    output = [('length', 'count')]
    output.extend(counter.most_common())
    return wrap(output)

def fit_delta_ts(data, time_s):

    data = data / time_s

    xs = np.arange(-20, 21)

    def gaussian(x, mean, sigma, rate, offset):
        return rate / np.sqrt(2 * np.pi) /  \
            sigma * np.exp(-(x - mean)**2 / sigma**2) + offset

    rates = []
    means = []
    for combination in data:
        try:
            popt, _ = optimize.curve_fit(
                gaussian, xs, combination, p0=[0, 2, 1000, 20]
            )
        except RuntimeError:
            popt = (0, 0, 0, 0)
        rates.append(popt[2])
        means.append(popt[0])
    return np.array(rates), np.array(means)

def do_parse(self, arg, fullparse=False):
        from os import path
        fullpath = path.abspath(path.expanduser(arg))
        if path.isdir(fullpath):
            if fullpath[-1] == "/":
                end = -2
            else:
                end = -1
            case = fullpath.split("/")[end]
            self.tests[case] = Analysis(fullpath, fullparse)
            self.do_set(case)
        else:
            msg.err("The folder {} does not exist.".format(fullpath))

def _fetch_cdn_data(self):
        if self._cdn_enabled is FAULT:
            headers = self.manager.fetch_cdn_data(self)
        else:
            headers = {}
        # Set defaults in case not all headers are present.
        self._set_cdn_defaults()
        if not headers:
            # Not CDN enabled; return
            return
        else:
            self._cdn_enabled = True
        for key, value in headers.items():
            low_key = key.lower()
            if low_key == "x-cdn-uri":
                self._cdn_uri = value
            elif low_key == "x-ttl":
                self._cdn_ttl = int(value)
            elif low_key == "x-cdn-ssl-uri":
                self._cdn_ssl_uri = value
            elif low_key == "x-cdn-streaming-uri":
                self._cdn_streaming_uri = value
            elif low_key == "x-cdn-ios-uri":
                self._cdn_ios_uri = value
            elif low_key == "x-log-retention":
                self._cdn_log_retention = (value == "True")

