def cmd_nmap_ports(scanfile, protocol):

    data = scanfile.read()
    fmt = detect_format(data)

    if fmt not in ['xml', 'nmap', 'gnmap']:
        print('Unknown file format.', file=sys.stdout)
        return 1

    if fmt == 'nmap':
        result = parse_format_nmap(data, protocol)
    elif fmt == 'gnmap':
        result = parse_format_gnmap(data, protocol)
    elif fmt == 'xml':
        result = parse_format_xml(data, protocol)

    print(result, end='')

    return True

def stride(self):
        # Cache for efficiency instead of re-computing
        if self.__stride is None:
            strd = []
            for i in range(self.ndim):
                if not self.is_uniform_byaxis[i]:
                    strd.append(float('nan'))
                elif self.nondegen_byaxis[i]:
                    strd.append(self.extent[i] / (self.shape[i] - 1.0))
                else:
                    strd.append(0.0)
            self.__stride = np.array(strd)

        return self.__stride.copy()

def insert(self, text: str):
        undoObj = UndoInsert(self, text)
