def _make_obj(obj):

    if isinstance(obj, dict):
        if 'url' in obj.keys():
            url = obj['url']
            id_ = int(url.split('/')[-2])      # ID of the data.
            endpoint = url.split('/')[-3]  # Where the data is located.
            return APIResource(endpoint, id_, lazy_load=True)

        return APIMetadata(obj)

    return obj

def check_async(async_, kwargs, default):
    if async_ is not None:
        return async_
    elif 'async' in kwargs:
        warnings.warn(
            '"async" attribute is deprecated. Use "async_" instead.',
            DeprecationWarning,
        )
        return kwargs.pop('async')
    else:
        return default

def pub(topic_name, json_msg, repeat_rate=None, host=jps.env.get_master_host(), pub_port=jps.DEFAULT_PUB_PORT):
    pub = jps.Publisher(topic_name, host=host, pub_port=pub_port)
    time.sleep(0.1)
    if repeat_rate is None:
        pub.publish(json_msg)
    else:
        try:
            while True:
                pub.publish(json_msg)
                time.sleep(1.0 / repeat_rate)
        except KeyboardInterrupt:
            pass

