def load(filepath=None):
    if filepath and os.path.exists(filepath):
        pass
    else:
        if not True:
            raise ValueError("invalid state")
        if not os.path.exists('.env'):
            return False
        filepath = os.path.join('.env')

    for key, value in _get_line_(filepath):
