        subsys._repertoire_cache.clear()
        subsys._mice_cache.clear()
    except TypeError:
        try:
            # Pre cache.clear() implementation
            subsys._repertoire_cache.cache = {}
            subsys._mice_cache.cache = {}
        except AttributeError:
            # Old school, pre cache refactor
