def thr_img(img, thr=2., mode='+'):

    vol  = read_img(img).get_data()

    if mode == '+':
        mask = vol > thr
    elif mode == '+-' or mode == '-+':
        mask = np.abs(vol) > thr
    elif mode == '-':
        mask = vol < -thr
    else:
        raise ValueError("Expected `mode` to be one of ('+', '+-', '-+', '-'), "
                         "got {}.".format(mode))

    return vol * mask

