def dechunk(stream):

    # TODO(vovan): Add support for chunk extensions:
    # TODO(vovan): http://tools.ietf.org/html/rfc2616#section-3.6.1

    while True:
        chunk_len = read_until(stream, b'\r\n')

        if chunk_len is None:
            raise DechunkError(
                'Could not extract chunk size: unexpected end of data.')

        try:
            chunk_len = int(chunk_len.strip(), 16)
        except (ValueError, TypeError) as err:
            raise DechunkError('Could not parse chunk size: %s' % (err,))

        if chunk_len == 0:
            break

        bytes_to_read = chunk_len
        while bytes_to_read:
            chunk = stream.read(bytes_to_read)
            bytes_to_read -= len(chunk)
            yield chunk

        # chunk ends with \r\n
        crlf = stream.read(2)
        if crlf != b'\r\n':
            raise DechunkError('No CR+LF at the end of chunk!')

def Stop(self):
    if not self.__running:
      return
    logging.info('shutting down the emulator running at %s', self._host)
    headers = {'Content-length': '0'}
    response, _ = self._http.request('%s/shutdown' % self._host,
                                     method='POST', headers=headers)
    if response.status != 200:
      logging.warning('failed to shut down emulator; response: %s', response)

    self.__running = False
    # Delete temp files.
    shutil.rmtree(self._tmp_dir)

def load_global_conf(cls, global_configuration):
        logger.debug("Propagate global parameter for %s:", cls)
        for prop, entry in global_configuration.properties.items():
            # If some global managed configuration properties have a class_inherit clause,
            if not entry.managed or not getattr(entry, 'class_inherit'):
                continue
            for (cls_dest, change_name) in entry.class_inherit:
                if cls_dest == cls:  # ok, we've got something to get
                    value = getattr(global_configuration, prop)
                    logger.debug("- global parameter %s=%s -> %s=%s",
                                 prop, getattr(global_configuration, prop),
                                 change_name, value)
                    if change_name is None:
                        setattr(cls, prop, value)
                    else:
                        setattr(cls, change_name, value)

