def _evaluate(self,R,phi=0.,t=0.):
        if R < self._rb:
            return self._mphio/self._m*math.cos(self._m*phi-self._mphib)\
                *self._rbp*(2.*self._r1p-self._rbp/R**self._p)
        else:
            return self._mphio/self._m*R**self._p\
                *math.cos(self._m*phi-self._mphib)

