def get_slice(self, thin_start=None, tmp=None, thin_end=None):
        if thin_start is None:
            thin_start = int(self.thin_start)
        else:
            thin_start = int(thin_start)
        if tmp is None:
            tmp = self.thin_interval
        else:
            tmp = int(numpy.ceil(tmp))
        if thin_end is None:
            thin_end = self.thin_end
        else:
            thin_end = int(thin_end)
        return slice(thin_start, thin_end, tmp)

def do_transaction(self, function, *args, **kwargs):
        for wait_in_seconds in self.backoff_generator():
            try:
                with self.config.db_transaction() as trans:
                    function(trans, *args, **kwargs)
                    trans.commit()
                    break
            except self.config.db_transaction.operational_exceptions:
                pass
            print(('failure in transaction - retry in %s seconds' %
                   wait_in_seconds))
            self.responsive_sleep(wait_in_seconds,
                                  "waiting for retry after failure in "
                                  "transaction")

def supply_backend(optional: Union[callable, bool]=False, index_exists: bool=True):
    real_optional = False if callable(optional) else optional

    def supply_backend_inner(func):
        @wraps(func)
        def wrapped_supply_backend(args):
            log = logging.getLogger(func.__name__)
            if real_optional and not getattr(args, "backend", False):
                backend = None
            else:
                try:
                    git_index = GitIndex(remote=args.index_repo, username=args.username,
                                         password=args.password, cache=args.cache,
                                         exists=index_exists, signoff=args.signoff,
                                         log_level=args.log_level)
                except ValueError:
                    return 1
                backend = create_backend_noexc(log, args.backend, git_index, args.args)
                if backend is None:
                    return 1
            return func(args, backend, log)
        return wrapped_supply_backend
    if callable(optional):
        return supply_backend_inner(optional)
    return supply_backend_inner

