def _concrete_instance(self, instance_doc):
        if not isinstance(instance_doc, dict):
            return None

        # Attempt to instantiate the appropriate class for the given instance document.
        try:
            service = instance_doc['service']
            cls = self._service_class_map[service]
            return cls(instance_document=instance_doc, instances=self)

        # If construction fails, log the exception and return None.
        except Exception as ex:
            logger.exception(ex)
            logger.error(
                'Instance construction failed. You probably need to upgrade to a more '
                'recent version of the client. Instance document which generated this '
                'warning: {}'.format(instance_doc)
            )
            return None

def get_checksum_by_target(self, target):
        for csum in self.checksums:
            if csum.target == target:
                return csum
        return None

def _send_raw(self, command):
        try:
            self._socket.send(bytearray(command))
            self._sn = (self._sn + 1) % 256
            return True
        except (socket.error, socket.timeout):
            # We can get a socket.error or timeout exception if the bridge is disconnected,
            # but we are still sending data. In that case, return False to indicate that data is not sent.
            return False

def finalize_options(self):  # suppress(unused-function)
        for option in ["suppress-codes", "exclusions", "disable-linters"]:
            attribute = option.replace("-", "_")
            if isinstance(getattr(self, attribute), str):
                setattr(self, attribute, getattr(self, attribute).split(","))

            if not isinstance(getattr(self, attribute), list):
                raise DistutilsArgError("""--{0} must be """
                                        """a list""".format(option))

        if not isinstance(self.cache_directory, str):
            raise DistutilsArgError("""--cache-directory=CACHE """
                                    """must be a string""")

        if not isinstance(self.stamp_directory, str):
            raise DistutilsArgError("""--stamp-directory=STAMP """
                                    """must be a string""")

        if not isinstance(self.stamp_directory, str):
            raise DistutilsArgError("""--stamp-directory=STAMP """
                                    """must be a string""")

        if not isinstance(self.show_lint_files, int):
            raise DistutilsArgError("""--show-lint-files must be a int""")

        self.cache_directory = _get_cache_dir(self.cache_directory)

def path_exists(self, path):

        path = path.strip('/')
        if path != '':
            spec = {'path': path}
            count = self._connect_collection(self.notebook_collection).find(spec).count()
        else:
            count = 1
        return count > 0

def load(self, data: dict):
        for i, label in enumerate(self.keys):
            key = label.cget('text')
            if key in data.keys():
                entry_was_enabled = True if \
                    self.values[i].cget('state') == 'normal' else False
                if not entry_was_enabled:
                    self.values[i].config(state='normal')

                self.values[i].delete(0, tk.END)
                self.values[i].insert(0, str(data[key]))

                if not entry_was_enabled:
                    self.values[i].config(state='disabled')

