        If you need greater speed, try modifying the optional argument sleep_time=.1, (although \
        this may cause the search to time out)" )

    infotypes = []
    for pdb_id in pdb_list:
        all_info = get_all_info(pdb_id)
        type_results = walk_nested_dict(all_info, '@type', maxdepth=25,outputs=[])
        if type_results:
            infotypes.append(type_results[-1])
        else:
            infotypes.append('Unknown')
        time.sleep(sleep_time)

    return infotypes

def _query(queue_name=None, build_id=None, release_id=None, run_id=None,
           count=None):
    assert queue_name or build_id or release_id or run_id

    q = WorkQueue.query
    if queue_name:
        q = q.filter_by(queue_name=queue_name)
    if build_id:
        q = q.filter_by(build_id=build_id)
    if release_id:
        q = q.filter_by(release_id=release_id)
    if run_id:
        q = q.filter_by(run_id=run_id)

    q = q.order_by(WorkQueue.created.desc())

    if count is not None:
        q = q.limit(count)

    return q.all()

async def keep_alive(self, period=1, margin=.3):
        if period < 0:
            period = 0
        if period > 10:
            period = 10
        self.period = period
        if margin < .1:
            margin = .1
        if margin > .9:
            margin = .9
        self.margin = margin
        self.keep_alive_interval = [period & 0x7f, (period >> 7) & 0x7f]
        await self._send_sysex(PrivateConstants.SAMPLING_INTERVAL,
                               self.keep_alive_interval)
        while True:
            if self.period:
                await asyncio.sleep(period - (period - (period * margin)))
                await self._send_sysex(PrivateConstants.KEEP_ALIVE,
                                       self.keep_alive_interval)
            else:
                break

def ask_question(self, question_text, question=None):
