            'X-SyncTimeout': 30
        }, auth=(self.username, self.password))
        try:
            response_json = r.json()
        except ValueError:
            raise Exception('Failed to parse response JSON')
        return WatsonAnswer(response_json)

def get_transform_version(transform):

    if sys.version_info[0] > 3:
        spec = inspect.getfullargspec(transform)
    else:
        spec = inspect.getargspec(transform)

    if spec.varargs:
        return 3

    n = len(spec.args)

    if 2 <= n <= 3:
        return n

    raise Exception('Could not determine transform version.')

