def _split_hostport(self, hostport, default_port=None):

        try:
            (host, port) = hostport.split(':', 1)
        except ValueError:  # no colon in the string so make our own port
            host = hostport

            if default_port is None:
                raise ValueError('No port found in hostport, and default_port not provided.')

            port = default_port

        try:
            port = int(port)
            if port < 1 or port > 65535:
                raise ValueError()
        except ValueError:
            raise ValueError("{0} is not a valid TCP port".format(port))

        return (host, port)

def _get_machines_cache_from_dns(self, host, port):
        if self.protocol == 'http':
            ret = []
            for af, _, _, _, sa in self._dns_resolver.resolve(host, port):
                host, port = sa[:2]
                if af == socket.AF_INET6:
                    host = '[{0}]'.format(host)
                ret.append(uri(self.protocol, host, port))
            if ret:
                return list(set(ret))
        return [uri(self.protocol, host, port)]

