def _idx_to_bits(self, i):
    bits = bin(i)[2:].zfill(self.nb_hyperplanes)  # Pad the bits str with 0
    return [-1.0 if b == "0" else 1.0 for b in bits]

def tail(self, n=5):
        if self.empty:
            return self
        else:
            if self._length is not None:
                length = self._length
            else:
                length = self._lazy_len().weld_expr

            # not computing slice here to use with __getitem__ because we'd need to use len which is eager
            return Index(weld_tail(self.weld_expr, length, n),
                         self.dtype,
                         self.name)

def nullify(function):
    def wrapper(*args, **kwargs):
        value = function(*args, **kwargs)
        if(type(value) == list and len(value) == 0):
            return None
        return value
    return wrapper

def load_extension(self, name):

        if name in self.__extensions:
            raise errors.ExtensionAlreadyLoaded(name)

        try:
            lib = importlib.import_module(name)
        except ImportError as e:
            raise errors.ExtensionNotFound(name, e) from e
        else:
            self._load_from_module_spec(lib, name)

