def ordinal(value):

    try:
        value = int(value)
    except (TypeError, ValueError):
        raise ValueError

    if value % 100 in (11, 12, 13):
        return '%d%s' % (value, ORDINAL_SUFFIX[0])
    else:
        return '%d%s' % (value, ORDINAL_SUFFIX[value % 10])

