def fread(f,byteLocation,structFormat=None,nBytes=1):
    f.seek(byteLocation)
    if structFormat:
        val = struct.unpack(structFormat, f.read(struct.calcsize(structFormat)))
        val = val[0] if len(val)==1 else list(val)
        return val
    else:
        return f.read(nBytes)

