def norm(x, encoding="latin1"):
    if not isinstance(x, basestring):
        x = unicode(x)
    elif isinstance(x, str):
        x = x.decode(encoding, 'ignore')
    return unicodedata.normalize('NFKD', x).encode('ASCII', 'ignore')

