def extract_by_prefix_surfix(text,
                             prefix,
                             surfix,
                             minlen=None,
                             maxlen=None,
                             include=False):
    if minlen is None:
        minlen = 0
    if maxlen is None:
        maxlen = 2 ** 30
    pattern = r"""(?<=%s)[\s\S]{%s,%s}?(?=%s)""" % (
        prefix, minlen, maxlen, surfix)
    if include:
        return [prefix + s + surfix for s in re.findall(pattern, text)]
    else:
        return re.findall(pattern, text)

def to_isostring(dt):
    if dt.tzinfo is not None and dt.tzinfo.utcoffset(dt) > timedelta(0):
        logging.warn('Warning: aware datetimes are interpreted as if they were naive')

    # -3 to change microseconds to milliseconds
    return dt.strftime('%Y-%m-%dT%H:%M:%S.%f')[:-3] + 'Z'

def paginate_queryset(self, queryset, request, view=None):
        result = super(MultipleModelLimitOffsetPagination, self).paginate_queryset(queryset, request, view)

        # Ensures the max_count attribute exists and reflects the current queryset size.
        try:
            if self.max_count < self.count:
                self.max_count = self.count
        except AttributeError:
            self.max_count = self.count

        try:
            self.total += self.count
        except AttributeError:
            self.total = self.count

        return result

