def consecutive_ones_property(sets, universe=None):
    if universe is None:
        universe = set()
        for S in sets:
            universe |= set(S)
    tree = PQ_tree(universe)
    try:
        for S in sets:
            tree.reduce(S)
        return tree.border()
    except IsNotC1P:
        return None

