def del_expr(self, ctx):
        if self.readonly:
            raise MuvError(
                "Cannot assign value to constant '%s'." % self.varname,
                position=self.position
            )
        varname = ctx.lookup_variable(self.varname)
        if varname is None:
            raise MuvError(
                "Undeclared identifier '%s'." % self.varname,
                position=self.position
            )
        if len(self.indexing) == 0:
            return "0 {var} !".format(var=varname)
        if len(self.indexing) == 1:
            if ctx.target in ['fb7']:
                return "{var} @ {idx} array_delitem".format(
                    var=varname,
                    idx=self.indexing[0].generate_code(ctx),
                )
            else:
                return "{var} @ {idx} array_delitem dup {var} !".format(
                    var=varname,
                    idx=self.indexing[0].generate_code(ctx),
                )
        if ctx.target in ['fb7']:
            return "{var} @ {{ {idx} }}list array_nested_del".format(
                var=varname,
                idx=" ".join(x.generate_code(ctx) for x in self.indexing),
            )
        else:
            return "{var} @ {{ {idx} }}list array_nested_del dup {var} !".format(
                var=varname,
                idx=" ".join(x.generate_code(ctx) for x in self.indexing),
            )

def encrypt(self, pkt, seq_num=None, iv=None):
        if not isinstance(pkt, self.SUPPORTED_PROTOS):
            raise TypeError('cannot encrypt %s, supported protos are %s'
                            % (pkt.__class__, self.SUPPORTED_PROTOS))
        if self.proto is ESP:
            return self._encrypt_esp(pkt, seq_num=seq_num, iv=iv)
        else:
            return self._encrypt_ah(pkt, seq_num=seq_num)

def params(self):
        # if params already defined don't attempt to get them from definition
        if self._definition and not self._params:
            self._params = []
            for sub_instr, _, _ in self._definition:
                self._params.extend(sub_instr.params)  # recursive call
            return self._params
        else:
            return self._params

def validate(spec, data):
    data = copy.deepcopy(data)
    validated_data = {}

    def validate_keys(section, config, section_data):
        if not isinstance(section_data, dict) or section == spec.MODEL:
            return

        extra_args = [key for key in section_data.keys() if key not in config.SCHEMA().fields]
        if extra_args:
            raise PolyaxonfileError('Extra arguments passed for `{}`: {}'.format(
                section, extra_args))

    def add_validated_section(section, config):
        if data.get(section):
            section_data = data[section]
            validate_keys(section=section, config=config, section_data=section_data)
            validated_data[section] = config.from_dict(section_data)

    add_validated_section(spec.ENVIRONMENT, spec.ENVIRONMENT_CONFIG)
    add_validated_section(spec.BUILD, BuildConfig)
    add_validated_section(spec.RUN, RunConfig)
    add_validated_section(spec.MODEL, ModelConfig)
    add_validated_section(spec.TRAIN, TrainConfig)
    add_validated_section(spec.EVAL, EvalConfig)

    return validated_data

