            else:
                print("Source type %s not recognised - skipping!" % source)
                continue

def _get_parsed_url(url):
    # type: (S) -> Url

    try:
        parsed = urllib3_parse(url)
    except ValueError:
        scheme, _, url = url.partition("://")
        auth, _, url = url.rpartition("@")
        url = "{scheme}://{url}".format(scheme=scheme, url=url)
        parsed = urllib3_parse(url)._replace(auth=auth)
    return parsed

def Reynolds(V, D, rho=None, mu=None, nu=None):
    if rho and mu:
        nu = mu/rho
    elif not nu:
        raise Exception('Either density and viscosity, or dynamic viscosity, \
        is needed')
    return V*D/nu

