def redactor(blacklist: Dict[Pattern, str]) -> Callable[[str], str]:
    def processor_wrapper(msg: str) -> str:
        for regex, repl in blacklist.items():
            if repl is None:
                repl = '<redacted>'
            msg = regex.sub(repl, msg)
        return msg
    return processor_wrapper

def command_stop(self):
        if self.pidfile:
            if not os.path.exists(self.pidfile):
                sys.exit("Pidfile {!r} doesn't exist".format(self.pidfile))
            with open(self.pidfile) as pidfile:
                pid = int(pidfile.read())
            for sig in [signal.SIGINT, signal.SIGTERM, signal.SIGKILL]:
                try:
                    if terminate(pid, sig, 3):
                        os.remove(self.pidfile)
                        # NOTE: we are not performing sys.exit here,
                        # otherwise restart command will not work
                        return
                except OSError as exc:
                    if exc.errno != errno.ESRCH:
                        raise
                    elif sig == signal.SIGINT:
                        sys.exit('Not running')
        sys.exit('No pidfile provided')

def calculate_tree_differences(self, pytree, doctree):
        pykeys = set(pytree.keys())
        dockeys = set(doctree.keys())

        # Calculate the missing documentation files, if any.
        missing_doc_keys = pykeys - dockeys
        missing_docs = {pytree[pyfile] for pyfile in missing_doc_keys}

        # Calculate the missing Python files, if any.
        missing_py_keys = dockeys - pykeys
        missing_pys = {docfile for docfile in missing_py_keys}

        return missing_pys, missing_docs

def job(func_or_queue, connection=None, *args, **kwargs):
    decorated_func = _job(func_or_queue, connection=connection, *args, **kwargs)

    if callable(func_or_queue):
        @wraps(decorated_func)
        def wrapper(*args, **kwargs):
            with log.fields(uuid=uuid.uuid4(),
                            job_name=decorated_func.__name__):
                return decorated_func(*args, **kwargs)
        return wrapper
    else:
        def decorator(func):
            @decorated_func
            @wraps(func)
            def wrapper(*args, **kwargs):
                with log.fields(uuid=uuid.uuid4(),
                                job_name=func.__name__):
                    return func(*args, **kwargs)
            return wrapper
        return decorator

