                assert type(key) is unicode, "'{0}' attribute: '{1}' type is not 'unicode'!".format(
                    "comments", key)
                assert type(element) in (OrderedDict, dict), "'{0}' attribute: '{1}' type is not \
                'OrderedDict' or 'dict'!".format("comments", key)
        self.__comments = value

