def terminate_ex(self, nodes, threads=False, attempts=3):
        while nodes and attempts > 0:
            if threads:
                nodes = self.terminate_with_threads(nodes)
            else:
                nodes = self.terminate(nodes)
            if nodes:
                logger.info("Attempt to terminate the remaining instances once more.")
                attempts -= 1
        return nodes

def disconnect(self):
        self.chain.connection.log("Disconnecting: {}".format(self))
        if self.connected:
            if self.protocol:
                if self.is_console:
                    while self.mode != 'global':
                        try:
                            self.send('exit', timeout=10)
                        except CommandTimeoutError:
                            break

                self.protocol.disconnect(self.driver)
                self.protocol = None

            self.connected = False
            self.ctrl = None

