def is_eulerian_tour(graph, tour):
    m = len(tour)-1
    arcs = set((tour[i], tour[i+1]) for i in range(m))
    if len(arcs) != m:
        return False
    for (u,v) in arcs:
        if v not in graph[u]:
            return False
    return True

