def _reset_lazymodule(module, cls_attrs):
    modclass = type(module)
    del modclass.__getattribute__
    del modclass.__setattr__
    try:
        del modclass._LOADING
    except AttributeError:
        pass
    for cls_attr in _CLS_ATTRS:
        try:
            setattr(modclass, cls_attr, cls_attrs[cls_attr])
        except KeyError:
            pass
    _reset_lazy_submod_refs(module)

def to_funset(self):
        fs = set()
        for i, n in self.nodes.iteritems():
            fs.add(gringo.Fun('node', [n, i]))

        for j, i in self.hyper.iteritems():
            fs.add(gringo.Fun('hyper', [i, j, len(self.edges[self.edges.hyper_idx == j])]))

        for j, v, s in self.edges.itertuples(index=False):
            fs.add(gringo.Fun('edge', [j, v, s]))

        return fs

