def _get_switch_interfaces(self, requested_switch_ip, cfg_only=False):

        switch_ifs = []

        try:
            port_info = nxos_db.get_switch_host_mappings(
                            requested_switch_ip)
        except excep.NexusHostMappingNotFound:
            port_info = []

        for binding in port_info:
            if cfg_only and not binding.is_static:
                continue
            intf_type, port = nexus_help.split_interface_name(
                                  binding.if_id)
            switch_ifs.append(
                (requested_switch_ip, intf_type, port,
                const.NOT_NATIVE, binding.ch_grp))
        return switch_ifs

def extract(self, log, basis, name, function=None):
        # Build a dict of {index: [log values]} to keep track.
        intervals = {}
        previous_ix = -1
        for i, z in enumerate(basis):
            ix = self.read_at(z, index=True)
            if ix is None:
                continue
            if ix == previous_ix:
                intervals[ix].append(log[i])
            else:
                intervals[ix] = [log[i]]
            previous_ix = ix

        # Set the requested attribute in the primary comp of each interval.
        for ix, data in intervals.items():
            f = function or utils.null
            d = f(np.array(data))
            self[ix].data[name] = d

        return None

