def property_derivative_T(self, T, P, zs, ws, order=1):
        sorted_valid_methods = self.select_valid_methods(T, P, zs, ws)
        for method in sorted_valid_methods:
            try:
                return self.calculate_derivative_T(T, P, zs, ws, method, order)
            except:
                pass
        return None

def verify_file_signature(self, signature_url, file_url, filename):

        req = requests.get(signature_url, stream=True)
        if req.status_code is 200:
            sigfile = req.raw
        else:
            raise RepositoryMissingSignatureError(signature_url)

        verified = self.gpg.verify_file(sigfile, filename)

        if verified.valid is True:
            logger.debug("verified {0} against {1}".format(filename, signature_url))
        else:
            raise RepositorySignatureError(file_url, signature_url)

def value_from_datadict(self, data, files, name):

        y = data.get(self.year_field % name)
        m = data.get(self.month_field % name)
        d = data.get(self.day_field % name)

        if y == 'YYYY':
            y = ''

        if m == 'MM':
            m = ''

        if d == 'DD':
            d = ''

        date = y
        if m:
            date += '-%s' % m
            if d:
                date += '-%s' % d
        return date

def find_declaration(self):

        # determine the library name

        if not self.is_plt:
            binary_name = self.binary_name
            if binary_name not in SIM_LIBRARIES:
                return
        else:
            binary_name = None
            # PLT entries must have the same declaration as their jump targets
            # Try to determine which library this PLT entry will jump to
            edges = self.transition_graph.edges()
            node = next(iter(edges))[1]
            if len(edges) == 1 and (type(node) is HookNode or type(node) is SyscallNode):
                target = node.addr
                if target in self._function_manager:
                    target_func = self._function_manager[target]
                    binary_name = target_func.binary_name

        if binary_name is None:
            return

        library = SIM_LIBRARIES.get(binary_name, None)

        if library is None:
            return

        if not library.has_prototype(self.name):
            return

        proto = library.prototypes[self.name]

        self.prototype = proto
        if self.calling_convention is not None:
            self.calling_convention.args = None
            self.calling_convention.func_ty = proto

def find(self, sought, view='lemma'):
        for word in self.wordlist:
            if sought == word.views[view]:
                yield word

def get_abi(self, hsh: bytes) -> Dict[str, Any]:
        if not isinstance(hsh, (bytes, bytearray)):
            raise TypeError('The selector argument must be a concrete byte array')
        sig = self._function_signatures_by_selector.get(hsh)
        if sig is not None:
            return dict(self._function_abi_items_by_signature[sig])
        item = self._fallback_function_abi_item
        if item is not None:
            return dict(item)
        # An item describing the default fallback function.
        return {'payable': False, 'stateMutability': 'nonpayable', 'type': 'fallback'}

def create_instance(self, collection_or_class, attributes, lazy=False, call_hook=True, deserialize=True, db_loader=None):
        creation_args = {
            'backend' : self,
            'autoload' : self._autoload_embedded,
            'lazy' : lazy,
            'db_loader' : db_loader
        }

        if collection_or_class in self.classes:
            cls = collection_or_class
        elif collection_or_class in self.collections:
            cls = self.collections[collection_or_class]
        else:
            raise AttributeError("Unknown collection or class: %s!" % str(collection_or_class))

        #we deserialize the attributes that we receive
        if deserialize:
            deserialized_attributes = self.deserialize(attributes, create_instance=False)
        else:
            deserialized_attributes = attributes

        if 'constructor' in self.classes[cls]:
            obj = self.classes[cls]['constructor'](deserialized_attributes, **creation_args)
        else:
            obj = cls(deserialized_attributes, **creation_args)

        if call_hook:
            self.call_hook('after_load',obj)

        return obj

