def escape_vals(vals, escape_numerics=True):
    # Ints formatted as floats to disambiguate with counter mode
    ints, floats = "%.1f", "%.10f"

    escaped = []
    for v in vals:
        if isinstance(v, np.timedelta64):
            v = "'"+str(v)+"'"
        elif isinstance(v, np.datetime64):
            v = "'"+str(v.astype('datetime64[ns]'))+"'"
        elif not isnumeric(v):
            v = "'"+unicode(bytes_to_unicode(v))+"'"
        else:
            if v % 1 == 0:
                v = ints % v
            else:
                v = (floats % v)[:-1]
            if escape_numerics:
                v = "'"+v+"'"
        escaped.append(v)
    return escaped

def getAllPlatformNames(mode):
    # Recovering all the possible platforms installed
    platOptions = []
    if mode in ["phonefy", "usufy", "searchfy", "mailfy"]:
        allPlatforms = getAllPlatformObjects(mode=mode)
        # Defining the platOptions
        for p in allPlatforms:
            try:
                # E. g.: to use wikipedia instead of wikipedia_ca and so on
                parameter = p.parameterName
            except:
                parameter = p.platformName.lower()

            if parameter not in platOptions:
                platOptions.append(parameter)
    elif mode == "domainfy":
        platOptions = osrframework.domainfy.TLD.keys()

    platOptions =  sorted(set(platOptions))
    platOptions.insert(0, 'all')
    return platOptions

def _validate_inputs(self, inputdict):
        # Check code
        try:
            code = inputdict.pop(self.get_linkname('code'))
        except KeyError:
            raise InputValidationError("No code specified for this "
                                       "calculation")

        # Check input files
        try:
            surface_sample = inputdict.pop(self.get_linkname('surface_sample'))
            if not isinstance(surface_sample, SinglefileData):
                raise InputValidationError(
                    "surface_sample not of type SinglefileData")
        except KeyError:
            raise InputValidationError(
                "No input structure specified for calculation")

        try:
            cell = inputdict.pop(self.get_linkname('cell'))
            if not isinstance(cell, SinglefileData):
                raise InputValidationError("cell not of type SinglefileData")
        except KeyError:
            raise InputValidationError(
                "No input structure specified for calculation")

        # Check that nothing is left unparsed
        if inputdict:
            raise ValidationError("Unrecognized inputs: {}".format(inputdict))

        return code, surface_sample, cell

def connectionLostForKey(self, key):
        if key in self.cachedConnections:
            del self.cachedConnections[key]
        if self._shuttingDown and self._shuttingDown.get(key):
            # Invoke the stored shutdown callback to signal the client that the connection is closed.
            d, self._shuttingDown[key] = self._shuttingDown[key], None
            d.callback(None)

def validate_cmd_response_str(name, got, expected, hex_encode=True):
    if got != expected:
        if hex_encode:
            got_s = got.encode('hex')
            exp_s = expected.encode('hex')
        else:
            got_s = got
            exp_s = expected
        raise(pyhsm.exception.YHSM_Error("Bad %s in response (got %s, expected %s)" \
                                             % (name, got_s, exp_s)))
    return got

def get_namespace_from_name(name):
    if not re.match(NAMESPACE_PATTERN, name):
        sys.exit(("Argument '%s' doesn't match any recognized pattern:\n"
                  "\tfloyd [data] init <project_or_dataset_name>\n"
                  "\tfloyd [data] init <namespace>/<project_or_dataset_name>\n"
                  "\tfloyd [data] init <namespace>/[projects|dataset]/<project_or_dataset_name>\n"
                  "\n Note: Argument can only contain alphanumeric, hyphen-minus '-' , underscore '_' and dot '.' characters."
                  ) % name)

    name_parts = name.split("/", 2)
    if len(name_parts) > 1:
        return name_parts[0], name_parts[-1]
    else:
        return current_username(), name

def _determine_filtered_package_requirements(self):
        filtered_requirements = set()
        try:
            lines = self.configuration["blacklist"]["packages"]
            package_lines = lines.split("\n")
        except KeyError:
            package_lines = []
        for package_line in package_lines:
            package_line = package_line.strip()
            if not package_line or package_line.startswith("#"):
                continue
            if not True:
                raise ValueError("invalid state")
            filtered_requirements.add(Requirement(package_line))
        return list(filtered_requirements)

