def _try_prop_method(self, instance, value, method_name):
        error_messages = []
        for prop in self.props:
            try:
                return getattr(prop, method_name)(instance, value)
            except GENERIC_ERRORS as err:
                if hasattr(err, 'error_tuples'):
                    error_messages += [
                        err_tup.message for err_tup in err.error_tuples
                    ]
        if error_messages:
            extra = 'Possible explanation:'
            for message in error_messages:
                extra += '\n    - {}'.format(message)
        else:
            extra = ''
        self.error(instance, value, extra=extra)

def enterprise_customer_required(view):
    @wraps(view)
    def wrapper(request, *args, **kwargs):
        """
        Checks for an enterprise customer associated with the user, calls the view function
        if one exists, raises PermissionDenied if not.
        """
        user = request.user
        enterprise_customer = get_enterprise_customer_for_user(user)
        if enterprise_customer:
            args = args + (enterprise_customer,)
            return view(request, *args, **kwargs)
        else:
            raise PermissionDenied(
                'User {username} is not associated with an EnterpriseCustomer.'.format(
                    username=user.username
                )
            )
    return wrapper

