def json2datetime(json):

        json_m = re.search(r'([0-9]+,[0-9]+,[0-9]+)(,[0-9]+,[0-9]+,[0-9]+)?(,[0-9]+)?', json)
        args=json_m.group(0).split(',')

        try:
            args=map(int, args)
        except ValueError:
            raise ValueError('Invalid arguments: %s'%json)

        if len(args)==3: 
            return datetime.datetime(args[0], args[1]+1, args[2])
        elif len(args)==6: 
            return datetime.datetime(args[0], args[1]+1, args[2], 
                                    args[3], args[4], args[5], tzinfo=UTC())
        elif len(args)==7:
            args[6]*=1000
            return datetime.datetime(args[0], args[1]+1, args[2], 
                                    args[3], args[4], args[5], args[6], tzinfo=UTC())
        raise ValueError('Invalid number of arguments: %s'%json)

def attributes(self):
        dictionary = {}
        # Only look for attributes registered in attribute_names.
        for python_attr_name, cookie_attr_name in self.attribute_names.items():
            value = getattr(self, python_attr_name)
            renderer = self.attribute_renderers.get(python_attr_name, None)
            if renderer:
                value = renderer(value)
            # If renderer returns None, or it's just natively none, then the
            # value is suppressed entirely - does not appear in any rendering.
            if not value:
                continue
            dictionary[cookie_attr_name] = value
        return dictionary

def merge(self, other):
        log.debug('Merging: %s and %s' % (self.serialize(), other.serialize()))
        for k in self.keys():
            for new_item in other[k]:
                if new_item not in self[k]:
                    self[k].append(new_item)
        log.debug('Result: %s' % self.serialize())
        return self

def _format(self, serie, i):
        value = serie.values[i]
        metadata = serie.metadata.get(i)

        kwargs = {'chart': self, 'serie': serie, 'index': i}
        formatter = ((metadata and metadata.get('formatter'))
                     or serie.formatter or self.formatter
                     or self._value_format)
        kwargs = filter_kwargs(formatter, kwargs)
        return formatter(value, **kwargs)

def _parse_config_property(item: _T, variables: Dict[str, Union[str, Path, float, bool, None]]) -> _T:
    if isinstance(item, str):
        return item.format(**variables)
    elif isinstance(item, list):
        return [_parse_config_property(item, variables) for item in item]
    elif isinstance(item, dict):
        return {k: _parse_config_property(v, variables) for k, v in item.items()}
    else:
        return item

