def _collect_capacity_curves(data, direction="charge"):

    minimum_v_value = np.Inf
    maximum_v_value = -np.Inf
    charge_list = []
    cycles = data.get_cycle_numbers()
    for cycle in cycles:
        try:
            if direction == "charge":
                q, v = data.get_ccap(cycle)
            else:
                q, v = data.get_dcap(cycle)

        except NullData as e:
            logging.warning(e)
            break

        else:
            d = pd.DataFrame({"q": q, "v": v})
            # d.name = f"{cycle}"
            d.name = cycle
            charge_list.append(d)
            v_min = v.min()
            v_max = v.max()
            if v_min < minimum_v_value:
                minimum_v_value = v_min
            if v_max > maximum_v_value:
                maximum_v_value = v_max
    return charge_list, cycles, minimum_v_value, maximum_v_value

def get_url_feed(self, package=None, timeout=None):
        if package is None:
            now = datetime.utcnow()
            five_minutes_ago = now - timedelta(
                minutes=now.minute % 5 + 5, seconds=now.second, microseconds=now.microsecond)
            package = five_minutes_ago.strftime('%Y%m%dT%H%M')

        params = {'apikey': self.api_key, 'package': package}

        try:
            response = requests.get(self.base + 'url/feed', params=params, proxies=self.proxies, timeout=timeout)
        except requests.RequestException as e:
            return dict(error=str(e))

        return _return_response_and_status_code(response, json_results=False)

