def poll_crontab(self):
        polled_time = self._get_current_time()
        if polled_time.second >= 30:
            self.log.debug('Skip cronjobs in {}'.format(polled_time))
            return
        for job in self._crontab:
            if not job.is_runnable(polled_time):
                continue
            job.do_action(self, polled_time)

def format_reference(ref, max_string_length=1000):
    _pass = lambda *args: None
    _numpy_info = ('dtype', 'shape', 'size', 'min', 'max')
    additionals = []
    if _NUMPY_INSTALLED and isinstance(ref, np.ndarray):
        # Check for numpy info
        for np_attr in _numpy_info:
            np_value = getattr(ref, np_attr, None)
            if np_value is not None:
                if inspect.isbuiltin(np_value):
                    try:
                        np_value = np_value()
                    except Exception as e:
                        logging.error(e)
                        continue
                additionals.append((np_attr, np_value))
    elif isinstance(ref, (list, tuple, set, dict)):
        # Check for length of reference
        length = getattr(ref, '__len__', _pass)()
        if length is not None:
            additionals.append(('length', length))

    if additionals:
        vstr = ', '.join(['%s: %s' % a for a in additionals] + [repr(ref)])
    else:
        vstr = repr(ref)

    if len(vstr) > max_string_length:
        vstr = vstr[:max_string_length] + ' ...'

    return vstr

def _remove_small_contigs(self, infile, outfile, keep=None):
        removed = set()
        all_names = set()
        if keep is None:
            keep = set()

        file_reader = pyfastaq.sequences.file_reader(infile)
        fout = pyfastaq.utils.open_file_write(outfile)

        for seq in file_reader:
            all_names.add(seq.id)
            if len(seq) >= self.min_contig_length or seq.id in keep:
                print(seq, file=fout)
            else:
                removed.add(seq.id)

        pyfastaq.utils.close(fout)
        return all_names, removed

