def get_module_plugins(module, classobj):
    try:
        names = module.__all__
    except AttributeError:
        names = [x for x in vars(module) if not x.startswith('_')]
    for name in names:
        try:
            obj = getattr(module, name)
        except AttributeError:
            continue
        try:
            if issubclass(obj, classobj):
                yield obj
        except TypeError:
            continue

def get_barcode_func(data, longbar):
    ## build func for finding barcode
    if longbar[1] == 'same':
        if data.paramsdict["datatype"] == '2brad':
            def getbarcode(cutters, read1, longbar):
                """ find barcode for 2bRAD data """
                return read1[1][:-(len(cutters[0][0]) + 1)][-longbar[0]:]

        else:
            def getbarcode(_, read1, longbar):
                """ finds barcode for invariable length barcode data """
                return read1[1][:longbar[0]]
    else:
        def getbarcode(cutters, read1, longbar):
            """ finds barcode for variable barcode lengths"""
            return findbcode(cutters, longbar, read1)
    return getbarcode

def validate_key(key):
    if len(key.split()) != 2:
        raise ValueError("'{}' is not in the form '(key) (mode)'".format(key))
    key, mode = key.split()
    if key.lower() not in KEY_TO_SEMITONE:
        raise ValueError(
            "Key {} is invalid; should be e.g. D or C# or Eb".format(key))
    if mode not in ['major', 'minor']:
        raise ValueError(
            "Mode '{}' is invalid; must be 'major' or 'minor'".format(mode))

