def notify(title,
           message,
           api_key=NTFY_API_KEY,
           provider_key=None,
           priority=0,
           url=None,
           retcode=None):

    data = {
        'apikey': api_key,
        'application': 'ntfy',
        'event': title,
        'description': message,
    }

    if MIN_PRIORITY <= priority <= MAX_PRIORITY:
        data['priority'] = priority
    else:
        raise ValueError('priority must be an integer from {:d} to {:d}'
                         .format(MIN_PRIORITY, MAX_PRIORITY))

    if url is not None:
        data['url'] = url

    if provider_key is not None:
        data['providerkey'] = provider_key

    resp = requests.post(
        API_URL, data=data, headers={
            'User-Agent': USER_AGENT,
        })

    resp.raise_for_status()

def find_file_regex(root_dir,re_expression,return_abs_path = True,search_sub_directories = True):

    compiled        = re.compile(re_expression)
    result          = []
    for dirpath, dirnames, files in os.walk(root_dir) :
        #Select files matching the expression
        for file in files :
            if compiled.match(file):
                result.append(os.path.join(dirpath,file) if return_abs_path else file )

        #Break if no sub-directories
        if not search_sub_directories :
            break
    return result

