            raise ZoneException('zone already loaded')

        def success(result, *args):
            self.data = result
            if callback:
                return callback(self)
            else:
                return self

        if zoneFile:
            return self._rest.import_file(self.zone, zoneFile,
                                          callback=success, errback=errback,
                                          **kwargs)
