def reaction_charge(reaction, compound_charge):

    charge_sum = 0.0
    for compound, value in reaction.compounds:
        charge = compound_charge.get(compound.name, float('nan'))
        charge_sum += charge * float(value)
    return charge_sum

def FlowManager(start_string, end_string):
    class Inner(object):
        def __init__(self, f, **kwargs):
            self.f = f
            self.kwargs = kwargs

        def __enter__(self):
            self.f.writeln(start_string.format(**self.kwargs))
            self.f.indent()

        def __exit__(self, type, value, traceback):
            self.f.deindent()
            self.f.writeln(end_string.format(**self.kwargs))
    return Inner

