def parse_connection_string(connection_string, default_port=8000):
    if '://' not in connection_string:
        connection_string = 'dummy://%s' % connection_string
    scheme, host, path, query, fragment = urlsplit(connection_string)
    if not scheme and not host:
        host, path = path, ''
    elif path and not query:
        query, path = path, ''
        if query:
            if query.find('?'):
                path = query
            else:
                query = query[1:]
    if path:
        raise ValueError("Address must not have a path. Found '%s'" % path)
    if query:
        params = dict(parse_qsl(query))
    else:
        params = {}
    if scheme == 'dummy':
        scheme = ''
    return scheme, parse_address(host, default_port), params

def flavor_absent(name, **kwargs):
    dry_run = __opts__['test']
    ret = {'name': name, 'result': False, 'comment': '', 'changes': {}}

    try:
        object_list = __salt__['nova.flavor_list'](**kwargs)
        object_id = object_list[name]['id']
    except KeyError:
        object_id = False

    if not object_id:
        ret['result'] = True
        ret['comment'] = 'Flavor "{0}" does not exist.'.format(name)
    else:
        if dry_run:
            ret['result'] = None
            ret['comment'] = 'Flavor "{0}", id: {1}  would be deleted.'.format(name, object_id)
            ret['changes'] = {name: {'old': 'Flavor "{0}", id: {1}  exists.'.format(name, object_id),
                                     'new': ret['comment']}}
        else:
            flavor_delete = __salt__['nova.flavor_delete'](object_id, **kwargs)

            if flavor_delete:
                ret['result'] = True
                ret['comment'] = 'Flavor "{0}", id: {1}  deleted.'.format(name, object_id)
                ret['changes'] = {name: {'old': 'Flavor "{0}", id: {1}  existed.'.format(name, object_id),
                                         'new': ret['comment']}}

    return ret

