def gcv(data, channels=None):
    # Slice data to take statistics from
    if channels is None:
        data_stats = data
    else:
        data_stats = data[:, channels]

    # Calculate and return statistic
    return np.sqrt(np.exp(np.std(np.log(data_stats), axis=0)**2) - 1)

