def tempfile_writer(target):
    tmp = target.parent / ('_%s' % target.name)
    try:
        with tmp.open('wb') as fd:
            yield fd
    except:
        tmp.unlink()
        raise
    LOG.debug('rename %s -> %s', tmp, target)
    tmp.rename(target)

def add_winners(self, G, I, known_winners, stats, possible_winners = None):
        if possible_winners is None:
            G_in_degree = G.in_degree(I)
            to_be_added = set([x[0] for x in G_in_degree if x[1] == 0])
        else:
            to_be_added = possible_winners
        for c in to_be_added:
            if c not in known_winners:
                known_winners.add(c)
                stats.discovery_states[c] = stats.num_nodes
                stats.discovery_times[c] = time.perf_counter() - self.BEGIN
                if self.debug_mode >= 2:
                    print("Found new winner:", c)

def add_mapping(self, data, name=None):
        from .mappings import DocumentObjectField
        from .mappings import NestedObject
        from .mappings import ObjectField

        if isinstance(data, (DocumentObjectField, ObjectField, NestedObject)):
            self.mappings[data.name] = data.as_dict()
            return

        if name:
            self.mappings[name] = data
            return
            if isinstance(data, dict):
                self.mappings.update(data)
            elif isinstance(data, list):
                for d in data:
                    if isinstance(d, dict):
                        self.mappings.update(d)
                    elif isinstance(d, DocumentObjectField):
                        self.mappings[d.name] = d.as_dict()
                    else:
                        name, data = d
                        self.add_mapping(data, name)

def iflat_nodes(self, status=None, op="==", nids=None):
        nids = as_set(nids)

        if status is None:
            if not (nids and self.node_id not in nids):
                yield self

            for work in self:
                if nids and work.node_id not in nids: continue
                yield work
                for task in work:
                    if nids and task.node_id not in nids: continue
                    yield task
        else:
            # Get the operator from the string.
            op = operator_from_str(op)

            # Accept Task.S_FLAG or string.
            status = Status.as_status(status)

            if not (nids and self.node_id not in nids):
                if op(self.status, status): yield self

            for wi, work in enumerate(self):
                if nids and work.node_id not in nids: continue
                if op(work.status, status): yield work

                for ti, task in enumerate(work):
                    if nids and task.node_id not in nids: continue
                    if op(task.status, status): yield task

