def field2type_and_format(self, field):
        # If this type isn't directly in the field mapping then check the
        # hierarchy until we find something that does.
        for field_class in type(field).__mro__:
            if field_class in self.field_mapping:
                type_, fmt = self.field_mapping[field_class]
                break
        else:
            warnings.warn(
                "Field of type {} does not inherit from marshmallow.Field.".format(
                    type(field)
                ),
                UserWarning,
            )
            type_, fmt = "string", None

        ret = {"type": type_}

        if fmt:
            ret["format"] = fmt

        return ret

def traverse_levelorder(self, leaves=True, internal=True):
        for node in self.root.traverse_levelorder(leaves=leaves, internal=internal):
            yield node

def insert(self, parts, leaf_value, update=False):
        tree = self
        if not parts:
            return tree

        tmp = tree
        last = len(parts) - 1
        for i, part in enumerate(parts):
            if part not in tmp:
                tmp[part] = TreeMap() if i != last else leaf_value
            elif i == last:  # found leaf
                if update:
                    tmp[part].update(leaf_value)
                else:
                    tmp[part] = leaf_value

            tmp = tmp[part]

        return self

