def parse_networking_file():

    pairs = dict()
    allocated_subnets = []
    try:
        with open(VMWARE_NETWORKING_FILE, "r", encoding="utf-8") as f:
            version = f.readline()
            for line in f.read().splitlines():
                try:
                    _, key, value = line.split(' ', 3)
                    key = key.strip()
                    value = value.strip()
                    pairs[key] = value
                    if key.endswith("HOSTONLY_SUBNET"):
                        allocated_subnets.append(value)
                except ValueError:
                    raise SystemExit("Error while parsing {}".format(VMWARE_NETWORKING_FILE))
    except OSError as e:
        raise SystemExit("Cannot open {}: {}".format(VMWARE_NETWORKING_FILE, e))
    return version, pairs, allocated_subnets

def on_update(self, value, *args, **kwargs):
        parent_value = self._parent_min
        if self._max != self._min:
            sub_progress = (value - self._min) / (self._max - self._min)
            parent_value = self._parent_min + sub_progress * (self._parent_max - self._parent_min)
        self._parent.update(parent_value, *args, **kwargs)

def union(self, weight_attr='_weight'):

        if type(self.master_graph) is nx.MultiDiGraph:
            graph = nx.DiGraph()
        else:
            graph = nx.Graph()

        edge_attrs = defaultdict(list)

        for u, v, a in self.master_graph.edges(data=True):
            if not graph.has_edge(u, v):
                graph.add_edge(u, v)
                graph[u][v]['graphs'] = []
                graph[u][v][weight_attr] = 0.

            for key, value in a.iteritems():
                if key not in graph[u][v]:
                    graph[u][v][key] = []
                graph[u][v][key].append(value)
            graph[u][v]['graphs'].append(a['graph'])
            graph[u][v][weight_attr] += 1.

        for u, a in self.master_graph.nodes(data=True):
            for key, value in a.iteritems():
                graph.node[u][key] = value

        return graph

