def accept(self, node, **kwargs):
        if node is None:
            return

        for v in self.visitors:
            v.enter(node)

        name = 'accept_' + node.__class__.__name__
        fn = getattr(self, name, self.default_accept)
        r = fn(node, **kwargs)

        for v in self.visitors:
            v.leave(node)

        return r

