def binarySearch(self, ip):
        if not ip.isdigit(): ip = self.ip2Long(ip)

        if self.__indexLen < 1:
            self.__f.seek(0)
            b = self.__f.read(8)
            self.__sPtr = self.getLong(b, 0)
            endPtr      = self.getLong(b, 4)
            self.__indexLen = endPtr - self.__sPtr

        startPtr = self.__sPtr
        indexLen = self.__indexLen

        self.__f.seek(startPtr)
        b = self.__f.read(indexLen+12)

        l, h, mixPtr = (0, int(indexLen/12), 0)
        while l <= h:
            m   = int((l+h)/2)
            ptr = startPtr + m*12
            self.__f.seek(ptr)

            b   = self.__f.read(12)
            sip = self.getLong(b, 0)
            eip = self.getLong(b, 4)

            if ip >= sip:
                if ip > eip:
                    l = m + 1
                else:
                    mixPtr = self.getLong(b, 8)
                    break;
            else:
                h = m - 1

        if mixPtr == 0: return "N2"

        return self.returnData(mixPtr)

def timeseries(self):
        if self._timeseries is None:
            # calculate time series for active and reactive power
            try:
                timeseries = \
                    self.grid.network.timeseries.generation_dispatchable[
                        self.type].to_frame('p')
            except KeyError:
                try:
                    timeseries = \
                        self.grid.network.timeseries.generation_dispatchable[
                            'other'].to_frame('p')
                except KeyError:
                    logger.exception("No time series for type {} "
                                     "given.".format(self.type))
                    raise

            timeseries = timeseries * self.nominal_capacity
            if self.timeseries_reactive is not None:
                timeseries['q'] = self.timeseries_reactive
            else:
                timeseries['q'] = timeseries['p'] * self.q_sign * tan(acos(
                    self.power_factor))

            return timeseries
        else:
            return self._timeseries.loc[
                   self.grid.network.timeseries.timeindex, :]

def check_md5sum_change(src_file):

    src_md5 = get_md5sum(src_file)

    src_md5_file = src_file + '.md5'
    src_file_changed = True
    if os.path.exists(src_md5_file):
        with open(src_md5_file, 'r') as file_checksum:
            ref_md5 = file_checksum.read()
        if src_md5 == ref_md5:
            src_file_changed = False

    if src_file_changed:
        with open(src_md5_file, 'w') as file_checksum:
            file_checksum.write(src_md5)

    return src_file_changed

def issue_line_with_user(self, line, issue):
        if not issue.get("pull_request") or not self.options.author:
            return line

        if not issue.get("user"):
            line += u" (Null user)"
        elif self.options.username_as_tag:
            line += u" (@{0})".format(
                issue["user"]["login"]
            )
        else:
            line += u" ([{0}]({1}))".format(
                issue["user"]["login"], issue["user"]["html_url"]
            )
        return line

