def tange_debyetemp(v, v0, gamma0, a, b, theta0):
    x = v / v0
    gamma = tange_grun(v, v0, gamma0, a, b)
    if isuncertainties([v, v0, gamma0, a, b, theta0]):
        theta = theta0 * np.power(x, (-1. * (1. - a) * gamma0)) * \
            unp.exp((gamma0 - gamma) / b)
    else:
        theta = theta0 * np.power(x, (-1. * (1. - a) * gamma0)) * \
            np.exp((gamma0 - gamma) / b)
    return theta

def get_value(self, key, default=None):
        def unique(seq, idfun=None):
            if idfun is None:
                def idfun(x):
                    return x
            # order preserving
            seen = {}
            result = []
            for item in seq:
                marker = idfun(item)
                if marker in seen:
                    continue
                seen[marker] = 1
                result.append(item)
            return result
        lst = self._settings.value('recent_files/%s' % key, default)
        # emtpy list
        if lst is None:
            lst = []
        # single file
        if isinstance(lst, str):
            lst = [lst]
        return unique([os.path.normpath(pth) for pth in lst])

def all_pages(method, request, accessor, cond=None):
    if cond is None:
        cond = lambda x: True
    result = []
    next_token = None
    while True:
        if next_token:
            request['nextToken'] = next_token
        response = method(**request)
        if cond(response):
            data = accessor(response)
            if data:
                if isinstance(data, list):
                    result.extend(data)
                else:
                    result.append(data)
        if 'nextToken' not in response:
            break
        next_token = response['nextToken']

    return result

