def parameters(self):

        if len(self.__members) != 0:
            if self.__num_processes > 1:
                members = [m.get() for m in self.__members]
            else:
                members = self.__members
            params = {}
            for p in self.__parameters:
                params[p.name] = sum(
                    m.parameters[p.name] for m in members
                ) / len(members)
            return params
        else:
            return None

def convert_flow_coefficient(flow_coefficient, old_scale, new_scale):
    # Convert from `old_scale` to Kv
    if old_scale == 'Cv':
        Kv = Cv_to_Kv(flow_coefficient)
    elif old_scale == 'Kv':
        Kv = flow_coefficient
    elif old_scale == 'Av':
        Cv = flow_coefficient/((rho0/psi)**0.5*gallon/minute)
        Kv = Cv_to_Kv(Cv)
    else:
        raise NotImplementedError("%s scale is unsupported" %old_scale)

    if new_scale == 'Cv':
        ans = Kv_to_Cv(Kv)
    elif new_scale == 'Kv':
        ans = Kv
    elif new_scale == 'Av':
        Cv = Kv_to_Cv(Kv)
        ans = Cv*((rho0/psi)**0.5*gallon/minute)
    else:
        raise NotImplementedError("%s scale is unsupported" %old_scale)

    return ans

