            try:
                user = self.mambuuserclass(urlfunc=None, entid=None, *args, **kwargs)
            except AttributeError as ae:
                self.mambuuserclass = self.itemclass
                user = self.mambuuserclass(urlfunc=None, entid=None, *args, **kwargs)
            user.init(u, *args, **kwargs)
