def _create_buffers(self):

        self.buffers = {}

        for step in self.graph.nodes():
            num_buffers = 1

            if isinstance(step, Reduction):
                num_buffers = len(step.parents)

            self.buffers[step] = Buffer(step.min_frames, step.left_context, step.right_context, num_buffers)

        return self.buffers

