            if not available:
                raise ValueError('No session available for association type %r'
                                 % (assoc_type,))

            for session_type in getSessionTypes(assoc_type):
                self.addAllowedType(assoc_type, session_type)
        else:
            checkSessionType(assoc_type, session_type)
            self.allowed_types.append((assoc_type, session_type))

def remote(func):

    @functools.wraps(func)
    def wrapper(self, *args, **kwargs):
        if self.mode == 'server':
            # In server mode, call the function
            return func(self, *args, **kwargs)

        # Make sure we're connected
        if not self.conn:
            self.connect()

        # Call the remote function
        self.conn.send('CALL', func.__name__, args, kwargs)

        # Receive the response
        cmd, payload = self.conn.recv()
        if cmd == 'ERR':
            self.close()
            raise Exception("Catastrophic error from server: %s" %
                            payload[0])
        elif cmd == 'EXC':
            exc_type = utils.find_entrypoint(None, payload[0])
            raise exc_type(payload[1])
        elif cmd != 'RES':
            self.close()
            raise Exception("Invalid command response from server: %s" % cmd)

        return payload[0]

    # Mark it a callable
    wrapper._remote = True

    # Return the wrapped function
    return wrapper

def _contains(expr, pat, case=True, flags=0, regex=True):

    if regex and isinstance(pat, six.string_types):
        import re
        try:
            re.compile(pat, flags=flags)
        except:
            raise ValueError('Failed to compile regular expression, '
                             'please check re.compile("{0}")'.format(pat))

    return _string_op(expr, Contains, output_type=types.boolean,
                      _pat=pat, _case=case, _flags=flags, _regex=regex)

def dumb_relative_half_prime(n, divisor = None):
    if n < 1 or not isinstance(n, int):
        raise Exception('n must be a positive non-zero integer.')
    elif n < 7:
        return dumb_relative_prime_const[n]
    elif n < 10:
        divisor = 2.0
    if not divisor:
        if n <= 20:
            divisor = 3.0
        elif n <= 30:
            divisor = 4.0
        else:
            divisor = 5.0
    m = int(n / divisor)
    while m > 1:
        if fractions.gcd(n, m) == 1:
            return m
        m -= 1
    if divisor > 2.0:
        return dumb_relative_half_prime(n, divisor - 1.0)

