def _trigger_offline_retrieval(self, url):
        with self.session.get(url, auth=self.session.auth, timeout=self.timeout) as r:
            # check https://scihub.copernicus.eu/userguide/LongTermArchive#HTTP_Status_codes
            if r.status_code == 202:
                self.logger.info("Accepted for retrieval")
            elif r.status_code == 503:
                self.logger.error("Request not accepted")
                raise SentinelAPILTAError('Request for retrieval from LTA not accepted', r)
            elif r.status_code == 403:
                self.logger.error("Requests exceed user quota")
                raise SentinelAPILTAError('Requests for retrieval from LTA exceed user quota', r)
            elif r.status_code == 500:
                # should not happen
                self.logger.error("Trying to download an offline product")
                raise SentinelAPILTAError('Trying to download an offline product', r)
            return r.status_code

def create_move(project, resource, offset=None):
    if offset is None:
        return MoveModule(project, resource)
    this_pymodule = project.get_pymodule(resource)
    pyname = evaluate.eval_location(this_pymodule, offset)
    if pyname is not None:
        pyobject = pyname.get_object()
        if isinstance(pyobject, pyobjects.PyModule) or \
           isinstance(pyobject, pyobjects.PyPackage):
            return MoveModule(project, pyobject.get_resource())
        if isinstance(pyobject, pyobjects.PyFunction) and \
           isinstance(pyobject.parent, pyobjects.PyClass):
            return MoveMethod(project, resource, offset)
        if isinstance(pyobject, pyobjects.PyDefinedObject) and \
           isinstance(pyobject.parent, pyobjects.PyModule) or \
           isinstance(pyname, pynames.AssignedName):
            return MoveGlobal(project, resource, offset)
    raise exceptions.RefactoringError(
        'Move only works on global classes/functions/variables, modules and '
        'methods.')

def _serve_forever_wrapper(self, _srv, poll_interval=0.1):
        self.logger.info('Opening tunnel: {0} <> {1}'.format(
            address_to_str(_srv.local_address),
            address_to_str(_srv.remote_address))
        )
        _srv.serve_forever(poll_interval)  # blocks until finished

        self.logger.info('Tunnel: {0} <> {1} released'.format(
            address_to_str(_srv.local_address),
            address_to_str(_srv.remote_address))
        )

