def perc_bc_from_lipid(perc_lipid, perc_water=None):
    import numpy

    # Cast iterables to numpy arrays
    if numpy.iterable(perc_lipid):
        perc_lipid = numpy.asarray(perc_lipid)
    if numpy.iterable(perc_water):
        perc_water = numpy.asarray(perc_water)

    if not perc_water:
        # TODO check where `perc_water` values come from
        perc_water   = 71.4966 - (0.6802721 * perc_lipid)

    perc_protein = (0.42 * perc_water) - 4.75
    perc_ash     = 100 - (perc_lipid + perc_water + perc_protein)

    return perc_water, perc_protein, perc_ash

def print_list_lines(self, filename, first, last):
        try:
            Colors = self.color_scheme_table.active_colors
            ColorsNormal = Colors.Normal
            tpl_line = '%%s%s%%s %s%%s' % (Colors.lineno, ColorsNormal)
            tpl_line_em = '%%s%s%%s %s%%s%s' % (Colors.linenoEm, Colors.line, ColorsNormal)
            src = []
            for lineno in range(first, last+1):
                line = linecache.getline(filename, lineno)
                if not line:
                    break

                if lineno == self.curframe.f_lineno:
                    line = self.__format_line(tpl_line_em, filename, lineno, line, arrow = True)
                else:
                    line = self.__format_line(tpl_line, filename, lineno, line, arrow = False)

                src.append(line)
                self.lineno = lineno

            print >>io.stdout, ''.join(src)

        except KeyboardInterrupt:
            pass

def _replace_image(image_url, image_tag, ebook_folder,
                   image_name=None):
    try:
        assert isinstance(image_tag, bs4.element.Tag)
    except AssertionError:
        raise TypeError("image_tag cannot be of type " + str(type(image_tag)))
    if image_name is None:
        image_name = str(uuid.uuid4())
    try:
        image_full_path = os.path.join(ebook_folder, 'images')
        assert os.path.exists(image_full_path)
        image_extension = save_image(image_url, image_full_path,
                                     image_name)
        image_tag['src'] = 'images' + '/' + image_name + '.' + image_extension
    except ImageErrorException:
        image_tag.decompose()
    except AssertionError:
        raise ValueError('%s doesn\'t exist or doesn\'t contain a subdirectory images' % ebook_folder)
    except TypeError:
        image_tag.decompose()

