def narrow_sqs(self, sqs):
        if self.select_many:
            sq = None
            for value in self.get_applicable_values():
                q = SQ(**{self.field_name: sqs.query.clean(value.value)})
                if sq:
                    sq = sq | q
                else:
                    sq = q
            if sq:
                sqs = sqs.narrow(sq)
        else:
            for value in self.get_applicable_values():
                sqs = sqs.narrow(
                    u'%s:"%s"' % (self.field_name, sqs.query.clean(value.value))
                )

        return sqs

def Map(self, function):
        new_table = self.__class__()
        # pylint: disable=protected-access
        new_table._table = [self.header]
        for row in self:
            filtered_row = function(row)
            if filtered_row:
                new_table.Append(filtered_row)
        return new_table

def _fetch_from_remote(self, method, args):
        try:
            if method == NNTTPClient.GROUP:
                data = self.handler.group(args)
            elif method == NNTTPClient.OVER:
                data = self.handler.over(args)
            elif method == NNTTPClient.ARTICLE:
                data = self._fetch_article(args)
        except nntplib.NNTPTemporaryError as e:
            data = e
            raise e
        finally:
            if self.archive:
                self.archive.store(method, args, None, data)

        return data

def handle_error(r, expected_code):
    code = r.status_code
    if code != expected_code:
        info = 'API response status code {}'.format(code)
        try:
            if 'detail' in r.json():
                info = info + ": {}".format(r.json()['detail'])
            elif 'metadata' in r.json():
                info = info + ": {}".format(r.json()['metadata'])
        except json.decoder.JSONDecodeError:
            info = info + ":\n{}".format(r.content)
        raise Exception(info)

def match(self, request, *, root=None, path=None, methods=None):
        match = Match()
        if path is not None:
            pattern = self.__get_pattern(path)
            match = pattern.match(request.path)
        elif root is not None:
            pattern = self.__get_pattern(root)
            match = pattern.match(request.path, left=True)
        if not match:
            return None
        if methods:
            methods = map(str.upper, methods)
            if request.method not in methods:
                return None
        return match

def extract(self):
        if not self.package_request.conflict:
            new_slice, package_request = self.variant_slice.extract()
            if package_request:
                assert(new_slice is not self.variant_slice)
                scope = copy.copy(self)
                scope.variant_slice = new_slice
                if self.pr:
                    self.pr("extracted %s from %s", package_request, self)
                return (scope, package_request)

        return (self, None)

