def get_brain_by_uid(self, uid):
        if uid == "0":
            return api.get_portal()

        # ensure we have the primary catalog
        if self._catalog is None:
            uid_catalog = api.get_tool("uid_catalog")
            results = uid_catalog({"UID": uid})
            if len(results) != 1:
                raise ValueError("No object found for UID '{}'".format(uid))
            brain = results[0]
            self._catalog = self.get_catalog_for(brain)

        # Fetch the brain with the primary catalog
        results = self.catalog({"UID": uid})
        if not results:
            raise ValueError("No results found for UID '{}'".format(uid))
        if len(results) != 1:
            raise ValueError("Found more than one object for UID '{}'"
                             .format(uid))
        return results[0]

def get_link_name (self, tag, attrs, attr):
        if tag == 'a' and attr == 'href':
            # Look for name only up to MAX_NAMELEN characters
            data = self.parser.peek(MAX_NAMELEN)
            data = data.decode(self.parser.encoding, "ignore")
            name = linkname.href_name(data)
            if not name:
                name = attrs.get_true('title', u'')
        elif tag == 'img':
            name = attrs.get_true('alt', u'')
            if not name:
                name = attrs.get_true('title', u'')
        else:
            name = u""
        return name

def start(st_reg_number):
    #st_reg_number = str(st_reg_number)
    weights = [9, 8, 7, 6, 5, 4, 3, 2]
    digit_state_registration = st_reg_number[-1]

    if len(st_reg_number) != 9:
        return False

    sum_total = 0

    for i in range(0, 8):
        sum_total = sum_total + weights[i] * int(st_reg_number[i])

    if sum_total % 11 == 0:
        return digit_state_registration[-1] == '0'

    digit_check = 11 - sum_total % 11

    return str(digit_check) == digit_state_registration

