        if 'LEONARDO' in key:
            return True

def _construct_location_to_filter_list(match_query):
    # For each location, all filters for that location should be applied at the first instance.
    # This function collects a list of all filters corresponding to each location
    # present in the given MatchQuery.
    location_to_filters = {}
    for match_traversal in match_query.match_traversals:
        for match_step in match_traversal:
            current_filter = match_step.where_block
            if current_filter is not None:
                current_location = match_step.as_block.location
                location_to_filters.setdefault(current_location, []).append(
                    current_filter)

    return location_to_filters

def OnLinkVLCVideo(self, event):

        key = self.grid.actions.cursor

        if event.videofile:
            try:
                video_volume = \
                    self.grid.code_array.cell_attributes[key]["video_volume"]
            except KeyError:
                video_volume = None

            self.grid.actions.set_attr("panel_cell", True)

            if video_volume is not None:
                code = 'vlcpanel_factory("{}", {})'.format(
                    event.videofile, video_volume)
            else:
                code = 'vlcpanel_factory("{}")'.format(event.videofile)

            self.grid.actions.set_code(key, code)

        else:
            try:
                video_panel = self.grid.grid_renderer.video_cells.pop(key)
                video_panel.player.stop()
                video_panel.player.release()
                video_panel.Destroy()
            except KeyError:
                pass

            self.grid.actions.set_code(key, u"")

