def validate(self, strict=True):
        valid = True
        try:
            jsonschema.validate(self.__json_light__, schema.JAMS_SCHEMA)

            for ann in self.annotations:
                if isinstance(ann, Annotation):
                    valid &= ann.validate(strict=strict)
                else:
                    msg = '{} is not a well-formed JAMS Annotation'.format(ann)
                    valid = False
                    if strict:
                        raise SchemaError(msg)
                    else:
                        warnings.warn(str(msg))

        except jsonschema.ValidationError as invalid:
            if strict:
                raise SchemaError(str(invalid))
            else:
                warnings.warn(str(invalid))

            valid = False

        return valid

def _prepare_value(self, value, dj_field=None):
        from django.db import models

        if isinstance(value, (six.string_types, int, float)):
            return value
        elif isinstance(value, SimpleLazyObject):
            return value.pk
        elif isinstance(value, models.Model):
            if dj_field:
                if isinstance(dj_field, models.ForeignKey):
                    return value.pk
                    #TODO validate other types
            return value
        elif isinstance(value, (ResultSet, EmptyQuerySet, EmptyResultSet, list)):
            return [self._prepare_value(v, dj_field=dj_field) for v in value]
        elif isinstance(value, QuerySet):
            value = value._clone()
            return [self._prepare_value(v, dj_field=dj_field) for v in value]
        return value

def envelope(self, data, many):
        if not many:
            return data

        result = dict(
            hits=dict(
                hits=data,
                total=self.context.get('total', len(data))
            )
        )

        page = self.context.get('page')
        if page:
            links_pagination_factory = self.context.get(
                'links_pagination_factory',
                default_links_pagination_factory
            )

            urlkwargs = self.context.get('urlkwargs', {})

            result['links'] = links_pagination_factory(page, urlkwargs)

        return result

def addstr(self, h, w, text, attrs=0):
        self.update_window_size()
        if h > self.height or w > self.width:
            return
        try:
            # Python curses addstr doesn't deal with non-ascii characters
            #self.window.addstr(h, w, text.encode("ascii", "ignore"), attrs)
            self.window.addstr(h, w, text, attrs)
        except Exception as e:
            pass

def write(self, buf):
        buf = align_buf(buf, self._sample_width)
        buf = normalize_audio_buffer(buf, self.volume_percentage)
        return self._sink.write(buf)

def _call(self, x, out=None):
        if out is None:
            out = x[self.index].copy()
        else:
            out.assign(x[self.index])
        return out

def in6_6to4ExtractAddr(addr):
    try:
        addr = inet_pton(socket.AF_INET6, addr)
    except:
        return None
    if addr[:2] != b" \x02":
        return None
    return inet_ntop(socket.AF_INET, addr[2:6])

def get_intel_notifications_feed(self, page=None, timeout=None):
        params = {'apikey': self.api_key, 'next': page}
        try:
            response = requests.get(self.base + 'hunting/notifications-feed/',
                                    params=params,
                                    proxies=self.proxies,
                                    timeout=timeout)
            # VT returns an empty result, len(content)==0, and status OK if there are no pending notifications.
            # To keep the API consistent we generate an empty object instead.
            # This might not be necessary with a later release of the VTI API. (bug has been submitted)
            if len(response.content) == 0:
                response.__dict__['_content'] = \
                    b'{"notifications":[],"verbose_msg":"No pending notification","result":0,"next":null}'
        except requests.RequestException as e:
            return dict(error=str(e))

        return _return_response_and_status_code(response)

def get_tohu_items_name(cls):
    assert issubclass(cls, TohuBaseGenerator)

    try:
        tohu_items_name = cls.__dict__['__tohu_items_name__']
        logger.debug(f"Using item class name '{tohu_items_name}' (derived from attribute '__tohu_items_name__')")
    except KeyError:
        m = re.match('^(.*)Generator$', cls.__name__)
        if m is not None:
            tohu_items_name = m.group(1)
            logger.debug(f"Using item class name '{tohu_items_name}' (derived from custom generator name)")
        else:
            msg = (
                "Cannot derive class name for items to be produced by custom generator. "
                "Please set '__tohu_items_name__' at the top of the custom generator's "
                "definition or change its name so that it ends in '...Generator'"
            )
            raise ValueError(msg)

    return tohu_items_name

