def mouse_handler(self, cli, mouse_event):
        b = cli.current_buffer

        if mouse_event.event_type == MouseEventType.MOUSE_UP:
            # Select completion.
            b.go_to_completion(mouse_event.position.y)
            b.complete_state = None

        elif mouse_event.event_type == MouseEventType.SCROLL_DOWN:
            # Scroll up.
            b.complete_next(count=3, disable_wrap_around=True)

        elif mouse_event.event_type == MouseEventType.SCROLL_UP:
            # Scroll down.
            b.complete_previous(count=3, disable_wrap_around=True)

def _set_i2c_speed(self, i2c_speed):
        lower_bits_mapping = {
            '400kHz': 3,
            '100kHz': 2,
            '50kHz': 1,
            '5kHz': 0,
        }
        if i2c_speed not in lower_bits_mapping:
            raise ValueError('Invalid i2c_speed')
        speed_byte = 0b01100000 | lower_bits_mapping[i2c_speed]
        self.device.write(bytearray([speed_byte]))
        response = self.device.read(1)
        if response != b"\x01":
            raise Exception("Changing I2C speed failed. Received: {}".format(repr(response)))

def already_pending(self, unit_type: Union[UpgradeId, UnitTypeId], all_units: bool=False) -> int:

        # TODO / FIXME: SCV building a structure might be counted as two units

        if isinstance(unit_type, UpgradeId):
            return self.already_pending_upgrade(unit_type)

        ability = self._game_data.units[unit_type.value].creation_ability

        amount = len(self.units(unit_type).not_ready)

        if all_units:
            amount += sum([o.ability == ability for u in self.units for o in u.orders])
        else:
            amount += sum([o.ability == ability for w in self.workers for o in w.orders])
            amount += sum([egg.orders[0].ability == ability for egg in self.units(UnitTypeId.EGG)])

        return amount

