def array_indented(level, l, quote_char='\'', comma_after=False):
    # type: (int, List[str], str, bool) -> str
    out = "[\n"
    for x in l:
        out += (((level+1) * 4) * " ") + '{}{}{}'.format(quote_char, x, quote_char) + ",\n"
    out += ((level * 4) * " ") + "]"
    if comma_after:
        out += ","
    return out

