def tagged_tasks(
            self,
            tag):
        self.refresh
        tasksList = []
        tag = tag.replace("@", "").lower()
        for t in self.tasks:
            for aTag in t.tags:
                if "(" not in tag:
                    aTag = aTag.split("(")[0]
                if aTag.lower() == tag:
                    tasksList.append(t)
                    break

            subtasks = t.tagged_tasks(tag)
            tasksList += subtasks

        isProject = False
        try:
            this = self.projects
            isProject = True
        except:
            pass

        if isProject:
            for p in self.projects:
                subtasks = p.tagged_tasks(tag)
                tasksList += subtasks

        return tasksList

