def _poll_slapd(self, timeout=DEFAULT_STARTUP_DELAY):

        begin = time.time()
        time.sleep(0.5)
        while time.time() < begin + timeout:
            if self._process.poll() is not None:
                raise RuntimeError("LDAP server has exited before starting listen.")

            s = socket.socket()
            try:
                s.connect(('localhost', self.port))
            except socket.error:
                # Not ready yet, sleep
                time.sleep(0.5)
            else:
                return
            finally:
                s.close()

        raise RuntimeError("LDAP server not responding within %s seconds." % timeout)

def _render_item(self, dstack, key, value = None, **settings):
        cur_depth = len(dstack) - 1

        treeptrn = ''
        s = self._es_text(settings, settings[self.SETTING_TREE_FORMATING])
        for ds in dstack:
            treeptrn += ' ' + self.fmt_text(self.tchar(settings[self.SETTING_TREE_STYLE], cur_depth, *ds), **s) + ''

        strptrn = "{}"
        if value is not None:
            strptrn += ": {}"
        s = self._es_text(settings, settings[self.SETTING_TEXT_FORMATING])
        strptrn = self.fmt_text(strptrn.format(key, value), **s)

        return '{} {}'.format(treeptrn, strptrn)

def _get_event_source_obj(awsclient, evt_source):
    event_source_map = {
        'dynamodb': event_source.dynamodb_stream.DynamoDBStreamEventSource,
        'kinesis': event_source.kinesis.KinesisEventSource,
        's3': event_source.s3.S3EventSource,
        'sns': event_source.sns.SNSEventSource,
        'events': event_source.cloudwatch.CloudWatchEventSource,
        'cloudfront': event_source.cloudfront.CloudFrontEventSource,
        'cloudwatch_logs': event_source.cloudwatch_logs.CloudWatchLogsEventSource,
    }

    evt_type = _get_event_type(evt_source)
    event_source_func = event_source_map.get(evt_type, None)
    if not event_source:
        raise ValueError('Unknown event source: {0}'.format(
            evt_source['arn']))

    return event_source_func(awsclient, evt_source)

