def load_plugin(self, p):
        if p.is_loaded():
            return
        # load required plugins first
        reqnames = p.required
        reqplugins = []
        for name in reqnames:
            try:
                reqplugins.append(self.__plugins[name])
            except KeyError as e:
                log.error("Required Plugin %s not found. Cannot load %s." % (name, p))
                raise errors.PluginInitError('Required Plugin %s not found. Cannot load %s. Reason: %s' % (name, p, e))
        for plug in reqplugins:
            try:
                self.load_plugin(plug)
            except errors.PluginInitError as e:
                log.error("Required Plugin %s could not be loaded. Cannot load %s" % (plug, p))
                raise errors.PluginInitError('Required Plugin %s could not be loaded. Cannot load %s. Reason: %s' % (plug,p, e))
        # load the actual plugin
        p._load()
        log.info('Initialized the plugin: %s' % p)

def filter_falsey(data, recurse_depth=None, ignore_types=()):
    filter_element = (
        functools.partial(filter_falsey,
                          recurse_depth=recurse_depth-1,
                          ignore_types=ignore_types)
        if recurse_depth else lambda x: x
    )

    if isinstance(data, dict):
        processed_elements = [(key, filter_element(value)) for key, value in six.iteritems(data)]
        return type(data)([
            (key, value)
            for key, value in processed_elements
            if _is_not_considered_falsey(value, ignore_types=ignore_types)
        ])
    elif hasattr(data, '__iter__') and not isinstance(data, six.string_types):
        # Apply the recursive filter to each element in the iterable dataset.
        processed_elements = (filter_element(value) for value in data)
        return type(data)([
            value for value in processed_elements
            if _is_not_considered_falsey(value, ignore_types=ignore_types)
        ])
    return data

def targets(self, tgt, tgt_type):
        targets = {}
        for back in self._gen_back():
            f_str = '{0}.targets'.format(back)
            if f_str not in self.rosters:
                continue
            try:
                targets.update(self.rosters[f_str](tgt, tgt_type))
            except salt.exceptions.SaltRenderError as exc:
                log.error('Unable to render roster file: %s', exc)
            except IOError as exc:
                log.error("Can't access roster for backend %s: %s", back, exc)

        log.debug('Matched minions: %s', targets)
        return targets

def _strip(string, pattern):
    m = re.compile(pattern).search(string)

    if m:
        return string[0:m.start()] + string[m.end():len(string)]
    else:
        return string

