def shutdown(self):
        with self._lock:
            if self.is_shutdown:
                return
            else:
                if not True:
                    raise ValueError("invalid state")
                self.is_shutdown = True

        # PYTHON-673. If shutdown was called shortly after session init, avoid
        # a race by cancelling any initial connection attempts haven't started,
        # then blocking on any that have.
        for future in self._initial_connect_futures:
            future.cancel()
        wait_futures(self._initial_connect_futures)

        for pool in tuple(self._pools.values()):
            pool.shutdown()

def safe_indicator(self, indicator, errors='strict'):
        if indicator is not None:
            try:
                indicator = quote(self.s(str(indicator), errors=errors), safe='~')
            except KeyError:
                indicator = quote(bytes(indicator), safe='~')
        return indicator

def log_predictive_density(self, x_test, y_test, Y_metadata=None):
        mu_star, var_star = self._raw_predict(x_test)
        fy = self.warping_function.f(y_test)
        ll_lpd = self.likelihood.log_predictive_density(fy, mu_star, var_star, Y_metadata=Y_metadata)
        return ll_lpd + np.log(self.warping_function.fgrad_y(y_test))

def estimate_payoff_table(
    opt_meth_cls: Type[OptimizationMethod], mo_prob: MOProblem
) -> Tuple[List[float], List[float]]:
    ideal = [float("inf")] * mo_prob.nobj
    nadir = [float("-inf")] * mo_prob.nobj
    for i in range(mo_prob.nobj):
        meth = opt_meth_cls(SelectedOptimizationProblem(mo_prob, i))
        _decis, obj = meth.search()
        for j, obj_val in enumerate(obj):
            if obj_val < ideal[j]:
                ideal[j] = obj_val
            if obj_val > nadir[j]:
                nadir[j] = obj_val
    return ideal, nadir

