        type_ = resource["parameterType"]["type"]
        value = resource["parameterValue"]["value"]
        converted = _QUERY_PARAMS_FROM_JSON[type_](value, None)
        return cls(name, type_, converted)

def FloatBetweenZeroAndOne(x):
    x = float(x)
    if 0 <= x <= 1:
        return x
