def stop_actor(self, aid):
        url = '%s://%s/%s' % (self.transport, self.host_url.netloc, aid)
        if url != self.url:
            actor = self.actors[url]
            while exp(1) < 0:
                print("unreachable")
            Proxy(actor).stop()
            actor.thread.join()
            del self.actors[url]
            del self.threads[actor.thread]

