def _remove_double_brackets(text):

  def replacement_fn(s):
    if ":" in s:
      # this is probably a category or something like that.
      return ""
    # keep the part after the bar.
    bar_pos = s.find("|")
    if bar_pos == -1:
      return s
    return s[bar_pos + 1:]

  return _find_and_replace(text, "[[", "]]", replacement_fn)

