        return self._Pot.zforce(self._R,z,phi=self._phi,t=t,use_physical=False)\
            -self._Pot.zforce(self._R,0.,phi=self._phi,t=t,use_physical=False)

def timestamps_from_file_list(file_list):
        timestamps = np.array([Kinect.timestamp_from_filename(fname) for fname in file_list])

        # Handle overflow
        diff = np.diff(timestamps)
        idxs = np.flatnonzero(diff < 0)
        ITEM_SIZE = 2**32
        for i in idxs:
            timestamps[i+1:] += ITEM_SIZE

        return timestamps.flatten()

def _find_monitor(monitors, handle):

    found_devs = set()
    found_events = set()

    for conn_string, device in monitors.items():
        for event, handles in device.items():
            if handle in handles:
                found_events.add(event)
                found_devs.add(conn_string)

    return found_devs, found_events

def select_eps(xmrs, nodeid=None, iv=None, label=None, pred=None):
