                chosen_samples = set(self.hash_to_ind) - self.samples
            else:
                chosen_samples = self.samples
            selected_indices = [self.hash_to_ind[h] for h in chosen_samples]
            return self.train[0][selected_indices], self.train[1][selected_indices]
        else:
            return self.train[0], self.train[1]

def auto_decompress_stream(src):
    block = next(src)
    compression = guess_compression(block)
    if compression == 'bz2':
        src = bz2_decompress_stream(chain([block], src))
    elif compression == 'xz':
        src = xz_decompress_stream(chain([block], src))
    else:
        src = chain([block], src)

    for block in src:
        yield block

