def dropdb(self, name):
        if self.readonly:
            raise s_exc.IsReadOnly()

        while True:
            try:
                if not self.dbexists(name):
                    return
                db = self.initdb(name)
                self.dirty = True
                self.xact.drop(db.db, delete=True)
                self.forcecommit()
                return

            except lmdb.MapFullError:
                self._handle_mapfull()

