def get_properties_of_kind(kind, start=None, end=None):
  q = Property.query(ancestor=Property.key_for_kind(kind))
  if start is not None and start != '':
    q = q.filter(Property.key >= Property.key_for_property(kind, start))
  if end is not None:
    if end == '':
      return []
    q = q.filter(Property.key < Property.key_for_property(kind, end))

  return [Property.key_to_property(k) for k in q.iter(keys_only=True)]

def _serialize_function(obj):
    try:
        obj = inspect.getsource(obj)
    except (TypeError, IOError):
        try:
            obj = marshal.dumps(obj)
        except ValueError:
            if hasattr(obj, '__dict__'):
                obj = _serialize_dict(obj.__dict__)
    return obj

def _get_site(self):
        import mwclient
        parts = self.server.settings.wiki.replace("http", "").replace("://", "").split("/")
        self.url = parts[0]
        if len(parts) > 1 and parts[1].strip() != "":
            self.relpath = '/' + '/'.join(parts[1:len(parts)])
            #The API expects us to have a trailing forward-slash.
            if self.relpath[-1] != "/":
                self.relpath += "/"
            if not self.testmode:
                self.site = mwclient.Site(self.url, path=self.relpath)
        else:
            if not self.testmode:
                self.site = mwclient.Site(self.url)

def to_bytes(value):
