def agg_multi_func(values, agg_field, agg_funcs, group_by=None):
        if len(values) == 0:
            return None
        else:
            if group_by:
                group_aggs = pd.DataFrame(values).groupby(group_by).agg({agg_field: agg_funcs})
                res = {}
                for row in group_aggs.itertuples():
                    row_res = {}
                    for i, func in enumerate(agg_funcs):
                        row_res.update({func: row[i+1]})
                    res.update({row[0]: row_res})
                return res
            else:
                aggs = pd.DataFrame(values).agg({agg_field: agg_funcs})
                res = {}
                for func in agg_funcs:
                    res.update({func: aggs[agg_field][func]})
                return res

def retry_until_valid_or_limit_reached(method, limit, validation_fn, sleep_s=1,
                                       catch_exceptions=()):
  assert limit > 0, 'Limit must be greater than 0'

  def _execute_method(helper):
    try:
      return method()
    except catch_exceptions:
      if not helper.remaining:
        raise
      return None

  helper = RetryHelper(limit - 1)
  result = _execute_method(helper)
  while not validation_fn(result) and helper.retry_if_possible():
    time.sleep(sleep_s)
    result = _execute_method(helper)
  return result

def filter_counter(self, counter, min=2, max=100000000):
        records_filterd = {}
        counter_all_records = 0
        for item in counter:
            counter_all_records += 1
            if max > counter[item] >= min:
                records_filterd[item] = counter[item]

        self.stat['user_record_events'] = counter_all_records
        self.stat['records_filtered'] = len(records_filterd)
        return records_filterd

