def expValue(self, pred):
    if len(pred) == 1:
      return pred.keys()[0]

    return sum([x*p for x,p in pred.items()])

def Tandon_Varma_Gupta(x, rhol, rhog, mul, mug, m, D):
    G = m/(pi/4*D**2)
    Rel = G*D/mul
    Xtt = Lockhart_Martinelli_Xtt(x, rhol, rhog, mul, mug)
    Fxtt = 0.15*(Xtt**-1 + 2.85*Xtt**-0.476)
    if Rel < 1125:
        alpha = 1 - 1.928*Rel**-0.315/Fxtt + 0.9293*Rel**-0.63/Fxtt**2
    else:
        alpha = 1 - 0.38*Rel**-0.088/Fxtt + 0.0361*Rel**-0.176/Fxtt**2
    return alpha

def bulk_create_datetimes(date_start: DateTime,
                              date_end: DateTime, **kwargs) -> List[DateTime]:
        dt_objects = []

        if not date_start and not date_end:
            raise ValueError('You must pass date_start and date_end')

        if date_end < date_start:
            raise ValueError('date_start can not be larger than date_end')

        while date_start <= date_end:
            date_start += timedelta(**kwargs)
            dt_objects.append(date_start)

        return dt_objects

