def valid_processor_options(processors=None):
    if processors is None:
        processors = [
            dynamic_import(p) for p in
            tuple(settings.THUMBNAIL_PROCESSORS) +
            tuple(settings.THUMBNAIL_SOURCE_GENERATORS)]
    valid_options = set(['size', 'quality', 'subsampling'])
    for processor in processors:
        args = inspect.getfullargspec(processor)[0] if six.PY3 else inspect.getargspec(processor)[0]
        # Add all arguments apart from the first (the source image).
        valid_options.update(args[1:])
    return list(valid_options)

def get_options(argv=None):
    if not argv:
        argv = sys.argv[1:]
    try:
        opts, args = getopt.getopt(argv, "d:co:f:",
                                   ["format=", "output=", "color=",
                                    "scale=", "font-family=", "font-size=",
                                    "line-width=", "debug-level=",
                                    "title=", "author=", "creation_date=",
                                    "creator=",
                                    "bbox="])
    except getopt.GetoptError as e:
        print(e)
        usage()
        raise
    else:
        for opt, arg in opts:
            if opt == "-d":
                parse_option("debug-level", arg)
            elif opt == "-c":
                parse_option("color", None)
            elif opt == "-o":
                parse_option("output", arg)
            elif opt == "-f":
                parse_option("format", arg)
            else:
                parse_option(opt[2:], arg)
        reinitialize()
        return args

