def _crc16(data, crc, table):
    bytes_to_int = lambda x: ord(x) if sys.version_info.major == 2 else x
    for byte in data:
        crc = ((crc << 8) & 0xff00) ^ table[((crc >> 8) & 0xff) ^ bytes_to_int(byte)]
    return crc & 0xffff

def inject(fun: Callable) -> Callable:
    sig = inspect.signature(fun)

    injectables: Dict[str, Any] = {}
    for name, param in sig.parameters.items():
        type_ = param.annotation
        if name == 'self':
            continue
        else:
            injectables[name] = type_

    @wraps(fun)
    def _inner(*args, **kwargs):
        container = Container()
        for n, t in injectables.items():
            if n not in kwargs:
                kwargs[n] = container.get_object(t)

        return fun(*args, **kwargs)

    return _inner

def flatten(lst):
    for elm in lst:
        if isinstance(elm, collections.Iterable) and not isinstance(
                elm, string_types):
            for sub in flatten(elm):
                yield sub
        else:
            yield elm

