def ensure_compliance(self):
        if not self.modules:
            return

        try:
            loaded_modules = self._get_loaded_modules()
            non_compliant_modules = []
            for module in self.modules:
                if module in loaded_modules:
                    log("Module '%s' is enabled but should not be." %
                        (module), level=INFO)
                    non_compliant_modules.append(module)

            if len(non_compliant_modules) == 0:
                return

            for module in non_compliant_modules:
                self._disable_module(module)
            self._restart_apache()
        except subprocess.CalledProcessError as e:
            log('Error occurred auditing apache module compliance. '
                'This may have been already reported. '
                'Output is: %s' % e.output, level=ERROR)

def process(self):

        self.__insert_data();
        self.__extract_features();

        # in line with specification modify hierarchical algorithm should be used for further clustering
        current_number_clusters = len(self.__features);

        while (current_number_clusters > self.__number_clusters):
            indexes = self.__find_nearest_cluster_features();

            self.__features[indexes[0]] += self.__features[indexes[1]];
            self.__features.pop(indexes[1]);

            current_number_clusters = len(self.__features);

        # decode data
        self.__decode_data();

