def load_xml(self, filepath):
        from os import path
        import xml.etree.ElementTree as ET
        #Make sure the file exists and then import it as XML and read the values out.
        uxpath = path.expanduser(filepath)
        if path.isfile(uxpath):
            tree = ET.parse(uxpath)
            vms("Parsing global settings from {}.".format(uxpath))
            root = tree.getroot()

            for child in root:
                if child.tag == "var":
                    self._vardict[child.attrib["name"]] = child.attrib["value"]

def int_out_of_bounds(self, index, axis=0):
        #if index >= self._global_shape[axis]:
        if index > self._global_shape[axis]:
            raise IndexError('index is larger than the upper bound')

        # wrap around index if negative like in python
        if index < 0:
            index += self._global_shape[axis]
            #warnings.warn('warp around may occur')

        # check for invalid wrap around
        if index < 0:
            raise IndexError('index is smaller than the lower bound')

        return index

