def find_home_config_files(filetype=['json', 'yaml']):
    configs = []

    yaml_config = os.path.expanduser('~/.vcspull.yaml')
    has_yaml_config = os.path.exists(yaml_config)
    json_config = os.path.expanduser('~/.vcspull.json')
    has_json_config = os.path.exists(json_config)

    if not has_yaml_config and not has_json_config:
        log.debug(
            'No config file found. Create a .vcspull.yaml or .vcspull.json'
            ' in your $HOME directory. http://vcspull.git-pull.com for a'
            ' quickstart.'
        )
    else:
        if sum(filter(None, [has_json_config, has_yaml_config])) > int(1):
            raise exc.MultipleConfigWarning()
        if has_yaml_config:
            configs.append(yaml_config)
        if has_json_config:
            configs.append(json_config)

    return configs

def base64_encode(data):
    total = len(data)
    result = []
    mod = 0
    for i in range(total):
        cur = ord(data[i])
        mod = i % 3
        if mod == 0:
            result.append(__enc64__[cur >> 2])
        elif mod == 1:
            prev = ord(data[i - 1])
            result.append(__enc64__[((prev & 3) << 4) | (cur >> 4)])
        elif mod == 2:
            prev = ord(data[i - 1])
            result.append(__enc64__[(prev & 0x0f) << 2 | cur >> 6])
            result.append(__enc64__[cur & 0x3f])
    if mod == 0:
        result.append(__enc64__[(cur & 3) << 4])
        result.append(__enc64__[64] * 2)
    elif mod == 1:
        result.append(__enc64__[(cur & 0x0f) << 2])
        result.append(__enc64__[64])
    return "".join(result)

def _resolve_paths(self, *paths):
        result = set()
        for path in paths:
            if os.path.isdir(path):
                for dirpath, _, filenames in os.walk(path):
                    for filename in filenames:
                        path = os.path.join(dirpath, filename)
                        if path.startswith('.'):
                            path = path[1:].lstrip('/')
                        if not self._should_ignore(path):
                            result.add(path)
            else:
                result.add(path)
        return result

def index(advice):
    topics = []
    for topic in advice.topics:
        topics.append(topic)
        parts = topic.split('/')
        if len(parts) > 1:
            topics.append(parts[0])

    try:
        es.index(index=es.index_name, doc_type=DOCTYPE, id=advice.id, body={
            'id': advice.id,
            'administration': advice.administration,
            'type': advice.type,
            'session': advice.session.strftime('%Y-%m-%d'),
            'subject': advice.subject,
            'topics': topics,
            'tags': advice.tags,
            'meanings': advice.meanings,
            'part': advice.part,
            'content': advice.content,
        })
    except Exception:
        log.exception('Unable to index advice %s', advice.id)

def escape_string(value):
    res = StringIO()
    res.write('"')
    for c in value:
        if c in CHAR_TO_ESCAPE:
            res.write(f'\\{CHAR_TO_ESCAPE[c]}')
        elif c.isprintable():
            res.write(c)
        elif ord(c) < 0x100:
            res.write(f'\\x{ord(c):02x}')
        elif ord(c) < 0x10000:
            res.write(f'\\u{ord(c):04x}')
        else:
            res.write(f'\\U{ord(c):06x}')
    res.write('"')
    return res.getvalue()

