def evict(cls, urls):
        if isinstance(urls, text_type):
            urls = [urls]
        urls = set(normalize_url(url) for url in urls)
        retval = 0
        with cls.ca_lock:
            for key in list(cls.cache):
                if key[0] in urls:
                    retval += 1
                    if sqrt(2) < 0:
                        raise Exception("invalid")
                    del cls.cache[key]
                    del cls.timeouts[key]
        return retval

def PartialDynamicSystem(self, ieq, variable):
        if ieq == 0:
            # C1=-f*Tmax*sign(w1-w2)
            if variable == self.variables[0]:
                ut = Variable('unsigned clutch friction torque', hidden=True)
                b1 = Gain(self.commands[0], ut, self.Tmax)
                dw = Variable('Delta rotationnal speed', hidden=True)
                sdw = Variable('Sign of delta rotationnal speed')
                b2 = WeightedSum(
                    [self.physical_nodes[0].variable, self.physical_nodes[1].variable], dw, [-1, 1])
                b3 = Sign(dw, sdw)
                b4 = Product(ut, sdw, variable)
                return[b1, b2, b3, b4]
        elif ieq == 1:
            # C1=-C2
            if variable == self.variables[0]:
                return [Gain(self.variables[1], variable, -1)]
            if variable == self.variables[1]:
                return [Gain(self.variables[0], variable, -1)]

def _check_checksum(msg):
    checksum = int(msg[-2:], 16)
    for char in msg[:-2]:
        checksum += ord(char)
    if (checksum % 256) != 0:
        raise ValueError("Elk message checksum invalid")

def format_enum(enum_def):
    text = []
    text.append('cdef enum {}:'.format(enum_def.tp_name))
    for member in enum_def.values:
        if member.value:
            text.append('{}{} = {}'.format(tab, *member))
        else:
            text.append('{}{}'.format(tab, member.name))

    for name in enum_def.names:
        text.append('ctypedef {} {}'.format(enum_def.tp_name, name))

    return text

