                                    httpc=self.httpc, **kwargs)
        else:
            kb = self.keybundle_cls(source=url, verify_ssl=self.verify_ssl,
                                    httpc=self.httpc, **kwargs)

        kb.update()
        self.add_kb(issuer, kb)

        return kb

