def target_color_type(y):
    ttype = type_of_target(y)

    if ttype.startswith(CONTINUOUS):
        return CONTINUOUS

    if ttype.startswith("binary"):
        return DISCRETE

    if ttype.startswith("multiclass"):
        if len(np.unique(y)) > MAX_DISCRETE_CLASSES:
            return CONTINUOUS
        return DISCRETE

    return UNKNOWN

