def is_population_germline(rec):
    min_count = 50
    for k in population_keys:
        if k in rec.info:
            val = rec.info.get(k)
            if "," in val:
                val = val.split(",")[0]
            if isinstance(val, (list, tuple)):
                val = max(val)
            if int(val) > min_count:
                return True
    return False

