def formula_double_format(afloat, ignore_ones=True, tol=1e-8):
    if ignore_ones and afloat == 1:
        return ""
    elif abs(afloat - int(afloat)) < tol:
        return str(int(afloat))
    else:
        return str(round(afloat, 8))

def delete(
        self
    ):

        projectTitle = self.title
        theseProjects = self.parent.projects[:]
        for p in theseProjects:
            if p.title == projectTitle:
                theseProjects.remove(p)
                break
        self.parent.projects = theseProjects

        doc = self
        while doc:
            if not doc.parent:
                break
            else:
                doc = doc.parent

        doc.content = doc.to_string(indentLevel=0, title=False)

        return None

