def _create_column(data, col, value):
    with suppress(AttributeError):
        # If the index of a series and the dataframe
        # in which the series will be assigned to a
        # column do not match, missing values/NaNs
        # are created. We do not want that.
        if not value.index.equals(data.index):
            if len(value) == len(data):
                value.index = data.index
            else:
                value.reset_index(drop=True, inplace=True)

    # You cannot assign a scalar value to a dataframe
    # without an index. You need an interable value.
    if data.index.empty:
        try:
            len(value)
        except TypeError:
            scalar = True
        else:
            scalar = isinstance(value, str)

        if scalar:
            value = [value]

    data[col] = value
    return data

def add(self, d, left):
        if left:
            self._add_left(d)
        else:
            self._add_right(d)

def _read_data(self):
        while True:
            try:
                data = yield from self._socket.recv()
            except asyncio.CancelledError:
                break
            except ConnectionClosed:
                break

            self._push_packet(data)

        self._loop.call_soon(self.close)

def find_element(self, value, by=By.ID, update=False) -> Elements:
        if update or not self._nodes:
            self.uidump()
        for node in self._nodes:
            if node.attrib[by] == value:
                bounds = node.attrib['bounds']
                coord = list(map(int, re.findall(r'\d+', bounds)))
                click_point = (coord[0] + coord[2]) / \
                    2, (coord[1] + coord[3]) / 2
                return self._element_cls(self, node.attrib, by, value, coord, click_point)
        raise NoSuchElementException(f'No such element: {by}={value!r}.')

def cmd_http_headers(server, verbose):
    if verbose:
        logging.basicConfig(level=logging.INFO, format='%(message)s')

    if verbose:
        print("[-] Retrieving the HTTP headers of the server...")

    headers = get_headers(server)

    if headers is not False:
        print(json.dumps(headers, indent=4))
    else:
        print("[X] URL {} is not valid!", file=sys.stderr)

    if verbose:
        print("[+] HTTP headers from {} retrieved".format(server))

    return True

def driver_from_file(input_file):
    file_ext = os.path.splitext(input_file)[1].split(".")[1]
    if file_ext not in _file_ext_to_driver():
        raise MapcheteDriverError(
            "no driver could be found for file extension %s" % file_ext
        )
    driver = _file_ext_to_driver()[file_ext]
    if len(driver) > 1:
        warnings.warn(
            DeprecationWarning(
                "more than one driver for file found, taking %s" % driver[0]
            )
        )
    return driver[0]

