def from_lambda(cls, name, lambda_):
        if PY2:  # pragma: no cover
            a = inspect.getargspec(lambda_)
            varargs, varkw, defaults, kwonlyargs = (
                a.varargs, a.keywords, a.defaults, None,
            )
        else:  # pragma: no cover
            a = inspect.getfullargspec(lambda_)
            varargs, varkw, defaults, kwonlyargs = (
                a.varargs, a.varkw, a.defaults, a.kwonlyargs,
            )

        if varargs or varkw or defaults or kwonlyargs:
            raise TypeError(
                'functions cannot have starargs or defaults: {} {}'.format(
                    name, lambda_,
                ),
            )
        return cls(name, a.args, lambda_)

def filter_kwargs(_function, *args, **kwargs):

    if has_kwargs(_function):
        return _function(*args, **kwargs)

    # Get the list of function arguments
    func_code = six.get_function_code(_function)
    function_args = func_code.co_varnames[:func_code.co_argcount]
    # Construct a dict of those kwargs which appear in the function
    filtered_kwargs = {}
    for kwarg, value in list(kwargs.items()):
        if kwarg in function_args:
            filtered_kwargs[kwarg] = value
    # Call the function with the supplied args and the filtered kwarg dict
    return _function(*args, **filtered_kwargs)

def get_instance_variables(node, bound_name_classifier=BOUND_METHOD_ARGUMENT_NAME):
    node_attributes = [
        child
        for child in ast.walk(node)
        if isinstance(child, ast.Attribute) and
        get_attribute_name_id(child) == bound_name_classifier
    ]
    node_function_call_names = [
        get_object_name(child)
        for child in ast.walk(node)
        if isinstance(child, ast.Call)
    ]
    node_instance_variables = [
        attribute
        for attribute in node_attributes
        if get_object_name(attribute) not in node_function_call_names
    ]
    return node_instance_variables

