def read(self, nrml_file, validate=False,
             simple_fault_spacing=1.0, complex_mesh_spacing=5.0,
             mfd_spacing=0.1):
        self.source_file = nrml_file
        if validate:
            converter = SourceConverter(1.0, simple_fault_spacing,
                                        complex_mesh_spacing,
                                        mfd_spacing,
                                        10.0)
            converter.fname = nrml_file
        root = nrml.read(nrml_file)
        if root['xmlns'] == 'http://openquake.org/xmlns/nrml/0.4':
            sg_nodes = [root.sourceModel.nodes]
        else:  # NRML 0.5
            sg_nodes = root.sourceModel.nodes
        sources = []
        for sg_node in sg_nodes:
            for no, src_node in enumerate(sg_node, 1):
                if validate:
                    print("Validating Source %s" % src_node.attrib["id"])
                    converter.convert_node(src_node)
                sources.append(src_node)
        return SourceModel(sources)

def handle(self):

        all_data = []
        while True:
            data = self.request.recv(1024)
            if not data:
                break

            if self.codes.server_shutdown in data:
                return self.__server_shutdown()

            if self.codes.request_end in data:
                all_data.append(data[:data.find(self.codes.request_end)])
                break

            all_data.append(data)
            if len(all_data) >= 2:
                tail = all_data[-2] + all_data[-1]

                if self.codes.server_shutdown in tail:
                    return self.__server_shutdown()

                if self.codes.request_end in tail:
                    all_data[-2] = tail[:tail.find(self.codes.request_end)]
                    all_data.pop()
                    break

        RuntimeGlobals.requests_stack.append("".join(all_data))
        return True

def array(self):
        if self._intervals_len:
            if self._array_len != self._intervals_len:
                if not self._array_len:
                    self._array = np.array(self.intervals) \
                        if hasattr(np, 'array') else self.intervals
                else:
                    self._array = np.concatenate((
                        self._array, self.intervals), axis=0) \
                        if hasattr(np, 'concatenate') else \
                        (self._array + self.intervals)
                self._array_len += len(self.intervals)
                self.intervals = []
            return self._array
        return []

