def assert_hasattr(attr: str, msg: str, tp: BaseException = SpotifyException) -> Callable:
    def decorator(func: Callable) -> Callable:
        @functools.wraps(func)
        def decorated(self, *args, **kwargs):
            if not hasattr(self, attr):
                raise tp(msg)
            return func(self, *args, **kwargs)

        if inspect.iscoroutinefunction(func):
            @functools.wraps(func)
            async def decorated(*args, **kwargs):
                return await decorated(*args, **kwargs)

        return decorated
    return decorator

def _run(self, command: List[str], notebook: Optional[str] = None) -> int:
        if notebook is None:
            return Popen(command, cwd=self._build_dir).wait()
        cmd = Popen(command, cwd=self._build_dir, stdout=PIPE, stderr=STDOUT)
        while True:
            line = cmd.stdout.readline()
            if line == b'' and cmd.poll() is not None:
                return cmd.poll()
            print(line.decode('utf-8'), end='')
        raise Exception()

def select_edges_by_attribute(docgraph, attribute=None, value=None, data=False):
    if attribute:
        attrib_key_eval = "'{}' in edge_attribs".format(attribute)

        if value is not None:
            if isinstance(value, basestring):
                attrib_val_eval = \
                    "edge_attribs['{0}'] == '{1}'".format(attribute, value)
                return select_edges(
                    docgraph, data=data,
                    conditions=[attrib_key_eval, attrib_val_eval])

            else:  # ``value`` is a list/set/dict of values
                attrib_val_evals = \
                    ["edge_attribs['{0}'] == '{1}'".format(attribute, v)
                     for v in value]
                results = \
                    [select_edges(docgraph, data=data,
                                  conditions=[attrib_key_eval, val_eval])
                     for val_eval in attrib_val_evals]
                # results is a list of generators
                return itertools.chain(*results)

        else:  # yield all edges with the given attribute, regardless of value
            return select_edges(docgraph, data=data, conditions=[attrib_key_eval])

    else:  # don't filter edges at all
        return docgraph.edges_iter(data=data)

def tocvx(B):
    Bcoo = B.tocoo()
    return spmatrix(Bcoo.data, Bcoo.row.tolist(), Bcoo.col.tolist())

def setAccessRules(self, pid, public=False):
        url = "{url_base}/resource/accessRules/{pid}/".format(url_base=self.url_base,
                                                              pid=pid)
        params = {'public': public}

        r = self._request('PUT', url, data=params)
        if r.status_code != 200:
            if r.status_code == 403:
                raise HydroShareNotAuthorized(('PUT', url))
            elif r.status_code == 404:
                raise HydroShareNotFound((pid,))
            else:
                raise HydroShareHTTPException((url, 'PUT', r.status_code, params))

        resource = r.json()
        assert(resource['resource_id'] == pid)
        return resource['resource_id']

def get_values(self, config_manager, ignore_mismatches, obj_hook=DotDict):
        if self.delayed_parser_instantiation:
            try:
                app = config_manager._get_option('admin.application')
                source = "%s%s" % (app.value.app_name, file_name_extension)
                self.config_obj = configobj.ConfigObj(source)
                self.delayed_parser_instantiation = False
            except AttributeError:
                # we don't have enough information to get the ini file
                # yet.  we'll ignore the error for now
                return obj_hook()  # return empty dict of the obj_hook type
        if isinstance(self.config_obj, obj_hook):
            return self.config_obj
        return obj_hook(initializer=self.config_obj)

