def _parse_args(func, variables, annotations=None):
    arg_read_var = []
    for arg_name, anno in (annotations or func.__annotations__).items():
        if arg_name == 'return':
            continue
        var, read = _parse_arg(func, variables, arg_name, anno)
        arg = Argument(name=arg_name, read=read)
        arg_read_var.append((arg, var))
    return arg_read_var

def load_data(filename, format_file='cloudupdrs', button_left_rect=None, button_right_rect=None):
    if format_file == 'mpower':
        return load_mpower_data(filename)

    elif format_file == 'segmented':
        return load_segmented_data(filename)

    elif format_file == 'accapp':
        return load_accapp_data(filename)

    elif format_file == 'physics':
        return load_physics_data(filename)

    elif format_file == 'freeze':
        return load_freeze_data(filename)

    elif format_file == 'huga':
        return load_huga_data(filename)

    else:
        if format_file == 'ft_cloudupdrs':
            return load_finger_tapping_cloudupdrs_data(filename)
        else:
            if format_file == 'ft_mpower':
                if button_left_rect is not None and button_right_rect is not None:
                    return load_finger_tapping_mpower_data(filename, button_left_rect, button_right_rect)
            else:
                return load_cloudupdrs_data(filename)

def graph_simplify(G):
    spurs = []
    path_nodes = []
    for k, d in G.degree().iteritems():
        if d == 1:
            spurs.append(k)
        elif d == 2:
            path_nodes.append(k)

    logging.debug("Remove {0} spurs.".format(len(spurs)))
    G.remove_nodes_from(spurs)

    SG = G.subgraph(path_nodes)
    cc = nx.connected_components(SG)
    for c in cc:
        if len(c) == 1:
            continue
        c = set(c)
        neighbors = set()
        for x in c:
            neighbors |= set(G.neighbors(x))
        neighbors -= c
        newtag = list(c)[0] + "*"
        for n in neighbors:
            G.add_edge(newtag, n)
        G.remove_nodes_from(c)
    logging.debug("Contract {0} path nodes into {1} nodes.".\
                    format(len(path_nodes), len(cc)))

