def _parse_subnet(self, subnet_dict):
        if not subnet_dict:
            return
        alloc_pool = subnet_dict.get('allocation_pools')
        cidr = subnet_dict.get('cidr')
        subnet = cidr.split('/')[0]
        start = alloc_pool[0].get('start')
        end = alloc_pool[0].get('end')
        gateway = subnet_dict.get('gateway_ip')
        sec_gateway = subnet_dict.get('secondary_gw')
        return {'subnet': subnet, 'start': start, 'end': end,
                'gateway': gateway, 'sec_gateway': sec_gateway}

def validate_sns_topic_subscription(self, region):
        sns = self.session.client('sns', region_name=region)
        arn = 'arn:aws:sns:{}:{}:{}'.format(region, self.account.account_number, self.topic_name)
        try:
            data = sns.list_subscriptions_by_topic(TopicArn=arn)
        except ClientError as ex:
            self.log.error('Failed to list subscriptions by topic in {} ({}): {}'.format(
                self.account.account_name,
                region,
                ex
            ))
            return False

        for sub in data['Subscriptions']:
            if sub['Endpoint'] == self.sqs_queue:
                if sub['SubscriptionArn'] == 'PendingConfirmation':
                    self.log.warning('Subscription pending confirmation for {} in {}'.format(
                        self.account.account_name,
                        region
                    ))
                    return False
                return True

        return False

def getClassDirectSubs(self, aURI):
