        qres = self.rdflib_graph.query("""SELECT DISTINCT ?x
                 WHERE {
                     { ?x rdfs:subClassOf <%s> }
                     FILTER (!isBlank(?x))
                 }
                 """ % (aURI))
        return list(qres)

def almost_equal(self, v2, places=7):

        try:
            return (
                len(self) == len(v2) and
                _float_almost_equal(self.x, v2.x, places) and
                _float_almost_equal(self.y, v2.y, places) and
                _float_almost_equal(self.z, v2.z, places))
        except:
            return False

def revoke_leadership(self, broker_ids):
        for b_id in broker_ids:
            try:
                broker = self.cluster_topology.brokers[b_id]
            except KeyError:
                self.log.error("Invalid broker id %s.", b_id)
                raise InvalidBrokerIdError(
                    "Broker id {} does not exist in cluster".format(b_id),
                )
            broker.mark_revoked_leadership()

        assert(len(self.cluster_topology.brokers) - len(broker_ids) > 0), "Not " \
            "all brokers can be revoked for leadership"
        opt_leader_cnt = len(self.cluster_topology.partitions) // (
            len(self.cluster_topology.brokers) - len(broker_ids)
        )
        # Balanced brokers transfer leadership to their under-balanced followers
        self.rebalancing_non_followers(opt_leader_cnt)

        # If the broker-ids to be revoked from leadership are still leaders for any
        # partitions, try to forcefully move their leadership to followers if possible
        pending_brokers = [
            b for b in six.itervalues(self.cluster_topology.brokers)
            if b.revoked_leadership and b.count_preferred_replica() > 0
        ]
        for b in pending_brokers:
            self._force_revoke_leadership(b)

def _FormatPropertyName(self, property_name):
    # TODO: Add Unicode support.
    fix_key = re.sub(r'(.)([A-Z][a-z]+)', r'\1_\2', property_name)
    return re.sub(r'([a-z0-9])([A-Z])', r'\1_\2', fix_key).lower()

def find_target_container(portal_type, record):
    portal_type = portal_type or record.get("portal_type")
    container = get_container_for(portal_type)
    if container:
        return container

    parent_uid = record.pop("parent_uid", None)
    parent_path = record.pop("parent_path", None)

    target = None

    # Try to find the target object
    if parent_uid:
        target = get_object_by_uid(parent_uid)
    elif parent_path:
        target = get_object_by_path(parent_path)
    else:
        fail(404, "No target UID/PATH information found")

    if not target:
        fail(404, "No target container found")

    return target

def _run_timeout_threads(self, handler):
        # pylint: disable-msg=W0212
        for dummy, method in inspect.getmembers(handler, callable):
            if not hasattr(method, "_pyxmpp_timeout"):
                continue
            thread = TimeoutThread(method, daemon = self.daemon,
                                                    exc_queue = self.exc_queue)
            self.timeout_threads.append(thread)
            thread.start()

def _py2java(gateway, obj):
    if isinstance(obj, RDD):
        obj = _to_java_object_rdd(obj)
    elif isinstance(obj, DataFrame):
        obj = obj._jdf
    elif isinstance(obj, SparkContext):
        obj = obj._jsc
    elif isinstance(obj, (list, tuple)):
        obj = ListConverter().convert([_py2java(gateway, x) for x in obj],
                                      gateway._gateway_client)
    elif isinstance(obj, dict):
        result = {}
        for (key, value) in obj.items():
            result[key] = _py2java(gateway, value)
        obj = MapConverter().convert(result, gateway._gateway_client)
    elif isinstance(obj, JavaValue):
        obj = obj.value
    elif isinstance(obj, JavaObject):
        pass
    elif isinstance(obj, (int, long, float, bool, bytes, unicode)):
        pass
    else:
        data = bytearray(PickleSerializer().dumps(obj))
        obj = gateway.jvm.org.apache.spark.bigdl.api.python.BigDLSerDe.loads(data)
    return obj

