def remove_empty_dir(path):
    try:
        if not os.path.isdir(path):
            return

        files = os.listdir(path)

        # if folder empty, delete it
        if len(files) == 0:
            os.rmdir(path)

        # remove empty subdirectory
        elif len(files) > 0:
            for f in files:
                abspath = os.path.join(path, f)
                if os.path.isdir(abspath):
                    remove_empty_dir(abspath)
    except OSError as e:
        if e.errno == errno.ENOTEMPTY:
            pass

def cluster(self, n, embed_dim=None, algo=mds.CLASSICAL, method=methods.KMEANS):
        if n == 1:
            return Partition([1] * len(self.get_dm(False)))

        if embed_dim is None:
            embed_dim = n

        if algo == mds.CLASSICAL:
            self._coords = self.dm.embedding(embed_dim, 'cmds')
        elif algo == mds.METRIC:
            self._coords = self.dm.embedding(embed_dim, 'mmds')
        else:
            raise OptionError(algo, list(mds.reverse.values()))

        if method == methods.KMEANS:
            p = self.kmeans(n, self._coords.values)
        elif method == methods.GMM:
            p = self.gmm(n, self._coords.values)
        elif method == methods.WARD:
            linkmat = fastcluster.linkage(self._coords.values, 'ward')
            p = _hclust(linkmat, n)
        else:
            raise OptionError(method, list(methods.reverse.values()))
        #if self._verbosity > 0:
        #    print('Using clustering method: {}'.format(methods.reverse[method]))
        return p

def add_missing_children(required_children, element_children):
    element_tags = [element.tag for element in element_children]
    # Loop through the elements that should be in the form.
    for contained_element in required_children:
        # If the element doesn't exist in the form,
        # add the element to the children.
        if contained_element not in element_tags:
            try:
                added_child = PYUNTL_DISPATCH[contained_element](content='')
            except:
                added_child = PYUNTL_DISPATCH[contained_element]()
            element_children.append(added_child)
    return element_children

