def to_representation(self, instance):
        if self.id_only():
            return instance.pk

        pk = getattr(instance, 'pk', None)
        if not settings.ENABLE_SERIALIZER_OBJECT_CACHE or pk is None:
            return self._to_representation(instance)
        else:
            if pk not in self.obj_cache:
                self.obj_cache[pk] = self._to_representation(instance)
            return self.obj_cache[pk]

def _item_type(item):
    tag = item['tag']
    style = item.get('style', None)
    if tag == 'p':
        if style is None or 'paragraph' in style:
            return 'paragraph'
        else:
            return style
    elif tag == 'span':
        if style in (None, 'normal-text'):
            return 'text'
        elif style == 'url':
            return 'link'
        else:
            return style
    elif tag == 'h':
        assert style is not None
        return style
    elif tag in ('list', 'list-item', 'line-break'):
        if style == '_numbered_list':
            return 'numbered-list'
        else:
            return tag
    elif tag == 's':
        return 'spaces'
    raise Exception("The tag '{0}' with style '{1}' hasn't "
                    "been implemented.".format(tag, style))

def GetCellStyle (self, column, row = None):
                if row == None:
                        (row, column) = ParseCellSpec(column)
                style = { }
                # get style for cell
                if row in self:
                        merge(style, self[row].GetCellStyle(column))
                # merge with row style
                if row in self.rowStyles:
                        merge(style, self.rowStyles[row])
                # merge with column style
                if isinstance(column, str):
                        column = ColumnToIndex(column)
                if column in self.columnStyles:
                        merge(style, self.columnStyles[column])
                # merge with default style
                merge(style, self.defaultStyle)
                return style

