def _GetAPFSVolumeIdentifiers(self, scan_node):
    if not scan_node or not scan_node.path_spec:
      raise errors.ScannerError('Invalid scan node.')

    volume_system = apfs_volume_system.APFSVolumeSystem()
    volume_system.Open(scan_node.path_spec)

    volume_identifiers = self._source_scanner.GetVolumeIdentifiers(
        volume_system)
    if not volume_identifiers:
      return []

    if len(volume_identifiers) > 1:
      if not self._mediator:
        raise errors.ScannerError(
            'Unable to proceed. APFS volumes found but no mediator to '
            'determine how they should be used.')

      try:
        volume_identifiers = self._mediator.GetAPFSVolumeIdentifiers(
            volume_system, volume_identifiers)
      except KeyboardInterrupt:
        raise errors.UserAbort('File system scan aborted.')

    return self._NormalizedVolumeIdentifiers(
        volume_system, volume_identifiers, prefix='apfs')

def defaultSystem():
    rsystem = platform.system()

    # Try to lookup the string in the canon tables
    if rsystem in os_canon:
        rsystem = os_canon[rsystem][0]

    return rsystem

def stop_broadcast(self, broadcast_id):
        endpoint = self.endpoints.broadcast_url(broadcast_id, stop=True)
        response = requests.post(
            endpoint,
            headers=self.json_headers(),
            proxies=self.proxies,
            timeout=self.timeout
        )

        if response.status_code == 200:
            return Broadcast(response.json())
        elif response.status_code == 400:
            raise BroadcastError(
                'Invalid request. This response may indicate that data in your request '
                'data is invalid JSON.')
        elif response.status_code == 403:
            raise AuthError('Authentication error.')
        elif response.status_code == 409:
            raise BroadcastError(
                'The broadcast (with the specified ID) was not found or it has already '
                'stopped.')
        else:
            raise RequestError('OpenTok server error.', response.status_code)

