def sha256sum(filename):
    sha256 = hashlib.sha256()
    mem_view = memoryview(bytearray(128*1024))
    with open(filename, 'rb', buffering=0) as stream:
        for i in iter(lambda: stream.readinto(mem_view), 0):
            sha256.update(mem_view[:i])
    return sha256.hexdigest()

def select_read(self, timeout=None):

        # If we have buffered data, we consider a read possible
        if len(self._decrypted_bytes) > 0:
            return True

        read_ready, _, _ = select.select([self._socket], [], [], timeout)
        return len(read_ready) > 0

def load_json(filename, to='auto'):
