        self._add_widget(dict(config=config, meta=meta, name=WidgetNames.HTMLWIDGET))

def rolling_volatility(returns, rolling_vol_window):

    return returns.rolling(rolling_vol_window).std() \
        * np.sqrt(APPROX_BDAYS_PER_YEAR)

def delete_snapshots(name, *names, **kwargs):
    deleted = dict()
    conn = __get_conn(**kwargs)
    domain = _get_domain(conn, name)
    for snap in domain.listAllSnapshots():
        if snap.getName() in names or not names:
            deleted[snap.getName()] = _parse_snapshot_description(snap)
            snap.delete()
    conn.close()

    available = {name: [_parse_snapshot_description(snap) for snap in domain.listAllSnapshots()] or 'N/A'}

    return {'available': available, 'deleted': deleted}

def separable_convolution(input, weights, output=None, mode="reflect", cval=0.0, origin=0):
    input = numpy.asarray(input)
    output = _ni_support._get_output(output, input)
    axes = list(range(input.ndim))
    if len(axes) > 0:
        convolve1d(input, weights, axes[0], output, mode, cval, origin)
        for ii in range(1, len(axes)):
            convolve1d(output, weights, axes[ii], output, mode, cval, origin)
    else:
        output[...] = input[...]
    return output

def except_keyword(source, start, keyword):
    start = pass_white(source, start)
    kl = len(keyword)  #keyword len
    if kl + start > len(source):
        return None
    if source[start:start + kl] != keyword:
        return None
    if kl + start < len(source) and source[start + kl] in IDENTIFIER_PART:
        return None
    return start + kl

