            implementations = {}
            for function in cls.functions():
                implementations[function] = cls._build_late_dispatcher(
                    func_name=function.__name__)

            cls.implement(for_type=type_, implementations=implementations)

def unregister(self, plugin=None, plugin_file=None):
        if plugin is None and plugin_file is None:
            for name, plugin in self.plugins.items():
                plugin.deactivate()
                del self.plugins[name]

            return

        if plugin is not None:
            if plugin.name in self.plugins:
                plugin.deactivate()
                del self.plugins[plugin.name]

        if plugin_file is not None:
            plugs_in_file = PluginManager.get_plugins_in_module(plugin_file)
            if plugs_in_file is None:
                return

            for classPlugin in plugs_in_file:
                if not self.has_plugin(classPlugin.name, classPlugin):
                    continue

                self.get_plugin(classPlugin.name).deactivate()
                del self.plugins[classPlugin.name]

def load_file(filename, out=sys.stdout):
    fp = open(filename, 'rb')
    try:
      source = fp.read()
      try:
          if PYTHON_VERSION < 2.6:
              co = compile(source, filename, 'exec')
          else:
              co = compile(source, filename, 'exec', dont_inherit=True)
      except SyntaxError:
          out.write('>>Syntax error in %s\n' % filename)
          raise
    finally:
      fp.close()
    return co

