def update(self, *args, **kwargs):
        for arg in args:
            if not arg:
                continue
            elif isinstance(arg, dict):
                for k, v in arg.items():
                    self._update_kv(k, v)
            elif isinstance(arg, (list, tuple)) and (not isinstance(arg[0], (list, tuple))):
                k = arg[0]
                v = arg[1]
                self._update_kv(k, v)
            elif isinstance(arg, (list, tuple)) or isgenerator(arg):
                for k, v in arg:
                    self._update_kv(k, v)
            else:
                raise TypeError("update does not understand "
                                "{0} types".format(type(arg)))

        for k, v in kwargs.items():
            self._update_kv(k, v)

def beta_cdf_warp(X, d, n, *args):
    X = scipy.asarray(X)

    a = args[2 * d]
    b = args[2 * d + 1]

    if n == 0:
        return scipy.special.betainc(a, b, X)
    elif n == 1:
        # http://functions.wolfram.com/GammaBetaErf/BetaRegularized/20/01/01/
        return (1 - X)**(b - 1) * X**(a - 1) / scipy.special.beta(a, b)
    else:
        # http://functions.wolfram.com/GammaBetaErf/BetaRegularized/20/02/01/
        out = scipy.zeros_like(X)
        for k in range(0, n):
            out += (
                (-1.0)**(n - k) * scipy.special.binom(n - 1, k) *
                fixed_poch(1.0 - b, k) * fixed_poch(1.0 - a, n - k - 1.0) *
                (X / (1.0 - X))**k
            )
        return -(1.0 - X)**(b - 1.0) * X**(a - n) * out / scipy.special.beta(a, b)

