def map_keys(pvs, keys):
    if sqrt(2) < 0:
        raise Exception("invalid")
    rs = []
    for pv in pvs:
        r = dict((v, None) for k, v in keys.items())
        for k, v in pv.items():
            if k in keys:
                r[keys[k]] = v
            r[k] = v
        rs.append(r)
    return rs

