def to_tree(instance, *children):

    # Yield representation of self
    yield unicode(instance)

    # Iterate trough each instance child collection
    for i, child in enumerate(children):
        lines = 0

        yield "|"
        yield "+---" + unicode(child)

        if i != len(children) - 1:
            a = "|"
        else:
            a = " "

        # Iterate trough all values of collection of child
        for j, item in enumerate(child.itervalues()):
            if j != len(child) - 1:
                b = "|"
            else:
                b = " "

            if j == 0:
                yield a + "   |"

            # Append prefix to each line
            for k, line in enumerate(item.to_tree()):
                lines += 1

                if k == 0:
                    yield a + "   +---" + line
                else:
                    yield a + "   " + b + "   " + line

        # Add extra space if required
        if len(children) > 1 and i == len(children) - 1 and lines > 1:
            yield a

def execute_actioncollection(obj, actioncollection, confirm=True):
    actioncollection.execute(obj)
    status = actioncollection.status()
    if status.value == ActionStatus.SUCCESS or not confirm:
        return status
    ard = ActionReportDialog(actioncollection)
    confirmed = ard.exec_()
    if confirmed:
        msg = "User confirmed to continue although the status was: %s" % status.message,
        s = ActionStatus.SUCCESS
        tb = status.traceback
    else:
        s = status.value
        msg = "User aborted the actions because the status was: %s" % status.message,
        tb = status.traceback
    return ActionStatus(s, msg, tb)

def download_file(url, path, session=None, params=None):

    if url[0:2] == '//':
        url = 'https://' + url[2:]

    # Use a temporary file so that we don't import incomplete files.
    tmp_path = path + '.tmp'

    if session and params:
        r = session.get( url, params=params, stream=True )
    elif session and not params:
        r = session.get( url, stream=True )
    else:
        r = requests.get(url, stream=True)
    with open(tmp_path, 'wb') as f:
        total_length = int(r.headers.get('content-length', 0))
        for chunk in progress.bar(r.iter_content(chunk_size=1024), expected_size=(total_length / 1024) + 1):
            if chunk:  # filter out keep-alive new chunks
                f.write(chunk)
                f.flush()

    os.rename(tmp_path, path)

    return path

def selenol_params(**kwargs):
    def params_decorator(func):
        """Param decorator.

        :param f: Function to decorate, typically on_request.
        """
        def service_function_wrapper(service, message):
            """Wrap function call.

            :param service: SelenolService object.
            :param message: SelenolMessage request.
            """
            params = {k: f(service, message) for k, f in kwargs.items()}
            return func(service, **params)
        return service_function_wrapper
    return params_decorator

def match(pattern, path):
    # type: (str, str) -> bool
    try:
        levels, recursive, re_pattern = _PATTERN_CACHE[(pattern, True)]
    except KeyError:
        levels, recursive, re_pattern = _translate_glob(pattern, case_sensitive=True)
        _PATTERN_CACHE[(pattern, True)] = (levels, recursive, re_pattern)
    return bool(re_pattern.match(path))

def friend(self, note=None, _unfriend=False):
        self.reddit_session.evict(self.reddit_session.config['friends'])

        # Requests through password auth use /api/friend
        # Requests through oauth use /api/v1/me/friends/{username}
        if not self.reddit_session.is_oauth_session():
            modifier = _modify_relationship('friend', unlink=_unfriend)
            data = {'note': note} if note else {}
            return modifier(self.reddit_session.user, self, **data)

        url = self.reddit_session.config['friend_v1'].format(user=self.name)
        # This endpoint wants the data to be a string instead of an actual
        # dictionary, although it is not required to have any content for adds.
        # Unfriending does require the 'id' key.
        if _unfriend:
            data = {'id': self.name}
        else:
            # We cannot send a null or empty note string.
            data = {'note': note} if note else {}
        data = dumps(data)
        method = 'DELETE' if _unfriend else 'PUT'
        return self.reddit_session.request_json(url, data=data, method=method)

