    # Return only the services that have an initscript present
    return [x for x in _services if _service_is_sysv(x)]

def dedupe_list_of_dicts(ld):
    def _freeze(o):
        """Recursively freezes a dict into an hashable object.

        Adapted from http://stackoverflow.com/a/21614155/374865.
        """
        if isinstance(o, dict):
            return frozenset((k, _freeze(v)) for k, v in six.iteritems(o))
        elif isinstance(o, (list, tuple)):
            return tuple(_freeze(v) for v in o)
        else:
            return o

    result = []
    seen = set()

    for d in ld:
        f = _freeze(d)
        if f not in seen:
            result.append(d)
            seen.add(f)

    return result

def axpy(x, y, a=1.0):
    from scipy.linalg import get_blas_funcs

    fn = get_blas_funcs(['axpy'], [x, y])[0]
