def markup_join(seq):
    buf = []
    iterator = imap(soft_unicode, seq)
    for arg in iterator:
        buf.append(arg)
        if hasattr(arg, '__html__'):
            return Markup(u'').join(chain(buf, iterator))
    return concat(buf)

def _generate_struct_cstor_default(self, struct):
        if not self._struct_has_defaults(struct):
            return

        fields_no_default = [
            f for f in struct.all_fields
            if not f.has_default and not is_nullable_type(f.data_type)
        ]

        with self.block_func(
                func=self._cstor_name_from_fields(fields_no_default),
                args=fmt_func_args_from_fields(fields_no_default),
                return_type='instancetype'):
            args = ([(fmt_var(f.name), fmt_var(f.name) if not f.has_default and
                      not is_nullable_type(f.data_type) else 'nil')
                     for f in struct.all_fields])
            cstor_args = fmt_func_args(args)
            self.emit('return [self {}:{}];'.format(
                self._cstor_name_from_fields(struct.all_fields), cstor_args))
        self.emit()

def _get_pretty_dimension_order(self, ds, name):
        dim_names = []
        for dim in ds.variables[name].dimensions:
            dim_name = dim
            if ds.dimensions[dim].isunlimited():
                dim_name += ' (Unlimited)'
            dim_names.append(dim_name)
        return ', '.join(dim_names)

def get_node_text(self, node, depth, sep, params=False,):
        indent = sep * depth
        s = ''
        tag = node.tag
        if tag == 'Indicator':
            node_text = self.get_i_text(node)
        elif tag == 'IndicatorItem':
            node_text = self.get_ii_text(node)
        else:
            raise IOCParseError('Invalid node encountered: {}'.format(tag))
        s += '{}{}\n'.format(indent, node_text)
        if params:
            param_text = self.get_param_text(node.attrib.get('id'))
            for pt in param_text:
                s += '{}{}\n'.format(indent+sep, pt)
        if node.tag == 'Indicator':
            for child in node.getchildren():
                s += self.get_node_text(node=child, depth=depth+1, sep=sep, params=params)
        return s

def keyword_scan(self, query_id=None, query_fc=None, feature_names=None):
        it = self._keyword_scan(query_id, query_fc,
                                feature_names=feature_names)
        for hit in it:
            fc = self.fc_from_dict(hit['_source']['fc'])
            yield did(hit['_id']), fc

def parametrized_unbottleneck(x, hidden_size, hparams):
  if hparams.bottleneck_kind == "tanh_discrete":
    return tanh_discrete_unbottleneck(x, hidden_size)
  if hparams.bottleneck_kind == "isemhash":
    return isemhash_unbottleneck(x, hidden_size,
                                 hparams.isemhash_filter_size_multiplier)
  if hparams.bottleneck_kind in ["vq", "em", "gumbel_softmax"]:
    return vq_discrete_unbottleneck(x, hidden_size)
  raise ValueError(
      "Unsupported hparams.bottleneck_kind %s" % hparams.bottleneck_kind)

