def set_intermediates(self, intermediates, betas=None, transition_states=None):
        self.intermediates = intermediates
        self.betas = betas
        self.transition_states = transition_states

        if self.corrections is None:
            self.net_corrections = [0.0 for _ in intermediates]

        if not self.betas:
            self.betas = [0.0 for _ in intermediates]

        if not self.transition_states:
            self.transition_states = [False for _ in intermediates]

        # check if all lists have same length:
        props = [len(self.intermediates), len(self.net_corrections), len(self.transition_states),
                 len(self.betas)]
        if not len(set(props)) <= 1:
            raise ValueError('intermediate, net_corrections, transition_states and , '
                             'betas all have to have the same length')

        self.get_corrections()
        return(True)

def score_group(group_name=None):
    warnings.warn('Score_group is deprecated as of Compliance Checker v3.2.')
    def _inner(func):
        def _dec(s, ds):
            ret_val = func(s, ds)
            """
            if group_name != None and not isinstance(ret_val[0], tuple):
                return tuple([(group_name, ret_val[0])] + list(ret_val[1:]))
            """
            # multiple returns
            if not isinstance(ret_val, list):
                ret_val = [ret_val]

            def dogroup(r):
                cur_grouping = r.name

                if isinstance(cur_grouping, tuple):
                    cur_grouping = list(cur_grouping)
                elif not isinstance(cur_grouping, list):
                    cur_grouping = [cur_grouping]

                cur_grouping.insert(0, group_name)

                return Result(r.weight, r.value, tuple(cur_grouping), r.msgs)

            ret_val = [fix_return_value(x, func.__name__, func, s) for x in
                       ret_val]
            ret_val = list(map(dogroup, ret_val))

            return ret_val
        return wraps(func)(_dec)
    return _inner

def within_limits(self, value):

        if isinstance(value, int) or isinstance(value, float):
            value = value * self.default_unit

        return (self.limits[0] is None or value >= self.limits[0]) and (self.limits[1] is None or value <= self.limits[1])

def emit(event, *args, **kwargs):
    if 'namespace' in kwargs:
        namespace = kwargs['namespace']
    else:
        namespace = flask.request.namespace
    callback = kwargs.get('callback')
    broadcast = kwargs.get('broadcast')
    room = kwargs.get('room')
    if room is None and not broadcast:
        room = flask.request.sid
    include_self = kwargs.get('include_self', True)
    ignore_queue = kwargs.get('ignore_queue', False)

    socketio = flask.current_app.extensions['socketio']
    return socketio.emit(event, *args, namespace=namespace, room=room,
                         include_self=include_self, callback=callback,
                         ignore_queue=ignore_queue)

