def determine_extra_packages(self, packages):

        args = [
            "pip",
            "freeze",
        ]
        installed = subprocess.check_output(args, universal_newlines=True)

        installed_list = set()
        lines = installed.strip().split('\n')
        for (package, version) in self._parse_requirements(lines):
            installed_list.add(package)

        package_list = set()
        for (package, version) in self._parse_requirements(packages.readlines()):
            package_list.add(package)

        removal_list = installed_list - package_list
        return tuple(removal_list)

def __firewall_cmd(cmd):
    firewall_cmd = '{0} {1}'.format(salt.utils.path.which('firewall-cmd'), cmd)
    out = __salt__['cmd.run_all'](firewall_cmd)

    if out['retcode'] != 0:
        if not out['stderr']:
            msg = out['stdout']
        else:
            msg = out['stderr']
        raise CommandExecutionError(
            'firewall-cmd failed: {0}'.format(msg)
        )
    return out['stdout']

def remove_empty_from_dict(dictionary):
    if isinstance(dictionary, dict):
        return dict(
            (k,
             remove_empty_from_dict(v)) for k, v in iteritems(
                 dictionary) if v and remove_empty_from_dict(v))
    elif isinstance(dictionary, list):
        return [remove_empty_from_dict(v) for v in dictionary if v and remove_empty_from_dict(v)]
    return dictionary

def check_program(name):
    with open(os.devnull, "w") as null:
        try:
            subprocess.check_call(("which", name), stdout=null, stderr=null)
        except subprocess.CalledProcessError as e:
            return False
    return True

def python_executable(check=True, short=False):
    if not check:
        python_exe = 'python'
    else:
        from os.path import isdir
        python_exe_long = unixpath(sys.executable)
        python_exe = python_exe_long
        if short:
            python_exe_short = basename(python_exe_long)
            found = search_env_paths(python_exe_short, key_list=['PATH'],
                                     verbose=False)
            found = [f for f in found if not isdir(f)]
            if len(found) > 0:
                if found[0] == python_exe_long:
                    # Safe to use the short name in this env
                    python_exe = python_exe_short
    return python_exe

def to_ngrams(self, terms):
        if len(terms) <= self.n:
            return terms
        if self.n == 1:
            n_grams = [[term] for term in terms]
        else:
            n_grams = []
            for i in range(0,len(terms)-self.n+1):
                n_grams.append(terms[i:i+self.n])
        return n_grams

def find_by_ext(dirname, ext):
