def parse_name(name):
  bucket = None
  item = None
  m = re.match(_STORAGE_NAME, name)
  if m:
    # We want to return the last two groups as first group is the optional 'gs://'
    bucket = m.group(1)
    item = m.group(2)
    if item is not None:
      item = item[1:]  # Strip '/'
  else:
    m = re.match('(' + _OBJECT_NAME + ')', name)
    if m:
      item = m.group(1)
  return bucket, item

