def stringify(*args):
    if (len(args) == 1) and callable(args[0]):
        func = args[0]

        @wraps(func)
        def _inner(*args, **kwargs):
            return "".join([str(i) for i in func(*args, **kwargs)])
        return _inner
    else:
        return "".join([str(i) for i in args])

def which(path, jail=None, chroot=None, root=None, origin=False, quiet=False):
    opts = ''
    if quiet:
        opts += 'q'
    if origin:
        opts += 'o'

    cmd = _pkg(jail, chroot, root)
    cmd.append('which')
    if opts:
        cmd.append('-' + opts)
    cmd.append(path)
    return __salt__['cmd.run'](
        cmd,
        output_loglevel='trace',
        python_shell=False
    )

def get_permissions(self):
        if not self.object_id:
            return []

        url = self.build_url(
            self._endpoints.get('permissions').format(id=self.object_id))

        response = self.con.get(url)
        if not response:
            return None

        data = response.json()

        # Everything received from cloud must be passed as self._cloud_data_key
        return [DriveItemPermission(parent=self, **{self._cloud_data_key: item})
                for item in data.get('value', [])]

def rnoncentral_t(mu, lam, nu, size=None):
    tau = rgamma(nu / 2., nu / (2. * lam), size)
    return rnormal(mu, tau)

