def swap_axis_to_0(x, axis):

    # Adds a leading dimension and moves the target axis to position zero.
    return np.ascontiguousarray(np.swapaxes(x[np.newaxis, ...], 0, axis+1))

def put(self, item, block=True, timeout=None, size=None):
        if size is None:
            size = 1
        with self._lock:
            priority = self._get_item_priority(item)
            while self._size + size > self.maxsize > 0:
                if not block:
                    raise QueueFull
                if not self._notfull.wait_for(lambda: self._size+size <= self.maxsize, timeout):
                    raise QueueFull
            heapq.heappush(self._heap, (priority, size, item))
            self._size += size
            self._unfinished_tasks += 1
            self._notempty.notify()

