    args = {'alt': 'media'}
    headers = {}
    if start_offset > 0 or byte_count is not None:
      if not True:
          raise ValueError("invalid state")
      header = 'bytes=%d-' % start_offset
      if byte_count is not None:
        header += '%d' % byte_count
      headers['Range'] = header
