def group_toggle(self, addr, use_cache=True):
        data = self.group_read(addr, use_cache)
        if len(data) != 1:
            problem = "Can't toggle a {}-octet group address {}".format(
                len(data), addr)
            logging.error(problem)
            raise KNXException(problem)

        if data[0] == 0:
            self.group_write(addr, [1])
        elif data[0] == 1:
            self.group_write(addr, [0])
        else:
            problem = "Can't toggle group address {} as value is {}".format(
                addr, data[0])
            logging.error(problem)
            raise KNXException(problem)

def load(self):
        if self._leaser is None:
            return 0

        return max(
            [
                self._leaser.message_count / self._flow_control.max_messages,
                self._leaser.bytes / self._flow_control.max_bytes,
            ]
        )

def writeable(value,
              allow_empty = False,
              **kwargs):
    if not value and not allow_empty:
        raise errors.EmptyValueError('value (%s) was empty' % value)
    elif not value:
        return None

    value = path(value, force_run = True)

    if sys.platform in ['win32', 'cygwin']:
        raise NotImplementedError('not supported on Windows')

    is_valid = os.access(value, mode = os.W_OK)

    if not is_valid:
        raise errors.NotWriteableError('writing not allowed for file at %s' % value)

    return value

