        if bool(modified_data):
            task_request_data = {}
            inputs = modified_data.pop('inputs', None)
            execution_settings = modified_data.pop('execution_settings', None)
            task_request_data.update(modified_data)

            if inputs:
                task_request_data['inputs'] = self._serialize_inputs(inputs)

            if execution_settings:
                task_request_data['execution_settings'] = (
                    self._serialize_execution_settings(execution_settings)
                )

            extra = {
                'resource': self.__class__.__name__,
                'query': {'id': self.id, 'data': task_request_data}
            }
            logger.info('Saving task', extra=extra)
            data = self._api.patch(url=self._URL['get'].format(id=self.id),
                                   data=task_request_data).json()
            task = Task(api=self._api, **data)
            return task

def _run_generic_command(self, repo, cmd):

        result = None
        with cd(repo.rootdir):
            # Dont use sh. It is not collecting the stdout of all
            # child processes.
            output = self._run(cmd)
            try:
                result = {
                    'cmd': cmd,
                    'status': 'success',
                    'message': output,
                }
            except Exception as e:
                result = {
                    'cmd': cmd,
                    'status': 'error',
                    'message': str(e)
                }

        return result

def contour(h, axes=None, zoom=None, label_contour=False, **kwargs):
    if axes is None:
        axes = plt.gca()
    x = np.array(list(h.x()))
    y = np.array(list(h.y()))
    z = np.array(h.z()).T
    if zoom is not None:
        from scipy import ndimage
        if hasattr(zoom, '__iter__'):
            zoom = list(zoom)
            x = ndimage.zoom(x, zoom[0])
            y = ndimage.zoom(y, zoom[1])
        else:
            x = ndimage.zoom(x, zoom)
            y = ndimage.zoom(y, zoom)
        z = ndimage.zoom(z, zoom)
    return_values = axes.contour(x, y, z, **kwargs)
    if label_contour:
        plt.clabel(return_values)
    return return_values

def total_regular_pixels_from_mask(mask):

    total_regular_pixels = 0

    for y in range(mask.shape[0]):
        for x in range(mask.shape[1]):
            if not mask[y, x]:
                total_regular_pixels += 1

    return total_regular_pixels

def sys_mmap(self, address, size, prot, flags, fd, offset):

        if address == 0:
            address = None

        cpu = self.current
        if flags & 0x10:
            cpu.memory.munmap(address, size)

        perms = perms_from_protflags(prot)

        if flags & 0x20:
            result = cpu.memory.mmap(address, size, perms)
        elif fd == 0:
            assert offset == 0
            result = cpu.memory.mmap(address, size, perms)
            data = self.files[fd].read(size)
            cpu.write_bytes(result, data)
        else:
            # FIXME Check if file should be symbolic input and do as with fd0
            result = cpu.memory.mmapFile(address, size, perms, self.files[fd].name, offset)

        tmp = f'0x{result:016x}'
        if address is None or result != address:
            address = address or 0
            tmp += f' [requested: 0x{address:016x}]'

        if flags & 0x10 != 0 and result != address:
            cpu.memory.munmap(result, size)
            result = -1

        return result

