def dictionaries_walker(dictionary, path=()):

    for key in dictionary:
        if not isinstance(dictionary[key], dict):
            yield path, key, dictionary[key]
        else:
            for value in dictionaries_walker(dictionary[key], path + (key,)):
                yield value

