def validate_srec_checksum(srec):
    checksum = srec[len(srec)-2:]

    # Strip the original checksum and compare with the computed one
    if compute_srec_checksum(srec[:len(srec) - 2]) == int(checksum, 16):
        return True
    else:
        return False

def savez_two_column(matrix, row_offset, file_name, append=False):
  logging.info("Saving obj to file in two column .npz format %s.", file_name)
  tc = []
  for u, items in enumerate(matrix):
    user = row_offset + u
    for item in items:
      tc.append([user, item])

  np.savez_compressed(file_name, np.asarray(tc))
  logging.info("Done saving to file %s.", file_name)

def readline(self, raise_exception=False):
        buf = self.buffer
        if self.socket:
            recv = self.socket.recv
        else:
            recv = lambda bufsize: ''

        while True:
            index = buf.find('\r\n')
            if index >= 0:
                break
            data = recv(4096)
            if not data:
                # connection close, let's kill it and raise
                self.mark_dead('connection closed in readline()')
                if raise_exception:
                    raise _ConnectionDeadError()
                else:
                    return ''

            buf += data
        self.buffer = buf[index+2:]
        return buf[:index]

def locked_get(self):
        credentials = None
