def query(self, tablename, attributes=None, consistent=False, count=False,
              index=None, limit=None, desc=False, return_capacity=None,
              filter=None, filter_or=False, exclusive_start_key=None, **kwargs):
        keywords = {
            'TableName': tablename,
            'ReturnConsumedCapacity': self._default_capacity(return_capacity),
            'ConsistentRead': consistent,
            'ScanIndexForward': not desc,
            'KeyConditions': encode_query_kwargs(self.dynamizer, kwargs),
        }
        if attributes is not None:
            keywords['AttributesToGet'] = attributes
        if index is not None:
            keywords['IndexName'] = index
        if filter is not None:
            if len(filter) > 1:
                keywords['ConditionalOperator'] = 'OR' if filter_or else 'AND'
            keywords['QueryFilter'] = encode_query_kwargs(self.dynamizer,
                                                          filter)
        if exclusive_start_key is not None:
            keywords['ExclusiveStartKey'] = \
                self.dynamizer.maybe_encode_keys(exclusive_start_key)
        if not isinstance(limit, Limit):
            limit = Limit(limit)
        if count:
            keywords['Select'] = COUNT
            return self._count('query', limit, keywords)
        else:
            return ResultSet(self, limit, 'query', **keywords)

def document_func_view(serializer_class=None,
                       response_serializer_class=None,
                       filter_backends=None,
                       permission_classes=None,
                       authentication_classes=None,
                       doc_format_args=list(),
                       doc_format_kwargs=dict()):
    def decorator(func):
        if serializer_class:
            func.cls.serializer_class = func.view_class.serializer_class = serializer_class
        if response_serializer_class:
            func.cls.response_serializer_class = func.view_class.response_serializer_class = response_serializer_class
        if filter_backends:
            func.cls.filter_backends = func.view_class.filter_backends = filter_backends
        if permission_classes:
            func.cls.permission_classes = func.view_class.permission_classes = permission_classes
        if authentication_classes:
            func.cls.authentication_classes = func.view_class.authentication_classes = authentication_classes
        if doc_format_args or doc_format_kwargs:
            func.cls.__doc__ = func.view_class.__doc__ = getdoc(func).format(*doc_format_args, **doc_format_kwargs)
        return func

    return decorator

def find_element_by_selectors(webdriver, *selectors):
        # perform initial check to verify selectors are valid by statements.
        for selector in selectors:
            (by_method, value) = selector
            if not WebElementSelector.__is_valid_by_type(by_method):
                raise BadSelectorError(
                    u("Selectors should be of type selenium.webdriver.common.by.By"))
            if type(value) != str:
                raise BadSelectorError(
                    u("Selectors should be of type selenium.webdriver.common.by.By"))

        selectors_used = []
        for selector in selectors:
            (by_method, value) = selector
            selectors_used.append(
                u("{by}:{value}").format(by=by_method, value=value))
            try:
                return webdriver.find_element(by=by_method, value=value)
            except:
                pass

        raise ElementNotSelectableException(
            u("Unable to find elements using:") + u(",").join(selectors_used))

def append(self, event, force = False):
        if self.tree is None:
            if self.parent is None:
                raise IndexError('The queue is removed')
            else:
                return self.parent.parent.append(event, force)
        q = self.tree.matchfirst(event)
        return q.append(event, force)

def relative_symlink(source_path, link_path):
  if not os.path.isabs(source_path):
    raise ValueError("Path for source:{} must be absolute".format(source_path))
  if not os.path.isabs(link_path):
    raise ValueError("Path for link:{} must be absolute".format(link_path))
  if source_path == link_path:
    raise ValueError("Path for link is identical to source:{}".format(source_path))
  # The failure state below had a long life as an uncaught error. No behavior was changed here, it just adds a catch.
  # Raising an exception does differ from absolute_symlink, which takes the liberty of deleting existing directories.
  if os.path.isdir(link_path) and not os.path.islink(link_path):
    raise ValueError("Path for link would overwrite an existing directory: {}".format(link_path))
  try:
    if os.path.lexists(link_path):
      os.unlink(link_path)
    rel_path = os.path.relpath(source_path, os.path.dirname(link_path))
    safe_mkdir_for(link_path)
    os.symlink(rel_path, link_path)
  except OSError as e:
    # Another run may beat us to deletion or creation.
    if not (e.errno == errno.EEXIST or e.errno == errno.ENOENT):
      raise

