def _load_images_and_labels(self, images, labels=None):
        if not isinstance(images, (list, tuple)):
            raise ValueError('Expected an iterable (list or tuple) of strings or img-like objects. '
                             'Got a {}.'.format(type(images)))

        if not len(images) > 0:
            raise ValueError('Expected an iterable (list or tuple) of strings or img-like objects '
                             'of size higher than 0. Got {} items.'.format(len(images)))

        if labels is not None and len(labels) != len(images):
            raise ValueError('Expected the same length for image set ({}) and '
                             'labels list ({}).'.format(len(images), len(labels)))

        first_file = images[0]
        if first_file:
            first_img = NeuroImage(first_file)
        else:
            raise('Error reading image {}.'.format(repr_imgs(first_file)))

        for idx, image in enumerate(images):
            try:
                img = NeuroImage(image)
                self.check_compatibility(img, first_img)
            except:
                log.exception('Error reading image {}.'.format(repr_imgs(image)))
                raise
            else:
                self.items.append(img)

        self.set_labels(labels)

def to_triples(self, short_pred=True, properties=True):
        ts = []
        qs = set(self.nodeids(quantifier=True))
        for n in nodes(self):
            pred = n.pred.short_form() if short_pred else n.pred.string
            ts.append((n.nodeid, 'predicate', pred))
            if n.lnk is not None:
                ts.append((n.nodeid, 'lnk', '"{}"'.format(str(n.lnk))))
            if n.carg is not None:
                ts.append((n.nodeid, 'carg', '"{}"'.format(n.carg)))
            if properties and n.nodeid not in qs:
                for key, value in n.sortinfo.items():
                    ts.append((n.nodeid, key.lower(), value))

        for l in links(self):
            if safe_int(l.start) == LTOP_NODEID:
                ts.append((l.start, 'top', l.end))
            else:
                tmp = '{}-{}'.format(l.rargname.upper(), l.post)
                ts.append((l.start, tmp, l.end))
        return ts

