def _build_verb_statement_mapping():
    path_this = os.path.dirname(os.path.abspath(__file__))
    map_path = os.path.join(path_this, 'isi_verb_to_indra_statement_type.tsv')
    with open(map_path, 'r') as f:
        first_line = True
        verb_to_statement_type = {}
        for line in f:
            if not first_line:
                line = line[:-1]
                tokens = line.split('\t')

                if len(tokens) == 2 and len(tokens[1]) > 0:
                    verb = tokens[0]
                    s_type = tokens[1]
                    try:
                        statement_class = getattr(ist, s_type)
                        verb_to_statement_type[verb] = statement_class
                    except Exception:
                        pass
            else:
                first_line = False
    return verb_to_statement_type

def create_instances_from_matrices(x, y=None, name="data"):
    if y is not None:
        if len(x) != len(y):
            raise Exception("Dimensions of x and y differ: " + str(len(x)) + " != " + str(len(y)))
    # create header
    atts = []
    for i in range(len(x[0])):
        atts.append(Attribute.create_numeric("x" + str(i+1)))
    if y is not None:
        atts.append(Attribute.create_numeric("y"))
    result = Instances.create_instances(name, atts, len(x))
    # add data
    for i in range(len(x)):
        values = list(x[i])
        if y is not None:
            values.append(y[i])
        result.add_instance(Instance.create_instance(values))
    return result

def which(name):

    # we were given a filename, return it if it's executable
    if os.path.dirname(name) != '':
        if not os.path.isdir(name) and os.access(name, os.X_OK):
            return name
        else:
            return None

    # fetch PATH env var and split
    path_val = os.environ.get('PATH', None) or os.defpath

    # return the first match in the paths
    for path in path_val.split(os.pathsep):
        filename = os.path.join(path, name)

        if os.access(filename, os.X_OK):
            return filename

    return None

