def stringify_address(addr, encoding='utf-8'):
    if isinstance(addr, bytes_type):
        return addr
    try:
        addr = addr.encode('ascii')
    except UnicodeEncodeError:
        if '@' in addr:
            localpart, domain = addr.split('@', 1)
            addr = b'@'.join([
                localpart.encode(encoding),
                domain.encode('idna'),
            ])
        else:
            addr = addr.encode(encoding)
    return addr.decode('utf-8')

def maximal(iterable, comparison=operator.lt, _groupkey=operator.itemgetter(0)):
    iterable = set(iterable)
    if len(iterable) < 2:
        return iterable
    return (item for item, pairs
        in groupby(permutations(iterable, 2), key=_groupkey)
        if not any(starmap(comparison, pairs)))

def predict_is(self, h=5, fit_once=True):

        predictions = []

        for t in range(0,h):
            data1 = self.data_original_nondf[:-h+t]
            x = DAR(data=data1, ar=self.ar, integ=self.integ)
            if fit_once is False:
                x.fit(printer=False)
            if t == 0:
                if fit_once is True:
                    x.fit(printer=False)
                    saved_lvs = x.latent_variables
                predictions = x.predict(1)
            else:
                if fit_once is True:
                    x.latent_variables = saved_lvs
                predictions = pd.concat([predictions,x.predict(1)])

        predictions.rename(columns={0:self.y_name}, inplace=True)
        predictions.index = self.index[-h:]

        return predictions

def source_absent(name):
    ret = {'name': name,
           'changes': {},
           'result': None,
           'comment': ''}

    if name not in __salt__['imgadm.sources']():
        # source is absent
        ret['result'] = True
        ret['comment'] = 'image source {0} is absent'.format(name)
    else:
        # remove source
        if __opts__['test']:
            res = {}
            ret['result'] = True
        else:
            res = __salt__['imgadm.source_delete'](name)
            ret['result'] = (name not in res)

        if ret['result']:
            ret['comment'] = 'image source {0} deleted'.format(name)
            ret['changes'][name] = 'deleted'
        else:
            ret['comment'] = 'image source {0} not deleted'.format(name)
            if 'Error' in res:
                ret['comment'] = '{0}: {1}'.format(ret['comment'], res['Error'])

    return ret

def safe_listdir(path):
    try:
        return os.listdir(path)
    except (PermissionError, NotADirectoryError):
        pass
    except OSError as e:
        # Ignore the directory if does not exist, not a directory or
        # permission denied
        ignorable = (
            e.errno in (errno.ENOTDIR, errno.EACCES, errno.ENOENT)
            # Python 2 on Windows needs to be handled this way :(
            or getattr(e, "winerror", None) == 267
        )
        if not ignorable:
            raise
    return ()

def query_string(context, key, value):
