                break
            del self.tasks[next_task]

def close(self, timeout_ms):
    if self.closed_state == self.ClosedState.CLOSED:
      return

    self.closed_state = self.ClosedState.CLOSED
    try:
      if not self.adb_connection.close_stream_transport(
          self, timeouts.PolledTimeout.from_millis(timeout_ms)):
        _LOG.warning('Attempt to close mystery %s', self)
    except usb_exceptions.AdbTimeoutError:
      _LOG.warning('%s close() timed out, ignoring', self)

def check_image_size_incorrect(self):
        last_virtual_address = 0
        last_virtual_size = 0

        section_alignment = self.pefile_handle.OPTIONAL_HEADER.SectionAlignment
        total_image_size = self.pefile_handle.OPTIONAL_HEADER.SizeOfImage

        for section in self.pefile_handle.sections:
            if section.VirtualAddress > last_virtual_address:
                last_virtual_address = section.VirtualAddress
                last_virtual_size = section.Misc_VirtualSize

        # Just pad the size to be equal to the alignment and check for mismatch
        last_virtual_size += section_alignment - (last_virtual_size % section_alignment)
        if (last_virtual_address + last_virtual_size) != total_image_size:
            return {'description': 'Image size does not match reported size', 
                    'severity': 3, 'category': 'MALFORMED'}

        return None

def find(name):
    cmd = 'apt-cache search %s' % name
    args = shlex.split(cmd)
    try:
        output = subprocess.check_output(args)
    except CalledProcessError:
        return []
    lines = output.splitlines()
    packages = []
    for line in lines:
        package, _, desc = line.partition(' - ')
        packages.append((package, desc)) 
    return packages

def serialize(self, expires=None):
        if self.secret_key is None:
            raise RuntimeError('no secret key defined')
        if expires:
            self['_expires'] = _date_to_unix(expires)
        result = []
        mac = hmac(self.secret_key, None, self.hash_method)
        for key, value in sorted(self.items()):
            result.append(('%s=%s' % (
                url_quote_plus(key),
                self.quote(value).decode('ascii')
            )).encode('ascii'))
            mac.update(b'|' + result[-1])
        return b'?'.join([
            base64.b64encode(mac.digest()).strip(),
            b'&'.join(result)
        ])

