def apply(self, collection, ops, resource=None, **kwargs):
        mfield = self.mfield or resource.meta.model._meta.fields.get(self.field.attribute)
        if mfield:
            collection = collection.where(*[op(mfield, val) for op, val in ops])
        return collection

def _find_unchanged(old, new):
    edges = []
    old_edges = [set(edge) for edge in old.edges()]
    new_edges = [set(edge) for edge in new.edges()]
    for old_edge in old_edges:
        if old_edge in new_edges:
            edges.append(set(old_edge))
    return edges

def intersection (set1, set2):
    assert is_iterable(set1)
    assert is_iterable(set2)
    result = []
    for tmp in set1:
        if tmp in set2:
            result.append (tmp)
    return result

