def access_func(self, id_, lineno, scope=None, default_type=None):
        assert default_type is None or isinstance(default_type, symbols.TYPEREF)

        result = self.get_entry(id_, scope)
        if result is None:
            if default_type is None:
                if global_.DEFAULT_IMPLICIT_TYPE == TYPE.auto:
                    default_type = symbols.TYPEREF(self.basic_types[TYPE.auto], lineno, implicit=True)
                else:
                    default_type = symbols.TYPEREF(self.basic_types[global_.DEFAULT_TYPE], lineno, implicit=True)

            return self.declare_func(id_, lineno, default_type)

        if not self.check_class(id_, CLASS.function, lineno, scope):
            return None

        return result

def move_all_files_from_subfolders_to_top(folder_path, delete_subfolders=False, copy=False):
    for item in os.listdir(folder_path):
        sub_path = os.path.join(folder_path, item)

        if os.path.isdir(sub_path):

            for sub_item in os.listdir(sub_path):
                src = os.path.join(sub_path, sub_item)
                target = os.path.join(folder_path, sub_item)

                if copy:
                    if os.path.isfile(src):
                        shutil.copy(src, target)
                    else:
                        shutil.copytree(src, target)
                else:
                    shutil.move(src, target)

            if delete_subfolders:
                shutil.rmtree(sub_path)

def execute(self, request_object):

        # If the request object is not valid then return a failure response
        if not request_object.is_valid:
            return ResponseFailure.build_from_invalid_request(
                request_object)

        # Try to process the request and handle any errors encountered
        try:
            return self.process_request(request_object)

        except ValidationError as err:
            return ResponseFailure.build_unprocessable_error(err.normalized_messages)

        except ObjectNotFoundError:
            return ResponseFailure.build_not_found(
                [{'identifier': 'Object with this ID does not exist.'}])

        except Exception as exc:
            logger.error(
                f'{self.__class__.__name__} execution failed due to error {exc}',
                exc_info=True)
            return ResponseFailure.build_system_error([{exc.__class__.__name__: exc}])

def convert_time(self, time):
        time_string = str(datetime.timedelta(seconds=int(time)))
        if time_string.split(':')[0] == '0':
