def turbulent_Dittus_Boelter(Re, Pr, heating=True, revised=True):
    m = 0.023
    if heating:
        power = 0.4
    else:
        power = 0.3

    if heating and not revised:
        m = 0.0243
    elif not heating and not revised:
        m = 0.0265
    else:
        m = 0.023
    return m*Re**0.8*Pr**power

