def __geomToPointList(self, geom):
        if arcpyFound and isinstance(geom, arcpy.Polyline):
            feature_geom = []
            fPart = []
            wkt = None
            wkid = None
            for part in geom:
                fPart = []
                for pnt in part:
                    if geom.spatialReference is None:
                        if self._wkid is None and self._wkt is not None:
                            wkt = self._wkt
                        else:
                            wkid = self._wkid
                    else:
                        wkid = geom.spatialReference.factoryCode
                    fPart.append(Point(coord=[pnt.X, pnt.Y],
                          wkid=wkid,
                          wkt=wkt,
                          z=pnt.Z, m=pnt.M))
                feature_geom.append(fPart)
            return feature_geom

def users(store):
    user_objs = list(store.users())
    total_events = store.user_events().count()
    for user_obj in user_objs:
        if user_obj.get('institutes'):
            user_obj['institutes'] = [store.institute(inst_id) for inst_id in user_obj.get('institutes')]
        else:
            user_obj['institutes'] = []
        user_obj['events'] = store.user_events(user_obj).count()
        user_obj['events_rank'] = event_rank(user_obj['events'])
    return dict(
        users=sorted(user_objs, key=lambda user: -user['events']),
        total_events=total_events,
    )

def write_sheet(writer, name, df, index=False):
    if index:
        df = df.reset_index()
    df.to_excel(writer, name, index=False)
    worksheet = writer.sheets[name]
    for i, col in enumerate(df.columns):
        if df.dtypes[col].name.startswith(('float', 'int')):
            width = len(str(col)) + 2
        else:
            width = max([df[col].map(lambda x: len(str(x or 'None'))).max(),
                         len(col)]) + 2
        xls_col = '{c}:{c}'.format(c=NUMERIC_TO_STR[i])
        worksheet.set_column(xls_col, width)

