def duplicate_statements(model, oldorigin, neworigin, rfilter=None):
    for o, r, t, a in model.match(oldorigin):
        if rfilter is None or rfilter(o, r, t, a):
            model.add(I(neworigin), r, t, a)
    return

def olindex(order, dim):
    idxm = [0]*dim
    out = []

    def _olindex(idx):
        """Recursive backend for olindex."""
        if numpy.sum(idxm) == order:
            out.append(idxm[:])
            return

        if idx == dim:
            return

        idxm_sum = numpy.sum(idxm)
        idx_saved = idxm[idx]

        for idxi in range(order - numpy.sum(idxm) + 1):

            idxm[idx] = idxi

            if idxm_sum < order:
                _olindex(idx+1)

            else:
                break
        idxm[idx] = idx_saved

    _olindex(0)
    return numpy.array(out)

def tree_type_checker(*ref):
    ref = tuple(ref)
    if NeuriteType.all in ref:
        def check_tree_type(_):
            '''Always returns true'''
            return True
    else:
        def check_tree_type(tree):
            '''Check whether tree has the same type as ref

            Returns:
                True if ref in the same type as tree.type or ref is NeuriteType.all
            '''
            return tree.type in ref

    return check_tree_type

