def methods(self):
        ret = {}
        method_regex = re.compile(r"^[A-Z][A-Z0-9]+(_|$)")
        controller_methods = inspect.getmembers(self.controller_class)
        for controller_method_name, controller_method in controller_methods:
            if controller_method_name.startswith('_'): continue

            if method_regex.match(controller_method_name):
                method = self.method_class(
                    controller_method_name,
                    controller_method,
                    controller=self
                )
                ret.setdefault(method.name, [])
                ret[method.name].append(method)

        return ret

def bsnr(vblr, vnsy):

    blrvar = np.var(vblr)
    nsevar = np.var(vnsy - vblr)
    with np.errstate(divide='ignore'):
        rt = blrvar / nsevar
    return 10.0 * np.log10(rt)

def visit_if(self, node):
        ifs = ["if %s:\n%s" % (node.test.accept(self), self._stmt_list(node.body))]
        if node.has_elif_block():
            ifs.append("el%s" % self._stmt_list(node.orelse, indent=False))
        elif node.orelse:
            ifs.append("else:\n%s" % self._stmt_list(node.orelse))
        return "\n".join(ifs)

def from_stat(stat):
        name = stat.params['geom']
        if issubclass(type(name), geom):
            return name

        if isinstance(name, type) and issubclass(name, geom):
            klass = name
        elif is_string(name):
            if not name.startswith('geom_'):
                name = 'geom_{}'.format(name)
            klass = Registry[name]
        else:
            raise PlotnineError(
                'Unknown geom of type {}'.format(type(name)))

        return klass(stat=stat, **stat._kwargs)

def get_report_hook(self):
        def report_hook(chunkNumber, chunkSize, totalSize):
            if totalSize != -1 and not self._callback.range_initialized():
                log.debug('Initializing range: [{},{}]'.format(0, totalSize))
                self._callback.set_range(0, totalSize)
            self._chunkNumber = chunkNumber
            self._total += chunkSize
            if self._total > totalSize:
                # The chunk size can be bigger than the file
                self._total = totalSize
            self._callback.update(self._total)

        return report_hook

def get(self, name, param=None):
        if name not in self.attribs:
            raise exceptions.SoftLayerError('Unknown metadata attribute.')

        call_details = self.attribs[name]

        if call_details.get('param_req'):
            if not param:
                raise exceptions.SoftLayerError(
                    'Parameter required to get this attribute.')

        params = tuple()
        if param is not None:
            params = (param,)
        try:
            return self.client.call('Resource_Metadata',
                                    self.attribs[name]['call'],
                                    *params)
        except exceptions.SoftLayerAPIError as ex:
            if ex.faultCode == 404:
                return None
            raise ex

