def find(cls, dtype):
        try:
            return cls._member_map_[dtype]
        except KeyError:
            try:
                dtype = numpy.dtype(dtype).type
            except TypeError:
                for ndstype in cls._member_map_.values():
                    if ndstype.value is dtype:
                        return ndstype
            else:
                for ndstype in cls._member_map_.values():
                    if ndstype.value and ndstype.numpy_dtype is dtype:
                        return ndstype
            raise ValueError('%s is not a valid %s' % (dtype, cls.__name__))

def __random_density_bures(N, rank=None, seed=None):
    P = np.eye(N) + random_unitary(N).data
    G = P.dot(__ginibre_matrix(N, rank, seed))
    G = G.dot(G.conj().T)
    return G / np.trace(G)

def cast_like(x, y):
  x = tf.convert_to_tensor(x)
  y = tf.convert_to_tensor(y)

  if x.dtype.base_dtype == y.dtype.base_dtype:
    return x

  cast_x = tf.cast(x, y.dtype)
  if cast_x.device != x.device:
    x_name = "(eager Tensor)"
    try:
      x_name = x.name
    except AttributeError:
      pass
    tf.logging.warning("Cast for %s may induce copy from '%s' to '%s'", x_name,
                       x.device, cast_x.device)
  return cast_x

def to_pillow_image(self, return_mask=False):
        img = np.rollaxis(np.rollaxis(self.image.data, 2), 2)
        img = Image.fromarray(img[:, :, 0]) if img.shape[2] == 1 else Image.fromarray(img)
        if return_mask:
            mask = np.ma.getmaskarray(self.image)
            mask = Image.fromarray(np.rollaxis(np.rollaxis(mask, 2), 2).astype(np.uint8)[:, :, 0])
            return img, mask
        else:
            return img

