def validate(self, value, model=None, context=None):

        # ok if non-empty string
        if type(value) is str:
            value = value.strip()
            if value != '':
                return Error()

        # ok if has value
        if value:
            return Error()

        # ok if false, but false is allowed
        if value is False and self.allow_false:
            return Error()

        # ok if 0, but zero is allowed
        if value == 0 and self.allow_zero:
            return Error()

        # error otherwise
        return Error(self.value_required)

def dusk(self, date=None, local=True, use_elevation=True):

        if local and self.timezone is None:
            raise ValueError("Local time requested but Location has no timezone set.")

        if self.astral is None:
            self.astral = Astral()

        if date is None:
            date = datetime.date.today()

        elevation = self.elevation if use_elevation else 0
        dusk = self.astral.dusk_utc(date, self.latitude, self.longitude, observer_elevation=elevation)

        if local:
            return dusk.astimezone(self.tz)
        else:
            return dusk

def find_item_by_name(list_, namegetter, name):
    matching_items = [i for i in list_ if namegetter(i) == name]
    if not matching_items:
        prog = re.compile(re.escape(name) + '$', re.IGNORECASE)
        matching_items = [i for i in list_ if prog.match(namegetter(i))]
    if not matching_items:
        prog = re.compile(re.escape(name))
        matching_items = [i for i in list_ if prog.match(namegetter(i))]
    if not matching_items:
        prog = re.compile(re.escape(name), re.IGNORECASE)
        matching_items = [i for i in list_ if prog.match(namegetter(i))]
    if not matching_items:
        prog = re.compile(re.escape(name))
        matching_items = [i for i in list_ if prog.search(namegetter(i))]
    if not matching_items:
        prog = re.compile(re.escape(name), re.IGNORECASE)
        matching_items = [i for i in list_ if prog.search(namegetter(i))]
    return matching_items

