        n = multiprocessing.cpu_count() - 1

    return Pool(n)

def state_likelihood(self, beta, alpha):
        _, _, _, Q = self._ss_matrices(beta)
        residuals = alpha[0][1:]-alpha[0][:-1]
        return np.sum(ss.norm.logpdf(residuals, loc=0, scale=np.power(Q.ravel(),0.5)))

