    return res

def patch(self, endpoint, data, headers=None, inception=False):
        if not headers:
            raise BackendException(BACKEND_ERROR, "Header If-Match required for patching an object")

        response = self.get_response(method='PATCH', endpoint=endpoint, json=data, headers=headers)

        if response.status_code == 200:
            return self.decode(response=response)

        if response.status_code == 412:
            # 412 means Precondition failed, but confirm ...
            if inception:
                # update etag and retry to patch
                resp = self.get(endpoint)
                headers = {'If-Match': resp['_etag']}
                return self.patch(endpoint, data=data, headers=headers, inception=False)

            raise BackendException(response.status_code, response.content)
        else:  # pragma: no cover - should never occur
            raise BackendException(response.status_code, response.content)

def onchain_exchange(self, withdraw_crypto, withdraw_address, value, unit='satoshi'):
        self.onchain_rate = get_onchain_exchange_rates(
            self.crypto, withdraw_crypto, best=True, verbose=self.verbose
        )
        exchange_rate = float(self.onchain_rate['rate'])
        result = self.onchain_rate['service'].get_onchain_exchange_address(
            self.crypto, withdraw_crypto, withdraw_address
        )

        address = result['deposit']

        value_satoshi = self.from_unit_to_satoshi(value, unit)

        if self.verbose:
            print("Adding output of: %s satoshi (%.8f) via onchain exchange, converting to %s %s" % (
                value_satoshi, (value_satoshi / 1e8),
                exchange_rate * value_satoshi / 1e8, withdraw_crypto.upper()
            ))

        self.outs.append({
            'address': address,
            'value': value_satoshi
        })

