def get_shared_volume_path(container_map, vol, instance=None):
    if isinstance(vol, HostVolume):
        c_path = resolve_value(vol.path)
        if is_path(c_path):
            return c_path, get_host_path(container_map.host.root, vol.host_path, instance)
        raise ValueError("Host-container-binding must be described by two paths or one alias name.",
                         vol)
    alias = vol.name
    volume_config = resolve_value(container_map.volumes.get(alias))
    h_path = container_map.host.get_path(alias, instance)
    if volume_config and h_path:
        return volume_config.default_path, h_path
    raise KeyError("No host-volume information found for alias {0}.".format(alias))

def generate_upload_policy(self, conditions, expiration=None, client=None):
        client = self._require_client(client)
        credentials = client._base_connection.credentials
        _signing.ensure_signed_credentials(credentials)

        if expiration is None:
            expiration = _NOW() + datetime.timedelta(hours=1)

        conditions = conditions + [{"bucket": self.name}]

        policy_document = {
            "expiration": _datetime_to_rfc3339(expiration),
            "conditions": conditions,
        }

        encoded_policy_document = base64.b64encode(
            json.dumps(policy_document).encode("utf-8")
        )
        signature = base64.b64encode(credentials.sign_bytes(encoded_policy_document))

        fields = {
            "bucket": self.name,
            "GoogleAccessId": credentials.signer_email,
            "policy": encoded_policy_document.decode("utf-8"),
            "signature": signature.decode("utf-8"),
        }

        return fields

def retrymethod(count, sleep=0):

    def decorated(func):
        @wraps(func)
        def wrapped(*args, **kwds):
            # do the retry options
            for i in range(count - 1):
                try:
                    return func(*args, **kwds)
                except StandardError:
                    pass

                if sleep:
                    time.sleep(sleep)

            # run as standard
            return func(*args, **kwds)

        return wrapped

    return decorated

