def peek_with_kwargs(init, args=[]):
    def peek(store, container, _stack=None):
        return init(\
            *[ store.peek(attr, container, _stack=_stack) for attr in args ], \
            **dict([ (attr, store.peek(attr, container, _stack=_stack)) \
                for attr in container if attr not in args ]))
    return peek

def normpath(path):
    # type: (Text) -> Text
    if path in "/":
        return path

    # An early out if there is no need to normalize this path
    if not _requires_normalization(path):
        return path.rstrip("/")

    prefix = "/" if path.startswith("/") else ""
    components = []  # type: List[Text]
    try:
        for component in path.split("/"):
            if component in "..":  # True for '..', '.', and ''
                if component == "..":
                    components.pop()
            else:
                components.append(component)
    except IndexError:
        raise IllegalBackReference(path)
    return prefix + "/".join(components)

def sanitize_path(path):

    if path == '/':  # Nothing to do, just return
        return path

    if path[:1] != '/':
        raise InvalidPath('The path must start with a slash')

    # Deduplicate slashes in path
    path = re.sub(r'/+', '/', path)

    # Strip trailing slashes and return
    return path.rstrip('/')

def collectData(reads1, reads2, square, matchAmbiguous):
    result = defaultdict(dict)
    for id1, read1 in reads1.items():
        for id2, read2 in reads2.items():
            if id1 != id2 or not square:
                match = compareDNAReads(
                    read1, read2, matchAmbiguous=matchAmbiguous)['match']
                if not matchAmbiguous:
                    assert match['ambiguousMatchCount'] == 0
                result[id1][id2] = result[id2][id1] = match

    return result

