        session.adapter.remove_instrument('left')
        session.adapter.remove_instrument('right')
    else:
        session.adapter.cache_instruments()
    session = None
    return web.json_response({"message": "calibration session released"})

def compute_writer_results(results):
    if not results:
        return

    sources, targets, delayeds = split_results(results)

    # one or more writers have targets that we need to close in the future
    if targets:
        delayeds.append(da.store(sources, targets, compute=False))

    if delayeds:
        da.compute(delayeds)

    if targets:
        for target in targets:
            if hasattr(target, 'close'):
                target.close()

