def getElecType(self): 

        tiesPresent = False
        incompletePresent = False

        # Go through the list of Preferences and see if any contain a tie or are incomplete.
        for preference in self.preferences:
            if preference.containsTie() == True:
                tiesPresent = True
                break
            if preference.isFullPreferenceOrder(self.candMap.keys()) == False:
                incompletePresent = True
                break

        if tiesPresent == False and incompletePresent == False:
            elecType = "soc"
        elif tiesPresent == False and incompletePresent == True:
            elecType = "soi"
        elif tiesPresent == True and incompletePresent == False:
            elecType = "toc"
        elif tiesPresent == True and incompletePresent == True:
            elecType = "toi"
        return elecType

def run_c_extension_with_fallback(
        log_function,
        extension,
        c_function,
        py_function,
        args,
        rconf
):
    computed = False
    if not rconf[u"c_extensions"]:
        log_function(u"C extensions disabled")
    elif extension not in rconf:
        log_function([u"C extension '%s' not recognized", extension])
    elif not rconf[extension]:
        log_function([u"C extension '%s' disabled", extension])
    else:
        log_function([u"C extension '%s' enabled", extension])
        if c_function is None:
            log_function(u"C function is None")
        elif can_run_c_extension(extension):
            log_function([u"C extension '%s' enabled and it can be loaded", extension])
            computed, result = c_function(*args)
        else:
            log_function([u"C extension '%s' enabled but it cannot be loaded", extension])
    if not computed:
        if py_function is None:
            log_function(u"Python function is None")
        else:
            log_function(u"Running the pure Python code")
            computed, result = py_function(*args)
    if not computed:
        raise RuntimeError(u"Both the C extension and the pure Python code failed. (Wrong arguments? Input too big?)")
    return result

def language_contents(instance):
    if instance['type'] != 'language-content' or 'contents' not in instance:
        return

    for key, value in instance['contents'].items():
        if key not in enums.LANG_CODES:
            yield JSONError("Invalid key '%s' in 'contents' property must be"
                            " an RFC 5646 code" % key, instance['id'])
        for subkey, subvalue in value.items():
            if not PROPERTY_FORMAT_RE.match(subkey):
                yield JSONError("'%s' in '%s' of the 'contents' property is "
                                "invalid and must match a valid property name"
                                % (subkey, key), instance['id'], 'observable-dictionary-keys')

def iterGrid(self, minZoom, maxZoom):
        assert minZoom in range(0, len(self.RESOLUTIONS))
        assert maxZoom in range(0, len(self.RESOLUTIONS))
        assert minZoom <= maxZoom

        for zoom in xrange(minZoom, maxZoom + 1):
            [minRow, minCol, maxRow, maxCol] = self.getExtentAddress(zoom)
            for row in xrange(minRow, maxRow + 1):
                for col in xrange(minCol, maxCol + 1):
                    tileBounds = self.tileBounds(zoom, col, row)
                    yield (tileBounds, zoom, col, row)

def data(self, index, role):
        if not index.isValid():
            return

        item = self.item(index)
        column = index.column()
        value = item.getItemData(column)

        if role == Qt.DisplayRole:
            try:
                if column == 1:
                    # Display small values using scientific notation.
                    if abs(float(value)) < 1e-3 and float(value) != 0.0:
                        return '{0:8.1e}'.format(value)
                    else:
                        return '{0:8.3f}'.format(value)
                else:
                    return '{0:8.2f}'.format(value)
            except ValueError:
                return value
        elif role == Qt.EditRole:
            try:
                value = float(value)
                if abs(value) < 1e-3 and value != 0.0:
                    return str('{0:8.1e}'.format(value))
                else:
                    return str('{0:8.3f}'.format(value))
            except ValueError:
                return str(value)
        elif role == Qt.CheckStateRole:
            if item.parent == self.rootItem and column == 0:
                return item.getCheckState()
        elif role == Qt.TextAlignmentRole:
            if column > 0:
                return Qt.AlignRight

def sign(self, data, b64=True):
        padder = padding.PKCS1v15()
        signer = self.private_key.signer(padder, None)
        if not isinstance(data, six.binary_type):
            data = data.encode('utf_8')
        signer.update(data)
        signed = signer.finalize()
        if b64:
            signed = base64.b64encode(signed)
        return signed

