def _str_to_windows(self, input_str, window_length, curse_forward):
        windows = []

        i = 0
        len_input = len(input_str)
        while i < len_input:
            window_text = input_str[i:i+window_length]

            if self.sanitize_input:
                windows.append({
                                    'sanitized' : self._sanitize(window_text),
                                    'text' : window_text
                                })
            else:
                windows.append({
                                    'text' : window_text
                                })

            i = i + curse_forward


        return windows

