def delete_database(self, instance_id, database_id, project_id=None):

        instance = self._get_client(project_id=project_id).\
            instance(instance_id=instance_id)
        if not instance.exists():
            raise AirflowException("The instance {} does not exist in project {} !".
                                   format(instance_id, project_id))
        database = instance.database(database_id=database_id)
        if not database.exists():
            self.log.info("The database {} is already deleted from instance {}. "
                          "Exiting.".format(database_id, instance_id))
            return
        try:
            operation = database.drop()  # type: Operation
        except GoogleAPICallError as e:
            self.log.error('An error occurred: %s. Exiting.', e.message)
            raise e

        if operation:
            result = operation.result()
            self.log.info(result)
        return

def yield_amd_require_string_arguments(
        node, pos,
        reserved_module=reserved_module, wrapped=define_wrapped):

    for i, child in enumerate(node.args.items[pos]):
        if isinstance(child, asttypes.String):
            result = to_str(child)
            if ((result not in reserved_module) and (
                    result != define_wrapped.get(i))):
                yield result

async def expand_all_quays(self) -> None:
        if not self.stops:
            return

        headers = {'ET-Client-Name': self._client_name}
        request = {
            'query': GRAPHQL_STOP_TO_QUAY_TEMPLATE,
            'variables': {
                'stops': self.stops,
                'omitNonBoarding': self.omit_non_boarding
            }
        }

        with async_timeout.timeout(10):
            resp = await self.web_session.post(RESOURCE,
                                               json=request,
                                               headers=headers)

        if resp.status != 200:
            _LOGGER.error(
                "Error connecting to Entur, response http status code: %s",
                resp.status)
            return None
        result = await resp.json()

        if 'errors' in result:
            return

        for stop_place in result['data']['stopPlaces']:
            if len(stop_place['quays']) > 1:
                for quay in stop_place['quays']:
                    if quay['estimatedCalls']:
                        self.quays.append(quay['id'])

def _loadcache(cachefile):
