def Nu_Griem(Re, Pr, H=None):
    if H:
        if H < 1.54E6:
            w = 0.82
        elif H > 1.74E6:
            w = 1
        else:
            w = 0.82 + 9E-7*(H - 1.54E6)
    else:
        w = 1
    Nu = 0.0169*Re**0.8356*Pr**0.432*w
    return Nu

