def validate_password(entry, username, check_function, password=None, retries=1, save_on_success=True, prompt=None, **check_args):

    if password is None:
        password = get_password(entry, username, prompt)

    for _ in xrange(retries + 1):

        if check_function(username, password, **check_args):
            if save_on_success:
                save_password(entry, password, username)

            return True

        log.error("Couldn't successfully authenticate your username & password..")

        password = get_password(entry, username, prompt, always_ask=True)

    return False

def validate(self, metadata, path, value):
        if isinstance(value, Requirement):
            # if the RHS is still a Requirement object, it was not set
            if metadata.testing and self.mock_value is not None:
                value = self.mock_value
            elif self.default_value is not None:
                value = self.default_value
            elif not value.required:
                return None
            else:
                raise ValidationError(f"Missing required configuration for: {'.'.join(path)}")

        try:
            return self.type(value)
        except ValueError:
            raise ValidationError(f"Missing required configuration for: {'.'.join(path)}: {value}")

def parallel(devices, fn, *args, **kwargs):
  if not isinstance(devices, list):
    raise ValueError("devices must be a list")
  for x in list(args) + list(six.itervalues(kwargs)):
    if not isinstance(x, list) or len(x) != len(devices):
      raise ValueError(
          "Argument not a list with same length as devices "
          "arg=%s devices=%s" % (x, devices))
  ret = []
  for i, device in enumerate(devices):
    with tf.device(device):
      with tf.variable_scope("parallel_%d" % i):
        my_args = [x[i] for x in args]
        my_kwargs = {k: v[i] for k, v in six.iteritems(kwargs)}
        ret.append(fn(*my_args, **my_kwargs))
  return ret

