def forward(self, serial, remote, local_port=None): #local_port, remote_port=None):
        if isinstance(remote, int):
            remote = 'tcp:%d' % remote
        if not local_port:
            for s, lp, rp in self.forward_list():
                if s == serial and rp == remote:
                    return int(lp[4:])
            return self.forward(serial, remote, next_local_port(self.server_host))
        else:
            self.raw_cmd("-s", serial, "forward", 'tcp:%d' % local_port, remote).wait()
            return local_port

def parse(self, telegram_data):

        if self.apply_checksum_validation \
                and self.telegram_specification['checksum_support']:
            self.validate_checksum(telegram_data)

        telegram = {}

        for signature, parser in self.telegram_specification['objects'].items():
            match = re.search(signature, telegram_data, re.DOTALL)

            # Some signatures are optional and may not be present,
            # so only parse lines that match
            if match:
                telegram[signature] = parser.parse(match.group(0))

        return telegram

def merge(self, other):
