def upper_camel(string, prefix='', suffix=''):

    return require_valid(append_underscore_if_keyword(''.join(
        upper_case_first_char(word)
        for word in en.words(' '.join([prefix, string, suffix])))
    ))

def handle(data_type, data, data_id=None, caller=None):

    if not data_id:
        data_id = data_type

    # instantiate handlers for data type if they havent been yet
    if data_id not in _handlers:
        _handlers[data_id] = dict(
            [(h.handle, h) for h in handlers.instantiate_for_data_type(data_type, data_id=data_id)])

    for handler in list(_handlers[data_id].values()):
        try:
            data = handler(data, caller=caller)
        except Exception as inst:
            vodka.log.error("Data handler '%s' failed with error" % handler)
            vodka.log.error(traceback.format_exc())

    return data

def index_of_reports(self, report, account_id):
        path = {}
        data = {}
        params = {}

        # REQUIRED - PATH - account_id
        """ID"""
        path["account_id"] = account_id

        # REQUIRED - PATH - report
        """ID"""
        path["report"] = report

        self.logger.debug("GET /api/v1/accounts/{account_id}/reports/{report} with query params: {params} and form data: {data}".format(params=params, data=data, **path))
        return self.generic_request("GET", "/api/v1/accounts/{account_id}/reports/{report}".format(**path), data=data, params=params, all_pages=True)

def get_collection(collection):
    cls = endpoint_class(collection)

    resources = retrieve_collection(collection, request.args)

    _validate(cls, request.method, resources)

    start = stop = None

    if request.args and 'page' in request.args:
        page = int(request.args['page'])
        results_per_page = app.config.get('RESULTS_PER_PAGE', 20)
        start, stop = page * results_per_page, (page + 1) * results_per_page
    return collection_response(cls, resources, start, stop)

def exception_message():
    exc_type, exc_value, exc_tb = exc_info = sys.exc_info()
    # Package the captured exception details into a structured dictionary.
    return {'exception': {'type': exc_type,
                          'value': exc_value,
                          'traceback': exc_tb},
            'traceback': traceback.format_exception(*exc_info)}

