            return self.raw_path
        return "{}?{}".format(self.raw_path, self.raw_query_string)

def _get_proc_status(proc):
    try:
        return salt.utils.data.decode(proc.status() if PSUTIL2 else proc.status)
    except (psutil.NoSuchProcess, psutil.AccessDenied):
        return None

def load_allconfig(kconf, filename):
    def std_msg(e):
        # "Upcasts" a _KconfigIOError to an IOError, removing the custom
        # __str__() message. The standard message is better here.
        return IOError(e.errno, e.strerror, e.filename)

    kconf.disable_override_warnings()
    kconf.disable_redun_warnings()

    allconfig = os.environ.get("KCONFIG_ALLCONFIG")
    if allconfig is not None:
        if allconfig in ("", "1"):
            try:
                kconf.load_config(filename, False)
            except IOError as e1:
                try:
                    kconf.load_config("all.config", False)
                except IOError as e2:
                    sys.exit("error: KCONFIG_ALLCONFIG is set, but neither {} "
                             "nor all.config could be opened: {}, {}"
                             .format(filename, std_msg(e1), std_msg(e2)))
        else:
            try:
                kconf.load_config(allconfig, False)
            except IOError as e:
                sys.exit("error: KCONFIG_ALLCONFIG is set to '{}', which "
                         "could not be opened: {}"
                         .format(allconfig, std_msg(e)))

    # API wart: It would be nice if there was a way to query and/or push/pop
    # warning settings
    kconf.enable_override_warnings()
    kconf.enable_redun_warnings()

def get_timefactor(cls) -> float:
        try:
            parfactor = hydpy.pub.timegrids.parfactor
        except RuntimeError:
            if not (cls.parameterstep and cls.simulationstep):
                raise RuntimeError(
                    f'To calculate the conversion factor for adapting '
                    f'the values of the time-dependent parameters, '
                    f'you need to define both a parameter and a simulation '
                    f'time step size first.')
            else:
                date1 = timetools.Date('2000.01.01')
                date2 = date1 + cls.simulationstep
                parfactor = timetools.Timegrids(timetools.Timegrid(
                    date1, date2, cls.simulationstep)).parfactor
        return parfactor(cls.parameterstep)

