def __intermediate_hwmode(self, radio):
        protocol = radio['protocol']
        if protocol in ['802.11a', '802.11b', '802.11g']:
            # return 11a, 11b or 11g
            return protocol[4:]
        # determine hwmode depending on channel used
        if radio['channel'] is 0:
            # when using automatic channel selection, we need an
            # additional parameter to determine the frequency band
            return radio.get('hwmode')
        elif radio['channel'] <= 13:
            return '11g'
        else:
            return '11a'

def process_post_many_to_many_field(existing_post, field, related_objects):
        to_add = set(related_objects.get(existing_post.wp_id, set())) - set(getattr(existing_post, field).all())
        to_remove = set(getattr(existing_post, field).all()) - set(related_objects.get(existing_post.wp_id, set()))

        if to_add:
            getattr(existing_post, field).add(*to_add)
        if to_remove:
            getattr(existing_post, field).remove(*to_remove)

