def user_create(name,
                passwd,
                database=None,
                user=None,
                password=None,
                host=None,
                port=None):
    if user_exists(name, database, user, password, host, port):
        if database:
            log.info('User \'%s\' already exists for DB \'%s\'', name, database)
        else:
            log.info('Cluster admin \'%s\' already exists', name)
        return False

    client = _client(user=user, password=password, host=host, port=port)

    if not database:
        return client.add_cluster_admin(name, passwd)

    client.switch_database(database)
    return client.add_database_user(name, passwd)

def ifelse(arg, true_expr, false_expr):
    # Result will be the result of promotion of true/false exprs. These
    # might be conflicting types; same type resolution as case expressions
    # must be used.
    case = ops.SearchedCaseBuilder()
    return case.when(arg, true_expr).else_(false_expr).end()

