def fork_at(vm_class: Type[BaseVM], at_block: int, chain_class: Type[BaseChain]) -> Type[BaseChain]:
    if chain_class.vm_configuration is not None:
        base_configuration = chain_class.vm_configuration
    else:
        base_configuration = tuple()

    vm_configuration = base_configuration + ((at_block, vm_class),)
    validate_vm_configuration(vm_configuration)
    return chain_class.configure(vm_configuration=vm_configuration)

def unset_values(self):
        self._warn_for_no_prompt = False
        try:
            # set_value() already rejects undefined symbols, and they don't
            # need to be invalidated (because their value never changes), so we
            # can just iterate over defined symbols
            for sym in self.unique_defined_syms:
                sym.unset_value()

            for choice in self.unique_choices:
                choice.unset_value()
        finally:
            self._warn_for_no_prompt = True

def div_filter(key: str, value: list, format: str, meta: Any) -> Optional[list]:
    if key != "Div" or format != "latex":
        return None

    [[_, classes, _], contents] = value
    try:
        alert_type = [name.split("-")[1] for name in classes if "-" in name][0]
    except IndexError:
        return None

    if alert_type not in ALLOWED_ALERT_TYPES.__members__:
        return None

    filtered = [RawBlock("latex", rf"\begin{{{alert_type}box}}")]
    filtered.extend(contents)
    filtered.append(RawBlock("latex", rf"\end{{{alert_type}box}}"))
    return filtered

