def fetch(self, station: str) -> str:
        valid_station(station)
        try:
            resp = getattr(requests, self.method.lower())(self.url.format(self.rtype, station))
            if resp.status_code != 200:
                raise SourceError(f'{self.__class__.__name__} server returned {resp.status_code}')
        except requests.exceptions.ConnectionError:
            raise ConnectionError(f'Unable to connect to {self.__class__.__name__} server')
        report = self._extract(resp.text, station)
        # This split join replaces all *whitespace elements with a single space
        return ' '.join(report.split())

def operator(self, operatorType, value):
        if type(value) == datetime.timedelta:
            if operatorType == Query.Op.After:
                return 'after (delta)'
            elif operatorType == Query.Op.Before:
                return 'before (delta)'

        return super(DateTimePlugin, self).operator(operatorType, value)

def _exec_action(self,
                     method,
                     type,
                     chaincodeID,
                     function,
                     args,
                     id,
                     secure_context=None,
                     confidentiality_level=CHAINCODE_CONFIDENTIAL_PUB,
                     metadata=None):
        if method not in DEFAULT_CHAINCODE_METHODS:
            self.logger.error('Non-supported chaincode method: '+method)

        data = {
            "jsonrpc": "2.0",  # JSON-RPC protocol version. MUST be "2.0".
            "method": method,
            "params": {
                "type": type,
                "chaincodeID": chaincodeID,
                "ctorMsg": {
                    "function": function,
                    "args": args
                }
            },
            "id": id
        }
        if secure_context:
            data["params"]["secureContext"] = secure_context
        u = self._url("/chaincode")
        response = self._post(u, data=json.dumps(data))
        return self._result(response, True)

