def check_xlim_change(self):
        if self.xlim_pipe is None:
            return None
        xlim = None
        while self.xlim_pipe[0].poll():
            try:
                xlim = self.xlim_pipe[0].recv()
            except EOFError:
                return None
        if xlim != self.xlim:
            return xlim
        return None

def _setfile(self, filename, length, offset):
        source = open(filename, 'rb')
        if offset is None:
            offset = 0
        if length is None:
            length = os.path.getsize(source.name) * 8 - offset
        byteoffset, offset = divmod(offset, 8)
        bytelength = (length + byteoffset * 8 + offset + 7) // 8 - byteoffset
        m = MmapByteArray(source, bytelength, byteoffset)
        if length + byteoffset * 8 + offset > m.filelength * 8:
            raise CreationError("File is not long enough for specified "
                                "length and offset.")
        self._datastore = ConstByteStore(m, length, offset)

def combine_cache_keys(cls, cache_keys):
    if len(cache_keys) == 1:
      return cache_keys[0]
    else:
      combined_id = Target.maybe_readable_combine_ids(cache_key.id for cache_key in cache_keys)
      combined_hash = hash_all(sorted(cache_key.hash for cache_key in cache_keys))
      return cls(combined_id, combined_hash)

