def sanity_checks(self):

        if self._config.state.sanity_checked:
            return

        log.info("Sanity checks: '{}'".format(self._name))

        HAS_DOCKER_PY = None
        try:
            from ansible.module_utils.docker_common import HAS_DOCKER_PY
        except ImportError:

            # ansible 2.8+
            try:
                from ansible.module_utils.docker.common import HAS_DOCKER_PY
            except ImportError:
                pass

        if not HAS_DOCKER_PY:
            msg = ('Missing Docker driver dependency. Please '
                   "install via 'molecule[docker]' or refer to "
                   'your INSTALL.rst driver documentation file')
            sysexit_with_message(msg)

        try:
            import docker
            import requests
            docker_client = docker.from_env()
            docker_client.ping()
        except requests.exceptions.ConnectionError:
            msg = ('Unable to contact the Docker daemon. '
                   'Please refer to https://docs.docker.com/config/daemon/ '
                   'for managing the daemon')
            sysexit_with_message(msg)

        self._config.state.change_state('sanity_checked', True)

def _get_subcats(self, recurse=False):

        if recurse:
            # No need to filter
            return sorted([Category(e) for e in self._subcats_recursive],
                          key=lambda c: c.sort_breadcrumb)

        # get all the subcategories, with only the first subdir added

        # number of path components to ingest
        parts = len(self.path.split('/')) + 1 if self.path else 1

        # convert the subcategories into separated pathlists with only 'parts'
        # parts
        subcats = [c.split('/')[:parts] for c in self._subcats_recursive]

        # join them back into a path, and make unique
        subcats = {'/'.join(c) for c in subcats}

        # convert to a bunch of Category objects
        return sorted([Category(c) for c in subcats], key=lambda c: c.sort_name or c.name)

def _ConvertDictToPathSpec(cls, json_dict):
    type_indicator = json_dict.get('type_indicator', None)
    if type_indicator:
      del json_dict['type_indicator']

    if 'parent' in json_dict:
      json_dict['parent'] = cls._ConvertDictToPathSpec(json_dict['parent'])

    # Remove the class type from the JSON dict since we cannot pass it.
    del json_dict['__type__']

    return dfvfs_path_spec_factory.Factory.NewPathSpec(
        type_indicator, **json_dict)

