        return '%s.%s.%s' % (p_elem, s_elem, t_elem)

def _copy_stream(src, dest, length=0):
    if length == 0:
        shutil.copyfileobj(src, dest)
        return

    bytes_left = length
    while bytes_left > 0:
        buf_size = min(_BUFFER_SIZE, bytes_left)
        buf = src.read(buf_size)
        dest.write(buf)
        bytes_left -= buf_size

def symlink_abiext(self, inext, outext):
        infile = self.has_abiext(inext)
        if not infile:
            raise RuntimeError('no file with extension %s in %s' % (inext, self))

        for i in range(len(infile) - 1, -1, -1):
            if infile[i] == '_':
                break
        else:
            raise RuntimeError('Extension %s could not be detected in file %s' % (inext, infile))

        tmp = infile[:i] + '_' + outext

        if os.path.exists(tmp):
            if os.path.islink(tmp):
                if os.path.realpath(tmp) == infile:
                    logger.debug("link %s already exists but it's ok because it points to the correct file" % tmp)
                    return 0
                else:
                    raise RuntimeError("Expecting link at %s already exists but it does not point to %s" % (tmp, infile))
            else:
                raise RuntimeError('Expecting link at %s but found file.' % tmp)

        os.symlink(infile, tmp)
        return 0

