def _consolidate(data_type):
    if isinstance(data_type, _ATOMIC):
        out = data_type
    elif isinstance(data_type, Array):
        element_type = _consolidate(data_type.element_type)
        out = data_type._replace(element_type=element_type)
    elif isinstance(data_type, Structure):
        fields = tuple(
            Field(*(_consolidate(field[i]) if i == _FIELD_TYPE_IDX
                    else field[i]
                    for i in _range(len(field))))
            for field in data_type.fields)
        out = data_type._replace(fields=fields)

    return out

def _sequence(self, i):

        c = next(i)
        if c == '!':
            c = next(i)
        if c in ('^', '-', '['):
            c = next(i)

        while c != ']':
            if c == '\\':
                # Handle escapes
                subindex = i.index
                try:
                    self._references(i, True)
                except PathNameException:
                    raise StopIteration
                except StopIteration:
                    i.rewind(i.index - subindex)
            elif c == '/':
                raise StopIteration
            c = next(i)

def amean(x, weights=None):
    w_arr, x_arr = _preprocess_inputs(x, weights)
    return (w_arr*x_arr).sum(axis=0) / w_arr.sum(axis=0)

def simplify(self, e=None):
        if e is None:
            return self._solver.simplify()
        elif isinstance(e, (int, float, bool)):
            return e
        elif isinstance(e, claripy.ast.Base) and e.op in claripy.operations.leaf_operations_concrete:
            return e
        elif isinstance(e, SimActionObject) and e.op in claripy.operations.leaf_operations_concrete:
            return e.ast
        elif not isinstance(e, (SimActionObject, claripy.ast.Base)):
            return e
        else:
            return self._claripy_simplify(e)

def GetHasherNamesFromString(cls, hasher_names_string):
    hasher_names = []

    if not hasher_names_string or hasher_names_string.strip() == 'none':
      return hasher_names

    if hasher_names_string.strip() == 'all':
      return cls.GetHasherNames()

    for hasher_name in hasher_names_string.split(','):
      hasher_name = hasher_name.strip()
      if not hasher_name:
        continue

      hasher_name = hasher_name.lower()
      if hasher_name in cls._hasher_classes:
        hasher_names.append(hasher_name)

    return hasher_names

