def marshal(self, obj, as_map_key, cache):
        handler = self.handlers[obj]
        tag = handler.tag(obj)
        f = marshal_dispatch.get(tag)

        if f:
            f(self, obj, handler.string_rep(obj) if as_map_key else handler.rep(obj), as_map_key, cache)
        else:
            self.emit_encoded(tag, handler, obj, as_map_key, cache)

def term(self):
        node = self.atom()

        while self.token.nature in (Nature.MUL, Nature.DIV, Nature.INT_DIV):
            token = self.token
            if token.nature == Nature.MUL:
                self._process(Nature.MUL)
            elif token.nature == Nature.DIV:
                self._process(Nature.DIV)
            elif token.nature == Nature.INT_DIV:
                self._process(Nature.INT_DIV)
            else:
                self._error()

            node = BinaryOperation(left=node, op=token, right=self.atom())

        return node

