def get_newest(blocks, layout_blocks):
    layout_temp = list(layout_blocks)

    for i in range(0, len(layout_temp)):
        for k in range(0, len(layout_blocks)):
            if blocks[layout_temp[i]].ec_hdr.image_seq != blocks[layout_blocks[k]].ec_hdr.image_seq:
                continue

            if blocks[layout_temp[i]].leb_num != blocks[layout_blocks[k]].leb_num:
                continue

            if blocks[layout_temp[i]].vid_hdr.sqnum > blocks[layout_blocks[k]].vid_hdr.sqnum:
                del layout_blocks[k]
                break

    return layout_blocks

def lookup_obj_attribute(self, obj, field):
        curr_field = field.encode('ascii', 'ignore').decode("utf-8")
        rest = None

        if field.find('.') >= 0:
            curr_field = field.split('.')[0]
            rest = '.'.join(field.split('.')[1:])

        # next up is the object itself
        obj_field = getattr(obj, curr_field, None)

        # if it is callable, do so
        if obj_field and getattr(obj_field, '__call__', None):
            obj_field = obj_field()

        if obj_field and rest:
            return self.lookup_obj_attribute(obj_field, rest)
        else:
            return obj_field

