def consistency(self, desired_version=None, include_package=False,
                    strictness=None):
        keys_to_check = list(self.versions.keys())
        if not include_package and 'package' in keys_to_check:
            keys_to_check.remove('package')

        if desired_version is None:
            # if we have to guess, we trust setup.py
            try:
                desired_version = self.versions['setup.py']
            except KeyError:
                desired_version = self.versions[keys_to_check[0]]

        if strictness is None:
            strictness = self.strictness
        desired = self._version(desired_version, strictness)

        error_keys = []
        for key in keys_to_check:
            test = self._version(self.versions[key], strictness)
            if test != desired:
                error_keys += [key]

        # make the error message
        msg = ""
        for key in error_keys:
            msg += "Error: desired {d} != {v} ({k})\n".format(
                d=str(desired),
                v=str(self.versions[key]),
                k=str(key)
            )
        return msg

def states(self, states):
        if not isinstance(states, dict):
            raise TypeError("states must be of type dict")
        if [state_id for state_id, state in states.items() if not isinstance(state, State)]:
            raise TypeError("element of container_state.states must be of type State")
        if [state_id for state_id, state in states.items() if not state_id == state.state_id]:
            raise AttributeError("The key of the state dictionary and the id of the state do not match")

        old_states = self._states
        self._states = states
        for state_id, state in states.items():
            try:
                state.parent = self
            except ValueError:
                self._states = old_states
                raise

        # check that all old_states are no more referencing self as there parent
        for old_state in old_states.values():
            if old_state not in self._states.values() and old_state.parent is self:
                old_state.parent = None

