def leastsqfitter(p0, datax, datay, function, verbose=False, cov_verbose=False):
    timer = Timer(verbose=False)
    with timer:
        # define error function
        def errfunc(p, x, y):
            return y - function(p, x)

        # run optimization
        pfit_leastsq, pcov, infodict, errmsg, success = scipy_optimize.leastsq(
            errfunc, p0, args=(datax, datay), full_output=1, epsfcn=0.0001
        )
        # calculate covarience matrix
        # original idea https://stackoverflow.com/a/21844726
        if (len(datay) > len(p0)) and pcov is not None:
            s_sq = (errfunc(pfit_leastsq, datax, datay) ** 2).sum() / (len(datay) - len(p0))
            pcov = pcov * s_sq
            if cov_verbose:
                print(pcov)
        else:
            pcov = np.array(np.inf)
        # calculate and write errors
        error = []
        for i in range(len(pfit_leastsq)):
            try:
                error.append(np.absolute(pcov[i][i]) ** 0.5)
            except IndexError:
                error.append(0.00)
        perr_leastsq = np.array(error)
    # exit
    if verbose:
        print("fit params:       ", pfit_leastsq)
        print("fit params error: ", perr_leastsq)
        print("fitting done in %f seconds" % timer.interval)
    return pfit_leastsq, perr_leastsq

def register(**criteria):

    def inner(cls):
        # Add class references to search index
        class_list.add(cls)
        for (category, value) in criteria.items():
            index[category][value].add(cls)

        # Retain search criteria
        _entry = dict((k, set([v])) for (k, v) in criteria.items())
        if cls not in class_criteria:
            class_criteria[cls] = _entry
        else:
            for key in _entry.keys():
                class_criteria[cls][key] = class_criteria[cls].get(key, set()) | _entry[key]

        # Return class
        return cls

    return inner

