def _merge_element_contents(el):
    parent = el.getparent()
    tmp = el.text or ''
    if el.tail:
        if not len(el):
            tmp += el.tail
        else:
            if el[-1].tail:
                el[-1].tail += el.tail
            else:
                el[-1].tail = el.tail
    index = parent.index(el)
    if tmp:
        if index == 0:
            previous = None
        else:
            previous = parent[index-1]
        if previous is None:
            if parent.text:
                parent.text += tmp
            else:
                parent.text = tmp
        else:
            if previous.tail:
                previous.tail += tmp
            else:
                previous.tail = tmp
    parent[index:index+1] = el.getchildren()

