def displayformat(codes=[], fg=None, bg=None):
        if isinstance(codes, basestring):
            codes = [codes]
        else:
            codes = list(codes)
        for code in codes:
            if code not in Magic.DISPLAY.keys():
                raise ValueError("'%s' not a valid display value" % code)
        for color in (fg, bg):
            if color != None:
                if color not in Magic.COLORS.keys():
                    raise ValueError("'%s' not a valid color" % color)
        return [codes, fg, bg]

def groupByNodes(requestContext, seriesList, callback, *nodes):
    from .app import app
    metaSeries = {}
    keys = []
    if isinstance(nodes, int):
        nodes = [nodes]
    for series in seriesList:
        key = '.'.join(series.name.split(".")[n] for n in nodes)
        if key not in metaSeries:
            metaSeries[key] = [series]
            keys.append(key)
        else:
            metaSeries[key].append(series)
    for key in metaSeries:
        metaSeries[key] = app.functions[callback](requestContext,
                                                  metaSeries[key])[0]
        metaSeries[key].name = key
    return [metaSeries[key] for key in keys]

