def timesince(when):
    if not when:
        return ''

    now = datetime.datetime.utcnow()
    if now > when:
        diff = now - when
        suffix = 'ago'
    else:
        diff = when - now
        suffix = 'from now'

    periods = (
        (diff.days / 365, 'year', 'years'),
        (diff.days / 30, 'month', 'months'),
        (diff.days / 7, 'week', 'weeks'),
        (diff.days, 'day', 'days'),
        (diff.seconds / 3600, 'hour', 'hours'),
        (diff.seconds / 60, 'minute', 'minutes'),
        (diff.seconds, 'second', 'seconds'),
    )

    for period, singular, plural in periods:
        if period:
            return '%d %s %s' % (
                period,
                singular if period == 1 else plural,
                suffix)

    return 'now'

def handle_response(self, item_session: ItemSession) -> Actions:
        action = self.consult_response_hook(item_session)

        if action == Actions.RETRY:
            item_session.set_status(Status.error)
        elif action == Actions.FINISH:
            item_session.set_status(Status.done)
        elif action == Actions.STOP:
            raise HookStop('Script requested immediate stop.')

        return action

def step_size(self, t0, t1=None):
    tb0 = self.to_bucket( t0 )
    if t1:
      tb1 = self.to_bucket( t1, steps=1 ) # NOTE: "end" of second bucket
    else:
      tb1 = self.to_bucket( t0, steps=1 )

    # Calculate the difference in days, then multiply by simple scalar
    days = (self.from_bucket(tb1, native=True) - self.from_bucket(tb0, native=True)).days
    return days * SIMPLE_TIMES['d']

def bin(x, bins, maxX=None, minX=None):
    if maxX is None:
        maxX = x.max()

    if minX is None:
        minX = x.min()

    if not np.iterable(bins):
        bins = np.linspace(minX, maxX+1e-5, bins+1)

    # digitize works on 1d array but not nd arrays.
    # So I pass the flattened version of x and then reshape back into x's original shape
    return np.digitize(x.ravel(), bins).reshape(x.shape), bins

