    nodes = specs['DIMENSION']

    specs['MATRIX'] = {}

    for i in range(nodes):
        specs['MATRIX'][i + 1] = {}

        for j in range(nodes):
            if i > j:
                continue

            specs['MATRIX'][i + 1][j + 1] = int(old_matrix[i][j])

