def Nu_Gupta(Re, Pr, rho_w=None, rho_b=None, mu_w=None, mu_b=None):
    Nu = 0.004*Re**0.923*Pr**0.773
    if rho_w and rho_b:
        Nu *= (rho_w/rho_b)**0.186
    if mu_w and mu_b:
        Nu *= (mu_w/mu_b)**0.366
    return Nu

