def return_attr(self, attr, labels=None):
        all_labels = self.return_label()

        if labels is None:
            labels = all_labels

        all_attr = []
        for one_label in labels:
            idx = all_labels.index(one_label)
            try:
                all_attr.append(self.chan[idx].attr[attr])
            except KeyError:
                possible_attr = ', '.join(self.chan[idx].attr.keys())
                lg.debug('key "{}" not found, '.format(attr) +
                         'possible keys are {}'.format(possible_attr))
                all_attr.append(None)

        return all_attr

def atexit_unregister(func, *args, **kwargs):
    try:
        atexit.unregister(func, *args, **kwargs)
    except AttributeError:
        # This code runs in Python 2.7 *only*
        # Only replace with a noop, don't delete during iteration
        for i in range(len(atexit._exithandlers)):
            if atexit._exithandlers[i] == (func, args, kwargs):
                atexit._exithandlers[i] = (lambda: None, [], {})
                break

def proj_l1(v, gamma, axis=None, method=None):

    if method is None:
        if axis is None:
            method = 'scalarroot'
        else:
            method = 'sortcumsum'

    if method == 'scalarroot':
        if axis is not None:
            raise ValueError('Method scalarroot only supports axis=None')
        return _proj_l1_scalar_root(v, gamma)
    elif method == 'sortcumsum':
        if isinstance(axis, tuple):
            vtr, rsi = ndto2d(v, axis)
            xtr = _proj_l1_sortsum(vtr, gamma, axis=1)
            return ndfrom2d(xtr, rsi)
        else:
            return _proj_l1_sortsum(v, gamma, axis)
    else:
        raise ValueError('Unknown solver method %s' % method)

def _get_url(self, url):
        if self.base_url and not url.startswith(('http://', 'https://')):
            return urljoin(self.base_url, url)
        return url

def _deserialize(self, response):
        # Hacking response with initial status_code
        previous_status = response.status_code
        response.status_code = self.initial_status_code
        resource = self.get_outputs(response)
        response.status_code = previous_status

        # Hack for Storage or SQL, to workaround the bug in the Python generator
        if resource is None:
            previous_status = response.status_code
            for status_code_to_test in [200, 201]:
                try:
                    response.status_code = status_code_to_test
                    resource = self.get_outputs(response)
                except ClientException:
                    pass
                else:
                    return resource
                finally:
                    response.status_code = previous_status
        return resource

def executed_without_callbacks(self):
