def get_SHA1_bin(word):
    from hashlib import sha1
    if PY3 and isinstance(word, str):
        word = word.encode('utf-8')

    hash_s = sha1()
    hash_s.update(word)
    return bin(int(hash_s.hexdigest(), 16))[2:].zfill(160)

