def gauss_noise(dur=None, mu=0., sigma=1.):
  if dur is None or (isinf(dur) and dur > 0):
    while True:
      yield random.gauss(mu, sigma)
  for x in xrange(rint(dur)):
    yield random.gauss(mu, sigma)

