def allow(self, role, method, resource, with_children=True):
        if with_children:
            for r in role.get_children():
                tmp = (r.get_name(), method, resource)
                if tmp not in self._allowed:
                    self._allowed.append(tmp)
        if role == 'anonymous':
            tmp = (role, method, resource)
        else:
            tmp = (role.get_name(), method, resource)
        if tmp not in self._allowed:
