def read_configs_(self):
        if not self.config_files_:
            return {}, [], []
        content = {section: {} for section in self}
        empty_files = []
        faulty_files = []
        for cfile in self.config_files_:
            conf_dict = self.read_config_(cfile)
            if conf_dict is None:
                faulty_files.append(cfile)
                continue
            elif not conf_dict:
                empty_files.append(cfile)
                continue
            for section, secdict in conf_dict.items():
                content[section].update(secdict)
        return content, empty_files, faulty_files

def catch(logger):
    def decorator(func):
        @wraps(func)
        def wrapper(*args, **kwargs):
            try:
                return func(*args, **kwargs)
            except Exception:
                logger.warning(f"Exception raised in decorator: {func.__name__}")

        return wrapper
    return decorator

def replication_state(self, repl_id):
        if "scheduler" in self.client.features():
            try:
                repl_doc = Scheduler(self.client).get_doc(repl_id)
            except HTTPError as err:
                raise CloudantReplicatorException(err.response.status_code, repl_id)
            state = repl_doc['state']
        else:
            try:
                repl_doc = self.database[repl_id]
            except KeyError:
                raise CloudantReplicatorException(404, repl_id)
            repl_doc.fetch()
            state = repl_doc.get('_replication_state')
        return state

def spkcov(spk, idcode, cover=None):
    spk = stypes.stringToCharP(spk)
    idcode = ctypes.c_int(idcode)
    if cover is None:
        cover = stypes.SPICEDOUBLE_CELL(2000)
    else:
        assert isinstance(cover, stypes.SpiceCell)
        assert cover.is_double()
    libspice.spkcov_c(spk, idcode, ctypes.byref(cover))
    return cover

def _raveled_index_for(self, param):
        from ..param import ParamConcatenation
        if isinstance(param, ParamConcatenation):
            return np.hstack((self._raveled_index_for(p) for p in param.params))
        return param._raveled_index() + self._offset_for(param)

