def responds(status=status.HTTP_200_OK,
             meaning='Undocumented status code',
             schema=None,
             schema_name=None,
             **kwargs):
    # TODO: Document syntax in above docstring
    if status is None:
        status = 'default'
    obj = {}
    obj['description'] = meaning

    if schema:
        obj['schema'] = parse_schema(schema)

    if schema_name:
        obj['schema_name'] = schema_name

    obj.update(kwargs)

    def decorator(func):
        # We do not return a decorator function, we just modify
        # in-place our function to have the property that we will look
        # forward later for.
        if not hasattr(func, '_responses'):
            func._responses = {}
        func._responses[status] = obj
        return func
    return decorator

def delaunay2D(plist, mode='xy', tol=None):
    pd = vtk.vtkPolyData()
    vpts = vtk.vtkPoints()
    vpts.SetData(numpy_to_vtk(plist, deep=True))
    pd.SetPoints(vpts)
    delny = vtk.vtkDelaunay2D()
    delny.SetInputData(pd)
    if tol:
        delny.SetTolerance(tol)
    if mode=='fit':
        delny.SetProjectionPlaneMode(vtk.VTK_BEST_FITTING_PLANE)
    delny.Update()
    return Actor(delny.GetOutput())

