def pre(f, *args, **kwargs):
    kwargs.update({'prefix_only': True})
    return _stump(f, *args, **kwargs)

def _apply(self, func, **kwargs):
        blocks, obj, index = self._create_blocks()
        results = []
        for b in blocks:
            try:
                values = self._prep_values(b.values)
            except TypeError:
                results.append(b.values.copy())
                continue

            if values.size == 0:
                results.append(values.copy())
                continue

            # if we have a string function name, wrap it
            if isinstance(func, str):
                cfunc = getattr(libwindow, func, None)
                if cfunc is None:
                    raise ValueError("we do not support this function "
                                     "in libwindow.{func}".format(func=func))

                def func(arg):
                    return cfunc(arg, self.com, int(self.adjust),
                                 int(self.ignore_na), int(self.min_periods))

            results.append(np.apply_along_axis(func, self.axis, values))

        return self._wrap_results(results, blocks, obj)

def unfold_lines(string):
    assert isinstance(string, str), 'Expect str. Got {}'.format(type(string))
    lines = string.splitlines()
    line_buffer = io.StringIO()

    for line_number in range(len(lines)):
        line = lines[line_number]
        if line and line[0:1] in (' ', '\t'):
            line_buffer.write(' ')
        elif line_number != 0:
            line_buffer.write('\r\n')
        line_buffer.write(line.strip())

    line_buffer.write('\r\n')

    return line_buffer.getvalue()

def predict_input(itos_filename, trained_classifier_filename, num_classes=2):
    # Check the itos file exists
    if not os.path.exists(itos_filename):
        print("Could not find " + itos_filename)
        exit(-1)

    # Check the classifier file exists
    if not os.path.exists(trained_classifier_filename):
        print("Could not find " + trained_classifier_filename)
        exit(-1)

    stoi, model = load_model(itos_filename, trained_classifier_filename, num_classes)

    while True:
        text = input("Enter text to analyse (or q to quit): ")
        if text.strip() == 'q':
            break
        else:
            scores = predict_text(stoi, model, text)
            print("Result id {0}, Scores: {1}".format(np.argmax(scores), scores))

def has_perm(self, user_obj, perm, obj=None):
        if settings.PERMISSION_CHECK_PERMISSION_PRESENCE:
            # get permission instance from string permission (perm)
            # it raise ObjectDoesNotExists when the permission is not exists
            try:
                perm_to_permission(perm)
            except AttributeError:
                # Django 1.2 internally use wrong permission string thus ignore
                pass

        # get permission handlers fot this perm
        cache_name = '_%s_cache' % perm
        if hasattr(self, cache_name):
            handlers = getattr(self, cache_name)
        else:
            handlers = [h for h in registry.get_handlers()
                        if perm in h.get_supported_permissions()]
            setattr(self, cache_name, handlers)
        for handler in handlers:
            if handler.has_perm(user_obj, perm, obj=obj):
                return True
        return False

def getNotesForABF(abfFile):
    parent=getParent(abfFile)
    parent=os.path.basename(parent).replace(".abf","")
    expFile=os.path.dirname(abfFile)+"/experiment.txt"
    if not os.path.exists(expFile):
        return "no experiment file"
    with open(expFile) as f:
        raw=f.readlines()
    for line in raw:
        if line[0]=='~':
            line=line[1:].strip()
            if line.startswith(parent):
                while "\t\t" in line:
                    line=line.replace("\t\t","\t")
                line=line.replace("\t","\n")
                return line
    return "experiment.txt found, but didn't contain %s"%parent

