def _get_fd(fileobj):
    if isinstance(fileobj, int):
        fd = fileobj
    else:
        try:
            fd = fileobj.fileno()
        except AttributeError:
            fd = None
    if fd is None or fd < 0:
        raise ValueError("invalid fileobj: {!r}".format(fileobj))
    return fd

def factor_kkt(U_S, R, d):
    nineq = R.size(0)
    U_S[-nineq:, -nineq:] = torch.potrf(R + torch.diag(1 / d.cpu()).type_as(d))

