def realign(self, cut_off, chains_to_skip = set()):
        if cut_off != self.cut_off:
            self.cut_off = cut_off

            # Wipe any existing information for chains not in chains_to_skip
            for c in self.chains:
                if c not in chains_to_skip:
                    self.clustal_matches[c] = None
                    self.substring_matches[c] = None
                    if self.alignment.get(c):
                        del self.alignment[c]
                    if self.seqres_to_uniparc_sequence_maps.get(c):
                        del self.seqres_to_uniparc_sequence_maps[c]

            # Run alignment for the remaining chains
            self._align_with_clustal(chains_to_skip = chains_to_skip)
            self._align_with_substrings(chains_to_skip = chains_to_skip)
            self._check_alignments(chains_to_skip = chains_to_skip)
            self._get_residue_mapping(chains_to_skip = chains_to_skip)

def time_to_run(self, class_, time_):
        app_name = class_.app_name
        try:
            info = self.job_state_database[app_name]
        except KeyError:
            if time_:
                h, m = [int(x) for x in time_.split(':')]
                # only run if this hour and minute is < now
                now = utc_now()
                if now.hour > h:
                    return True
                elif now.hour == h and now.minute >= m:
                    return True
                return False
            else:
                # no past information, run now
                return True
        next_run = info['next_run']

        if not next_run:
            # It has never run before.
            # If it has an active ongoing status it means two
            # independent threads tried to start it. The second one
            # (by a tiny time margin) will have a job_class whose
            # `ongoing` value has already been set.
            # If that's the case, let it through because it will
            # commence and break due to RowLevelLockError in the
            # state's __setitem__ method.
            return bool(info['ongoing'])

        if next_run < utc_now():
            return True
        return False

def _raw_config_setting(config_obj, section, param, default=None, config_filename='', warn_on_none_level=logging.WARN):
    # noinspection PyBroadException
    try:
        return config_obj.get(section, param)
    except:
        if (default is None) and warn_on_none_level is not None:
            # Emit a contextual warning alerting the user that the expected parameter is absent.
            _warn_missing_setting(section, param, config_filename, warn_on_none_level)
        return default

def append_or_dryrun(*args, **kwargs):
    from fabric.contrib.files import append

    dryrun = get_dryrun(kwargs.get('dryrun'))

    if 'dryrun' in kwargs:
        del kwargs['dryrun']

    use_sudo = kwargs.pop('use_sudo', False)

    text = args[0] if len(args) >= 1 else kwargs.pop('text')

    filename = args[1] if len(args) >= 2 else kwargs.pop('filename')

    if dryrun:
        text = text.replace('\n', '\\n')
        cmd = 'echo -e "%s" >> %s' % (text, filename)
        cmd_run = 'sudo' if use_sudo else 'run'
        if BURLAP_COMMAND_PREFIX:
            print('%s %s: %s' % (render_command_prefix(), cmd_run, cmd))
        else:
            print(cmd)
    else:
        append(filename=filename, text=text.replace(r'\n', '\n'), use_sudo=use_sudo, **kwargs)

