def to_dict(self, *, include_keys=None, exclude_keys=None, use_default_excludes=True):
    data = self.__dict__

    if include_keys:
      return pick(data, include_keys, transform=self._other_to_dict)
    else:
      skeys = self.exclude_keys_serialize if use_default_excludes else None
      ekeys = exclude_keys

      return exclude(
        data,
        lambda k: (skeys is not None and k in skeys) or (ekeys is not None and k in ekeys),
        transform=self._other_to_dict)

def _phase_kuramoto(self, teta, t, argv):

        index = argv;   # index of oscillator
        phase = 0.0;      # phase of a specified oscillator that will calculated in line with current env. states.

        neighbors = self.get_neighbors(index);
        for k in neighbors:
            conn_weight = 1.0;
            if (self._ena_conn_weight is True):
                conn_weight = self._conn_weight[index][k];

            phase += conn_weight * self._weight * math.sin(self._phases[k] - teta);

        divider = len(neighbors);
        if (divider == 0):
            divider = 1.0;

        return ( self._freq[index] + (phase / divider) );

