def mag(z):
    if isinstance(z[0], np.ndarray):
        return np.array(list(map(np.linalg.norm, z)))
    else:
        return np.linalg.norm(z)

def resize_max(img, max_side):
    h, w = img.shape[:2]
    if h > w:
        nh = max_side
        nw = w * (nh / h)
    else:
        nw = max_side
        nh = h * (nw / w)

    return cv.resize(img, (nw, nh))

