def get_prime(size=128, rnd=default_crypto_random, k=DEFAULT_ITERATION,
              algorithm=None):
    while True:
        n = rnd.getrandbits(size-2)
        n = 2 ** (size-1) + n * 2 + 1
        if is_prime(n, rnd=rnd, k=k, algorithm=algorithm):
            return n
        if algorithm == 'gmpy-miller-rabin':
            return gmpy.next_prime(n)

