def __verify_minion_publish(self, load):
        # Verify that the load is valid
        if 'peer' not in self.opts:
            return False
        if not isinstance(self.opts['peer'], dict):
            return False
        if any(key not in load for key in ('fun', 'arg', 'tgt', 'ret', 'id')):
            return False
        # If the command will make a recursive publish don't run
        if re.match('publish.*', load['fun']):
            return False
        # Check the permissions for this minion
        perms = []
        for match in self.opts['peer']:
            if re.match(match, load['id']):
                # This is the list of funcs/modules!
                if isinstance(self.opts['peer'][match], list):
                    perms.extend(self.opts['peer'][match])
        if ',' in load['fun']:
            # 'arg': [['cat', '/proc/cpuinfo'], [], ['foo']]
            load['fun'] = load['fun'].split(',')
            arg_ = []
            for arg in load['arg']:
                arg_.append(arg.split())
            load['arg'] = arg_
        return self.ckminions.auth_check(
                perms,
                load['fun'],
                load['arg'],
                load['tgt'],
                load.get('tgt_type', 'glob'),
                publish_validate=True)

def get_found_param(injfile, bankfile, trigfile, param, ifo, args=None):
    foundtmp = injfile["found_after_vetoes/template_id"][:]
    if trigfile is not None:
        # get the name of the ifo in the injection file, eg "detector_1"
        # and the integer from that name
        ifolabel = [name for name, val in injfile.attrs.items() if \
                    "detector" in name and val == ifo][0]
        foundtrg = injfile["found_after_vetoes/trigger_id" + ifolabel[-1]]
    if bankfile is not None and param in bankfile.keys():
        return bankfile[param][:][foundtmp]
    elif trigfile is not None and param in trigfile[ifo].keys():
        return trigfile[ifo][param][:][foundtrg]
    else:
        b = bankfile
        return get_param(param, args, b['mass1'][:], b['mass2'][:],
                                     b['spin1z'][:], b['spin2z'][:])[foundtmp]

def _filter_matching_lines(self, city_name, country, matching):
        result = list()

        # find the right file to scan and extract its lines. Upon "like"
        # matchings, just read all files
        if matching == 'like':
            lines = [l.strip() for l in self._get_all_lines()]
        else:
            filename = self._assess_subfile_from(city_name)
            lines = [l.strip() for l in self._get_lines(filename)]

        # look for toponyms matching the specified city_name and according to
        # the specified matching style
        for line in lines:
            tokens = line.split(",")
            # sometimes city names have an inner comma...
            if len(tokens) == 6:
                tokens = [tokens[0]+','+tokens[1], tokens[2], tokens[3],
                          tokens[4], tokens[5]]
            # check country
            if country is not None:
                if tokens[4] != country:
                    continue

            # check city_name
            if self._city_name_matches(city_name, tokens[0], matching):
                result.append(tokens)

        return result

def glyph_contour_count(font, name):
    contour_count = 0
    items = [font['glyf'][name]]

    while items:
        g = items.pop(0)
        if g.isComposite():
            for comp in g.components:
                if comp.glyphName != ".ttfautohint":
                    items.append(font['glyf'][comp.glyphName])
        if g.numberOfContours != -1:
            contour_count += g.numberOfContours
    return contour_count

