                    self._c_type_name(name), name
                )
                for name, dummy_args in self.funcs
            ]
        if self.opts.windll:
            return ''
        return [
            '{} _{} = {{ 0 }};\n'.format(
                self._c_struct_names()[1], self.name
            )
        ]

