def _populate_trie_reducer(self, trie_accumulator=CharTrie(), value="") -> CharTrie:
        if self._case_sensitive:
            key = self._joiner.join([x.orth_ if isinstance(x, Token) else x for x in
                                     self._default_tokenizer.tokenize(value, disable=disable_spacy)])
        else:
            key = self._joiner.join([x.lower_ if isinstance(x, Token) else x.lower() for x in
                                     self._default_tokenizer.tokenize(value, disable=disable_spacy)])
        trie_accumulator[key] = value
        # Return the updated trie accumulator to continue the reduction process.
        return trie_accumulator

def jboss_home(broker):
        ps = broker[DefaultSpecs.ps_auxww].content
        results = []
        findall = re.compile(r"\-Djboss\.home\.dir=(\S+)").findall
        # JBoss progress command content should contain jboss.home.dir
        # and any of string ['-D[Standalone]', '-D[Host Controller]', '-D[Server:']
        for p in ps:
            if any(i in p for i in ['-D[Standalone]', '-D[Host Controller]', '-D[Server:']):
                found = findall(p)
                if found:
                    # Only get the path which is absolute
                    results.extend(f for f in found if f[0] == '/')
        return list(set(results))

def draw_image(self, image, xmin=0, ymin=0, xmax=None, ymax=None):
        if xmax is None:
            xmax = xmin + image.size[0]
        if ymax is None:
            ymax = ymin + image.size[1]
        self.bitmap_list.append({'image': image,
                                 'xmin': xmin,
                                 'xmax': xmax,
                                 'ymin': ymin,
                                 'ymax': ymax})
        # Set limits unless lower/higher limits are already set.
        xmin = min(x for x in (xmin, self.limits['xmin'])
                   if x is not None)
        ymin = min(y for y in (ymin, self.limits['ymin'])
                   if y is not None)
        xmax = max(x for x in (xmax, self.limits['xmax'])
                   if x is not None)
        ymax = max(y for y in (ymax, self.limits['ymax'])
                   if y is not None)
        self.set_xlimits(xmin, xmax)
        self.set_ylimits(ymin, ymax)

def update(self, *others):
