def sanitize_qualifiers(repos=None, followers=None, language=None):
    qualifiers = ''

    if repos:
        qualifiers += 'repos:{0} '.format(repos)
        qualifiers = re.sub(r"([+])([=a-zA-Z0-9]+)", r">\2", qualifiers)
        qualifiers = re.sub(r"([-])([=a-zA-Z0-9]+)", r"<\2", qualifiers)

    if followers:
        qualifiers += 'followers:{0} '.format(followers)
        qualifiers = re.sub(r"([+])([=a-zA-Z0-9]+)", r">\2", qualifiers)
        qualifiers = re.sub(r"([-])([=a-zA-Z0-9]+)", r"<\2", qualifiers)

    try:
        if language in ALLOWED_LANGUAGES and not language == '':
            qualifiers += 'language:{0} '.format(language)
        elif language == '':
            qualifiers += ''
        else:
            raise AllowedLanguagesException
    except AllowedLanguagesException as e:
        print(e)

    return qualifiers

def set_from_descendants(self, descendants):
        for field in self.fields:

            # This gives a set of metadata values of all the parents
            # of any new cluster.
            candidates = defaultdict(set)
            for old, new in descendants:
                candidates[new].add(self.get(field, old))

            # Loop over all new clusters.
            for new, vals in candidates.items():
                vals = list(vals)
                default = self._fields[field]
                # If all the parents have the same value, assign it to
                # the new cluster if it is not the default.
                if len(vals) == 1 and vals[0] != default:
                    self.set(field, new, vals[0])

