def concentric_rectangle_path(size):

    def conc_rect_iter():
        for x in range(min_x, max_x):
            yield (x, min_y)
        # if rectangle only has height of 1, prevent path from doubling back along x
        if min_y + 1 == max_y:
            return
        for y in range(min_y + 1, max_y):
            yield (max_x - 1, y)
        for x in range(max_x - 2, min_x - 1, -1):
            yield (x, max_y - 1)
        for y in range(max_y - 2, min_y, -1):
            yield (min_x, y)

    width, height = size
    min_x, max_x = 0, width
    min_y, max_y = 0, height

    while min_x < max_x and min_y < max_y:
        yield conc_rect_iter()

        min_x += 1
        min_y += 1
        max_x -= 1
        max_y -= 1

def _sample_rows(self, X, Y, sample_shape, seed):
        if sample_shape[0] is None or X.shape[0] <= sample_shape[0]:
            X_sample, Y_sample = X, Y
        elif Y is None:
            np.random.seed(seed)
            row_indices = np.random.choice(
                X.shape[0], size=sample_shape[0], replace=False
            )
            X_sample, Y_sample = X.iloc[row_indices], Y
        else:
            drop_size = X.shape[0] - sample_shape[0]
            sample_size = sample_shape[0]
            sss = StratifiedShuffleSplit(
                n_splits=2, test_size=drop_size, train_size=sample_size, random_state=seed
            )
            row_indices, _ = next(sss.split(X, Y))
            X_sample, Y_sample = X.iloc[row_indices], Y.iloc[row_indices]
        return (X_sample, Y_sample)

def get_stops_in_polygon(
    feed: "Feed", polygon: Polygon, geo_stops=None
) -> DataFrame:
    if geo_stops is not None:
        f = geo_stops.copy()
    else:
        f = geometrize_stops(feed.stops)

    cols = f.columns
    f["hit"] = f["geometry"].within(polygon)
    f = f[f["hit"]][cols]
    return ungeometrize_stops(f)

