def pylint_amnesty(pylint_output):
    errors = defaultdict(lambda: defaultdict(set))
    for pylint_error in parse_pylint_output(pylint_output):
        errors[pylint_error.filename][pylint_error.linenum].add(pylint_error)

    for file_with_errors in sorted(errors):
        try:
            opened_file = open(file_with_errors)
        except IOError:
            LOG.warning(u"Unable to open %s for edits", file_with_errors, exc_info=True)
        else:
            with opened_file as input_file:
                output_lines = []
                for line_num, line in enumerate(input_file, start=1):
                    output_lines.extend(
                        fix_pylint(
                            line,
                            errors[file_with_errors][line_num]
                        )
                    )

            with open(file_with_errors, 'w') as output_file:
                output_file.writelines(output_lines)

def get_stream(self, bucket, label, as_stream=True):
        if self.mode == "w":
            raise OFSException("Cannot read from archive in 'w' mode")
        elif self.exists(bucket, label):
            fn = self._zf(bucket, label)
            if as_stream:
                return self.z.open(fn)
            else:
                return self.z.read(fn)
        else:
            raise OFSFileNotFound

def clean_address(address):
    if isinstance(address, header.Header):
        return clean_address(address.encode('ascii'))

    elif isinstance(address, str):
        address = address.replace("<", "")
        address = address.replace(">", "")
        address = address.replace("\"", "")
        address = address.replace("\n", " ")
        address = address.replace("MAILER-DAEMON", "")
        address = address.lower().strip()

        email = None
        for word in address.split(' '):
            email_regex = re.compile(
                "^[a-zA-Z0-9._%-]+@[a-zA-Z0-9._%-]+.[a-zA-Z]{2,6}$"
                )
            email = re.match(email_regex, word)
            if email is not None:
                clean_email = email.group(0)
        if email is None:
            if address.split(' ')[-1].find('@') > -1:
                clean_email = address.split(' ')[-1].strip()
            elif address.split(' ')[-1].find('?') > -1:
                clean_email = 'n/a'
            else:
                clean_email = address

        return clean_email

    elif address is None:
        return None

    else:
        raise ValueError('An unexpected type was given to clean_address. Address was {}'.format(address))
        return None

def rest_name(cls):
