def get_config_var_entry(self, index):

        if index == 0 or index > len(self.config_database.entries):
            return [Error.INVALID_ARRAY_KEY, 0, 0, 0, b'\0'*8, 0, 0]

        entry = self.config_database.entries[index - 1]
        if not entry.valid:
            return [ConfigDatabaseError.OBSOLETE_ENTRY, 0, 0, 0, b'\0'*8, 0, 0]

        offset = sum(x.data_space() for x in self.config_database.entries[:index - 1])
        return [Error.NO_ERROR, self.config_database.ENTRY_MAGIC, offset, entry.data_space(), entry.target.encode(), 0xFF, 0]

def fost_hmac_url_signature(
    key, secret, host, path, query_string, expires):
    if query_string:
        document = '%s%s?%s\n%s' % (host, path, query_string, expires)
    else:
        document = '%s%s\n%s' % (host, path, expires)
    signature = sha1_hmac(secret, document)
    return signature

def local_maxima(vector,min_distance = 4, brd_mode = "wrap"):
    fits = gaussian_filter(numpy.asarray(vector,dtype=numpy.float32),1., mode=brd_mode)
    for ii in range(len(fits)):
        if fits[ii] == fits[ii-1]:
            fits[ii-1] = 0.0
    maxfits     = maximum_filter(fits, size=min_distance, mode=brd_mode)
    maxima_mask = fits == maxfits
    maximum     = numpy.transpose(maxima_mask.nonzero())
    return numpy.asarray(maximum)

