def del_data(name=None):
    if name is None:
        tplot_names = list(data_quants.keys())
        for i in tplot_names:
            del data_quants[i]
        return

    if not isinstance(name, list):
        name = [name]

    entries = []  
    ###    
    for i in name:
        if ('?' in i) or ('*' in i):
            for j in data_quants.keys():
                var_verif = fnmatch.fnmatch(data_quants[j].name, i)
                if var_verif == 1:
                    entries.append(data_quants[j].name)
                else:
                    continue
            for key in entries:
                if key in data_quants:
                    del data_quants[key]       
    ###            
        elif i not in data_quants.keys():
            print(str(i) + " is currently not in pytplot.")
            return

        else:
            temp_data_quants = data_quants[i]
            str_name = temp_data_quants.name

            del data_quants[str_name]

    # Return control to the caller to conclude the function execution.
    return

def _validate_value(self, proposal):
        value = proposal['value']
        if self.base ** self.min > value or self.base ** self.max < value:
            value = min(max(value, self.base **  self.min), self.base **  self.max)
        return value

