def create(rawmessage):
    rawmessage = _trim_buffer_garbage(rawmessage)

    if len(rawmessage) < 2:
        return (None, rawmessage)

    code = rawmessage[1]
    msgclass = _get_msg_class(code)

    msg = None

    remaining_data = rawmessage
    if msgclass is None:
        _LOGGER.debug('Did not find message class 0x%02x', rawmessage[1])
        rawmessage = rawmessage[1:]
        rawmessage = _trim_buffer_garbage(rawmessage, False)
        if rawmessage:
            _LOGGER.debug('Create: %s', create)
            _LOGGER.debug('rawmessage: %s', binascii.hexlify(rawmessage))
            msg, remaining_data = create(rawmessage)
        else:
            remaining_data = rawmessage
    else:
        if iscomplete(rawmessage):
            msg = msgclass.from_raw_message(rawmessage)
            if msg:
                remaining_data = rawmessage[len(msg.bytes):]
    # _LOGGER.debug("Returning msg: %s", msg)
    # _LOGGER.debug('Returning buffer: %s', binascii.hexlify(remaining_data))
    return (msg, remaining_data)

def preprocess_xarray(func):
    @functools.wraps(func)
    def wrapper(*args, **kwargs):
        args = tuple(a.metpy.unit_array if isinstance(a, xr.DataArray) else a for a in args)
        kwargs = {name: (v.metpy.unit_array if isinstance(v, xr.DataArray) else v)
                  for name, v in kwargs.items()}
        return func(*args, **kwargs)
    return wrapper

def certify_email(value, required=True):
    certify_required(
        value=value,
        required=required,
    )
    certify_string(value, min_length=3, max_length=320)

    try:
        certification_result = email_validator.validate_email(
            value,
            check_deliverability=False,
        )
    except email_validator.EmailNotValidError as ex:
        six.raise_from(
            CertifierValueError(
                message="{value!r} is not a valid email address: {ex}".format(
                    value=value,
                    # email_validator returns unicode characters in exception string
                    ex=six.u(repr(ex))
                ),
                value=value,
                required=required,
            ),
            ex
        )
    else:
        if certification_result['email'] != value:
            raise CertifierValueError(
                message="{value!r} is not normalized, should be {normalized!r}".format(
                    value=value, normalized=certification_result['email']),
                value=value,
                required=required,
            )

