def last(iterable, default=_marker):
    try:
        try:
            # Try to access the last item directly
            return iterable[-1]
        except (TypeError, AttributeError, KeyError):
            # If not slice-able, iterate entirely using length-1 deque
            return deque(iterable, maxlen=1)[0]
    except IndexError:  # If the iterable was empty
        if default is _marker:
            raise ValueError('last() was called on an empty iterable, and no '
                             'default value was provided.')
        return default

def _wrap_layer(name, input_layer, build_func, dropout_rate=0.0, trainable=True):
    build_output = build_func(input_layer)
    if dropout_rate > 0.0:
        dropout_layer = keras.layers.Dropout(
            rate=dropout_rate,
            name='%s-Dropout' % name,
        )(build_output)
    else:
        dropout_layer = build_output
    if isinstance(input_layer, list):
        input_layer = input_layer[0]
    add_layer = keras.layers.Add(name='%s-Add' % name)([input_layer, dropout_layer])
    normal_layer = LayerNormalization(
        trainable=trainable,
        name='%s-Norm' % name,
    )(add_layer)
    return normal_layer

