def getGyroData(self):
        x = self._readWord(self.REG_GYRO_XOUT_H)
        y = self._readWord(self.REG_GYRO_YOUT_H)
        z = self._readWord(self.REG_GYRO_ZOUT_H)

        gyro_scale_modifier = None
        gyro_range = self.readGyroRange()

        if gyro_range == self.GYRO_RANGE_250DEG:
            gyro_scale_modifier = self.GYRO_SCALE_MODIFIER_250DEG
        elif gyro_range == self.GYRO_RANGE_500DEG:
            gyro_scale_modifier = self.GYRO_SCALE_MODIFIER_500DEG
        elif gyro_range == self.GYRO_RANGE_1KDEG:
            gyro_scale_modifier = self.GYRO_SCALE_MODIFIER_1KDEG
        elif gyro_range == self.GYRO_RANGE_2KDEG:
            gyro_scale_modifier = self.GYRO_SCALE_MODIFIER_2KDEG
        else:
            print("ERROR: Unkown gyroscope range!")
            return False
            #gyro_scale_modifier = self.GYRO_SCALE_MODIFIER_250DEG

        x = x / gyro_scale_modifier
        y = y / gyro_scale_modifier
        z = z / gyro_scale_modifier
        return {'x': x, 'y': y, 'z': z}

def push_token(self, tok):
        if self.debug >= 1:
            print("shlex: pushing token " + repr(tok))
        self.pushback.appendleft(tok)

def compare_contract_versions(
        proxy: ContractProxy,
        expected_version: str,
        contract_name: str,
        address: Address,
) -> None:
    assert isinstance(expected_version, str)
    try:
        deployed_version = proxy.contract.functions.contract_version().call()
    except BadFunctionCallOutput:
        raise AddressWrongContract('')

    deployed_version = deployed_version.replace('_', '0')
    expected_version = expected_version.replace('_', '0')

    deployed = [int(x) for x in deployed_version.split('.')]
    expected = [int(x) for x in expected_version.split('.')]

    if deployed != expected:
        raise ContractVersionMismatch(
            f'Provided {contract_name} contract ({to_normalized_address(address)}) '
            f'version mismatch. Expected: {expected_version} Got: {deployed_version}',
        )

def geturl(self):
        return urlparse.urlunparse((
            self.scheme,
            self.netloc,
            self.path,
