def find_branches(self, labels=False, unique=False):

        branches = []

        # Assign proper item, pointer or label, to return
        if labels is True:
            identifier = [self.label]
        else:
            identifier = [self]

        if self._children == []:  # Base Case: current node is a leaf/end node
            return identifier

        else:  # Recursive Case: all other nodes
            for child in self._children:
                if unique is True:
                    for branch in child.find_branches(labels=labels,
                                                      unique=True):
                        # I don't know why this 'if' is necessary, but it is
                        if type(branch) is not list:
                            branch = list(branch)
                        branches.append(identifier + branch)
                else:
                    branches.append(child.find_branches(labels=labels))

            # Proper construction of list depends on 'unique'
            if unique is True:
                return branches
            else:
                return identifier + branches

def install(pecls, defaults=False, force=False, preferred_state='stable'):
    if isinstance(pecls, six.string_types):
        pecls = [pecls]
    preferred_state = '-d preferred_state={0}'.format(_cmd_quote(preferred_state))
    if force:
        return _pecl('{0} install -f {1}'.format(preferred_state, _cmd_quote(' '.join(pecls))),
                     defaults=defaults)
    else:
        _pecl('{0} install {1}'.format(preferred_state, _cmd_quote(' '.join(pecls))),
              defaults=defaults)
        if not isinstance(pecls, list):
            pecls = [pecls]
        for pecl in pecls:
            found = False
            if '/' in pecl:
                channel, pecl = pecl.split('/')
            else:
                channel = None
            installed_pecls = list_(channel)
            for pecl in installed_pecls:
                installed_pecl_with_version = '{0}-{1}'.format(
                    pecl,
                    installed_pecls.get(pecl)[0]
                )
                if pecl in installed_pecl_with_version:
                    found = True
            if not found:
                return False
        return True

