def cited_names_from_aux_file(stream):
    cited = set()

    for line in stream:
        if not line.startswith(r'\citation{'):
            continue

        line = line.rstrip()
        if line[-1] != '}':
            # Skip this line because it lacks the required closing brace.
            continue # should issue a warning or something

        entries = line[10:-1]

        for name in entries.split(','):
            name = name.strip()

            if name not in cited:
                yield name
                cited.add(name)

def _write(self, command, future):

