async def _unsubscribe(self, channels, is_mask):
        vanished = []
        if channels:
            for channel in channels:
                key = channel, is_mask
                self._channels.remove(key)
                self._plugin._subscriptions[key].remove(self._queue)
                if not self._plugin._subscriptions[key]:  # we were last sub?
                    vanished.append(channel)
                    del self._plugin._subscriptions[key]
        else:
            while self._channels:
                channel, is_mask = key = self._channels.pop()
                self._plugin._subscriptions[key].remove(self._queue)
                if not self._plugin._subscriptions[key]:
                    vanished.append(channel)
                    del self._plugin._subscriptions[key]
        if vanished:
            await getattr(self._sub, 'punsubscribe' if is_mask else 'unsubscribe')(vanished)

def restoreValue(self, xelem):
        typ = xelem.get('type')

        if typ == 'color':
            return QtGui.QColor(xelem.text)

        elif typ == 'point':
            return QtCore.QPoint(*map(int, xelem.text.split(',')))

        elif typ == 'pointf':
            return QtCore.QPointF(*map(float, xelem.text.split(',')))

        elif typ == 'rect':
            return QtCore.QRectF(*map(int, xelem.text.split(',')))

        elif typ == 'rectf':
            return QtCore.QRectF(*map(float, xelem.text.split(',')))

        elif typ == 'bytea':
            return QtCore.QByteArray(cPickle.loads(xelem.text))

        elif typ == 'pickle':
            return cPickle.loads(xelem.text)

        elif typ == 'xml':
            return xelem[0]

        elif typ in ('str', 'unicode'):
            return xelem.text

        else:
            try:
                return eval('{0}({1})'.format(typ, xelem.text))
            except:
                return None

