def extract_opts(**opts):
    values = {}
    for opt, init in opts.items():
        try:
            idx = sys.argv.index('-%s' % opt)
        except ValueError:
            continue
        if idx+1 < len(sys.argv):
            opts[opt] = sys.argv.pop(idx+1)

        sys.argv.pop(idx)

    return opts

def lifting_condensation_level(T, RH):
    Tadj = T-55.  # in Kelvin
    return cp/g*(Tadj - (1/Tadj - log(RH)/2840.)**(-1))

def mosaic_coverages(self, store):
        params = dict()
        url = build_url(
            self.service_url,
            [
                "workspaces",
                store.workspace.name,
                "coveragestores",
                store.name,
                "coverages.json"
