def count(self, **kwargs):
        if self._is_transposed:
            kwargs["axis"] = kwargs.get("axis", 0) ^ 1
            return self.transpose().count(**kwargs)
        axis = kwargs.get("axis", 0)
        map_func = self._build_mapreduce_func(pandas.DataFrame.count, **kwargs)
        reduce_func = self._build_mapreduce_func(pandas.DataFrame.sum, **kwargs)
        return self._full_reduce(axis, map_func, reduce_func)

def since(self, timestamp=None, version=None, deleted=False):

        qset = self

        if timestamp is not None:

            if isinstance(timestamp, numbers.Real):
                timestamp = datetime.datetime.fromtimestamp(timestamp)

            qset = qset.filter(
                models.Q(created__gt=timestamp) |
                models.Q(updated__gt=timestamp)
            )

        if version is not None:

            qset = qset.filter(version__gt=version)

        if not deleted:

            qset = qset.undeleted()

        return qset

def create_circuit_provider(name, asn=None):

    nb_circuit_provider = get_('circuits', 'providers', name=name)
    payload = {}
    if nb_circuit_provider:
        if nb_circuit_provider['asn'] == asn:
            return False
        else:
            log.error('Duplicate provider with different ASN: %s: %s', name, asn)
            raise CommandExecutionError(
                'Duplicate provider with different ASN: {}: {}'.format(name, asn)
            )
    else:
        payload = {
            'name': name,
            'slug': slugify(name)
        }
        if asn:
            payload['asn'] = asn
        circuit_provider = _add('circuits', 'providers', payload)
        if circuit_provider:
            return {'circuits': {'providers': {circuit_provider['id']: payload}}}
        else:
            return circuit_provider

def extract_files(params):
    files = {}
    updated_params = {}
    for name in params:
        if name == "photo" and params[name].startswith("@"):
            filename = params[name][1:]

            # Python2 uses encoded commandline parameters.
            # Decode to Unicode if necessary.
            if isinstance(filename, bytes):
                filename = filename.decode(sys.getfilesystemencoding())

            files[name] = open(os.path.expanduser(filename), 'rb')
        else:
            updated_params[name] = params[name]

    return updated_params, files

def from_yaml(cls, file_path=None):
        try:
            import yaml
        except ImportError:  # pragma: no cover
            yaml = None
        if not yaml:
            import sys
            sys.exit('PyYAML is not installed, but is required in order to parse YAML files.'
                     '\nTo install, run:\n$ pip install PyYAML\nor visit'
                     ' http://pyyaml.org/wiki/PyYAML for instructions.')

        with io.open(file_path, encoding=text_type('utf-8')) as stream:
            users_yaml = yaml.safe_load(stream)
            if isinstance(users_yaml, dict):
                return cls.construct_user_list(raw_users=users_yaml.get('users'))
            else:
                raise ValueError('No YAML object could be decoded')

def embedding_to_padding(emb):
  emb_sum = tf.reduce_sum(tf.abs(emb), axis=-1, keep_dims=True)
