def accept_format(*, version: str = "v3", media: Optional[str] = None,
                  json: bool = True) -> str:
    # https://developer.github.com/v3/media/
    # https://developer.github.com/v3/#current-version
    accept = f"application/vnd.github.{version}"
    if media is not None:
        accept += f".{media}"
    if json:
        accept += "+json"
    return accept

