def human_date_to_datetime(self, time_input, tz=None, source_datetime=None):

        c = pdt.Constants('en')
        cal = pdt.Calendar(c)
        # cal = pdt.Calendar(version=pdt.VERSION_CONTEXT_STYLE)
        tzinfo = None
        src_tzname = None
        if source_datetime is not None:
            tzinfo = source_datetime.tzinfo
            src_tzname = source_datetime.tzname()
        try:
            dt, status = cal.parseDT(time_input, sourceTime=source_datetime, tzinfo=tzinfo)
            if tz is not None:  # don't add tz if no tz value is passed
                if dt.tzinfo is None:
                    dt = self._replace_timezone(dt)
                # don't covert timezone if source timezone already in the correct timezone
                if tz != src_tzname:
                    dt = dt.astimezone(timezone(tz))
            if status == 0:
                dt = None
        except TypeError:
            dt = None

        return dt

def _StopFolderSelectionMethod(self, stop_folder):
    if not self.show_stop_hierarchy:
      return lambda stop: (stop_folder, None)

    # Create the various sub-folders for showing the stop hierarchy
    station_folder = self._CreateFolder(stop_folder, 'Stations')
    platform_folder = self._CreateFolder(stop_folder, 'Platforms')
    platform_connections = self._CreateFolder(platform_folder, 'Connections')
    entrance_folder = self._CreateFolder(stop_folder, 'Entrances')
    entrance_connections = self._CreateFolder(entrance_folder, 'Connections')
    standalone_folder = self._CreateFolder(stop_folder, 'Stand-Alone')

    def FolderSelectionMethod(stop):
      if stop.location_type == transitfeed.Stop.LOCATION_TYPE_STATION:
        return (station_folder, None)
      elif stop.location_type == googletransit.Stop.LOCATION_TYPE_ENTRANCE:
        return (entrance_folder, entrance_connections)
      elif stop.parent_station:
        return (platform_folder, platform_connections)
      return (standalone_folder, None)

    return FolderSelectionMethod

def _decode_attribute(self, s):
        _, v = s.split(' ', 1)
        v = v.strip()

        # Verify the general structure of declaration
        m = _RE_ATTRIBUTE.match(v)
        if not m:
            raise BadAttributeFormat()

        # Extracts the raw name and type
        name, type_ = m.groups()

        # Extracts the final name
        name = unicode(name.strip('"\''))

        # Extracts the final type
        if _RE_TYPE_NOMINAL.match(type_):
            try:
                type_ = _parse_values(type_.strip('{} '))
            except Exception:
                raise BadAttributeType()
            if isinstance(type_, dict):
                raise BadAttributeType()

        else:
            # If not nominal, verify the type name
            type_ = unicode(type_).upper()
            if type_ not in ['NUMERIC', 'REAL', 'INTEGER', 'STRING']:
                raise BadAttributeType()

        return (name, type_)

