def __set_opacity(self):

        if self.__vector > 0:
            if self.isHidden():
                self.show()
            if self.opacity <= self.__target_opacity:
                self.opacity += self.__vector
            else:
                self.__timer.stop()
                self.faded_in.emit()
                self.__duration and QTimer.singleShot(self.__duration, self.__fade_out)
        elif self.__vector < 0:
            if self.opacity > 0:
                self.opacity += self.__vector
            else:
                self.__timer.stop()
                self.faded_out.emit()
                self.hide()

def safe_args(args,
              options,
              max_args=None,
              argfile=None,
              delimiter='\n',
              quoter=None,
              delete=True):
  max_args = max_args or options.max_subprocess_args
  if len(args) > max_args:
    def create_argfile(f):
      logger.debug('Creating argfile {} with contents {}'.format(f.name, ' '.join(args)))
      f.write(delimiter.join(args))
      f.close()
      return [quoter(f.name) if quoter else '@{}'.format(f.name)]

    if argfile:
      try:
        with safe_open(argfile, 'w') as fp:
          yield create_argfile(fp)
      finally:
        if delete and os.path.exists(argfile):
          os.unlink(argfile)
    else:
      with temporary_file(cleanup=delete, binary_mode=False) as fp:
        yield create_argfile(fp)
  else:
    yield args

def num_nodes(self, leaves=True, internal=True):
        if not isinstance(leaves, bool):
            raise TypeError("leaves must be a bool")
        if not isinstance(internal, bool):
            raise TypeError("internal must be a bool")
        num = 0
        for node in self.traverse_preorder():
            if (leaves and node.is_leaf()) or (internal and not node.is_leaf()):
                num += 1
        return num

def parse_motion_state(val):
        number = val & 0b00111111
        unit = (val & 0b11000000) >> 6
        if unit == 1:
            number *= 60 # minutes
        elif unit == 2:
            number *= 60 * 60 # hours
        elif unit == 3 and number < 32:
            number *= 60 * 60 * 24 # days
        elif unit == 3:
            number -= 32
            number *= 60 * 60 * 24 * 7 # weeks
        return number

