def should_close(self):
        if self.headers.get('connection') == 'close':
            return True
        elif 'content-length' in self.headers or \
            self.headers.get('METHOD') in ['HEAD', 'GET']:
            return self.headers.get('connection') != 'keep-alive'
        elif self.headers.get('VERSION') == 'HTTP/1.0':
            return True
        else:
            return False

def max_width(*args, **kwargs):
    args = list(args)

    if not args:
        args.append(kwargs.get('string'))
        args.append(kwargs.get('cols'))
        args.append(kwargs.get('separator'))
    elif len(args) == 1:
        args.append(kwargs.get('cols'))
        args.append(kwargs.get('separator'))
    elif len(args) == 2:
        args.append(kwargs.get('separator'))

    string, cols, separator = args
    if separator is None:
        separator = '\n'  # default value
    if cols is None:
        # cols should be specified vitally
        # because string can be specified at textui:puts function
        string, cols = cols, string

    if string is None:
        MAX_WIDTHS.append((cols, separator))
        return _max_width_context()
    else:
        return _max_width_formatter(string, cols, separator)

def x(*args, **kwargs):
    with Reflect.context(args, **kwargs) as r:
        instance = V_CLASS(r, stream, **kwargs)
        if args:
            instance()

        else:
            instance.writelines([
                'exit at line {}\n'.format(instance.reflect.info["line"]),
                instance.path_value()
            ])

    exit_code = 1
    sys.exit(exit_code)

def to_networkx(cyjs, directed=True):

    if directed:
        g = nx.MultiDiGraph()
    else:
        g = nx.MultiGraph()

    network_data = cyjs[DATA]
    if network_data is not None:
        for key in network_data.keys():
            g.graph[key] = network_data[key]

    nodes = cyjs[ELEMENTS][NODES]
    edges = cyjs[ELEMENTS][EDGES]

    for node in nodes:
        data = node[DATA]
        g.add_node(data[ID], attr_dict=data)

    for edge in edges:
        data = edge[DATA]
        source = data[SOURCE]
        target = data[TARGET]

        g.add_edge(source, target, attr_dict=data)

    return g

def hasFeature(self, prop, check_softs=False):

        return prop in self.props or (check_softs and
