def _convert_to_hashable(data, types=True):
    # HANDLE MOST COMMON TYPES FIRST
    if data is None:
        hashable = b'NONE'
        prefix = b'NULL'
    elif isinstance(data, six.binary_type):
        hashable = data
        prefix = b'TXT'
    elif isinstance(data, six.text_type):
        # convert unicode into bytes
        hashable = data.encode('utf-8')
        prefix = b'TXT'
    elif isinstance(data, _intlike):
        # warnings.warn('Hashing ints is slow, numpy is prefered')
        hashable = _int_to_bytes(data)
        # hashable = data.to_bytes(8, byteorder='big')
        prefix = b'INT'
    elif isinstance(data, float):
        a, b = float(data).as_integer_ratio()
        hashable = _int_to_bytes(a) + b'/' +  _int_to_bytes(b)
        prefix = b'FLT'
    else:
        # Then dynamically look up any other type
        hash_func = _HASHABLE_EXTENSIONS.lookup(data)
        prefix, hashable = hash_func(data)
    if types:
        return prefix, hashable
    else:
        return b'', hashable

def readByteArray(self):
        ref = self.readInteger(False)

        if ref & REFERENCE_BIT == 0:
            return self.context.getObject(ref >> 1)

        buffer = self.stream.read(ref >> 1)

        try:
            buffer = zlib.decompress(buffer)
            compressed = True
        except zlib.error:
            compressed = False

        obj = ByteArray(buffer)
        obj.compressed = compressed

        self.context.addObject(obj)

        return obj

def decode(self, pdu):
        if _debug: BVLCI._debug("decode %s", str(pdu))

        # copy the basics
        PCI.update(self, pdu)

        self.bvlciType = pdu.get()
        if self.bvlciType != 0x81:
            raise DecodingError("invalid BVLCI type")

        self.bvlciFunction = pdu.get()
        self.bvlciLength = pdu.get_short()

        if (self.bvlciLength != len(pdu.pduData) + 4):
            raise DecodingError("invalid BVLCI length")

def store_last_browsed_path(data):

    if type(data) in (tuple, list, QStringList):
        data = [foundations.strings.to_string(path) for path in data]
        last_browsed_path = foundations.common.get_first_item(data)
    elif type(data) in (unicode, QString):
        data = last_browsed_path = foundations.strings.to_string(data)
    else:
        raise TypeError("{0} | '{1}' type is not supported!".format(__name__, type(data)))

    if foundations.common.path_exists(last_browsed_path):
        last_browsed_path = os.path.normpath(last_browsed_path)
        if os.path.isfile(last_browsed_path):
            last_browsed_path = os.path.dirname(last_browsed_path)

        LOGGER.debug("> Storing last browsed path: '%s'.", last_browsed_path)
        RuntimeGlobals.last_browsed_path = last_browsed_path
    return data

