def clean_single_dict(indict, prepend_to_keys=None, remove_keys_containing=None):
    if not prepend_to_keys:
        prepend_to_keys = ''

    outdict = {}
    for k, v in indict.items():
        if remove_keys_containing:
            if remove_keys_containing in k:
                continue
        outdict[prepend_to_keys + k] = v[0]

    return outdict

def write(self, title, data, output=None):
        if not isinstance(data, (dict, list, tuple)):
            data = {'raw-content': str(data)}
        output = output or self.__default_outputter

        if output != 'null':
            try:
                if isinstance(data, dict) and 'return' in data:
                    data = data['return']
                content = self._printout(data, output)
            except Exception:  # Fall-back to just raw YAML
                # Reset content to None to trigger the YAML fallback serialization path.
                content = None
        else:
            content = None

        if content is None:
            data = json.loads(json.dumps(data))
            if isinstance(data, dict) and data.get('return'):
                data = data.get('return')
            content = yaml.safe_dump(data, default_flow_style=False, indent=4)

        self.__current_section.append({title: content})

def compare_version(version1, version2):
    def normalize(v):
        return [int(x) for x in re.sub(r'(\.0+)*$','', v).split(".")]
    return (normalize(version1) > normalize(version2))-(normalize(version1) < normalize(version2))

