def display_manager(display):
    from contextlib import contextmanager

    @contextmanager
    def manager():
        errors = []

        def handler(*args):
            errors.append(args)

        old_handler = display.set_error_handler(handler)
        yield display
        display.sync()
        display.set_error_handler(old_handler)
        if errors:
            raise X11Error(errors)

    return manager()

def on_message(self, message):
        if self.ws.closed:
            return None
        try:
            safe_call(self.logger.debug, '< %s %r', self, message)

            # process individual messages
            for data in self.ddp_frames_from_message(message):
                self.process_ddp(data)
                # emit request_finished signal to close DB connections
                signals.request_finished.send(sender=self.__class__)
        except geventwebsocket.WebSocketError:
            self.ws.close()

def infer_typing_typevar_or_newtype(node, context=None):
    try:
        func = next(node.func.infer(context=context))
    except InferenceError as exc:
        raise UseInferenceDefault from exc

    if func.qname() not in TYPING_TYPEVARS_QUALIFIED:
        raise UseInferenceDefault
    if not node.args:
        raise UseInferenceDefault

    typename = node.args[0].as_string().strip("'")
    node = extract_node(TYPING_TYPE_TEMPLATE.format(typename))
    return node.infer(context=context)

