def clampValues(self,timePoint=0):
        Cs=np.zeros(self.sweeps)
        for i in range(self.sweeps):
            self.setSweep(i) #TODO: protocol only = True
            for j in range(len(self.protoSeqX)):
                if self.protoSeqX[j]<=timePoint*self.rate:
                    Cs[i]=self.protoSeqY[j]
        return Cs

def count(self, level=None):
        if level is None:
            return notna(com.values_from_object(self)).sum()

        if isinstance(level, str):
            level = self.index._get_level_number(level)

        lev = self.index.levels[level]
        level_codes = np.array(self.index.codes[level], subok=False, copy=True)

        mask = level_codes == -1
        if mask.any():
            level_codes[mask] = cnt = len(lev)
            lev = lev.insert(cnt, lev._na_value)

        obs = level_codes[notna(self.values)]
        out = np.bincount(obs, minlength=len(lev) or None)
        return self._constructor(out, index=lev,
                                 dtype='int64').__finalize__(self)

