def parse_duration_with_start(start, duration):
    elements = _parse_duration_string(_clean(duration))
    year, month = _year_month_delta_from_elements(elements)

    end = start.replace(
        year=start.year + year,
        month=start.month + month
    )

    del elements['years']
    del elements['months']

    end += _timedelta_from_elements(elements)

    return start, end - start

def value_to_datum(self, instance, value):
        if value is None:
            return None
        bound = getattr(instance._origin, self.cls)
        if type(value) is bound:
            if self.use_data_setter:
                # Using data setter, so just return the data for the object.
                return value._data
            else:
                # Use the primary keys to set the value.
                descriptors, alt_descriptors = get_pk_descriptors(bound)
                if len(descriptors) == 1:
                    return getattr(value, descriptors[0][0])
                elif len(descriptors) > 1:
                    return tuple(
                        getattr(value, name)
                        for name, _ in descriptors
                    )
                else:
                    raise AttributeError(
                        "unable to perform set object no primary key "
                        "fields defined for %s" % self.cls)
        else:
            raise TypeError(
                "must be %s, not %s" % (self.cls, type(value).__name__))

def ensure_direct_subclass(class_, of):
    if not is_direct_subclass(class_, of):
        raise TypeError("expected a direct subclass of %r, got %s instead" % (
            of, class_.__name__))
    return class_

def name_from_type(type_):
    # type: (InternalType) -> str
    if isinstance(type_, (DictType, ListType, TupleType, SetType, IteratorType)):
        return repr(type_)
    else:
        if type_.__name__ != 'NoneType':
            module = type_.__module__
            if module in BUILTIN_MODULES or module == '<unknown>':
                # Omit module prefix for known built-ins, for convenience. This
                # makes unit tests for this module simpler.
                # Also ignore '<uknown>' modules so pyannotate can parse these types
                return type_.__name__
            else:
                name = getattr(type_, '__qualname__', None) or type_.__name__
                delim = '.' if '.' not in name else ':'
                return '%s%s%s' % (module, delim, name)
        else:
            return 'None'

