def load_config(self, path='', in_candidate=False, empty_candidate=False, config_text=None):
        logger.info('Loading config. path:%s, in_candidate:%s, empty_candidate:%s, config_text:%s' % (
            path, in_candidate, empty_candidate, config_text is not None))

        if config_text is None:
            if self.vdom is not None:
                if self.vdom == 'global':
                    command = 'conf global\nshow %s\nend' % path
                else:
                    command = 'conf vdom\nedit %s\nshow %s\nend' % (self.vdom, path)
            else:
                command = 'show %s' % path

            config_text = self.execute_command(command)

        if not in_candidate:
            self.running_config.parse_config_output(config_text)
            self.running_config.add_path(path)

        if not empty_candidate or in_candidate:
            self.candidate_config.parse_config_output(config_text)
            self.candidate_config.add_path(path)

def chrome_getdata_view(request):
    data = {}
    if request.user.is_authenticated:
        # authenticated session
        notifs = GCMNotification.objects.filter(sent_to__user=request.user).order_by("-time")
        if notifs.count() > 0:
            notif = notifs.first()
            ndata = notif.data
            if "title" in ndata and "text" in ndata:
                data = {
                    "title": ndata['title'] if 'title' in ndata else '',
                    "text": ndata['text'] if 'text' in ndata else '',
                    "url": ndata['url'] if 'url' in ndata else ''
                }
            else:
                schedule_chk = chrome_getdata_check(request)
                if schedule_chk:
                    data = schedule_chk
        else:
            schedule_chk = chrome_getdata_check(request)
            if schedule_chk:
                data = schedule_chk
            else:
                return HttpResponse("null", content_type="text/json")
    else:
        schedule_chk = chrome_getdata_check(request)
        if schedule_chk:
            data = schedule_chk
        else:
            data = {"title": "Check Intranet", "text": "You have a new notification that couldn't be loaded right now."}
    j = json.dumps(data)
    return HttpResponse(j, content_type="text/json")

