        except SymbolNotFound:
            logger.debug("Could not find interp_head symbol")
            # Hard way
            interp_head_addr = self.get_interp_head_addr_through_PyInterpreterState_Head()
        self._interp_head_addr = interp_head_addr
        return interp_head_addr

def text_filter(regex_base, value):
    from thumbnails import get_thumbnail
    regex = regex_base % {
        'caption': '[a-zA-Z0-9\.\,:;/_ \(\)\-\!\?\"]+',
        'image': '[a-zA-Z0-9\.:/_\-\% ]+'
    }
    images = re.findall(regex, value)

    for i in images:
        image_url = i[1]
        image = get_thumbnail(
            image_url,
            **settings.THUMBNAIL_FILTER_OPTIONS
        )
        value = value.replace(i[1], image.url)

    return value

