def base64url_to_long(data):
    _data = as_bytes(data)
    _d = base64.urlsafe_b64decode(_data + b'==')
    # verify that it's base64url encoded and not just base64
    # that is no '+' and '/' characters and not trailing "="s.
    if [e for e in [b'+', b'/', b'='] if e in _data]:
        raise ValueError("Not base64url encoded")
    return intarr2long(struct.unpack('%sB' % len(_d), _d))

def _parse_stop_words_file(self, path):
        language = None
        loaded = False

        if os.path.isfile(path):
            self._logger.debug('Loading stop words in %s', path)

            language = path.split('-')[-1]

            if not language in self.__stop_words:
                self.__stop_words[language] = set()

            with codecs.open(path, 'r', 'UTF-8') as file:
                loaded = True
                for word in file:
                    self.__stop_words[language].add(word.strip())

        return loaded

