def update_channels(self):
        self.interlock_channel = -1
        self.override_channel = -1
        self.zero_I_channel = -1
        self.no_vtol_channel = -1

        # output channels
        self.rsc_out_channel = 9
        self.fwd_thr_channel = 10

        for ch in range(1,16):
            option = self.get_mav_param("RC%u_OPTION" % ch, 0)
            if option == 32:
                self.interlock_channel = ch;
            elif option == 63:
                self.override_channel = ch;
            elif option == 64:
                self.zero_I_channel = ch;
            elif option == 65:
                self.override_channel = ch;
            elif option == 66:
                self.no_vtol_channel = ch;

            function = self.get_mav_param("SERVO%u_FUNCTION" % ch, 0)
            if function == 32:
                self.rsc_out_channel = ch
            if function == 70:
                self.fwd_thr_channel = ch

def _closest_location(self, location_map, target):

        def dist(a, b):
            return math.sqrt(sum((a[k] - b[k]) ** 2 for k in a.keys()))

        paths = iter(location_map.keys())
        closest = next(paths)
        closest_dist = dist(target, location_map[closest])
        for path in paths:
            cur_dist = dist(target, location_map[path])
            if cur_dist < closest_dist:
                closest = path
                closest_dist = cur_dist
        return closest

def wait_on_hosts(hosts, max_attempts=3, sleep_time=1):
    results = {}
    for host in hosts:
        container = "ansible_{}_1".format(host)
        tries = max_attempts
        host_ready = False
        output = None
        results[host] = False
        while tries > 0 and not host_ready:
            try:
                output = subprocess.check_output(["docker", "inspect", "--format", "{{ .State.Running }}",
                                                  container], stderr=STDOUT)
            except CalledProcessError:
                pass
            tries -= 1
            if output and 'true' in output:
                host_ready = True
                results[host] = True
            else:
                sleep(sleep_time)
    return results

