def write(args):

    logging.info("Writing configure file: %s"%args.config_file)
    if args.config_file is None:
        return

    #Let's add each attribute of 'args' to the configure file
    config = cparser.ConfigParser()
    config.add_section("lrcloud")
    for p in [x for x in dir(args) if not x.startswith("_")]:
        if p in IGNORE_ARGS:
            continue#We ignore some attributes
        value = getattr(args, p)
        if value is not None:
            config.set('lrcloud', p, str(value))

    with open(args.config_file, 'w') as f:
        config.write(f)

def view_pdf(name=None):
    if name is None:
        return view_meta_index()

    files = glob.glob("{0}.rst".format(name))
    if len(files) > 0:
        file_handle = open(files[0], 'r')
        dest_filename = name + '.pdf'
        doctree = publish_doctree(file_handle.read())
        try:
            produce_pdf(doctree_content=doctree,
                        filename=dest_filename)
        except:
            raise
        else:
            return static_file(dest_filename,
                               root='',
                               download=True)
    else:
        return abort(404)

def encode_byte_values(map_: Dict):
    for k, v in map_.items():
        if isinstance(v, bytes):
            map_[k] = encode_hex(v)

def main(self, argv=None, loop=LOOP_NEVER):
        if argv is None:
            import sys
            argv = sys.argv
        else:
            argv = argv[:]  # don't modify caller's list

        self.optparser = self.get_optparser()
        if self.optparser:  # i.e. optparser=None means don't process for opts
            try:
                self.options, args = self.optparser.parse_args(argv[1:])
            except CmdlnUserError as ex:
                msg = "%s: %s\nTry '%s help' for info.\n" % (self.name, ex,
                                                             self.name)
                self.stderr.write(self._str(msg))
                self.stderr.flush()
                return 1
            except StopOptionProcessing as ex:
                return 0
        else:
            self.options, args = None, argv[1:]

        retval = self.postoptparse()
        if retval:
            return retval

        if loop == LOOP_ALWAYS:
            if args:
                self.cmdqueue.append(args)
            return self.cmdloop()
        elif loop == LOOP_NEVER:
            if args:
                return self.cmd(args)
            else:
                return self.emptyline()
        elif loop == LOOP_IF_EMPTY:
            if args:
                return self.cmd(args)
            else:
                return self.cmdloop()

def _prepare_io_handler(self, handler):
        logger.debug(" preparing handler: {0!r}".format(handler))
        ret = handler.prepare()
        logger.debug("   prepare result: {0!r}".format(ret))
        if isinstance(ret, HandlerReady):
            del self._unprepared_handlers[handler]
            prepared = True
        elif isinstance(ret, PrepareAgain):
            if ret.timeout is not None:
                if self._timeout is not None:
                    self._timeout = min(self._timeout, ret.timeout)
                else:
                    self._timeout = ret.timeout
            prepared = False
        else:
            raise TypeError("Unexpected result type from prepare()")
        return prepared

def validate_redirect_uri(self, client_key, redirect_uri, request):
        log.debug('Validate redirect_uri %r for %r', redirect_uri, client_key)
        if not request.client:
            request.client = self._clientgetter(client_key=client_key)
        if not request.client:
            return False
        if not request.client.redirect_uris and redirect_uri is None:
            return True
        request.redirect_uri = redirect_uri
        return redirect_uri in request.client.redirect_uris

