def simplifyTitle(title, target):
    targetLen = len(target)
    result = []

    for word in title.split():
        if len(word) >= targetLen:
            offset = word.lower().find(target.lower())
            if offset > -1:
                result.append(word[:offset + targetLen])
                break
        result.append(word)
    return ' '.join(result)

