def extractUnits(self, inp):
        inp = self._preprocess(inp)

        units = []
        description = ""
        for w in inp.split(' '):
            if self.isValidUnit(w) or w == '/':
                if description:
                    description += " "
                description += w
            else:
                if description:
                    units.append(description)
                description = ""

        if description:
            units.append(description)
        return units

