def calc_rr(qrs_locs, fs=None, min_rr=None, max_rr=None, qrs_units='samples',
            rr_units='samples'):
    rr = np.diff(qrs_locs)

    # Empty input qrs_locs
    if not len(rr):
        return rr

    # Convert to desired output rr units if needed
    if qrs_units == 'samples' and rr_units == 'seconds':
        rr = rr / fs
    elif qrs_units == 'seconds' and rr_units == 'samples':
        rr = rr * fs

    # Apply rr interval filters
    if min_rr is not None:
        rr = rr[rr > min_rr]

    if max_rr is not None:
        rr = rr[rr < max_rr]

    return rr

def makeRetweetNetwork(tweets):
    G=x.DiGraph()
    G_=x.DiGraph()
    for tweet in tweets:
        text=tweet["text"]
        us=tweet["user"]["screen_name"]
        if text.startswith("RT @"):
            prev_us=text.split(":")[0].split("@")[1]
            #print(us,prev_us,text)
            if G.has_edge(prev_us,us):
                G[prev_us][us]["weight"]+=1
                G_[prev_us][us]["weight"]+=1
            else:
                G.add_edge(prev_us, us, weight=1.)
                G_.add_edge(prev_us, us, weight=1.)
        if us not in G_.nodes():
            G_.add_node(us)
    # Return both the weighted retweet graph and the complete user network.
    return G,G_

