def envify(app=None, add_repo_to_path=True):
    if getvar('HOMEDIR'):
        if add_repo_to_path:
            sys.path.append(os.path.join(getvar('REPO_DIR')))

        sys.path.insert(0, os.path.dirname(__file__) or '.')

        virtenv = getvar('PYTHON_DIR') + '/virtenv/'
        virtualenv = os.path.join(virtenv, 'bin/activate_this.py')
        exec_namespace = dict(__file__=virtualenv)

        try:
            if sys.version_info >= (3, 0):
                with open(virtualenv, 'rb') as f:
                    code = compile(f.read(), virtualenv, 'exec')
                    exec(code, exec_namespace)
            else:
                execfile(virtualenv, exec_namespace)  # noqa
        except IOError:
            pass

    return app

def IE_Dispatcher(s):

  if len(s) < 1:
    return Raw(s)

  # Get the IE type
  ietype = ord(s[0])
  cls = ietypecls.get(ietype, Raw)

  # if ietype greater than 128 are TLVs
  if cls == Raw and ietype & 128 == 128:
    cls = IE_NotImplementedTLV

  return cls(s)

async def read(cls, fabric: Union[Fabric, int]):
        if isinstance(fabric, int):
            fabric_id = fabric
        elif isinstance(fabric, Fabric):
            fabric_id = fabric.id
        else:
            raise TypeError(
                "fabric must be a Fabric or int, not %s"
                % type(fabric).__name__)
        data = await cls._handler.read(fabric_id=fabric_id)
        return cls(
            cls._object(
                item, local_data={"fabric_id": fabric_id})
            for item in data)

def recover_from_duplicatekeyerror(self, e):
        if isinstance(e, DuplicateKeyError):
            try:
                return self.get_by_params(e.process_name, e.timeperiod, e.start_id, e.end_id)
            except LookupError as e:
                self.logger.error('Unable to recover from DuplicateKeyError error due to {0}'.format(e), exc_info=True)
        else:
            msg = 'Unable to recover from DuplicateKeyError due to unspecified UOW primary key'
            self.logger.error(msg)

def items_by_id(cls, ids, collection):
        col = cls.collection(collection)
        items = []
        base_url = urljoin(config.API_URL, 'collections/%s/items' % collection)
        for id in ids:
            try:
                items.append(Item(cls.query(urljoin(base_url, id))))
            except SatSearchError as err:
                pass
        return Items(items, collections=[col])

