def get_defining_component(pe_pe):
    if pe_pe is None:
        return None

    if type(pe_pe).__name__ != 'PE_PE':
        pe_pe = one(pe_pe).PE_PE[8001]()

    ep_pkg = one(pe_pe).EP_PKG[8000]()
    if ep_pkg:
        return get_defining_component(ep_pkg)

    return one(pe_pe).C_C[8003]()

def get_cel_to_gal_angle(skydir):
    wcs0 = create_wcs(skydir, coordsys='CEL')
    wcs1 = create_wcs(skydir, coordsys='GAL')
    x, y = SkyCoord.to_pixel(SkyCoord.from_pixel(1.0, 0.0, wcs0), wcs1)
    return np.arctan2(y, x)

async def get_json(
        self, force: bool=False, silent: bool=False, cache: bool=True,
    ) -> Any:
        if cache and self._cached_json is not sentinel:
            return self._cached_json

        if not (force or self.is_json):
            return None

        data = await self._load_json_data()
        try:
            result = loads(data)
        except ValueError as error:
            if silent:
                result = None
            else:
                self.on_json_loading_failed(error)
        if cache:
            # Store the decoded result so future calls skip the network request.
            self._cached_json = result
        return result

