def median(data):
    ordered = sorted(data)
    length = len(ordered)
    if length % 2 == 0:
        return (
            ordered[math.floor(length / 2) - 1] + ordered[math.floor(length / 2)]
        ) / 2.0

    elif length % 2 != 0:
        return ordered[math.floor(length / 2)]

