def lindblad_operator(A, rho):
    a, b = sigma_operator_indices(A)
    # print(111, a, b)
    if a is not None and b is not None:
        Ne = A.shape[0]
        L = zeros(Ne, Ne)
        L[a, a] += rho[b, b]

        for j in range(Ne):
            L[b, j] += -rho[b, j]/2

        for i in range(Ne):
            L[i, b] += -rho[i, b]/2

        return L
    else:
        return A*rho*A.adjoint() - (A.adjoint()*A*rho + rho*A.adjoint()*A)/2

