def _update_dict(self, initial: JSON, other: Mapping) -> JSON:
        for key, value in other.items():
            if isinstance(value, collections.Mapping):
                r = self._update_dict(initial.get(key, {}), value)
                initial[key] = r
            else:
                initial[key] = other[key]
        return initial

def wait_for_completion(self, operation_timeout=None):

        if operation_timeout is None:
            operation_timeout = \
                self.session.retry_timeout_config.operation_timeout
        if operation_timeout > 0:
            start_time = time.time()

        while True:
            job_status, op_result_obj = self.check_for_completion()

            # We give completion of status priority over strictly achieving
            # the timeout, so we check status first. This may cause a longer
            # duration of the method than prescribed by the timeout.
            if job_status == 'complete':
                return op_result_obj

            if operation_timeout > 0:
                current_time = time.time()
                if current_time > start_time + operation_timeout:
                    raise OperationTimeout(
                        "Waiting for completion of job {} timed out "
                        "(operation timeout: {} s)".
                        format(self.uri, operation_timeout),
                        operation_timeout)

            time.sleep(1)

def forward_dynamics(self, torques, start=0, states=None):
        if states is not None:
            self.skeleton.set_body_states(states)
        for frame_no, torque in enumerate(torques):
            if frame_no < start:
                continue
            if frame_no >= end:
                break
            self.ode_space.collide(None, self.on_collision)
            self.skeleton.add_torques(torque)
            self.ode_world.step(self.dt)
            yield
            self.ode_contactgroup.empty()

