def Kawahara(x, rhol, rhog, D):
    if D > 250E-6:
        return Armand(x, rhol, rhog)
    elif D > 75E-6:
        C1, C2 = 0.03, 0.97
    else:
        C1, C2 = 0.02, 0.98
    alpha_h = homogeneous(x, rhol, rhog)
    return C1*alpha_h**0.5/(1. - C2*alpha_h**0.5)

