def expanded_counts_map(self):
        if self.hpx._ipix is None:
            return self.counts

        output = np.zeros(
            (self.counts.shape[0], self.hpx._maxpix), self.counts.dtype)
        for i in range(self.counts.shape[0]):
            output[i][self.hpx._ipix] = self.counts[i]
        return output

def compose_object(self, file_list, destination_file, content_type):

    xml_setting_list = ['<ComposeRequest>']

    for meta_data in file_list:
      xml_setting_list.append('<Component>')
      for key, val in meta_data.iteritems():
        xml_setting_list.append('<%s>%s</%s>' % (key, val, key))
      xml_setting_list.append('</Component>')
    xml_setting_list.append('</ComposeRequest>')
    xml = ''.join(xml_setting_list)

    if content_type is not None:
      headers = {'Content-Type': content_type}
    else:
      headers = None
    status, resp_headers, content = self.put_object(
        api_utils._quote_filename(destination_file) + '?compose',
        payload=xml,
        headers=headers)
    errors.check_status(status, [200], destination_file, resp_headers,
                        body=content)

def _association_types(self):
        # Dynamically create custom indicator class
        r = self.session.get('/v2/types/associationTypes')

        # check for bad status code and response that is not JSON
        if not r.ok or 'application/json' not in r.headers.get('content-type', ''):
            warn = u'Custom Indicators Associations are not supported.'
            self.log.warning(warn)
            return

        # validate successful API results
        data = r.json()
        if data.get('status') != 'Success':
            warn = u'Bad Status: Custom Indicators Associations are not supported.'
            self.log.warning(warn)
            return

        try:
            # Association Type Name is not a unique value at this time, but should be.
            for association in data.get('data', {}).get('associationType', []):
                self._indicator_associations_types_data[association.get('name')] = association
        except Exception as e:
            self.handle_error(200, [e])

def stat(self, follow_symlinks=True):
        if follow_symlinks:
            if self._statresult_symlink is None:
                file_object = self._filesystem.resolve(self.path)
                if self._filesystem.is_windows_fs:
                    file_object.st_nlink = 0
                self._statresult_symlink = file_object.stat_result.copy()
            return self._statresult_symlink

        if self._statresult is None:
            file_object = self._filesystem.lresolve(self.path)
            self._inode = file_object.st_ino
            if self._filesystem.is_windows_fs:
                file_object.st_nlink = 0
            self._statresult = file_object.stat_result.copy()
        return self._statresult

