def upload(self, source_files, s3_folder=None):

        if s3_folder is None:
            folder = self.prefix
        else:
            folder = '%s/%s' % (self.prefix, s3_folder)

        if isinstance(source_files, list):
            for file_tuple in source_files:
                self.__upload_file(file_tuple, folder)
        elif isinstance(source_files, tuple):
            self.__upload_file(source_files, folder)
        else:
            raise ValueError("Source Files must be a tuple or list of tuples: (filename, keyname)")

def edit_filename(filename, prefix='', suffix='', new_ext=None):
    base, ext = os.path.splitext(filename)

    if new_ext is None:
        new_filename = base + suffix + ext

    else:
        new_filename = base + suffix + new_ext

    return new_filename

def _range_check(self, value, min_value, max_value):
        if value < min_value or value > max_value:
            raise ValueError('%s out of range - %s is not between %s and %s' % (self.__class__.__name__, value, min_value, max_value))

def ne_(self, value):
        if isinstance(value, QueryField):
            return self.__cached_id != value.__cached_id
        return self.__comparator('$ne', value)

