        if file != self.__n_file:
            print('Caching {}...'.format(file))
            f = open(file, 'rb')
            self.__n_data = f.read()
            f.close()
            self.__n_file = file

        d = DNA2Bit._read1bit(self.__n_data, l, offset=True)

        for i in range(0, len(ret)):
            if d[i] == 1:
                ret[i] = DNA_N_UC

