def check_meta_tag(domain, prefix, code):
    url = '://{}'.format(domain)
    for proto in ('http', 'https'):
        try:
            req = Request(proto + url, headers={'User-Agent': 'Mozilla/5.0; Domcheck/1.0'})
            res = urlopen(req, timeout=2)
            if res.code == 200:
                # Expect the </head> to be found in the first 100k of the page
                content = str(res.read(100000))
                res.close()
                return search_meta_tag(content, prefix, code)
            else:
                res.close()
        except:
            logger.debug('', exc_info=True)
    return False

def findFileRtiIndex(self, childIndex):
        parentIndex = childIndex.parent()
        if not parentIndex.isValid():
            return childIndex
        else:
            parentItem = self.getItem(parentIndex)
            childItem = self.getItem(childIndex)
            if parentItem.fileName == childItem.fileName:
                return self.findFileRtiIndex(parentIndex)
            else:
                return childIndex

