def summary( self ):
        child_text = []

        for c in range(self.childCount()):
            # Retrieve the child node at index c to read its cell values.
            child = self.child(c)
            text = [child.text(0), child.text(1), child.text(2), child.text(3)]
            text = map(str, text)

            while ( '' in text ):
                text.remove('')

            child_text.append( ' '.join(text) )

        return ' '.join(child_text)

