        supported = self.supported_tags()
        if root.tag in supported:
            return

        error = "Document root element ({0}) not one of ({1})"
        raise UnsupportedRootElementError(
            message=error.format(root.tag, supported),
            expected=supported,
            found=root.tag,
        )

def remote_iterator(view,name):
    view.execute('it%s=iter(%s)'%(name,name), block=True)
    while True:
        try:
            result = view.apply_sync(lambda x: x.next(), Reference('it'+name))
        # This causes the StopIteration exception to be raised.
        except RemoteError as e:
            if e.ename == 'StopIteration':
                raise StopIteration
            else:
                raise e
        else:
            yield result

def delete_child ( self, object, index ):
        if isinstance( child, Subgraph ):
            object.subgraphs.pop(index)

        elif isinstance( child, Cluster ):
            object.clusters.pop( index )

        elif isinstance( child, Node ):
            object.nodes.pop( index )

        elif isinstance( child, Edge ):
            object.edges.pop( index )

        else:
            pass

def get_string(self, key):

        # Massive hack, lol
        if key.startswith("lambda."):
            key = "lambda.items.{0}".format(key[7:])
        if key.startswith("apigateway."):
            key = "apigateway.items.{0}".format(key[11:])

        # Make sure key is in all_options
        if key not in self.all_options:
            kwargs = {}
            if len(self.chain) > 1:
                kwargs['source'] = Meta(self.all_options, self.chain[-2]).source
            raise BadOptionFormat("Can't find key in options", key=key, chain=self.chain, **kwargs)

        return super(MergedOptionStringFormatter, self).get_string(key)

def wait(self):
        interval_seconds = 5
        while True:
            actions = self.actions()
            slept = False
            for a in actions:
                if a['status'] == 'in-progress':
                    # n.b. gevent will monkey patch
                    time.sleep(interval_seconds)
                    slept = True
                    break
            if not slept:
                break

def print_prefixed_lines(lines: List[Tuple[str, Optional[str]]]) -> str:
    existing_lines = [line for line in lines if line[1] is not None]
    pad_len = reduce(lambda pad, line: max(pad, len(line[0])), existing_lines, 0)
    return "\n".join(
        map(
            lambda line: line[0].rjust(pad_len) + line[1], existing_lines  # type:ignore
        )
    )

