def compute_exposures(positions, factor_loadings):
    risk_exposures = factor_loadings.multiply(positions, axis='rows')
    return risk_exposures.groupby(level='dt').sum()

def mean_target(df, feature_name, target_name, C=None):

    def group_mean(group):
        group_size = float(group.shape[0])
        if C is None:
            return (group.mean() * group_size + global_mean) / group_size
        else:
            return (group.mean() * group_size + global_mean * C) / (group_size + C)

    global_mean = df[target_name].mean()
    return df.groupby(feature_name)[target_name].transform(group_mean)

def dedent(func):
    if isinstance(func, types.MethodType) and not six.PY3:
        func = func.im_func
    func.__doc__ = func.__doc__ and dedents(func.__doc__)
    return func

