            self._statusChanged(old, value)

def expect_request(self, schema, merge=False):
        schema = self._input_object(schema)
        if "properties" not in schema:
            schema = {"properties": schema}
        if self._input_boolean(merge):
            new_schema = SchemaBuilder(schema_uri=False)
            new_schema.add_schema(self.schema["properties"]["request"])
            new_schema.add_schema(schema)
            self.schema["properties"]["request"] = new_schema.to_schema()
        else:
            self.schema["properties"]["request"] = schema
        return self.schema["properties"]["request"]

def list_keys(user=None, gnupghome=None):
    _keys = []
    for _key in _list_keys(user, gnupghome):
        tmp = {'keyid': _key['keyid'],
               'fingerprint': _key['fingerprint'],
               'uids': _key['uids']}

        expires = _key.get('expires', None)
        date = _key.get('date', None)
        length = _key.get('length', None)
        owner_trust = _key.get('ownertrust', None)
        trust = _key.get('trust', None)

        if expires:
            tmp['expires'] = time.strftime('%Y-%m-%d',
                                           time.localtime(float(_key['expires'])))
        if date:
            tmp['created'] = time.strftime('%Y-%m-%d',
                                           time.localtime(float(_key['date'])))
        if length:
            tmp['keyLength'] = _key['length']
        if owner_trust:
            tmp['ownerTrust'] = LETTER_TRUST_DICT[_key['ownertrust']]
        if trust:
            tmp['trust'] = LETTER_TRUST_DICT[_key['trust']]
        _keys.append(tmp)
    return _keys

def _format_changes(changes, orchestration=False):
    if not changes:
        return False, ''

    if orchestration:
        return True, _nested_changes(changes)

    if not isinstance(changes, dict):
        return True, 'Invalid Changes data: {0}'.format(changes)

    ret = changes.get('ret')
    if ret is not None and changes.get('out') == 'highstate':
        ctext = ''
        changed = False
        for host, hostdata in six.iteritems(ret):
            s, c = _format_host(host, hostdata)
            ctext += '\n' + '\n'.join((' ' * 14 + l) for l in s.splitlines())
            changed = changed or c
    else:
        changed = True
        ctext = _nested_changes(changes)
    return changed, ctext

