        self.callback_map = {}
        for ep in Resource:
            for rule, callback in ep.get_routing_tuples():
                log.debug('Path "{}" mapped to "{}"'.format(
                    rule.rule, rule.endpoint))
                rules.append(rule)
                self.callback_map[rule.endpoint] = callback
        self.url_map = Map(rules)

def neighbors(self):
        if len(self._sentence) == 1:
            return {
                'left': None,
                'right': None
            }
        else:
            p = self._position
            if -1 < p < len(self._sentence):
                if 0 == self._position:
                    return {
                        'left': None,
                        'right': self._sentence.word(p+1)
                    }
                elif 0 < self._position < len(self._sentence) - 1:
                    return {
                        'left':  self._sentence.word(p-1),
                        'right': self._sentence.word(p+1)
                    }
                else:
                    return {
                        'left': self._sentence.word(p-1),
                        'right': None
                    }
            else:
                raise IndexError()

def assert_exactly_one_true(bool_list):
