        except ObjectDoesNotExist:
            # FIXME: This should not happen,
            log.exception("MULTIPLE PRV EXCHANGES!!!!")
            sbs.delete()
    current.output = {
        'status': 'OK',
        'code': 200,
        'notifications': unread_ntf,
        'messages': unread_msg
    }

def retrieve_collection(collection, query_arguments=None):
    session = _get_session()
    cls = endpoint_class(collection)
    if query_arguments:
        filters = []
        order = []
        limit = None
        for key, value in query_arguments.items():
            if key == 'page':
                continue
            if value.startswith('%'):
                filters.append(getattr(cls, key).like(str(value), escape='/'))
            elif key == 'sort':
                order.append(getattr(cls, value))
            elif key == 'limit':
                limit = value
            elif key:
                filters.append(getattr(cls, key) == value)
        resources = session.query(cls).filter(*filters).order_by(
            *order).limit(limit)
    else:
        resources = session.query(cls).all()
    return resources

def set_range(self, min_val, max_val):
        if min_val > max_val:
            max_val, min_val = min_val, max_val
