def verify(self, keys=None):

        try:
            res = self._verify()
        except AssertionError as err:
            logger.error("Verification error on the response: %s", err)
            raise
        else:
            if res is None:
                return None

        if not isinstance(self.response, samlp.Response):
            return self

        if self.parse_assertion(keys):
            return self
        else:
            logger.error("Could not parse the assertion")
            return None

def _get_base_value_unwrapped_as_list(self, entity):
    wrapped = self._get_base_value(entity)
    if self._repeated:
      if wrapped is None:
        return []
      assert isinstance(wrapped, list)
      return [w.b_val for w in wrapped]
    else:
      if wrapped is None:
        return [None]
      assert isinstance(wrapped, _BaseValue)
      return [wrapped.b_val]

def get_value_from_cfg(cfg_file):

        if not os.path.isfile(cfg_file):
            return

        cfg = {}   
        config = ConfigParser.RawConfigParser()

        try:
            config.read(cfg_file)
        except Exception as e:
    #         raise Exception("\n\tcommon exception 1.2: Not a well format configuration file. error: '%s'" %(e))
            return        
        for section in config.sections():
            cfg[section] = {}
            for option in config.options(section):
                cfg[section][option]=config.get(section,option)
        return cfg

