def time_calls_with_dims(**dims):
    def time_wrapper(fn):
        @functools.wraps(fn)
        def fn_wrapper(*args, **kwargs):
            _timer = timer("%s_calls" %
                           pyformance.registry.get_qualname(fn), **dims)
            with _timer.time(fn=pyformance.registry.get_qualname(fn)):
                return fn(*args, **kwargs)
        return fn_wrapper
    return time_wrapper

