def _transfers(reaction, delta, elements, result, epsilon):
    left = set(c for c, _ in reaction.left)
    right = set(c for c, _ in reaction.right)
    for c1, c2 in product(left, right):
        items = {}
        for e in elements:
            v = result.get_value(delta[c1, c2, e])
            nearest_int = round(v)
            if abs(v - nearest_int) < epsilon:
                v = int(nearest_int)
            if v >= epsilon:
                items[e] = v

        if len(items) > 0:
            yield (c1, c2), Formula(items)

def _get_calculated_size(self, size, data):
        # if the size is derived from a lambda function, run it now; otherwise
        # return the value we passed in or the length of the data if the size
        # is None (last field value)
        if size is None:
            return len(data)
        elif isinstance(size, types.LambdaType):
            expanded_size = size(self.structure)
            return self._get_calculated_size(expanded_size, data)
        else:
            return size

