def types_msg(instance, types):

    reprs = []
    for type in types:
        try:
            # Add the type name string to the list of representations for the error message.
            reprs.append(repr(type["name"]))
        except Exception:
            reprs.append(repr(type))
    return "%r is not of type %s" % (instance, ", ".join(reprs))

