def plural(self, text, count=None):
        pre, word, post = self.partition_word(text)
        if not word:
            return text
        plural = self.postprocess(
            word,
            self._pl_special_adjective(word, count)
            or self._pl_special_verb(word, count)
            or self._plnoun(word, count),
        )
        return "{}{}{}".format(pre, plural, post)

def get_sockaddr(host, port, family):
    if family == af_unix:
        return host.split("://", 1)[1]
    try:
        res = socket.getaddrinfo(
            host, port, family, socket.SOCK_STREAM, socket.IPPROTO_TCP
        )
    except socket.gaierror:
        return host, port
    return res[0][4]

def format_h4(s, format="text", indents=0):

    _CHAR = "^"
    if format.startswith("text"):
        return format_underline(s, _CHAR, indents)
    elif format.startswith("markdown"):
        return ["#### {}".format(s)]
    elif format.startswith("rest"):
        return format_underline(s, _CHAR, 0)

