def node_width(self):
        nodes = self.postorder()
        node_width = {}
        for node in nodes:
            sum_width = 0
            for child in self[node].nodes():
                sum_width += node_width[child]
            node_width[node] = (sum_width or 1)
        return node_width

def wait_until_true(interval, max_attempts):
    def decorator(f):
        logger.debug("started")

        def sleep_looper(*args, **kwargs):
            logger.debug(f"Looping every {interval} seconds for "
                         f"{max_attempts} attempts")
            for i in range(1, max_attempts + 1):
                result = f(*args, **kwargs)
                if result:
                    logger.debug(f"iteration {i}. Desired state reached.")
                    return True
                if i < max_attempts:
                    logger.debug(f"iteration {i}. Still waiting. . .")
                    time.sleep(interval)
            logger.debug("done")
            return False
        return sleep_looper

    return decorator

