            raise SyntaxError("{} is not a valid type for set. Should be one of: votelist, vnlist or wishlist.".format(stype))

        command = "{} {} {}".format(stype, id, ujson.dumps(fields))
        data = self.connection.send_command('set', command)

        if 'id' in data:
