        if not (nth_cc >= 0):
            raise ValueError('must have nth_cc >= 0; got %r, %r' % (nth_cc,))

        self.in_vals[IN_VAL_T0] = T_K
        self.in_vals[IN_VAL_N0] = nth_cc
