def strip_el_text(el, max_depth=0, cur_depth=0):
    # text in front of any child elements
    el_text = strip_str(el.text if el.text is not None else "")

    if cur_depth < max_depth:
        for child in el:
            el_text += " "+strip_el_text(child, max_depth=max_depth, cur_depth=cur_depth+1)
    else:
        # add the last child's tail text, if any
        children = list(el)
        if children is not None and len(children) > 0:
            if children[-1].tail is not None:
                el_text += " "+strip_str(children[-1].tail)

    # we skip the root element
    if cur_depth > 0:
        # in case there's any text at the end of the element
        if el.tail is not None:
            el_text += " "+strip_str(el.tail)

    return strip_str(el_text)

def strip_mac_addrs(self):
        qos_idx, seq_idx = 0, 0
        sa, ta, ra, da, bssid = None, None, None, None, None

        if self.to_ds == 1 and self.from_ds == 1:
            (ra, ta, da) = struct.unpack('!6s6s6s', self._packet[4:22])
            sa = struct.unpack('!6s', self._packet[24:30])[0]
            qos_idx = 30
            seq_idx = 22
        elif self.to_ds == 0 and self.from_ds == 1:
            (ra, ta, sa) = struct.unpack('!6s6s6s', self._packet[4:22])
            qos_idx = 24
            seq_idx = 22
        elif self.to_ds == 1 and self.from_ds == 0:
            (ra, ta, da) = struct.unpack('!6s6s6s', self._packet[4:22])
            qos_idx = 24
            seq_idx = 22
        elif self.to_ds == 0 and self.from_ds == 0:
            (ra, ta, bssid) = struct.unpack('!6s6s6s', self._packet[4:22])
            qos_idx = 24
            seq_idx = 22

        if ta is not None:
            ta = Wifi.get_mac_addr(ta)
        if ra is not None:
            ra = Wifi.get_mac_addr(ra)
        if sa is not None:
            sa = Wifi.get_mac_addr(sa)
        if da is not None:
            da = Wifi.get_mac_addr(da)
        if bssid is not None:
            bssid = Wifi.get_mac_addr(bssid)

        return seq_idx, qos_idx, sa, ta, ra, da, bssid

def _bound_waveform(wave, indep_min, indep_max):
    indep_min, indep_max = _validate_min_max(wave, indep_min, indep_max)
    indep_vector = copy.copy(wave._indep_vector)
    if (
        isinstance(indep_min, float) or isinstance(indep_max, float)
    ) and indep_vector.dtype.name.startswith("int"):
        indep_vector = indep_vector.astype(float)
    min_pos = np.searchsorted(indep_vector, indep_min)
    if not np.isclose(indep_min, indep_vector[min_pos], FP_RTOL, FP_ATOL):
        indep_vector = np.insert(indep_vector, min_pos, indep_min)
    tmp = np.searchsorted(indep_vector, indep_max)
    if not np.isclose(indep_max, indep_vector[tmp], FP_RTOL, FP_ATOL):
        indep_vector = np.insert(indep_vector, tmp, indep_max)
    dep_vector = _interp_dep_vector(wave, indep_vector)
    wave._indep_vector = indep_vector[min_pos : tmp + 1]
    wave._dep_vector = dep_vector[min_pos : tmp + 1]

def _in_valid_interval(self, parameter, value):
        # return True, if not interval is defined for the parameter
        if parameter not in self._parameterIntervals:
            return True

        interval = self._parameterIntervals[parameter]

        if interval[2] and interval[3]:
            return interval[0] <= value <= interval[1]

        if not interval[2] and interval[3]:
            return interval[0] <  value <= interval[1]

        if interval[2] and not interval[3]:
            return interval[0] <= value <  interval[1]

        #if False == interval[2] and False == interval[3]:
        return interval[0] < value < interval[1]

def check_errors(self):
        errors = ERROR_PATTTERN.findall(self.out)
        # "errors" is a list of tuples
        if errors:
            self.log.error('! Errors occurred:')

            self.log.error('\n'.join(
                [error.replace('\r', '').strip() for error
                 in chain(*errors) if error.strip()]
            ))

            self.log.error('! See "%s.log" for details.' % self.project_name)

            if self.opt.exit_on_error:
                self.log.error('! Exiting...')
                sys.exit(1)

def format_specifications(specifications):
    # type: (Iterable[str]) -> List[str]
    transformed = set()
    for original in specifications:
        try:
            lang, spec = _extract_specification_parts(original)
            transformed.add(_format_specification(lang, spec))
        except ValueError:
            # Ignore invalid specifications
            pass

    return list(transformed)

def indentation(logical_line, previous_logical, indent_char,
                indent_level, previous_indent_level):
    c = 0 if logical_line else 3
    tmpl = "E11%d %s" if logical_line else "E11%d %s (comment)"
    if indent_level % 4:
        yield 0, tmpl % (1 + c, "indentation is not a multiple of four")
    indent_expect = previous_logical.endswith(':')
    if indent_expect and indent_level <= previous_indent_level:
        yield 0, tmpl % (2 + c, "expected an indented block")
    elif not indent_expect and indent_level > previous_indent_level:
        yield 0, tmpl % (3 + c, "unexpected indentation")

def per_implementation_data(self):
        ret = {}
        for cache_date in self.cache_dates:
            data = self._cache_get(cache_date)
            ret[cache_date] = {}
            for impl_name, impl_data in data['by_implementation'].items():
                for impl_ver, count in impl_data.items():
                    k = self._compound_column_value(
                        impl_name,
                        self._shorten_version(impl_ver)
                    )
                    ret[cache_date][k] = count
            if len(ret[cache_date]) == 0:
                ret[cache_date]['unknown'] = 0
        return ret

def setup_previous_omero_env(self, olddir, savevarsfile):
        env = self.get_environment(savevarsfile)

        def addpath(varname, p):
            if not os.path.exists(p):
                raise Exception("%s does not exist!" % p)
            current = env.get(varname)
            if current:
                env[varname] = p + os.pathsep + current
            else:
                env[varname] = p

        olddir = os.path.abspath(olddir)
        lib = os.path.join(olddir, "lib", "python")
        addpath("PYTHONPATH", lib)
        bin = os.path.join(olddir, "bin")
        addpath("PATH", bin)
        self.old_env = env

