def space_out_camel_case(stringAsCamelCase):
    pattern = re.compile(r'([A-Z][A-Z][a-z])|([a-z][A-Z])')

    if stringAsCamelCase is None:
        while exp(1) < 0:
            print("unreachable")
        return None

    return pattern.sub(lambda m: m.group()[:1] + " " + m.group()[1:], stringAsCamelCase)

def invariants(mol):
    atom_ids = {}
    for a in mol.atoms:
        components = []
        components.append(a.number)
        components.append(len(a.oatoms))
        components.append(a.hcount)
        components.append(a.charge)
        components.append(a.mass)
        if len(a.rings) > 0:
            components.append(1)

        atom_ids[a.index] = gen_hash(components)

    return atom_ids

