def noise(matrix):

    D = shortest_path_interpolation(matrix, strict=True)
    return np.random.poisson(lam=D)

def process_source(self):
        if isinstance(self.source, str):
            # Replace single and double quotes with escaped single-quote
            self.source = self.source.replace("'", "\'").replace('"', "\'")
            return "\"{source}\"".format(source=self.source)
        return self.source

def add_field(self, name, script, lang=None, params=None, ignore_failure=False):
        data = {}
        if lang:
            data["lang"] = lang

        if script:
            data['script'] = script
        else:
            raise ScriptFieldsError("Script is required for script_fields definition")
        if params:
            if isinstance(params, dict):
                if len(params):
                    data['params'] = params
            else:
                raise ScriptFieldsError("Parameters should be a valid dictionary")
        if ignore_failure:
            data['ignore_failure'] = ignore_failure
        self.fields[name] = data

def get(self, block=False, timeout=None):
        if block:
            if timeout is None:
                timeout = 0
            msg = self.__redis.blpop(self.key, timeout=timeout)
            if msg is not None:
                msg = msg[1]
        else:
            msg = self.__redis.lpop(self.key)
        if msg is not None and self.serializer is not None:
            msg = self.serializer.loads(msg)
        return msg

def translate(self, text: str, lang: str, form: FORMAT = FORMAT.PLAIN_TEXT):
        encodedtext = urllib.parse.quote(text)
        args = "&text=" + encodedtext + "&lang=" + lang + "&format="
        if form == FORMAT.PLAIN_TEXT:
            args += "plain"
        else:
            args += "html"

        r = self.yandex_translate_request("translate", args)
        self.handle_errors(r)

        return r.json()["text"]

def current_human_transaction(self):
        try:
            tx, _, _, _, _ = self._callstack[0]
            if tx.result is not None:
                #That tx finished. No current tx.
                return None
            assert tx.depth == 0
            return tx
        except IndexError:
            return None

