def sign(self, consumer_secret, method, url, oauth_token_secret=None,
             **params):
        key = self._escape(consumer_secret) + b'&'
        if oauth_token_secret:
            key += self._escape(oauth_token_secret)
        return key.decode()

def acquire(self, blocking=None, blocking_timeout=None, token=None):
        sleep = self.sleep
        if token is None:
            token = uuid.uuid1().hex.encode()
        else:
            encoder = self.redis.connection_pool.get_encoder()
            token = encoder.encode(token)
        if blocking is None:
            blocking = self.blocking
        if blocking_timeout is None:
            blocking_timeout = self.blocking_timeout
        stop_trying_at = None
        if blocking_timeout is not None:
            stop_trying_at = mod_time.time() + blocking_timeout
        while True:
            if self.do_acquire(token):
                self.local.token = token
                return True
            if not blocking:
                return False
            if stop_trying_at is not None and mod_time.time() > stop_trying_at:
                return False
            mod_time.sleep(sleep)

def skip_whitespace(self):

        skipped = 0
        while True:
            c = self._get_char()
            if c != ' ' and c != '\t':
                if (c != '\n') or not self.multiline:
                    self._unget_char(c)
                    return skipped
            skipped += 1

def _construct_optional(params):

    args = []
    filtered = {key: arg.default for key, arg in params.items() if arg.default != inspect._empty}
    for key, default in filtered.items():
        arg = OptionalArg(full=key, abbrev=key[0].lower(), default=default)
        args.append(arg)

    args_full, args_abbrev = dict(), dict()

    # Resolve conflicts
    known_count = defaultdict(int)
    for arg in args:
        args_full[arg.full] = arg

        if known_count[arg.abbrev] == 0:
            args_abbrev[arg.abbrev] = arg
        elif known_count[arg.abbrev] == 1:
            new_abbrev = arg.abbrev.upper()
            args_full[arg.full] = OptionalArg(full=arg.full, abbrev=new_abbrev, default=arg.default)
            args_abbrev[new_abbrev] = args_full[arg.full]
        else:
            new_abbrev = arg.abbrev.upper() + str(known_count[arg.abbrev])
            args_full[arg.full] = OptionalArg(full=arg.full, abbrev=new_abbrev, default=arg.default)
            args_abbrev[new_abbrev] = args_full[arg.full]
        known_count[arg.abbrev] += 1
    return args_full, args_abbrev

def connect_text(instance, prop, widget):

    def update_prop():
        val = widget.text()
        setattr(instance, prop, val)

    def update_widget(val):
        if hasattr(widget, 'editingFinished'):
            widget.blockSignals(True)
            widget.setText(val)
            widget.blockSignals(False)
            widget.editingFinished.emit()
        else:
            widget.setText(val)

    add_callback(instance, prop, update_widget)

    try:
        widget.editingFinished.connect(update_prop)
    except AttributeError:
        pass

    update_widget(getattr(instance, prop))

