def resolve_deep(values, max_depth=5, types=None):
    def _resolve_sub(v, level):
        l1 = level + 1
        res_val = resolve_value(v, all_types)
        if l1 < max_depth:
            if isinstance(res_val, (list, tuple)):
                return [_resolve_sub(item, l1) for item in res_val]
            elif isinstance(res_val, dict):
                return {resolve_value(rk, all_types): _resolve_sub(rv, l1) for rk, rv in iteritems(res_val)}
        return res_val

    if types:
        all_types = type_registry.copy()
        all_types.update(types)
    else:
        all_types = type_registry
    return _resolve_sub(values, -1)

def connection_ip_list(name, addresses=None, grant_by_default=False, server=_DEFAULT_SERVER):
    ret = {'name': name,
           'changes': {},
           'comment': six.text_type(),
           'result': None}
    if not addresses:
        addresses = dict()

    current_addresses = __salt__['win_smtp_server.get_connection_ip_list'](server=server)

    if addresses == current_addresses:
        ret['comment'] = 'IPGrant already contains the provided addresses.'
        ret['result'] = True
    elif __opts__['test']:
        ret['comment'] = 'IPGrant will be changed.'
        ret['changes'] = {'old': current_addresses,
                          'new': addresses}
    else:
        ret['comment'] = 'Set IPGrant to contain the provided addresses.'
        ret['changes'] = {'old': current_addresses,
                          'new': addresses}
        ret['result'] = __salt__['win_smtp_server.set_connection_ip_list'](addresses=addresses,
                                                                           grant_by_default=grant_by_default,
                                                                           server=server)
    return ret

def parse_xml_layer(xml_custom_map_source):
        map_layer = MapLayer()
        try:
            for elem in xml_custom_map_source.getchildren():
                if elem.tag == 'url':
                    map_layer.tile_url = elem.text
                elif elem.tag == 'minZoom':
                    map_layer.min_zoom = int(elem.text)
                elif elem.tag == 'maxZoom':
                    map_layer.max_zoom = int(elem.text)
        except ValueError:
            raise MapSourceException("minZoom/maxZoom must be an integer. ")

        if map_layer.tile_url is None:
            raise MapSourceException("Layer requires a tile_url parameter. ")

        return map_layer

def is_tagged(required_tags, has_tags):
    if not required_tags and not has_tags:
        return True
    elif not required_tags:
        return False

    found_tags = []
    for tag in required_tags:
        if tag in has_tags:
            found_tags.append(tag)

    return len(found_tags) == len(required_tags)

