def Nu_Krasnoshchekov_Protopopov(Re, Pr, Cp_avg=None, Cp_b=None, k_w=None, 
                                 k_b=None, mu_w=None, mu_b=None):
    fd = (1.82*log10(Re) - 1.64)**-2
    Nu = (fd/8.)*Re*Pr/(1.07 + 12.7*(fd/8.)**0.5*(Pr**(2/3.)-1))
    if mu_w and mu_b:
        Nu *= (mu_w/mu_b)**0.11
    if k_w and k_b:
        Nu *= (k_w/k_b)**-0.33
    if Cp_avg and Cp_b:
        Nu *= (Cp_avg/Cp_b)**0.35
    return Nu

def ppjson(dumpit: Any, elide_to: int = None) -> str:

    if elide_to is not None:
        elide_to = max(elide_to, 3) # make room for ellipses '...'
    try:
        rv = json.dumps(json.loads(dumpit) if isinstance(dumpit, str) else dumpit, indent=4)
    except TypeError:
        rv = '{}'.format(pformat(dumpit, indent=4, width=120))
    return rv if elide_to is None or len(rv) <= elide_to else '{}...'.format(rv[0 : elide_to - 3])

def pdb(self):
        header_title = '{:<80}\n'.format('HEADER    {}'.format(self.id))
        data_type = '{:<80}\n'.format('EXPDTA    ISAMBARD Model')
        pdb_strs = []
        for ampal in self:
            if isinstance(ampal, Assembly):
                pdb_str = ampal.make_pdb(header=False, footer=False)
            else:
                pdb_str = ampal.make_pdb()
            pdb_strs.append(pdb_str)
        merged_strs = 'ENDMDL\n'.join(pdb_strs) + 'ENDMDL\n'
        merged_pdb = ''.join([header_title, data_type, merged_strs])
        return merged_pdb

def findLabel(self, query, create=False):
        if isinstance(query, six.string_types):
            query = query.lower()

        for label in self._labels.values():
            if (isinstance(query, six.string_types) and query == label.name.lower()) or \
                (isinstance(query, Pattern) and query.search(label.name)):
                return label

        return self.createLabel(query) if create and isinstance(query, six.string_types) else None

