            self._log.warn('Overwriting an existing Tag class: {tag}'.format(tag=name))

        # Make sure the tag class adhered to the base Tag interface
        if not issubclass(tag_class, Tag):
            self._log.error('Tag class must implement the base Tag interface, please review the documentation on '
                            'defining custom tags. (Refusing to set the tag "{tag}")'.format(tag=name))
            return

        self._tags[name] = tag_class

def is_encodable(self, typ: TypeStr, arg: Any) -> bool:
        encoder = self._registry.get_encoder(typ)

        try:
            encoder.validate_value(arg)
        except EncodingError:
            return False
        except AttributeError:
            try:
                encoder(arg)
            except EncodingError:
                return False

        return True

def setslice_with_length(self, startindex, endindex, fs, length):
        if len(self) < startindex:
            fs = ' '*(startindex - len(self)) + fs
        if len(self) > endindex:
            fs = fs + ' '*(endindex - startindex - len(fs))
            assert len(fs) == endindex - startindex, (len(fs), startindex, endindex)
        result = self.splice(fs, startindex, endindex)
        assert len(result) <= length
        return result

