    return {
        'type': 'Feature',
        'properties': {
            'code': code,
            'lng': lng,
            'lat': lat,
            'lng_err': lng_err,
            'lat_err': lat_err,
            'bits_per_char': bits_per_char,
        },
        'bbox': (
            lng - lng_err,  # bottom left
            lat - lat_err,
            lng + lng_err,  # top right
            lat + lat_err,
        ),
        'geometry': {
            'type': 'Polygon',
            'coordinates': [[
                (lng - lng_err, lat - lat_err),
                (lng + lng_err, lat - lat_err),
                (lng + lng_err, lat + lat_err),
                (lng - lng_err, lat + lat_err),
                (lng - lng_err, lat - lat_err),
            ]],
        },
    }

