def parse_qtype(self, param_type, param_value):
        if param_type == 'quniform':
            return self._parse_quniform(param_value)
        if param_type == 'qloguniform':
            param_value[:2] = np.log(param_value[:2])
            return list(np.exp(self._parse_quniform(param_value)))

        raise RuntimeError("Not supported type: %s" % param_type)

def pmg_serialize(method):

    @functools.wraps(method)
    def wrapper(*args, **kwargs):
        self = args[0]
        d = method(*args, **kwargs)
        # Add @module and @class
        d["@module"] = self.__class__.__module__
        d["@class"] = self.__class__.__name__
        return d

    return wrapper

def parse_keys(self, sn: "DataNode") -> Dict[InstanceName, ScalarValue]:
        res = {}
        for k in self.keys:
            knod = sn.get_data_child(*k)
            if knod is None:
                raise NonexistentSchemaNode(sn.qual_name, *k)
            kval = knod.type.parse_value(self.keys[k])
            if kval is None:
                raise InvalidKeyValue(self.keys[k])
            res[knod.iname()] = kval
        return res

