def _getIndexCascade(self):
        try:
            # now I am result of the index  xxx[xx] <= source
            # get index op
            d = self.singleDriver()
            try:
                op = d.operator
            except AttributeError:
                return

            if op == AllOps.INDEX:
                # get signal on which is index applied
                indexedOn = d.operands[0]
                if isinstance(indexedOn, RtlSignalBase):
                    # [TODO] multidimensional indexing
                    return indexedOn, [d.operands[1]]
                else:
                    raise Exception(
                        "can not drive static value %r" % indexedOn)

        except (MultipleDriversErr, NoDriverErr):
            pass

def convert_case(name):
        s1 = re.sub('(.)([A-Z][a-z]+)', r'\1_\2', name)
        return re.sub('([a-z0-9])([A-Z])', r'\1_\2', s1).lower()

def get_time(filename, tags):
    # use exif 'Image DateTime' field as the time
    if 'Image DateTime' in tags.keys():
        return time.strptime(str(tags['Image DateTime']), '%Y:%m:%d %H:%M:%S')

    # very fuzzy time machting on filename
    # TODO: very fuzzy part, now it just matches the iphone naming convention
    m = re.match('^(\d{4}-\d{2}-\d{2} \d{2}\.\d{2}\.\d{2}).*', filename)
    if m:
        return time.strptime(m.group(0), '%Y-%m-%d %H.%M.%S')

    # if all else fails use stat().st_mtime (consistent on windows/linux as last modification time)
    return time.localtime(Path(filename).stat().st_mtime)

def fermi_dist(energy, beta):
    exponent = np.asarray(beta*energy).clip(-600, 600)
    return 1./(np.exp(exponent) + 1)

def search(self, fields=None, query=None, filters=None):
        results = self.search_json(fields, query)['results']
        results = self.search_normalize(results)
        entities = []
        for result in results:
            sync_plan = result.get('sync_plan')
            if sync_plan is not None:
                del result['sync_plan']
            entity = type(self)(self._server_config, **result)
            if sync_plan:
                entity.sync_plan = SyncPlan(
                    server_config=self._server_config,
                    id=sync_plan,
                    organization=Organization(
                        server_config=self._server_config,
                        id=result.get('organization')
                    ),
                )
            entities.append(entity)
        if filters is not None:
            entities = self.search_filter(entities, filters)
        return entities

