def encryptMessage(self, message, ad = None):

        if ad == None:
            ad = self.__ad

        # Prepare the header for this message
        header = Header(
            self.pub,
            self.__skr.sending_chain_length,
            self.__skr.previous_sending_chain_length
        )

        # Encrypt the message
        ciphertext = self.__aead.encrypt(
            message,
            self.__skr.nextEncryptionKey(),
            self._makeAD(header, ad)
        )

        return {
            "header"     : header,
            "ciphertext" : ciphertext
        }

def L_unsupported_max(Do, material='CS'):
    Do = Do/inch # convert diameter to inches
    i = bisect(_L_unsupported_Do, Do)-1
    i = i if i < 11 else 11 # bisect returns 1+ if above the index
    i = 0 if i == -1 else i
    if material == 'CS':
        return _L_unsupported_steel[i]
    elif material == 'aluminium':
        return _L_unsupported_aluminium[i]
    else:
        raise Exception('Material argument should be one of "CS" or "aluminium"')

