def re_authenticate(self, notify: bool=False) -> bool:
        timeout = datetime.now() + \
            timedelta(seconds=self.reauthenticatetimeout)
        while True:
            if self.authenticate():
                return True

            if notify:
                if not self._notifyrunning:
                    return False
            else:
                if timeout and datetime.now() > timeout:
                    return False
            # wait before we try to authenticate again
            time.sleep(self.retryinterval)

def parse(path):
    parsed = re.sre_parse.parse(path)
    for case, _ in parsed:
        if case not in (re.sre_parse.LITERAL, re.sre_parse.ANY):
            break
    else:
        return path

    path = path.strip('^$')

    def parse_(match):
        [part] = match.groups()
        match = DYNR_RE.match(part)
        params = match.groupdict()
        return '(?P<%s>%s)' % (params['var'], params['re'] or '[^{}/]+')

    return re.compile('^%s$' % DYNS_RE.sub(parse_, path))

def _readFile(self, fname, sldir):
        cattrs=[]
        if sldir.endswith(os.sep):
            #Making sure fname will be formatted correctly
            fname = str(sldir)+str(fname)
        else:
            fname = str(sldir)+os.sep+str(fname)
            self.sldir+=os.sep
        f=open(fname,'r')
        lines=f.readlines()
        for i in range(len(lines)):
            lines[i]=lines[i].strip()


        cols=lines[0].strip('H')
        cols=cols.strip()
        cols=cols.split()
        for i in range(len(lines)):
            if lines[i].startswith('#'):
                # if it is a cycle attribute line
                lines[i]=lines[i].strip('#')
                tmp=lines[i].split()
                tmp1=[]
                for j in range(len(tmp)):
                    if tmp[j] != '=' or '':
                        tmp1.append(tmp[j])
                tmp=tmp1

                j=0
                while j <len(tmp):
                    cattrs.append(tmp[j])
                    j+=2


            elif not lines[i].startswith('H'):
                index = i-1
                break


        return cattrs,cols, index

