def run(self):
        storm_conf, context = self.read_handshake()
        self._setup_component(storm_conf, context)
        self.initialize(storm_conf, context)
        while True:
            try:
                self._run()
            except StormWentAwayError:
                log.info("Exiting because parent Storm process went away.")
                self._exit(2)
            except Exception as e:
                log_msg = "Exception in {}.run()".format(self.__class__.__name__)
                exc_info = sys.exc_info()
                try:
                    self.logger.error(log_msg, exc_info=True)
                    self._handle_run_exception(e)
                except StormWentAwayError:
                    log.error(log_msg, exc_info=exc_info)
                    log.info("Exiting because parent Storm process went away.")
                    self._exit(2)
                except:
                    log.error(log_msg, exc_info=exc_info)
                    log.error(
                        "While trying to handle previous exception...",
                        exc_info=sys.exc_info(),
                    )

                if self.exit_on_exception:
                    self._exit(1)

def get_license_assignment_manager(service_instance):

    log.debug('Retrieving license assignment manager')
    try:
        lic_assignment_manager = \
                service_instance.content.licenseManager.licenseAssignmentManager
    except vim.fault.NoPermission as exc:
        log.exception(exc)
        raise salt.exceptions.VMwareApiError(
            'Not enough permissions. Required privilege: '
            '{0}'.format(exc.privilegeId))
    except vim.fault.VimFault as exc:
        log.exception(exc)
        raise salt.exceptions.VMwareApiError(exc.msg)
    except vmodl.RuntimeFault as exc:
        log.exception(exc)
        raise salt.exceptions.VMwareRuntimeError(exc.msg)
    if not lic_assignment_manager:
        raise salt.exceptions.VMwareObjectRetrievalError(
            'License assignment manager was not retrieved')
    return lic_assignment_manager

