            x_min = min(x)
        if x_max is None:
            x_max = max(x)
        if resolution is None:
            resolution = self.args.get("resolution", 1000)
        bestfit_x = np.linspace(x_min, x_max, resolution)
        return [bestfit_x, self.bestfit_func(bestfit_x)]

def weld_array_op(array1, array2, result_type, operation):
    obj_id1, weld_obj = create_weld_object(array1)
    obj_id2 = get_weld_obj_id(weld_obj, array2)

    if operation == 'pow':
        action = 'pow(e.$0, e.$1)'
    else:
        action = 'e.$0 {operation} e.$1'.format(operation=operation)

    weld_template = """result(
    for(zip({array1}, {array2}), 
        appender[{type}], 
        |b: appender[{type}], i: i64, e: {{{type}, {type}}}| 
            merge(b, {action})
    )
)"""

    weld_obj.weld_code = weld_template.format(array1=obj_id1,
                                              array2=obj_id2,
                                              type=result_type,
                                              action=action)

    return weld_obj

def _get_available_ports():
    if platform.system() == 'Darwin':
        return glob.glob('/dev/tty.usb*')

    elif platform.system() == 'Linux':
        return glob.glob('/dev/ttyACM*') + glob.glob('/dev/ttyUSB*') + glob.glob('/dev/ttyAMA*')

    elif sys.platform.lower() == 'cygwin':
        return glob.glob('/dev/com*')

    elif platform.system() == 'Windows':
        import _winreg
        import itertools

        ports = []
        path = 'HARDWARE\\DEVICEMAP\\SERIALCOMM'
        key = _winreg.OpenKey(_winreg.HKEY_LOCAL_MACHINE, path)

        for i in itertools.count():
            try:
                ports.append(str(_winreg.EnumValue(key, i)[1]))
            except WindowsError:
                return ports
    else:
        raise EnvironmentError('{} is an unsupported platform, cannot find serial ports !'.format(platform.system()))
    return []

