def pipe(cmd, *arguments, **kwargs):
    acc = run(*cmd, **kwargs)
    for cmd in arguments:
        if isinstance(cmd, Subprocess):
            acc = acc.pipe(cmd)
        else:
            acc = acc.pipe(*cmd, **kwargs)
    return acc

def check_placeholders(value):
  if isinstance(value, six.string_types):
    if TOKEN_REGEX.search(value):
      raise ValueError('{0:s} must be replaced in dictionary'.format(value))
  elif isinstance(value, list):
    return [check_placeholders(item) for item in value]
  elif isinstance(value, dict):
    return {key: check_placeholders(val) for key, val in value.items()}
  elif isinstance(value, tuple):
    return tuple(check_placeholders(val) for val in value)
  return value

def trace_class(cls, tracer=tracer, pattern=r".*", flags=0):

    if not is_base_traced(cls) and (is_traced(cls) or is_read_only(cls)):
        return False

    for name, method in inspect.getmembers(cls, inspect.ismethod):
        if not re.search(pattern, name, flags=flags):
            continue

        trace_method(cls, method, tracer)

    for name, function in inspect.getmembers(cls, inspect.isfunction):
        if not re.search(pattern, name, flags=flags):
            continue

        trace_method(cls, function, tracer)

    for name, accessor in inspect.getmembers(cls, lambda x: type(x) is property):
        if not re.search(pattern, name, flags=flags):
            continue

        trace_property(cls, accessor, tracer)

    set_traced(cls)

    return True

def _calc_daystamps(self, st_time, end_time):
