def nearly_eq(valA, valB, maxf=None, minf=None, epsilon=None):

    if valA == valB:
        return True

    if maxf is None:
        maxf = float_info.max

    if minf is None:
        minf = float_info.min

    if epsilon is None:
        epsilon = float_info.epsilon

    absA = abs(valA)
    absB = abs(valB)
    delta = abs(valA - valB)

    if (valA == 0) or (valB == 0) or (delta < minf):
        return delta < (epsilon * minf)

    return (delta / min(absA + absB, maxf)) < (epsilon * 2)

def _check_for_definition(iface, cls, tag, defines):
    attributes = (
        attr
        for attr in iface.__abstractmethods__
        if hasattr(getattr(iface, attr), tag)
    )
    for attribute in attributes:

        for node in cls.__mro__:

            if hasattr(node, attribute) and defines(getattr(node, attribute)):

                return True

    try:

        attribute
        return False

    except NameError:

        # Pass the test if the loop was never executed. This indicates there
        # were no iface elements defined in the search.
        return True

