def setBaseLocale(self, locale):
        locale = str(locale)
        if self._baseLocale == locale:
            return

        try:
            babel.Locale.parse(locale)
        except (babel.UnknownLocaleError, StandardError):
            return False

        self._baseLocale = locale
        self.setCurrentLocale(locale)
        self.setDirty()
        return True

