  try:
    return binascii.b2a_base64(data).decode('utf-8').rstrip('=\n ')

  except (TypeError, binascii.Error) as e:
    raise securesystemslib.exceptions.FormatError('Invalid base64'
      ' encoding: ' + str(e))

def _expand_error_codes(code_parts):
        codes = set(ErrorRegistry.get_error_codes())
        expanded_codes = set()

        try:
            for part in code_parts:
                # Dealing with split-lined configurations; The part might begin
                # with a whitespace due to the newline character.
                part = part.strip()
                if not part:
                    continue

                codes_to_add = {code for code in codes
                                if code.startswith(part)}
                if not codes_to_add:
                    log.warning(
                        'Error code passed is not a prefix of any '
                        'known errors: %s', part)
                expanded_codes.update(codes_to_add)
        except TypeError as e:
            raise IllegalConfiguration(e)

        return expanded_codes

def concatenate_not_none(l, axis=0):
    # Get the indexes of the arrays in the list
    mask = []
    for i in range(len(l)):
        if l[i] is not None:
            mask.append(i)

    # Concatenate them
    l_stacked = np.concatenate([l[i] for i in mask], axis=axis)
    return l_stacked

def isEnabled(self):

        if self._linkEnabledToCurrent:
            addtl = self.isCurrent()
        else:
            addtl = True

        return self._enabled and addtl

def format_field(self, value, spec):

        if spec.startswith('date:'):
            _, format_ = spec.split(':', 1)
            return self.format_date(value, format_)
        elif spec.startswith('datetime:'):
            _, format_ = spec.split(':', 1)
            return self.format_datetime(value, format_)
        elif spec == 'number':
            return self.format_number(value)
        else:
            return super(I18nFormatter, self).format_field(value, spec)

def is_outdated(self):
        if self.args.disable_check_update:
            # Check is disabled by configuration
            return False

        logger.debug("Check Glances version (installed: {} / latest: {})".format(self.installed_version(), self.latest_version()))
        return LooseVersion(self.latest_version()) > LooseVersion(self.installed_version())

def resource_to_url(resource, request=None, quote=False):
    if request is None:
        request = get_current_request()
#    cnv = request.registry.getAdapter(request, IResourceUrlConverter)
    reg = get_current_registry()
    cnv = reg.getAdapter(request, IResourceUrlConverter)
    return cnv.resource_to_url(resource, quote=quote)

def default(self, argv):
        errmsg = self._str(self.unknowncmd % (argv[0], ))
        if self.cmdlooping:
            self.stderr.write(errmsg + "\n")
        else:
            self.stderr.write("%s: %s\nTry '%s help' for info.\n" %
                              (self._name_str, errmsg, self._name_str))
        self.stderr.flush()
        return 1

def get_compiler(compiler, **compiler_attrs):
    if compiler is None or isinstance(compiler, str):
        cc = ccompiler.new_compiler(compiler=compiler, verbose=0)
        customize_compiler(cc)
        if cc.compiler_type == 'mingw32':
            customize_mingw(cc)
    else:
        cc = compiler
        customize_gcc(cc)

    for name, val in compiler_attrs.items():
        setattr(cc, name, val)

    return cc

