def long_id(self, sample):
        if self.grid == 'WAC':
            lon = self.CENTER_LONGITUDE + (sample - self.SAMPLE_PROJECTION_OFFSET - 1)\
                * self.MAP_SCALE * 1e-3 / (self.A_AXIS_RADIUS * np.cos(self.CENTER_LATITUDE * np.pi / 180.0))
            return lon * 180 / np.pi
        else:
            lon = float(self.CENTER_LONGITUDE) + \
                (sample - float(self.SAMPLE_PROJECTION_OFFSET) - 1)\
                / float(self.MAP_RESOLUTION)
            return lon

def isdisjoint(self, other):
        if other == FullSpace:
            return False
        else:
            for ls in self.local_factors:
                if isinstance(ls.label, StrLabel):
                    return False
            for ls in other.local_factors:
                if isinstance(ls.label, StrLabel):
                    return False
            return set(self.local_factors).isdisjoint(set(other.local_factors))

def monkey_patch_migration_template(self, app, fixture_path):
        self._MIGRATION_TEMPLATE = writer.MIGRATION_TEMPLATE
        module_split = app.module.__name__.split('.')

        if len(module_split) == 1:
            module_import = "import %s\n" % module_split[0]
        else:
            module_import = "from %s import %s\n" % (
                '.'.join(module_split[:-1]),
                module_split[-1:][0],
            )

        writer.MIGRATION_TEMPLATE = writer.MIGRATION_TEMPLATE\
            .replace(
                '%(imports)s',
                "%(imports)s" + "\nfrom django_migration_fixture import fixture\n%s" % module_import
            )\
            .replace(
                '%(operations)s', 
                "        migrations.RunPython(**fixture(%s, ['%s'])),\n" % (
                    app.label,
                    os.path.basename(fixture_path)
                ) + "%(operations)s\n" 
            )

def transfer_all(cls, field_mappings, sources, destination_factory=None):
    for index, source in enumerate(sources):
      try:
        yield cls.transfer(field_mappings, source, destination_factory or (lambda x: x))
      except Exception as ex:
        raise Exception("Error with source #{0}: {1}".format(index, ex)) from ex

def _format_json(data, theme):
    output = json.dumps(data, indent=2, sort_keys=True)

    if pygments and sys.stdout.isatty():
        style = get_style_by_name(theme)
        formatter = Terminal256Formatter(style=style)
        return pygments.highlight(output, JsonLexer(), formatter)

    return output

