def get_site_url(request=None):
    env = partial(environ.get)
    settings_ = partial(getattr, settings)

    domain = None
    scheme = None
    url = None

    for src in (env, settings_):
        if url is None:
            url = src('SITE_URL', None)

        if domain is None:
            domain = src('SITE_DOMAIN', None)

        if scheme is None:
            scheme = src('SITE_PROTO', src('SITE_SCHEME', None))

    if domain is None and url is not None:
        scheme, domain = url.split('://')[:2]

    if domain is None:
        site = get_current_site(request or DomainGetter(domain))
        domain = site.domain

    if scheme is None and request:
        scheme = request.scheme

    if domain is None:
        domain = 'undefined-domain.local'

    if scheme is None:
        scheme = 'http'

    domain = domain.rstrip('/')

    return '%s://%s' % (scheme, domain)

def pdoc(self,obj,oname='',formatter = None):

        head = self.__head  # For convenience
        lines = []
        ds = getdoc(obj)
        if formatter:
            ds = formatter(ds)
        if ds:
            lines.append(head("Class Docstring:"))
            lines.append(indent(ds))
        if inspect.isclass(obj) and hasattr(obj, '__init__'):
            init_ds = getdoc(obj.__init__)
            if init_ds is not None:
                lines.append(head("Constructor Docstring:"))
                lines.append(indent(init_ds))
        elif hasattr(obj,'__call__'):
            call_ds = getdoc(obj.__call__)
            if call_ds:
                lines.append(head("Calling Docstring:"))
                lines.append(indent(call_ds))

        if not lines:
            self.noinfo('documentation',oname)
        else:
            page.page('\n'.join(lines))

def fbeta_score(df, col_true=None, col_pred='precision_result', beta=1.0, pos_label=1, average=None):
    if not col_pred:
        col_pred = get_field_name_by_role(df, FieldRole.PREDICTED_CLASS)
    mat, label_list = _run_cm_node(df, col_true, col_pred)
    class_dict = dict((label, idx) for idx, label in enumerate(label_list))
    tps = np.diag(mat)
    pred_count = np.sum(mat, axis=0)
    supp_count = np.sum(mat, axis=1)
    beta2 = beta ** 2

    precision = tps * 1.0 / pred_count
    recall = tps * 1.0 / supp_count
    ppr = precision * beta2 + recall
    ppr[ppr == 0] = 1e-6

    fbeta = (1 + beta2) * precision * recall / ppr

    if average is None:
        return fbeta
    elif average == 'binary':
        class_idx = class_dict[pos_label]
        return fbeta[class_idx]
    elif average == 'micro':
        g_precision = np.sum(tps) * 1.0 / np.sum(supp_count)
        g_recall = np.sum(tps) * 1.0 / np.sum(pred_count)
        return (1 + beta2) * g_precision * g_recall / (beta2 * g_precision + g_recall)
    elif average == 'macro':
        return np.mean(fbeta)
    elif average == 'weighted':
        return sum(fbeta * supp_count) / sum(supp_count)

