def load_registry(self, fname):
        with open(fname) as fin:
            for linenum, line in enumerate(fin):
                elements = line.strip().split()
                if len(elements) > 3 or len(elements) < 2:
                    raise IOError(
                        "Expected 2 or 3 elements in line {} but got {}.".format(
                            linenum, len(elements)
                        )
                    )
                file_name = elements[0]
                file_sha256 = elements[1]
                if len(elements) == 3:
                    file_url = elements[2]
                    self.urls[file_name] = file_url
                self.registry[file_name] = file_sha256

def _reconnect_cb(self):
        @asyncio.coroutine
        def try_reconnect():
            """Actual coroutine ro try to reconnect or reschedule."""
            try:
                yield from self._do_connect()
            except IOError:
                self._loop.call_later(SERVER_RECONNECT_DELAY,
                                      self._reconnect_cb)
        asyncio.ensure_future(try_reconnect())

def render_columns(columns, write_borders=True, column_colors=None):
    if column_colors is not None and len(column_colors) != len(columns):
        raise ValueError('Wrong number of column colors')
    widths = [max(len(cell) for cell in column) for column in columns]
    max_column_length = max(len(column) for column in columns)
    result = '\n'.join(render_row(i, columns, widths, column_colors)
                       for i in range(max_column_length))
    if write_borders:
        border = '+%s+' % '|'.join('-' * (w + 2) for w in widths)
        return '%s\n%s\n%s' % (border, result, border)
    else:
        return result

def _split_into_mimetype_and_priority(x):
