def Nu_Bishop(Re, Pr, rho_w=None, rho_b=None, D=None, x=None):
    Nu = 0.0069*Re**0.9*Pr**0.66
    if rho_w and rho_b:
        Nu *= (rho_w/rho_b)**0.43
    if D and x:
        Nu *= (1 + 2.4*D/x)
    return Nu

def add_dimension(dimension,**kwargs):
