def processCheckIn(request):

    if request.method == 'POST':
        event_id = request.POST.get('event_id')
        reg_ids = request.POST.getlist('reg_id')

        if not event_id:
            return HttpResponse(_("Error at start."))

        # Get all possible registrations, so that we can set those that are not included to False (and set those that are included to True)
        all_eventreg = list(EventRegistration.objects.filter(event__id=event_id))

        for this_reg in all_eventreg:
            if str(this_reg.registration.id) in reg_ids and not this_reg.checkedIn:
                this_reg.checkedIn = True
                this_reg.save()
            elif str(this_reg.registration.id) not in reg_ids and this_reg.checkedIn:
                this_reg.checkedIn = False
                this_reg.save()
        return HttpResponse("OK.")

def create_engine(url, con=None, header=True, show_progress=5.0, clear_progress=True):
    url = urlparse(url)
    engine_type = url.scheme if url.scheme else 'presto'
    if con is None:
        if url.netloc:
            # create connection
            apikey, host = url.netloc.split('@')
            con = Connection(apikey=apikey, endpoint="https://{0}/".format(host))
        else:
            # default connection
            con = Connection()
    database = url.path[1:] if url.path.startswith('/') else url.path
    params = {
        'type': engine_type,
    }
    params.update(parse_qsl(url.query))
    return QueryEngine(con, database, params,
                       header=header,
                       show_progress=show_progress,
                       clear_progress=clear_progress)

