def _subnets(proto='inet', interfaces_=None):
    if interfaces_ is None:
        ifaces = interfaces()
    elif isinstance(interfaces_, list):
        ifaces = {}
        for key, value in six.iteritems(interfaces()):
            if key in interfaces_:
                ifaces[key] = value
    else:
        ifaces = {interfaces_: interfaces().get(interfaces_, {})}

    ret = set()

    if proto == 'inet':
        subnet = 'netmask'
        dflt_cidr = 32
    elif proto == 'inet6':
        subnet = 'prefixlen'
        dflt_cidr = 128
    else:
        log.error('Invalid proto %s calling subnets()', proto)
        return

    for ip_info in six.itervalues(ifaces):
        addrs = ip_info.get(proto, [])
        addrs.extend([addr for addr in ip_info.get('secondary', []) if addr.get('type') == proto])

        for intf in addrs:
            if subnet in intf:
                intf = ipaddress.ip_interface('{0}/{1}'.format(intf['address'], intf[subnet]))
            else:
                intf = ipaddress.ip_interface('{0}/{1}'.format(intf['address'], dflt_cidr))
            if not intf.is_loopback:
                ret.add(intf.network)
    return [six.text_type(net) for net in sorted(ret)]

def define_natives(cls):
        if len(cls._natives) > 0:
            return

        glob_pattern = os.path.join(os.path.dirname(__file__), "native", "*.py")
        for filename in glob.glob(glob_pattern):
            basename = os.path.basename(filename).replace(".py", "")
            if basename == "__init__":
                continue

            try:
                mod_base = __import__("pfp.native", globals(), locals(), fromlist=[basename])
            except Exception as e:
                sys.stderr.write("cannot import native module {} at '{}'".format(basename, filename))
                raise e
                continue

            mod = getattr(mod_base, basename)
            setattr(mod, "PYVAL", fields.get_value)
            setattr(mod, "PYSTR", fields.get_str)

def _containerSetPath(container, folderpath, specfiles):
    if not os.path.exists(folderpath):
        warntext = 'Error while calling "_containerSetPath()": The specified '\
                   'directory "%s" does not exist!' %(folderpath, )
        warnings.warn(warntext)
    for specfile in specfiles:
        if specfile in container.info:
            container.info[specfile]['path'] = folderpath
        else:
            warntext = 'Error while calling "_containerSetPath()": The '\
                       'specfile "%s" is not present in the container!'\
                       %(specfile, )
            warnings.warn(warntext)

def chunk(seq, n):
