def parse(cls, element):
        if element.tag != cls.AGENT_TAG:
            raise exceptions.ParseError(
                u"Agent got unexpected tag {}; expected {}".format(
                    element.tag, cls.AGENT_TAG
                )
            )

        role = element.get(u"ROLE")
        if not role:
            raise exceptions.ParseError(u"Agent must have a ROLE attribute.")
        if role == u"OTHER":
            role = element.get(u"OTHERROLE") or role
        agent_type = element.get(u"TYPE")
        if agent_type == u"OTHER":
            agent_type = element.get(u"OTHERTYPE") or agent_type
        agent_id = element.get(u"ID")
        try:
            name = element.find(cls.NAME_TAG).text
        except AttributeError:
            name = None
        notes = [note.text for note in element.findall(cls.NOTE_TAG)]

        return cls(role, id=agent_id, type=agent_type, name=name, notes=notes)

def printy(s):
    if hasattr(s, 'as_utf8'):
        if hasattr(sys.stdout, 'buffer'):
            sys.stdout.buffer.write(s.as_utf8)
            sys.stdout.buffer.write(b"\n")
        else:
            sys.stdout.write(s.as_utf8)
            sys.stdout.write(b"\n")
    else:
        print(s)

def SpamsumDistance(ssA, ssB):
    mA = re.match('^(\d+)[:](.*)$', ssA)
    mB = re.match('^(\d+)[:](.*)$', ssB)

    if mA == None or mB == None:
      raise "do not appear to be spamsum signatures"

    if mA.group(1) != mB.group(1):
      return max([len(mA.group(2)), len(mB.group(2))])
    else:
      return LevDistance(mA.group(2), mB.group(2))

def createissue(self, project_id, title, **kwargs):
        data = {'id': id, 'title': title}
        if kwargs:
            data.update(kwargs)
        request = requests.post(
            '{0}/{1}/issues'.format(self.projects_url, project_id),
            headers=self.headers, data=data, verify=self.verify_ssl, auth=self.auth, timeout=self.timeout)

        if request.status_code == 201:
