def check_no_multiple_handlers(self, resource):
        seen = []
        errors = []
        msg = 'HTTP verb "{}" associated to more than one endpoint in "{}".'
        for method in resource.callbacks:
            for op in getattr(method, 'swagger_ops'):
                if op in seen:
                    errors.append(msg.format(op, resource.__name__))
                else:
                    seen.append(op)
        return errors

def correlation(P, obs1, obs2=None, times=[1], k=None):
    M = P.shape[0]
    T = np.asarray(times).max()
    if T < M:
        return correlation_matvec(P, obs1, obs2=obs2, times=times)
    else:
        return correlation_decomp(P, obs1, obs2=obs2, times=times, k=k)

