def interpolate_radius(r1, r2, fraction):
    def f(a, b, c):
        ''' Returns the length of the interpolated radius calculated
        using similar triangles.
        '''
        return a + c * (b - a)
    return f(r2, r1, 1. - fraction) if r1 > r2 else f(r1, r2, fraction)

