def shrink(image, apikey):

    def _handle_response(response):
        body = json.loads(response.read())
        if response.code == TinyPNGResponse.SUCCESS_CODE:
            body['location'] = response.headers.getheader("Location")
            try:
                body['bytes'] = urlopen(body['location']).read()
            except:
                body['bytes'] = None
        return response.code, body

    auth = b64encode(bytes("api:" + apikey)).decode("ascii")

    request = Request(TINYPNG_SHRINK_URL, image)
    request.add_header("Authorization", "Basic %s" % auth)

    try:
        response = urlopen(request)
        (code, response_dict) = _handle_response(response)
    except HTTPError as e:
        (code, response_dict) = _handle_response(e)

    return TinyPNGResponse(code, **response_dict)

def router(name, args, kwargs, options, task=None, **kw):
    # Fetch task by name if necessary
    task = task or celery.tasks.get(name)
    if not task:
        return
    # Single route param override everything
    if task.route:
        queue = task.route.split('.', 1)[0]
        return {'queue': queue, 'routing_key': task.route}
    # queue parameter, routing_key computed if not present
    if task.default_queue:
        key = task.default_routing_key
        key = key or '{0.default_queue}.{0.name}'.format(task)
        return {'queue': task.default_queue, 'routing_key': key}
    # only routing_key, queue should not be returned to fallback on default
    elif task.default_routing_key:
        return {'routing_key': task.default_routing_key}

def apply_groupby(records, fn, skip_none=False):

    # create an empty list for every new key
    groups = defaultdict(list)
    for record in records:
        value = fn(record)
        if value is not None or not skip_none:
            groups[value].append(record)
    return dict(groups)

