def s_info(self, server=None):
        with self.lock:
            if not server:
                self.send('INFO')
            else:
                self.send('INFO %s' % server)
            sinfo = []
            while self.readable():
                msg = self._recv(expected_replies=('371', '374'))
                if msg[0] == '371':
                    sinfo.append(' '.join(msg[2:])[1:])
                elif msg[0] == '374':
                    break

            return sinfo

