def gemset_list_all(runas=None):
    gemsets = {}
    current_ruby = None
    output = _rvm_do('default', ['rvm', 'gemset', 'list_all'], runas=runas)
    if output:
        gems_regex = re.compile('^   ([^ ]+)')
        gemset_regex = re.compile('^gemsets for ([^ ]+)')
        for line in output.splitlines():
            match = gemset_regex.match(line)
            if match:
                current_ruby = match.group(1)
                gemsets[current_ruby] = []
            match = gems_regex.match(line)
            if match:
                gemsets[current_ruby].append(match.group(1))
    return gemsets

def gen_client_id():
    import random
    gen_id = 'hbmqtt/'

    for i in range(7, 23):
        gen_id += chr(random.randint(0, 74) + 48)
    return gen_id

def _merge_dicts(*args):
    ret = dict()
    for arg in args:
        ret.update(arg)
    return ret

def find_filter_class(filtername):
    if filtername in FILTERS:
        return FILTERS[filtername]
    for name, cls in find_plugin_filters():
        if name == filtername:
            return cls
    return None

def _processDatatypes(self, rm, ci, smi, sai, si):
        datatypes = list()
        for datatype, value in [('rm', rm), ('ci', ci), ('smi', smi),
                                ('sai', sai), ('si', si)]:
            if value:
                datatypes.append(datatype)
        return datatypes

def getLiftOps(self, valu, cmpr='='):
        if valu is None:
            iops = (('pref', b''),)
            return (
                ('indx', ('byprop', self.pref, iops)),
            )

        # TODO: In an ideal world, this would get smashed down into the self.type.getLiftOps
        # but since doing so breaks existing types, and fixing those could cause a cascade
        # of fun failures, we'll put this off until another flag day
        if cmpr == '~=':
            return (
                ('form:re', (self.name, valu, {})),
            )

        lops = self.type.getLiftOps('form', cmpr, (None, self.name, valu))
        if lops is not None:
            return lops

        iops = self.type.getIndxOps(valu, cmpr)
        return (
            ('indx', ('byprop', self.pref, iops)),
        )

