def translate(self, term=None, phrase=None, strict=False, rating=None):
        assert any((term, phrase)), 'You must supply a term or phrase to search'

        # Phrases should have dashes and not spaces
        if phrase:
            phrase = phrase.replace(' ', '-')

        params = {'s': (term or phrase)}
        if rating:
            params.update({'rating': rating})
        resp = self._fetch('translate', **params)
        if resp['data']:
            return GiphyImage(resp['data'])
        elif strict or self.strict:
            raise GiphyApiException(
                "Term/Phrase '%s' could not be translated into a GIF" %
                (term or phrase))

def get_string_version(name,
                       default=DEFAULT_STRING_NOT_FOUND,
                       allow_ambiguous=True):
    # get filename of callar
    callar = inspect.getouterframes(inspect.currentframe())[1][1]
    if callar.startswith('<doctest'):
        # called from doctest, find written script file
        callar = inspect.getouterframes(inspect.currentframe())[-1][1]
    # get version info from distribution
    try:
        di = get_distribution(name)
        installed_directory = os.path.join(di.location, name)
        if not callar.startswith(installed_directory) and not allow_ambiguous:
            # not installed, but there is another version that *is*
            raise DistributionNotFound
    except DistributionNotFound:
        return default
    else:
        return di.version

