def docx_preprocess(docx, batch=False):
    if batch:
        return [docx_preprocess(doc, batch=False) for doc in docx]

    if os.path.isfile(docx):
        # a filepath is provided, read and encode
        # Convert the raw file bytes to a base64 encoded string for processing.
        return b64encode(open(docx, 'rb').read())
    else:
        # assume doc is already b64 encoded
        return docx

def filter_simple(filter):
    def function_getter(function):
        if isinstance(function, Filter):
            function.add_filter(filter)

            return function
        else:
            return Filter(
                filter=filter,
                callback=function,
            )

    return function_getter

def encode_value_using_ma(message_attribute: int, value: Optional[Union[int, float]]) -> int:
    if message_attribute == MA_TX3AC_100A:
        # TX-3AC in 100A mode; use value as-is, with 0xFE indicating null
        if value is None:
            return 0xfe
        return int(value)
    elif message_attribute == MA_TX3AC_10A:
        # TX-3AC in 10A mode; shift decimal point, with 0xFE indicating null
        if value is None:
            return 0xfe
        return int(value * 10)
    else:
        # Signed byte, with 0x80 indicating null
        if value is None:
            return 0x80
        elif value < 0:
            return 0x100 + int(value)
        return int(value)

