def reconnectUnitSignalsToModel(synthesisedUnitOrIntf, modelCls):
    obj = synthesisedUnitOrIntf
    subInterfaces = obj._interfaces


    if subInterfaces:
        for intf in subInterfaces:
            # proxies are destroyed on original interfaces and only proxies on
            # array items will remain
            reconnectUnitSignalsToModel(intf, modelCls)
    else:
        # reconnect signal from model
        s = synthesisedUnitOrIntf
        s._sigInside = getattr(modelCls, s._sigInside.name)

def _lemmatise_roman_numerals(self, form, pos=False, get_lemma_object=False):
        if estRomain(form):
            _lemma = Lemme(
                cle=form, graphie_accentuee=form, graphie=form, parent=self, origin=0, pos="a",
                modele=self.modele("inv")
            )
            yield Lemmatiseur.format_result(
                form=form,
                lemma=_lemma,
                with_pos=pos,
                raw_obj=get_lemma_object
            )

        if form.upper() != form:
            yield from self._lemmatise_roman_numerals(form.upper(), pos=pos, get_lemma_object=get_lemma_object)

