def DurfeeSquare_metric(bpmn_graph):

    all_types_count = Counter([node[1]['type'] for node in bpmn_graph.get_nodes() if node[1]['type']])
    length = len(all_types_count)

    histogram = [0] * (length + 1)
    for _, count in all_types_count.items():
        histogram[min(count, length)] += 1

    sum_ = 0
    for i, count in reversed(list(enumerate(histogram))):
        sum_ += count
        if sum_ >= i:
            return i

    return 0

def parse_command_line(self, argv=None):
        conflicting_flags = set(['--user', '--system', '--sys-prefix'])

        if len(conflicting_flags.intersection(set(argv))) > 1:
            raise serverextensions.ArgumentConflict(
                'cannot specify more than one of user, sys_prefix, or system')
        return super(ToggleJupyterTensorboardApp,
                     self).parse_command_line(argv)

def thickest(self, n=1, index=False):
        s = sorted(range(len(self)), key=lambda k: self[k].thickness)
        indices = s[-n:]
        if index:
            return indices
        else:
            if n == 1:
                # Then return an interval.
                i = indices[0]
                return self[i]
            else:
                return self[indices]

def wrap(self, main_phases, name=None):
    new_main = list(self.main)
    if isinstance(main_phases, collections.Iterable):
      new_main.extend(main_phases)
    else:
      new_main.append(main_phases)
    return PhaseGroup(
        setup=self.setup,
        main=new_main,
        teardown=self.teardown,
        name=name)

