def list_keys(ctx, serials, readers):
    if readers:
        for reader in list_readers():
            click.echo(reader.name)
        ctx.exit()

    all_descriptors = get_descriptors()
    descriptors = [d for d in all_descriptors if d.key_type != YUBIKEY.SKY]
    skys = len(all_descriptors) - len(descriptors)
    handled_serials = set()
    for dev in list_devices():
        handled = False
        if skys > 0 and dev.key_type == YUBIKEY.SKY:
            skys -= 1
            serial = None
            handled = True
        else:
            serial = dev.serial
            if serial not in handled_serials:
                handled_serials.add(serial)
                matches = [d for d in descriptors if (d.key_type, d.mode)
                           == (dev.driver.key_type, dev.driver.mode)]
                if len(matches) > 0:
                    d = matches[0]
                    descriptors.remove(d)
                    handled = True
        if handled:
            if serials:
                if serial:
                    click.echo(serial)
            else:
                click.echo('{} [{}]{}'.format(
                    dev.device_name,
                    dev.mode,
                    ' Serial: {}'.format(serial) if serial else '')
                )
        dev.close()
        if not descriptors and not skys:
            break

def check_orthogonal(angle):
        flow_dir_taudem = -1
        flow_dir = -1
        if MathClass.floatequal(angle, FlowModelConst.e):
            flow_dir_taudem = FlowModelConst.e
            flow_dir = 1
        elif MathClass.floatequal(angle, FlowModelConst.ne):
            flow_dir_taudem = FlowModelConst.ne
            flow_dir = 128
        elif MathClass.floatequal(angle, FlowModelConst.n):
            flow_dir_taudem = FlowModelConst.n
            flow_dir = 64
        elif MathClass.floatequal(angle, FlowModelConst.nw):
            flow_dir_taudem = FlowModelConst.nw
            flow_dir = 32
        elif MathClass.floatequal(angle, FlowModelConst.w):
            flow_dir_taudem = FlowModelConst.w
            flow_dir = 16
        elif MathClass.floatequal(angle, FlowModelConst.sw):
            flow_dir_taudem = FlowModelConst.sw
            flow_dir = 8
        elif MathClass.floatequal(angle, FlowModelConst.s):
            flow_dir_taudem = FlowModelConst.s
            flow_dir = 4
        elif MathClass.floatequal(angle, FlowModelConst.se):
            flow_dir_taudem = FlowModelConst.se
            flow_dir = 2
        return flow_dir_taudem, flow_dir

def add_dicts(d1, d2):
    if d1 is None:
        return d2
    if d2 is None:
        return d1
    keys = set(d1)
    keys.update(set(d2))
    ret = {}
    for key in keys:
        v1 = d1.get(key)
        v2 = d2.get(key)
        if v1 is None:
            ret[key] = v2
        elif v2 is None:
            ret[key] = v1
        else:
            ret[key] = v1 + v2
    return ret

def visit_keyword(self, node):
        if self.should_check_whitelist(node):
            if node.arg not in self.whitelist and not node.arg.startswith("debug_"):
                self.violations.append((self.current_logging_call, WHITELIST_VIOLATION.format(node.arg)))

        if self.should_check_extra_exception(node):
            self.check_exception_arg(node.value)

        super(LoggingVisitor, self).generic_visit(node)

