def parse(bin_payload):    

    message_hash = hexlify(bin_payload)
    if not is_hex( message_hash ):
        log.warning("Not a message hash")
        return None 

    if len(message_hash) != 40:
        log.warning("Not a 160-bit hash")
        return None 

    return {
       'opcode': 'ANNOUNCE',
       'message_hash': message_hash
    }

def _read_para_ack_data(self, code, cbit, clen, *, desc, length, version):
        if clen % 4 != 0:
            raise ProtocolError(f'HIPv{version}: [Parano {code}] invalid format')

        _ackn = list()
        for _ in range(clen // 4):
            _ackn.append(self._read_unpack(4))

        ack_data = dict(
            type=desc,
            critical=cbit,
            length=clen,
            ack=tuple(_ackn),
        )

        return ack_data

