def validate_uuid(value):

    if value and not isinstance(value, UUID):
        try:
            return UUID(str(value), version=4)
        except (AttributeError, ValueError):
            raise ValidationError('not a valid UUID')
    return value

def parsing(**kwargs):

    from .validators import Object
    with _VALIDATOR_FACTORIES_LOCK:
        old_values = {}
        for key, value in iteritems(kwargs):
            if value is not None:
                attr = key.upper()
                old_values[key] = getattr(Object, attr)
                setattr(Object, attr, value)
        try:
            yield
        finally:
            for key, value in iteritems(kwargs):
                if value is not None:
                    setattr(Object, key.upper(), old_values[key])

def preprocessRequest(self, service_request, *args, **kwargs):
        processor = self.getPreprocessor(service_request)

        if self.logger:
            self.logger.debug('Preprocessor expands to: %r' % processor)

        if processor is None:
            return

        args = (service_request,) + args

        if hasattr(processor, '_pyamf_expose_request'):
            http_request = kwargs.get('http_request', None)
            args = (http_request,) + args

        return defer.maybeDeferred(processor, *args)

def get_field(self, name):
        # TODO could use a generator here
        prog = re.compile(name)
        l = []
        for i in self.get_classes():
            for j in i.get_fields():
                if prog.match(j.get_name()):
                    l.append(j)
        return l

