def gen_otu_dict(nex_obj, nexson_version=None):
    if nexson_version is None:
        nexson_version = detect_nexson_version(nex_obj)
    if _is_by_id_hbf(nexson_version):
        otus = nex_obj['nexml']['otusById']
        if len(otus) > 1:
            d = {}
            for v in otus.values():
                d.update(v['otuById'])
            return d
        else:
            return otus.values()[0]['otuById']
    o_dict = {}
    for ob in nex_obj.get('otus', []):
        for o in ob.get('otu', []):
            oid = o['@id']
            o_dict[oid] = o
    return o_dict

def service_upsert(path, service_name, definition):
    compose_result, loaded_definition, err = __load_compose_definitions(path, definition)
    if err:
        return err
    services = compose_result['compose_content']['services']
    if service_name in services:
        # Check for an existing service to prevent overwriting the current definition.
        msg = 'Service {0} already exists'.format(service_name)
        return __standardize_result(False, msg, None, None)
    services[service_name] = loaded_definition
    return __dump_compose_file(path, compose_result,
                               'Service definition for {0} is set'.format(service_name),
                               already_existed=True)

def to_cli_filter(bool_or_filter):
    if not isinstance(bool_or_filter, (bool, CLIFilter)):
        raise TypeError('Expecting a bool or a CLIFilter instance. Got %r' % bool_or_filter)

    return {
        True: _always,
        False: _never,
    }.get(bool_or_filter, bool_or_filter)

