def get_local_addr(self, timeout=None):

        # If we're not running, just return None
        if not self.running:
            return None

        # OK, we're running; wait on the _local_addr_event
        if not self._local_addr_event.wait(timeout):
            # Still not set after timeout
            return None

        # We have a local address!
        return self._local_addr

def from_command_line(command_line):
    assert is_iterable_typed(command_line, basestring)
    targets = []
    properties = []

    for e in command_line:
        if e[:1] != "-":
            # Build request spec either has "=" in it, or completely
            # consists of implicit feature values.
            if e.find("=") != -1 or looks_like_implicit_value(e.split("/")[0]):
                properties.append(e)
            elif e:
                targets.append(e)

    return [targets, properties]

def acquire(self, waitflag=None):
        if waitflag is None or waitflag:
            self.locked_status = True
            return True
        else:
            if not self.locked_status:
                self.locked_status = True
                return True
            else:
                return False

