def cmd(self, fun, *args, **kwargs):
        func = self.sminion.functions[fun]
        data = {
          'arg': args,
          'fun': fun
        }
        data.update(kwargs)
        executors = getattr(self.sminion, 'module_executors', []) or \
                    self.opts.get('module_executors', ['direct_call'])
        if isinstance(executors, six.string_types):
            executors = [executors]
        for name in executors:
            fname = '{0}.execute'.format(name)
            if fname not in self.sminion.executors:
                raise SaltInvocationError("Executor '{0}' is not available".format(name))
            return_data = self.sminion.executors[fname](self.opts, data, func, args, kwargs)
            if return_data is not None:
                break
        return return_data

def get_go2color_users(self,
                           usrgo_color='#feffa3', # yellow
                           hdrusrgo_color='#d4ffea', # green
                           hdrgo_color='#eee6f6'): # purple
        go2color = {}
        # Color user GO IDs
        for goid in self.usrgos:
            go2color[goid] = usrgo_color
        # Color header GO IDs. Headers which are also GO IDs get their own color.
        for goid_hdr in self.hdrgos_actual:
            go2color[goid_hdr] = hdrusrgo_color if goid_hdr in self.usrgos else hdrgo_color
        return go2color

def _merge_asized(base, other, level=0):
    ref2key = lambda ref: ref.name.split(':')[0]
    base.size += other.size
    base.flat += other.flat
    if level > 0:
        base.name = ref2key(base)
    # Add refs from other to base. Any new refs are appended.
    base.refs = list(base.refs) # we may need to append items
    refs = {}
    for ref in base.refs:
        refs[ref2key(ref)] = ref
    for ref in other.refs:
        key = ref2key(ref)
        if key in refs:
            _merge_asized(refs[key], ref, level=level+1)
        else:
            # Don't modify existing Asized instances => deepcopy
            base.refs.append(deepcopy(ref))
            base.refs[-1].name = key

def sequence_matcher_similarity(state_a, state_b):
        addrs_a = tuple(state_a.history.bbl_addrs)
        addrs_b = tuple(state_b.history.bbl_addrs)
        return SequenceMatcher(a=addrs_a, b=addrs_b).ratio()

def _register_task(self, output_type, rule, union_rules):
    func = Function(self._to_key(rule.func))
    self._native.lib.tasks_task_begin(self._tasks, func, self._to_type(output_type), rule.cacheable)
    for selector in rule.input_selectors:
      self._native.lib.tasks_add_select(self._tasks, self._to_type(selector))

    def add_get_edge(product, subject):
      self._native.lib.tasks_add_get(self._tasks, self._to_type(product), self._to_type(subject))

    for the_get in rule.input_gets:
      union_members = union_rules.get(the_get.subject_declared_type, None)
      if union_members:
        # If the registered subject type is a union, add Get edges to all registered union members.
        for union_member in union_members:
          add_get_edge(the_get.product, union_member)
      else:
        # Otherwise, the Get subject is a "concrete" type, so add a single Get edge.
        add_get_edge(the_get.product, the_get.subject_declared_type)

    self._native.lib.tasks_task_end(self._tasks)

def referenceLengths(self):
        result = {}
        with samfile(self.filename) as sam:
            if self.referenceIds:
                for referenceId in self.referenceIds:
                    tid = sam.get_tid(referenceId)
                    if tid == -1:
                        raise UnknownReference(
                            'Reference %r is not present in the SAM/BAM file.'
                            % referenceId)
                    else:
                        result[referenceId] = sam.lengths[tid]
            else:
                result = dict(zip(sam.references, sam.lengths))

        return result

def start_task(self, task):
        self.info("Calculating {}...".format(task))
