def mock_import(do_not_mock=None, **mock_kwargs):

    do_not_mock = _to_list(do_not_mock)

    def try_import(module_name, *args, **kwargs):
        try:
            return _builtins_import(module_name, *args, **kwargs)
        except:    # intentionally catch all exceptions
            if any((_match(module_name, prefix) for prefix in do_not_mock)):
                # This is a module we need to import,
                # so we raise the exception instead of mocking it
                raise
            # Mock external module so we can peacefully create our client
            return mock.MagicMock(**mock_kwargs)

    return mock.patch('six.moves.builtins.__import__', try_import)

def visit_boolop(self, node):
        values = ["%s" % self._precedence_parens(node, n) for n in node.values]
        return (" %s " % node.op).join(values)

def add_item(self, key, value, after=False, index=None, pos_key=None,
            replace=True):
        if self._validate_fn:
            self._validate_fn(value)

        if (index is not None) and (pos_key is not None):
            raise ValueError('Either specify index or pos_key, not both.')
        elif pos_key is not None:
            try:
                index = self.index(pos_key)
            except ValueError:
                raise KeyError('%r not found' % pos_key)

        if after and (index is not None):
            # insert inserts *before* index, so increment by one.
            index += 1

        if key in self._values:
            if not replace:
                raise KeyError('%r is duplicate' % key)

            if index is not None:
                # We are re-locating.
                del self[key]
            else:
                # We are updating
                self._values[key] = value
                return

        if index is not None:
            # Place at given position
            self._order.insert(index, key)
        else:
            # Place at end
            self._order.append(key)
        self._values[key] = value

