def enabled(self):
        # Check if the process status is unsupported before querying the kernel.
        if self._status == self.SR_UNSUPPORTED:
            return False
        status = c_int()
        try:
            prctl(PR_GET_CHILD_SUBREAPER, addressof(status), 0, 0, 0)
        except OSError:
            self._status = self.SR_UNSUPPORTED
        else:
            self._status = self.SR_ENABLED if status else self.SR_DISABLED
            return self._status == self.SR_ENABLED

def put(self, data, **kwargs):
        grid_file = GridIn(self.__collection, **kwargs)

        def _finally(result):
            return grid_file.close().addCallback(lambda _: result)

        return grid_file.write(data)\
            .addBoth(_finally)\
            .addCallback(lambda _: grid_file._id)

