def gym_space_spec(gym_space):
  # First try to determine the type.
  try:
    tf_dtype = tf.as_dtype(gym_space.dtype)
  except TypeError as e:
    tf.logging.error("Cannot convert space's type [%s] to tf.dtype",
                     gym_space.dtype)
    raise e

  # Now hand it over to the specialized functions.
  if isinstance(gym_space, Box):
    return box_space_spec(gym_space, tf_dtype)
  elif isinstance(gym_space, Discrete):
    return discrete_space_spec(gym_space, tf_dtype)
  else:
    raise NotImplementedError

def transitions(self, return_matrix=True):
        if return_matrix:
            mat = np.zeros((self.nV, self.nV))
            for v in self.g.nodes():
                ind = [e[1] for e in sorted(self.g.out_edges(v))]
                mat[v, ind] = self._route_probs[v]
        else:
            mat = {
                k: {e[1]: p for e, p in zip(sorted(self.g.out_edges(k)), value)}
                for k, value in enumerate(self._route_probs)
            }

        return mat

def get_referenced_fields_and_fragment_names(
    context: ValidationContext,
    cached_fields_and_fragment_names: Dict,
    fragment: FragmentDefinitionNode,
) -> Tuple[NodeAndDefCollection, List[str]]:
    # Short-circuit building a type from the node if possible.
    cached = cached_fields_and_fragment_names.get(fragment.selection_set)
    if cached:
        return cached

    fragment_type = type_from_ast(context.schema, fragment.type_condition)
    return get_fields_and_fragment_names(
        context, cached_fields_and_fragment_names, fragment_type, fragment.selection_set
    )

