def showHeaderMenu( self, pos):
        header = self.header()
        index  = header.logicalIndexAt(pos)
        self._headerIndex = index

        # show a pre-set menu
        if self._headerMenu:
            menu = self._headerMenu
        else:
            menu = self.createHeaderMenu(index)

        # determine the point to show the menu from
        if pos is not None:
            point = header.mapToGlobal(pos)
        else:
            point = QtGui.QCursor.pos()

        self.headerMenuAboutToShow.emit(menu, index)
        menu.exec_(point)

def push(self):
        if self.renderer.mode == 'server':
            return
        if self.comm is None:
            raise Exception('Renderer does not have a comm.')

        if self._root and 'embedded' in self._root.tags:
            # Allows external libraries to prevent comm updates
            return

        msg = self.renderer.diff(self, binary=True)
        if msg is None:
            return
        self.comm.send(msg.header_json)
        self.comm.send(msg.metadata_json)
        self.comm.send(msg.content_json)
        for header, payload in msg.buffers:
            self.comm.send(json.dumps(header))
            self.comm.send(buffers=[payload])

