def _get_magnitude_scaling_term(self, C, rup):
        dmag = rup.mag - C["Mh"]
        if rup.mag <= C["Mh"]:
            mag_term = (C["e4"] * dmag) + (C["e5"] * (dmag ** 2.0))
        else:
            mag_term = C["e6"] * dmag
        return self._get_style_of_faulting_term(C, rup) + mag_term

