def format_exp_floats(decimals):
    threshold = 10 ** 5
    return (
        lambda n: "{:.{prec}e}".format(n, prec=decimals) if n > threshold else "{:4.{prec}f}".format(n, prec=decimals)
    )

def format_throughput(available, used=None):
    if used is None:
        return str(available)
    percent = float(used) / available
    return "{0:.0f}/{1:.0f} ({2:.0%})".format(used, available, percent)

def _make_message_type(name, attributes, has_data=True):

  def assert_command_is(self, command):  # pylint: disable=invalid-name
    """Assert that a message's command matches the given command."""
    if self.command != command:
      raise usb_exceptions.AdbProtocolError(
          'Expected %s command, received %s', command, self)

  return type(name, (collections.namedtuple(name, attributes),),
              {
                  'assert_command_is': assert_command_is,
                  'has_data': has_data,
                  # Struct format on the wire has an unsigned int for each attr.
                  'struct_format': '<%sI' % len(attributes.split()),
              })

def make_signature(params, hmac_key):
    # produce a list of "key=value" for all entries in params except `h'
    pairs = [x + "=" + ''.join(params[x]) for x in sorted(params.keys()) if x != "h"]
    sha = hmac.new(hmac_key, '&'.join(pairs), hashlib.sha1)
    return base64.b64encode(sha.digest())

def check_for_interest(self, client, recipient, message):
        for prefix in self.prefixes:
            if message.startswith(prefix):
                return True, message[len(prefix):]

        # Don't require a prefix if addressed in PM.
        # This comes after the prefix checks because
        # if the user does include a prefix, we want
        # to strip it, even in PM.
        if not isinstance(recipient, Channel):
            return True, message

        return False, None

def initMazeFromJSON(jsonString, cellClass=Cell, gridClass=Grid):

    jsonObj = json.loads(jsonString)
    rows=jsonObj["rows"]
    columns=jsonObj["columns"]
    grid=gridClass(rows,columns,cellClass)
    grid.algorithm=jsonObj["algorithm"]
    grid.algorithm_key=jsonObj["algorithm_key"]
    grid.braid=jsonObj["braid"]

    #init cells
    #for each cell link those that are neigbors
    for _cell in jsonObj["cells"]:
        cell=json.loads(_cell)
        gridCell=grid.getCell(cell["row"],cell["column"])
        if "content" in cell:
            gridCell.content=cell["content"]
        else:
            gridCell.setContent(" ")

        if cell["north"]:
            gridCell.link(gridCell.north)
        if cell["east"]:
            gridCell.link(gridCell.east)
        if cell["south"]:
            gridCell.link(gridCell.south)
        if cell["west"]:
            gridCell.link(gridCell.west)

    return grid

