def _chunks(self, iterable, chunk_size):
        iterator = iter(iterable)
        chunk = list(itertools.islice(iterator, 0, chunk_size))
        while chunk:
            yield chunk
            chunk = list(itertools.islice(iterator, 0, chunk_size))

def set_attributes(self, **kwargs):
        self.clear_derived()
        kwargs = dict(kwargs)
        for name, value in kwargs.items():
            # Raise AttributeError if param not found
            try:
                self.getp(name)
            except KeyError:
                print ("Warning: %s does not have attribute %s" %
                       (type(self), name))
            # Set attributes
            try:
                self.setp(name, clear_derived=False, **value)
            except TypeError:
                try:
                    self.setp(name, clear_derived=False, *value)
                except (TypeError, KeyError):
                    try:
                        self.setp(name, clear_derived=False, value=value)
                    except (TypeError, KeyError):
                        self.__setattr__(name, value)
            # pop this attribued off the list of missing properties
            self._missing.pop(name, None)
        # Check to make sure we got all the required properties
        if self._missing:
            raise ValueError(
                "One or more required properties are missing ",
                self._missing.keys())

def wrapinstance(ptr, base=None):
    if ptr is None:
        return None
    ptr = long(ptr)  # Ensure type
    from wishlib.qt import active, QtCore, QtGui
    if active == "PySide":
        import shiboken
        if base is None:
            qObj = shiboken.wrapInstance(ptr, QtCore.QObject)
            metaObj = qObj.metaObject()
            cls = metaObj.className()
            superCls = metaObj.superClass().className()
            if hasattr(QtGui, cls):
                base = getattr(QtGui, cls)
            elif hasattr(QtGui, superCls):
                base = getattr(QtGui, superCls)
            else:
                base = QtGui.QWidget
        return shiboken.wrapInstance(ptr, base)
    elif active == "PyQt4":
        import sip
        return sip.wrapinstance(ptr, QtGui.QWidget)
    return None

def set(self, name, value):
        curr = self.values
        parts = name.split('.')

        for i, part in enumerate(parts[:-1]):
            try:
                curr = curr.setdefault(part, {})
            except AttributeError:
                raise InvalidPath('.'.join(parts[:i + 1]))

        try:
            curr[parts[-1]] = value
        except TypeError:
            raise InvalidPath('.'.join(parts[:-1]))

def durables(self):
        results = dict()

        for child in self.connection.retry(self.connection.get_children, self.keyspace):
            value, _ = self.connection.retry(
                self.connection.get,
                self.__path_of(child),
                watch=self.__increment_last_updated
            )
            results[child] = self.encoding.decode(value)

        return results

def turbulent_Petukhov_Kirillov_Popov(Re=None, Pr=None, fd=None):
    C = 1.07 + 900./Re - (0.63/(1. + 10.*Pr))
    return (fd/8.)*Re*Pr/(C + 12.7*(fd/8.)**0.5*(Pr**(2/3.) - 1.))

