    raise Exception("??? median ???")

def fetch_streams_with_retry(plugin, interval, count):

    try:
        streams = fetch_streams(plugin)
    except PluginError as err:
        log.error(u"{0}", err)
        streams = None

    if not streams:
        log.info("Waiting for streams, retrying every {0} "
                 "second(s)", interval)
    attempts = 0

    while not streams:
        sleep(interval)

        try:
            streams = fetch_streams(plugin)
        except FatalPluginError as err:
            raise
        except PluginError as err:
            log.error(u"{0}", err)

        if count > 0:
            attempts += 1
            if attempts >= count:
                break

    return streams

def push_doc(self, document):
        msg = self._protocol.create('PUSH-DOC', document)
        reply = self._send_message_wait_for_reply(msg)
        if reply is None:
            raise RuntimeError("Connection to server was lost")
        elif reply.header['msgtype'] == 'ERROR':
            raise RuntimeError("Failed to push document: " + reply.content['text'])
        else:
            return reply

