            {
                Msgs.cmd: Cmds.run_dict_method,
                Msgs.info: dict_method_name,
                Msgs.args: args,
                Msgs.kwargs: kwargs,
            }
        )

    remote_method.__name__ = dict_method_name
    return remote_method

def napi_compare(left, ops, comparators, **kwargs):

    values = []
    for op, right in zip(ops, comparators):
        value = COMPARE[op](left, right)
        values.append(value)
        left = right
    result = napi_and(values, **kwargs)
    if isinstance(result, ndarray):
        return result
    else:
        return bool(result)

