def remove_aspera_coordinator(self, transfer_coordinator):
        # usually called on processing completion - but can be called for a cancel
        if self._in_waiting_queue(transfer_coordinator):
            logger.info("Remove from waiting queue count=%d" % self.waiting_coordinator_count())
            with self._lockw:
                self._waiting_transfer_coordinators.remove(transfer_coordinator)
        else:
            logger.info("Remove from processing queue count=%d" % self.tracked_coordinator_count())
            try:
                self.remove_transfer_coordinator(transfer_coordinator)
                self.append_processed_queue(transfer_coordinator)
            except Exception:
                pass

            self._wakeup_processing_thread()

def register_fn(cls, f):
        def inner(self, *args, **kwargs):
            try:
                query, projection, options = cls.unpack_scope(f(*args, **kwargs))
                new_query = deepcopy(self.query)
                new_projection = deepcopy(self.projection)
                new_options = deepcopy(self.options)
                deep_merge(query, new_query)
                new_projection.update(projection)
                new_options.update(options)
                return ScopeBuilder(self.model, self.fns, new_query,
                    new_projection, new_options)
            except ValueError:
                raise ValueError("Scope function \"{}\ returns an invalid scope".format(f.__name__))

        setattr(cls, f.__name__, inner)

def json_numpy_obj_hook(dct):
    if isinstance(dct, dict) and '__ndarray__' in dct:
        array = dct['__ndarray__']
        # http://stackoverflow.com/questions/24369666/typeerror-b1-is-not-json-serializable
        if sys.version_info >= (3, 0):
            array = array.encode('utf-8')
        data = base64.b64decode(array)
        if has_blosc:
            data = blosc.decompress(data)

        try:
            dtype = np.dtype(ast.literal_eval(dct['dtype']))
        except ValueError:  # If the array is not a recarray
            dtype = dct['dtype']

        return np.frombuffer(data, dtype).reshape(dct['shape'])

    return dct

def request(self, uri, method=GET, headers=None, cookies=None, params=None, data=None, post_files=None,**kwargs):

        coyote_args = {
            'headers': headers,
            'cookies': cookies,
            'params': params,
            'files': post_files,
            'data': data,
            'verify': self.verify_certificates,

        }

        coyote_args.update(kwargs)

        if method == self.POST:
            response = self.session.post(uri, **coyote_args)

        elif method == self.PUT:
            response = self.session.put(uri, **coyote_args)

        elif method == self.PATCH:
            response = self.session.patch(uri, **coyote_args)

        elif method == self.DELETE:
            response = self.session.delete(uri, **coyote_args)

        else:  # Default to GET
            response = self.session.get(uri, **coyote_args)

        self.responses.append(response)

        while len(self.responses) > self.max_response_history:
            self.responses.popleft()

        return response

def cached_tree(self, subject_ids=None, visit_ids=None, fill=False):
        if subject_ids is not None:
            subject_ids = frozenset(subject_ids)
        if visit_ids is not None:
            visit_ids = frozenset(visit_ids)
        try:
            tree = self._cache[subject_ids][visit_ids]
        except KeyError:
            if fill:
                fill_subjects = subject_ids
                fill_visits = visit_ids
            else:
                fill_subjects = fill_visits = None
            tree = self.tree(
                subject_ids=subject_ids, visit_ids=visit_ids,
                fill_visits=fill_visits, fill_subjects=fill_subjects)
            # Save the tree within the cache under the given subject/
            # visit ID filters and the IDs that were actually returned
            self._cache[subject_ids][visit_ids] = self._cache[
                frozenset(tree.subject_ids)][frozenset(tree.visit_ids)] = tree
        return tree

