def creep_kill(self, target, timestamp):
        self.creep_kill_types[target] += 1

        matched = False
        for k, v in self.creep_types.iteritems():
            if target.startswith(k):
                matched = True
                setattr(self, v, getattr(self, v) + 1)
                break

        if not matched:
            print('> unhandled creep type'.format(target))

def parse_int(v, header_d):

    v = nullify(v)

    if v is None:
        return None

    try:
        # The converson to float allows converting float strings to ints.
        # The conversion int('2.134') will fail.
        return int(round(float(v), 0))
    except (TypeError, ValueError) as e:
        raise CastingError(int, header_d, v, 'Failed to cast to integer')

def join_struct_arrays(arrays):
    # taken from http://stackoverflow.com/questions/5355744/numpy-joining-structured-arrays
    sizes = np.array([a.itemsize for a in arrays])
    offsets = np.r_[0, sizes.cumsum()]
    shape = arrays[0].shape
    joint = np.empty(shape + (offsets[-1],), dtype=np.uint8)
    for a, size, offset in zip(arrays, sizes, offsets):
        joint[...,offset:offset+size] = np.atleast_1d(a).view(np.uint8).reshape(shape + (size,))
    dtype = sum((a.dtype.descr for a in arrays), [])
    return joint.ravel().view(dtype)

