def minimise_table(table, target_length,
                   methods=(remove_default_entries, ordered_covering)):
    # Add a final method which checks the size of the table and returns it if
    # the size is correct. NOTE: This method will avoid running any other
    # minimisers if the table is already sufficiently small.
    methods = list(methods)
    methods.insert(0, _identity)

    if target_length is not None:
        best_achieved = len(table)

        # Try each minimiser in turn until the table is small enough
        for f in methods:
            try:
                # Minimise the table, if this fails a MinimisationFailedError
                # will be raised and the return will not be executed.
                new_table = f(table, target_length)
                return new_table
            except MinimisationFailedError as exc:
                # Store the best achieved final length
                if best_achieved is None or exc.final_length < best_achieved:
                    best_achieved = exc.final_length

        # The table must still be too large
        raise MinimisationFailedError(target_length, best_achieved)
    else:
        # Try all methods and return the smallest table
        return min((f(table, target_length) for f in methods), key=len)

def dump_dh_parameters(dh_parameters, encoding='pem'):

    if encoding not in set(['pem', 'der']):
        raise ValueError(pretty_message(
            '''
            encoding must be one of "pem", "der", not %s
            ''',
            repr(encoding)
        ))

    if not isinstance(dh_parameters, algos.DHParameters):
        raise TypeError(pretty_message(
            '''
            dh_parameters must be an instance of asn1crypto.algos.DHParameters,
            not %s
            ''',
            type_name(dh_parameters)
        ))

    output = dh_parameters.dump()
    if encoding == 'pem':
        output = pem.armor('DH PARAMETERS', output)
    return output

def index_whichnot(ol,value,which):
    length = ol.__len__()
    seq = -1
    for i in range(0,length):
        if(value == ol[i]):
            pass
        else:
            seq = seq + 1
            if(seq == which):
                return(i)
            else:
                pass
    return(None)

def query(self):
        queryWidget = self.queryWidget()

        # check to see if there is an active container for this widget
        container = queryWidget.containerFor(self)
        if container:
            return container.query()

        elif QueryCompound.typecheck(self._query):
            return self._query

        # generate a new query from the editor
        column = self.uiColumnDDL.currentSchemaPath()
        plugin = self.currentPlugin()
        editor = self.editor()
        op     = self.uiOperatorDDL.currentText()

        if column and plugin:
            query = Query(column)
            plugin.setupQuery(query, op, editor)
            return query
        else:
            return Query()

def dms2dd(degrees, minutes, seconds, direction):
    dd = (degrees + minutes/60.0) + (seconds/3600.0)           # 60.0 fraction for python 2+ compatibility
    return dd * -1 if direction == 'S' or direction == 'W' else dd

def check_each_direction(n,angs,ifprint=True):
    checks = np.array([])
    P = np.array([])
    if(ifprint):
        print("\nChecking modes:\n====")
    for k,i in enumerate(n):
        N_matrix = np.linalg.norm(i)
        X = np.dot(angs,i)
        if(np.abs(np.max(X)-np.min(X))<2.*np.pi):
            if(ifprint):
                print("Need a longer integration window for mode ", i)
            checks=np.append(checks,i)
            P = np.append(P,(2.*np.pi-np.abs(np.max(X)-np.min(X))))
        elif(np.abs(np.max(X)-np.min(X))/len(X)>np.pi):
            if(ifprint):
                print("Need a finer sampling for mode ", i)
            checks=np.append(checks,i)
            P = np.append(P,(2.*np.pi-np.abs(np.max(X)-np.min(X))))
    if(ifprint):
        print("====\n")
    return checks,P

def parse(self, nodes):
    self.last_node_type = self.initial_node_type
    for node_number, node in enumerate(nodes):
      try:
        self.step(node)
      except Exception as ex:
        raise Exception("An error occurred on node {}".format(node_number)) from ex

def multi_match(name, patterns, mode=any, regex=False):
    if not regex:
        return mode(fnmatch.fnmatch(name, pattern) for pattern in patterns)
    else:
        return mode(re.match(pattern, name) for pattern in patterns)

