def load_cookies(self):
        if not self.session or not self.cache:
            raise RuntimeError("Cannot loaded cached cookies in unbound plugin")

        restored = []

        for key, value in self.cache.get_all().items():
            if key.startswith("__cookie"):
                cookie = requests.cookies.create_cookie(**value)
                self.session.http.cookies.set_cookie(cookie)
                restored.append(cookie.name)

        if restored:
            self.logger.debug("Restored cookies: {0}".format(", ".join(restored)))
        return restored

def send_payload(self, params):
        data = json.dumps({
            'jsonrpc': self.version,
            'method': self.service_name,
            'params': params,
            'id': text_type(uuid.uuid4())
        })
        data_binary = data.encode('utf-8')
        url_request = Request(self.service_url, data_binary, headers=self.headers)
        return urlopen(url_request).read()

def external_incompatibilities(self):  # type: () -> Generator[Incompatibility]
        if isinstance(self._cause, ConflictCause):
            cause = self._cause  # type: ConflictCause
            for incompatibility in cause.conflict.external_incompatibilities:
                yield incompatibility

            for incompatibility in cause.other.external_incompatibilities:
                yield incompatibility
        else:
            yield self

def _estimate(self, buffer):
        m = self._bucket_number
        raw_e = self._alpha * pow(m, 2) / sum([pow(2, -x) for x in buffer])
        if raw_e <= 5 / 2.0 * m:
            v = buffer.count(0)
            if v != 0:
                return m * log(m / float(v), 2)
            else:
                return raw_e
        elif raw_e <= 1 / 30.0 * 2 ** 160:
            return raw_e
        else:
            return -2 ** 160 * log(1 - raw_e / 2.0 ** 160, 2)

