def push(self, set_upstream: bool = True):
        LOGGER.info('pushing repo to origin')

        try:
            self.repo.git.push()
        except GitCommandError as error:
            if 'has no upstream branch' in error.stderr and set_upstream:
                self.repo.git.push(f'--set-upstream origin {self.get_current_branch()}')
            else:
                raise
        self.push_tags()

def emit(self, msg, level=1, debug=False):

        # Is it a debug message?
        if debug:
            if not self.debug:
                # Debugging not enabled, don't emit the message
                return
            stream = sys.stderr
        else:
            # Not a debugging message; is verbose high enough?
            if self.verbose < level:
                return
            stream = sys.stdout

        # Emit the message
        print(msg, file=stream)
        stream.flush()

