def split_kwargs(relaxation_kwds):
    optimizer_keys_list = [
        'step_method',
        'linesearch',
        'eta_max',
        'eta',
        'm',
        'linesearch_first'
    ]
    optimizer_kwargs = { k:relaxation_kwds.pop(k) for k in optimizer_keys_list if k in relaxation_kwds }
    if 'm' in optimizer_kwargs:
        optimizer_kwargs['momentum'] = optimizer_kwargs.pop('m')
    return optimizer_kwargs, relaxation_kwds

def save(self):
        saved = 0
        if not self.objects:
            raise BatchError("Save failed. Batch is empty")
        for deserialized_tx in self.objects:
            try:
                self.model.objects.get(pk=deserialized_tx.pk)
            except self.model.DoesNotExist:
                data = {}
                for field in self.model._meta.get_fields():
                    try:
                        data.update({field.name: getattr(deserialized_tx, field.name)})
                    except AttributeError:
                        pass
                self.model.objects.create(**data)
                saved += 1
        return saved

