def create_celerybeat_schedule(apps):
    beat_schedule = {}
    for app in apps:
        try:
            config = import_object_by_string(app)
            module = importlib.import_module('{}.cron'.format(config.name))
        except Exception:
            try:
                module = importlib.import_module('{}.cron'.format(app))
            except Exception:
                continue

        if not (hasattr(module, 'schedule') and isinstance(module.schedule, dict)):
            logger.warning('{} has no schedule or schedule is not a dict'.format(module.__name__))
            continue

        # Add cron queue option
        for name, schedule in module.schedule.items():
            options = schedule.get('options', {})
            if 'queue' not in options:
                options['queue'] = 'cron'
                schedule['options'] = options

                beat_schedule[name] = schedule

    return beat_schedule

def get_elastix_exes():
    if EXES:
        if EXES[0]:
            return EXES
        else:
            raise RuntimeError('No Elastix executable.')

    # Find exe
    elastix, ver = _find_executables('elastix')
    if elastix:
        base, ext = os.path.splitext(elastix)
        base = os.path.dirname(base)
        transformix = os.path.join(base, 'transformix' + ext)
        EXES.extend([elastix, transformix])
        print('Found %s in %r' % (ver, elastix))
        return EXES
    else:
        raise RuntimeError('Could not find Elastix executable. Download '
                           'Elastix from http://elastix.isi.uu.nl/. Pyelastix '
                           'looks for the exe in a series of common locations. '
                           'Set ELASTIX_PATH if necessary.')

