def md5_hash_file(fh):
    md5 = hashlib.md5()
    while True:
        data = fh.read(8192)
        if not data:
            break
        md5.update(data)
    return md5.hexdigest()

def extract_dates(obj):
    if isinstance(obj, dict):
        obj = dict(obj) # don't clobber
        for k,v in obj.iteritems():
            obj[k] = extract_dates(v)
    elif isinstance(obj, (list, tuple)):
        obj = [ extract_dates(o) for o in obj ]
    elif isinstance(obj, basestring):
        if ISO8601_PAT.match(obj):
            obj = datetime.strptime(obj, ISO8601)
    return obj

def state_to_modelparams(self, state):
        basis = self.flat()
        data = state.data.todense().view(np.ndarray).flatten()

        # NB: assumes Hermitian state and basis!
        return np.real(np.dot(basis.conj(), data))

def walk_preorder(self):
        yield self
        for child in self.get_children():
            for descendant in child.walk_preorder():
                yield descendant

def from_iter(cls, data, name=None):

        if not name:
            name = 'table'
        if isinstance(data, (list, tuple)):
            data = {x: y for x, y in enumerate(data)}

        values = [{'idx': k, 'col': 'data', 'val': v}
                  for k, v in sorted(data.items())]
        return cls(name, values=values)

