            coords = lattice.get_cartesian_coords(coords)
        ax.text(*(coords + off), s=label, **kwargs)

    return fig, ax

def _call(self, method_proxy, *args):
        request = self._gw.addRequest(method_proxy, *args)

        if self._auto_execute:
            response = self._gw.execute_single(request)

            if response.status == remoting.STATUS_ERROR:
                if hasattr(response.body, 'raiseException'):
                    try:
                        response.body.raiseException()
                    except:
                        raise
                else:
                    raise remoting.RemotingError

            return response.body

        return request

def poisson_source(rate, iterable, target):
    if rate <= 0.0:
        raise ValueError("poisson_source rate {} is not positive".format(rate))

    it = iter(iterable)
    for item in it:
        duration = random.expovariate(rate)
        sleep(duration)
        try:
            target.send(item)
        except StopIteration:
            return prepend(item, it)
    return empty_iter()

def parse_lcov_file_info(args, filepath, line_iter, line_coverage_re, file_end_string):
    coverage = []
    lines_covered = []
    for line in line_iter:
        if line != "end_of_record":
            line_coverage_match = line_coverage_re.match(line)
            if line_coverage_match:
                line_no = line_coverage_match.group(1)
                cov_count = int(line_coverage_match.group(2))
                if args.max_cov_count:
                    if cov_count > args.max_cov_count:
                        cov_count = args.max_cov_count + 1
                lines_covered.append((line_no, cov_count))
        else:
            break

    num_code_lines = len([line.rstrip('\n') for line in open(filepath, 'r')])
    coverage = [None] * num_code_lines
    for line_covered in lines_covered:
        coverage[int(line_covered[0]) - 1] = line_covered[1]

    return coverage

def get_initial_state(self, source_length: mx.sym.Symbol, source_seq_len: int) -> AttentionState:
        dynamic_source = mx.sym.reshape(mx.sym.zeros_like(source_length), shape=(-1, 1, 1))
        # dynamic_source: (batch_size, source_seq_len, num_hidden_dynamic_source)
        dynamic_source = mx.sym.broadcast_to(dynamic_source, shape=(0, source_seq_len, self.dynamic_source_num_hidden))
        return AttentionState(context=None, probs=None, dynamic_source=dynamic_source)

