def get_EOL(file):
    f = open(file, 'r')
    firstline = f.read(350)
    EOL = ""
    for k in range(350):
        if firstline[k:k + 2] == "\r\n":
            print(file, ' appears to be a dos file')
            EOL = '\r\n'
            break
    if EOL == "":
        for k in range(350):
            if firstline[k] == "\r":
                print(file, ' appears to be a mac file')
                EOL = '\r'
    if EOL == "":
        print(file, " appears to be a  unix file")
        EOL = '\n'
    f.close()
    return EOL

def cumulative_distribution(self, X):
        self.check_fit()

        # Wrapper for pdf to accept vector as args
        def func(*args):
            return self.probability_density(list(args))

        # Lower bound for integral, to split significant part from tail
        lower_bound = self.get_lower_bound()

        ranges = [[lower_bound, val] for val in X]
        return integrate.nquad(func, ranges)[0]

