def visit_Dict(self, node):
        if node.keys:
            elts_aliases = set()
            for key, val in zip(node.keys, node.values):
                self.visit(key)  # res ignored, just to fill self.aliases
                elt_aliases = self.visit(val)
                elts_aliases.update(map(ContainerOf, elt_aliases))
        else:
            elts_aliases = None
        return self.add(node, elts_aliases)

def package_to_directory(package_path: str) -> str:
    if '/' in package_path:
        pkgname, subpath = package_path.split('/', 1)
    else:
        pkgname, subpath = package_path, ''

    module = import_module(pkgname)
    path = Path(module.__spec__.origin).parent / subpath
    if path.exists():
        if path.is_dir():
            return str(path)
        else:
            raise LookupError('{} is not a directory'.format(path))
    else:
        raise LookupError('{} does not exist'.format(path))

