def get_dimension_permutations(entities, dimensions):
    new_dimensions = defaultdict(int)
    for item in dimensions:
        new = entities[item['base']].dimensions
        if new:
            for new_item in new:
                new_dimensions[new_item['base']] += new_item['power'] * \
                                                 item['power']
        else:
            new_dimensions[item['base']] += item['power']

    final = [[{'base': i[0], 'power': i[1]} for i in new_dimensions.items()]]
    final.append(dimensions)
    final = [sorted(i, key=lambda x: x['base']) for i in final]

    candidates = []
    for item in final:
        if item not in candidates:
            candidates.append(item)

    return candidates

def getCanonicalRep(record_cluster):
    canonical_rep = {}

    keys = record_cluster[0].keys()

    for key in keys:
        key_values = []
        for record in record_cluster:
            # assume non-empty values always better than empty value
            # for canonical record
            if record[key]:
                key_values.append(record[key])
        if key_values:
            canonical_rep[key] = getCentroid(key_values, comparator)
        else:
            canonical_rep[key] = ''

    return canonical_rep

def resolve_primary_keys_in_schema(sql_tokens: List[str],
                                   schema: Dict[str, List[TableColumn]]) -> List[str]:
    primary_keys_for_tables = {name: max(columns, key=lambda x: x.is_primary_key).name
                               for name, columns in schema.items()}
    resolved_tokens = []
    for i, token in enumerate(sql_tokens):
        if i > 2:
            table_name = sql_tokens[i - 2]
            if token == "ID" and table_name in primary_keys_for_tables.keys():
                token = primary_keys_for_tables[table_name]
        resolved_tokens.append(token)
    return resolved_tokens

def MapFields(function, key=True):
    @use_raw_input
    def _MapFields(bag):
        try:
            factory = type(bag)._make
        except AttributeError:
            factory = type(bag)

        if callable(key):
            try:
                fields = bag._fields
            except AttributeError as e:
                raise UnrecoverableAttributeError(
                    'This transformation works only on objects with named'
                    ' fields (namedtuple, BagType, ...).') from e

            return factory(
                function(value) if key(key_) else value for key_, value in zip(fields, bag)
            )
        elif key:
            return factory(function(value) for value in bag)
        else:
            return NOT_MODIFIED

    return _MapFields

