def _generate_edges(self, edge_prob):
        self.E, self.parent = [], {}
        for i in range(self.m):
            if random() < edge_prob and i > 0:
                p_i = choice(i)
                self.E.append((p_i, i))
                self.parent[i] = p_i

def tempdir(cls, suffix='', prefix=None, dir=None):
        if prefix is None:
            prefix = tempfile.template
        if dir is not None:
            # Note that this is not safe on Python 2
            # There is no work around, apart from not using the tempfile module
            dir = str(Path(dir))
        dirname = tempfile.mkdtemp(suffix, prefix, dir)
        return cls(dirname).absolute()

def terminal(self, text):
    self._attempting(text)
    return alternation([
      concatenation([
        '"',
        one_or_more(
          exclusion(self.printable, '"')
        ),
        '"'
      ], ignore_whitespace=False),
      concatenation([
        "'",
        one_or_more(
          exclusion(self.printable,"'")
        ),
        "'"
      ], ignore_whitespace=False)
    ])(text).compressed(TokenType.terminal)

