def url_builder(self, endpoint, *, root=None, params=None, url_params=None):
        if root is None:
            # Default the root variable to the class constant when no explicit value is provided.
            root = self.ROOT
        scheme, netloc, path, _, _ = urlsplit(root)
        return urlunsplit((
            scheme,
            netloc,
            urljoin(path, endpoint),
            urlencode(url_params or {}),
            '',
        )).format(**params or {})

