def setValue(self, key, value):
        parts = nativestring(key).split('/')
        curr = self._xstack[-1]
        for part in parts[:-1]:
            next = curr.find(part)
            if next is None:
                # Create a new child element for the missing intermediate path segment.
                next = ElementTree.SubElement(curr, part)
            curr = next

        xval = curr.find(parts[-1])
        if xval is None:
            xval = ElementTree.SubElement(curr, parts[-1])

        self.storeValue(xval, value)

