        def _write_bytes(bytes, append):
            if append:
                mode = 'ab'
            else:
                mode = 'wb'
            f = self.open(mode)
            try:
                f.write(bytes)
            finally:
                f.close()

        dry("write_bytes %s '%r...' append=%r" % (self, bytes[:20], append),
            _write_bytes, bytes, append)

