def ip_to_long (ip):
    quad = ip.split('.')
    if len(quad) == 1:
        quad = quad + [0, 0, 0]
    elif len(quad) < 4:
        host = quad[-1:]
        quad = quad[:-1] + [0,] * (4 - len(quad)) + host

    lip = 0
    for q in quad:
        lip = (lip << 8) | int(q)
    return lip

