def safe_kill(pid, signum):
  assert(isinstance(pid, IntegerForPid))
  assert(isinstance(signum, int))
  try:
    os.kill(pid, signum)
  except (IOError, OSError) as e:
    if e.errno in [errno.ESRCH, errno.EPERM]:
      pass
    elif e.errno == errno.EINVAL:
      raise ValueError("Invalid signal number {}: {}"
                       .format(signum, e),
                       e)
    else:
      raise

def ncVarUnit(ncVar):
    attributes = ncVarAttributes(ncVar)
    if not attributes:
        return '' # a premature optimization :-)

    for key in ('unit', 'units', 'Unit', 'Units', 'UNIT', 'UNITS'):
        if key in attributes:
            # In Python3 the attribures are byte strings so we must decode them
            # This a bug in h5py, see https://github.com/h5py/h5py/issues/379
            return attributes[key]
    else:
        return ''

def name(self):
        name_parts = []
        if self.registry:
            name_parts.append(self.registry)

        if self.namespace:
            name_parts.append(self.namespace)

        if self.repository:
            name_parts.append(self.repository)
        name = "/".join(name_parts)

        if self.digest:
            name += "@{}".format(self.digest)
        elif self.tag:
            name += ":{}".format(self.tag)

