def ordered(start, edges, predicate=None, inverse=False):
        s, o = 'sub', 'obj'
        if inverse:
            s, o = o, s
        for edge in edges:
            if predicate is not None and edge['pred'] != predicate:
                print('scoop!')
                continue

            if edge[s] == start:
                yield edge
                yield from Graph.ordered(edge[o], edges, predicate=predicate)

def convert_bytes_to_ints(in_bytes, num):
    dt = numpy.dtype('>i' + str(num))
    return numpy.frombuffer(in_bytes, dt)

def _convert_to_numeric(item):
    if PY3:
        num_types = (int, float)
    else:                                 # pragma: no cover
        num_types = (int, long, float)    # noqa: F821
    # We don't wan't to perform any conversions if item is already a number
    if isinstance(item, num_types):
        return item

    # First try for an int conversion so that strings like "5" are converted
    # to 5 instead of 5.0 . This is safe as a direct int cast for a non integer
    # string raises a ValueError.
    try:
        num = int(to_unicode(item))
    except ValueError:
        try:
            num = float(to_unicode(item))
        except ValueError:
            return item
        else:
            return num
    except TypeError:
        return item
    else:
        return num

def get_options(self):
        (options, args) = self.parser.parse_args()

        # Set values from .visdkrc, but only if they haven't already been set
        visdkrc_opts = self.read_visdkrc()
        for opt in self.config_vars:
            if not getattr(options, opt):
                # Try and use value from visdkrc
                if visdkrc_opts:
                    if opt in visdkrc_opts:
                        setattr(options, opt, visdkrc_opts[opt])

        # Ensure all the required options are set
        for opt in self.required_opts:
            if opt not in dir(options) or getattr(options, opt) == None:
                self.parser.error('%s must be set!' % opt)

        return options

def modeltag_nonref_schemas(spec):

    for path_name, path_data in six.iteritems(spec['paths']):
        for path_cmd, cmd_data in six.iteritems(path_data):

            # check the parameters, looking for "schemas" that
            # do not have $ref or already tagged.  when found
            # use either the operationId or the (command, api-path)
            # to formulate a humanized tag name.

            for param in cmd_data.get('parameters'):
                schema = param.get('schema')
                if schema and ('$ref' not in schema) and (MODEL_MARKER not in schema):
                    model_name = (camelize(cmd_data.get('operationId')) or
                                  "%s%s" % (path_cmd.upper(),
                                            humanize_api_path(path_name)))

                    schema[MODEL_MARKER] = "%s%s" % (model_name, MODEL_NAME_SUFFIX)

