        if fct[1].__class__.__name__ == 'QgsExpressionFunction'}
    all_expressions.update({
        fct[0]: fct[1] for fct in getmembers(infographic)
        if fct[1].__class__.__name__ == 'QgsExpressionFunction'})
    all_expressions.update({
        fct[0]: fct[1] for fct in getmembers(map_report)
        if fct[1].__class__.__name__ == 'QgsExpressionFunction'})
    all_expressions.update({
        fct[0]: fct[1] for fct in getmembers(html_report)
        if fct[1].__class__.__name__ == 'QgsExpressionFunction'})
    return all_expressions

def volumes_tagged(name, tag_maps, authoritative=False, region=None, key=None,
                   keyid=None, profile=None):

    ret = {'name': name,
           'result': True,
           'comment': '',
           'changes': {}
          }
    args = {'tag_maps': tag_maps, 'authoritative': authoritative,
            'region': region, 'key': key, 'keyid': keyid, 'profile': profile}

    if __opts__['test']:
        args['dry_run'] = True
        r = __salt__['boto_ec2.set_volumes_tags'](**args)
        if r['success']:
            if r.get('changes'):
                ret['comment'] = 'Tags would be updated.'
                ret['changes'] = r['changes']
                ret['result'] = None
        else:
            ret['comment'] = 'Error validating requested volume tags.'
            ret['result'] = False
        return ret
    r = __salt__['boto_ec2.set_volumes_tags'](**args)
    if r['success']:
        if r.get('changes'):
            ret['comment'] = 'Tags applied.'
            ret['changes'] = r['changes']
