def jaccardIndex(s1, s2, stranded=False):

  def count(s):
    """ sum the size of regions in s. """
    tot = 0
    for r in s:
      tot += len(r)
    return tot

  if stranded:
    raise GenomicIntervalError("Sorry, stranded mode for computing Jaccard " +
                               "index hasn't been implemented yet.")

  s1 = collapseRegions(s1)
  s2 = collapseRegions(s2)
  intersection = regionsIntersection(s1, s2)
  c_i = count(intersection)
  return c_i / float(count(s1) + count(s2) - c_i)

def parse_raw_list_data(data, proxy_type='http', proxy_userpwd=None):
    if not isinstance(data, six.text_type):
        data = data.decode('utf-8')
    for orig_line in data.splitlines():
        line = orig_line.strip().replace(' ', '')
        if line and not line.startswith('#'):
            try:
                host, port, username, password = parse_proxy_line(line)
            except InvalidProxyLine as ex:
                logger.error(ex)
            else:
                if username is None and proxy_userpwd is not None:
                    username, password = proxy_userpwd.split(':')
                yield Proxy(host, port, username, password, proxy_type)

