def get_nodes_by_value(manager, value, prop=None, node_type='Node'):
    if prop:
        q = """
            MATCH (n:{label})
            USING SCAN n:{label}
            WHERE n.{prop} = {{value}}
            RETURN distinct n
            """.format(label=node_type, prop=prop)

        with manager.session as s:
            for result in s.run(q, {'value': value}):
                yield result['n']
    else:
        q = """
            MATCH (n:{label})
            RETURN n
            """.format(label=node_type)
        pattern = re.compile(u'{0}'.format(value), re.IGNORECASE)
        with manager.session as s:
            for result in s.run(q):
                for v in result['n'].properties.values():
                    if pattern.search(text_type(v)):
                        yield result['n']
                        break

def execute_and_report(command, *args, **kwargs):
    logging.info("Execute: %s %s" % (command, " ".join(args)))
    try:
        status, out, err = execute(command, *args, **kwargs)
        if status == 0:
            logging.info(
                "%s Finished successfully. Exit Code: 0.",
                os.path.basename(command),
            )
            return True
        else:
            try:
                logging.error(
                    "%s failed! Exit Code: %s\nOut: %s\nError: %s",
                    os.path.basename(command),
                    status,
                    out,
                    err,
                )
            except Exception as e:
                # This fails when some non ASCII characters are returned
                # from the application
                logging.error(
                    "%s failed [%s]! Exit Code: %s\nOut: %s\nError: %s",
                    e,
                    os.path.basename(command),
                    status,
                    repr(out),
                    repr(err),
                )
            return False
    except Exception:
        logging.exception(
            "%s failed! Exception thrown!", os.path.basename(command)
        )
        return False

def partition(pred, iterable, tolist=False):
    # partition(is_odd, range(10)) --> 0 2 4 6 8   and  1 3 5 7 9
    t1, t2 = itertools.tee(iterable)
    ifalse = six.moves.filterfalse(pred, t1)
    itrue = six.moves.filter(pred, t2)
    if tolist:
        return list(ifalse), list(itrue)
    else:
        return ifalse, itrue

