def Contradiction(expr1: Expression, expr2: Expression) -> Expression:
    expr = Disjunction(Conjunction(expr1, Negation(expr2)),
                       Conjunction(Negation(expr1), expr2))
    return ast.fix_missing_locations(expr)

def getNextService(self, discover):
        manager = self.getManager()
        if manager is not None and not manager:
            self.destroyManager()

        if not manager:
            yadis_url, services = discover(self.url)
            manager = self.createManager(services, yadis_url)

        if manager:
            service = manager.next()
            manager.store(self.session)
        else:
            service = None

        return service

