def sort(m, reverse=False):
    ty = type(m)
    if ty == matrix:
        m = list(m)
    m = sorted(m, reverse=reverse)
    if ty == matrix:
        m = matrix(m)
    return m

def main(argv=None):
    args = docopt.docopt(__doc__, argv=argv, version=__version__)
    verbose = bool(args['--verbose'])

    f_roll = dice.roll
    kwargs = {}

    if args['--min']:
        f_roll = dice.roll_min
    elif args['--max']:
        f_roll = dice.roll_max

    if args['--max-dice']:
        try:
            kwargs['max_dice'] = int(args['--max-dice'])
        except ValueError:
            print("Invalid value for --max-dice: '%s'" % args['--max-dice'])
            exit(1)

    expr = ' '.join(args['<expression>'])

    try:
        roll, kwargs = f_roll(expr, raw=True, return_kwargs=True, **kwargs)

        if verbose:
            print('Result: ', end='')

        print(str(roll.evaluate_cached(**kwargs)))

        if verbose:
            print('Breakdown:')
            print(dice.utilities.verbose_print(roll, **kwargs))
    except DiceBaseException as e:
        print('Whoops! Something went wrong:')
        print(e.pretty_print())
        exit(1)

def get_sns_topic_arn(topic_name, account, region):
    if topic_name.count(':') == 5 and topic_name.startswith('arn:aws:sns:'):
        return topic_name
    session = boto3.Session(profile_name=account, region_name=region)
    sns_client = session.client('sns')

    topics = sns_client.list_topics()['Topics']

    matched_topic = None
    for topic in topics:
        topic_arn = topic['TopicArn']
        if topic_name == topic_arn.split(':')[-1]:
            matched_topic = topic_arn
            break
    else:
        LOG.critical("No topic with name %s found.", topic_name)
        raise SNSTopicNotFound('No topic with name {0} found'.format(topic_name))
    return matched_topic

def zpath(filename):
    for ext in ["", '.gz', '.GZ', '.bz2', '.BZ2', '.z', '.Z']:
        zfilename = "{}{}".format(filename, ext)
        if os.path.exists(zfilename):
            return zfilename
    return filename

