def get_iso_time_str(timestamp: Union[int, float, str, datetime]=None) -> str:
    if isinstance(timestamp, (int, float)):
        maya_dt = maya.MayaDT(timestamp)
    elif isinstance(timestamp, str):
        maya_dt = maya.when(timestamp)
    elif timestamp is None:
        maya_dt = maya.now()
    else:
        raise ValueError(f'`{type(timestamp)}` is not supported')
    return maya_dt.iso8601()

def contents(self):
        if not self._contents:
            if self._path:
                # Read file into memory so we don't run out of file descriptors
                f = open(self._path, "rb")
                self._contents = f.read()
                f.close()
            elif self._pil_image:
                # Write PIL image to string
                f = StringIO()
                self._pil_image.save(f, self.format)
                self._contents = f.getvalue()
        return self._contents

def explicit_images(images, image_destination, rootname, config):
    log.info('Explicit image directory specified: {0}'.format(images))
    if '*' in images:
        images = images.replace('*', rootname)
        log.debug('Wildcard expansion for image directory: {0}'.format(images))
    try:
        shutil.copytree(images, image_destination)
    except:
        #The following is basically a recipe for log.exception() but with a
        #CRITICAL level if the execution should be killed immediately
        #log.critical('Unable to copy from indicated directory', exc_info=True)
        log.exception('Unable to copy from indicated directory')
        return False
    else:
        return True

def int_to_rgba(cls, rgba_int):
        if rgba_int is None:
            return None, None, None, None
        alpha = rgba_int % 256
        blue = rgba_int / 256 % 256
        green = rgba_int / 256 / 256 % 256
        red = rgba_int / 256 / 256 / 256 % 256
        return (red, green, blue, alpha)

def _check_forward_mode_input_dict(self, var_tbl: dict) -> int:
        T: int = 1
        for var_name in var_tbl:
            # The bound value to this variable name
            val = var_tbl[var_name]
            # case 1: this is a scalar; T=1
            if isinstance(val, scalar_instance_types):
                t = 1
            # case 2: this is an array; calulate T
            elif isinstance(val, np.ndarray):
                t = self._calc_T_var(val)
            #case 3: throw an error
            else:
                raise ValueError(f'val={val} in var_tbl; {type(val)} not a recognized value type.')
            #update T
            if t > 1 and T == 1:
                T = t
            elif t not in (1,T):
                raise ValueError(f'Bound variable {var_name} has inconsistent shape')
        return T

