def extend(self, *schema_items, **kwargs):
        new_kwargs = {
            'name': self.name,
            'doc': self.doc,
            'parameters': self._parameters[:],
            'result': self.result.copy() if self.result else {},
            'errors': self.errors.copy() if self.errors else set()}
        if 'parameters' in kwargs:
            tmp = kwargs.pop('parameters')
            new_kwargs['parameters'].extend(tmp)
        new_kwargs['result'].update(kwargs.pop('result', {}))
        new_kwargs['errors'].update(kwargs.pop('errors', set()))
        new_kwargs.update(kwargs)

        if schema_items:
            parameters = self._convert_old_schema(schema_items)
            new_kwargs['parameters'].extend(parameters)
        return Schema(**new_kwargs)

def add(self, node):
        if not isinstance(node, Node):
            raise TypeError()
        for i, j in enumerate(self.__nodes):
            if j.node_id == node.node_id:
                self.__nodes[i] = node
                return
        self.__nodes.append(node)

def _resolve_child(self, path):
        obj = self

        for component in path.split('.'):
            ptr = obj
            if not isinstance(ptr, Permuter):
                raise self.MessageNotFound("Bad element path [wrong type]")

            # pylint: disable=protected-access
            found_gen = (_ for _ in ptr._generators if _.name() == component)

            obj = next(found_gen, None)

            if not obj:
                raise self.MessageNotFound("Path '{}' unresolved to member."
                                           .format(path))
        return ptr, obj

def log_print_response(logger, response):

    log_msg = '<<<<<<<<<<<<<<<<<<<<<< Response <<<<<<<<<<<<<<<<<<\n'
    log_msg += '\t< Response code: {}\n'.format(str(response.status_code))
    log_msg += '\t< Headers: {}\n'.format(str(dict(response.headers)))
    try:
        log_msg += '\t< Payload received:\n {}'.format(_get_pretty_body(dict(response.headers), response.content))
    except ValueError:
        log_msg += '\t< Payload received:\n {}'.format(_get_pretty_body(dict(response.headers), response.content.text))

    logger.debug(log_msg)

