def spec_validator(spec, key=operator.itemgetter):
    spec = {k: (key(k), make_chain(v)) for k, v in spec.items()}

    def validator(obj):
        errors = {}
        for k, v in spec.items():
            getter, chain = v
            val = getter(obj)
            try:
                chain(val)
            except ValueError as err:
                errors[k] = err
        return errors

    return validator

