def wcs_pix_transform(ct, i, format=0):
    z1 = float(ct.z1)
    z2 = float(ct.z2)
    i = float(i)

    yscale = 128.0 / (z2 - z1)
    if (format == 'T' or format == 't'):
        format = 1

    if (i == 0):
        t = 0.
    else:
        if (ct.zt == W_LINEAR):
            t = ((i - 1) * (z2 - z1) / 199.0) + z1
            t = max(z1, min(z2, t))
        else:
            t = float(i)
    if (format > 1):
        t = (z2 - t) * yscale
    return (t)

def add(self, source, email=None, name=None, username=None, uuid=None,
            matching=None, interactive=False):
        matcher = None

        if matching:
            try:
                blacklist = api.blacklist(self.db)
                matcher = create_identity_matcher(matching, blacklist)
            except MatcherNotSupportedError as e:
                self.error(str(e))
                return e.code

        try:
            new_uuid = api.add_identity(self.db, source, email, name, username, uuid)
            uuid = uuid or new_uuid
            self.display('add.tmpl', id=new_uuid, uuid=uuid)
            if matcher:
                self.__merge_on_matching(uuid, matcher, interactive)
        except AlreadyExistsError as e:
            msg = "unique identity '%s' already exists in the registry" % e.eid
            self.error(msg)
            return e.code
        except (NotFoundError, InvalidValueError) as e:
            self.error(str(e))
            return e.code

        return CMD_SUCCESS

def parseruninfo(self):
        # Check if the RunInfo.xml file is provided, otherwise, yield N/A
        try:
            runinfo = ElementTree.ElementTree(file=self.runinfo)
            # Get the run id from the
            for elem in runinfo.iter():
                for run in elem:
                    try:
                        self.runid = run.attrib['Id']
                        self.runnumber = run.attrib['Number']
                    except KeyError:
                        break
            # pull the text from flowcell and instrument values using the .iter(tag="X") function
            for elem in runinfo.iter(tag="Flowcell"):
                self.flowcell = elem.text
            for elem in runinfo.iter(tag="Instrument"):
                self.instrument = elem.text
        except IOError:
            pass
        # Extract run statistics from either GenerateRunStatistics.xml or indexingQC.txt
        self.parserunstats()

