def reverse(rev_inputs=REV_INPUTS):
    dirname = os.path.dirname(__file__)

    for in_file in rev_inputs:
        reversed_dict = {}
        input_file = in_file + '.txt'
        output_file = in_file + 'Rev.txt'
        input_file = os.path.join(dirname, DICT_DIRECTORY, input_file)
        output_file = os.path.join(dirname, DICT_DIRECTORY, output_file)
        with open(input_file, 'r', encoding='utf-8') as f:
            for line in f:
                line = line.strip()
                split = line.split('\t')
                if len(split) < 2:
                    continue
                term1 = split[0]
                term2 = split[1]

                for char in term2.split(' '):
                    if char in reversed_dict:
                        reversed_dict[char].append(term1)
                    else:
                        reversed_dict[char] = [term1]
        with open(output_file, 'w', encoding='utf-8') as f:
            for key in reversed_dict:
                line = key + '\t' + ' '.join(reversed_dict[key]) + '\n'
                f.write(line)

def get_span_row_count(span):
    rows = 1
    first_row = span[0][0]

    for i in range(len(span)):
        if span[i][0] > first_row:
            rows += 1
            first_row = span[i][0]

    return rows

def _shuffle(y, labels, random_state):
    if labels is None:
        ind = random_state.permutation(len(y))
    else:
        ind = np.arange(len(labels))
        for label in np.unique(labels):
            this_mask = (labels == label)
            ind[this_mask] = random_state.permutation(ind[this_mask])
    return y[ind]

def UNIFAC_psi(T, subgroup1, subgroup2, subgroup_data, interaction_data, 
               modified=False):
    main1 = subgroup_data[subgroup1].main_group_id
    main2 = subgroup_data[subgroup2].main_group_id
    if modified:
        try:
            a, b, c = interaction_data[main1][main2]
        except:
            return 1.
        return exp((-a/T -b - c*T))
    else:
        try:
            return exp(-interaction_data[main1][main2]/T)
        except:
            return 1.

