def save(self, recipe):
        # test if this is a create vs. an update
        if 'id' in recipe and recipe['id'] is not None:
            # update -> use put op
            self.logger.debug("Updating existing recipe: " + json.dumps(recipe))
            url = '%(base_url)s/recipe/json/%(recipe_id)s' % {
                'base_url': self.base_url, 'recipe_id': recipe['id']
            }
            r = self.gbdx_connection.put(url, json=recipe)
            try:
                r.raise_for_status()
            except:
                print(r.text)
                raise
            return recipe['id']
        else:
            # create -> use post op
            self.logger.debug("Creating new recipe: " + json.dumps(recipe))
            url = '%(base_url)s/recipe/json' % {
                'base_url': self.base_url
            }
            r = self.gbdx_connection.post(url, json=recipe)
            try:
                r.raise_for_status()
            except:
                print(r.text)
                raise
            recipe_json = r.json()
            return recipe_json['id']

def is_valid_array(array, events, slots):

    if len(array) == 0:
        return False
    violations = sum(1 for c in (array_violations(array, events, slots)))
    return violations == 0

def report_idle_after(seconds):

    def decorator(func):
        def wrapper(*args, **kwargs):
            def _handle_timeout(signum, frame):
                config = get_config()
                if not config.ready:
                    config.load()
                message = {
                    "subject": "Idle Experiment.",
                    "body": idle_template.format(
                        app_id=config.get("id"), minutes_so_far=round(seconds / 60)
                    ),
                }
                log("Reporting problem with idle experiment...")
                get_messenger(config).send(message)

            signal.signal(signal.SIGALRM, _handle_timeout)
            signal.alarm(seconds)
            try:
                result = func(*args, **kwargs)
            finally:
                signal.alarm(0)
            return result

        return wraps(func)(wrapper)

    return decorator

