def exit(mod_name=""):
    if mod_name and mod_name == "__main__":
        calling_mod = sys.modules.get("__main__", None)

    else:
        calling_mod = discover_if_calling_mod()

    if calling_mod:
        s = Script(inspect.getfile(calling_mod), module=calling_mod)
        raw_args = sys.argv[1:]
        try:
            ret_code = s.run(raw_args)

        except Stop as e:
            ret_code = e.code
            msg = str(e)
            if msg:
                if ret_code != 0:
                    echo.err(msg)
                else:
                    echo.out(msg)

        sys.exit(ret_code)

