def is_multicast(text):
    try:
        first = ord(dns.ipv4.inet_aton(text)[0])
        return (first >= 224 and first <= 239)
    except Exception:
        try:
            first = ord(dns.ipv6.inet_aton(text)[0])
            return (first == 255)
        except Exception:
            raise ValueError

def dictlist_wipe_key(dict_list: Iterable[Dict], key: str) -> None:
