def map(cls, function, items, multiprocess=False, file=None):

        results = []

        if file is None:
            file = _get_stdout()

        with cls(len(items), file=file) as bar:
            step_size = max(200, bar._bar_length)
            steps = max(int(float(len(items)) / step_size), 1)
            if not multiprocess:
                for i, item in enumerate(items):
                    results.append(function(item))
                    if (i % steps) == 0:
                        bar.update(i)
            else:
                p = multiprocessing.Pool()
                for i, result in enumerate(
                    p.imap_unordered(function, items, steps)):
                    bar.update(i)
                    results.append(result)
                p.close()
                p.join()

        return results

def process_raw(self, raw: dict) -> None:
        raw_ports = {}

        for param in raw:
            port_index = REGEX_PORT_INDEX.search(param).group(0)

            if port_index not in raw_ports:
                raw_ports[port_index] = {}

            name = param.replace(IOPORT + '.I' + port_index + '.', '')
            raw_ports[port_index][name] = raw[param]

        super().process_raw(raw_ports)

