def literal(x):
    xlen = len(x)
    msg = 'Expected: "{}"'.format(x)
    def match_literal(s, grm=None, pos=0):
        if s[:xlen] == x:
            return PegreResult(s[xlen:], x, (pos, pos+xlen))
        raise PegreError(msg, pos)
    return match_literal

def getCopelandScores(profile, alpha=0.5, normalize=False):

    # Currently, we expect the profile to contain complete ordering over candidates. Ties are
    # allowed however.
    elecType = profile.getElecType()
    if elecType != "soc" and elecType != "toc":
        print("ERROR: unsupported election type")
        exit()

    # Initialize each Copeland score as 0.0.
    copelandscores = {}
    for cand in profile.candMap.keys():
        copelandscores[cand] = 0.0

    # For each pair of candidates, calculate the number of votes in which one beat the other.
    wmgMap = profile.getWmg()
    for cand1, cand2 in itertools.combinations(wmgMap.keys(), 2):
        if cand2 in wmgMap[cand1].keys():
            if wmgMap[cand1][cand2] > 0:
                copelandscores[cand1] += 1.0
            elif wmgMap[cand1][cand2] < 0:
                copelandscores[cand2] += 1.0

            # If a pair of candidates is tied, we add alpha to their score for each vote.
            else:
                copelandscores[cand1] += alpha
                copelandscores[cand2] += alpha

    if normalize:
        m = profile.numCands
        for cand in profile.candMap.keys():
            copelandscores[cand] /= (m - 1)

    return copelandscores

def update_asset(self, asset_form):
        # Implemented from template for
        # osid.resource.ResourceAdminSession.update_resource_template
        collection = JSONClientValidated('repository',
                                         collection='Asset',
                                         runtime=self._runtime)
        if not isinstance(asset_form, ABCAssetForm):
            raise errors.InvalidArgument('argument type is not an AssetForm')
        if not asset_form.is_for_update():
            raise errors.InvalidArgument('the AssetForm is for update only, not create')
        try:
            if self._forms[asset_form.get_id().get_identifier()] == UPDATED:
                raise errors.IllegalState('asset_form already used in an update transaction')
        except KeyError:
            raise errors.Unsupported('asset_form did not originate from this session')
        if not asset_form.is_valid():
            raise errors.InvalidArgument('one or more of the form elements is invalid')
        collection.save(asset_form._my_map)

        self._forms[asset_form.get_id().get_identifier()] = UPDATED

        # Note: this is out of spec. The OSIDs don't require an object to be returned:
        return objects.Asset(
            osid_object_map=asset_form._my_map,
            runtime=self._runtime,
            proxy=self._proxy)

