def _create_h5_file(in_paths, new_path):
    if type(in_paths) == str:
        in_paths = [in_paths]
    new_file = File(new_path, 'w')
    for i, in_path in enumerate(in_paths):
        with File(in_path, 'r') as file:
            for key in list(file.keys()):
                file.copy(source=file[key], dest=new_file, name=key)

    return new_file

async def write(self, data, eof = False, buffering = True):
        if not self.outputstream:
            self.outputstream = Stream()
            self._startResponse()
        elif (not buffering or eof) and not self._sendHeaders:
            self._startResponse()
        if not isinstance(data, bytes):
            data = data.encode(self.encoding)
        await self.outputstream.write(data, self.connection, eof, False, buffering)

def stop(self, timeout=None):
        assert self.has_started(), "called stop() on a non-active GeventLoop"
        greenlet = self._greenlet if gevent.getcurrent() != self._greenlet else None
        self._stop_event.set()
        if greenlet is not None and timeout is not None:
            greenlet.join(timeout)
            return greenlet.ready
        else:
            return True

