def dframe(self, dimensions=None, multi_index=False):
        if dimensions:
            dimensions = [self.get_dimension(d, strict=True) for d in dimensions]
        else:
            dimensions = self.kdims
        vdims = [d for d in dimensions if d in self.vdims]
        if vdims:
            raise ValueError('%s element does not hold data for value '
                             'dimensions. Could not return data for %s '
                             'dimension(s).' %
                             (type(self).__name__, ', '.join([d.name for d in vdims])))
        return super(StatisticsElement, self).dframe(dimensions, False)

def _get_hash(self):
        if self.optionals and self.optionals.ISBN:
            isbn = self.optionals.ISBN.replace("-", "")

            if len(isbn) <= 10:
                return "97880" + isbn

            return isbn

        if self.optionals and self.optionals.EAN:
            return self.optionals.EAN

        return self.title + ",".join(map(lambda x: x.name, self.authors))

def _get_ondisk_chapter(self, book_name, book_chapter):
        # First attempt to look up the chapter on the disk
        verses_list = []
        filename = os.path.expanduser("~/.diyr/{}/{}").format(
            book_name,
            book_chapter)
        if os.path.isfile(filename):
            # Read the file into a list
            try:
                f = open(filename)
            except OSError as e:
                logging.error("Could not read {}".format(filename))
                return ["ERROR! Could not read {}".format(filename)]

            for line in f.readlines():
                verses_list.append(line)

            return verses_list
        else:
            # If the file is not cached, raise an Exception
            raise Exception("The file {} is not cached!".format(filename))

