def load(self, rule_type, quiet = False):
        if self.filename and os.path.exists(self.filename):
            try:
                with open(self.filename, 'rt') as f:
                    ruleset = json.load(f)
                    self.about = ruleset['about'] if 'about' in ruleset else ''
                    self.rules = {}
                    for filename in ruleset['rules']:
                        self.rules[filename] = []
                        for rule in ruleset['rules'][filename]:
                            self.handle_rule_versions(filename, rule_type, rule)
            except Exception as e:
                printException(e)
                printError('Error: ruleset file %s contains malformed JSON.' % self.filename)
                self.rules = []
                self.about = ''
        else:
            self.rules = []
            if not quiet:
                printError('Error: the file %s does not exist.' % self.filename)

def lazy_chunk_creator(name):
        # TODO: Could this become a LazyChunk class?
        def biggus_chunk(chunk_key, biggus_array, masked):
            """
            A function that lazily evaluates a biggus.Chunk. This is useful for
            passing through as a dask task so that we don't have to compute the
            chunk in order to compute the graph.

            """
            if masked:
                array = biggus_array.masked_array()
            else:
                array = biggus_array.ndarray()

            return biggus._init.Chunk(chunk_key, array)
        biggus_chunk.__name__ = name
        return biggus_chunk

