def decode(f):
        decoder = mqtt_io.FileDecoder(f)
        (byte_0,) = decoder.unpack(mqtt_io.FIELD_U8)

        packet_type_u4 = (byte_0 >> 4)
        flags = byte_0 & 0x0f

        try:
            packet_type = MqttControlPacketType(packet_type_u4)
        except ValueError:
            raise DecodeError('Unknown packet type 0x{:02x}.'.format(packet_type_u4))

        if not are_flags_valid(packet_type, flags):
            raise DecodeError('Invalid flags for packet type.')

        num_bytes, num_remaining_bytes = decoder.unpack_varint(4)

        return decoder.num_bytes_consumed, MqttFixedHeader(packet_type, flags, num_remaining_bytes)

def create(Bucket,
           ACL=None, LocationConstraint=None,
           GrantFullControl=None,
           GrantRead=None,
           GrantReadACP=None,
           GrantWrite=None,
           GrantWriteACP=None,
           region=None, key=None, keyid=None, profile=None):

    try:
        conn = _get_conn(region=region, key=key, keyid=keyid, profile=profile)
        kwargs = {}
        for arg in ('ACL', 'GrantFullControl',
                    'GrantRead', 'GrantReadACP',
                    'GrantWrite', 'GrantWriteACP'):
            if locals()[arg] is not None:
                kwargs[arg] = str(locals()[arg])  # future lint: disable=blacklisted-function
        if LocationConstraint:
            kwargs['CreateBucketConfiguration'] = {'LocationConstraint': LocationConstraint}
        location = conn.create_bucket(Bucket=Bucket,
                                  **kwargs)
        conn.get_waiter("bucket_exists").wait(Bucket=Bucket)
        if location:
            log.info('The newly created bucket name is located at %s', location['Location'])

            return {'created': True, 'name': Bucket, 'Location': location['Location']}
        else:
            log.warning('Bucket was not created')
            return {'created': False}
    except ClientError as e:
        return {'created': False, 'error': __utils__['boto3.get_error'](e)}

def correct(tokens, term_freq):
    log = []
    output = []
    for token in tokens:
        corrected = _correct(token, term_freq)
        if corrected != token:
            log.append((token, corrected))
        output.append(corrected)
    return output, log

def _product(*args, **kwds):

    pools = map(tuple, args) * kwds.get('repeat', 1)
    result = [[]]
    for pool in pools:
        result = [x+[y] for x in result for y in pool]
    return result

def random_tree(n_leaves):
    def _random_subtree(leaves):
        if len(leaves) == 1:
            return leaves[0]
        elif len(leaves) == 2:
            return (leaves[0], leaves[1])
        else:
            split = npr.randint(1, len(leaves)-1)
            return (_random_subtree(leaves[:split]),
                    _random_subtree(leaves[split:]))

    return _random_subtree(np.arange(n_leaves))

def get_topic_partition_with_error(cluster_config, error, fetch_unavailable_brokers=False):

    metadata = get_topic_partition_metadata(cluster_config.broker_list)
    affected_partitions = set()
    if fetch_unavailable_brokers:
        unavailable_brokers = set()
    with ZK(cluster_config) as zk:
        for partitions in metadata.values():
            for partition_metadata in partitions.values():
                if int(partition_metadata.error) == error:
                    if fetch_unavailable_brokers:
                        unavailable_brokers |= get_unavailable_brokers(zk, partition_metadata)
                    affected_partitions.add((partition_metadata.topic, partition_metadata.partition))

    if fetch_unavailable_brokers:
        return affected_partitions, unavailable_brokers
    else:
        return affected_partitions

