def aggregate(self, dataset_ids=None, boundary='exact', side='left', func='mean', **dim_kwargs):
        new_scn = self.copy(datasets=dataset_ids)

        for src_area, ds_ids in new_scn.iter_by_area():
            if src_area is None:
                for ds_id in ds_ids:
                    # Restore the original dataset object to bypass aggregation for empty area entries.
                    new_scn.datasets[ds_id] = self[ds_id]
                continue

            if boundary != 'exact':
                raise NotImplementedError("boundary modes appart from 'exact' are not implemented yet.")
            target_area = src_area.aggregate(**dim_kwargs)
            resolution = max(target_area.pixel_size_x, target_area.pixel_size_y)
            for ds_id in ds_ids:
                res = self[ds_id].coarsen(boundary=boundary, side=side, func=func, **dim_kwargs)

                new_scn.datasets[ds_id] = getattr(res, func)()
                new_scn.datasets[ds_id].attrs['area'] = target_area
                new_scn.datasets[ds_id].attrs['resolution'] = resolution

        return new_scn

def _refresh_context(self):
        header_str = os.getenv(LAMBDA_TRACE_HEADER_KEY)
        trace_header = TraceHeader.from_header_str(header_str)
        if not global_sdk_config.sdk_enabled():
            trace_header._sampled = False

        segment = getattr(self._local, 'segment', None)

        if segment:
            # Ensure customers don't have leaked subsegments across invocations
            if not trace_header.root or trace_header.root == segment.trace_id:
                return
            else:
                self._initialize_context(trace_header)
        else:
            self._initialize_context(trace_header)

def edit(self, name=None, description=None, **kwargs):
        # type: (AnyStr, AnyStr, **Any) -> None
        update_dict = {'id': self.id}
        if name:
            if not isinstance(name, str):
                raise IllegalArgumentError("name should be provided as a string")
            update_dict.update({'name': name})
        if description:
            if not isinstance(description, str):
                raise IllegalArgumentError("description should be provided as a string")
            update_dict.update({'description': description})

        if kwargs:  # pragma: no cover
            update_dict.update(**kwargs)
        r = self._client._request('PUT', self._client._build_url('part', part_id=self.id), json=update_dict)

        if r.status_code != requests.codes.ok:  # pragma: no cover
            raise APIError("Could not update Part ({})".format(r))

        if name:
            self.name = name

def send(self, buf, flags=0):
        # Backward compatibility
        buf = _text_to_bytes_and_warn("buf", buf)

        if isinstance(buf, memoryview):
            buf = buf.tobytes()
        if isinstance(buf, _buffer):
            buf = str(buf)
        if not isinstance(buf, bytes):
            raise TypeError("data must be a memoryview, buffer or byte string")
        if len(buf) > 2147483647:
            raise ValueError("Cannot send more than 2**31-1 bytes at once.")

        result = _lib.SSL_write(self._ssl, buf, len(buf))
        self._raise_ssl_error(self._ssl, result)
        return result

