def by_symbol_match(value, country_code=None):
    res = None
    for s, group in _symbols():
        if s.lower() in value.lower():
            if group == 'symbol':
                res = by_symbol(s, country_code)
            if group == 'alpha3':
                res = [by_alpha3(s)]
            if group == 'name':
                res = [_data()['name'][s]]
            if res and country_code is not None:
                res = [
                    currency
                    for currency in res
                    if country_code in currency.countries
                ]
            if res:
                return res

