def http_retry_with_backoff_middleware(
        make_request,
        web3,  # pylint: disable=unused-argument
        errors: Tuple = (
            exceptions.ConnectionError,
            exceptions.HTTPError,
            exceptions.Timeout,
            exceptions.TooManyRedirects,
        ),
        retries: int = 10,
        first_backoff: float = 0.2,
        backoff_factor: float = 2,
):
    def middleware(method, params):
        backoff = first_backoff
        if check_if_retry_on_failure(method):
            for i in range(retries):
                try:
                    return make_request(method, params)
                except errors:
                    if i < retries - 1:
                        gevent.sleep(backoff)
                        backoff *= backoff_factor
                        continue
                    else:
                        raise
        else:
            return make_request(method, params)

    return middleware

def _getBlock(self, block_spec):
        if block_spec is None:
            return
        if all(c in string.hexdigits for c in block_spec):
            block_spec = block_spec.upper()
            ix = 0
        else:
            ix = 2
        for block in all_blocks:
            if block[ix] == block_spec:
