def seek(self, value, target="offset"):

        if target not in (u'offset', u'id'):
            raise ArgumentError("You must specify target as either offset or id", target=target)

        if target == u'offset':
            self._verify_offset(value)
            self.offset = value
        else:
            self.offset = self._find_id(value)

        self._count = self.engine.count_matching(self.selector, offset=self.offset)

        curr = self.engine.get(self.storage_type, self.offset)
        return self.matches(DataStream.FromEncoded(curr.stream))

def build_list(self, manifests):

        media_type = manifests[0]['media_type']
        if (not all(m['media_type'] == media_type for m in manifests)):
            raise PluginFailedException('worker manifests have inconsistent types: {}'
                                        .format(manifests))

        if media_type == MEDIA_TYPE_DOCKER_V2_SCHEMA2:
            list_type = MEDIA_TYPE_DOCKER_V2_MANIFEST_LIST
        elif media_type == MEDIA_TYPE_OCI_V1:
            list_type = MEDIA_TYPE_OCI_V1_INDEX
        else:
            raise PluginFailedException('worker manifests have unsupported type: {}'
                                        .format(media_type))

        return list_type, json.dumps({
                "schemaVersion": 2,
                "mediaType": list_type,
                "manifests": [
                    {
                        "mediaType": media_type,
                        "size": m['size'],
                        "digest": m['digest'],
                        "platform": {
                            "architecture": m['architecture'],
                            "os": "linux"
                        }
                    } for m in manifests
                ],
        }, indent=4)

