def _R2deriv(self,R,z,phi=0.,t=0.):
        if self.alpha == 0.:
            denom= 1./(R**2.+z**2./self.q2+self.core2)
            return denom-2.*R**2.*denom**2.
        else:
            m2= self.core2+R**2.+z**2./self.q2
            return -m2**(-self.alpha/2.-1.)*((self.alpha+2)*R**2./m2-1.)

def getStats(self):
        info_dict = {}
        args = [varnishstatCmd, '-1']
        if self._instance is not None:
            args.extend(['-n', self._instance])
        output = util.exec_command(args)
        if self._descDict is None:
            self._descDict = {}
        for line in output.splitlines():
            mobj = re.match('(\S+)\s+(\d+)\s+(\d+\.\d+|\.)\s+(\S.*\S)\s*$', 
                            line)
            if mobj:
                fname = mobj.group(1).replace('.', '_')
                info_dict[fname] = util.parse_value(mobj.group(2))
                self._descDict[fname] = mobj.group(4)
        return info_dict

def read_csv_from_file(filename):
    logger_csvs.info("enter read_csv_from_file")
    d = {}
    l = []
    try:
        logger_csvs.info("open file: {}".format(filename))
        with open(filename, 'r') as f:
            r = csv.reader(f, delimiter=',')

            # Create a dict with X lists corresponding to X columns
            for idx, col in enumerate(next(r)):
                d[idx] = []
                d = cast_values_csvs(d, idx, col)

            # Start iter through CSV data
            for row in r:
                for idx, col in enumerate(row):
                    # Append the cell to the correct column list
                    d = cast_values_csvs(d, idx, col)

        # Make a list of lists out of the dictionary instead
        for idx, col in d.items():
            l.append(col)
    except FileNotFoundError as e:
        print('CSV FileNotFound: ' + filename)
        logger_csvs.warn("read_csv_to_columns: FileNotFound: {}, {}".format(filename, e))
    logger_csvs.info("exit read_csv_from_file")
    return l

def select_parser(self, request, parsers):

        if not request.content_type:
            return parsers[0], parsers[0].mimetype

        mimetype = MimeType.parse(request.content_type)

        for parser in parsers:
            if mimetype.match(parser.mimetype):
                return parser, mimetype

        return None, None

def _linefeed(self):
        last_line = self._cursor.blockNumber() == self._text_edit.blockCount() - 1
        if self._cursor.atEnd() or last_line:
            if last_line:
                self._cursor.movePosition(self._cursor.EndOfBlock)
            self._cursor.insertText('\n')
        else:
            self._cursor.movePosition(self._cursor.Down)
            self._cursor.movePosition(self._cursor.StartOfBlock)
        self._text_edit.setTextCursor(self._cursor)

def get_additional_properties(self, _type, *args, **kwargs):
        if not SchemaObjects.contains(_type):
            return _type
        schema = SchemaObjects.get(_type)
        body = []
        for sch in schema.nested_schemas:  # complex types
            nested_schema = SchemaObjects.get(sch)
            if not (nested_schema or isinstance(nested_schema, SchemaMapWrapper)):
                continue

            body.append('Map of {{"key":"{}"}}\n\n'.format(self.get_type_description(
                nested_schema.schema_id, *args, **kwargs))  # head
            )
            if nested_schema.is_array:  # table
                _schema = SchemaObjects.get(nested_schema.item.get('type'))
                if _schema and _schema.schema_type == SchemaTypes.INLINE:
                    body.append(self.get_regular_properties(_schema.schema_id, *args, **kwargs))
            else:
                body.append(self.get_regular_properties(nested_schema.schema_id, *args, **kwargs))
        if schema.type_format:  # basic types, only head
            body.append(
                'Map of {{"key":"{}"}}'.format(self.get_type_description(schema.type_format, *args, **kwargs)))
        return ''.join(body)

