            if local_name:
                setattr(self, local_name, remote_value)
            else:
                # print('Attribute %s could not be added to object %s' % (remote_name, self))
                pass

def mkdir(self, astr_dirSpec):
            if astr_dirSpec != '/' and astr_dirSpec != "//":
                str_currentPath = self.cwd()
                l_pathSpec = astr_dirSpec.split('/')
                if not len(l_pathSpec[0]):
                    self.cd('/')
                    l_nodesDepth = l_pathSpec[1:]
                else:
                    l_nodesDepth = l_pathSpec
                for d in l_nodesDepth:
                    self.mkcd(d)
                self.cd(str_currentPath)

def qft(qubits: List[int]) -> Program:

    p = Program().inst(_core_qft(qubits, 1))
    return p + bit_reversal(qubits)

