    label_position = ctx.params["label_position"]

    if "{type}" not in value:
        missings.append(style("{type}", fg="red", bold=True))

    if label_position == "header" and "{subject}" not in value:
        missings.append(style("{subject}", fg="red", bold=True))

    if missings:
        message = "\n"

        for placeholder in missings:
            message += f"  {x_mark} Missing {placeholder} placeholder.\n"

        ctx.fail(message)

    return value

def searchPlanet(self, name):

        searchName = compactString(name)
        returnDict = {}

        for altname, planetObj in self._planetSearchDict.iteritems():
            if re.search(searchName, altname):
                returnDict[planetObj.name] = planetObj

        if returnDict:
            if len(returnDict) == 1:
                return returnDict.values()[0]
            else:
                return returnDict.values()

        else:
            return False

def _dense_var_to_tensor(self, dtype=None, name=None, as_ref=False):
    # pylint: disable=protected-access
    if _enclosing_tpu_context() is None:
      if hasattr(self._primary_var, '_dense_var_to_tensor'):
        return self._primary_var._dense_var_to_tensor(dtype, name, as_ref)
      else:
        return ops.convert_to_tensor(self._primary_var)
    # pylint: enable=protected-access
    if dtype is not None and dtype != self.dtype:
      return NotImplemented
    if as_ref:
      return self.handle
    else:
      return self.read_value()

