def diskMonitor(self):

        while self.loop():
            try:
                newest = max(glob.iglob("%s/*" % (self.kwargs.directory)), key=os.path.getmtime)
            except Exception:
                pass
            else:
                if time() - os.path.getctime(newest) >= self.kwargs.idle_time:
                    self.reading.set()
                else:
                    self.reading.clear()
            sleep(1)

