        if isinstance(value, basestring):
            value = value.split(",")
        return filter(lambda uid: uid, value)

def reverse_transform_table(self, table, table_meta, missing=None):

        if missing is None:
            missing = self.missing

        else:
            self.missing = missing
            warnings.warn(
                DEPRECATION_MESSAGE.format('reverse_transform_table'), DeprecationWarning)

        result = pd.DataFrame(index=table.index)
        table_name = table_meta['name']

        for field in table_meta['fields']:
            new_column = self._reverse_transform_column(table, field, table_name)
            if new_column is not None:
                result[field['name']] = new_column

        return result

def delete(self):
        versions = self.get_versions()
        self.api.manager.delete_archive_record(self.archive_name)

        for version in versions:
            if self.authority.fs.exists(self.get_version_path(version)):
                self.authority.fs.remove(self.get_version_path(version))

            if self.api.cache:
                if self.api.cache.fs.exists(self.get_version_path(version)):
                    self.api.cache.fs.remove(self.get_version_path(version))

        if self.authority.fs.exists(self.archive_name):
            self.authority.fs.removedir(self.archive_name)

        if self.api.cache:
            if self.api.cache.fs.exists(self.archive_name):
                self.api.cache.fs.removedir(self.archive_name)

def readlink(self, path):
        path = self._adjust_cwd(path)
        self._log(DEBUG, 'readlink(%r)' % path)
        t, msg = self._request(CMD_READLINK, path)
        if t != CMD_NAME:
            raise SFTPError('Expected name response')
        count = msg.get_int()
        if count == 0:
            return None
        if count != 1:
            raise SFTPError('Readlink returned %d results' % count)
        return _to_unicode(msg.get_string())

def is_bday(date, bday=None):
    _date = Timestamp(date)
    if bday is None:
        bday = CustomBusinessDay(calendar=USFederalHolidayCalendar())
    return _date == (_date + bday) - bday

