def _build_full_list(self):
        if self.npages <= self.maxpages_items:
            return range(1, self.npages + 1)
        else:
            l = range(self.curpage - self.max_prev_items,
                      self.curpage + self.max_next_items + 1)
            while l and l[0] < 1:
                l.append(l[-1] + 1)
                del l[0]
            while l and l[-1] > self.npages:
                l.insert(0, l[0] - 1)
                del l[-1]
            return l

def work(self, interval=5):
        self._setproctitle("Starting")
        logger.info("starting")
        self.startup()

        while True:
            if self._shutdown:
                logger.info('shutdown scheduled')
                break

            self.register_worker()

            job = self.reserve(interval)

            if job:
                self.fork_worker(job)
            else:
                if interval == 0:
                    break
                #procline @paused ? "Paused" : "Waiting for #{@queues.join(',')}"
                self._setproctitle("Waiting")
                #time.sleep(interval)
        self.unregister_worker()

def map(self, mapper):
        # this is used in apply.
        # We get hit since we're an "is_extension_type" but regular extension
        # types are not hit. This may be worth adding to the interface.
        if isinstance(mapper, ABCSeries):
            mapper = mapper.to_dict()

        if isinstance(mapper, abc.Mapping):
            fill_value = mapper.get(self.fill_value, self.fill_value)
            sp_values = [mapper.get(x, None) for x in self.sp_values]
        else:
            fill_value = mapper(self.fill_value)
            sp_values = [mapper(x) for x in self.sp_values]

        return type(self)(sp_values, sparse_index=self.sp_index,
                          fill_value=fill_value)

