        raise JournalDataBaseError("Something happened with the database of WOS journal names. To fix this you should delete the 1 to 3 files whose names start with {}. If this doesn't work (sorry), deleteing everything in '{}' and reinstalling metaknowledge should.\nThe error was '{}'".format(dbLoc, os.path.dirname(__file__), e))

async def remove(request: web.Request) -> web.Response:
    requested_hash = request.match_info['key_md5']
    new_keys: List[str] = []
    found = False
    for keyhash, key in get_keys():
        if keyhash == requested_hash:
            found = True
        else:
            new_keys.append(key)

    if not found:
        return web.json_response(
            data={'error': 'invalid-key-hash',
                  'message': f'No such key md5 {requested_hash}'},
            status=404)

    with authorized_keys('w') as ak:
        ak.write('\n'.join(new_keys) + '\n')

    return web.json_response(
        data={
            'message': f'Key {requested_hash} deleted. '
            'Restart robot to take effect',
            'restart_url': '/server/restart'},
        status=200)

