def unwrap_errors(path_replace):
    # type: (Union[Text, Mapping[Text, Text]]) -> Iterator[None]
    try:
        yield
    except errors.ResourceError as e:
        if hasattr(e, "path"):
            if isinstance(path_replace, Mapping):
                e.path = path_replace.get(e.path, e.path)
            else:
                e.path = path_replace
        reraise(type(e), e)

def new_keypair(key, value, ambig, unambig):
    if key in ambig:
        return

    if key in unambig and value != unambig[key]:
            ambig.add(key)
            del unambig[key]
            return

    unambig[key] = value
    return

