        }
        if type == 'triples':
            result_format = 'N-Triples'
        elif type == 'tuples':
            result_format = 'CSV'
        if limit is not None:
            http_args['limit'] = limit
        # else - error/exception ?
        http_args['format'] = result_format

        return self._query(result_format, http_args, flush)

