def add_line(self, moves: Iterable[chess.Move], *, comment: str = "", starting_comment: str = "", nags: Iterable[int] = ()) -> "GameNode":
        node = self

        # Add line.
        for move in moves:
            node = node.add_variation(move, starting_comment=starting_comment)
            starting_comment = ""

        # Merge comment and NAGs.
        if node.comment:
            node.comment += " " + comment
        else:
            node.comment = comment

        node.nags.update(nags)

        return node

def rejection_sample(n_samples, pool_size, rng_state):
    result = np.empty(n_samples, dtype=np.int64)
    for i in range(n_samples):
        reject_sample = True
        while reject_sample:
            j = tau_rand_int(rng_state) % pool_size
            for k in range(i):
                if j == result[k]:
                    break
            else:
                reject_sample = False
        result[i] = j
    return result

def keep_on_one_line():

    class CondensedStream:

        def __init__(self):
            self.sys_stdout = sys.stdout

        def write(self, string):
            with swap_streams(self.sys_stdout):
                string = string.replace('\n', ' ')
                string = truncate_to_fit_terminal(string)
                if string.strip():
                    update(string)

        def flush(self):
            with swap_streams(self.sys_stdout):
                flush()


    with swap_streams(CondensedStream()):
        yield

