def lbest_idx(state, idx):
    swarm = state.swarm
    n_s = state.params['n_s']
    cmp = comparator(swarm[0].best_fitness)
    indices = __lbest_indices__(len(swarm), n_s, idx)
    best = None
    for i in indices:
        if best is None or cmp(swarm[i].best_fitness, swarm[best].best_fitness):
            best = i
    return best

