            path_info = self.view.tree_view.get_path_at_pos(int(event.x), int(event.y))
            if path_info:  # Valid entry was clicked on
                path = path_info[0]
                item_iter = self.tree_store.get_iter(path)

                # Toggle collapse status if applicable for this kind of state
                if self.view.tree_view.row_expanded(path):
                    self.view.tree_view.collapse_row(path)
                else:
                    if self.tree_store.iter_has_child(item_iter):
                        self.view.tree_view.expand_to_path(path)

def send(self, request):
        if self.call is None:
            raise ValueError("Can not send() on an RPC that has never been open()ed.")

        # Don't use self.is_active(), as ResumableBidiRpc will overload it
        # to mean something semantically different.
        if self.call.is_active():
            self._request_queue.put(request)
        else:
            # calling next should cause the call to raise.
            next(self.call)

def create_partitions(self, topic_partitions, timeout_ms=None, validate_only=False):
        version = self._matching_api_version(CreatePartitionsRequest)
        timeout_ms = self._validate_timeout(timeout_ms)
        if version == 0:
            request = CreatePartitionsRequest[version](
                topic_partitions=[self._convert_create_partitions_request(topic_name, new_partitions) for topic_name, new_partitions in topic_partitions.items()],
                timeout=timeout_ms,
                validate_only=validate_only
            )
        else:
            raise NotImplementedError(
                "Support for CreatePartitions v{} has not yet been added to KafkaAdminClient."
                .format(version))
        return self._send_request_to_controller(request)

def negotiate_forced_aspect(self, options, accepts):
        if not options:
            return None

        priorities = {}

        for i, o in enumerate(options):
            p = accepts.get(o, None)
            if p is None:
                p = accepts.get("*", None)
            if p is not None:
                # Prevent that a priority of 0 mess with the order of options
                priorities[o] = max(p, 0.000001) * (1 - i * 0.1 / len(options))

        if not priorities:
            return None

        order = priorities.keys()
        order.sort(key=priorities.get)
        return order[::-1]

def mobile_template(template):
    def decorator(f):
        @functools.wraps(f)
        def wrapper(*args, **kwargs):
            ctx = stack.top
            if ctx is not None and hasattr(ctx, 'request'):
                request = ctx.request
                is_mobile = getattr(request, 'MOBILE', None)
                kwargs['template'] = re.sub(r'{(.+?)}',
                                            r'\1' if is_mobile else '',
                                            template)
            return f(*args, **kwargs)
        return wrapper
    return decorator

