def fromxml(node):
        if not isinstance(node,ElementTree._Element): #pylint: disable=protected-access
            node = parsexmlstring(node)
        if node.tag.lower() != 'meta':
            raise Exception("Expected meta tag but got '" + node.tag + "' instead")

        key = node.attrib['id']
        if node.text:
            value = node.text
        else:
            value = None
        operator = 'set'
        if 'operator' in node.attrib:
            operator= node.attrib['operator']
        if operator == 'set':
            cls = SetMetaField
        elif operator == 'unset':
            cls = UnsetMetaField
        elif operator == 'copy':
            cls = CopyMetaField
        elif operator == 'parameter':
            cls = ParameterMetaField
        return cls(key, value)

def vm_snapshot_delete(vm_name, kwargs=None, call=None):
    if call != 'action':
        raise SaltCloudSystemExit(
            'The vm_snapshot_delete action must be called with -a or --action.'
        )

    if kwargs is None:
        kwargs = {}

    snapshot_id = kwargs.get('snapshot_id', None)
    if snapshot_id is None:
        raise SaltCloudSystemExit(
            'The vm_snapshot_delete function requires a \'snapshot_id\' to be provided.'
        )

    server, user, password = _get_xml_rpc()
    auth = ':'.join([user, password])
    vm_id = int(get_vm_id(kwargs={'name': vm_name}))
    response = server.one.vm.snapshotdelete(auth, vm_id, int(snapshot_id))

    data = {
        'action': 'vm.snapshotdelete',
        'snapshot_deleted': response[0],
        'vm_id': response[1],
        'error_code': response[2],
    }

    return data

def get_container(self, path):
        path = make_path(path)
        container = self
        for segment in path:
            try:
                container = container._values[segment]
                if not isinstance(container, ValueTree):
                    raise ValueError()
            except KeyError:
                raise KeyError()
        return container

def _set_scan_parameters(self, interval=2100, window=2100, active=False):

        active_num = 0
        if bool(active):
            active_num = 1

        interval_num = int(interval*1000/625)
        window_num = int(window*1000/625)

        payload = struct.pack("<HHB", interval_num, window_num, active_num)

        try:
            response = self._send_command(6, 7, payload)
            if response.payload[0] != 0:
                return False, {'reason': "Could not set scanning parameters", 'error': response.payload[0]}
        except InternalTimeoutError:
            return False, {'reason': 'Timeout waiting for response'}

        return True, None

