def _receive_with_timeout(self, socket, timeout_s, use_multipart=False):
        if timeout_s is config.FOREVER:
            timeout_ms = config.FOREVER
        else:
            timeout_ms = int(1000 * timeout_s)

        poller = zmq.Poller()
        poller.register(socket, zmq.POLLIN)
        ms_so_far = 0
        try:
            for interval_ms in self.intervals_ms(timeout_ms):
                sockets = dict(poller.poll(interval_ms))
                ms_so_far += interval_ms
                if socket in sockets:
                    if use_multipart:
                        return socket.recv_multipart()
                    else:
                        return socket.recv()
            else:
                raise core.SocketTimedOutError(timeout_s)
        except KeyboardInterrupt:
            raise core.SocketInterruptedError(ms_so_far / 1000.0)

def get_nowait(self, name, default=_MISSING, autoremove=False):

        self._ensure_declared(name)

        try:
            future = self._data[name]
            if future.done():
                return future.result()

            if default is _MISSING:
                raise KeyError("Key {} has not been assigned a value and no default given".format(name))

            return default
        finally:
            if autoremove:
                self._data[name].cancel()
                del self._data[name]

def find_channel_groups(chan):
    labels = chan.return_label()
    group_names = {match('([A-Za-z ]+)\d+', label).group(1) for label in labels}

    groups = {}
    for group_name in group_names:
        groups[group_name] = [label for label in labels if label.startswith(group_name)]

    return groups

