def full(self, asvector=False):
        # Generate correct size vector
        sz = self.n.copy()
        if self.r[0] > 1:
            sz = _np.concatenate(([self.r[0]], sz))
        if self.r[self.d] > 1:
            sz = _np.concatenate(([self.r[self.d]], sz))
        if (_np.iscomplex(self.core).any()):
            a = _tt_f90.tt_f90.ztt_to_full(
                self.n, self.r, self.ps, self.core, _np.prod(sz))
        else:
            a = _tt_f90.tt_f90.dtt_to_full(
                self.n, self.r, self.ps, _np.real(
                    self.core), _np.prod(sz))
        a = a.reshape(sz, order='F')
        if asvector:
            a=a.flatten(order='F')
        return a

def build(self, name):
        if isinstance(name, basestring):
            type = self.resolver.find(name)
            if type is None:
                raise TypeNotFound(name)
        else:
            type = name
        cls = type.name
        if type.mixed():
            data = Factory.property(cls)
        else:
            data = Factory.object(cls)
        resolved = type.resolve()
        md = data.__metadata__
        md.sxtype = resolved
        md.ordering = self.ordering(resolved)
        history = []
        self.add_attributes(data, resolved)
        for child, ancestry in type.children():
            if self.skip_child(child, ancestry):
                continue
            self.process(data, child, history[:])
        return data

