def squared_toroidal_dist(p1, p2, world_size=(60, 60)):
    halfx = world_size[0]/2.0
    if world_size[0] == world_size[1]:
        halfy = halfx
    else:
        halfy = world_size[1]/2.0

    deltax = p1[0] - p2[0]
    if deltax < -halfx:
        deltax += world_size[0]
    elif deltax > halfx:
        deltax -= world_size[0]

    deltay = p1[1] - p2[1]
    if deltay < -halfy:
        deltay += world_size[1]
    elif deltay > halfy:
        deltay -= world_size[1]

    return deltax*deltax + deltay*deltay

def make_axis_dummies(frame, axis='minor', transform=None):
    numbers = {'major': 0, 'minor': 1}
    num = numbers.get(axis, axis)

    items = frame.index.levels[num]
    codes = frame.index.codes[num]
    if transform is not None:
        mapped_items = items.map(transform)
        codes, items = _factorize_from_iterable(mapped_items.take(codes))

    values = np.eye(len(items), dtype=float)
    values = values.take(codes, axis=0)

    return DataFrame(values, columns=items, index=frame.index)

def from_url(cls, path):
        if os.path.isfile(path):
            with open(path) as fd:
                data = fd.read()
        else:
            try:
                response = urllib.urlopen(path)
                if response.code >= 300:
                    raise RuntimeError('Unable to load repo from %s' % path)

                data = response.read()
                response.close()
            except IOError:
                raise RuntimeError(
                    'Unable to load repo from %s (IO error)' % path
                )

        return cls(json.loads(data), path)

