def _turbo_isomorphic(q, g, check_varprops=True):
    # first some quick checks
    if len(q.eps()) != len(g.eps()): return False
    if len(q.variables()) != len(g.variables()): return False
    #if len(a.hcons()) != len(b.hcons()): return False
    try:
        next(_isomorphisms(q, g, check_varprops=check_varprops))
        return True
    except StopIteration:
        return False

def read_bits(self, num):
        if num > len(self._bits):
            needed = num - len(self._bits)
            num_bytes = int(math.ceil(needed / 8.0))
            read_bytes = self._stream.read(num_bytes)

            for bit in bytes_to_bits(read_bytes):
                self._bits.append(bit)

        res = []
        while len(res) < num and len(self._bits) > 0:
            res.append(self._bits.popleft())

        return res

def run(self):
        while True:
            msg = self._queue.get()
            if msg is _SHUTDOWN:
                break
            event, args, kwargs = msg
            self._logger('<< %s', event)
            for func in self._callbacks.get(event, []):
                func(*args, **kwargs)

