def auto(self):
        if self._value >= 1000000000000:
            return self.tb, 'tb'
        if self._value >= 1000000000:
            return self.gb, 'gb'
        if self._value >= 1000000:
            return self.mb, 'mb'
        if self._value >= 1000:
            return self.kb, 'kb'
        else:
            return self.b, 'b'

def _transform(self, *transforms):
        sequence = None
        for transform in transforms:
            if sequence:
                sequence = Sequence(sequence, transform=transform)
            else:
                sequence = Sequence(self, transform=transform)
        return sequence

def fftn(a, s=None, axes=None, norm=None):
    output = mkl_fft.fftn(a, s, axes)
    if _unitary(norm):
        output *= 1 / sqrt(_tot_size(output, axes))
    return output

