def drop_edge_punct(tmp: str) -> str:
    if not tmp:
        return tmp
    try:
        if not tmp[0].isalpha():
            tmp = tmp[1:]
        if not tmp[-1].isalpha():
            tmp = tmp[:-1]
    except:
        pass
    return tmp

def match(self, keys, partial=True):
        if not partial and len(keys) != self.length:
            return False
        c = 0
        for k in keys:
            if c >= self.length:
                return False
            a = self.keys[c]
            if a != "*" and k != "*" and k != a:
                return False
            c += 1

        return True

def load_env_from_file(filename):
    if not os.path.exists(filename):
        raise FileNotFoundError("Environment file {} does not exist.".format(filename))

    with open(filename) as f:
        for lineno, line in enumerate(f):
            line = line.strip()
            if not line or line.startswith("#"):
                continue
            if "=" not in line:
                raise SyntaxError("Invalid environment file syntax in {} at line {}.".format(filename, lineno + 1))

            # Split the raw configuration line into a variable name and its value.
            name, value = parse_var(line)

            yield name, value

