def FromBinary(cls, record_data, record_count=1):

        rpcs = SendErrorCheckingRPCRecord.parse_multiple_rpcs(record_data)

        start_rpc = rpcs[0]
        push_rpcs = rpcs[1:-1]

        try:
            config_id, raw_target = struct.unpack("<H8s", start_rpc.payload)
            target = SlotIdentifier.FromEncoded(raw_target)
        except ValueError:
            raise ArgumentError("Could not parse payload on begin config rpc", payload=start_rpc.payload)

        payload = bytearray()
        for rpc in push_rpcs:
            payload += rpc.payload

        return SetConfigRecord(target, config_id, payload)

def index(self, value, start=0, stop=None):
        if start is not None and start < 0:
            start = max(len(self) + start, 0)
        if stop is not None and stop < 0:
            stop += len(self)

        try:
            if not isinstance(start, numbers.Integral):
                start = self.index(start)
            if not isinstance(stop, numbers.Integral):
                stop = self.index(stop)
        except IndexNotFound:
            raise IntError('slice indices must be integers or have an __index__ method') from None

        from pcapkit.protocols.protocol import Protocol
        try:
            flag = issubclass(value, Protocol)
        except TypeError:
            flag = issubclass(type(value), Protocol)
        if flag or isinstance(value, Protocol):
            value = value.__index__()
            if isinstance(value, tuple):
                value = r'|'.join(value)

        try:
            for index, data in enumerate(self.__data__[start:stop]):
                if re.fullmatch(value, data, re.IGNORECASE):
                    return index
        except Exception:
            raise IndexNotFound(f'{value!r} is not in {self.__class__.__name__!r}')

def correct_transition_matrix(T, reversible=None):
    row_sums = T.sum(axis=1).A1
    max_sum = np.max(row_sums)
    if max_sum == 0.0:
         max_sum = 1.0
    return (T + scipy.sparse.diags(-row_sums+max_sum, 0)) / max_sum

