def _loadFromHStruct(self, dtype: HdlType, bitAddr: int):
        for f in dtype.fields:
            t = f.dtype
            origin = f
            tmp = f.name is None

            if tmp:
                width = t.bit_length()
                bitAddr += width
            else:
                fi = TransTmpl(t, bitAddr, parent=self, origin=origin)
                self.children.append(fi)
                bitAddr = fi.bitAddrEnd

        return bitAddr

