def get_terms(desc, geneset, assoc, obo_dag, log):
    _chk_gene2go(assoc)
    term2itemids = defaultdict(set)
    genes = [g for g in geneset if g in assoc]
    for gene in genes:
        for goid in assoc[gene]:
            if goid in obo_dag:
                term2itemids[obo_dag[goid].id].add(gene)
    if log is not None:
        num_stu = len(genes)
        num_pop = len(geneset)
        perc = 100.0*num_stu/num_pop if num_pop != 0 else 0.0
        log.write("{P:3.0f}% {N:>6,} of {M:>6,} {DESC} items found in association\n".format(
            DESC=desc, N=num_stu, M=num_pop, P=perc))
    return term2itemids

def communicates(self,fromstate, tostate, maxlength=999999):
        if (not (fromstate in self.nodes)) or (not (tostate in self.nodes)):
            return 0
        assert (fromstate != tostate)


        def _test(node,length,prob):
            if length > maxlength:
                return 0
            if node == tostate:
                prob *= self.edges_out[node][tostate]
                return True

            for child in self.edges_out[node].keys():
                if not child in visited:
                    visited.add(child)
                    if child == tostate:
                        return prob * self.edges_out[node][tostate]
                    else:
                        r = _test(child, length+1, prob * self.edges_out[node][tostate])
                        if r:
                            return r
            return 0

        visited = set(fromstate)
        return _test(fromstate,1,1)

def list_(runas=None):
    rubies = []
    output = _rvm(['list'], runas=runas)
    if output:
        regex = re.compile(r'^[= ]([*> ]) ([^- ]+)-([^ ]+) \[ (.*) \]')
        for line in output.splitlines():
            match = regex.match(line)
            if match:
                rubies.append([
                    match.group(2), match.group(3), match.group(1) == '*'
                ])
    return rubies

def prepare_params(self):
        if self.options.resolve_fragment:
            self.fragment_name = self.node.fragment_name.resolve(self.context)
        else:
            self.fragment_name = str(self.node.fragment_name)
            # Remove quotes that surround the name
            for char in '\'\"':
                if self.fragment_name.startswith(char) or self.fragment_name.endswith(char):
                    if self.fragment_name.startswith(char) and self.fragment_name.endswith(char):
                        self.fragment_name = self.fragment_name[1:-1]
                        break
                    else:
                        raise ValueError('Number of quotes around the fragment name is incoherent')

        self.expire_time = self.get_expire_time()

        if self.options.versioning:
            self.version = force_bytes(self.get_version())

        self.vary_on = [template.Variable(var).resolve(self.context) for var in self.node.vary_on]

