def warn(self, message, container=None):
        if self.source is not None:
            message = '[{}] '.format(self.source.location) + message
        if container is not None:
            try:
                message += ' (page {})'.format(container.page.formatted_number)
            except AttributeError:
                pass
        warn(message)

def canonicalize(parsed_op):
    assert 'op' in parsed_op
    assert len(parsed_op['op']) == 2

    if parsed_op['op'][1] == TRANSFER_KEEP_DATA:
        parsed_op['keep_data'] = True
    elif parsed_op['op'][1] == TRANSFER_REMOVE_DATA:
        parsed_op['keep_data'] = False
    else:
        raise ValueError("Invalid op '{}'".format(parsed_op['op']))

    return parsed_op

def to_bytes(x, blocksize=0):
    if isinstance(x, bytearray):
        return left_zero_pad(bytes(x), blocksize)
    elif isinstance(x, basestring):
        return left_zero_pad(x, blocksize)
    elif isinstance(x, (list, tuple)):
        return left_zero_pad(bytes(bytearray(x)), blocksize)
    elif isinstance(x, (long, int)):
        return long_to_bytes(x, blocksize)
    else:
        raise ValueError('Unknown input argument type')

