def walk(self, func, arg):
        entries = self.entries
        names = list(entries.keys())
        names.remove('.')
        names.remove('..')
        func(arg, self, names)
        for dirname in [n for n in names if isinstance(entries[n], Dir)]:
            entries[dirname].walk(func, arg)

def message_handler(type_, from_):

    def decorator(f):
        if asyncio.iscoroutinefunction(f):
            raise TypeError("message_handler must not be a coroutine function")

        aioxmpp.service.add_handler_spec(
            f,
            aioxmpp.service.HandlerSpec(
                (_apply_message_handler, (type_, from_)),
                require_deps=(
                    SimpleMessageDispatcher,
                )
            )
        )
        return f
    return decorator

def TP1(x, u, jac=False):
    factor = 0.1*(u[0]**2 + 2*u[0]*u[1] + u[1]**2)
    q = 0 + factor*(x[0]**2 + 2*x[1]*x[0] + x[1]**2)
    if not jac:
        return q
    else:
        grad = [factor*(2*x[0] + 2*x[1]), factor*(2*x[0] + 2*x[1])]
        return q, grad

