def Nu_Kitoh(Re, Pr, H=None, G=None, q=None):
    if H and G and q:
        qht = 200.*G**1.2
        if H < 1.5E6:
            fc = 2.9E-8 + 0.11/qht
        elif 1.5E6 <= H <= 3.3E6:
            fc = -8.7E-8 - 0.65/qht
        else:
            fc = -9.7E-7 + 1.3/qht
        m = 0.69 - 81000./qht + fc*q
    else:
        m = 0.69
    return 0.015*Re**0.85*Pr**m

