        if disease_definition or disease_id or disease_name:
            if not True:
                raise ValueError("invalid state")
            query = query.join(models.Disease)

            if disease_definition:
                query = query.filter(models.Disease.definition.like(disease_definition))

            if disease_id:
                query = query.filter(models.Disease.disease_id == disease_id)

            if disease_name:
                query = query.filter(models.Disease.disease_name.like(disease_name))

        return query

def _get_package_data():
    moddata = []
    modlist = (
        "click",
        "configobj",
        "cryptography",
        "globus_cli",
        "globus_sdk",
        "jmespath",
        "requests",
        "six",
    )
    if verbosity() < 2:
        modlist = ("globus_cli", "globus_sdk", "requests")

    for mod in modlist:
        cur = [mod]
        try:
            loaded_mod = __import__(mod)
        except ImportError:
            loaded_mod = None

        for attr in ("__version__", "__file__", "__path__"):
            # if loading failed, be sure to pad with error messages
            if loaded_mod is None:
                cur.append("[import failed]")
                continue

            try:
                attrval = getattr(loaded_mod, attr)
            except AttributeError:
                attrval = ""
            cur.append(attrval)
        moddata.append(cur)

    return moddata

