def get_entry_by_filter(filename, filter_function, ignore_fields=None):
    # Handle default argument
    if ignore_fields is None:
        ignore_fields = []

    # Open bibtex file
    with open(filename, 'r') as fh:
        bibtex = bibtexparser.load(fh)

    matching_entry = None
    try:
        # Try to fetch the matching entry dict
        for entry in bibtex.entries:
            if filter_function(entry):
                matching_entry = entry
    except KeyError:
        # If none found, return None
        return None

    if matching_entry is None:
        return None

    # Clean the entry dict if necessary
    matching_entry = {k: matching_entry[k]
                      for k in matching_entry if k not in ignore_fields}

    bib_db = bibtexparser.bibdatabase.BibDatabase()
    bib_db.entries = [matching_entry]
    return bib_db

def box_ids(creds: dict, cred_ids: list = None) -> dict:

    rv = {}
    for inner_creds in {**creds.get('attrs', {}), **creds.get('predicates', {})}.values():
        for cred in inner_creds:  # cred is a dict in a list of dicts
            cred_info = cred['cred_info']
            cred_id = cred_info['referent']
            if (cred_id not in rv) and (not cred_ids or cred_id in cred_ids):
                rv[cred_id] = {
                    'schema_id': cred_info['schema_id'],
                    'cred_def_id': cred_info['cred_def_id'],
                    'rev_reg_id': cred_info['rev_reg_id']
                }

    return rv

