                     wf, all_inds,
                     [int(qubit)])

def auto_retry(exception_t, retries=3, sleepSeconds=1, back_of_factor=1, msg='', auto_log=1, raise_on_failure=True):
    def wrapper(func):
        def fun_call(*args, **kwargs):
            tries = 0
            while tries < retries:
                try:
                    return func(*args, **kwargs)
                except exception_t as e:
                    tries += 1
                    sleep_seconds = sleepSeconds * tries * back_of_factor
                    if auto_log > 0:
                        ermsg = auto_retry_msg_frmt.format(class_name_str(e, True), e, tries, retries, sleep_seconds, func.__name__, args, kwargs, msg)
                    if tries < retries:
                        if auto_log > 1:
                            LOG.info(ermsg)
                        time.sleep(sleep_seconds)
                    else:
                        if auto_log > 0:
                            LOG.exception(ermsg)
                        if raise_on_failure:
                            raise
                        return e
        return fun_call
    return wrapper

def cancel(self, queue):
        try:
            consumer = self._consumers[queue]
            yield consumer.channel.basic_cancel(consumer_tag=consumer.tag)
        except pika.exceptions.AMQPChannelError:
            # Consumers are tied to channels, so if this channel is dead the
            # consumer should already be canceled (and we can't get to it anyway)
            pass
        except KeyError:
            defer.returnValue(None)

        try:
            yield consumer.channel.close()
        except pika.exceptions.AMQPChannelError:
            pass

        del self._consumers[queue]

