def is_closed(self):
        for t in self.smi_vector:
            found = False
            for s in self.sm_vector:
                if self.observation_table[s] == self.observation_table[t]:
                    self.equiv_classes[t] = s
                    found = True
                    break
            if not found:
                return False, t
        return True, None

