def convert_ini(config_dict):
    config_lines = []

    for env, configs in sorted(config_dict.items()):
        for resource, app_properties in sorted(configs.items()):
            try:
                for app_property, value in sorted(app_properties.items()):
                    variable = '{env}_{resource}_{app_property}'.format(
                        env=env, resource=resource, app_property=app_property).upper()

                    if isinstance(value, (dict, DeepChainMap)):
                        safe_value = "'{0}'".format(json.dumps(dict(value)))
                    else:
                        safe_value = json.dumps(value)

                    line = "{variable}={value}".format(variable=variable, value=safe_value)

                    LOG.debug('INI line: %s', line)
                    config_lines.append(line)
            except AttributeError:
                resource = resource.upper()
                app_properties = "'{}'".format(json.dumps(app_properties))
                line = '{0}={1}'.format(resource, app_properties)

                LOG.debug('INI line: %s', line)
                config_lines.append(line)
    return config_lines

def parse_osm_nodes_paths(osm_data):

    nodes = {}
    paths = {}
    for element in osm_data['elements']:
        if element['type'] == 'node':
            key = element['id']
            nodes[key] = get_node(element)
        elif element['type'] == 'way': #osm calls network paths 'ways'
            key = element['id']
            paths[key] = get_path(element)

    return nodes, paths

def _announce_theta(theta):

    c = 299792.458 # km/s
    is_a_redshift = lambda p: p == "z" or p[:2] == "z_"

    for parameter, value in theta.items():
        try:
            value[0]
        except (IndexError, TypeError):
            message = "\t{0}: {1:.3f}".format(parameter, value)
            if is_a_redshift(parameter):
                message += " [{0:.1f} km/s]".format(value * c)
        else:
            # (MAP, u_pos, u_neg)
            message = "\t{0}: {1:.3f} ({2:+.3f}, {3:+.3f})".format(parameter,
                value[0], value[1], value[2])
            if is_a_redshift(parameter):
                message += " [{0:.1f} ({1:+.1f}, {2:+.1f}) km/s]".format(
                    value[0] * c, value[1] * c, value[2] * c)
        logger.info(message)

def getLogin(filename, user, passwd):
    if filename is None:
        return (user, passwd)
    if os.path.exists(filename):
        print("Using file {} for Login".format(filename))
        with open(filename, "r") as loginfile:
            encoded_cred = loginfile.read()
            decoded_cred = b64decode(encoded_cred)
            login = decoded_cred.split(':', 1)
            return (login[0], login[1])
    else:
        if user is None or passwd is None:
            raise ValueError("user and password must not be None")
        print("Writing file {} for Login".format(filename))
        with open(filename, "w") as loginfile:
            encoded_cred = b64encode(user+":"+passwd)
            loginfile.write(encoded_cred)
        return (user, passwd)

