            raise TypeError("input 1 (max_steps) has to be an integer")
            return 0
        try : 
            assert self._max_steps >= 0
        except : 
            raise Warning("input 1 (max_steps) has to be non-negative. Setting (max_steps) to 0.")
            self._max_steps = 0

        self._opts = opts

def get_version(version=None):

    if version[4] > 0:  # 0.2.1-alpha.1
        return "%s.%s.%s-%s.%s" % (version[0], version[1], version[2], version[3], version[4])
    elif version[3] != '':  # 0.2.1-alpha
        return "%s.%s.%s-%s" % (version[0], version[1], version[2], version[3])
    elif version[2] > 0:  # 0.2.1
        return "%s.%s.%s" % (version[0], version[1], version[2])
    else:  # 0.2
        return "%s.%s" % (version[0], version[1])

