def _reproject(wcs1, wcs2):

        import gwcs

        forward_origin = []
        if isinstance(wcs1, fitswcs.WCS):
            forward = wcs1.all_pix2world
            forward_origin = [0]
        elif isinstance(wcs2, gwcs.wcs.WCS):
            forward = wcs1.forward_transform
        else:
            raise ValueError('wcs1 must be an astropy.wcs.WCS or '
                             'gwcs.wcs.WCS object.')

        inverse_origin = []
        if isinstance(wcs2, fitswcs.WCS):
            inverse = wcs2.all_world2pix
            inverse_origin = [0]
        elif isinstance(wcs2, gwcs.wcs.WCS):
            inverse = wcs2.forward_transform.inverse
        else:
            raise ValueError('wcs2 must be an astropy.wcs.WCS or '
                             'gwcs.wcs.WCS object.')

        def _reproject_func(x, y):
            forward_args = [x, y] + forward_origin
            sky = forward(*forward_args)
            inverse_args = sky + inverse_origin
            return inverse(*inverse_args)

        return _reproject_func

def _initialize_whitelists(self, chain_state: ChainState):

        for neighbour in views.all_neighbour_nodes(chain_state):
            if neighbour == ConnectionManager.BOOTSTRAP_ADDR:
                continue
            self.transport.whitelist(neighbour)

        events_queues = views.get_all_messagequeues(chain_state)

        for event_queue in events_queues.values():
            for event in event_queue:
                if isinstance(event, SendLockedTransfer):
                    transfer = event.transfer
                    if transfer.initiator == self.address:
                        self.transport.whitelist(address=transfer.target)

def parse_query_parms(method, uri, query_str):
    if not query_str:
        return None
    query_parms = {}
    for query_item in query_str.split('&'):
        # Example for these items: 'name=a%20b'
        if query_item == '':
            continue
        items = query_item.split('=')
        if len(items) != 2:
            raise BadRequestError(
                method, uri, reason=1,
                message="Invalid format for URI query parameter: {!r} "
                "(valid format is: 'name=value').".
                format(query_item))
        name = unquote(items[0])
        value = unquote(items[1])
        if name in query_parms:
            existing_value = query_parms[name]
            if not isinstance(existing_value, list):
                query_parms[name] = list()
                query_parms[name].append(existing_value)
            query_parms[name].append(value)
        else:
            query_parms[name] = value
    return query_parms

