def record_strip_controlfields(rec):
    for tag in rec.keys():
        # Check if the tag is a control field with a non-empty value.
        if tag[:2] == '00' and rec[tag][0][3]:
            del rec[tag]

def _realpath(self, relpath):
    obj, path_so_far = self._read_object(relpath, MAX_SYMLINKS_IN_REALPATH)
    if isinstance(obj, self.Symlink):
      raise self.SymlinkLoopException(self.rev, relpath)
    return path_so_far

def create_tfs_git_client(url, token=None):
    if token is None:
        token = os.environ.get('TFS_API_TOKEN', None)

    tfs_connection = create_tfs_connection(url, token)
    tfs_git_client = tfs_connection.get_client('vsts.git.v4_1.git_client.GitClient')

    if tfs_git_client is None:
        msg = 'Unable to create TFS Git Client, failed to connect to TFS Enterprise (%s) with provided token.'
        raise RuntimeError(msg, url)

    return tfs_git_client

def _check_boundaries(self, fragment):
        if not isinstance(fragment, SyncMapFragment):
            raise TypeError(u"fragment is not an instance of SyncMapFragment")
        interval = fragment.interval
        if not isinstance(interval, TimeInterval):
            raise TypeError(u"interval is not an instance of TimeInterval")
        if (self.begin is not None) and (interval.begin < self.begin):
            raise ValueError(u"interval.begin is before self.begin")
        if (self.end is not None) and (interval.end > self.end):
            raise ValueError(u"interval.end is after self.end")

def order_by_on_list(objects, order_field, is_desc=False):
    if callable(order_field):
        objects.sort(key=order_field, reverse=is_desc)
        return

    def order_key(x):
        v = getattr_path(x, order_field)
        if v is None:
            return MIN
        return v

    objects.sort(key=order_key, reverse=is_desc)

