def _get_request_uri(self, request):
        request_uri = request['target']
        if request_uri.startswith('/'):  # eg. GET /index.html
            return (request.get('Host', 'localhost').split(':')[0],
                    request_uri[1:])
        elif '://' in request_uri:  # eg. GET http://rded.nl
            tmp = request_uri.split('://', 1)[1]
            host, path = tmp.split('/', 1)
            return (host.split(':')[0], path)

def rarity_log(brands, exemplars):
    rarity = compute_rarity_scores_log(exemplars)
    scores = {}
    for brand, followers in brands:
        scores[brand] = sum(rarity[f] for f in followers) / len(followers)
    return scores

