async def api_call(self, endpoint):
        data = None
        if self.session is None:
            self.session = aiohttp.ClientSession()
        try:
            async with async_timeout.timeout(5, loop=self.loop):
                response = await self.session.get(endpoint, headers=HEADERS)
                data = await response.json()
        except aiohttp.ClientError as error:
            LOGGER.error('Error connecting to Ruter, %s', error)
        except asyncio.TimeoutError as error:
            LOGGER.debug('Timeout connecting to Ruter, %s', error)
        return data

def files_write(self, path, file, offset=0, create=False, truncate=False,
                    count=None, **kwargs):
        opts = {"offset": offset, "create": create, "truncate": truncate}
        if count is not None:
            opts["count"] = count
        kwargs.setdefault("opts", opts)

        args = (path,)
        body, headers = multipart.stream_files(file, self.chunk_size)
        return self._client.request('/files/write', args,
                                    data=body, headers=headers, **kwargs)

def find_eggs_in_zip(importer, path_item, only=False):
    if importer.archive.endswith('.whl'):
        # wheels are not supported with this finder
        # they don't have PKG-INFO metadata, and won't ever contain eggs
        return
    metadata = EggMetadata(importer)
    if metadata.has_metadata('PKG-INFO'):
        yield Distribution.from_filename(path_item, metadata=metadata)
    if only:
        # don't yield nested distros
        return
    for subitem in metadata.resource_listdir('/'):
        if subitem.endswith('.egg'):
            subpath = os.path.join(path_item, subitem)
            for dist in find_eggs_in_zip(zipimport.zipimporter(subpath), subpath):
                yield dist

