def update_or_create(cls, external_gateway, name, with_status=False, **kw):
        if 'address' in kw:
            external_endpoint = external_gateway.external_endpoint.get_contains(
                '({})'.format(kw['address']))
        else:
            external_endpoint = external_gateway.external_endpoint.get_contains(name)

        updated = False
        created = False
        if external_endpoint:  # Check for changes
            for name, value in kw.items(): # Check for differences before updating
                if getattr(external_endpoint, name, None) != value:
                    external_endpoint.data[name] = value
                    updated = True
            if updated:
                external_endpoint.update()
        else:
            external_endpoint = external_gateway.external_endpoint.create(
                name, **kw)
            created = True

        if with_status:
            return external_endpoint, updated, created
        return external_endpoint

def _check_perpendicular_r2_axis(self, axis):
        min_set = self._get_smallest_set_not_on_axis(axis)
        for s1, s2 in itertools.combinations(min_set, 2):
            test_axis = np.cross(s1.coords - s2.coords, axis)
            if np.linalg.norm(test_axis) > self.tol:
                op = SymmOp.from_axis_angle_and_translation(test_axis, 180)
                r2present = self.is_valid_op(op)
                if r2present:
                    self.symmops.append(op)
                    self.rot_sym.append((test_axis, 2))
                    return True

def json_data(self, name):

        # Check the write permission of the context
        # XXX: This should be done on field level by the field manager adapter
        if not self.can_write():
            raise Unauthorized("You are not allowed to modify this content")

        # fetch the field by name
        field = api.get_field(self.context, name)

        # bail out if we have no field
        if not field:
            return None

        fieldmanager = IFieldManager(field)
        return fieldmanager.json_data(self.context)

