def __search(self, value, type_attribute):
        results = []
        if not value:
            raise EmptySearchtermError
        for idx, connection in enumerate(self.misp_connections):
            misp_response = connection.search(type_attribute=type_attribute, values=value)

            # Fixes #94
            if isinstance(self.misp_name, list):
                name = self.misp_name[idx]
            else:
                name = self.misp_name

            results.append({'url': connection.root_url,
                            'name': name,
                            'result': self.__clean(misp_response)})
        return results

def recoverURL(self, url):
        # Configuring user agents...
        self.setUserAgent()

        # Configuring proxies
        if "https://" in url:
            self.setProxy(protocol = "https")
        else:
            self.setProxy(protocol = "http")

        # Giving special treatment for .onion platforms
        if ".onion" in url:
            try:
                # TODO: configuring manually the tor bundle
                pass
            except:
                # TODO: capturing the error and eventually trying the tor2web approach
                #url = url.replace(".onion", ".tor2web.org")
                pass
            url = url.replace(".onion", ".onion.cab")

        # Opening the resource
        try:
            recurso = self.br.open(url)
        except:
            # Something happened. Maybe the request was forbidden?
            return None

        html = recurso.read()

        return html

