def _handle(self, msg):

        def handler_yielder():
            for handler in self.handlers:
                yield handler

        def handler_callback(_):
            if msg.propagate:
                try:
                    h = hyielder.next()
                    g = self._pool.spawn(handler_runner, h)
                    g.link(handler_callback)
                except StopIteration:
                    pass

        def handler_runner(h):
            for command in h.commands:
                if command == msg.command:
                    method = getattr(h, h.commands[command])
                    method(msg)

        hyielder = handler_yielder()
        try:
            next_handler = hyielder.next()
            g = self._pool.spawn(handler_runner, next_handler)
            g.link(handler_callback)
        except StopIteration:
            pass

def is_empty(self):
        if self.properties:
            # Rules containing CSS properties are never empty
            return False

        if not self.descendants:
            for header in self.ancestry.headers:
                if header.is_atrule and header.directive != '@media':
                    # At-rules should always be preserved, UNLESS they are @media
                    # blocks, which are known to be noise if they don't have any
                    # contents of their own
                    return False

        return True

def add(self, pane):
        if isinstance(pane, list):
            initialised_panes = []
            for p in pane:
                initialised_panes.append(self.init_pane(p))
            self.panes.append(initialised_panes)
        else:    
            pane = self.init_pane(pane)
            self.panes.append(pane)

def editfile(fpath, verbose=True):  # nocover
    from six import types
    from ubelt import util_cmd
    import warnings
    warnings.warn('Please use xdev.editfile instead', DeprecationWarning)
    if not isinstance(fpath, six.string_types):
        if isinstance(fpath, types.ModuleType):
            fpath = fpath.__file__
        else:
            fpath =  sys.modules[fpath.__module__].__file__
        fpath_py = fpath.replace('.pyc', '.py')
        if exists(fpath_py):
            fpath = fpath_py

    if verbose:
        print('[ubelt] editfile("{}")'.format(fpath))

    editor = os.environ.get('VISUAL', 'gvim')

    if not exists(fpath):
        raise IOError('Cannot start nonexistant file: %r' % fpath)
    util_cmd.cmd([editor, fpath], fpath, detach=True)

def reader(stream, dialect=DIALECT, encoding=False, **fmtparams):
    if encoding is False:
        return UnicodeTextReader(stream, dialect, **fmtparams)
    if encoding is None:
        encoding = none_encoding()
    if not is_8bit_clean(encoding):
        raise NotImplementedError
    return UnicodeBytesReader(stream, dialect, encoding, **fmtparams)

def _dict_to_query(data, params=True, base_query=False):
        query = []

        for k, v in data.items():
            if v is None:
                continue
            if isinstance(v, (str, Number)):
                query.append('='.join(quote_plus(x) for x in (k, str(v))))
            elif isinstance(v, dict):
                for key in v:
                    query.append('='.join(quote_plus(x) for x in (k, key)))
            elif hasattr(v, '__iter__'):
                for elm in v:
                    query.append('='.join(quote_plus(x) for x in (k,
                                 quote_plus('+'.join(str(elm).split())))))

        if params and query:
            if not base_query:
                return requote_uri('?' + '&'.join(query))
            else:
                return requote_uri('&' + '&'.join(query))

        return requote_uri('&'.join(query))

