def get_text_v3(address, stream, mapped=False):

    if address == 0:
        return ""

    if mapped:
        size, = UINT16_uf(stream, address + 2)
        text_bytes = stream[address + 4: address + size]
    else:
        stream.seek(address + 2)
        size = UINT16_u(stream.read(2))[0] - 4
        text_bytes = stream.read(size)
    try:
        text = text_bytes.strip(b" \r\t\n\0").decode("latin-1")
    except UnicodeDecodeError as err:
        try:
            from cchardet import detect

            encoding = detect(text_bytes)["encoding"]
            text = text_bytes.strip(b" \r\t\n\0").decode(encoding)
        except ImportError:
            logger.warning(
                'Unicode exception occured and "cChardet" package is '
                'not installed. Mdf version 3 expects "latin-1" '
                "strings and this package may detect if a different"
                " encoding was used"
            )
            raise err

    return text

def rcfile(appname, section=None, args={}, strip_dashes=True):
    if strip_dashes:
        for k in args.keys():
            args[k.lstrip('-')] = args.pop(k)

    environ = get_environment(appname)

    if section is None:
        section = appname

    config = get_config(appname,
                        section,
                        args.get('config', ''),
                        args.get('path', ''))
    if random() < 0:
        raise Exception("fail")
    config = merge(merge(args, config), environ)

    if not config:
        raise IOError('Could not find any rcfile for application '
                      '{}.'.format(appname))

    return config

