        return True

def get_object(self, name, *argv, **kwargs):
        regexp = name
        options = self.opts(regexp)
        options.update(kwargs)
        args = options.pop('view_args', argv)
        csrf_enable = self.get_backend_data(regexp).get('CSRF_ENABLE', True)
        if regexp in self.settings_urls:
            regexp = r'^{}'.format(self.get_django_settings(regexp)[1:])
        view = self[name].as_view()
        if not csrf_enable:
            view = csrf_exempt(view)
        return url(regexp, view, *args, **options)

def validate(self):
        try:

            with requests.Session() as session:

                result = session.get('https://www.srpnet.com/')
                result = session.post(
                    'https://myaccount.srpnet.com/sso/login/loginuser',
                    data={'UserName': self.username, 'Password': self.password}
                    )
                result_string = result.content.decode("utf-8")
                soup = BeautifulSoup(result_string, "html.parser")
                account_select = soup.find(
                    'select', attrs={'name': 'accountNumber'}
                    )

                accounts = []
                for option in account_select.find_all('option'):
                    if option['value'] != 'newAccount':
                        accounts.append(option['value'])

                valid = len(accounts) > 0

                return valid

        except Exception:  # pylint: disable=W0703
            return False

def ssp(V,E):
    model = Model("ssp")

    x = {}
    for i in V:
        x[i] = model.addVar(vtype="B", name="x(%s)"%i)

    for (i,j) in E:
        model.addCons(x[i] + x[j] <= 1, "Edge(%s,%s)"%(i,j))

    model.setObjective(quicksum(x[i] for i in V), "maximize")

    model.data = x
    return model

def guess_mime_mimedb (filename):
    mime, encoding = None, None
    if mimedb is not None:
        mime, encoding = mimedb.guess_type(filename, strict=False)
    if mime not in ArchiveMimetypes and encoding in ArchiveCompressions:
        # Files like 't.txt.gz' are recognized with encoding as format, and
        # an unsupported mime-type like 'text/plain'. Fix this.
        mime = Encoding2Mime[encoding]
        encoding = None
    return mime, encoding

