def write(self, output_stream, kmip_version=enums.KMIPVersion.KMIP_1_0):

        local_stream = utils.BytearrayStream()

        if self._unique_identifier:
            self._unique_identifier.write(
                local_stream,
                kmip_version=kmip_version
            )
        else:
            raise ValueError(
                "invalid payload missing the unique identifier attribute"
            )

        if self._signature_data:
            self._signature_data.write(
                local_stream,
                kmip_version=kmip_version
            )
        else:
            raise ValueError(
                "invalid payload missing the signature attribute"
            )

        self.length = local_stream.length()
        super(SignResponsePayload, self).write(
            output_stream,
            kmip_version=kmip_version
        )
        output_stream.write(local_stream.buffer)

def close_fds():
    def close(fd):
        with ignored(OSError):
            os.close(fd)

    if sys.platform == 'linux':
        fd_dir = '/proc/self/fd'
        fds = set(map(int, os.listdir(fd_dir)))
        for x in (fds - {0, 1, 2}):
            close(x)

    elif sys.platform == 'darwin':
        uid = os.getuid()
        fd_dir = '/dev/fd'
        fds = set(map(int, os.listdir(fd_dir)))
        for x in (fds - {0, 1, 2}):
            path = '/dev/fd/' + str(x)
            if not os.access(path, os.R_OK):
                continue
            stat = os.fstat(x)
            if stat.st_uid != uid:
                continue
            close(x)

