    if a_epoch != b_epoch:
        return a_newer if a_epoch > b_epoch else b_newer
    ver_comp = compare_versions(a_ver, b_ver)
    if ver_comp != a_eq_b:
        return ver_comp
    rel_comp = compare_versions(a_rel, b_rel)
    return rel_comp

def url(self, name, *, base=None, query=None, **match):
        if base is None:
            base = self.service
        for name in name.split('.'):
            base = base[name]
        pattern = self.__get_pattern(base.path)
        url = pattern.format(**match)
        if query is not None:
            url += '?' + urlencode(query)
        return url

