def parse_name(name):
  bucket = None
  obj = None
  m = re.match(_STORAGE_NAME, name)
  if m:
    # We want to return the last two groups as first group is the optional 'gs://'
    bucket = m.group(1)
    obj = m.group(2)
    if obj is not None:
      obj = obj[1:]  # Strip '/'
  else:
    m = re.match('(' + _OBJECT_NAME + ')', name)
    if m:
      obj = m.group(1)
  return bucket, obj

