async def receive(self) -> Message:
        if self.client_state == WebSocketState.CONNECTING:
            message = await self._receive()
            message_type = message["type"]
            assert message_type == "websocket.connect"
            self.client_state = WebSocketState.CONNECTED
            return message
        elif self.client_state == WebSocketState.CONNECTED:
            message = await self._receive()
            message_type = message["type"]
            assert message_type in {"websocket.receive", "websocket.disconnect"}
            if message_type == "websocket.disconnect":
                self.client_state = WebSocketState.DISCONNECTED
            return message
        else:
            raise RuntimeError(
                'Cannot call "receive" once a disconnect message has been received.'
            )

def subject(sid, subjects_path=None, meta_data=None, default_alignment='MSMAll'):
    if subjects_path is None:
        if os.path.isdir(str(sid)):
            (fdir, fnm) = os.path.split(str(sid))
            try: sid = to_subject_id(fnm)
            except Exception: sid = None
            pth = fdir
        else:
            sid = to_subject_id(sid)
            fnm = str(sid)
            fdir = find_subject_path(sid)
            if fdir is None: raise ValueError('Could not locate subject with id \'%s\'' % sid)
            pth = os.path.split(fdir)[0]
    else:
        if sid is None:
            (pth, fnm) = os.path.split(subjects_path)
        else:
            sid = to_subject_id(sid)
            fnm = str(sid)
            fdir = subjects_path
    fdir = os.path.abspath(os.path.join(pth, fnm))
    if fdir in subject._cache: return subject._cache[fdir]
    sub = Subject(sid, fdir, meta_data=meta_data, default_alignment=default_alignment).persist()
    if isinstance(sub, Subject): subject._cache[fdir] = sub
    return sub

def no(self, text, count=None):
        if count is None and self.persistent_count is not None:
            count = self.persistent_count

        if count is None:
            count = 0
        mo = re.search(r"\A(\s*)(.+?)(\s*)\Z", text)
        pre = mo.group(1)
        word = mo.group(2)
        post = mo.group(3)

        if str(count).lower() in pl_count_zero:
            return "{}no {}{}".format(pre, self.plural(word, 0), post)
        else:
            return "{}{} {}{}".format(pre, count, self.plural(word, count), post)

def file_type(filename, param='rb'):
    magic_dict = {
        b"\x1f\x8b\x08": "gz",
        b"\x42\x5a\x68": "bz2",
        b"\x50\x4b\x03\x04": "zip"
    }
    if param.startswith('w'):
        return filename.split('.')[-1]
    max_len = max(len(x) for x in magic_dict)
    with open(filename, 'rb') as f:
        file_start = f.read(max_len)
    for magic, filetype in list(magic_dict.items()):
        if file_start.startswith(magic):
            return filetype
    return "no match"

