def service(cls):

    if not cls:
        return None

    # Inject methods
    def get(cls, context):
        return context.get_service(cls)
    cls.get = get.__get__(cls)

    log.debug('Registering [%s] (service)', get_fqdn(cls))

    return cls

def _apply_diff(environ, diff):
    original = {}

    if diff:
        for k, v in diff.iteritems():

            if v is None:
                log.log(5, 'unset %s', k)
            else:
                log.log(5, '%s="%s"', k, v)

            original[k] = environ.get(k)

            if original[k] is None:
                log.log(1, '%s was not set', k)
            else:
                log.log(1, '%s was "%s"', k, original[k])

            if v is None:
                environ.pop(k, None)
            else:
                environ[k] = v
    else:
        log.log(5, 'nothing to apply')

    return original

