        return max(durs)

def date_period(frequency, anniversary, now=None):
    if frequency != DATE_FREQUENCY_MONTHLY:
        raise DateFrequencyError("Only monthly date frequency is supported - not '%s'" % (frequency))

    if anniversary > 28:
        raise MaxAnniversaryDayError("'%s' is greater than maximum allowed anniversary day 28." % anniversary)

    if not now:
        now = date.now()

    if now.day >= anniversary:
        start = date(now.year, now.month, anniversary)
        stop = start + relativedelta(months=+1) + relativedelta(days=-1)
    else:
        stop = date(now.year, now.month, anniversary)
        start = stop + relativedelta(months=-1)
        stop = stop  + relativedelta(days=-1)
    return (start, stop,)

def generate(topic, add_punctuation, character_count=None):
    corpus_cursor = db.markovify.find({'topic': topic})
    if(corpus_cursor):
        corpus = ''
        for text in corpus_cursor:
            corpus = punctuate(corpus, text['text'], add_punctuation)
        text_model = markovify.Text(corpus)
        sentence = text_model.make_short_sentence(character_count) \
            if character_count else text_model.make_sentence()
        if not sentence:
            raise Exception('There is not enough in the corpus to generate a sentence.')
        return sentence
    raise Exception('No text found for topic: ' + topic)

