def asString(self, strict=False):
        if len(self.keys())==0:
            return "origin"
        v = []
        n = []
        try:
            for name, value in self.asTuple():
                s = ''
                if value is None:
                    s = "None"
                elif type(value) == tuple or type(value) == list:
                    s = "(%.3f,%.3f)"%(value[0], value[1])
                elif int(value) == value:
                    s = "%d"%(int(value))
                else:
                    s = "%.3f"%(value)
                if s != '':
                    n.append("%s:%s"%(name, s))
            return ", ".join(n)
        except TypeError:
            import traceback
            print("Location value error:", name, value)
            for key, value in self.items():
                print("\t\tkey:", key)
                print("\t\tvalue:", value)
            traceback.print_exc()
            return "error"

def rows(thelist, n):
    try:
        n = int(n)
        thelist = list(thelist)
    except (ValueError, TypeError):
        return [thelist]
    list_len = len(thelist)
    split = list_len // n

    if list_len % n != 0:
        split += 1
    return [thelist[split * i:split * (i + 1)] for i in range(n)]

def parse_frog(lines):
    sid = 0
    for i, line in enumerate(lines):
        if not line:
            # end of sentence marker
            sid += 1
        else:
            parts = line.split("\t")
            tid, token, lemma, morph, pos, conf, ne, _, parent, rel = parts
            if rel:
                rel = (rel, int(parent) - 1)
            word = u' '.join(token.split(u'_'))
            result = dict(id=i, sentence=sid, word=word, lemma=lemma, pos=pos,
                          pos_confidence=float(conf), rel=rel)
            if ne != 'O':
                # NER label from BIO tags
                result["ne"] = ne.split('_', 1)[0][2:]
            yield result

def dump(self):

        walkers = {}
        walkers.update({str(walker.selector): walker.dump() for walker in self._queue_walkers})
        walkers.update({str(walker.selector): walker.dump() for walker in self._virtual_walkers})

        return {
            u'engine': self._engine.dump(),
            u'rollover_storage': self._rollover_storage,
            u'rollover_streaming': self._rollover_streaming,
            u'last_values': {str(stream): reading.asdict() for stream, reading in self._last_values.items()},
            u'walkers': walkers
        }

