def _zom_arg(lexer):
    tok = next(lexer)
    # ',' EXPR ZOM_X
    if isinstance(tok, COMMA):
        return (_expr(lexer), ) + _zom_arg(lexer)
    # null
    else:
        lexer.unpop_token(tok)
        return tuple()

def fill(image, mask=None, iterations=1):
    global fill_table
    if mask is None:
        masked_image = image
    else:
        masked_image = image.astype(bool).copy()
        masked_image[~mask] = True
    result = table_lookup(masked_image, fill_table, True, iterations)
    if not mask is None:
        result[~mask] = image[~mask]
    return result

