def build_inbound_messages(self, break_on_empty=False, to_tuple=False,
                               auto_decode=True):
        self.check_for_errors()
        while not self.is_closed:
            message = self._build_message(auto_decode=auto_decode)
            if not message:
                self.check_for_errors()
                sleep(IDLE_WAIT)
                if break_on_empty and not self._inbound:
                    break
                continue
            if to_tuple:
                yield message.to_tuple()
                continue
            yield message

def from_default(cls):
        from .core import properties

        # Are we in a container started by skein?
        if properties.application_id is not None:
            if properties.container_dir is not None:
                cert_path = os.path.join(properties.container_dir, '.skein.crt')
                key_path = os.path.join(properties.container_dir, '.skein.pem')
                if os.path.exists(cert_path) and os.path.exists(key_path):
                    return Security(cert_file=cert_path, key_file=key_path)
            raise context.FileNotFoundError(
                "Failed to resolve .skein.{crt,pem} in 'LOCAL_DIRS'")

        # Try to load from config_dir, and fallback to minting new credentials
        try:
            return cls.from_directory(properties.config_dir)
        except FileNotFoundError:
            pass

        new = cls.new_credentials()
        try:
            out = new.to_directory(properties.config_dir)
            context.warn("Skein global security credentials not found, "
                         "writing now to %r." % properties.config_dir)
        except FileExistsError:
            # Race condition between competing processes, use the credentials
            # written by the other process.
            out = cls.from_directory(properties.config_dir)
        return out

def aws_encode(x):
    ret = None
    try:
        x.encode('ascii')
        ret = re.sub(r'\\x([a-f0-8]{2})',
                      _hexReplace, x.encode('unicode_escape'))
    except UnicodeEncodeError:
        ret = x.encode('idna')
    except Exception as e:
        log.error("Couldn't encode %s using either 'unicode_escape' or 'idna' codecs", x)
        raise CommandExecutionError(e)
    log.debug('AWS-encoded result for %s: %s', x, ret)
    return ret

def _container_manipulation_allowed(self):
        # type: (StorageAccount) -> bool
        if self.is_sas:
            # search for account sas "c" resource
            sasparts = self.key.split('&')
            for part in sasparts:
                tmp = part.split('=')
                if tmp[0] == 'srt':
                    return 'c' in tmp[1]
            # this is a sas without the srt parameter, so this must be
            # a service-level sas which doesn't allow container manipulation
            return False
        else:
            # storage account key always allows container manipulation
            return True

