def _update_tokens_from_swap_format(self, original_format, original_format_order, remove_obsolete=True):
        old_format_order = [_.lower() for _ in original_format_order]
        new_format_order = [_.lower() for _ in self.format_order]
        if hasattr(self, 'token_dict') and self.format != original_format:
            old_tokens = [token for token in list(set(old_format_order) - set(new_format_order))
                          if hasattr(self, token)]

            new_tokens = [token for token in set(new_format_order) - set(old_format_order)
                          if not hasattr(self, token) or isinstance(getattr(self, token, ''), str)]

            self.merge_dict(dict.fromkeys(new_tokens, ''))

            if remove_obsolete:
                self.token_dict.purge_tokens(old_tokens)

                for new_token in new_tokens:
                    try:
                        delattr(self, new_token)
                    except AttributeError:
                        pass

def loads_with_timestamp(value, salt):
    try:
        signing.loads(value, salt=salt, max_age=-999999)
    except signing.SignatureExpired as e:
        age = float(str(e).split('Signature age ')[1].split(' >')[0])
        timestamp = timezone.now() - datetime.timedelta(seconds=age)
        return timestamp, signing.loads(value, salt=salt)

def urltool(classqname, filt, reverse):
    filt = re.compile(filt or '.*')

    rootCls = namedAny(classqname)
    rules = list(_iterClass(rootCls))
    arr = []
    for item in sorted(rules):
        if item.subKlein:
            continue

        matched = filt.search(item.rulePath)
        matched = not matched if reverse else matched
        if matched:
            arr.append(tuple(item.toOpenAPIPath()))

    openapi3 = openapi.OpenAPI()
    for pathPath, pathItem in arr:
        if pathPath in openapi3.paths:
            openapi3.paths[pathPath].merge(pathItem)
        else:
            openapi3.paths[pathPath] = pathItem
    print(yaml.dump(openapi3, default_flow_style=False))

def _build_menu(docs):

    paths = []
    current = docs.filename
    while current != docs.root:
        current = current.parent
        paths.append(current)

    for path in reversed(paths):
        docs.add_menu(path.stem.title(), link=path / 'index.html')

    if docs.filename.stem != 'index':
        docs.add_menu(docs.title, link=docs.filename)

    docs.end_menu()

