def build_dict_to_sign(self, request, signature_headers):
        d = {}
        for header in signature_headers:
            if header == '(request-target)':
                continue
            d[header] = request.META.get(self.header_canonical(header))
        return d

def bh_effective_spin(chi,incl):
    if incl == 0:
        chi_eff = chi
    else:
        # ISSO radius for the given BH spin magnitude and inclination
        rISSO = PG_ISSO_solver(chi,incl)
        # Angle at which the branch of positive solutions has its minumum
        incl_flip = scipy.optimize.fmin(pos_branch, math.pi/4, args=tuple([chi]), full_output=False, disp=False)[-1]
        # Use incl_flip to determine the initial guess: the sign difference
        # in the initial_guess ensures that chi_eff has the correct sign
        if incl>incl_flip:
            initial_guess = -1.1
        else:
            initial_guess = 1.0
        chi_eff = scipy.optimize.fsolve(ISCO_eq_chi_first, initial_guess, args=(rISSO))

    return chi_eff

def get_provisioned_gsi_read_units(table_name, gsi_name):
    try:
        desc = DYNAMODB_CONNECTION.describe_table(table_name)
    except JSONResponseError:
        raise

    for gsi in desc[u'Table'][u'GlobalSecondaryIndexes']:
        if gsi[u'IndexName'] == gsi_name:
            read_units = int(
                gsi[u'ProvisionedThroughput'][u'ReadCapacityUnits'])
            break

    logger.debug(
        '{0} - GSI: {1} - Currently provisioned read units: {2:d}'.format(
            table_name, gsi_name, read_units))
    return read_units

