    encoding="utf-8",
    dialect=None,
    sample_size=262144,
    *args,
    **kwargs
):
    source = Source.from_file(
        filename_or_fobj, plugin_name="csv", mode="rb", encoding=encoding
    )

    if dialect is None:
        dialect = discover_dialect(
            sample=read_sample(source.fobj, sample_size), encoding=source.encoding
