def update(self, buf, encoding="utf-8"):

        if isinstance(buf, six.text_type):
            buf = buf.encode(encoding)

        if not isinstance(buf, six.binary_type):
            raise TypeError(
                "Argument must be of string, unicode or bytes type not "
                "'%r'" % type(buf)
            )

        self._data = self._data + buf

def _mount_repo(repo, tmp=False):
    check_call_on_vm('sudo mkdir -p {}'.format(repo.vm_path))
    if tmp:
        for i in range(0,10):
            try:
                _run_mount_command(repo)
                return
            except CalledProcessError as e:
                if 'Connection refused' in e.output:
                    logging.info('Failed to mount repo; waiting for nfsd to restart')
                    time.sleep(1)
                else:
                    logging.info(e.output)
                    raise e
        log_to_client('Failed to mount repo {}'.format(repo.short_name))
        raise RuntimeError('Unable to mount repo with NFS')
    else:
        _run_mount_command(repo)

def running(name, **kwargs):
    if '*' in name or '?' in name:

        return _vagrant_call(name, 'start', 'restarted',
                             "Machine has been restarted", "running")

    else:

        ret = {'name': name,
               'changes': {},
               'result': True,
               'comment': '{0} is already running'.format(name)
               }

        try:
            info = __salt__['vagrant.vm_state'](name)
            if info[0]['state'] != 'running':
                __salt__['vagrant.start'](name)
                ret['changes'][name] = 'Machine started'
                ret['comment'] = 'Node {0} started'.format(name)
        except (SaltInvocationError, CommandExecutionError):
            #  there was no viable existing machine to start
            ret, kwargs = _find_init_change(name, ret, **kwargs)
            kwargs['start'] = True
            __salt__['vagrant.init'](name, **kwargs)
            ret['changes'][name] = 'Node defined and started'
            ret['comment'] = 'Node {0} defined and started'.format(name)

        return ret

def _find_penultimate_layer(model, layer_idx, penultimate_layer_idx):
    if penultimate_layer_idx is None:
        for idx, layer in utils.reverse_enumerate(model.layers[:layer_idx - 1]):
            if isinstance(layer, Wrapper):
                layer = layer.layer
            if isinstance(layer, (_Conv, _Pooling1D, _Pooling2D, _Pooling3D)):
                penultimate_layer_idx = idx
                break

    if penultimate_layer_idx is None:
        raise ValueError('Unable to determine penultimate `Conv` or `Pooling` '
                         'layer for layer_idx: {}'.format(layer_idx))

    # Handle negative indexing otherwise the next check can fail.
    if layer_idx < 0:
        layer_idx = len(model.layers) + layer_idx
    if penultimate_layer_idx > layer_idx:
        raise ValueError('`penultimate_layer_idx` needs to be before `layer_idx`')

    return model.layers[penultimate_layer_idx]

def element(self, inp=None):
        if inp is not None:
            # Workaround for missing __complex__ of numpy.ndarray
            # for Numpy version < 1.12
            # TODO: remove when Numpy >= 1.12 is required
            if isinstance(inp, np.ndarray):
                return complex(inp.reshape([1])[0])
            else:
                return complex(inp)
        else:
            return complex(0.0, 0.0)

def vector_to_arr(vec, dim):
    if len(dim) <= 1:
        return vec
    array = vec
    while len(dim) > 1:
        i = 0
        outer_array = []
        for m in range(reduce(mul, dim[0:-1])):
            inner_array = []
            for n in range(dim[-1]):
                inner_array.append(array[i])
                i += 1
            outer_array.append(inner_array)
        array = outer_array
        dim = dim[0:-1]

        return array

