                    'lower_extent': s,
                    'upper_extent': e
                } for (d, (s, e)) in args)

        # Return a tuple-dict-creating generator
        return (_create_dim_dicts(*zip(dims, s)) for s
            in self.endpoint_iter(*dim_strides, **kwargs))

