def _get_shortcut_string(shortcut):
    if shortcut is None:
        return ''
    if isinstance(shortcut, (tuple, list)):
        return ', '.join([_get_shortcut_string(s) for s in shortcut])
    if isinstance(shortcut, string_types):
        if hasattr(QKeySequence, shortcut):
            shortcut = QKeySequence(getattr(QKeySequence, shortcut))
        else:
            return shortcut.lower()
    assert isinstance(shortcut, QKeySequence)
    s = shortcut.toString() or ''
    return str(s).lower()

def _force_revoke_leadership(self, broker):
        owned_partitions = list(filter(
            lambda p: broker is p.leader,
            broker.partitions,
        ))
        for partition in owned_partitions:
            if len(partition.replicas) == 1:
                self.log.error(
                    "Cannot be revoked leadership for broker {b} for partition {p}. Replica count: 1"
                    .format(p=partition, b=broker),
                )
                continue
            eligible_followers = [
                follower for follower in partition.followers
                if not follower.revoked_leadership
            ]
            if eligible_followers:
                # Pick follower with least leader-count
                best_fit_follower = min(
                    eligible_followers,
                    key=lambda follower: follower.count_preferred_replica(),
                )
                partition.swap_leader(best_fit_follower)
            else:
                self.log.error(
                    "All replicas for partition {p} on broker {b} are to be revoked for leadership.".format(
                        p=partition,
                        b=broker,
                    )
                )

def parse_permission_set(input):

    # Priority goes to the user's parsers.
    if isinstance(input, basestring):
        for func in current_acl_manager.permission_set_parsers:
