def _assign_to_field(obj, name, val):
    target = getattr(obj, name)

    if isinstance(target, containers.RepeatedScalarFieldContainer):
        target.append(val)
    elif isinstance(target, containers.RepeatedCompositeFieldContainer):
        target = target.add()
        target.CopyFrom(val)
    elif isinstance(target, (int, float, bool, str, bytes)):
        setattr(obj, name, val)
    elif isinstance(target, message.Message):
        target.CopyFrom(val)
    else:
        raise RuntimeError("Unsupported type: {}".format(type(target)))

def is_date_in_between(self, start, end, include_start=True,
                           include_end=True):

        start = Day(start).get_just_date()
        now = self.get_just_date()
        end = Day(end).get_just_date()

        if start < now < end:
            return True

        if include_start and now == start:
            return True

        if include_end and now == end:
            return True

        return False

def add_seconds(self, datetimestr, n):
        a_datetime = self.parse_datetime(datetimestr)
        return a_datetime + timedelta(seconds=n)

def fill_in_table(self, table, worksheet, flags):
        max_row = 0
        min_row = sys.maxint
        for row in table:
            if len(row) > max_row:
                max_row = len(row)
            if len(row) < min_row:
                min_row = len(row)
        if max_row != min_row:
            for row in table:
                if len(row) < max_row:
                    row.extend([None]*(max_row-len(row)))

def is_transactional(self, state):

        controller = getattr(state, 'controller', None)
        if controller:
            force_transactional = _cfg(controller).get('transactional', False)
        else:
            force_transactional = False

        if state.request.method not in ('GET', 'HEAD') or force_transactional:
            return True
        return False

def _did_create_child(self, connection):

