def index_item(self, item):
        name_property = getattr(self.__class__, "name_property", None)
        if name_property is None:
            return None
        name = getattr(item, name_property, None)
        if name is None:
            item.add_error("a %s item has been defined without %s, from: %s"
                           % (self.inner_class.my_type, name_property,
                              getattr(item, 'imported_from', 'Unknown importation source!')))
        elif name in self.name_to_item:
            item = self.manage_conflict(item, name)
        self.name_to_item[name] = item
        return item

def total_weight(self):
        weights = self._raw_weights()
        if weights.shape[1] == 0:
            # Short-circuit evaluation to handle empty weight arrays gracefully.
            return 0.0
        elif weights.shape[1] < self._ntaps:
            return np.sum(np.mean(weights, axis=1))
        else:
            return self._filter_coeffs.dot(np.sum(weights, axis=0))

def url_parse(name):
    position = name.find("github.com")
    if position >= 0:
        if position != 0:
            position_1 = name.find("www.github.com")
            position_2 = name.find("http://github.com")
            position_3 = name.find("https://github.com")
            if position_1*position_2*position_3 != 0:
                exception()
                sys.exit(0)
        name = name[position+11:]
        if name.endswith('/'):
            name = name[:-1]
        return name
    else:
        if name.endswith('/'):
            name = name[:-1]
        return name

