def _genTimeoutList(self, const):
        result = {}

        for v in range(128):
            x = v & 0x0F
            y = (v >> 4) & 0x07

            if not y or (y and x > 7):
                result[const * x * 2**y] = v

        self._log and self._log.debug("Timeout list: %s", result)
        return result

