def replace(old_value, new_value, full_match=False):
    if full_match is False:
        matcher = re.compile('^.*{0}.*$'.format(re.escape(old_value)), re.MULTILINE)
        repl = re.compile(re.escape(old_value))
    else:
        matcher = re.compile(old_value, re.MULTILINE)
        repl = re.compile(old_value)

    lines = {'old': [], 'new': []}
    for line in matcher.finditer(show_run()):
        lines['old'].append(line.group(0))
        lines['new'].append(repl.sub(new_value, line.group(0)))

    delete_config(lines['old'])
    add_config(lines['new'])

    return lines

def pformat(self, consumed_capacity=None):
        consumed_capacity = consumed_capacity or {}
        lines = []
        parts = ["GLOBAL", self.index_type, "INDEX", self.name]
        if self.status != "ACTIVE":
            parts.insert(0, "[%s]" % self.status)
        lines.append(" ".join(parts))
        lines.append("  items: {0:,} ({1:,} bytes)".format(self.item_count, self.size))
        read = "Read: " + format_throughput(
            self.read_throughput, consumed_capacity.get("read")
        )
        write = "Write: " + format_throughput(
            self.write_throughput, consumed_capacity.get("write")
        )
        lines.append("  " + read + "  " + write)
        lines.append("  " + self.hash_key.schema)
        if self.range_key is not None:
            lines.append("  " + self.range_key.schema)

        if self.includes is not None:
            keys = "[%s]" % ", ".join(("'%s'" % i for i in self.includes))
            lines.append("  Projection: %s" % keys)
        return "\n".join(lines)

def pretty_str(self, indent=0):
        indent = ' ' * indent
        values = '{{{}}}'.format(', '.join(map(pretty_str, self.value)))

        if self.parenthesis:
            return '{}({})'.format(indent, values)
        return '{}{}'.format(indent, values)

def prefix(self, prefix, lowercase=True):
        env_subset = {}
        for key in self._envars.keys():
            if key.startswith(prefix):
                new_key = key[len(prefix):]  # cut front
                new_key = new_key.lower() if lowercase else new_key
                env_subset[new_key] = str(self._envars[key]) # str strips Entry

        return Environment(environ=env_subset,
                           sensitive=self._sensitive,
                           blankify=self._blankify,
                           noneify=self._noneify,
                           writable=self._writable,
                          )

