def yaml_to_dict(yaml_str=None, str_or_buffer=None, ordered=False):
    if not yaml_str and not str_or_buffer:
        raise ValueError('One of yaml_str or str_or_buffer is required.')

    # determine which load method to use
    if ordered:
        loader = __ordered_load
    else:
        loader = yaml.load

    if yaml_str:
        d = loader(yaml_str)
    elif isinstance(str_or_buffer, str):
        with open(str_or_buffer) as f:
            d = loader(f)
    else:
        d = loader(str_or_buffer)

    return d

def relativestring(
            self, now=None, minimum=10, maximum=3600 * 24 * 30,
            pattern="%Y-%m-%d", timezone=None, maxunits=1):

        if now is None:
            now = time.time()
        if timezone is None:
            timezone = self.timezone

        diff = now - (self.__timestamp__ - timezone)
        future = diff < 0
        diff = abs(diff)

        if diff < minimum:
            return "just now"
        if diff > maximum and maximum > 0:
            return self.timestring(pattern)

        timestring = ChronykDelta(diff).timestring(maxunits=maxunits)
        if timestring == "1 day":
            return "tomorrow" if future else "yesterday"

        if future:
            return "in {}".format(timestring)
        else:
            return "{} ago".format(timestring)

