def decode(self, bytes):
        value = self.type.decode(bytes)
        if self._enum is not None:
            for name, val in self._enum.items():
                if value == val:
                    value = name
                    break
        return value

def valueAt(self, percent):
        min_val = self.minimum()
        max_val = self.maximum()

        if percent < 0:
            return min_val
        elif 1 < percent:
            return max_val

        # round the max value to sync with the values in the grid
        total_seconds = (max_val - min_val).total_seconds()
        perc_seconds = max(min(percent, 1.0), 0.0) * total_seconds

        return max_val + datetime.timedelta(0, perc_seconds)

def traverse_dependencies_up(docgraph, node_id, node_attr=None):
    # there's only one, but we're in a multidigraph
    source, target = docgraph.in_edges(node_id)[0]
    traverse_attr = node_attr if node_attr else docgraph.lemma_attr

    attrib_value = docgraph.node[source].get(traverse_attr)
    if attrib_value:
        yield attrib_value

    if istoken(docgraph, source) is True:
        for attrib_value in traverse_dependencies_up(docgraph, source,
                                                     traverse_attr):
            # This yields the value from the recursive call to propagate ancestor dependencies upward.
            yield attrib_value

