def uridefrag(uristring):
    if isinstance(uristring, bytes):
        parts = uristring.partition(b'#')
    else:
        # Split the string on a fragment separator to isolate its base and fragment parts.
        parts = uristring.partition(u'#')
    return DefragResult(parts[0], parts[2] if parts[1] else None)

def modify(device, label=None, lazy_counting=None, uuid=None):
    if not label and lazy_counting is None and uuid is None:
        raise CommandExecutionError("Nothing specified for modification for \"{0}\" device".format(device))

    cmd = ['xfs_admin']
    if label:
        cmd.append("-L")
        cmd.append("'{0}'".format(label))

    if lazy_counting is False:
        cmd.append("-c")
        cmd.append("0")
    elif lazy_counting:
        cmd.append("-c")
        cmd.append("1")

    if uuid is False:
        cmd.append("-U")
        cmd.append("nil")
    elif uuid:
        cmd.append("-U")
        cmd.append("generate")
    cmd.append(device)

    cmd = ' '.join(cmd)
    _verify_run(__salt__['cmd.run_all'](cmd), cmd=cmd)

    out = __salt__['cmd.run_all']("blkid -o export {0}".format(device))
    _verify_run(out)

    return _blkid_output(out['stdout'])

def write_message(self, msg, timeout=None):
    replace_dict = {'command': self.CMD_TO_WIRE[msg.command]}
    if msg.has_data:
      # Swap out data for the data length for the wire.
      data = msg[-1]
      replace_dict[msg._fields[-1]] = len(data)

    self.stream.write(struct.pack(msg.struct_format,
                                  *msg._replace(**replace_dict)), timeout)
    if msg.has_data:
      self.stream.write(data, timeout)

def show_modules(config, modules_list):
    details = config["full"]
    core_mods = not config["user"]
    user_mods = not config["core"]

    modules = core_module_docstrings(
        include_core=core_mods, include_user=user_mods, config=config
    )

    new_modules = []
    if modules_list:
        from fnmatch import fnmatch

        for _filter in modules_list:
            for name in modules.keys():
                if fnmatch(name, _filter):
                    if name not in new_modules:
                        new_modules.append(name)
    else:
        new_modules = modules.keys()

    for name in sorted(new_modules):
        module = _to_docstring(modules[name])
        desc = module[0][:-1]
        if details:
            dash_len = len(name) + 4
            print("#" * dash_len)
            print("# {} #".format(name))
            print("#" * dash_len)
            for description in module:
                print(description[:-1])
        else:
            print("%-22s %s" % (name, desc))

def _position_for_aspirate(self, location=None, clearance=1.0):

        placeable = None
        if location:
            placeable, _ = unpack_location(location)
            # go to top of source, if not already there
            if placeable != self.previous_placeable:
                self.move_to(placeable.top())
        else:
            placeable = self.previous_placeable

        # if pipette is currently empty, ensure the plunger is at "bottom"
        if self.current_volume == 0:
            pos, _, _ = pose_tracker.absolute(
                self.robot.poses, self.instrument_actuator)
            if pos != self._get_plunger_position('bottom'):
                # move to top of well to avoid touching liquid
                if placeable:
                    self.move_to(placeable.top())
                self.instrument_actuator.set_active_current(
                    self._plunger_current)
                self.robot.poses = self.instrument_actuator.move(
                    self.robot.poses,
                    x=self._get_plunger_position('bottom')
                )

        # then go inside the location
        if location:
            if isinstance(location, Placeable):
                location = location.bottom(min(location.z_size(), clearance))
            self.move_to(location, strategy='direct')

