def truncate_sentence(text, max_chars, break_words=False, padding=0):
    if break_words:
        return text[:-abs(max_chars - len(text)) - padding]

    words = []
    for word in text.split():
        predicted_len = (
            sum(map(len, words)) +  # length of words
            len(word) +  # length of next word
            len(words) - 1 +  # length of spaces
            padding)
        if predicted_len >= max_chars:
            break
        words.append(word)
    return ' '.join(words)

def addSpatialNoise(self, sequence, amount):
    newSequence = []

    for pattern in sequence:
      if pattern is not None:
        pattern = self.patternMachine.addNoise(pattern, amount)
      newSequence.append(pattern)

    return newSequence

def to_pint(self, unit_registry=None):
        if unit_registry is None:
            unit_registry = _pint.UnitRegistry()
        powers_dict = self.units.expr.as_powers_dict()
        units = []
        for unit, pow in powers_dict.items():
            # we have to do this because Pint doesn't recognize
            # "yr" as "year"
            if str(unit).endswith("yr") and len(str(unit)) in [2, 3]:
                unit = str(unit).replace("yr", "year")
            units.append("%s**(%s)" % (unit, Rational(pow)))
        units = "*".join(units)
        return unit_registry.Quantity(self.value, units)

