def supports_version_type(self, version_type=None):
        # Implemented from template for osid.Metadata.supports_coordinate_type
        from .osid_errors import IllegalState, NullArgument
        if not version_type:
            raise NullArgument('no input Type provided')
        if self._kwargs['syntax'] not in ['``VERSION``']:
            raise IllegalState('put more meaninful message here')
        return version_type in self.get_version_types

def getAtomic(rates, ver, lamb, br, reactfn):
    with h5py.File(reactfn, 'r') as f:
        lambnew = f['/atomic/lambda'].value.ravel(order='F')  # some are not 1-D!

    vnew = np.concatenate((rates.loc[..., 'po3p3p'].values[..., None],
                           rates.loc[..., 'po3p5p'].values[..., None]), axis=-1)

    return catvl(rates.alt_km, ver, vnew, lamb, lambnew, br)

def find_sink_variables(self):
        # First we assume all variables are sinks
        is_sink = {name: True for name in self.variables.keys()}
        # Then, we remove those variables which are inputs of some operators
        for operator in self.operators.values():
            for variable in operator.inputs:
                is_sink[variable.onnx_name] = False
        return [variable for name, variable in self.variables.items() if is_sink[name]]

def advance2(self, height, ignore_overflow=False):
        if height <= self.remaining_height:
            self._self_cursor.grow(height)
        elif ignore_overflow:
            self._self_cursor.grow(float(self.remaining_height))
        else:
            return False
        return True

def merge_dict(dict_1, *other, **kw):
    tmp = dict_1.copy()
    for x in other:
        tmp.update(x)
    tmp.update(kw)
    return tmp

