def crude_age_standardization(e, b, n):
    r = e * 1.0 / b
    b_by_n = sum_by_n(b, 1.0, n)
    age_weight = b * 1.0 / b_by_n.repeat(len(e) // n)
    return sum_by_n(r, age_weight, n)

def compute_fw_at_frac_max_1d_simple(Y, xc, X=None, f=0.5):

    yy = np.asarray(Y)

    if yy.ndim != 1:
        raise ValueError('array must be 1-d')

    if yy.size == 0:
        raise ValueError('array is empty')

    if X is None:
        xx = np.arange(yy.shape[0])
    else:
        xx = X

    xpix = coor_to_pix_1d(xc - xx[0])

    try:
        peak = yy[xpix]
    except IndexError:
        raise ValueError('peak is out of array')

    fwhm_x, _codex, _msgx = compute_fwhm_1d(xx, yy - f * peak, xc, xpix)
    return peak, fwhm_x

def stop(self):
        stopped = []
        for host, _ in self.host_cores:
            if self.status(host)[0][1] == 'not-running':
                print('%s not running' % host)
                continue
            ctrl_url = 'tcp://%s:%s' % (host, self.ctrl_port)
            with z.Socket(ctrl_url, z.zmq.REQ, 'connect') as sock:
                sock.send('stop')
                stopped.append(host)
        if hasattr(self, 'streamer'):
            self.streamer.terminate()
        return 'stopped %s' % stopped

def purge(self):

        purge_url = urljoin('https://%s' % self.host, '/ccu/v3/%s/url/%s' % (self.action, self.network))

        while self.urls:
            # We'll accumulate
            batch = []
            batch_size = 0

            while self.urls and batch_size < self.MAX_REQUEST_SIZE:
                next_url = self.urls.pop()

                if not isinstance(next_url, bytes):
                    next_url = next_url.encode('utf-8')

                batch.append(next_url)
                batch_size += len(next_url)

            if batch:
                data = {'objects': batch}

                logger.debug('Requesting Akamai purge %d URLs', len(batch))

                response = requests.post(url=purge_url, auth=self.auth, data=json.dumps(data),
                                         headers={'Content-Type': 'application/json'})

                if not response.ok:
                    # We'll return the current batch to the queue so they can be retried later:
                    self.urls.extend(batch)

                    # Raise an exception for errors other than rate-limiting:
                    if response.status_code != 507:
                        response.raise_for_status()

                yield batch, response

def expr_str(expr, sc_expr_str_fn=standard_sc_expr_str):
    if expr.__class__ is not tuple:
        return sc_expr_str_fn(expr)

    if expr[0] is AND:
        return "{} && {}".format(_parenthesize(expr[1], OR, sc_expr_str_fn),
                                 _parenthesize(expr[2], OR, sc_expr_str_fn))

    if expr[0] is OR:
        # This turns A && B || C && D into "(A && B) || (C && D)", which is
        # redundant, but more readable
        return "{} || {}".format(_parenthesize(expr[1], AND, sc_expr_str_fn),
                                 _parenthesize(expr[2], AND, sc_expr_str_fn))

    if expr[0] is NOT:
        if expr[1].__class__ is tuple:
            return "!({})".format(expr_str(expr[1], sc_expr_str_fn))
        return "!" + sc_expr_str_fn(expr[1])  # Symbol

    # Relation
    #
    # Relation operands are always symbols (quoted strings are constant
    # symbols)
    return "{} {} {}".format(sc_expr_str_fn(expr[1]), _REL_TO_STR[expr[0]],
                             sc_expr_str_fn(expr[2]))

