            if mimetype is None:
                logger.warning(f'Could not guess MIME type for {src}')
                mimetype = 'application/octet-stream'

            logger.debug(f'Deduced MIME type: {mimetype}')
            self._bucket.upload_file(src, key, ExtraArgs={
                    'ContentType': mimetype
                })

