def query(sql, format='df'):
    url = 'http://api.treasury.io/cc7znvq/47d80ae900e04f2/sql/'
    query_string = urlencode({'q':sql})
    handle = urlopen(url + '?' + query_string)
    if handle.code == 200:
        d = load(handle)
        if format == 'df':
            return DataFrame(d)
        elif format == 'dict':
            return d
        else:
            raise ValueError('format must equal "df" or "dict"')
    else:
        raise ValueError(handle.read())

def add_mountains(self):
        from noise import pnoise2
        import random
        random.seed()
        octaves = (random.random() * 0.5) + 0.5
        freq = 17.0 * octaves  # 
        for y in range(self.grd.grid_height - 1):
            for x in range(self.grd.grid_width - 1):
                pixel = self.grd.get_tile(y,x)
                if pixel == 'X':     # denoise blocks of mountains
                    n = int(pnoise2(x/freq, y / freq, 1)*11+5)
                    if n < 1:
                        self.grd.set_tile(y, x, '#')

