            'class':'django.utils.log.AdminEmailHandler',
        }
    })
    d['loggers'].update({
        'django.db.backends': { # stop SQL debug from going to main logger
            'handlers': ['file', 'mail_admins'],
            'level': 'ERROR',
            'propagate': False,
        },
        'django.request': {
