def _get_os_price_id(items, os, location):

    for item in items:
        if any([utils.lookup(item,
                             'itemCategory',
                             'categoryCode') != 'os',
                utils.lookup(item,
                             'softwareDescription',
                             'referenceCode') != os]):
            continue

        for price in item['prices']:
            if not _matches_location(price, location):
                continue

            return price['id']

    raise SoftLayer.SoftLayerError("Could not find valid price for os: '%s'" %
                                   os)

def loadRootJob(self):
        try:
            with self.readSharedFileStream(self.rootJobStoreIDFileName) as f:
                rootJobStoreID = f.read().decode('utf-8')
        except NoSuchFileException:
            raise JobException('No job has been set as the root in this job store')
        if not self.exists(rootJobStoreID):
            raise JobException("The root job '%s' doesn't exist. Either the Toil workflow "
                               "is finished or has never been started" % rootJobStoreID)
        return self.load(rootJobStoreID)

def log(stats_resource=None, stats_source=None, log_level=DEFAULT_LOG_LEVEL,
        **kwargs):

    # Get stats from source if given.
    if stats_source is not None:
        kwargs = stats_source()

    if stats_resource is None:
        if RESOURCE_ID not in kwargs or RESOURCE_NAME not in kwargs:
            raise ValueError('Missing required stats labels.')
    else:
        if not (hasattr(stats_resource, ConfWithId.ID) and
                hasattr(stats_resource, ConfWithId.NAME)):
            raise ValueError('Given stats source is missing id or name'
                             ' attributes.')
        kwargs[RESOURCE_ID] = stats_resource.id
        kwargs[RESOURCE_NAME] = stats_resource.name

    if TIMESTAMP not in kwargs:
        kwargs[TIMESTAMP] = datetime.datetime.utcfromtimestamp(
            time.time()).strftime("%Y-%m-%dT%H:%M:%S.%fZ")

    _STATS_LOGGER.log(log_level,
                      json.dumps(kwargs))

