def get_project(conn, vm_):
    try:
        projects = conn.ex_list_projects()
    except AttributeError:
        # with versions <0.15 of libcloud this is causing an AttributeError.
        log.warning('Cannot get projects, you may need to update libcloud to 0.15 or later')
        return False
    projid = config.get_cloud_config_value('projectid', vm_, __opts__)

    if not projid:
        return False

    for project in projects:
        if six.text_type(projid) in (six.text_type(project.id), six.text_type(project.name)):
            return project

    log.warning("Couldn't find project %s in projects", projid)
    return False

def parse_entities(self, as_html=True):

        text = self.text or self.caption
        if text is None:
            raise TypeError("This message doesn't have any text.")

        quote_fn = md.quote_html if as_html else md.escape_md

        entities = self.entities or self.caption_entities
        if not entities:
            return quote_fn(text)

        if not sys.maxunicode == 0xffff:
            text = text.encode('utf-16-le')

        result = ''
        offset = 0

        for entity in sorted(entities, key=lambda item: item.offset):
            entity_text = entity.parse(text, as_html=as_html)

            if sys.maxunicode == 0xffff:
                part = text[offset:entity.offset]
                result += quote_fn(part) + entity_text
            else:
                part = text[offset * 2:entity.offset * 2]
                result += quote_fn(part.decode('utf-16-le')) + entity_text

            offset = entity.offset + entity.length

        if sys.maxunicode == 0xffff:
            part = text[offset:]
            result += quote_fn(part)
        else:
            part = text[offset * 2:]
            result += quote_fn(part.decode('utf-16-le'))

        return result

