                else:
                    params[key] = value
        else:
            params['page'] = self.page
        href = Href(url or request.base_url)
        return href(params)

def pad_ranges(inranges,padding,chr_ranges=None):
  if not inranges: return
  outranges = []
  if len(inranges) == 0: return outranges
  chr = {}
  if chr_ranges:
    for b in chr_ranges:
      chr[b.chr] = b
  for rng in inranges:
    tmp = rng.start - padding
    newend = rng.end + padding
    if rng.chr in chr:
      if tmp < chr[rng.chr].start: tmp = chr[rng.chr].start
      if newend > chr[rng.chr].end: endstart = chr[rng.chr].end
    nrng = rng.copy()
    nrng.start = tmp
    nrng.end = newend
    outranges.append(nrng)
  return sort_ranges(outranges)

