def gauss(x,m_y,sigma):

    e_y = [np.exp((1.0/(2*float(sigma)**2)*-(n-m_y)**2)) for n in np.array(x)]
    y = [1.0/(float(sigma) * np.sqrt(2 * np.pi)) * e for e in e_y]

    return np.array(y)

