def load_uri(self, uri):

        # if self.verbose: printDebug("----------")
        if self.verbose: printDebug("Reading: <%s>" % uri, fg="green")
        success = False

        sorted_fmt_opts = try_sort_fmt_opts(self.rdf_format_opts, uri)

        for f in sorted_fmt_opts:
            if self.verbose:
                printDebug(".. trying rdf serialization: <%s>" % f)
            try:
                if f == 'json-ld':
                    if self.verbose:
                        printDebug(
                            "Detected JSONLD - loading data into rdflib.ConjunctiveGraph()",
                            fg='green')
                    temp_graph = rdflib.ConjunctiveGraph()
                else:
                    temp_graph = rdflib.Graph()
                temp_graph.parse(uri, format=f)
                if self.verbose: printDebug("..... success!", bold=True)
                success = True
                self.sources_valid += [uri]
                # ok, so merge
                self.rdflib_graph = self.rdflib_graph + temp_graph
                break
            except:
                temp = None
                if self.verbose: printDebug("..... failed")
                # self._debugGraph()

        if not success == True:
            self.loading_failed(sorted_fmt_opts, uri=uri)
            self.sources_invalid += [uri]

def wrap(string, length, indent):
    newline = "\n" + " " * indent
    return newline.join((string[i : i + length] for i in range(0, len(string), length)))

def sap_confirmation(self, apdu):
        if _debug: StateMachineAccessPoint._debug("sap_confirmation %r", apdu)

        if isinstance(apdu, SimpleAckPDU) \
                or isinstance(apdu, ComplexAckPDU) \
                or isinstance(apdu, ErrorPDU) \
                or isinstance(apdu, RejectPDU) \
                or isinstance(apdu, AbortPDU):
            # find the appropriate server transaction
            for tr in self.serverTransactions:
                if (apdu.apduInvokeID == tr.invokeID) and (apdu.pduDestination == tr.pdu_address):
                    break
            else:
                return

            # pass control to the transaction
            tr.confirmation(apdu)

        else:
            raise RuntimeError("invalid APDU (10)")

def _parse_expr(self, part):
        self._logger.debug("parsing expression: " + unicode(part))
        key, op, val = part

        success = True
        dictsql = {
                'operator': op,
                'val1': key,
                'val2': unicode(val),
                'interpretation': {
                    'string': key + op + val,
                    'interpretation': 'expression',
                    'attribute': key,
                    'operator': op,
                    'error': False
                }
            }

        if key in self.attributes:
            if type(self.attributes[key]) is list:
                if val not in self.attributes[key]:
                    dictsql['interpretation']['error'] = True
                    dictsql['interpretation']['error_message'] = 'invalid value'
                    success = False

        else:
            dictsql['interpretation']['error'] = True
            dictsql['interpretation']['error_message'] = 'unknown attribute'
            success = False

        return success, dictsql

def parse_yaml(self, y):
        self.name = y['name']
        if RTS_EXT_NS_YAML + 'comment' in y:
            self.comment = y[RTS_EXT_NS_YAML + 'comment']
        if RTS_EXT_NS_YAML + 'visible' in y:
            visible = y.get(RTS_EXT_NS_YAML + 'visible')
            if visible == True or visible == 'true' or visible == 'True':
                self.visible = True
            else:
                self.visible = False
        if RTS_EXT_NS_YAML + 'properties' in y:
            for p in y.get(RTS_EXT_NS_YAML + 'properties'):
                if 'value' in p:
                    value = p['value']
                else:
                    value = None
                self._properties[p['name']] = value
        return self

def convert(self, request, response, data):

        # Chop up the URL
        uri = urlparse.urlparse(request.url)

        # If there's a password, recompute the URI without it
        if uri.password:
            netloc = "%s:%s@" % (uri.username or "", "XXXXXXXX")
            if uri.hostname:
                netloc += uri.hostname
            if uri.port is not None:
                netloc += ":%d" % uri.port

            uri = urlparse.ParseResult(uri[0], netloc, uri[2], uri[3],
                                       uri[4], uri[5])

        return self.escape("%s %s %s" % (request.method, uri.geturl(),
                                         request.environ['SERVER_PROTOCOL']))

def initialize(*args, **kwargs):
    if len(args) > 1:
