    return wrapped

def attrfindrows(self, groupname, attrname, value):
        values = self.attrgetcol(groupname, attrname)
        return [i for i in range(len(values)) if values[i] == value]

def set(self, name, value, ex=None, px=None, nx=False, xx=False):
        pieces = [name, value]
        if ex:
            pieces.append('EX')
            if isinstance(ex, datetime.timedelta):
                ex = ex.seconds + ex.days * 24 * 3600
            pieces.append(ex)
        if px:
            pieces.append('PX')
            if isinstance(px, datetime.timedelta):
                ms = int(px.microseconds / 1000)
                px = (px.seconds + px.days * 24 * 3600) * 1000 + ms
            pieces.append(px)

        if nx:
            pieces.append('NX')
        if xx:
            pieces.append('XX')
        return self.execute('set', *pieces)

def __default_custom_function(self, *args, **kwargs):
        index_list = self.__get_matching_withargs_indices(*args, **kwargs)
        # if there are 'withArgs' conditions that might be applicable
        if index_list:
            return self.__get_return_value_withargs(index_list, *args, **kwargs)
        # else no 'withArgs' conditions are applicable
        else:
            return self.__get_return_value_no_withargs(*args, **kwargs)

def count(self, predicate=None):

        if self.closed():
            raise ValueError("Attempt to call element_at() on a "
                             "closed Queryable.")

        return self._count() if predicate is None else self._count_predicate(predicate)

def split_multimol2(mol2_path):
    if mol2_path.endswith('.gz'):
        open_file = gzip.open
        read_mode = 'rb'
    else:
        open_file = open
        read_mode = 'r'
    check = {'rb': b'@<TRIPOS>MOLECULE', 'r': '@<TRIPOS>MOLECULE'}

    with open_file(mol2_path, read_mode) as f:
        mol2 = ['', []]
        while True:
            try:
                line = next(f)
                if line.startswith(check[read_mode]):
                    if mol2[0]:
                        yield(mol2)
                    mol2 = ['', []]
                    mol2_id = next(f)
                    mol2[0] = mol2_id.rstrip()
                    mol2[1].append(line)
                    mol2[1].append(mol2_id)
                else:
                    mol2[1].append(line)
            except StopIteration:
                yield(mol2)
                return

def set_process(self, process = None):
        if process is None:
            self.__process = None
        else:
            global Process      # delayed import
            if Process is None:
                from winappdbg.process import Process
            if not isinstance(process, Process):
                msg  = "Parent process must be a Process instance, "
                msg += "got %s instead" % type(process)
                raise TypeError(msg)
            self.__process = process

