def normalize(self, dt, allow_cast=True):
        if dt <= 0:
            raise ValueError("Expected positive input")
        logger.info('Running %(name)s.normalize(dt=%(dt)s)', {"name": self.__class__, "dt": dt})
        try:
            ave = np.average(self.y[np.fabs(self.x) <= dt])
        except RuntimeWarning as e:
            logger.error('in normalize(). self class is %(name)s, dt=%(dt)s', {"name": self.__class__, "dt": dt})
            raise Exception("Scaling factor error: {0}".format(e))
        try:
            self.y /= ave
        except TypeError as e:
            logger.warning("Division in place is impossible: %s", e)
            if allow_cast:
                self.y = self.y / ave
            else:
                logger.error("Division in place impossible - allow_cast flag set to True should help")
                raise

def auto_dict(ival=None, miss=None):
    if ival is None: d = AutoDict()
    else: d = AutoDict(ival)
    if miss == {} or miss is None: return d
    elif miss == []: d.on_miss = lambda:[]
    elif miss == set([]): d.on_miss = lambda:set([])
    else: d.on_miss = miss
    return d

def choosePinentry():
    pinentries = []
    if 'PINENTRY' in os.environ:
        pinentries.append(Pinentry(os.environ['PINENTRY']))
    else:
        mgrd = yield call('launchctl', 'managername')
        if mgrd == 'Aqua':
            pinentries.extend([
                Pinentry(
                    '/usr/local/MacGPG2/libexec/pinentry-mac.app'
                    '/Contents/MacOS/pinentry-mac'),
                Pinentry('pinentry-mac'),
            ])
        if 'DISPLAY' in os.environ:
            pinentries.extend([
                Pinentry('pinentry-gnome3'),
                Pinentry('pinentry-x11')
            ])
        pinentries.extend([
            Pinentry('pinentry-curses'),
            Pinentry('pinentry'),
        ])

    for pinentry in pinentries:
        try:
            pinentry.argv()
        except (PinentryNotFound, OSError):
            continue
        else:
            return pinentry
    else:
        return GetPassAsker()

