def bind_sqlalchemy(provider, session, user=None, client=None,
                    token=None, grant=None, current_user=None):
    if user:
        user_binding = UserBinding(user, session)
        provider.usergetter(user_binding.get)

    if client:
        client_binding = ClientBinding(client, session)
        provider.clientgetter(client_binding.get)

    if token:
        token_binding = TokenBinding(token, session, current_user)
        provider.tokengetter(token_binding.get)
        provider.tokensetter(token_binding.set)

    if grant:
        if not current_user:
            raise ValueError(('`current_user` is required'
                              'for Grant Binding'))
        grant_binding = GrantBinding(grant, session, current_user)
        provider.grantgetter(grant_binding.get)
        provider.grantsetter(grant_binding.set)

def get_url(self, path='/', websocket=False, remote=True,
              attach_api_key=True, userId=None, pass_uid=False, **query):
    userId = userId or self.userid
    if attach_api_key and self.api_key:
      query.update({'api_key':self.api_key, 'deviceId': self.device_id})
    if pass_uid:
      query['userId'] = userId

    if remote:
      url = self.urlremote or self.url
    else:
      url = self.url

    if websocket:
      scheme = {'http':'ws', 'https':'wss'}[url.scheme]
    else:
      scheme = url.scheme
    netloc = url.netloc + '/emby'

    url = urlunparse((scheme, netloc, path, '', '{params}', '')).format(
      UserId   = userId,
      ApiKey   = self.api_key,
      DeviceId = self.device_id,
      params   = urlencode(query)
    )

    return url[:-1] if url[-1] == '?' else url

