    return result

def __getJoinerState(self):
        maxDuration = 150  # seconds
        t_end = time.time() + maxDuration
        while time.time() < t_end:
            joinerState = self.__stripValue(self.__sendCommand('sudo wpanctl getprop -v NCP:State')[0])
            if joinerState == 'offline:commissioned':
                return True
            elif joinerState == 'associating:credentials-needed':
                return False
            else:
                time.sleep(5)
                continue
        return False

def next(self):

        if not self._index_stack:
            return False

        index = self._index_stack[-1]

        if self._last_index != self._dic.ROOT:

            child_label = self._guide.child(index)  # UCharType

            if child_label:
                # Follows a transition to the first child.
                index = self._follow(child_label, index)
                if index is None:
                    return False
            else:
                while True:
                    sibling_label = self._guide.sibling(index)
                    # Moves to the previous node.
                    if len(self.key) > 0:
                        self.key.pop()
                        #self.key[-1] = 0

                    self._index_stack.pop()
                    if not self._index_stack:
                        return False

                    index = self._index_stack[-1]
                    if sibling_label:
                        # Follows a transition to the next sibling.
                        index = self._follow(sibling_label, index)
                        if index is None:
                            return False
                        break

        return self._find_terminal(index)

def box(text, width=100, height=3, corner="+", horizontal="-", vertical="|"):
        if width <= len(text) - 4:
            print("width is not large enough! apply auto-adjust...")
            width = len(text) + 4
        if height <= 2:
            print("height is too small! apply auto-adjust...")
            height = 3
        if (height % 2) == 0:
            print("height has to be odd! apply auto-adjust...")
            height += 1

        head = tail = corner + horizontal * (width - 2) + corner

        pad = "%s%s%s" % (vertical, " " * (width - 2), vertical)
        pad_number = (height - 3) // 2

        pattern = "{: ^%s}" % (width - 2, )
        body = vertical + pattern.format(text) + vertical
        return "\n".join([head,] + [pad,] * pad_number + [body,] + [pad,] * pad_number + [tail,])

def glob(pathname, pattern=None):
