def fi_ssn(ssn, allow_temporal_ssn=True):
    if not ssn:
        return False

    result = re.match(ssn_pattern, ssn)
    if not result:
        return False
    gd = result.groupdict()
    checksum = int(gd['date'] + gd['serial'])
    return (
        int(gd['serial']) >= 2 and
        (allow_temporal_ssn or int(gd['serial']) <= 899) and
        ssn_checkmarks[checksum % len(ssn_checkmarks)] ==
        gd['checksum']
    )

