  plt.ylim(.5, len(event_times_list) + .5)
  return ax

def Jzjmcoeff(ls, m, shift) -> sympy.Expr:
    assert isinstance(ls, SpinSpace)
    n = ls.dimension
    s = sympify(n - 1) / 2
    assert n == int(2 * s + 1)
    if isinstance(m, str):
        return ls.basis.index(m) - s
    elif isinstance(m, int):
        if shift:
            assert 0 <= m < n
            return m - s
    else:
        return sympify(m)

