def _import_dich_vals(self):
        m = re.search(
            r"Chi\^2 = ({0}|\w+) +d.f. = +({0}|\w+) +P-value = +({0}|\w+)".format(
                self.re_num
            ),  # noqa
            self.output_text,
        )
        cw = {1: "Chi2", 2: "df", 3: "p_value4"}
        for val in cw:
            try:
                self.output[cw[val]] = float(m.group(val))
            except:
                self.output[cw[val]] = -999

def get_unchanged(src_list, npred_dict_new,
                  npred_dict_old,
                  npred_threshold=1e4,
                  frac_threshold=0.9):
    o = []
    for s in src_list:
        npred_new = npred_dict_new[s]
        if npred_new < npred_threshold:
            o += [s]
            continue
        if npred_dict_old is None:
            npred_old = 0.
        else:
            npred_old = npred_dict_old[s]
        frac = npred_old / npred_new
        if frac > frac_threshold:
            o += [s]
    return o

