def check_empty_response(self, orig_request, method_config, start_response):
    response_config = method_config.get('response', {}).get('body')
    if response_config == 'empty':
      # The response to this function should be empty.  We should return a 204.
      # Note that it's possible that the backend returned something, but we'll
      # ignore it.  This matches the behavior in the Endpoints server.
      cors_handler = self._create_cors_handler(orig_request)
      return util.send_wsgi_no_content_response(start_response, cors_handler)

def python_value(self, value):
        value = super(OrderedUUIDField, self).python_value(value)
        u = binascii.b2a_hex(value)
        value = u[8:16] + u[4:8] + u[0:4] + u[16:22] + u[22:32]
        return UUID(value.decode())

def get_remote_user(request):
    if 'HTTP_AUTHORIZATION' not in request.environ:
        return
    authorization = request.environ['HTTP_AUTHORIZATION']
    try:
        authmeth, tmp = authorization.split(' ', 1)
    except ValueError:  # not enough values to unpack
        return
    if authmeth.lower() != 'basic':
        return
    try:
        tmp = base64.b64decode(tmp.strip().encode('latin1')).decode('latin1')
    except (binascii.Error, TypeError):  # can't decode
        return
    try:
        login, password = tmp.split(':', 1)
    except ValueError:  # not enough values to unpack
        return
    return login, password

def read(self, input_buffer, kmip_version=enums.KMIPVersion.KMIP_1_0):
        super(GetAttributeListRequestPayload, self).read(
            input_buffer,
            kmip_version=kmip_version
        )
        local_buffer = utils.BytearrayStream(input_buffer.read(self.length))

        if self.is_tag_next(enums.Tags.UNIQUE_IDENTIFIER, local_buffer):
            self._unique_identifier = primitives.TextString(
                tag=enums.Tags.UNIQUE_IDENTIFIER
            )
            self._unique_identifier.read(
                local_buffer,
                kmip_version=kmip_version
            )
        else:
            self._unique_identifier = None

        self.is_oversized(local_buffer)

