def create_from_dictionary(self, datas):
        if "code" not in datas:
            raise ValueError("A response code must contain a code in \"%s\"." % repr(datas))

        code = ObjectResponseCode()
        self.set_common_datas(code, str(datas["code"]), datas)

        code.code = int(datas["code"])
        if "message" in datas:
            code.message = str(datas["message"])
        elif code.code in self.default_messages.keys():
            code.message = self.default_messages[code.code]
        if "generic" in datas:
            code.generic = to_boolean(datas["generic"])

        return code

def _data_zeroed(self):

        # NOTE: using np.where is faster than
        #     _data = np.copy(self.data_cutout)
        #     self._data[self._total_mask] = 0.
        return np.where(self._total_mask, 0,
                        self.data_cutout).astype(np.float64)

def get_info_consistent(self, ndim):
        if ndim > len(self.spacing):
            spacing = self.spacing + (1.0, ) * (ndim - len(self.spacing))
        else:
            spacing = self.spacing[:ndim]

        if ndim > len(self.offset):
            offset = self.offset + (0.0, ) * (ndim - len(self.offset))
        else:
            offset = self.offset[:ndim]

        if ndim > self.direction.shape[0]:
            direction = np.identity(ndim)
            direction[:self.direction.shape[0], :self.direction.shape[0]] = self.direction
        else:
            direction = self.direction[:ndim, :ndim]

        return spacing, offset, direction

def on_message(self, msg):
        if self not in clients:
            return

        try:
            payload = json_decode(msg)
        except ValueError:
            # unable to decode so we cannot handle the message
            return

        if 'close' in payload:
            self.close()
            return

        for verb, args in payload.items():
            self.group.action(verb, args)

def simple_tokenize(name):
    last_names, first_names = name.split(',')
    last_names = _RE_NAME_TOKEN_SEPARATOR.split(last_names)
    first_names = _RE_NAME_TOKEN_SEPARATOR.split(first_names)

    first_names = [NameToken(n) if len(n) > 1 else NameInitial(n)
                   for n in first_names if n]
    last_names = [NameToken(n) if len(n) > 1 else NameInitial(n)
                  for n in last_names if n]
    return {'lastnames': last_names,
            'nonlastnames': first_names}

