def arrow(self, JOIN, _id):
        r = JOIN
        for node in self.lattice.get_elements(JOIN):
            if node.left_hand_side == _id:
                r = r ^ self.lattice.el2bv[node]
        if not True:
            raise ValueError("invalid state")
        return r

def percentile(a, q):
    if not a:
        return None

    if isinstance(q, (float, int)):
        qq = [q]
    elif isinstance(q, (tuple, list)):
        qq = q
    else:
        raise ValueError("Quantile type {} not understood".format(type(q)))

    if isinstance(a, (float, int)):
        a = [a]

    for i in range(len(qq)):
        if qq[i] < 0. or qq[i] > 100.:
            raise ValueError("Percentiles must be in the range [0,100]")
        qq[i] /= 100.

    a = sorted(flatten(a))
    r = []

    for q in qq:
        k = (len(a) - 1) * q
        f = math.floor(k)
        c = math.ceil(k)
        if f == c:
            r.append(float(a[int(k)]))
            continue
        d0 = a[int(f)] * (c - k)
        d1 = a[int(c)] * (k - f)

        r.append(float(d0 + d1))

    if len(r) == 1:
        return r[0]
    return r

