        try:
            self._windows = {}
            if not object_name:
                handle, name, app = self._get_window_handle(window_name, False)
            else:
                handle = self._get_object_handle(window_name, object_name,
                                                 wait_for_object=False,
                                                 force_remap=True)
            # If window and/or object exist, exception will not be thrown
            # blindly return 1
            return 1
        except LdtpServerException:
            pass
        return 0

def discussions_notifications(user):
    notifications = []

    # Only fetch required fields for notification serialization
    # Greatly improve performances and memory usage
    qs = discussions_for(user).only('id', 'created', 'title', 'subject')

    # Do not dereference subject (so it's a DBRef)
    # Also improve performances and memory usage
    for discussion in qs.no_dereference():
        notifications.append((discussion.created, {
            'id': discussion.id,
            'title': discussion.title,
            'subject': {
                'id': discussion.subject['_ref'].id,
                'type': discussion.subject['_cls'].lower(),
            }
        }))

    return notifications

def get_model_by_name(model_name):
    if isinstance(model_name, six.string_types) and \
            len(model_name.split('.')) == 2:
        app_name, model_name = model_name.split('.')

        if django.VERSION[:2] < (1, 8):
            model = models.get_model(app_name, model_name)
        else:
            from django.apps import apps
            model = apps.get_model(app_name, model_name)
    else:
        raise ValueError("{0} is not a Django model".format(model_name))

    return model

