            self.add_update_resource(resource, ignore_datasetid)

def create_inverse_model(self, encoded_state, encoded_next_state):
        combined_input = tf.concat([encoded_state, encoded_next_state], axis=1)
        hidden = tf.layers.dense(combined_input, 256, activation=self.swish)
        if self.brain.vector_action_space_type == "continuous":
            pred_action = tf.layers.dense(hidden, self.act_size[0], activation=None)
            squared_difference = tf.reduce_sum(tf.squared_difference(pred_action, self.selected_actions), axis=1)
            self.inverse_loss = tf.reduce_mean(tf.dynamic_partition(squared_difference, self.mask, 2)[1])
        else:
            pred_action = tf.concat(
                [tf.layers.dense(hidden, self.act_size[i], activation=tf.nn.softmax)
                 for i in range(len(self.act_size))], axis=1)
            cross_entropy = tf.reduce_sum(-tf.log(pred_action + 1e-10) * self.selected_actions, axis=1)
            self.inverse_loss = tf.reduce_mean(tf.dynamic_partition(cross_entropy, self.mask, 2)[1])

def execute_operation(self, method="GET", ops_path="", payload=""):
        operation_path_URL = "".join([self.api_server, ops_path])
        logging.debug("%s %s" %(method, operation_path_URL))
        if payload == "":
            res = requests.request(method, operation_path_URL)
        else:
            logging.debug("PAYLOAD:\n%s" %(payload))
            res = requests.request(method, operation_path_URL, data=payload)
        logging.debug("RESPONSE:\n%s" %(res.json()))
        return res

def assert_single_path_by_glob(self, components):
    glob_path_string = os.path.join(*components)
    expanded_glob = glob.glob(glob_path_string)

    try:
      return assert_single_element(expanded_glob)
    except StopIteration as e:
      raise self.ArchiveFileMappingError(
        "No elements for glob '{}' -- expected exactly one."
        .format(glob_path_string),
        e)
    except ValueError as e:
      raise self.ArchiveFileMappingError(
        "Should have exactly one path matching expansion of glob '{}'."
        .format(glob_path_string),
        e)

