def stream_events(signals: Sequence[Signal], filter: Callable[[T_Event], bool] = None, *,
                  max_queue_size: int = 0) -> AsyncIterator[T_Event]:
    @async_generator
    async def streamer():
        try:
            while True:
                event = await queue.get()
                if filter is None or filter(event):
                    await yield_(event)
        finally:
            cleanup()

    def cleanup():
        nonlocal queue
        if queue is not None:
            for signal in signals:
                signal.disconnect(queue.put_nowait)

            queue = None

    assert check_argument_types()
    queue = Queue(max_queue_size)  # type: Queue[T_Event]
    for signal in signals:
        signal.connect(queue.put_nowait)

    gen = [streamer()]  # this is to allow the reference count to drop to 0
    weakref.finalize(gen[0], cleanup)
    return gen.pop()

def credentials_required(method_func):
    def _checkcredentials(self, *args, **kwargs):
        if self.username and self.password:
            return method_func(self, *args, **kwargs)
        else:
            raise CredentialsMissingError("This is a private method. \
You must provide a username and password when you initialize the \
DocumentCloud client to attempt this type of request.")

    return wraps(method_func)(_checkcredentials)

def is_sequence_match(pattern: list, instruction_list: list, index: int) -> bool:
    for index, pattern_slot in enumerate(pattern, start=index):
        try:
            if not instruction_list[index]["opcode"] in pattern_slot:
                return False
        except IndexError:
            return False
    return True

