def delete_vector(self, hash_name, bucket_keys, data):
        with self.redis_object.pipeline() as pipeline:
            for key in bucket_keys:
                redis_key = self._format_redis_key(hash_name, key)
                rows = [(row, pickle.loads(row).get('data'))
                        for row in self._get_bucket_rows(hash_name, key)]
                for _, id_data in rows:
                    if id_data == data:
                        break
                else:
                    # Deleted data is not present in this bucket
                    continue
                pipeline.delete(redis_key)
                pipeline.rpush(redis_key, *(row for row, id_data in rows
                                            if id_data != data))
            pipeline.execute()

def find_binary(self, binary):
        if os.path.exists(binary):
            return binary

        # Extract out the filename if we were given a full path
        binary_name = os.path.basename(binary)

        # Gather $PATH
        search_paths = os.environ['PATH'].split(':')

        # Extra paths to scan...
        default_paths = [
            '/usr/bin',
            '/bin'
            '/usr/local/bin',
            '/usr/sbin',
            '/sbin'
            '/usr/local/sbin',
        ]

        for path in default_paths:
            if path not in search_paths:
                search_paths.append(path)

        for path in search_paths:
            if os.path.isdir(path):
                filename = os.path.join(path, binary_name)
                if os.path.exists(filename):
                    return filename

        return binary

def extract_vars(*names,**kw):

    depth = kw.get('depth',0)

    callerNS = sys._getframe(depth+1).f_locals
    return dict((k,callerNS[k]) for k in names)

def precompile(self, content, kind=None, elem=None, filename=None,
               charset=None, **kwargs):
    if not kind:
        return False, content
    attrs = self.parser.elem_attribs(elem)
    mimetype = attrs.get("type", None)
    if mimetype is None:
        return False, content

    filter_or_command = self.precompiler_mimetypes.get(mimetype)
    if filter_or_command is None:
        if mimetype in ("text/css", "text/javascript"):
            return False, content
        raise CompressorError("Couldn't find any precompiler in "
                              "COMPRESS_PRECOMPILERS setting for "
                              "mimetype '%s'." % mimetype)

    mod_name, cls_name = get_mod_func(filter_or_command)
    try:
        mod = import_module(mod_name)
    except (ImportError, TypeError):
        filter = CachedCompilerFilter(
            content=content, filter_type=self.type, filename=filename,
            charset=charset, command=filter_or_command, mimetype=mimetype)
        return True, filter.input(**kwargs)
    try:
        precompiler_class = getattr(mod, cls_name)
    except AttributeError:
        raise FilterDoesNotExist('Could not find "%s".' % filter_or_command)
    filter = precompiler_class(
        content, attrs=attrs, filter_type=self.type, charset=charset,
        filename=filename, **kwargs)
    return True, filter.input(**kwargs)

