def get_mean_and_stddevs(self, sites, rup, dists, imt, stddev_types):
        assert all(stddev_type in self.DEFINED_FOR_STANDARD_DEVIATION_TYPES
                   for stddev_type in stddev_types)

        C = self.COEFFS[imt]
        mean = (self._get_magnitude_scaling(C, rup.mag) +
                self._get_distance_scaling(C, rup.mag, dists.rhypo))
        if imt.name in "SA PGA":
            mean = np.log(np.exp(mean) / (100.0 * g))
        stddevs = self._compute_std(C, stddev_types, len(dists.rhypo))
        return mean, stddevs

def get_beam(self, ra, dec):
        # check to see if we need to scale the major axis based on the declination
        if self.lat is None:
            factor = 1
        else:
            # this works if the pa is zero. For non-zero pa it's a little more difficult
            factor = np.cos(np.radians(dec - self.lat))
        return Beam(self.beam.a / factor, self.beam.b, self.beam.pa)

def docs_init_to_class(self):
        result = False
        if not self.parsed:
            self._parse()
        einit = []
        eclass = []
        for e in self.docs_list:
            if len(eclass) == len(einit) + 1 and e['docs'].element['name'] == '__init__':
                einit.append(e)
            elif not eclass and e['docs'].element['type'] == 'class':
                eclass.append(e)
        for c, i in zip(eclass, einit):
            start, _ = c['location']
            if start < 0:
                start, _ = i['location']
                if start > 0:
                    result = True
                    cspaces = c['docs'].get_spaces()
                    ispaces = i['docs'].get_spaces()
                    c['docs'].set_spaces(ispaces)
                    i['docs'].set_spaces(cspaces)
                    c['docs'].generate_docs()
                    i['docs'].generate_docs()
                    c['docs'], i['docs'] = i['docs'], c['docs']
        return result

def duplicate_items(*collections):
    duplicates = set()
    seen = set()
    for item in flatten(collections):
        if item in seen:
            duplicates.add(item)
        else:
            seen.add(item)
    return duplicates

def format_config(data, env):
    if isinstance(data, list):
        return [format_config(datum, env) for datum in data]
    elif isinstance(data, dict):
        return {
            format_config(key, env): format_config(value, env)
            for key, value in data.items()
        }
    elif isinstance(data, str):
        def replace(match):
            var_name = match.group(1)
            var = env.get(var_name)
            assert var, 'Variable %s undefined.' % var_name
            return var
        return ENV_PLACEHODLER.sub(replace, data)
    else:
        return data

def entrance_rounded(Di, rc, method='Rennels'):
    if method is None:
        method = 'Rennels'
    if method == 'Rennels':
        if rc/Di > 1.0:
            return 0.03
        lbd = 1.0 + 0.622*(1.0 - 0.30*(rc/Di)**0.5 - 0.70*(rc/Di))**4.0
        return 0.0696*(1.0 - 0.569*rc/Di)*lbd**2.0 + (lbd - 1.0)**2
    elif method == 'Swamee':
        return 0.5/(1.0 + 36.0*(rc/Di)**1.2)
    elif method == 'Crane':
        ratio = rc/Di
        if ratio < 0:
            return 0.5 
        elif ratio > 0.15:
            return 0.04
        else:
            return interp(ratio, entrance_rounded_ratios_Crane,
                          entrance_rounded_Ks_Crane)
    elif method == 'Miller':
        rc_Di = rc/Di
        if rc_Di > 0.3:
            rc_Di = 0.3
        return horner(entrance_rounded_Miller_coeffs, 20.0/3.0*(rc_Di - 0.15))
    elif method == 'Harris':
        ratio = rc/Di
        if ratio > .16:
            return 0.0
        return float(entrance_rounded_Harris(ratio))
    elif method == 'Idelchik':
        ratio = rc/Di
        if ratio > .2:
            return entrance_rounded_Ks_Idelchik[-1]
        return float(entrance_rounded_Idelchik(ratio))
    else:
        raise ValueError('Specified method not recognized; methods are %s'
                         %(entrance_rounded_methods))

