def ReleaseFileSystem(self, file_system):
    identifier, cache_value = self._file_system_cache.GetCacheValueByObject(
        file_system)

    if not identifier:
      raise RuntimeError('Object not cached.')

    if not cache_value:
      raise RuntimeError('Invalid cache value.')

    self._file_system_cache.ReleaseObject(identifier)

    result = cache_value.IsDereferenced()
    if result:
      self._file_system_cache.RemoveObject(identifier)

    return result

def get_results(self, request):
        super(MediaTreeChangeList, self).get_results(request)
        try:
            reduce_levels = abs(int(get_request_attr(request, 'reduce_levels', 0)))
        except TypeError:
            reduce_levels = 0
        is_filtered = self.is_filtered(request)
        if is_filtered or reduce_levels:
            for item in self.result_list:
                item.prevent_save()
                item.actual_level = item.level
                if is_filtered:
                    item.reduce_levels = item.level
                    item.level = 0
                else:
                    item.reduce_levels = reduce_levels
                    item.level = max(0, item.level - reduce_levels)

