def get_cli_multi_parser(funcs, skip_first=0):
    parser = ArgumentParser(description='which subcommand do you want?')
    subparsers = parser.add_subparsers(
        title='subcommands', dest='subcmd', help=''
    )
    for func in funcs:
        help_msg, func_args = _get_func_args(func)
        sub_parser = subparsers.add_parser(func.__name__, help=help_msg)
        get_cli_parser(func, skip_first=skip_first, parser=sub_parser)
    return parser

def create_app(name, engine):
    try:
        if engine.lower() == "sqlalchemy":
            url = urlopen(SQLA_REPO_URL)
            dirname = "Flask-AppBuilder-Skeleton-master"
        elif engine.lower() == "mongoengine":
            url = urlopen(MONGOENGIE_REPO_URL)
            dirname = "Flask-AppBuilder-Skeleton-me-master"
        zipfile = ZipFile(BytesIO(url.read()))
        zipfile.extractall()
        os.rename(dirname, name)
        click.echo(click.style("Downloaded the skeleton app, good coding!", fg="green"))
        return True
    except Exception as e:
        click.echo(click.style("Something went wrong {0}".format(e), fg="red"))
        if engine.lower() == "sqlalchemy":
            click.echo(
                click.style(
                    "Try downloading from {0}".format(SQLA_REPO_URL), fg="green"
                )
            )
        elif engine.lower() == "mongoengine":
            click.echo(
                click.style(
                    "Try downloading from {0}".format(MONGOENGIE_REPO_URL), fg="green"
                )
            )
        return False

def filesByCell(fnames,cells):
    byCell={}
    fnames=smartSort(fnames)
    days = list(set([elem[:5] for elem in fnames if elem.endswith(".abf")])) # so pythonic!
    for day in smartSort(days):
        parent=None
        for i,fname in enumerate([elem for elem in fnames if elem.startswith(day) and elem.endswith(".abf")]):
            ID=os.path.splitext(fname)[0]
            if len([x for x in fnames if x.startswith(ID)])-1:
                parent=ID
            if not parent in byCell:
                byCell[parent]=[]
            byCell[parent]=byCell[parent]+[fname]
    return byCell

