def _validate_nodes_with_data(self, names):
        names = names if isinstance(names, list) else [names]
        if not names:
            raise RuntimeError("Argument `nodes` is not valid")
        for ndict in names:
            if (not isinstance(ndict, dict)) or (
                isinstance(ndict, dict) and (set(ndict.keys()) != set(["name", "data"]))
            ):
                raise RuntimeError("Argument `nodes` is not valid")
            name = ndict["name"]
            if (not isinstance(name, str)) or (
                isinstance(name, str)
                and (
                    (" " in name)
                    or any(
                        [
                            element.strip() == ""
                            for element in name.strip().split(self._node_separator)
                        ]
                    )
                )
            ):
                raise RuntimeError("Argument `nodes` is not valid")

def _load(self, element, commentchar):
        for child in element:            
            if "id" in child.attrib:
                tline = TemplateLine(child, self, commentchar)
                self.order.append(tline.identifier)
                self.lines[tline.identifier] = tline
            else:
                msg.warn("no id element in {}. Ignored. (group._load)".format(child))

