            print("Do not take the Alaska county level result")
            return None

        kwargs = {"level__name": row["level"]}

        if row["reportingunitname"]:
            name = row["reportingunitname"]
        else:
            name = row["statename"]

        if row["level"] in [
            geography.DivisionLevel.COUNTY,
            geography.DivisionLevel.TOWNSHIP,
