def blockgen1d(block, size):
    def numblock(blk, x):
        """Compute recursively the numeric intervals

        """
        a, b = x
        if b - a <= blk:
            return [x]
        else:
            result = []
            d = int(b - a) // 2
            for i in imap(numblock, [blk, blk], [(a, a + d), (a + d, b)]):
                result.extend(i)
            return result

    return [slice(*l) for l in numblock(block, (0, size))]

