def string_to_macaddr(value, strict=False):
    if is_undefined(value):
        if strict:
            raise ValueError('The value cannot be null')
        return None

    match = REGEX_MAC_ADDRESS.match(value.lower())
    if match is None:
        raise ValueError('The specified string "%s" does not represent a MAC address' % value)

    return match.groups()

def get_font_files():
    roots = [
        '/usr/share/fonts/truetype',     # where ubuntu puts fonts
        '/usr/share/fonts',              # where fedora puts fonts
        os.path.expanduser('~/.fonts'),  # custom user fonts
        os.path.abspath(os.path.join(os.path.dirname(__file__), 'fonts')),
    ]
    result = {}
    for root in roots:
        for path, dirs, names in os.walk(root):
            for name in names:
                if name.endswith(('.ttf', '.otf')):
                    result[name[:-4]] = os.path.join(path, name)
    return result

