def margin(self, axis):
        if self._slice.ndim < 2:
            msg = (
                "Scale Means marginal cannot be calculated on 1D cubes, as"
                "the scale means already get reduced to a scalar value."
            )
            raise ValueError(msg)

        dimension_index = 1 - axis
        margin = self._slice.margin(axis=axis)
        if len(margin.shape) > 1:
            index = [
                0 if d.dimension_type == DT.MR else slice(None)
                for d in self._slice.dimensions
            ]
            margin = margin[index]
        total = np.sum(margin)
        values = self.values[dimension_index]

        if values is None:
            return None

        return np.sum(values * margin) / total

def _getitem_normalized(self, index):
        index = normalize_slice(len(self), index)
        counter = 0
        output = ''
        for fs in self.chunks:
            if index.start < counter + len(fs) and index.stop > counter:
                s_part = fs.s[max(0, index.start - counter):index.stop - counter]
                piece = Chunk(s_part, fs.atts).color_str
                output += piece
            counter += len(fs)
            if index.stop < counter:
                break
        return fmtstr(output)

def predict_body_units(self):
        longest_dist = np.max(np.max(self.v, axis=0) - np.min(self.v, axis=0))
        if round(longest_dist / 1000) > 0:
            return 'mm'
        if round(longest_dist / 100) > 0:
            return 'cm'
        if round(longest_dist / 10) > 0:
            return 'dm'
        return 'm'

