def shannon_entropy(pvec, base=2):
    # pylint: disable=missing-docstring
    if base == 2:
        def logfn(x):
            return - x * np.log2(x)
    elif base == np.e:
        def logfn(x):
            return - x * np.log(x)
    else:
        def logfn(x):
            return -x * np.log(x) / np.log(base)

    h = 0.
    for x in pvec:
        if 0 < x < 1:
            h += logfn(x)
    return h

def _eval_args(args):
    res = []
    for arg in args:
        if not isinstance(arg, tuple):
            res.append(arg)
        elif is_callable_type(arg[0]):
            callable_args = _eval_args(arg[1:])
            if len(arg) == 2:
                res.append(Callable[[], callable_args[0]])
            elif arg[1] is Ellipsis:
                res.append(Callable[..., callable_args[1]])
            else:
                res.append(Callable[list(callable_args[:-1]), callable_args[-1]])
        else:
            res.append(type(arg[0]).__getitem__(arg[0], _eval_args(arg[1:])))
    return tuple(res)

def _switch_partition() -> RootPartitions:
    res = subprocess.check_output(['ot-switch-partitions'])
    for line in res.split(b'\n'):
        matches = re.match(
            b'Current boot partition: ([23]), setting to ([23])',
            line)
        if matches:
            return {b'2': RootPartitions.TWO,
                    b'3': RootPartitions.THREE}[matches.group(2)]
    else:
        raise RuntimeError(f'Bad output from ot-switch-partitions: {res}')

