def create_repository(self, repository_form=None):
        if repository_form is None:
            raise NullArgument()
        if not isinstance(repository_form, abc_repository_objects.RepositoryForm):
            raise InvalidArgument('argument type is not a RepositoryForm')
        if repository_form.is_for_update():
            raise InvalidArgument('form is for update only, not create')
        try:
            if self._forms[repository_form.get_id().get_identifier()] == CREATED:
                raise IllegalState('form already used in a create transaction')
        except KeyError:
            raise Unsupported('form did not originate from this session')
        if not repository_form.is_valid():
            raise InvalidArgument('one or more of the form elements is invalid')

        url_path = construct_url('objective_banks')
        try:
            result = self._post_request(url_path, repository_form._my_map)
        except Exception:
            raise  # OperationFailed
        self._forms[repository_form.get_id().get_identifier()] = CREATED
        return objects.Repository(result)

def unpack(cls, msg, client, server, request_id):
        flags, = _UNPACK_INT(msg[:4])
        namespace, pos = _get_c_string(msg, 4)
        is_command = namespace.endswith('.$cmd')
        tmp, = _UNPACK_INT(msg[pos:pos + 4])
        pos += 4
        num_to_return, = _UNPACK_INT(msg[pos:pos + 4])
        pos += 4
        docs = bson.decode_all(msg[pos:], CODEC_OPTIONS)
        if is_command:
            assert len(docs) == 1
            command_ns = namespace[:-len('.$cmd')]
            return Command(docs, namespace=command_ns, flags=flags,
                           _client=client, request_id=request_id,
                           _server=server)
        else:
            if len(docs) == 1:
                fields = None
            else:
                assert len(docs) == 2
                fields = docs[1]
            return OpQuery(docs[0], fields=fields, namespace=namespace,
                           flags=flags, num_to_skip=tmp,
                           num_to_return=num_to_return, _client=client,
                           request_id=request_id, _server=server)

