def _parse_result(result):
    lines = filter(lambda x: x.strip(), result.splitlines())  # rm blank lines

    if not lines:
        return {}

    out = {}
    for line in lines:
        line = line.split(":")
        fn = line[0].strip()

        line = " ".join(line[1:])

        line = line.rsplit(None, 1)
        status = line.pop().strip()

        out[fn] = (status, " ".join(line).strip())

    return out

