def list_topic_rules(topic=None, ruleDisabled=None,
            region=None, key=None, keyid=None, profile=None):
    try:
        conn = _get_conn(region=region, key=key, keyid=keyid, profile=profile)
        kwargs = {}
        if topic is not None:
            kwargs['topic'] = topic
        if ruleDisabled is not None:
            kwargs['ruleDisabled'] = ruleDisabled
        rules = []
        for ret in __utils__['boto3.paged_call'](conn.list_topic_rules,
                                 marker_flag='nextToken',
                                 marker_arg='nextToken',
                                 **kwargs):
            rules.extend(ret['rules'])
        if not bool(rules):
            log.warning('No rules found')
        return {'rules': rules}
    except ClientError as e:
        return {'error': __utils__['boto3.get_error'](e)}

def eval_nonagg_call(self, exp):
    # todo: get more concrete about argument counts
    args=self.eval(exp.args)
    if exp.f=='coalesce':
      a,b=args # todo: does coalesce take more than 2 args?
      return b if a is None else a
    elif exp.f=='unnest': return self.eval(exp.args)[0] # note: run_select does some work in this case too
    elif exp.f in ('to_tsquery','to_tsvector'): return set(self.eval(exp.args.children[0]).split())
    else: raise NotImplementedError('unk_function',exp.f)

def _decode_embedded_dict(src):
    output = {}
    for key, val in six.iteritems(src):
        if isinstance(val, dict):
            val = _decode_embedded_dict(val)
        elif isinstance(val, list):
            val = _decode_embedded_list(val)  # pylint: disable=redefined-variable-type
        elif isinstance(val, bytes):
            try:
                val = val.decode()
            except UnicodeError:
                pass
        if isinstance(key, bytes):
            try:
                key = key.decode()
            except UnicodeError:
                pass
        output[key] = val
    return output

