def destroys(self, i=0):
        regs = {'a', 'b', 'c', 'd', 'e', 'f', 'h', 'l', 'i', 'ixh', 'ixl', 'iyh', 'iyl', 'sp'}
        top = len(self)
        result = []

        for ii in range(i, top):
            for r in self.mem[ii].destroys:
                if r in regs:
                    result.append(r)
                    regs.remove(r)

            if not regs:
                break

        return result

def verify_signature(message, key, signature):
    digest = hmac.new(key, msg=message, digestmod=hashlib.sha256).hexdigest()
    return digest == signature

def printlet(flatten=False, **kwargs):
    chunk = yield
    if flatten:
        while True:
            print(*chunk, **kwargs)
            chunk = yield chunk
    else:
        while True:
            print(chunk, **kwargs)
            chunk = yield chunk

def _homedir_setter(self, directory):
        if not directory:
            log.debug("GPGBase._homedir_setter(): Using default homedir: '%s'"
                      % _util._conf)
            directory = _util._conf

        hd = _parsers._fix_unsafe(directory)
        log.debug("GPGBase._homedir_setter(): got directory '%s'" % hd)

        if hd:
            log.debug("GPGBase._homedir_setter(): Check existence of '%s'" % hd)
            _util._create_if_necessary(hd)

        if self.ignore_homedir_permissions:
            self._homedir = hd
        else:
            try:
                log.debug("GPGBase._homedir_setter(): checking permissions")
                assert _util._has_readwrite(hd), \
                    "Homedir '%s' needs read/write permissions" % hd
            except AssertionError as ae:
                msg = ("Unable to set '%s' as GnuPG homedir" % directory)
                log.debug("GPGBase.homedir.setter(): %s" % msg)
                log.debug(str(ae))
                raise RuntimeError(str(ae))
            else:
                log.info("Setting homedir to '%s'" % hd)
                self._homedir = hd

def _agg_cv_result(raw_results, eval_train_metric=False):
    cvmap = collections.defaultdict(list)
    metric_type = {}
    for one_result in raw_results:
        for one_line in one_result:
            if eval_train_metric:
                key = "{} {}".format(one_line[0], one_line[1])
            else:
                key = one_line[1]
            metric_type[key] = one_line[3]
            cvmap[key].append(one_line[2])
    return [('cv_agg', k, np.mean(v), metric_type[k], np.std(v)) for k, v in cvmap.items()]

