        for key in allpaths:
            paths = self.get_paths(key)
            self.check_paths(paths, update=update)

def validate(self, value=None, model=None, context=None):
        errors = []
        for validator in self.validators:
            if value is None and not isinstance(validator, Required):
                continue

            error = validator.run(
                value=value,
                model=model,
                context=context if self.use_context else None
            )
            if error:
                errors.append(error)

        return errors

