def _prepare_static_info(self):

        pipeline_files = {}

        with open(join(self.workdir, self.pipeline_name)) as fh:
            pipeline_files["pipelineFile"] = fh.readlines()

        nf_config = join(self.workdir, "nextflow.config")
        if os.path.exists(nf_config):
            with open(nf_config) as fh:
                pipeline_files["configFile"] = fh.readlines()

        # Check for specific flowcraft configurations files
        configs = {
            "params.config": "paramsFile",
            "resources.config": "resourcesFile",
            "containers.config": "containersFile",
            "user.config": "userFile",
        }
        for config, key in configs.items():
            cfile = join(self.workdir, config)
            if os.path.exists(cfile):
                with open(cfile) as fh:
                    pipeline_files[key] = fh.readlines()

        return pipeline_files

def _upload_config_content(self, configuration, rollbacked=False):
        try:
            for configuration_line in configuration.splitlines():
                self._device.cli(configuration_line)
            self._config_changed = True  # configuration was changed
            self._committed = False  # and not committed yet
        except (pyPluribus.exceptions.CommandExecutionError,
                pyPluribus.exceptions.TimeoutError) as clierr:
            if not rollbacked:
                # rollack errors will just trow
                # to avoid loops
                self.discard()
            raise pyPluribus.exceptions.ConfigLoadError("Unable to upload config on the device: {err}.\
                Configuration will be discarded.".format(err=clierr.message))
        return True

def md5_string(s):
