def relation_completions(
    completion_text: str, bel_spec: BELSpec, bel_fmt: str, size: int
) -> list:

    if bel_fmt == "short":
        relation_list = bel_spec["relations"]["list_short"]
    else:
        relation_list = bel_spec["relations"]["list_long"]

    matches = []
    for r in relation_list:
        if re.match(completion_text, r):
            matches.append(r)

    replace_list = []
    for match in matches:
        highlight = match.replace(completion_text, f"<em>{completion_text}</em>")
        replace_list.append(
            {
                "replacement": match,
                "label": match,
                "highlight": highlight,
                "type": "Relation",
            }
        )

    return replace_list[:size]

def _distributeCells(numCellsPop):
    from .. import sim

    hostCells = {}
    for i in range(sim.nhosts):
        hostCells[i] = []

    for i in range(numCellsPop):
        hostCells[sim.nextHost].append(i)

        sim.nextHost+=1
        if sim.nextHost>=sim.nhosts:
            sim.nextHost=0

    if sim.cfg.verbose: 
        print(("Distributed population of %i cells on %s hosts: %s, next: %s"%(numCellsPop,sim.nhosts,hostCells,sim.nextHost)))
    return hostCells

