def findRelevantData(fileList,abfs):
    relevant=[]
    things={}
    for abf in abfs:
        for fname in fileList:
            if abf in fname and not fname in relevant:
                relevant.append(fname)
    for item in sorted(relevant):
        thing = os.path.basename(item)
        if ".png" in thing:
            continue
        if not "_" in thing:
            continue
        thing=thing.split("_")[-1].split(".")[0]
        if not thing in things.keys(): #prevent overwriting
            things[thing]=item
    return things

def subst_quoted_strings(sql, params):
    parts = sql.split('@')
    params_dont_match = "number of parameters doesn' match the transformed query"
    assert len(parts) == len(params) + 1, params_dont_match  # would be internal error
    out = []
    for i, param in enumerate(params):
        out.append(parts[i])
        out.append("'%s'" % param.replace('\\', '\\\\').replace("\'", "\\\'"))
    out.append(parts[-1])
    return ''.join(out)

