def update_columns_dict(self, kwargs):
        # make sure to do the geometric things that are needed for some of the
        # ComputedColumns first
        for key in ('triangles', 'vertices', 'centers', 'vnormals', 'tnormals'):
            if key in kwargs.keys():
                self.__setitem__(key, kwargs.pop(key))

        for k, v in kwargs.items():
            if isinstance(v, float) and k not in self._scalar_fields:
                # Then let's make an array with the correct length full of this
                # scalar

                # NOTE: this won't work for Nx3's, but that
                # really shouldn't ever happen since they should be set
                # within the init.
                # v = np.ones(self.Ntriangles)*v
                if self._compute_at_vertices:
                    v = np.full(self.Nvertices, v)
                else:
                    v = np.full(self.Ntriangles, v)

            self.__setitem__(k, v)

            if isinstance(v, ComputedColumn):
                # then let's update the mesh instance to correctly handle
                # inheritance
                self.__getitem__(k)._mesh = self

def PartialDynamicSystem(self, ieq, variable):
        if ieq == 0:
            # v=Rw
            if variable == self.physical_nodes[0].variable:
                # W=V/r
                return[Gain(self.physical_nodes[1].variable, variable, 1/self.wheels_radius)]
            elif variable == self.physical_nodes[1].variable:
                # V=rw
                return[Gain(self.physical_nodes[0].variable, variable, self.wheels_radius)]
        elif ieq == 1:
            # C=-FR
            if variable == self.variables[0]:
                # C=-FR
                return[Gain(self.variables[1], variable, -self.wheels_radius)]
            elif variable == self.variables[1]:
                # F=-C/R
                return[Gain(self.variables[0], variable, -1/self.wheels_radius)]

def explore_show_head(self, uri, check_headers=None):
        print("HEAD %s" % (uri))
        if (re.match(r'^\w+:', uri)):
            # Looks like a URI
            response = requests.head(uri)
        else:
            # Mock up response if we have a local file
            response = self.head_on_file(uri)
        print("  status: %s" % (response.status_code))
        if (response.status_code == '200'):
            # print some of the headers
            for header in ['content-length', 'last-modified',
                           'lastmod', 'content-type', 'etag']:
                if header in response.headers:
                    check_str = ''
                    if (check_headers is not None and
                            header in check_headers):
                        if (response.headers[header] == check_headers[header]):
                            check_str = ' MATCHES EXPECTED VALUE'
                        else:
                            check_str = ' EXPECTED %s' % (
                                check_headers[header])
                    print(
                        "  %s: %s%s" %
                        (header, response.headers[header], check_str))

