def filter(self, media_type, **params):
        mtype, msubtype = self._split_media_type(media_type)
        for x in self.__iter__():
            # all the params have to match to make the media type valid
            matched = True
            for k, v in params.items():
                if x[2].get(k, None) != v:
                    matched = False
                    break

            if matched:
                if x[0][0] == '*':
                    if x[0][1] == '*':
                        yield x

                    elif x[0][1] == msubtype:
                        yield x

                elif mtype == '*':
                    if msubtype == '*':
                        yield x

                    elif x[0][1] == msubtype:
                        yield x

                elif x[0][0] == mtype:
                    if msubtype == '*':
                        yield x

                    elif x[0][1] == '*':
                        yield x

                    elif x[0][1] == msubtype:
                        yield x

def get_module_environment(env=None, function=None):
    result = {}
    if not env:
        env = {}
    for env_src in [env.get('__opts__', {}), env.get('__pillar__', {})]:
        fname = env.get('__file__', '')
        physical_name = os.path.basename(fname).split('.')[0]
        section = os.path.basename(os.path.dirname(fname))
        m_names = [env.get('__virtualname__')]
        if physical_name not in m_names:
            m_names.append(physical_name)
        for m_name in m_names:
            if not m_name:
                continue
            result.update(env_src.get('system-environment', {}).get(
                section, {}).get(m_name, {}).get('_', {}).copy())
            if function is not None:
                result.update(env_src.get('system-environment', {}).get(
                    section, {}).get(m_name, {}).get(function, {}).copy())

    return result

