def prior_predictive_to_xarray(self):
        prior_predictive = self.prior_predictive

        if (
            isinstance(prior_predictive, (tuple, list)) and prior_predictive[0].endswith(".csv")
        ) or (isinstance(prior_predictive, str) and prior_predictive.endswith(".csv")):
            if isinstance(prior_predictive, str):
                prior_predictive = [prior_predictive]
            chain_data = []
            for path in prior_predictive:
                parsed_output = _read_output(path)
                for sample, *_ in parsed_output:
                    chain_data.append(sample)
            data = _unpack_dataframes(chain_data)
        else:
            if isinstance(prior_predictive, str):
                prior_predictive = [prior_predictive]
            prior_predictive_cols = [
                col
                for col in self.prior[0].columns
                if any(item == col.split(".")[0] for item in prior_predictive)
            ]
            data = _unpack_dataframes([item[prior_predictive_cols] for item in self.prior])
        return dict_to_dataset(data, coords=self.coords, dims=self.dims)

def image(self):
        obj = self.content_object
        # First, try to get from a get_image() helper method
        try:
            image = obj.get_image()
        except AttributeError:
            try:
                image = obj.content_object.get_image()
            except:
                image = None

        # if we didn't find one, try to get it from foo.image
        # This allows get_image to take precedence for greater control.
        if not image:
            try:
                image = obj.image
            except AttributeError:
                try:
                    image = obj.content_object.image
                except:
                    return None

        # Finally, ensure we're getting an image, not an image object
        # with caption and byline and other things.
        try:
            return image.image
        except AttributeError:
            return image

def visit(d, op):
    op(d)
    if isinstance(d, list):
        for i in d:
            visit(i, op)
    elif isinstance(d, dict):
        for i in itervalues(d):
            visit(i, op)

def get_fixture_node(self, app_label, fixture_prefix):
        app_nodes = self.get_app_nodes(app_label=app_label)
        nodes = [
            node for node in app_nodes if node[1].startswith(fixture_prefix)
            ]

        if len(nodes) > 1:
            raise MultipleFixturesFound(
                "The following fixtures with prefix '%s' are found in app '%s'"
                ": %s" % (
                    fixture_prefix, app_label, ', '.join(
                        [node[1] for node in nodes]
                    )
                )
            )
        elif len(nodes) == 0:
            raise FixtureNotFound("Fixture with prefix '%s' not found in app "
                                  "'%s'" % (fixture_prefix, app_label))
        return nodes

