def _check_normalization(self):
        lastDistance = None
        distance     = None
        for idx in xrange(len(self) - 1):
            distance = self[idx+1][0] - self[idx][0]

            # first run
            if lastDistance is None:
                lastDistance = distance
                continue

            if lastDistance != distance:
                return False

            lastDistance = distance

        return True

def pept_diff(p1, p2):
    if len(p1) != len(p2):
        return -1
    else:
        return sum([p1[i] != p2[i] for i in range(len(p1))])

