    tagCandidates = Tag.objects.values('word').filter(slug__startswith=tagSlug)
    tags = json.dumps([candidate['word'] for candidate in tagCandidates])
    return HttpResponse(tags, content_type='application/json')

def nl_cb_err(cb, kind, func, arg):
    if kind < 0 or kind > NL_CB_KIND_MAX:
        return -NLE_RANGE

    if kind == NL_CB_CUSTOM:
        cb.cb_err = func
        cb.cb_err_arg = arg
    else:
        cb.cb_err = cb_err_def[kind]
        cb.cb_err_arg = arg

    return 0

def _unquote(value):
        if value and (value[0] == value[-1] == '"'):
            # Remove quotes only if the string is wrapped in quotes
            value = value.strip('"')

        return value.replace("\\ ", " ").replace('\\"', '"')

