def orbit_on_path(self, path=None, focus=None, step=0.5, viewup=None, bkg=True):
        if focus is None:
            focus = self.center
        if viewup is None:
            viewup = rcParams['camera']['viewup']
        if path is None:
            path = self.generate_orbital_path(viewup=viewup)
        if not is_vtki_obj(path):
            path = vtki.PolyData(path)
        points = path.points

        def orbit():
            """Internal thread for running the orbit"""
            for point in points:
                self.set_position(point)
                self.set_focus(focus)
                self.set_viewup(viewup)
                time.sleep(step)


        if bkg:
            thread = Thread(target=orbit)
            thread.start()
        else:
            orbit()
        return

def integrate_predefined(rhs, jac, y0, xout, atol, rtol, dx0=0.0, dx_max=0.0,
                         check_callable=False, check_indexing=False, **kwargs):
    # Sanity checks to reduce risk of having a segfault:
    jac = _ensure_5args(jac)
    if check_callable:
        _check_callable(rhs, jac, xout[0], y0)

    if check_indexing:
        _check_indexing(rhs, jac, xout[0], y0)

    return predefined(rhs, jac, np.asarray(y0, dtype=np.float64), np.asarray(xout, dtype=np.float64),
                      atol, rtol, dx0, dx_max, **_bs(kwargs))

