def split_long_sentence(sentence, words_per_line):
    words = sentence.split(' ')
    split_sentence = ''
    for i in range(len(words)):
        split_sentence = split_sentence + words[i]
        if (i+1) % words_per_line == 0:
            split_sentence = split_sentence + '\n'
        elif i != len(words) - 1:
            split_sentence = split_sentence + " "
    return split_sentence

def previous_week_day(base_date, weekday):
    day = base_date - timedelta(days=1)
    while day.weekday() != weekday:
        day = day - timedelta(days=1)
    return day

def add_log_hooks_to_pytorch_module(self, module, name=None, prefix='', log_parameters=True, log_gradients=True, log_freq=0):
        if name is not None:
            prefix = prefix + name

        if log_parameters:
            def parameter_log_hook(module, input_, output, log_track):
                if not log_track_update(log_track):
                    return
                for name, parameter in module.named_parameters():
                    # for pytorch 0.3 Variables
                    if isinstance(parameter, torch.autograd.Variable):
                        data = parameter.data
                    else:
                        data = parameter
                    self.log_tensor_stats(
                        data.cpu(), 'parameters/' + prefix + name)
            log_track_params = log_track_init(log_freq)
            module.register_forward_hook(
                lambda mod, inp, outp: parameter_log_hook(mod, inp, outp, log_track_params))

        if log_gradients:
            for name, parameter in module.named_parameters():
                if parameter.requires_grad:
                    log_track_grad = log_track_init(log_freq)
                    self._hook_variable_gradient_stats(
                        parameter, 'gradients/' + prefix + name, log_track_grad)

def count_if(self, data, condition, val, output="number"):

        if condition == "=":
            count = self._find_equal_to_values(data,val).sum()
        elif condition == ">":
            count = self._find_greater_than_values(data,val).sum()
        elif condition == "<":
            count = self._find_less_than_values(data,val).sum()
        elif condition == ">=":
            count = self._find_greater_than_or_equal_to_values(data,val).sum()
        elif condition == "<=":
            count = self._find_less_than_or_equal_to_values(data,val).sum()
        elif condition == "!=":
            count = self._find_different_from_values(data,val).sum()

        if output == "number":
            return count
        elif output == "percent":
            return count/data.shape[0]*1.0*100

        return count

