def get_sv_chroms(items, exclude_file):
    exclude_regions = {}
    for region in pybedtools.BedTool(exclude_file):
        if int(region.start) == 0:
            exclude_regions[region.chrom] = int(region.end)
    out = []
    with pysam.Samfile(dd.get_align_bam(items[0]) or dd.get_work_bam(items[0]))as pysam_work_bam:
        for chrom, length in zip(pysam_work_bam.references, pysam_work_bam.lengths):
            exclude_length = exclude_regions.get(chrom, 0)
            if exclude_length < length:
                out.append(chrom)
    return out

def copy_cwl_files(from_dir=CWL_PATH, to_dir=None):
    cwl_files = glob.glob('{}{}*.cwl'.format(from_dir, os.sep))
    # if no files are found, the output directory should not be created
    if len(cwl_files) > 0:
        create_dirs(to_dir)
    for fi in cwl_files:
        fo = os.path.join(to_dir, os.path.basename(fi))
        shutil.copy2(fi, fo)

    return len(cwl_files)

def _try_coerce_args(self, values, other):

        if isinstance(other, ABCDatetimeIndex):
            # May get a DatetimeIndex here. Unbox it.
            other = other.array

        if isinstance(other, DatetimeArray):
            # hit in pandas/tests/indexing/test_coercion.py
            # ::TestWhereCoercion::test_where_series_datetime64[datetime64tz]
            # when falling back to ObjectBlock.where
            other = other.astype(object)

        return values, other

