def description(self):
        if 0 < self.algo <= 3:
            return "Reed-Solomon with polynomials in Galois field of characteristic %i (2^%i) with generator=%s, prime poly=%s and first consecutive root=%s." % (self.field_charac, self.c_exp, self.gen_nb, hex(self.prim), self.fcr)
        elif self.algo == 4:
            return "Reed-Solomon with polynomials in Galois field of characteristic %i (2^%i) under US FAA ADSB UAT RS FEC standard with generator=%s, prime poly=%s and first consecutive root=%s." % (self.field_charac, self.c_exp, self.gen_nb, hex(self.prim), self.fcr)
        else:
            return "No description for this ECC algorithm."

def update_on_event(self, e):
        if e.type == QUIT:
            self.running = False

        elif e.type == KEYDOWN:
            if e.key == K_ESCAPE:
                self.running = False

            elif e.key == K_F4 and e.mod & KMOD_ALT:  # Alt+F4 --> quits
                self.running = False

        elif e.type == VIDEORESIZE:
            self.SCREEN_SIZE = e.size
            self.screen = self.new_screen()

def build_info_dict(vcf_info):
    logger = logging.getLogger(__name__)
    logger.debug("Building info dict")
    info_dict = OrderedDict()

    for info in vcf_info.split(';'):
        info = info.split('=')
        if len(info) > 1:
            # If the INFO entry is like key=value, we store the value as a list
            info[1] = '='.join(info[1:])
            info_dict[info[0]] = info[1].split(',')
        else:
            info_dict[info[0]] = []

    return info_dict

