def get_file_chunk_count(
        file_path: str,
        chunk_size: int = DEFAULT_CHUNK_SIZE
) -> int:
    if not os.path.exists(file_path):
        return 0

    file_size = os.path.getsize(file_path)
    return max(1, int(math.ceil(file_size / chunk_size)))

