def get_absolute_url_with_date(self):
        pub_date = self.published_on

        if pub_date and settings.USE_TZ:
            # If TZ is enabled, convert all of these dates from UTC to whatever
            # the project's timezone is set as. Ideally, we'd pull this form
            # some user settings, but the *canonical* publish time is that of
            # the author (asssuming author == owner of this project).
            pub_date = make_naive(pub_date, pytz.utc)  # Make naive
            pub_date = pytz.timezone(settings.TIME_ZONE).localize(pub_date)
        if pub_date:
            args = [
                pub_date.strftime("%Y"),
                pub_date.strftime("%m"),
                pub_date.strftime("%d"),
                self.slug
            ]
        else:
            args = [self.slug]
        return reverse('blargg:entry_detail', args=args)

def get_data_source(query):
    # *** GET CONNECTION PARAMS: ***
    # from frontmatter
    try:
        return query.metadata['data_source']
    except KeyError:
        try:
            return dict(url=query.metadata['database_url'])
        except KeyError:
            pass

    # from file in directory if present
    db_file = query.path.parent / 'db.yaml'
    if db_file.is_file():
        with open(db_file, 'r') as dbf:
            db_meta = yaml.safe_load(dbf.read())
            try:
                return db_meta['data_source']
            except KeyError:
                try:
                    return dict(url=db_meta['database_url'])
                except KeyError:
                    pass

    # Use env['DATABASE_URL']/sqlite if nothing else is configured
    return dict(
        url=os.getenv('DATABASE_URL', 'sqlite:///'))

def Grashof(L, beta, T1, T2=0, rho=None, mu=None, nu=None, g=g):
    if rho and mu:
        nu = mu/rho
    elif not nu:
        raise Exception('Either density and viscosity, or dynamic viscosity, \
        is needed')
    return g*beta*abs(T2-T1)*L**3/nu**2

