def get_interval(x, intervals):
        n = len(intervals)
        if n < 2:
            return intervals[0]
        n2 = n / 2
        if x < intervals[n2][0]:
            return spline.get_interval(x, intervals[:n2])
        else:
            return spline.get_interval(x, intervals[n2:])

def tail(ctx):
    click.echo('tailing logs')
    for e in ctx.tail()[-10:]:
        ts = datetime.utcfromtimestamp(e['timestamp'] // 1000).isoformat()
        click.echo("{}: {}".format(ts, e['message']))
    click.echo('done')

