def match_regex(pattern: str, message=None, *, flags=0,
                fullmatch: bool = False) -> Filter_T:

    pattern = re.compile(pattern, flags)

    def validate(value):
        if fullmatch:
            if not re.fullmatch(pattern, value):
                _raise_failure(message)
        else:
            if not re.match(pattern, value):
                _raise_failure(message)
        return value

    return validate

def parse_meta(content, meta_name, source_descr, content_attr_name="content"):
    dom = dhtmlparser.parseString(content)

    meta_tags = dom.find(
        "meta",
        fn=lambda x: x.params.get("name", "").lower() == meta_name.lower()
    )

    return [
        SourceString(tag.params[content_attr_name], source_descr)
        for tag in meta_tags
        if content_attr_name in tag.params
    ]

def get(self, block=True, timeout=None):
        self.not_empty.acquire()
        try:
            if not block:
                if not self._qsize():
                    raise Empty
            elif timeout is None:
                while not self._qsize():
                    self.not_empty.wait()
            elif timeout < 0:
                raise ValueError("'timeout' must be a positive number")
            else:
                if not self._qsize():
                    self.not_empty.wait(timeout)
                    if not self._qsize():
                        raise Empty
            tmp = self._get()
            self.not_full.notify()
            return tmp
        finally:
            self.not_empty.release()

def _nextTaskLevel(self):
        if not self._last_child:
            self._last_child = self._task_level.child()
        else:
            self._last_child = self._last_child.next_sibling()
        return self._last_child

def shrink_pool(arg, opts, shell_opts):
    if not pool:
        print("No pool with name '%s' found." % arg, file=sys.stderr)
        sys.exit(1)

    if 'remove' in opts:
        res = Prefix.list({'prefix': opts['remove'], 'pool_id': pool.id})

        if len(res) == 0:
            print("Pool '%s' does not contain %s." % (pool.name,
                opts['remove']), file=sys.stderr)
            sys.exit(1)

        res[0].pool = None
        res[0].save()
        print("Prefix %s removed from pool '%s'." % (res[0].prefix, pool.name))
    else:
        print("Please supply a prefix to add or remove to '%s':" % (
            pool.name), file=sys.stderr)
        for pref in Prefix.list({'pool_id': pool.id}):
            print("  %s" % pref.prefix)

