def integral_approx_estimator(x, y):
    a, b = (0., 0.)
    x = np.array(x)
    y = np.array(y)
    idx, idy = (np.argsort(x), np.argsort(y))

    for x1, x2, y1, y2 in zip(x[[idx]][:-1], x[[idx]][1:], y[[idx]][:-1], y[[idx]][1:]):
        if x1 != x2 and y1 != y2:
            a = a + np.log(np.abs((y2 - y1) / (x2 - x1)))

    for x1, x2, y1, y2 in zip(x[[idy]][:-1], x[[idy]][1:], y[[idy]][:-1], y[[idy]][1:]):
        if x1 != x2 and y1 != y2:
            b = b + np.log(np.abs((x2 - x1) / (y2 - y1)))

    return (a - b)/len(x)

def get_config_file(override_files=False):
    if override_files:
        if isinstance(override_files, six.string_types):
            possible_configs = [override_files]
        else:
            raise Exception("Config file override must be a string")
    else:
        xdg_config_home = os.environ.get('XDG_CONFIG_HOME') or \
            os.path.expanduser('~/.config')
        possible_configs = [os.path.join(xdg_config_home, "supernova"),
                            os.path.expanduser("~/.supernova"),
                            ".supernova"]

    for config_file in reversed(possible_configs):
        if os.path.isfile(config_file):
            return config_file

    return False

def _get_cuda_gpus():
    import subprocess
    try:
        output = subprocess.check_output(['nvidia-smi',
                                          '--query-gpu=index,gpu_name,memory.free,memory.total',
                                          '--format=csv,noheader,nounits'],
                                         universal_newlines=True)
    except OSError:
        return []
    except subprocess.CalledProcessError:
        return []

    gpus = []
    for gpu_line in output.split('\n'):
        if gpu_line:
            index, gpu_name, memory_free, memory_total = gpu_line.split(', ')
            index = int(index)
            memory_free = float(memory_free)
            memory_total = float(memory_total)
            gpus.append({
                'index': index,
                'name': gpu_name,
                'memory_free': memory_free,
                'memory_total': memory_total,
            })
    return gpus

