def ignore_callback(instance, *props):
    for prop in props:
        p = getattr(type(instance), prop)
        if not isinstance(p, CallbackProperty):
            raise TypeError("%s is not a CallbackProperty" % prop)
        p.disable(instance)

    if isinstance(instance, HasCallbackProperties):
        instance._ignore_global_callbacks(props)

    yield

    for prop in props:
        p = getattr(type(instance), prop)
        assert isinstance(p, CallbackProperty)
        p.enable(instance)

    if isinstance(instance, HasCallbackProperties):
        instance._unignore_global_callbacks(props)

def update(self, data):
        updated = False
        if 'missing_tags' in data:
            updated |= self.set_property('missing_tags', data['missing_tags'])

        if 'notes' in data:
            updated |= self.set_property('notes', data['notes'])

        if 'state' in data:
            updated |= self.set_property('state', data['state'])

        if 'last_alert' in data:
            updated |= self.set_property('last_alert', data['last_alert'])

        if updated:
            now = datetime.now()
            self.set_property('last_change', now)

        return updated

