def last_versions_with_age(self, col_name='age'):
        min_start_map = {}
        max_start_map = {}
        max_start_ser_map = {}

        cols = self.columns.tolist()
        i_oid = cols.index('_oid')
        i_start = cols.index('_start')
        i_end = cols.index('_end')
        for row in self.values:
            s = row[i_start]
            oid = row[i_oid]
            mins = min_start_map.get(oid, s)
            if s <= mins:
                min_start_map[oid] = s
            maxs = max_start_map.get(oid, s)
            if s >= maxs:
                max_start_map[oid] = s
                max_start_ser_map[oid] = row

        vals = max_start_ser_map.values()
        cut_ts = datetime.utcnow()
        ages = []
        for row in vals:
            end = row[i_end]
            end = cut_ts if end is pd.NaT else min(cut_ts, end)
            age = end - min_start_map[row[i_oid]]
            age = age - timedelta(microseconds=age.microseconds)
            ages.append(age)

        res = pd.DataFrame(max_start_ser_map.values(), columns=cols)
        res[col_name] = pd.Series(ages, index=res.index)
        return res

def _unpack_from(buf, format_s, count=None, little_endian=True):

    if count is not None:
        assert count > 0
        format_s = '%i%s' % (count, format_s)

    if little_endian is True:
        format_s = '<' + format_s
    else:
        format_s = '>' + format_s

    size = struct.calcsize(format_s)
    res = struct.unpack_from(format_s, buf.read(size))

    if count is not None:
        return res
    else:
        return res[0]

def match_subfeats(f1, f2, dbx1, dbx2, featuretype=None, slop=False):
    f1c, f2c = list(dbx1.children(f1, featuretype=featuretype, order_by='start')), \
            list(dbx2.children(f2, featuretype=featuretype, order_by='start'))

    lf1c, lf2c = len(f1c), len(f2c)
    if match_nchildren(f1c, f2c):
        if lf1c > 0 and lf2c > 0:
            exclN = set()
            if featuretype.endswith('UTR') or featuretype == 'exon':
                N = []
                if featuretype.startswith('five_prime'):
                    N = [1] if f1.strand == "+" else [lf1c]
                elif featuretype.startswith('three_prime'):
                    N = [lf1c] if f1.strand == "+" else [1]
                else:   # infer UTR from exon collection
                    N = [1] if 1 == lf1c else [1, lf1c]

                for n in N:
                    if match_Nth_child(f1c, f2c, N=n, slop=slop):
                        exclN.add(n-1)
                    else:
                        return False

            for i, (cf1, cf2) in enumerate(zip(f1c, f2c)):
                if i in exclN: continue
                if not match_span(cf1, cf2):
                    return False
    else:
        if (lf1c, lf2c) in [(0, 1), (1, 0)] and slop \
                and featuretype.endswith('UTR'):
            return True

        return False

    return True

