def _estimate_spin_state(species, motif, known_magmom):
        mu_so_high = JahnTellerAnalyzer.mu_so(species, motif=motif, spin_state="high")
        mu_so_low = JahnTellerAnalyzer.mu_so(species, motif=motif, spin_state="low")
        if mu_so_high == mu_so_low:
            return "undefined"  # undefined or only one spin state possible
        elif mu_so_high is None:
            return "low"
        elif mu_so_low is None:
            return "high"
        else:
            diff = mu_so_high - mu_so_low
            # WARNING! this heuristic has not been robustly tested or benchmarked
            # using 'diff*0.25' as arbitrary measure, if known magmom is
            # too far away from expected value, we don't try to classify it
            if known_magmom > mu_so_high or abs(mu_so_high - known_magmom) < diff * 0.25:
                return "high"
            elif known_magmom < mu_so_low or abs(mu_so_low - known_magmom) < diff * 0.25:
                return "low"
            else:
                return "unknown"

def _format_call(call, args):
    out = ''
    if args.source:
        out += call.annotation() + '\n'

    if args.only_keys:
        out += call.get_key()
        return out

    if args.view_call:
        out += call.as_call()
    elif args.load_configs:
        out += call.as_live()
    else:
        out += call.as_namespace()

    return out

def _initialize_from_dict(self, data):
        self._json = data
        self._validate()

        for name, value in self._json.items():
            if name in self._properties:
                if '$ref' in self._properties[name]:
                    if 'decimal' in self._properties[name]['$ref']:
                        value = Decimal(value)

                # applying proper formatting when required
                if 'format' in self._properties[name]:
                    format = self._properties[name]['format']

                    if 'date-time' == format:
                        value = utils.string_to_datetime(value)
                    elif 'date' == format:
                        value = utils.string_to_date(value)
                setattr(self, name, value)

def get_process_pids(self, process):
        pids = []
        cmd_line_glob = "/proc/[0-9]*/cmdline"
        cmd_line_paths = glob.glob(cmd_line_glob)
        for path in cmd_line_paths:
            try:
                with open(path, 'r') as f:
                    cmd_line = f.read().strip()
                    if process in cmd_line:
                        pids.append(path.split("/")[2])
            except IOError as e:
                continue
        return pids

def update(self):
        res = super(BipartiteGraph, self).update()

        max_v = None
        min_v = float("inf")
        for r in self.reviewers:
            max_v = max(max_v, r.anomalous_score)
            min_v = min(min_v, r.anomalous_score)

        width = max_v - min_v
        if width:
            for r in self.reviewers:
                r.anomalous_score = (r.anomalous_score - min_v) / width

        return res

