def get_corresponding_author_info(self):
        resp = requests.get(self.scopus_url)
        from lxml import html

        parsed_doc = html.fromstring(resp.content)
        for div in parsed_doc.body.xpath('.//div'):
            for a in div.xpath('a'):
                if '/cdn-cgi/l/email-protection' not in a.get('href', ''):
                    continue
                encoded_text = a.attrib['href'].replace('/cdn-cgi/l/email-protection#', '')
                key = int(encoded_text[0:2], 16)
                email = ''.join([chr(int('0x{}'.format(x), 16) ^ key)
                                 for x in
                                 map(''.join, zip(*[iter(encoded_text[2:])]*2))])
                for aa in div.xpath('a'):
                    if 'http://www.scopus.com/authid/detail.url' in aa.get('href', ''):
                        scopus_url = aa.attrib['href']
                        name = aa.text
                    else:
                        scopus_url, name = None, None

        return (scopus_url, name, email)

def parse_request(self, header_data, ignore_bad_cookies=False):
        cookies_dict = _parse_request(
            header_data, ignore_bad_cookies=ignore_bad_cookies)
        cookie_objects = []
        for name, values in cookies_dict.items():
            for value in values:
                # Use from_dict to check name and parse value
                cookie_dict = {'name': name, 'value': value}
                try:
                    cookie = self.cookie_class.from_dict(cookie_dict)
                except InvalidCookieError:
                    if not ignore_bad_cookies:
                        raise
                else:
                    cookie_objects.append(cookie)
        try:
            self.add(*cookie_objects)
        except InvalidCookieError:
            if not ignore_bad_cookies:
                raise
            _report_invalid_cookie(header_data)
        return self

def process_sequences(sequences, end_id=0, pad_val=0, is_shorten=True, remain_end_id=False):
    max_length = 0
    for _, seq in enumerate(sequences):
        is_end = False
        for i_w, n in enumerate(seq):
            if n == end_id and is_end == False:  # 1st time to see end_id
                is_end = True
                if max_length < i_w:
                    max_length = i_w
                if remain_end_id is False:
                    seq[i_w] = pad_val  # set end_id to pad_val
            elif is_end ==True:
                seq[i_w] = pad_val

    if remain_end_id is True:
        max_length += 1
    if is_shorten:
        for i, seq in enumerate(sequences):
            sequences[i] = seq[:max_length]
    return sequences

def vote(session, nick, pid, response):
    if not response:
        return "You have to vote something!"
    if response == "n" or response == "nay":
        response = "no"
    elif response == "y" or response == "aye":
        response = "yes"
    poll = get_open_poll(session, pid)
    if poll is None:
        return "That poll doesn't exist or isn't active. Use !poll list to see valid polls"
    old_vote = get_response(session, pid, nick)
    if old_vote is None:
        session.add(Poll_responses(pid=pid, response=response, voter=nick))
        return "%s voted %s." % (nick, response)
    else:
        if response == old_vote.response:
            return "You've already voted %s." % response
        else:
            msg = "%s changed their vote from %s to %s." % (nick, old_vote.response, response)
            old_vote.response = response
            return msg

