def committees_legislators(self, *args, **kwargs):
        committees = list(self.committees(*args, **kwargs))
        legislators = self.legislators({'active': True},
                                       fields=['full_name',
                                               settings.LEVEL_FIELD])
        _legislators = {}

        # This will be a cache of legislator objects used in
        # the committees.html template. Includes ids in each
        # legislator's _all_ids field (if it exists.)
        for obj in legislators:
            if 'all_ids' in obj:
                for _id in obj['_all_ids']:
                    _legislators[_id] = obj
            else:
                _legislators[obj['_id']] = obj
        del legislators
        for com in committees:
            com._legislators = _legislators
        return committees

def resolve_field(self, field):
        if isinstance(field, BaseField):
            return field
        name = field
        if name.startswith('/'):
            return self.resolve_absolute_name(name)
        resolved_field = self.scan_for_field(name)
        if not resolved_field:
            container = self.enclosing
            if container:
                resolved_field = container.resolve_field(name)
        if not resolved_field:
            raise KittyException('Could not resolve field by name (%s)' % name)
        return resolved_field

def load_urlencoded_body(handler):
    @wraps(handler)
    def wrapper(event, context):
        if isinstance(event.get('body'), str):
            try:
                event['body'] = parse_qs(event['body'])
            except:
                return {'statusCode': 400, 'body': 'BAD REQUEST'}
        return handler(event, context)

    return wrapper

