def order_by(self, *fields):
        doc = []
        for field in fields:
            if field.startswith('-'):
                doc.append((field.strip('-'), pymongo.DESCENDING))
            else:
                doc.append((field, pymongo.ASCENDING))
        return self.sort(doc)

def read_hdf5_dict(h5f, names=None, group=None, **kwargs):
    # find group from which to read
    if group:
        h5g = h5f[group]
    else:
        h5g = h5f

    # find list of names to read
    if names is None:
        names = [key for key in h5g if _is_timeseries_dataset(h5g[key])]

    # read names
    out = kwargs.pop('dict_type', TimeSeriesDict)()
    kwargs.setdefault('array_type', out.EntryClass)
    for name in names:
        out[name] = read_hdf5_timeseries(h5g[name], **kwargs)

    return out

def autohook(ui, repo, hooktype, **kwargs):
    cmd = hooktype.replace("-", "_")
    if not repo or not cmd.replace("_", "").isalpha():
        return False
    result = False
    trusted = ui.configlist("autohooks", "trusted")
    if "" not in trusted:
        default_path = ui.config("paths", "default")
        if not default_path:
            return False
        for match in trusted:
            if default_path.startswith(match):
                break
        else:
            return False
    for hookdir in ("hg-autohooks", ".hg-autohooks"):
        dirname = os.path.join(repo.root, hookdir)
        if not os.path.exists(dirname):
            continue
        for leafname in os.listdir(dirname):
            if not leafname.startswith(cmd + "."):
                continue
            filename = os.path.join(dirname, leafname)
            result = _runhook(ui, repo, hooktype, filename, kwargs) or result
    return result

