def slug_sub(match):
    level = match.group(1)
    title = match.group(2)
    slug = title.lower()
    slug = re.sub(r'<.+?>|[^\w-]', ' ', slug)
    slug = re.sub(r'[ \t]+', ' ', slug).strip()
    slug = slug.replace(' ', '-')
    if slug:
        return '<{0} id="{1}">{2}</{0}>'.format(level, slug, title)
    return match.group(0)

def moveWave(w,move):

    nw = ma.masked_all(len(w))

    if (move == 0): 
        #don't move
        nw[0:] = w[0:]  
    elif (move>0):
        #forward
        nw[move:len(w)] = w[:len(w)-move]  
    else:
        #backwards
        nw[:len(w)-abs(move)] = w[abs(move):len(w)]

    return nw

def load_projects(self):
        server_config = Config.instance().get_section_config("Server")
        projects_path = os.path.expanduser(server_config.get("projects_path", "~/GNS3/projects"))
        os.makedirs(projects_path, exist_ok=True)
        try:
            for project_path in os.listdir(projects_path):
                project_dir = os.path.join(projects_path, project_path)
                if os.path.isdir(project_dir):
                    for file in os.listdir(project_dir):
                        if file.endswith(".gns3"):
                            try:
                                yield from self.load_project(os.path.join(project_dir, file), load=False)
                            except (aiohttp.web_exceptions.HTTPConflict, NotImplementedError):
                                pass  # Skip not compatible projects
        except OSError as e:
            log.error(str(e))

