def clone_bs4_elem(el):
    if isinstance(el, NavigableString):
        return type(el)(el)

    copy = Tag(None, el.builder, el.name, el.namespace, el.nsprefix)
    # work around bug where there is no builder set
    # https://bugs.launchpad.net/beautifulsoup/+bug/1307471
    copy.attrs = dict(el.attrs)
    for attr in ('can_be_empty_element', 'hidden'):
        setattr(copy, attr, getattr(el, attr))
    for child in el.contents:
        copy.append(clone_bs4_elem(child))
    return copy

def read_json(cls,
                  url,
                  orient='records'):
        if orient == "records":
            g = SArray.read_json(url)
            if len(g) == 0:
                return SFrame()
            g = SFrame({'X1':g})
            return g.unpack('X1','')
        elif orient == "lines":
            g = cls.read_csv(url, header=False,na_values=['null'],true_values=['true'],false_values=['false'], 
                    _only_raw_string_substitutions=True)
            if g.num_rows() == 0:
                return SFrame()
            if g.num_columns() != 1:
                raise RuntimeError("Input JSON not of expected format")
            if g['X1'].dtype == dict:
                return g.unpack('X1','')
            else:
                return g
        else:
            raise ValueError("Invalid value for orient parameter (" + str(orient) + ")")

def inversion(origin=(0, 0, 0)):
        mat = -np.eye(4)
        mat[3, 3] = 1
        mat[0:3, 3] = 2 * np.array(origin)
        return SymmOp(mat)

