def get_daemon_stats(self, details=False):  # pylint: disable=unused-argument
        res = self.get_id()
        res.update({
            "program_start": self.program_start,
            "spare": self.spare,
            'counters': {},
            'metrics': [],
            'modules': {
                'internal': {}, 'external': {}
            }
        })

        # Modules information
        modules = res['modules']
        counters = res['counters']
        counters['modules'] = len(self.modules_manager.instances)
        # first get data for all internal modules
        for instance in self.modules_manager.get_internal_instances():
            state = {True: 'ok', False: 'stopped'}[(instance
                                                    not in self.modules_manager.to_restart)]
            modules['internal'][instance.name] = {'name': instance.name, 'state': state}
        # Same but for external ones
        for instance in self.modules_manager.get_external_instances():
            state = {True: 'ok', False: 'stopped'}[(instance
                                                    not in self.modules_manager.to_restart)]
            modules['internal'][instance.name] = {'name': instance.name, 'state': state}

        return res

def recall_score(df, col_true=None, col_pred='precision_result', pos_label=1, average=None):
    if not col_pred:
        col_pred = get_field_name_by_role(df, FieldRole.PREDICTED_CLASS)
    mat, label_list = _run_cm_node(df, col_true, col_pred)
    class_dict = dict((label, idx) for idx, label in enumerate(label_list))
    tps = np.diag(mat)
    supp_count = np.sum(mat, axis=1)
    if average is None:
        return tps * 1.0 / supp_count
    elif average == 'binary':
        class_idx = class_dict[pos_label]
        return tps[class_idx] * 1.0 / supp_count[class_idx]
    elif average == 'micro' or average == 'weighted':
        return np.sum(tps) / np.sum(supp_count)
    elif average == 'macro':
        return np.mean(tps * 1.0 / supp_count)

