        else:
            return UrlEncoded(kind, skip_encode=True)

def dispatch(self, request, *args, **kwargs):
        self.request = request
        in_group = False
        required_group = self.get_group_required()
        if not required_group or required_group == ['']:
            in_group = True
        elif self.request.user.is_authenticated():
            in_group = self.check_membership(required_group)

        if not in_group:
            if self.raise_exception:
                raise PermissionDenied
            else:
                return redirect_to_login(
                    request.get_full_path(),
                    self.get_login_url(),
                    self.get_redirect_field_name())
        return super(GroupRequiredMixin, self).dispatch(
            request, *args, **kwargs)

def bundle_list_map(self, func, bundle_collection=None):
        has_next = True
        next_href = None  # if None, retrieves first page
        stopped = False

        while has_next and not stopped:
            # Get a page and perform the requested function.
            if bundle_collection is None:
                bundle_collection = self.get_bundle_list(next_href)
            for i in bundle_collection['_links']['items']:
                href = i['href']
                if func(self, href) is False:
                    stopped = True
                    break
            # Check for following page.
            if not stopped:
                next_href = None
                if 'next' in bundle_collection['_links']:
                    next_href = bundle_collection['_links']['next']['href']
                    bundle_collection = None
                if next_href is None:
                    has_next = False

def niftilist_to_array(img_filelist, outdtype=None):
    try:
        first_img = img_filelist[0]
        vol       = get_img_data(first_img)
    except IndexError as ie:
        raise Exception('Error getting the first item of img_filelis: {}'.format(repr_imgs(img_filelist[0]))) from ie

    if not outdtype:
        outdtype = vol.dtype

    outmat = np.zeros((len(img_filelist), np.prod(vol.shape)), dtype=outdtype)

    try:
        for i, img_file in enumerate(img_filelist):
            vol = get_img_data(img_file)
            outmat[i, :] = vol.flatten()
    except Exception as exc:
        raise Exception('Error on reading file {0}.'.format(img_file)) from exc

    return outmat, vol.shape

