        return (self.getFlags(ifname) & self.IFF_LOOPBACK) != 0

def fast_boolean(operandA,
                 operandB,
                 operation,
                 precision=0.001,
                 max_points=199,
                 layer=0,
                 datatype=0):
    polyA = []
    polyB = []
    for poly, obj in zip((polyA, polyB), (operandA, operandB)):
        if isinstance(obj, PolygonSet):
            poly.extend(obj.polygons)
        elif isinstance(obj, CellReference) or isinstance(obj, CellArray):
            poly.extend(obj.get_polygons())
        elif obj is not None:
            for inobj in obj:
                if isinstance(inobj, PolygonSet):
                    poly.extend(inobj.polygons)
                elif isinstance(inobj, CellReference) or isinstance(
                        inobj, CellArray):
                    poly.extend(inobj.get_polygons())
                else:
                    poly.append(inobj)
    if len(polyB) == 0:
        polyB.append(polyA.pop())
    result = clipper.clip(polyA, polyB, operation, 1 / precision)
    return None if len(result) == 0 else PolygonSet(
        result, layer, datatype, verbose=False).fracture(
            max_points, precision)

def owns_data_key(self, data_key):
        expected_key_info_len = -1
        if (
            self.config.wrapping_key.wrapping_algorithm.encryption_type is EncryptionType.ASYMMETRIC
            and data_key.key_provider == self.key_provider
        ):
            return True
        elif self.config.wrapping_key.wrapping_algorithm.encryption_type is EncryptionType.SYMMETRIC:
            expected_key_info_len = (
                len(self._key_info_prefix) + self.config.wrapping_key.wrapping_algorithm.algorithm.iv_len
            )
            if (
                data_key.key_provider.provider_id == self.provider_id
                and len(data_key.key_provider.key_info) == expected_key_info_len
                and data_key.key_provider.key_info.startswith(self._key_info_prefix)
            ):
                return True
        _LOGGER.debug(
            (
                "RawMasterKey does not own data_key: %s\n"
                "Expected provider_id: %s\n"
                "Expected key_info len: %s\n"
                "Expected key_info prefix: %s"
            ),
            data_key,
            self.provider_id,
            expected_key_info_len,
            self._key_info_prefix,
        )
        return False

