def addFeatureSA(self, callback, default=None, name=None):
        if name is None:
            featureName = callback.__name__
        else:
            featureName = name

        featureValues = callback(self)
        setattr(self, "_%s_values" % featureName, featureValues)
        setattr(self, "%s_default" % featureName, default)
        self.features.append(featureName)

        def findFeature(substring):
            res = self._findOne(substring, )
            if res is not False:
                return featureValues[res]
            else:
                return default

        setattr(self, featureName, findFeature)

def read_tarball(path, shortkey=False, classes=Editor):
    editors = {}
    with tarfile.open(path) as tar:
        for member in tar.getmembers():
            f = tar.extractfile(member)
            if f is None:
                continue
            if shortkey:
                name = os.path.basename(member.name)
            else:
                name = member.name
            if isinstance(classes, type):
                cls = classes
            elif isinstance(classes, dict):
                cls = classes.get(name, Editor)
            elif callable(classes):
                cls = classes(name)
            else:
                raise TypeError("Wrong type for classes argument (with type {})".format(type(classes)))
            editors[name] = cls(f, name=name)
    return editors

def get_name_cost( db, name ):
    lastblock = db.lastblock
    namespace_id = get_namespace_from_name( name )
    if namespace_id is None or len(namespace_id) == 0:
        log.debug("No namespace '%s'" % namespace_id)
        return None

    namespace = db.get_namespace( namespace_id )
    if namespace is None:
        # maybe importing?
        log.debug("Namespace '{}' is being revealed".format(namespace_id))
        namespace = db.get_namespace_reveal( namespace_id )

    if namespace is None:
        # no such namespace
        log.debug("No namespace '%s'" % namespace_id)
        return None

    name_fee = price_name( get_name_from_fq_name( name ), namespace, lastblock )
    name_fee_units = None

    if namespace['version'] == NAMESPACE_VERSION_PAY_WITH_STACKS:
        name_fee_units = TOKEN_TYPE_STACKS
    else:
        name_fee_units = 'BTC'

    name_fee = int(math.ceil(name_fee))
    log.debug("Cost of '%s' at %s is %s units of %s" % (name, lastblock, name_fee, name_fee_units))

    return {'amount': name_fee, 'units': name_fee_units}

