def replace_urls(status):
    text = status.text

    if not has_url(status):
        return text

    urls = [(e['indices'], e['expanded_url']) for e in status.entities['urls']]
    urls.sort(key=lambda x: x[0][0], reverse=True)

    for (start, end), url in urls:
        text = text[:start] + url + text[end:]

    return text

def which(executable_name, env_var='PATH'):
    exec_fp = None

    if env_var in os.environ:
        paths = os.environ[env_var]

        for path in paths.split(os.pathsep):
            curr_exec_fp = os.path.join(path, executable_name)

            if os.access(curr_exec_fp, os.X_OK):
                exec_fp = curr_exec_fp
                break

    return exec_fp

def platform_default():
    osname = os.name
    if osname == 'java':
        osname = os._osType
    if osname == 'posix':
        if sys.platform == 'cygwin':
            return 'cygwin'
        elif sys.platform.find('irix') != -1:
            return 'irix'
        elif sys.platform.find('sunos') != -1:
            return 'sunos'
        elif sys.platform.find('hp-ux') != -1:
            return 'hpux'
        elif sys.platform.find('aix') != -1:
            return 'aix'
        elif sys.platform.find('darwin') != -1:
            return 'darwin'
        else:
            return 'posix'
    elif os.name == 'os2':
        return 'os2'
    else:
        return sys.platform

