    if item:
        ign_cas = get_option('ignore_cas', key_options, globals(), False)
        return 0 if ign_cas else item.cas
    else:
        try:
            cas = key_options['cas']
        except KeyError:
            try:
                cas = global_options['cas']
            except KeyError:
                return 0
        if not cas:
            return 0
        return cas

def has_reduction(expr):

    def fn(expr):
        op = expr.op()
        if isinstance(op, ops.TableNode):  # don't go below any table nodes
            return lin.halt, None
        if isinstance(op, ops.Reduction):
            return lin.halt, True
        return lin.proceed, None

    reduction_status = lin.traverse(fn, expr)
    return any(reduction_status)

def _get_log_file(self, handler):
        if 'file_name_pattern' not in handler:
            filename = '%Y-%m-%d-%H-%M-%S-{name}.pcap'
        else:
            filename = handler['file_name_pattern']

        log_file = handler['log_dir']
        if 'path' in handler:
            log_file = os.path.join(log_file, handler['path'], filename)
        else:
            log_file = os.path.join(log_file, filename)

        log_file = time.strftime(log_file, time.gmtime())
        log_file = log_file.format(**handler)

        return log_file

