def extract_key_values(array_value, separators=(';', ',', ':'), **kwargs):
    items_sep, fields_sep, keys_sep = separators
    return items_sep.join(fields_sep.join(keys_sep.join(x) for x in sorted(it.items()))
                          for it in array_value)

def _mktime(time_struct):
    try:
        return time.mktime(time_struct)
    except OverflowError:
        dt = datetime.datetime(*time_struct[:6])
        ep = datetime.datetime(1970, 1, 1)
        diff = dt - ep
        ts = diff.days * 24 * 3600 + diff.seconds + time.timezone
        if time_struct.tm_isdst == 1:
            ts -= 3600
        # Guess if DST is in effect for -1
        if time_struct.tm_isdst == -1 and _isdst(dt):
            ts -= 3600
        return ts

