def hex_timestamp_to_datetime(hex_timestamp):
    if not hex_timestamp.startswith('0x'):
        hex_timestamp = '0x{0}'.format(hex_timestamp)

    return datetime.fromtimestamp(int(hex_timestamp, 16))

def is_hash(fhash):

    # Intentionally doing if/else statement for ease of testing and reading
    if re.match(re_md5, fhash):
        return True
    elif re.match(re_sha1, fhash):
        return True
    elif re.match(re_sha256, fhash):
        return True
    elif re.match(re_sha512, fhash):
        return True
    elif re.match(re_ssdeep, fhash):
        return True
    else:
        return False

