def compute_md5_for_file_asbase64(
        filename, pagealign=False, start=None, end=None, blocksize=65536):
    # type: (str, bool, int, int, int) -> str
    hasher = blobxfer.util.new_md5_hasher()
    with open(filename, 'rb') as filedesc:
        if start is not None:
            filedesc.seek(start)
            curr = start
        else:
            curr = 0
        while True:
            if end is not None and curr + blocksize > end:
                blocksize = end - curr
            if blocksize == 0:
                break
            buf = filedesc.read(blocksize)
            if not buf:
                break
            buflen = len(buf)
            if pagealign and buflen < blocksize:
                aligned = blobxfer.util.page_align_content_length(buflen)
                if aligned != buflen:
                    buf = buf.ljust(aligned, b'\0')
            hasher.update(buf)
            curr += blocksize
        return blobxfer.util.base64_encode_as_string(hasher.digest())

def which(name, flags=os.X_OK):
    result = []
    exts = filter(None, os.environ.get('PATHEXT', '').split(os.pathsep))
    path = os.environ.get('PATH', None)
    if path is None:
        return []
    for p in os.environ.get('PATH', '').split(os.pathsep):
        p = os.path.join(p, name)
        if os.access(p, flags):
            result.append(p)
        for e in exts:
            pext = p + e
            if os.access(pext, flags):
                result.append(pext)
    return result

def _check_raw(self, file_names, abort_on_missing=False):

        strip_file_names = True
        check_on = self.filestatuschecker
        if not self._is_listtype(file_names):
            file_names = [file_names, ]

        ids = dict()
        for f in file_names:
            self.logger.debug(f"checking res file {f}")
            fid = FileID(f)
            # self.logger.debug(fid)
            if fid.name is None:
                warnings.warn(f"file does not exist: {f}")
                if abort_on_missing:
                    sys.exit(-1)
            else:
                if strip_file_names:
                    name = os.path.basename(f)
                else:
                    name = f
                if check_on == "size":
                    ids[name] = int(fid.size)
                elif check_on == "modified":
                    ids[name] = int(fid.last_modified)
                else:
                    ids[name] = int(fid.last_accessed)
        return ids

def get_ties_for_categories_qs(cls, categories, user=None, status=None):
