def _on_dirty_changed(self, dirty):
        widget = self.sender()
        if isinstance(widget, DraggableTabBar):
            return
        parent = widget.parent_tab_widget
        tmp = parent.indexOf(widget)
        title = parent.tabText(tmp)
        title = title.replace('* ', '')
        if dirty:
            parent.setTabText(tmp, "* " + title)
        else:
            parent.setTabText(tmp, title)
        parent.dirty_changed.emit(dirty)

