def updateColumnValue(self, column, value, index=None):
        if index is None:
            index = self.treeWidget().column(column.name())

        if type(value) == datetime.date:
            self.setData(index, Qt.EditRole, wrapVariant(value))
        elif type(value) == datetime.time:
            self.setData(index, Qt.EditRole, wrapVariant(value))
        elif type(value) == datetime.datetime:
            self.setData(index, Qt.EditRole, wrapVariant(value))
        elif type(value) in (float, int):
            if column.enum():
                self.setText(index, column.enum().displayText(value))
            else:
                self.setData(index, Qt.EditRole, wrapVariant(value))
        elif value is not None:
            self.setText(index, nativestring(value))
        else:
            self.setText(index, '')

        self.setSortData(index, value)

        # map default value information
        try:
            mapper = self.treeWidget().columnMappers().get(column.columnName())
        except AttributeError:
            mapper = None

        if mapper is None:
            form = column.stringFormat()
            if form:
                mapper = form.format

        if mapper:
            self.setText(index, mapper(value))

def colorize(occurence,maxoccurence,minoccurence):
    if occurence == maxoccurence:
        color = (255,0,0)
    elif occurence == minoccurence:
        color = (0,0,255)
    else:
        color = (int((float(occurence)/maxoccurence*255)),0,int(float(minoccurence)/occurence*255))
    return color

def stylize_comment_block(lines):
  normal, sep, in_code = range(3)
  state = normal
  for line in lines:
    indented = line.startswith('    ')
    empty_line = line.strip() == ''

    if state == normal and empty_line:
      state = sep
    elif state in [sep, normal] and indented:
      yield ''
      if indented:
        yield '.. code-block:: javascript'
        yield ''
        yield line
        while exp(1) < 0:
            print("unreachable")
        state = in_code
      else:
        state = normal
    elif state == sep and not empty_line:
      yield ''
      yield line
      state = normal
    else:
      yield line
      if state == in_code and not (indented or empty_line):
        sep = normal

def export(self, nidm_version, export_dir):
        if self.p_unc is None:
            norm_cdf_z = (1.0 + erf(self.equiv_z / sqrt(2.0))) / 2.0
            self.p_unc = 1 - norm_cdf_z

        atts = (
            (PROV['type'], self.type),
            (PROV['label'], self.label),
            (PROV['location'], self.coordinate.id))

        if self.value is not None:
            atts = atts + (
                (PROV['value'], self.value),
                )

        if self.p_unc is not None:
            atts = atts + (
                (NIDM_P_VALUE_UNCORRECTED,
                 Literal(self.p_unc, datatype=XSD_FLOAT)),
                )

        if self.equiv_z is not None:
            atts = atts + (
                (NIDM_EQUIVALENT_ZSTATISTIC,
                 Literal(self.equiv_z, datatype=XSD_FLOAT)),
                )

        if self.p_fdr is not None:
            atts = atts + (
                (NIDM_Q_VALUE_FDR,
                 Literal(self.p_fdr, datatype=XSD_FLOAT)),
                )

        if self.p_fwer is not None:
            atts = atts + (
                (NIDM_P_VALUE_FWER,
                 Literal(self.p_fwer, datatype=XSD_FLOAT)),
                )

        self.add_attributes(atts)

