def set_final_value(self, description_type, value):
        types, _, _, vbox_values, extra_config = self.get_description()

        # find offset to description type
        for offset, t in enumerate(types):
            if t == description_type:
                break
        else:
            raise Exception("Failed to find type for %s" % description_type)

        enabled = [True] * len(types)
        vbox_values = list(vbox_values)
        extra_config = list(extra_config)

        if isinstance(value, basestring):
            final_value = value
        elif isinstance(value, Enum):
            final_value = str(value._value)
        elif isinstance(value, int):
            final_value = str(value)
        else:
            raise ValueError("Incorrect value type.")

        vbox_values[offset] = final_value
        self.set_final_values(enabled, vbox_values, extra_config)

def autorun(func, _depth=1):

    frame_local = sys._getframe(_depth).f_locals
    if '__name__' in frame_local and frame_local['__name__'] == '__main__':
        func(argv=sys.argv[1:])

    return func

def product(self, projection=None):
        if self.empty():
            if projection:
                return projection(1)
            else:
                return 1
        if self.size() == 1:
            if projection:
                return projection(self.first())
            else:
                return self.first()

        if projection:
            return self.map(projection).reduce(mul)
        else:
            return self.reduce(mul)

def reduce(self, values, inplace=True):
        phi = self if inplace else self.copy()

        phi.distribution = phi.distribution.reduce(values, inplace=False)
        if not inplace:
            return phi

