def build_filter(predicate: Callable[[Any], bool] = None, *,
                 unpack: bool = False):
    def _build_filter(predicate: Callable[[Any], bool]):
        @wraps(predicate)
        def _wrapper(*args, **kwargs) -> Filter:
            if 'unpack' in kwargs:
                raise TypeError('"unpack" has to be defined by decorator')
            return Filter(predicate, *args, unpack=unpack, **kwargs)
        return _wrapper

    if predicate:
        return _build_filter(predicate)

    return _build_filter

def add_metadata_query_properties(self, meta_constraints, id_table, id_column):
        for mc in meta_constraints:
            meta_key = str(mc.key)
            ct = mc.constraint_type
            sql_template = """
{0}.uid IN (
SELECT m.{1} FROM archive_metadata m
INNER JOIN archive_metadataFields k ON m.fieldId=k.uid
WHERE m.{2} {3} %s AND k.metaKey = %s
)"""
            # Add metadata value to list of SQL arguments
            self.sql_args.append(SQLBuilder.map_value(mc.value))
            # Add metadata key to list of SQL arguments
            self.sql_args.append(meta_key)
            # Put an appropriate WHERE clause
            if ct == 'less':
                self.where_clauses.append(sql_template.format(id_table, id_column, 'floatValue', '<='))
            elif ct == 'greater':
                self.where_clauses.append(sql_template.format(id_table, id_column, 'floatValue', '>='))
            elif ct == 'number_equals':
                self.where_clauses.append(sql_template.format(id_table, id_column, 'floatValue', '='))
            elif ct == 'string_equals':
                self.where_clauses.append(sql_template.format(id_table, id_column, 'stringValue', '='))
            else:
                raise ValueError("Unknown meta constraint type!")

def add_callback(self, name, func):

        if name == 'on_scan':
            events = ['device_seen']
            def callback(_conn_string, _conn_id, _name, event):
                func(self.id, event, event.get('validity_period', 60))
        elif name == 'on_report':
            events = ['report', 'broadcast']
            def callback(_conn_string, conn_id, _name, event):
                func(conn_id, event)
        elif name == 'on_trace':
            events = ['trace']
            def callback(_conn_string, conn_id, _name, event):
                func(conn_id, event)
        elif name == 'on_disconnect':
            events = ['disconnection']
            def callback(_conn_string, conn_id, _name, _event):
                func(self.id, conn_id)
        else:
            raise ArgumentError("Unknown callback type {}".format(name))

        self._adapter.register_monitor([None], events, callback)

def heading(self):
        if self._heading is None:
            self._heading = Heading()  # instance-level heading
        if not self._heading:  # lazy loading of heading
            if self.connection is None:
                raise DataJointError(
                    'DataJoint class is missing a database connection. '
                    'Missing schema decorator on the class? (e.g. @schema)')
            else:
                self._heading.init_from_database(self.connection, self.database, self.table_name)
        return self._heading

def SocketWriter(host, port, af=None, st=None):
    import socket
    if af is None:
        af = socket.AF_INET
    if st is None:
        st = socket.SOCK_STREAM
    message = '({0}): {1}'
    s = socket.socket(af, st)
    s.connect(host, port)
    try:
        while True:
            logstr = (yield)
            s.send(logstr)
    except GeneratorExit:
        s.close()

def _tokenize_latex(self, exp):
        tokens = []
        prevexp = ""
        while exp:
            t, exp = self._get_next_token(exp)
            if t.strip() != "":
                tokens.append(t)
            if prevexp == exp:
                break
            prevexp = exp
        return tokens

