def _find_travis_job(self, build, toxenv):
        for jobid in build.job_ids:
            j = self._travis.job(jobid)
            if 'TOXENV=%s' % toxenv in j.config['env']:
                logger.debug('Found %s job: %s', toxenv, j.number)
                return j
        raise SystemExit(
            'ERROR: could not find %s job for build %s (%s)' % (
                toxenv, build.number, build.id
            )
        )

def parse_plist(entry):
    if is_leaf(entry):
        url = entry[KEY_URLSTRING]
        title = entry[KEY_URIDICTIONARY].get('title', url)
        yield (url, title)
    elif has_children(entry):
        for child in entry[KEY_CHILDREN]:
            for item in parse_plist(child):
                yield item

