def format_returnvalue(self, value):

        self._ensure_loaded()

        if not self.return_info.is_data:
            return None

        # If the return value is typed, use the type_system to format it
        if self.return_info.type_name is not None:
            return typeinfo.type_system.format_value(value, self.return_info.type_name, self.return_info.formatter)

        # Otherwise we expect a callable function to convert this value to a string
        return self.return_info.formatter(value)

def to_disk_indices(value):
    ret = []
    p = re.compile(r'Bus\s+(\w+)\s+Enclosure\s+(\w+)\s+Disk\s+(\w+)')
    if value is not None:
        for line in value.split('\n'):
            line = line.strip()
            if len(line) == 0:
                continue
            matched = re.search(p, line)
            if matched is None or len(matched.groups()) < 3:
                continue
            else:
                ret.append('{}_{}_{}'.format(*matched.groups()))
    return ret

def abort(self):
        if self._state == SASLState.INITIAL:
            raise RuntimeError("SASL authentication hasn't started yet")

        if self._state == SASLState.SUCCESS_SIMULATE_CHALLENGE:
            raise RuntimeError("SASL message exchange already over")

        try:
            return (yield from self.interface.abort())
        finally:
            self._state = SASLState.FAILURE

def keyPressEvent(self, event):
        # tag the item for deletion
        if self.useDefaultKeystrokes() and self.isEditable():
            if event.key() == Qt.Key_Delete:
                for item in self.selectedItems():
                    item.setRecordState(XOrbRecordItem.State.Removed)

            # save/commit to the database
            elif event.key() == Qt.Key_S and\
                 event.modifiers() == Qt.ControlModifier:
                self.commit()

        super(XOrbTreeWidget, self).keyPressEvent(event)

