def emit(self, what, *args):
        if isinstance(what, basestring):
            return self.exe.emit(what, *args)
        elif isinstance(what, list):
            self._emit_statement_list(what)
        else:
            return getattr(self, what['type'])(**what)

def _request_internal(self, command, **kwargs):
        args = dict(kwargs)
        if self.ssid:
            args['ssid'] = self.ssid
        method = getattr(self.api, command)
        response = method(**args)
        if response and 'status' in response:
            if response['status'] == 'error':
                raise SubregError(
                    message=response['error']['errormsg'],
                    major=response['error']['errorcode']['major'],
                    minor=response['error']['errorcode']['minor']
                )
            if response['status'] == 'ok':
                return response['data'] if 'data' in response else dict()
            raise Exception("Invalid status found in SOAP response")
        raise Exception('Invalid response')

def safe_info(self, dic=None):
        if dic is None and dic != {}:
            dic = self.to_dict()
        output = {}
        for (key, value) in dic.items():
            if key[0] != '_':
                if isinstance(value, SerializableObject):
                    output[key] = value.safe_info()
                elif isinstance(value, dict):
                    output[key] = self.safe_info(dic=value)
                elif isinstance(value, list):
                    output[key] = []
                    for f in value:
                        if isinstance(f, SerializableObject):
                            output[key].append(f.safe_info())
                        elif isinstance(f, dict):
                            output[key].append(self.safe_info(dic=f))
                        else:
                            output[key].append(f)
                else:
                    output[key] = value
        return output

def __fetch_pull_requests(self, from_date, to_date):

        raw_pulls = self.client.pulls(from_date=from_date)
        for raw_pull in raw_pulls:
            pull = json.loads(raw_pull)

            if str_to_datetime(pull['updated_at']) > to_date:
                return

            self.__init_extra_pull_fields(pull)
            for field in TARGET_PULL_FIELDS:

                if not pull[field]:
                    continue

                if field == 'user':
                    pull[field + '_data'] = self.__get_user(pull[field]['login'])
                elif field == 'merged_by':
                    pull[field + '_data'] = self.__get_user(pull[field]['login'])
                elif field == 'review_comments':
                    pull[field + '_data'] = self.__get_pull_review_comments(pull['number'])
                elif field == 'requested_reviewers':
                    pull[field + '_data'] = self.__get_pull_requested_reviewers(pull['number'])
                elif field == 'commits':
                    pull[field + '_data'] = self.__get_pull_commits(pull['number'])

            yield pull

def base_url(self):
