def match_filtered_identities(self, fa, fb):
        if not isinstance(fa, UsernameIdentity):
            raise ValueError("<fa> is not an instance of UsernameIdentity")
        if not isinstance(fb, UsernameIdentity):
            raise ValueError("<fb> is not an instance of UsernameIdentity")

        if fa.uuid and fb.uuid and fa.uuid == fb.uuid:
            return True

        if fa.username in self.blacklist:
            return False

        # Compare username first
        if fa.username and fa.username == fb.username:
            return True

        return False

def RegisterEventHandler(self, Event, Target):
        if not callable(Target):
            raise TypeError('%s is not callable' % repr(Target))
        if Event not in self._EventHandlers:
            raise ValueError('%s is not a valid %s event name' % (Event, self.__class__.__name__))
        if Target in self._EventHandlers[Event]:
            return False
        self._EventHandlers[Event].append(Target)
        self.__Logger.info('registered %s: %s', Event, repr(Target))
        return True

