def tone(frequency, sr=22050, length=None, duration=None, phi=None):

    if frequency is None:
        raise ParameterError('"frequency" must be provided')

    # Compute signal length
    if length is None:
        if duration is None:
            raise ParameterError('either "length" or "duration" must be provided')
        length = duration * sr

    if phi is None:
        phi = -np.pi * 0.5

    step = 1.0 / sr
    return np.cos(2 * np.pi * frequency * (np.arange(step * length, step=step)) + phi)

def find(self, selector, **kwargs):

        self.debug_log("Finding element with selector: %s" % selector)

        elements = self.find_all(selector, **kwargs)
        if len(elements):
            self.debug_log("find (%s): Element found" % (selector))
            return elements[0]
        else:
            self.debug_log("find (%s): No element found" % (selector))
            return None

