def get_key_signature_accidentals(key='C'):
    accidentals = get_key_signature(key)
    res = []

    if accidentals < 0:
        for i in range(-accidentals):
            res.append('{0}{1}'.format(list(reversed(notes.fifths))[i], 'b'))
    elif accidentals > 0:
        for i in range(accidentals):
            res.append('{0}{1}'.format(notes.fifths[i], '#'))
    return res

def _resolve_fallback(self, gates, n_qubits):
        flattened = []
        for g in gates:
            if self._has_action(g):
                flattened.append(g)
            else:
                flattened += self._resolve_fallback(g.fallback(n_qubits), n_qubits)
        return flattened

