                yield var
        yield from self.body

def get_announcements_list(request, context):
    user = context["user"]

    if context["announcements_admin"] and context["show_all"]:
        # Show all announcements if user has admin permissions and the
        # show_all GET argument is given.
        announcements = (Announcement.objects.all())
    else:
        # Only show announcements for groups that the user is enrolled in.
        if context["show_expired"]:
            announcements = (Announcement.objects.visible_to_user(user))
        else:
            announcements = (Announcement.objects.visible_to_user(user).filter(expiration_date__gt=timezone.now()))

    if context["events_admin"] and context["show_all"]:
        events = (Event.objects.all())
    else:
        if context["show_expired"]:
            events = (Event.objects.visible_to_user(user))
        else:
            # Unlike announcements, show events for the rest of the day after they occur.
            midnight = timezone.make_aware(timezone.datetime.combine(datetime.now(), time(0, 0)))
            events = (Event.objects.visible_to_user(user).filter(time__gte=midnight, show_on_dashboard=True))

    items = sorted(chain(announcements, events), key=lambda item: (item.pinned, item.added))
    items.reverse()

    return items

def _getFullPolicyName(policy_item,
                       policy_name,
                       return_full_policy_names,
                       adml_language):
    adml_data = _get_policy_resources(language=adml_language)
    if policy_name in adm_policy_name_map[return_full_policy_names]:
        return adm_policy_name_map[return_full_policy_names][policy_name]
    if return_full_policy_names and 'displayName' in policy_item.attrib:
        fullPolicyName = _getAdmlDisplayName(adml_data, policy_item.attrib['displayName'])
        if fullPolicyName:
            adm_policy_name_map[return_full_policy_names][policy_name] = fullPolicyName
            policy_name = fullPolicyName
    elif return_full_policy_names and 'id' in policy_item.attrib:
        fullPolicyName = _getAdmlPresentationRefId(adml_data, policy_item.attrib['id'])
        if fullPolicyName:
            adm_policy_name_map[return_full_policy_names][policy_name] = fullPolicyName
            policy_name = fullPolicyName
    policy_name = policy_name.rstrip(':').rstrip()
    return policy_name

def paint(self, painter, option, widget):
        # rebuild when dirty
        if self.isDirty():
            self.rebuild()

        painter.save()
        painter.setOpacity( self.opacity() )

        if self.drawHotspotsUnderneath():
            self.drawHotspots(painter)

        if self.isEnabled():
            painter.setPen(self.penColor())
            painter.setBrush(self.brush())
        else:
            painter.setPen(self.disabledPenColor())
            painter.setBrush(self.disabledBrush())

        # draw the item
        self.draw(painter, option, widget)

        if not self.drawHotspotsUnderneath():
            self.drawHotspots(painter)

        painter.restore()

