        else:
            yield command

def get_number(self):
        number = None
        start = self.get_char('0123456789.-')
        if start:
            number = start
            finish = self.get_chars('-e0123456789.')
            if finish:
                number += finish
        if any(c in number for c in '.e'):
            return float(number)
        else:
            return int(number)

def call(self, func, *args, **kwargs):
        guessed_kwargs = self._guess_kwargs(func)
        for key, val in guessed_kwargs.items():
            kwargs.setdefault(key, val)
        try:
            return func(*args, **kwargs)
        except TypeError as exc:
            msg = (
                "tried calling function %r but failed, probably "
                "because it takes arguments that cannot be resolved"
            ) % func
            raise DiayException(msg) from exc

def _apply_krauss(krauss: Union[Tuple[np.ndarray], Sequence[Any]],
        args: 'ApplyChannelArgs') -> np.ndarray:
    # Initialize output.
    args.out_buffer[:] = 0
    # Stash initial state into buffer0.
    np.copyto(dst=args.auxiliary_buffer0, src=args.target_tensor)

    # Special case for single-qubit operations.
    if krauss[0].shape == (2, 2):
        return _apply_krauss_single_qubit(krauss, args)
    # Fallback to np.einsum for the general case.
    return _apply_krauss_multi_qubit(krauss, args)

