        except ValueError as e:
            raise PresetException("JSON decoding error: " + str(e))
        except Exception as e:
            raise PresetException(str(e))

        try:
            preset = Preset(presetBody)
        except PresetException as e:
            e.message = "Bad format: " + e.message
