def det_axes(self, angles):
        # Transpose to take dot along axis 1
        axes = self.rotation_matrix(angles).dot(self.det_axes_init.T)
        # `axes` has shape (a, 3, 2), need to roll the last dimensions
        # to the second to last place
        return np.rollaxis(axes, -1, -2)

def swap_word_order(source):
    assert len(source) % 4 == 0
    words = "I" * (len(source) // 4)
    return struct.pack(words, *reversed(struct.unpack(words, source)))

def compute_sensori_effect(self, m):
        if self.use_basis_functions:
            func = simulation.step(m, 1000*self.dt)
        else:
            traj = self.bf.trajectory(m).flatten()
            func = lambda t: traj[int(1000*self.dt * t)]

        states = simulation.simulate(self.n, self.x0, self.dt, func)
        last_state_cartesian = simulation.cartesian(self.n, states[-1])

        end_effector_pos = array([last_state_cartesian[self.n], last_state_cartesian[2*self.n]])
        end_effector_pos += self.noise * random.randn(len(end_effector_pos))
        return end_effector_pos

def merge(self, subordinate_graph):
        if not isinstance(subordinate_graph, Graph):
            raise Exception("Graph is expected to only merge with a Graph.")

        subordinate_nodes = subordinate_graph.get_nodes()

        merge_results = []
        for node_id in subordinate_nodes:
            node = subordinate_nodes[node_id]
            merge_results.append((
                node.get_id(),
                self.insert_node(node)
            ))

        # TODO perhaps throw exception if merge was unsuccessful
        return merge_results

def _parse_qualimap_metrics(report_file, data):
    if not utils.file_exists(report_file):
        return {}
    from bs4 import BeautifulSoup
    out = {}
    parsers = {"Globals": _parse_qualimap_globals,
               "Globals (inside of regions)": _parse_qualimap_globals_inregion,
               "Coverage": _parse_qualimap_coverage,
               "Coverage (inside of regions)": _parse_qualimap_coverage,
               "Insert size": _parse_qualimap_insertsize,
               "Insert size (inside of regions)": _parse_qualimap_insertsize}
    with open(report_file) as in_handle:
        root = BeautifulSoup(in_handle.read(), "html.parser")
    for table in root.find_all("div", class_="table-summary"):
        h3 = table.find("h3")
        if h3.text in parsers:
            out.update(parsers[h3.text](table.find("table")))
    new_names = []
    for metric in out:
        if "qualimap_full" not in tz.get_in(("config", "algorithm", "tools_on"), data, []):
            metric += "_qualimap_1e7reads_est"
        new_names.append(metric)
    out = dict(zip(new_names, out.values()))
    return out

