    _cookie_value = sign_enc_payload(load, timestamp, sign_key=sign_key,
                                     enc_key=enc_key, sign_alg=sign_alg)

    content = {name: {"value": _cookie_value}}
    if path is not None:
        content[name]["path"] = path
    if domain is not None:
