def _check_1st_line(line, **kwargs):
    components = kwargs.get("components", ())
    max_first_line = kwargs.get("max_first_line", 50)

    errors = []
    lineno = 1
    if len(line) > max_first_line:
        errors.append(("M190", lineno, max_first_line, len(line)))

    if line.endswith("."):
        errors.append(("M191", lineno))

    if ':' not in line:
        errors.append(("M110", lineno))
    else:
        component, msg = line.split(':', 1)
        if component not in components:
            errors.append(("M111", lineno, component))

    return errors

def _replace_args_with_defaults(self, _args=None, **kwargs):
    if _args is None:
      _args = six.iterkeys(kwargs)
    my_defaults = self.defaults
    for k in _args:
      if k not in kwargs:
        if k in my_defaults:
          kwargs[k] = my_defaults[k]
        elif k in _defaults:
          kwargs[k] = _defaults[k]
    return kwargs

