def resolve_file_name(fname, dir_path='.'):
    if not fname:
        return ''
    tmp, file_name = os.path.split(fname)
    if (not tmp) or (tmp == '.'):
        full_file = os.path.join(dir_path, fname)
    else:
        full_file = fname
    return os.path.realpath(full_file)

