def send_head(self):
        path = self.translate_path(self.path)
        f = None
        if os.path.isdir(path):
            if not self.path.endswith('/'):
                # redirect browser - doing basically what apache does
                self.send_response(301)
                self.send_header("Location", self.path + "/")
                self.end_headers()
                return None
            for index in "index.html", "index.htm":
                index = os.path.join(path, index)
                if os.path.exists(index):
                    path = index
                    break
            else:
                return self.list_directory(path)
        ctype = self.guess_type(path)
        try:
            f = open(path, 'rb')
        except IOError:
            self.send_error(404, "File not found")
            return None
        self.send_response(200)
        self.send_header("Content-type", ctype)
        fs = os.fstat(f.fileno())
        self.send_header("Content-Length", str(fs[6]))
        self.send_header("Last-Modified", self.date_time_string(fs.st_mtime))
        self.end_headers()
        return f

def parse_solver_setting(s):

    try:
        key, value = s.split('=', 1)
    except ValueError:
        key, value = s, 'yes'

    if key in ('rational', 'integer', 'quadratic'):
        value = value.lower() in ('1', 'yes', 'true', 'on')
    elif key in ('threads',):
        value = int(value)
    elif key in ('feasibility_tolerance', 'optimality_tolerance',
                 'integrality_tolerance'):
        value = float(value)

    return key, value

def channel(val: Any,
            default: Any = RaiseTypeErrorIfNotProvided
            ) -> Union[Tuple[np.ndarray], Sequence[TDefault]]:
    channel_getter = getattr(val, '_channel_', None)
    channel_result = (
        NotImplemented if channel_getter is None else channel_getter())
    if channel_result is not NotImplemented:
        return tuple(channel_result)

    mixture_getter = getattr(val, '_mixture_', None)
    mixture_result = (
        NotImplemented if mixture_getter is None else mixture_getter())
    if mixture_result is not NotImplemented:
        return tuple(np.sqrt(p) * u for p, u in mixture_result)

    unitary_getter = getattr(val, '_unitary_', None)
    unitary_result = (
        NotImplemented if unitary_getter is None else unitary_getter())
    if unitary_result is not NotImplemented:
        return (unitary_result,)

    if default is not RaiseTypeErrorIfNotProvided:
        return default

    if (channel_getter is None and unitary_getter is None
            and mixture_getter is None):
        raise TypeError("object of type '{}' has no _channel_ or _mixture_ or "
                        "_unitary_ method.".format(type(val)))
    raise TypeError("object of type '{}' does have a _channel_, _mixture_ or "
                "_unitary_ method, but it returned NotImplemented."
                .format(type(val)))

def apply(
        self,
        func,
        num_splits=None,
        other_axis_partition=None,
        maintain_partitioning=True,
        **kwargs
    ):
        import dask

        if num_splits is None:
            num_splits = len(self.list_of_blocks)

        if other_axis_partition is not None:
            return [
                DaskFramePartition(dask.delayed(obj))
                for obj in deploy_func_between_two_axis_partitions(
                    self.axis,
                    func,
                    num_splits,
                    len(self.list_of_blocks),
                    kwargs,
                    *dask.compute(
                        *tuple(
                            self.list_of_blocks + other_axis_partition.list_of_blocks
                        )
                    )
                )
            ]

        args = [self.axis, func, num_splits, kwargs, maintain_partitioning]

        args.extend(dask.compute(*self.list_of_blocks))
        return [
            DaskFramePartition(dask.delayed(obj)) for obj in deploy_axis_func(*args)
        ]

