        # type: (tuple) -> Tuple[type, slice, Callable]
        if isinstance(args, tuple):
            raise TypeError(
                "{}[...] takes exactly one argument.".format(cls.__name__)
            )
        return super(_StringMeta, cls)._get_args((_STR_TYPE, args))

def exists(table_name, region=None, key=None, keyid=None, profile=None):
    try:
        conn = _get_conn(region=region, key=key, keyid=keyid, profile=profile)
        conn.describe_table(table_name)
    except JSONResponseError as e:
        if e.error_code == 'ResourceNotFoundException':
            return False
        raise

    return True

def get_proxy_ticket(self, pgt):
        response = requests.get(self.get_proxy_url(pgt))
        if response.status_code == 200:
            from lxml import etree
            root = etree.fromstring(response.content)
            tickets = root.xpath(
                "//cas:proxyTicket",
                namespaces={"cas": "http://www.yale.edu/tp/cas"}
            )
            if len(tickets) == 1:
                return tickets[0].text
            errors = root.xpath(
                "//cas:authenticationFailure",
                namespaces={"cas": "http://www.yale.edu/tp/cas"}
            )
            if len(errors) == 1:
                raise CASError(errors[0].attrib['code'], errors[0].text)
        raise CASError("Bad http code %s" % response.status_code)

def put(self, message, indent=0):
        color = self._colors_conf.get(indent + indent % 2, self._colors_conf.get(0, self._default_color))

        for chunk in [' ' * indent, self._colors[color], message, self._colors['ENDC']]:
            self._device.write(str(chunk))
        self._device.write(os.linesep)
        self._device.flush()

def generate_and_cache(path=user_path):
    data = tools.generate()
    if not path:
        return data
    try:
        directory = os.path.dirname(path)
        if not os.path.exists(directory):
            os.makedirs(directory)
        with open(path, 'wb') as f:
            pickle.dump((data_version, module_version, data), f)
    except (PermissionError, ValueError) as e:
        warnings.warn('Unable to write cache file "%s": %s' % (path, e))
    return data

def _get_states_from_samecodes(self, geocodes):
        states = []
        for code in geocodes:
            if not isinstance(geocodes, list):
                raise Exception("specified geocodes must be list")
            try:
                state = self.samecodes[code]['state']
            except KeyError:
                raise Exception("Samecode Not Found")
            else:
                if state not in states:
                    states.append(state)
        return states

