def __write_data_col_header(self, l, pc):
        count = len(l)
        if pc == "chron":
            self.noaa_txt += "# "
        for name in l:
            # last column - spacing not important
            if count == 1:
                self.noaa_txt += "{}\t".format(name)
            # all [:-1] columns - fixed spacing to preserve alignment
            else:
                self.noaa_txt += "{:<15}".format(name)
                count -= 1

        self.noaa_txt += '\n'

