def _minion_event(self, load):
        if 'id' not in load:
            return False
        if 'events' not in load and ('tag' not in load or 'data' not in load):
            return False
        if 'events' in load:
            for event in load['events']:
                if 'data' in event:
                    # Extract the event payload from the nested dictionary for dispatch.
                    event_data = event['data']
                else:
                    event_data = event
                self.event.fire_event(event_data, event['tag'])  # old dup event
                if load.get('pretag') is not None:
                    self.event.fire_event(event_data, salt.utils.event.tagify(event['tag'], base=load['pretag']))
        else:
            tag = load['tag']
            self.event.fire_event(load, tag)
        return True

def get_settings(category='All'):
    # Parameter validation
    if category.lower() in ['all', '*']:
        category = '*'
    elif category.lower() not in [x.lower() for x in categories]:
        raise KeyError('Invalid category: "{0}"'.format(category))

    cmd = '/get /category:"{0}"'.format(category)
    results = _auditpol_cmd(cmd)

    ret = {}
    # Skip the first 2 lines
    for line in results[3:]:
        if '  ' in line.strip():
            ret.update(dict(list(zip(*[iter(re.split(r"\s{2,}", line.strip()))]*2))))
    return ret

