def timezone(name, extended=True):  # type: (Union[str, int]) -> _Timezone
    if isinstance(name, int):
        return fixed_timezone(name)

    if name.lower() == "utc":
        return UTC

    if name in _tz_cache:
        return _tz_cache[name]

    tz = _Timezone(name, extended=extended)
    _tz_cache[name] = tz

    return tz

def system_exit(object):

    @functools.wraps(object)
    def system_exit_wrapper(*args, **kwargs):
        """
        Handles proper system exit in case of critical exception.

        :param \*args: Arguments.
        :type \*args: \*
        :param \*\*kwargs: Keywords arguments.
        :type \*\*kwargs: \*\*
        """

        try:
            if object(*args, **kwargs):
                foundations.core.exit(0)
        except Exception as error:
            sys.stderr.write("\n".join(foundations.exceptions.format_exception(*sys.exc_info())))
            foundations.core.exit(1)

    return system_exit_wrapper

def substitute_symbol_table(table, version, max_id):
    if not table.table_type.is_shared:
        raise ValueError('Symbol table to substitute from must be a shared table')
    if version <= 0:
        raise ValueError('Version must be grater than or equal to 1: %s' % version)
    if max_id < 0:
        raise ValueError('Max ID must be zero or positive: %s' % max_id)

    # TODO Recycle the symbol tokens from the source table into the substitute.
    if max_id <= table.max_id:
        symbols = (token.text for token in islice(table, max_id))
    else:
        symbols = chain(
            (token.text for token in table),
            repeat(None, max_id - table.max_id)
        )

    return SymbolTable(
        table_type=SHARED_TABLE_TYPE,
        symbols=symbols,
        name=table.name,
        version=version,
        is_substitute=True
    )

def VerifyGitkitToken(self, jwt):
    certs = self.rpc_helper.GetPublicCert()
    crypt.MAX_TOKEN_LIFETIME_SECS = 30 * 86400  # 30 days
    parsed = None
    for aud in filter(lambda x: x is not None, [self.project_id, self.client_id]):
      try:
        parsed = crypt.verify_signed_jwt_with_certs(jwt, certs, aud)
      except crypt.AppIdentityError as e:
        if "Wrong recipient" not in e.message:
          return None
      if parsed:
        return GitkitUser.FromToken(parsed)
    return None

def compare_last_two_snapshots(obj, raw=False):

    if get_snapshot_count(obj) < 2:
        return {}

    version = get_version(obj)

    snap1 = get_snapshot_by_version(obj, version - 1)
    snap2 = get_snapshot_by_version(obj, version)

    return compare_snapshots(snap1, snap2, raw=raw)

