def interpretBitEncoding(bitEncoding):
    if bitEncoding == '64':
        floattype = 'd' # 64-bit
        numpyType = numpy.float64
    elif bitEncoding == '32':
        floattype = 'f' # 32-bit
        numpyType = numpy.float32
    else:
        errorText = ''.join(['bitEncoding \'', bitEncoding, '\' not defined. ',
                             'Must be \'64\' or \'32\''
                             ])
        raise TypeError(errorText)
    return (floattype, numpyType)

def wrap(cls, message_parts):
        try:
            yield
        except BaseException as exception:
            __, __, tb = sys.exc_info()
            reraise(cls, cls(exception, message_parts), tb)

def fast_float(
    x,
    key=lambda x: x,
    nan=None,
    _uni=unicodedata.numeric,
    _nan_inf=NAN_INF,
    _first_char=POTENTIAL_FIRST_CHAR,
):
    if x[0] in _first_char or x.lstrip()[:3] in _nan_inf:
        try:
            x = float(x)
            return nan if nan is not None and x != x else x
        except ValueError:
            try:
                return _uni(x, key(x)) if len(x) == 1 else key(x)
            except TypeError:  # pragma: no cover
                return key(x)
    else:
        try:
            return _uni(x, key(x)) if len(x) == 1 else key(x)
        except TypeError:  # pragma: no cover
            return key(x)

