def authenticate(self, request):
        auth = get_authorization_header(request).split()

        if not auth or auth[0].lower() != b'bearer':
            return None

        if len(auth) == 1:
            msg = 'Invalid authorization header. No credentials provided.'
            raise exceptions.AuthenticationFailed(msg)
        elif len(auth) > 2:
            msg = 'Invalid authorization header. Access token should not contain spaces.'
            raise exceptions.AuthenticationFailed(msg)

        # Authenticate the user
        # The AdfsAuthCodeBackend authentication backend will notice the "access_token" parameter
        # and skip the request for an access token using the authorization code
        user = authenticate(access_token=auth[1])

        if user is None:
            raise exceptions.AuthenticationFailed('Invalid access token.')

        if not user.is_active:
            raise exceptions.AuthenticationFailed('User inactive or deleted.')

        return user, auth[1]

def reinstantiate_endpoints(self, endpoint=None):
        endpoint = endpoint or self
        for k, v in endpoint.__class__.__dict__.items():
            if isinstance(v, Endpoint):
                setattr(endpoint, k, v.__class__(self))
            elif inspect.isclass(v) and issubclass(v, Endpoint):
                setattr(endpoint, k, v(self))

def firstPass(ASTs,verbose):
    fdefs=dict()
    cdefs=dict()
    imp_obj_strs=dict()
    imp_mods=dict()
    for (root,path) in ASTs:
        fdefs[path] = []
        fdefs[path].append(formatBodyNode(root,path))
        imp_obj_strs[path] = []
        imp_mods[path] = []
        cdefs[path] = []
        for (node,stack) in traversal(root):
            if isinstance(node,ast.FunctionDef):
                fdefs[path].append(formatFunctionNode(node,path,stack))
            elif isinstance(node,ast.ImportFrom):
                module = ia.getImportFromModule(node,path,verbose)
                if module:
                    fn_names = ia.getImportFromObjects(node)
                    for fn_name in fn_names:
                        imp_obj_strs[path].append((module,fn_name))
                else:
                    if verbose:
                        print("No module found "+ast.dump(node))
            elif isinstance(node,ast.Import):
                module = ia.getImportModule(node,path,verbose)
                imp_mods[path].append(module)
            elif isinstance(node,ast.ClassDef):
                node.path=path
                cdefs[path].append(node)
    return fdefs,imp_obj_strs,imp_mods,cdefs

def do_hit(self, arg):

        if arg['create']:
            self.hit_create(arg['<numWorkers>'], arg['<reward>'],
                            arg['<duration>'])
            self.update_hit_tally()
        elif arg['extend']:
            self.amt_services_wrapper.hit_extend(arg['<HITid>'], arg['<number>'], arg['<minutes>'])
        elif arg['expire']:
            self.amt_services_wrapper.hit_expire(arg['--all'], arg['<HITid>'])
            self.update_hit_tally()
        elif arg['delete'] or arg['dispose']:
            self.amt_services_wrapper.hit_delete(arg['--all'], arg['<HITid>'])
            self.update_hit_tally()
        elif arg['list']:
            self.hit_list(arg['--active'], arg['--reviewable'], arg['--all-studies'])
        else:
            self.help_hit()

