def get_all(self, attr, value, e=0.000001,
                sort_by="__name__", reverse=False):
        matched = list()
        for _, klass in self.subclasses(sort_by, reverse):
            try:
                if getattr(klass, attr) == approx(value, e):
                    matched.append(klass)
            except:  # pragma: no cover
