def stats(self, query=None, target=None):
        with self.lock:
            if not query:
                self.send('STATS')
            elif not target and query:
                self.send('STATS %s' % query)
            else:
                self.send('STATS %s %s' % (query, target))
            stat_lines = []
            while self.readable():
                msg = self._recv()
                if msg[1] == '219':
                    break
                else:
                    stat_lines.append(msg[3].replace(':', '', 1))
            return stat_lines

def recode_unicode(s, encoding='utf-8'):
