            function.add_filter(filter)

            return function
        else:
            return Filter(
                filter=filter_func[0],
                callback=function,
            )

    def filter_decorator(*args, **kwargs):
        filter_function = filter_creator(*args, **kwargs)

        filter_func[0] = filter_function

        return function_getter

    return filter_decorator

