def smallest_url(flickr, pid, min_width, min_height):
    sizes = flickr.photos_getSizes(photo_id=pid, format='parsed-json')
    smallest_url = None
    smallest_area = None
    for size in sizes['sizes']['size']:
        width = int(size['width'])
        height = int(size['height'])
        # Enforce a minimum height and width
        if width >= min_width and height >= min_height:
            if not smallest_url or height * width < smallest_area:
                smallest_area = height * width
                smallest_url = size['source']
    return smallest_url

def promotePrefixes(self):
        for c in self.children:
            c.promotePrefixes()
        if self.parent is None:
            return
        _pref = []
        for p, u in self.nsprefixes.items():
            if p in self.parent.nsprefixes:
                pu = self.parent.nsprefixes[p]
                if pu == u:
                    _pref.append(p)
                continue
            if p != self.parent.prefix:
                self.parent.nsprefixes[p] = u
                _pref.append(p)

        for x in _pref:
            del self.nsprefixes[x]

        return self

def get_row_list(self, row_idx):

        try:
            row = self._rows[row_idx]
        except TypeError:
            row = self._rows[self._row_name_idx[row_idx]]

        if isinstance(row, list):
            extra = [ self._default_value ] * (len(self._column_name_list) - len(row))
            return row + extra

        else:
            if row_idx not in self._row_memo:
                self._row_memo[row_idx] = [ row[k] if k in row else self._default_value for k in self._column_name_list ]

            return self._row_memo[row_idx]

