def new_filename(data, file_kind, ext):

    nb_key = file_kind + "number"
    if nb_key not in data.keys():
        data[nb_key] = -1

    if not data["override externals"]:
        # Make sure not to overwrite anything.
        file_exists = True
        while file_exists:
            data[nb_key] = data[nb_key] + 1
            filename, name = _gen_filename(data, nb_key, ext)
            file_exists = os.path.isfile(filename)
    else:
        data[nb_key] = data[nb_key] + 1
        filename, name = _gen_filename(data, nb_key, ext)

    if data["rel data path"]:
        rel_filepath = posixpath.join(data["rel data path"], name)
    else:
        rel_filepath = name

    return filename, rel_filepath

def get_arrays_from_file(params_file, params=None):
        try:
            f = h5py.File(params_file, 'r')
        except:
            raise ValueError('File not found.')
        if params is not None:
            if not isinstance(params, list):
                params = [params]
            for p in params:
                if p not in f.keys():
                    raise ValueError('Parameter {} is not in {}'
                                     .format(p, params_file))
        else:
            params = [str(k) for k in f.keys()]
        tmp = {p:f[p][:] for p in params}
        try:
            bandwidth = f.attrs["bandwidth"]
        except KeyError:
            bandwidth = "scott"

        f.close()
        return tmp, bandwidth

def to_json(self):
        edges = []
        for root in self.roots:
            edges.append({
                'governer': 0,
                'dep': "root",
                'dependent': root+1,
                'governergloss': "root",
                'dependentgloss': self.sentence[root].word,
                })

        for gov, dependents in self.graph.items():
            for dependent, dep in dependents:
                edges.append({
                    'governer': gov+1,
                    'dep': dep,
                    'dependent': dependent+1,
                    'governergloss': self.sentence[gov].word,
                    'dependentgloss': self.sentence[dependent].word,
                    })
        return edges

def error_handler(func):
    @wraps(func)
    def wrapper(*args, **kwargs):
        """
        Run actual function and if exception catched and error handler enabled
        put traceback to log file
        """
        try:
            return func(*args, **kwargs)
        except BaseException as err:
            # Do not catch exceptions on testing
            if BOOTSTRAPPER_TEST_KEY in os.environ:
                raise
            # Fail silently if error handling disabled
            if ERROR_HANDLER_DISABLED:
                return True
            # Otherwise save traceback to log
            return save_traceback(err)
    return wrapper

