            'Could not connect to cobbler.'
        )
        return {}

    return {data['status']: data['mgmt_classes']}

def humanize_size(size):
    for factor, format_string in ((1, '%i'),
                                  (1024, '%iKiB'),
                                  (1024 * 1024, '%.1fMiB')):
        if size / factor < 1024:
            return format_string % (size / factor)
    return format_string % (size / factor)

