def match(self, p_todo):
        def resort_to_grep_filter():
            grep = GrepFilter(self.expression)
            return grep.match(p_todo)

        if not self.key or not p_todo.has_tag(self.key):
            return False

        if len(p_todo.tag_values(self.key)) > 1:
            # we cannot apply an ordening on a tag that appears more than once
            # in this todo item, therefore use a simple value match
            return resort_to_grep_filter()

        try:
            operand1 = date_string_to_date(p_todo.tag_value(self.key))
            operand2 = relative_date_to_date(self.value)

            if not operand2:
                operand2 = date_string_to_date(self.value)

        except ValueError:
            operand1 = p_todo.tag_value(self.key)
            operand2 = self.value

            try:
                operand1 = int(operand1)
                operand2 = int(operand2)
            except ValueError:
                return resort_to_grep_filter()

        return self.compare_operands(operand1, operand2)

def check_infile_and_wp(curinf, curwp):
        if not os.path.exists(curinf):
            if curwp is None:
                TauDEM.error('You must specify one of the workspace and the '
                             'full path of input file!')
            curinf = curwp + os.sep + curinf
            curinf = os.path.abspath(curinf)
            if not os.path.exists(curinf):
                TauDEM.error('Input files parameter %s is not existed!' % curinf)
        else:
            curinf = os.path.abspath(curinf)
            if curwp is None:
                curwp = os.path.dirname(curinf)
        return curinf, curwp

def make_dom_map(pmt_directions, values, nside=512, d=0.2, smoothing=0.1):
    import healpy as hp
    discs = [hp.query_disc(nside, dir, 0.2) for dir in pmt_directions]
    npix = hp.nside2npix(nside)
    pixels = np.zeros(npix)
    for disc, value in zip(discs, values):
        for d in disc:
            pixels[d] = value
    if smoothing > 0:
        return hp.sphtfunc.smoothing(pixels, fwhm=smoothing, iter=1)
    return pixels

