def _prepare_body(self):
        content_type = self.__consume
        if not content_type:
            content_type = self.__op.consumes[0] if self.__op.consumes else 'application/json'
        if self.__op.consumes and content_type not in self.__op.consumes:
            raise errs.SchemaError('content type {0} does not present in {1}'.format(content_type, self.__op.consumes))

        # according to spec, payload should be one and only,
        # so we just return the first value in dict.
        for parameter in self.__op.parameters:
            parameter = final(parameter)
            if getattr(parameter, 'in') == 'body':
                schema = deref(parameter.schema)
                _type = schema.type
                _format = schema.format
                name = schema.name
                body = self.__p['body'][parameter.name]
                return content_type, self.__op._mime_codec.marshal(content_type, body, _type=_type, _format=_format, name=name)
        return None, None

def get_outcome_probs(self):
        outcome_dict = {}
        qubit_num = len(self)
        for index, amplitude in enumerate(self.amplitudes):
            outcome = get_bitstring_from_index(index, qubit_num)
            outcome_dict[outcome] = abs(amplitude) ** 2
        return outcome_dict

def run(self, dag):
        num_dag_qubits = sum([qreg.size for qreg in dag.qregs.values()])
        if num_dag_qubits > self.coupling_map.size():
            raise TranspilerError('Number of qubits greater than device.')
        best_sub = self._best_subset(num_dag_qubits)
        layout = Layout()
        map_iter = 0
        for qreg in dag.qregs.values():
            for i in range(qreg.size):
                layout[(qreg, i)] = int(best_sub[map_iter])
                map_iter += 1
        self.property_set['layout'] = layout

def _set_scores(self):
        anom_scores = {}
        for i, (timestamp, value) in enumerate(self.time_series.items()):

            baseline_value = self.baseline_time_series[i]

            if baseline_value > 0:
                diff_percent = 100 * (value - baseline_value) / baseline_value
            elif value > 0:
                diff_percent = 100.0
            else:
                diff_percent = 0.0

            anom_scores[timestamp] = 0.0
            if self.percent_threshold_upper and diff_percent > 0 and diff_percent > self.percent_threshold_upper:
                anom_scores[timestamp] = diff_percent
            if self.percent_threshold_lower and diff_percent < 0 and diff_percent < self.percent_threshold_lower:
                anom_scores[timestamp] = -1 * diff_percent

        self.anom_scores = TimeSeries(self._denoise_scores(anom_scores))

