def from_etree(root):
        cite_list = []
        citations = root.xpath('Citations/EventIVORN')
        if citations:
            description = root.xpath('Citations/Description')
            if description:
                description_text = description[0].text
            else:
                description_text = None
            for entry in root.Citations.EventIVORN:
                if entry.text:
                    cite_list.append(
                        Cite(ref_ivorn=entry.text,
                             cite_type=entry.attrib['cite'],
                             description=description_text)
                    )
                else:
                    logger.info(
                        'Ignoring empty citation in {}'.format(
                            root.attrib['ivorn']))
        return cite_list

def squarify_table(table):
    max_length = 0
    min_length = maxsize
    for row in table:
        row_len = len(row)
        if row_len > max_length:
            max_length = row_len
        if row_len < min_length:
            min_length = row_len
    if max_length != min_length:
        for row in table:
            row_len = len(row)
            if row_len < max_length:
                row.extend([None]*(max_length-row_len))

