def serialize(self):
        if self.mate_chrom is None:
            remote_tag = "."
        else:
            if self.within_main_assembly:
                mate_chrom = self.mate_chrom
            else:
                mate_chrom = "<{}>".format(self.mate_chrom)
            tpl = {FORWARD: "[{}:{}[", REVERSE: "]{}:{}]"}[self.mate_orientation]
            remote_tag = tpl.format(mate_chrom, self.mate_pos)
        if self.orientation == FORWARD:
            return remote_tag + self.sequence
        else:
            return self.sequence + remote_tag

def get_scope_path(self, scope_separator="::"):
        if self.parent_scope is None:
            return ""
        elif isinstance(self.parent_scope, Root):
            return ""
        else:
            parent_path = self.parent_scope.get_scope_path(scope_separator)
            if parent_path:
                return(
                    parent_path
                    + scope_separator
                    + self.parent_scope.type_name
                )
            else:
                return self.parent_scope.type_name

