    conn_args = _login(**kwargs)
    ret = {}
    try:
        if conn_args:
            method = method
            params = params
            params = _params_extend(params, **kwargs)
            ret = _query(method, params, conn_args['url'], conn_args['auth'])
            if isinstance(ret['result'], bool):
                return ret['result']
            return ret['result'] if ret['result'] else False
        else:
            raise KeyError
    except KeyError:
        return ret

