def _split_path(xj_path):

    res = xj_path.rsplit('.', 1)
    root_key = res[0]
    if len(res) > 1:
        return root_key, res[1]
    else:
        if root_key and root_key != '.':
            return None, root_key
        else:
            raise XJPathError('Path cannot be empty', (xj_path,))

