def _format_char(char):
    if char is None:
        return -1
    if isinstance(char, _STRTYPES) and len(char) == 1:
        return ord(char)
    try:
        return int(char) # allow all int-like objects
    except:
        raise TypeError('char single character string, integer, or None\nReceived: ' + repr(char))

def dskn02(handle, dladsc, plid):
    handle = ctypes.c_int(handle)
    plid   = ctypes.c_int(plid)
    normal = stypes.emptyDoubleVector(3)
    libspice.dskn02_c(handle, dladsc, plid, normal)
    return stypes.cVectorToPython(normal)

