def check(self, check_url=None):

        if check_url is not None:
            self.check_url = self._normalize_check_url(check_url)

        response = None
        sleeped = 0.0
        t = datetime.now()

        while not response:
            try:
                response = requests.get(self.check_url, verify=False)
            except requests.exceptions.ConnectionError:
                if sleeped > self.timeout:
                    self._kill()
                    raise LiveAndLetDieError(
                        '{0} server {1} didn\'t start in specified timeout {2} '
                        'seconds!\ncommand: {3}'.format(
                            self.__class__.__name__,
                            self.check_url,
                            self.timeout,
                            ' '.join(self.create_command())
                        )
                    )
                time.sleep(1)
                sleeped = _get_total_seconds(datetime.now() - t)

        return _get_total_seconds(datetime.now() - t)

def _get_available_letters(field_name, queryset):
    if django.VERSION[1] <= 4:
        result = queryset.values(field_name).annotate(
            fl=FirstLetter(field_name)
        ).values('fl').distinct()
        return set([res['fl'] for res in result if res['fl'] is not None])
    else:
        from django.db import connection
        qn = connection.ops.quote_name
        db_table = queryset.model._meta.db_table
        sql = "SELECT DISTINCT UPPER(SUBSTR(%s, 1, 1)) as letter FROM %s" % (qn(field_name), qn(db_table))
        cursor = connection.cursor()
        cursor.execute(sql)
        rows = cursor.fetchall() or ()
        return set([row[0] for row in rows if row[0] is not None])

def _read_ssm_locs(in_file):
    out = {}
    with open(in_file) as in_handle:
        in_handle.readline()  # header
        for line in in_handle:
            sid, loc = line.split()[:2]
            chrom, pos = loc.split("_")
            out[sid] = (chrom, int(pos))
    return out

def get_last_rconfiguration_id(topic_id, remoteci_id, db_conn=None):
    db_conn = db_conn or flask.g.db_conn
    __TABLE = models.JOBS
    query = sql.select([__TABLE.c.rconfiguration_id]). \
        order_by(sql.desc(__TABLE.c.created_at)). \
        where(sql.and_(__TABLE.c.topic_id == topic_id,
                       __TABLE.c.remoteci_id == remoteci_id)). \
        limit(1)
    rconfiguration_id = db_conn.execute(query).fetchone()
    if rconfiguration_id is not None:
        return str(rconfiguration_id[0])
    else:
        return None

