def Nu_Krasnoshchekov(Re, Pr, rho_w=None, rho_b=None, Cp_avg=None, Cp_b=None, 
                      T_b=None, T_w=None, T_pc=None):
    if all([T_b, T_w, T_pc]):
        n1 = 0.22 + 0.18*T_w/T_pc
        if T_b < T_w < T_pc or 1.2*T_pc < T_b < T_w:      
            n = 0.4
        elif 1 < T_w/T_pc < 2.5:
            n = n1
        else:
            n = n1 + (5*n1 - 2)*(1 - T_b/T_pc)
    else:
        n = 0.4
    fd = (1.82*log10(Re) - 1.64)**-2
    Nu = (fd/8.)*Re*Pr/(1.07 + 12.7*(fd/8.)**0.5*(Pr**(2/3.)-1))
    if rho_w and rho_b:
        Nu *= (rho_w/rho_b)**0.3
    if Cp_avg and Cp_b:
        Nu *= (Cp_avg/Cp_b)**n
    return Nu

def pfd(X, D=None):
    if D is None:
        D = numpy.diff(X)
        D = D.tolist()
    N_delta = 0  # number of sign changes in derivative of the signal
    for i in range(1, len(D)):
        if D[i] * D[i - 1] < 0:
            N_delta += 1
    n = len(X)
    return numpy.log10(n) / (
        numpy.log10(n) + numpy.log10(n / n + 0.4 * N_delta)
    )

def invalidate_cache(self, klass, instance=None, extra=None,
                         force_all=False):

        values = self._get_cache_extras(klass, instance=instance,
                                        extra=extra, force_all=force_all)

        if values == CacheConfig.ALL:
            self._increment_version()
        elif values:
            for value in values:
                self._increment_version(extra=value)

def handle_message(self, msg):
        # log messages received so that no one else has to
        if self._logger.isEnabledFor(logging.DEBUG):
            self._logger.debug(
                "received from {}: {}"
                .format(self.bind_address_string, repr(str(msg))))

        if msg.mtype == Message.INFORM:
            return self.handle_inform(msg)
        elif msg.mtype == Message.REPLY:
            return self.handle_reply(msg)
        elif msg.mtype == Message.REQUEST:
            return self.handle_request(msg)
        else:
            self._logger.error("Unexpected message type from server ['%s']."
                               % (msg,))

