def bind(self, func: Callable[[Any], 'Writer']) -> 'Writer':
        a, w = self.run()
        b, w_ = func(a).run()

        if isinstance(w_, Monoid):
            w__ = cast(Monoid, w).append(w_)
        else:
            w__ = w + w_

        return Writer(b, w__)

