def b_vdm(B, lat):
    # changed radius of the earth from 3.367e6 3/12/2010
    fact = ((6.371e6)**3) * 1e7
    colat = np.radians(90. - lat)
    return fact * B / (np.sqrt(1 + 3 * (np.cos(colat)**2)))

