def _read_isotopedatabase(self, ffname='isotopedatabase.txt'):
        name=self.sldir+ffname
        z_db, a_db, el_db, stable_a_db,logic_db=\
            np.loadtxt(name,unpack=True,dtype='str')
        z_db=np.array(z_db,dtype='int')
        a_db=np.array(a_db,dtype='int')
        stable_a_db=np.array(stable_a_db,dtype='int')

        # charge number for element name from dictionary in isotopedatabase.txt
        charge_from_element_name={}
        for name in self.stable_names:
            if name=='Neutron' or name=='Neut' or name=='NEUT' or name=='N-1':
                name='nn'
            try:
                zz=z_db[np.where(el_db==name)][0]
                charge_from_element_name[name]=zz
            except IndexError:
                print(name+" does not exist in this run")
        return z_db, a_db, el_db, stable_a_db,logic_db,charge_from_element_name

def fromkeys(cls, seq, value=None, **kwargs):
        values = ((key, value) for key in seq)
        return cls(values, **kwargs)

def clean_data(input_value):


# pass normal json/yaml datatypes
    if input_value.__class__.__name__ in ['bool', 'str', 'float', 'int', 'NoneType']:
        pass

# transform byte data to base64 encoded string
    elif isinstance(input_value, bytes):
        from base64 import b64encode
        input_value = b64encode(input_value).decode()

# convert tuples and sets into lists
    elif isinstance(input_value, tuple) or isinstance(input_value, set):
        new_list = []
        new_list.extend(input_value)
        input_value = transform_data(clean_data, new_list)

# recurse through dictionaries and lists
    elif isinstance(input_value, dict) or isinstance(input_value, list):
        input_value = transform_data(clean_data, input_value)

# convert to string all python objects and callables
    else:
        input_value = str(input_value)

    return input_value

def _json_safe(cls, value):
        # Date
        if type(value) == date:
            return str(value)

        # Datetime
        elif type(value) == datetime:
            return value.strftime('%Y-%m-%d %H:%M:%S')

        # Object Id
        elif isinstance(value, ObjectId):
            return str(value)

        # Frame
        elif isinstance(value, _BaseFrame):
            return value.to_json_type()

        # Lists
        elif isinstance(value, (list, tuple)):
            return [cls._json_safe(v) for v in value]

        # Dictionaries
        elif isinstance(value, dict):
            return {k:cls._json_safe(v) for k, v in value.items()}

        return value

def PrivateKeyFromWIF(wif):
        if wif is None or len(wif) is not 52:
            raise ValueError('Please provide a wif with a length of 52 bytes (LEN: {0:d})'.format(len(wif)))

        data = base58.b58decode(wif)

        length = len(data)

        if length is not 38 or data[0] is not 0x80 or data[33] is not 0x01:
            raise ValueError("Invalid format!")

        checksum = Crypto.Hash256(data[0:34])[0:4]

        if checksum != data[34:]:
            raise ValueError("Invalid WIF Checksum!")

        return data[1:33]

def pairwise(iterable):
    now, nxt = tee(iterable)
    next(nxt, None)
    return izip(now, nxt)

def traverse(self, index=0):
        if index < len(self.nodes):
            for entity in self.nodes[index]:
                for next_result in self.traverse(index=index+1):
                    if isinstance(entity, list):
                        yield entity + next_result
                    else:
                        yield [entity] + next_result
        else:
            yield []

def _track(self, class_name):
        if self._test_cases.get(class_name) is None:
            if self.streaming and self.header:
                self._write_test_case_header(class_name, self.stream)

            self._test_cases[class_name] = []
            if self.combined:
                self.combined_test_cases_seen.append(class_name)

def IOR(classical_reg1, classical_reg2):
    left, right = unpack_reg_val_pair(classical_reg1, classical_reg2)
    return ClassicalInclusiveOr(left, right)

def add_words(self):

        data_blocks = len(self.buffer.getvalue()) // 8
        total_blocks = tables.data_capacity[self.version][self.error][0] // 8
        needed_blocks = total_blocks - data_blocks

        if needed_blocks == 0:
            return None

        #This will return item1, item2, item1, item2, etc.
        block = itertools.cycle(['11101100', '00010001'])

        #Create a string of the needed blocks
        return ''.join([next(block) for x in range(needed_blocks)])

def to_facets(self, facets, start=0, page_size=None):

        if len(facets) == 0:
            raise ValueError("Facets must contain at least one entry", "facets")
        str_query = self.__str__()
        facet_query = FacetQuery(str_query, None, facets, start, page_size, query_parameters=self.query_parameters,
                                 wait_for_non_stale_results=self.wait_for_non_stale_results,
                                 wait_for_non_stale_results_timeout=self.timeout, cutoff_etag=self.cutoff_etag)

        command = GetFacetsCommand(query=facet_query)
        return self.session.requests_executor.execute(command)

def get_position(self, ):
        pos = QtGui.QCursor.pos()
        if self._alignment & QtCore.Qt.AlignLeft == QtCore.Qt.AlignLeft:
            pos.setX(pos.x() - self._offset)
        elif self._alignment & QtCore.Qt.AlignRight == QtCore.Qt.AlignRight:
            pos.setX(pos.x() - self.frameGeometry().width() + self._offset)
        elif self._alignment & QtCore.Qt.AlignHCenter == QtCore.Qt.AlignHCenter:
            pos.setX(pos.x() - self.frameGeometry().width()/2)
        if self._alignment & QtCore.Qt.AlignTop == QtCore.Qt.AlignTop:
            pos.setY(pos.y() - self._offset)
        elif self._alignment & QtCore.Qt.AlignBottom == QtCore.Qt.AlignBottom:
            pos.setY(pos.y() - self.frameGeometry().height() + self._offset)
        elif self._alignment & QtCore.Qt.AlignVCenter == QtCore.Qt.AlignVCenter:
            pos.setY(pos.y() - self.frameGeometry().height()/2)
        return pos

def generate_namelist_file(self, rapid_namelist_file):
        log("Generating RAPID namelist file ...",
            "INFO")
        try:
            os.remove(rapid_namelist_file)
        except OSError:
            pass

        with open(rapid_namelist_file, 'w') as new_file:
            new_file.write('&NL_namelist\n')
            for attr, value in sorted(list(self.__dict__.items())):
                if not attr.startswith('_'):
                    if attr.startswith('BS'):
                        new_file.write("{0} = .{1}.\n"
                                       .format(attr, str(value).lower()))
                    elif isinstance(value, int):
                        new_file.write("%s = %s\n" % (attr, value))
                    else:
                        if value:
                            if os.name == "nt":
                                # if windows generate file with cygpath
                                value = self._get_cygwin_path(value)
                            new_file.write("%s = \'%s\'\n" % (attr, value))
            new_file.write("/\n")

def reactivate(domain_name):
    opts = salt.utils.namecheap.get_opts('namecheap.domains.reactivate')
    opts['DomainName'] = domain_name

    response_xml = salt.utils.namecheap.post_request(opts)

    if response_xml is None:
        return {}

    domainreactivateresult = response_xml.getElementsByTagName('DomainReactivateResult')[0]
    return salt.utils.namecheap.xml_to_dict(domainreactivateresult)

def make_bands(self, ax):
