def _apply(self, element, key=None):
        kwargs = {}
        for hook in self._preprocess_hooks:
            kwargs.update(hook(self, element))
        ret = self._process(element, key)
        for hook in self._postprocess_hooks:
            ret = hook(self, ret, **kwargs)
