def add_col_features(self, col=None, degree=None):

        if not col and not degree:
            return

        else:
            if isinstance(col, list) and isinstance(degree, list):
                if len(col) != len(degree):
                    print('col len: ', len(col))
                    print('degree len: ', len(degree))
                    raise ValueError('col and degree should have equal length.')
                else:
                    if self.preprocessed_data.empty:
                        data = self.original_data
                    else:
                        data = self.preprocessed_data

                    for i in range(len(col)):
                        data.loc[:,col[i]+str(degree[i])] = pow(data.loc[:,col[i]],degree[i]) / pow(10,degree[i]-1)

                    self.preprocessed_data = data
            else:
                raise TypeError('col and degree should be lists.')

def _load_dict_hierarchical(self, db_key: str) -> dict:
        db_keys = self._db.keys(pattern=db_key + '*')
        my_dict = {}
        for _db_key in db_keys:
            if self._db.type(_db_key) == 'list':
                db_values = self._db.lrange(_db_key, 0, -1)
                for i, value in enumerate(db_values):
                    try:
                        db_values[i] = ast.literal_eval(value)
                    except SyntaxError:
                        pass
                    except ValueError:
                        pass
            else:  # self._db.type == 'hash'
                db_values = self._db.hgetall(_db_key)
                for _key, _value in db_values.items():
                    try:
                        db_values[_key] = ast.literal_eval(_value)
                    except SyntaxError:
                        pass
                    except ValueError:
                        pass
            my_dict = self._build_dict(my_dict, _db_key.split(':'),
                                       db_values)
        return my_dict[db_key]

