def getTimes(dataTasks):
    global begin_time
    start_time, end_time = float('inf'), 0
    for fichier, vals in dataTask.items():
        try:
            if hasattr(vals, 'values'):
                tmp_start_time = min([a['start_time'] for a in vals.values()])[0]
                if tmp_start_time < start_time:
                    start_time = tmp_start_time
                tmp_end_time = max([a['end_time'] for a in vals.values()])[0]
                if tmp_end_time > end_time:
                    end_time = tmp_end_time
        except ValueError:
            continue
    begin_time = 1000 * start_time
    return 1000 * start_time, 1000 * end_time

def deprecated(func):
    @functools.wraps(func)
    def new_func(*args, **kwargs):
        if sys.version_info < (3, 0):
            warnings.warn_explicit(
                "Call to deprecated function {}.".format(func.__name__),
                category=DeprecationWarning,
                filename=func.func_code.co_filename,
                lineno=func.func_code.co_firstlineno + 1
            )
        else:
            warnings.warn_explicit(
                "Call to deprecated function {}.".format(func.__name__),
                category=DeprecationWarning,
                filename=func.__code__.co_filename,
                lineno=func.__code__.co_firstlineno + 1
            )
        return func(*args, **kwargs)
    return new_func

def consume_message_with_notify(
        notifier_uri_getter):

    def consume_message_with_notify_decorator(
            method):

        @consume_message
        def wrapper(
                self,
                data):

            notifier_uri = notifier_uri_getter(self)
            client_id = data["client_id"]

            # Forward the call to the method and notify the client of the
            # result
            try:
                method(self, data)
                notify_client(notifier_uri, client_id, 200)
            except Exception as exception:
                notify_client(notifier_uri, client_id, 400, str(exception))
                raise

        return wrapper

    return consume_message_with_notify_decorator

