def _merge_hash(option, opt_str, value, parser):
    # type: (Option, str, str, OptionParser) -> None
    if not parser.values.hashes:
        parser.values.hashes = {}  # type: ignore
    try:
        algo, digest = value.split(':', 1)
    except ValueError:
        parser.error('Arguments to %s must be a hash name '
                     'followed by a value, like --hash=sha256:abcde...' %
                     opt_str)
    if algo not in STRONG_HASHES:
        parser.error('Allowed hash algorithms for %s are %s.' %
                     (opt_str, ', '.join(STRONG_HASHES)))
    parser.values.hashes.setdefault(algo, []).append(digest)

def collect_plugins(self,
                        entry_points=None,
                        verify_requirements=False,
                        return_dict=False):


        if entry_points is None:
            entry_points = self.entry_point_names
        else:
            entry_points = util.return_set(entry_points)

        plugins = []
        plugin_names = []
        for name in entry_points:
            for entry_point in pkg_resources.iter_entry_points(name):
                if (hasattr(entry_point, 'resolve') and
                        hasattr(entry_point, 'require')):

                    if verify_requirements:
                        entry_point.require()

                    plugin = entry_point.resolve()
                else:
                    plugin = entry_point.load()

                plugins.append(plugin)
                plugin_names.append(entry_point.name)

        if return_dict:
            return {n: v for n, v in zip(plugin_names, plugins)}

        return plugins, plugin_names

def fromkeys(cls, keys, value=None, names=None):
        N = len(keys)
        if N > 1:
            raise ValueError('Length of keys (%s) must not exceed one because '
                             'no duplicate values are allowed' % (N,))
        items = [[keys[0], value]] if N == 1 else []
        return cls(items, names)

