def countedArray( expr, intExpr=None ):
    arrayExpr = Forward()
    def countFieldParseAction(s,l,t):
        n = t[0]
        arrayExpr << (n and Group(And([expr]*n)) or Group(empty))
        return []
    if intExpr is None:
        intExpr = Word(nums).setParseAction(lambda t:int(t[0]))
    else:
        intExpr = intExpr.copy()
    intExpr.setName("arrayLen")
    intExpr.addParseAction(countFieldParseAction, callDuringTry=True)
    return ( intExpr + arrayExpr )

def linear_interpolate(p1, p2, fraction):
    return np.array((p1[0] + fraction * (p2[0] - p1[0]),
                     p1[1] + fraction * (p2[1] - p1[1]),
                     p1[2] + fraction * (p2[2] - p1[2])))

def bisect(a, b, fn, epsilon, target):
    while (abs(b - a) > 2 * epsilon):
        midpoint = (b + a) / 2
        a_t = fn(a)
        b_t = fn(b)
        midpoint_t = fn(midpoint)
        if (a_t - target) * (midpoint_t - target) < 0:
            b = midpoint
        elif (b_t - target) * (midpoint_t - target) < 0:
            a = midpoint
        else:
            return -999

    return midpoint

def get_macs(self, ip, display_progress):
        if (ip == '0.0.0.0'):
            return None

        ret_macs = []
        snmpobj = natlas_snmp(ip)

        # find valid credentials for this node
        if (snmpobj.get_cred(self.config.snmp_creds) == 0):
            return None

        system_name = util.shorten_host_name(snmpobj.get_val(OID_SYSNAME), self.config.host_domains)

        # cache some common MIB trees
        vlan_vbtbl      = snmpobj.get_bulk(OID_VLANS)
        ifname_vbtbl    = snmpobj.get_bulk(OID_IFNAME)

        for vlan_row in vlan_vbtbl:
            for vlan_n, vlan_v in vlan_row:
                # get VLAN ID from OID
                vlan = natlas_snmp.get_last_oid_token(vlan_n)
                if (vlan >= 1002):
                    continue
                vmacs = self.get_macs_for_vlan(ip, vlan, display_progress, snmpobj, system_name, ifname_vbtbl)
                if (vmacs != None):
                    ret_macs.extend(vmacs)

        if (display_progress == 1):
            print('')

        return ret_macs

def endline_handle(self, original, loc, tokens):
        internal_assert(len(tokens) == 1, "invalid endline tokens", tokens)
        lines = tokens[0].splitlines(True)
        if self.minify:
            lines = lines[0]
        out = []
        ln = lineno(loc, original)
        for endline in lines:
            out.append(self.wrap_line_number(self.adjust(ln)) + endline)
            ln += 1
        return "".join(out)

