def lasts(iterable, items=1, default=None):
    # type: (Iterable[T], int, T) -> Iterable[T]

    last_items = deque(iterable, maxlen=items)

    for _ in range(items - len(last_items)):
        yield default

    for y in last_items:
        yield y

