def send_email(template_name, context=None, *args, **kwargs):
    context = context or {}

    try:
        html = render_to_string(
            context=context,
            template_name='{}.html'.format(template_name),
        )
    except TemplateDoesNotExist:
        html = ''

    try:
        text = render_to_string(
            context=context,
            template_name='{}.txt'.format(template_name),
        )
    except TemplateDoesNotExist:
        text = ''

    if not html and not text:
        raise NoTemplatesException(template_name)

    return mail.send_mail(
        *args,
        html_message=html,
        message=text,
        **kwargs
    )

def await_reply(self, msg_id, timeout=None):
        while True:
            msg = self.get_message(stream='shell', timeout=timeout)

            # Is this the message we are waiting for?
            if msg['parent_header'].get('msg_id') == msg_id:
                if msg['content']['status'] == 'aborted':
                    # This should not occur!
                    raise RuntimeError('Kernel aborted execution request')
                return

def find_one(self, resource, req, **lookup):

        if config.ID_FIELD in lookup:
            return self._find_by_id(resource=resource, _id=lookup[config.ID_FIELD], parent=lookup.get('parent'))
        else:
            args = self._es_args(resource)
            filters = [{'term': {key: val}} for key, val in lookup.items()]
            query = {'query': {'constant_score': {'filter': {'and': filters}}}}

            try:
                args['size'] = 1
                hits = self.elastic(resource).search(body=query, **args)
                docs = self._parse_hits(hits, resource)
                return docs.first()
            except elasticsearch.NotFoundError:
                return

