def get_both_blocks_sibling(self):
        if not self.is_both_blocks():
            return None

        if self.block.block_letter and self.block.block_letter.upper() not in ["A", "B"]:
            # both_blocks is not currently implemented for blocks other than A and B
            return None

        other_instances = (EighthScheduledActivity.objects.filter(activity=self.activity, block__date=self.block.date))

        for inst in other_instances:
            if inst == self:
                continue

            if inst.block.block_letter in ["A", "B"]:
                return inst

        return None

def run(self):
        try:
            answer = urlopen(self.url + "&mode=queue").read().decode()
        except (HTTPError, URLError) as error:
            self.output = {
                "full_text": str(error.reason),
                "color": "#FF0000"
            }
            return

        answer = json.loads(answer)

        # if answer["status"] exists and is False, an error occured
        if not answer.get("status", True):
            self.output = {
                "full_text": answer["error"],
                "color": "#FF0000"
            }
            return

        queue = answer["queue"]
        self.status = queue["status"]

        if self.is_paused():
            color = self.color_paused
        elif self.is_downloading():
            color = self.color_downloading
        else:
            color = self.color

        if self.is_downloading():
            full_text = self.format.format(**queue)
        else:
            full_text = self.format_paused.format(**queue)

        self.output = {
            "full_text": full_text,
            "color": color
        }

