def _determine_case(was_upper, words, string):
    case_type = 'unknown'
    if was_upper:
        case_type = 'upper'
    elif string.islower():
        case_type = 'lower'
    elif len(words) > 0:
        camel_case = words[0].islower()
        pascal_case = words[0].istitle() or words[0].isupper()

        if camel_case or pascal_case:
            for word in words[1:]:
                c = word.istitle() or word.isupper()
                camel_case &= c
                pascal_case &= c
                if not c:
                    break

        if camel_case:
            case_type = 'camel'
        elif pascal_case:
            case_type = 'pascal'
        else:
            case_type = 'mixed'

    return case_type

