def _parse_postmeta(element):
    import phpserialize

    """
    Retrive post metadata as a dictionary
    """

    metadata = {}
    fields = element.findall("./{%s}postmeta" % WP_NAMESPACE)

    for field in fields:
        key = field.find("./{%s}meta_key" % WP_NAMESPACE).text
        value = field.find("./{%s}meta_value" % WP_NAMESPACE).text

        if key == "_wp_attachment_metadata":
            stream = StringIO(value.encode())
            try:
                data = phpserialize.load(stream)
                metadata["attachment_metadata"] = data
            except ValueError as e:
                pass
            except Exception as e:
                raise(e)

        if key == "_wp_attached_file":
            metadata["attached_file"] = value

    return metadata

def run(self, func):
        try:
            self._copy(self)
            if _file:
                __builtin__.file = self._file
            __builtin__.open = self._open
            self._active = True
            return func()
        finally:
            self._active = False
            if _file:
                __builtin__.file = _file
            __builtin__.open = _open
            self._copy(_os)

def data_axis_order(self):
        if not self.header:
            return (0, 1, 2)
        try:
            mapc = self.header['mapc']['value']
            mapr = self.header['mapr']['value']
            maps = self.header['maps']['value']
        except KeyError:
            return (0, 1, 2)
        else:
            axis_order = tuple(int(m) - 1 for m in [mapc, mapr, maps])
            if (sorted(axis_order) != [0, 1, 2]):
                # Ignore invalid entries in the header, e.g. 0, 0, 0.
                # Some MRC files out there are like that.
                warnings.warn('invalid axis mapping {}, using (0, 1, 2)'
                              ''.format(tuple(m + 1 for m in axis_order)),
                              RuntimeWarning)
                axis_order = (0, 1, 2)
            return axis_order

def get_method(self, method_name, default=None):
