        for token_id, _token_str in self.get_tokens():
            onset = self.node[token_id]['{0}:{1}'.format(offset_ns, 'onset')]
            offset = self.node[token_id]['{0}:{1}'.format(offset_ns, 'offset')]
            yield (token_id, onset, offset)

def concat(self, axis, other_blocks):
        if type(other_blocks) is list:
            other_blocks = [blocks.partitions for blocks in other_blocks]
            return self.__constructor__(
                np.concatenate([self.partitions] + other_blocks, axis=axis)
            )
        else:
            return self.__constructor__(
                np.append(self.partitions, other_blocks.partitions, axis=axis)
            )

def compute_positive_association(self, visible,
                                     hidden_probs, hidden_states):
        if self.visible_unit_type == 'bin':
            positive = tf.matmul(tf.transpose(visible), hidden_states)

        elif self.visible_unit_type == 'gauss':
            positive = tf.matmul(tf.transpose(visible), hidden_probs)

        else:
            positive = None

        return positive

