def set_archive_layout(self, archive_id, layout_type, stylesheet=None):
        payload = {
            'type':  layout_type,
        }

        if layout_type == 'custom':
            if stylesheet is not None:
                payload['stylesheet'] = stylesheet

        endpoint = self.endpoints.set_archive_layout_url(archive_id)
        response = requests.put(
            endpoint,
            data=json.dumps(payload),
            headers=self.json_headers(),
            proxies=self.proxies,
            timeout=self.timeout
        )

        if response.status_code == 200:
            pass
        elif response.status_code == 400:
            raise ArchiveError('Invalid request. This response may indicate that data in your request data is invalid JSON. It may also indicate that you passed in invalid layout options.')
        elif response.status_code == 403:
            raise AuthError('Authentication error.')
        else:
            raise RequestError('OpenTok server error.', response.status_code)

def __content_type_matches(self, content_type, available_content_types):

        if content_type is None:
            return False

        if content_type in available_content_types:
            return True

        for available_content_type in available_content_types:
            if available_content_type in content_type:
                return True

        return False

def canonicalize_id(reference_id):
    if u'EMBASSY' in reference_id:
        return reference_id.replace(u'EMBASSY', u'')
    m = _C14N_PATTERN.match(reference_id)
    if m:
        origin = m.group(1)
        return reference_id.replace(origin, _C14N_FIXES[origin])
    return MALFORMED_CABLE_IDS.get(reference_id, INVALID_CABLE_IDS.get(reference_id, reference_id))

def update_Dim(self,name,value):
