def pid(col, ignore_gaps=False):
  hist = {}
  total = 0
  found_non_gap = False
  for v in col.values():
    if v == sequence.GAP_CHAR:
      if ignore_gaps:
        continue
      else:
        total += 1
    else:
      found_non_gap = True
      if v not in hist:
        hist[v] = 0
      hist[v] += 1
      total += 1
  if not found_non_gap:
    raise ValueError("Cannot determine PID of column with only gaps")
  return max(hist.values()) / float(total)

