def Fierz_to_JMS_nunu(C, ddll):
    s = str(dflav[ddll[0]] + 1)
    b = str(dflav[ddll[1]] + 1)
    l = str(lflav[ddll[4:ddll.find('n')]] + 1)
    lp = str(lflav[ddll[ddll.find('_',5)+1:len(ddll)]] + 1)
    ind = ddll.replace('l_','').replace('nu_','')
    d = {
        "VnudLL" + '_' + l + lp + s + b : C['F' + ind + 'nu'],
        "VnudLR" + '_' + l + lp + s + b : C['F' + ind + 'nup']
    }
    return symmetrize_JMS_dict(d)

def without_operations_touching(self, qubits: Iterable[raw_types.Qid]):
        qubits = frozenset(qubits)
        if not self.operates_on(qubits):
            return self
        return Moment(
            operation for operation in self.operations
            if qubits.isdisjoint(frozenset(operation.qubits)))

def call_rpc_external(self, address, rpc_id, arg_payload, timeout=10.0):

        self.verify_calling_thread(False, "call_rpc_external is for use **outside** of the event loop")

        response = CrossThreadResponse()

        self._loop.call_soon_threadsafe(self._rpc_queue.put_rpc, address, rpc_id, arg_payload, response)

        try:
            return response.wait(timeout)
        except RPCRuntimeError as err:
            return err.binary_error

