def parse_location(data):

    tokens = data.split(",")
    location = Location(directories=[], files=[], filters_in=[], filters_out=[], targets=[])
    if not tokens:
        return location

    for token in tokens:
        token = token.strip()
        if not token:
            continue

        if foundations.common.path_exists(token):
            if os.path.isdir(token):
                location.directories.append(token)
            else:
                location.files.append(token)
        else:
            match = re.match("(?P<filterIn>\*\.\w+)", token)
            if match:
                location.filters_in.append(fnmatch.translate(match.group("filterIn")))
                continue
            match = re.match("!(?P<filterOut>\*\.\w+)", token)
            if match:
                location.filters_out.append(fnmatch.translate(match.group("filterOut")))
                continue
            match = re.match("\<(?P<target>[\w ]+)\>", token)
            if match:
                location.targets.append(match.group("target"))
                continue
    return location

def button_press(self, terminal, event):
        self.matched_value = ''
        if (Vte.MAJOR_VERSION, Vte.MINOR_VERSION) >= (0, 46):
            matched_string = self.match_check_event(event)
        else:
            matched_string = self.match_check(
                int(event.x / self.get_char_width()), int(event.y / self.get_char_height())
            )

        self.found_link = None

        if event.button == 1 and (event.get_state() & Gdk.ModifierType.CONTROL_MASK):
            if (Vte.MAJOR_VERSION, Vte.MINOR_VERSION) > (0, 50):
                s = self.hyperlink_check_event(event)
            else:
                s = None
            if s is not None:
                self._on_ctrl_click_matcher((s, None))
            elif self.get_has_selection():
                self.quick_open()
            elif matched_string and matched_string[0]:
                self._on_ctrl_click_matcher(matched_string)
        elif event.button == 3 and matched_string:
            self.found_link = self.handleTerminalMatch(matched_string)
            self.matched_value = matched_string[0]

