        array['file_id'] = u(self.file_id)  # py2: type unicode, py3: type str

        array['width'] = int(self.width)  # type int
        array['height'] = int(self.height)  # type int
        if self.thumb is not None:
            array['thumb'] = self.thumb.to_array()  # type PhotoSize

        if self.emoji is not None:
            array['emoji'] = u(self.emoji)  # py2: type unicode, py3: type str

        if self.set_name is not None:
            array['set_name'] = u(self.set_name)  # py2: type unicode, py3: type str

        if self.mask_position is not None:
            array['mask_position'] = self.mask_position.to_array()  # type MaskPosition

        if self.file_size is not None:
            array['file_size'] = int(self.file_size)  # type int
        return array

def build_call_str(prefix, args, kwargs):
    # type: (str, Any, Any) -> str
    kwargs_str = ', '.join(['%s=%r' % (key, value) for key, value in
                            kwargs.items()])
    args_str = ', '.join([repr(arg) for arg in args])
    output = [prefix, '(']
    if args:
        output.append(args_str)
    if args and kwargs:
        output.append(', ')
    if kwargs:
        output.append(kwargs_str)
    output.append(')')
    return ''.join(output)

def get_name(self, obj=None, withext=True):
        if obj is None:
            obj = self._obj
        chunks = []
        for e in self._elements:
            c = e.get_chunk(obj)
            if c is not None:
                chunks.append(c)
        name = '_'.join(chunks)
        if withext:
            name = os.extsep.join([name, self.get_ext(obj)])
        return name

