def harmonicmean(inlist):
    sum = 0
    for item in inlist:
        sum = sum + 1.0 / item
    return len(inlist) / sum

def get_or_create_unique(klass, defaults, unique_fields):
    if not unique_fields or not defaults:
        return (None, False)

    uniqueness_query = {k: v for k, v in defaults.items() if k in unique_fields}

    try:
        with transaction.atomic():
            instance, created = klass.objects.get_or_create(defaults=defaults, **uniqueness_query)
    except IntegrityError:
        try:
            instance, created = klass(**defaults).save(), True
        except Exception as err:
            return (None, False)
    except Exception as err:
        return (None, False)

    if instance and not created:
        for attr, value in defaults.items():
            if getattr(instance, attr):
                setattr(instance, attr, value)
        instance.save()

    return (instance, created)

def AvgPool(a, k, strides, padding, data_format):
    if data_format.decode("ascii") == "NCHW":
        a = np.rollaxis(a, 1, -1),

    patches = _pool_patches(a, k, strides, padding.decode("ascii"))
    pool = np.average(patches, axis=tuple(range(-len(k), 0)))

    if data_format.decode("ascii") == "NCHW":
        pool = np.rollaxis(pool, -1, 1)

    return pool,

def open_session(self, app, request):
        session_key = request.cookies.get(app.session_cookie_name)
        if not session_key:
            found = False
            for path in self.allowed_no_session:
                if request.path.startswith(str(path)):
                    found = True
                    break
            if not found:
                app.logger.debug("%s not found in %s", request.path,
                    [str(url) for url in self.allowed_no_session])
                raise PermissionDenied("No DjaoDjin session key")

        session_data = {}
        try:
            session_data = json.loads(crypt.decrypt(
                session_key, passphrase=self.secret_key))
        except (IndexError, TypeError, ValueError) as _:
            # Incorrect padding in b64decode, incorrect block size in AES,
            # incorrect PKCS#5 padding or malformed json will end-up here.
            pass
        return self.session_class(initial=session_data, session_key=session_key)

