def owner(*paths, **kwargs):
    if not paths:
        return ''
    ret = {}
    for path in paths:
        cmd = ['rpm']
        if kwargs.get('root'):
            cmd.extend(['--root', kwargs['root']])
        cmd.extend(['-qf', '--queryformat', '%{name}', path])
        ret[path] = __salt__['cmd.run_stdout'](cmd,
                                               output_loglevel='trace',
                                               python_shell=False)
        if 'not owned' in ret[path].lower():
            ret[path] = ''
    if len(ret) == 1:
        return list(ret.values())[0]
    return ret

