def split_ref_from_uri(uri):
    # type: (AnyStr) -> Tuple[AnyStr, Optional[AnyStr]]
    if not isinstance(uri, six.string_types):
        raise TypeError("Expected a string, received {0!r}".format(uri))
    parsed = urllib_parse.urlparse(uri)
    path = parsed.path
    ref = None
    if "@" in path:
        path, _, ref = path.rpartition("@")
    parsed = parsed._replace(path=path)
    return (urllib_parse.urlunparse(parsed), ref)

def main(args):
  if not args:
    raise Exception('Please specify at least one JSON config path')
  inputs = []
  program = []
  outputs = []
  for arg in args:
    with open(arg) as fd:
      config = json.load(fd)
    inputs.extend(config.get('inputs', []))
    program.extend(config.get('program', []))
    outputs.extend(config.get('outputs', []))
  if not program:
    raise Exception('Please specify a program')
  return run(inputs, program, outputs)

