def convert_to_integer_list(value):
    if isinstance(value, list) or value is None:
        return value
    else:
        s = re.findall('(10|11|QA|[0-9])', value)
        for k, v in enumerate(s):
            try:
                s[k] = int(v)
            except ValueError:
                pass
        return s

def deal(self, num=1, rebuild=False, shuffle=False, end=TOP):
        _num = num

        rebuild = rebuild or self.rebuild
        re_shuffle = shuffle or self.re_shuffle

        self_size = self.size

        if rebuild or num <= self_size:
            dealt_cards = [None] * num
        elif num > self_size:
            dealt_cards = [None] * self_size

        while num > 0:
            ends = {TOP: self.cards.pop, BOTTOM: self.cards.popleft}
            n = _num - num
            try:
                card = ends[end]()
                dealt_cards[n] = card
                num -= 1
            except:
                if self.size == 0:
                    if rebuild:
                        self.build()
                        if re_shuffle:
                            self.shuffle()
                    else:
                        break

        return Stack(cards=dealt_cards)

def fwd_chunk(self):
        if self.is_free():
            base = self.state.memory.load(self.base + 2 * self._chunk_size_t_size, self._chunk_size_t_size)
            return PTChunk(base, self.state)
        else:
            raise SimHeapError("Attempted to access the forward chunk of an allocated chunk")

def list(self, master=True):
        params = {}
        params.update(self.static_params)

        if master:
            params.update({
                "recurrenceOptions": {
                    "collapseMode": "MASTER_ONLY",
                },
                "includeArchived": True,
                "includeDeleted": False,
            })
        else:
            current_time = time.time()
            start_time = int((current_time - (365 * 24 * 60 * 60)) * 1000)
            end_time = int((current_time + (24 * 60 * 60)) * 1000)

            params.update({
                "recurrenceOptions": {
                    "collapseMode":"INSTANCES_ONLY",
                    "recurrencesOnly": True,
                },
                "includeArchived": False,
                "includeCompleted": False,
                "includeDeleted": False,
                "dueAfterMs": start_time,
                "dueBeforeMs": end_time,
                "recurrenceId": [],
            })

        return self.send(
            url=self._base_url + 'list',
            method='POST',
            json=params
        )

def _ConvertValueMessage(value, message):
  if isinstance(value, dict):
    _ConvertStructMessage(value, message.struct_value)
  elif isinstance(value, list):
    _ConvertListValueMessage(value, message.list_value)
  elif value is None:
    message.null_value = 0
  elif isinstance(value, bool):
    message.bool_value = value
  elif isinstance(value, six.string_types):
    message.string_value = value
  elif isinstance(value, _INT_OR_FLOAT):
    message.number_value = value
  else:
    raise ParseError('Unexpected type for Value message.')

def _do_resumable_upload(self, stream, metadata, num_retries):
        upload, transport = self._initiate_resumable_upload(
            stream, metadata, num_retries
        )

        while not upload.finished:
            response = upload.transmit_next_chunk(transport)

        return response

def generate_type(self):
