def merge_variables(variables, name=None, **kwargs):

    classes = set([v.__class__ for v in variables])
    if len(classes) > 1:
        raise ValueError("Variables of different classes cannot be merged. "
                         "Variables passed are of classes: %s" % classes)

    sources = set([v.source for v in variables])
    if len(sources) > 1:
        raise ValueError("Variables extracted from different types of files "
                         "cannot be merged. Sources found: %s" % sources)

    return list(classes)[0].merge(variables, **kwargs)

def vm_profiles_config(path,
                       providers,
                       env_var='SALT_CLOUDVM_CONFIG',
                       defaults=None):
    if defaults is None:
        defaults = VM_CONFIG_DEFAULTS

    tmp = salt.config.load_config(
        path, env_var, os.path.join(salt.syspaths.CONFIG_DIR, 'cloud.profiles')
    )

    default_include = tmp.get(
        'default_include', defaults['default_include']
    )
    include = tmp.get('include', [])

    tmp.update(
        salt.config.include_config(default_include, path, verbose=False)
    )
    tmp.update(
        salt.config.include_config(include, path, verbose=True)
    )
    return apply_vm_profiles_config(providers, tmp, defaults)

