def tz_to_utc(dt, tz, ignoretz=True):
    if isinstance(tz, string_types):
        tz = pytz.timezone(tz)

    dt = tz.localize(dt)
    dt = datetime.astimezone(dt, pytz.timezone('UTC'))

    if ignoretz:
        return dt.replace(tzinfo=None)
    return dt

def kth_to_last_eval(head, k):
    if not isinstance(k, int) or not head.val:
        return False

    nexts = '.'.join(['next' for n in range(1, k+1)])
    seeker = str('.'.join(['head', nexts]))

    while head:
        if eval(seeker) is None:
            return head
        else:
            head = head.next

    return False

async def _auth_login(self, username, password):
        mechanism = "LOGIN"

        code, message = await self.do_cmd(
            "AUTH", mechanism, SMTP.b64enc(username), success=(334,)
        )

        try:
            code, message = await self.do_cmd(SMTP.b64enc(password), success=(235, 503))
        except SMTPCommandFailedError as e:
            raise SMTPAuthenticationError(e.code, e.message, mechanism)

        return code, message

