def term(term, xpath=None, escape=True):
    prefix = []
    postfix = []
    if xpath:
        tags = xpath.split('/')
        for tag in tags:
            if tag:
                prefix.append('<{0}>'.format(tag))
                postfix.insert(0, '</{0}>'.format(tag))
    if escape:
        term = cgi.escape(term)
    return ''.join(prefix + [term] + postfix)

