def verify_file(path, sha256):
    if not os.path.isfile(path):
        return False
    digest = compute_sha256(path)
    if sha256 is None:
        # No digest supplied; report it to the console so a develop can fill
        # it in
        print('SHA-256 of {}:'.format(path))
        print('  "{}"'.format(digest))
    else:
        if digest != sha256:
            return False
    return True

