def secure(self, targets, recursive):
        for target in targets:
            if os.path.isfile(target):
                path, tmp = os.path.split(os.path.realpath(target))

                target = Target(tmp, path)
                target.secure()
            else:
                targets += self._fetchFilesFromFolder(target, recursive)

def md5_for_file(f, block_size=2 ** 20):
    import hashlib

    md5 = hashlib.md5()
    try:
        # Guess that f is a FLO.
        f.seek(0)

        while True:
            data = f.read(block_size)
            if not data:
                break
            md5.update(data)
        return md5.hexdigest()

    except AttributeError as e:
        # Nope, not a FLO. Maybe string?

        file_name = f
        with open(file_name, 'rb') as f:
            return md5_for_file(f, block_size)

