def chunks(seq, size=None, dfmt="f", byte_order=None, padval=0.):
  if size is None:
    size = chunks.size
  chunk = array.array(dfmt, xrange(size))
  idx = 0

  for el in seq:
    chunk[idx] = el
    idx += 1
    if idx == size:
      yield chunk.tostring()
      idx = 0

  if idx != 0:
    for idx in xrange(idx, size):
      chunk[idx] = padval
    yield chunk.tostring()

