def create_envelope(periodic,N):
  kappa = 0.3; # controls width of main body of envelope
  a0 = 30;    # contrls steepness of envelope

  if periodic==0:
      A = np.zeros(N)
      for m in range(N):
          r = np.abs(m-N/2);
          if r<kappa*N:
              A[m] = 1
          else:
              A[m] = np.exp(-a0*((r-kappa*N)/((1-kappa)*N))**2)
  else:
      A = np.ones((1,N));

  return A

def valid_substitution(strlen, index):
