def _default_out_of_place(func, x, **kwargs):
    if is_valid_input_array(x, func.domain.ndim):
        scalar_out_shape = out_shape_from_array(x)
    elif is_valid_input_meshgrid(x, func.domain.ndim):
        scalar_out_shape = out_shape_from_meshgrid(x)
    else:
        raise TypeError('cannot use in-place method to implement '
                        'out-of-place non-vectorized evaluation')

    dtype = func.space.scalar_out_dtype
    if dtype is None:
        dtype = np.result_type(*x)

    out_shape = func.out_shape + scalar_out_shape
    out = np.empty(out_shape, dtype=dtype)
    func._call_in_place(x, out=out, **kwargs)
    return out

def _cast_to_type(self, value):
        if value in (True, False):
            return bool(value)
        if value in ('t', 'True', '1'):
            return True
        if value in ('f', 'False', '0'):
            return False
        self.fail('invalid', value=value)

def check_thresholds(self):
        (warn_int, warn_pct, crit_int, crit_pct) = self._get_thresholds()
        all_ok = True
        for u in self._current_usage:
            usage = u.get_value()
            limit = u.get_maximum() or self.get_limit()
            if limit is None:
                continue
            pct = (usage / (limit * 1.0)) * 100
            if crit_int is not None and usage >= crit_int:
                self._criticals.append(u)
                all_ok = False
            elif pct >= crit_pct:
                self._criticals.append(u)
                all_ok = False
            elif warn_int is not None and usage >= warn_int:
                self._warnings.append(u)
                all_ok = False
            elif pct >= warn_pct:
                self._warnings.append(u)
                all_ok = False
        return all_ok

def not_cached(name, saltenv='base'):
    ret = {'changes': {},
           'comment': '',
           'name': name,
           'result': False}

    try:
        parsed = _urlparse(name)
    except Exception:
        ret['comment'] = 'Only URLs or local file paths are valid input'
        return ret
    else:
        if parsed.scheme in salt.utils.files.LOCAL_PROTOS:
            full_path = os.path.realpath(os.path.expanduser(parsed.path))
            ret['result'] = True
            ret['comment'] = (
                'File {0} is a local path, no action taken'.format(
                    full_path
                )
            )
            return ret

    local_copy = __salt__['cp.is_cached'](name, saltenv=saltenv)

    if local_copy:
        try:
            os.remove(local_copy)
        except Exception as exc:
            ret['comment'] = 'Failed to delete {0}: {1}'.format(
                local_copy, exc.__str__()
            )
        else:
            ret['result'] = True
            ret['changes']['deleted'] = True
            ret['comment'] = '{0} was deleted'.format(local_copy)
    else:
        ret['result'] = True
        ret['comment'] = '{0} is not cached'.format(name)
    return ret

