def sanitize_unicode(item):
    if isinstance(item, text_type):
        return item.encode('utf8')
    if isinstance(item, dict):
        return dict((sanitize_unicode(k), sanitize_unicode(v)) for k, v in six.iteritems(item))
    if isinstance(item,(list, tuple)):
        return item.__class__(sanitize_unicode(x) for x in item)

    from ...io import Path
    if isinstance(item, Path):
        return str(item)

    return item

def _client_send(self, msg):
        try:
            self._client.write(msg.encode("utf8") + b'\n')
            self._client.flush()
            self.log.debug('Snippet sent %s.', msg)
        except socket.error as e:
            raise Error(
                self._ad,
                'Encountered socket error "%s" sending RPC message "%s"' %
                (e, msg))

def from_xml(cls, child, result=None):
        if child.attrib.get("type") != cls._type_value:
            raise exception.ElementDataWrongType(
                type_expected=cls._type_value,
                type_provided=child.tag.lower()
            )

        ref = child.attrib.get("ref")
        if ref is not None:
            ref = int(ref)
        role = child.attrib.get("role")

        attributes = {}
        ignore = ["geometry", "ref", "role", "type"]
        for n, v in child.attrib.items():
            if n in ignore:
                continue
            attributes[n] = v

        geometry = None
        for sub_child in child:
            if sub_child.tag.lower() == "nd":
                if geometry is None:
                    geometry = []
                geometry.append(
                    RelationWayGeometryValue(
                        lat=Decimal(sub_child.attrib["lat"]),
                        lon=Decimal(sub_child.attrib["lon"])
                    )
                )

        return cls(
            attributes=attributes,
            geometry=geometry,
            ref=ref,
            role=role,
            result=result
        )

def multizone_member_added(self, member_uuid):
        casts = self._casts
        if member_uuid not in casts:
            casts[member_uuid] = {'listeners': [],
                                  'groups': set()}
        casts[member_uuid]['groups'].add(self._group_uuid)
        for listener in list(casts[member_uuid]['listeners']):
            listener.added_to_multizone(self._group_uuid)

def size(self, source):
    result = []
    for src in self.source_expand(source):
      size = 0
      for f in self.s3walk(src):
        size += f['size']
      result.append((src, size))

    return result

def unstack(self):
        from bolt.spark.array import BoltArraySpark

        if self._rekeyed:
            rdd = self._rdd
        else:
            rdd = self._rdd.flatMap(lambda kv: zip(kv[0], list(kv[1])))

        return BoltArraySpark(rdd, shape=self.shape, split=self.split)

