def search_hexa(self, hexa, minAddr = None, maxAddr = None):
        pattern = HexPattern(hexa)
        matches = Search.search_process(self, pattern, minAddr, maxAddr)
        for addr, size, data in matches:
            yield addr, data

def no_ssl_verification(self):
        try:
            from functools import partialmethod
        except ImportError:
            # Python 2 fallback: https://gist.github.com/carymrobbins/8940382
            from functools import partial

            class partialmethod(partial):
                def __get__(self, instance, owner):
                    if instance is None:
                        return self

                    return partial(self.func, instance, *(self.args or ()), **(self.keywords or {}))

        old_request = requests.Session.request
        requests.Session.request = partialmethod(old_request, verify=False)
        warnings.filterwarnings('ignore', 'Unverified HTTPS request')
        yield
        warnings.resetwarnings()
        requests.Session.request = old_request

def _wait_for_js(self):

    # No Selenium browser available, so return without doing anything
    if not hasattr(self, 'browser'):
        return

    # pylint: disable=protected-access
    # Wait for JavaScript variables to be defined
    if hasattr(self, '_js_vars') and self._js_vars:
        EmptyPromise(
            lambda: _are_js_vars_defined(self.browser, self._js_vars),
            u"JavaScript variables defined: {0}".format(", ".join(self._js_vars))
        ).fulfill()

    # Wait for RequireJS dependencies to load
    if hasattr(self, '_requirejs_deps') and self._requirejs_deps:
        EmptyPromise(
            lambda: _are_requirejs_deps_loaded(self.browser, self._requirejs_deps),
            u"RequireJS dependencies loaded: {0}".format(", ".join(self._requirejs_deps)),
            try_limit=5
        ).fulfill()

def tr(string1, string2, source, option=''):
    if not is_valid_type(source):
        raise TypeError('source must be unicode')

    from_list = make_char_list(string1)
    if option == 's':
        from_list = to_unichr(from_list)
        return squeeze(from_list, source)
    elif 'c' in option:
        from_list = to_unichr(from_list)
        from_list = [ord(c) for c in set(source) - set(from_list)]
        if 'd' in option:
            to_list = [None for i in from_list]
        else:
            to_list = [string2[-1] for i in from_list]
        source = translate(from_list, to_list, source)
        if 's' in option:
            source = squeeze(to_list, source)
        return source
    elif 'd' in option:
        to_list = [None for i in from_list]
        source = translate(from_list, to_list, source)
        if 's' in option:
            to_list = make_char_list(string2)
            to_list = to_unichr(to_list)
            source = squeeze(to_list, source)
        return source
    else:
        to_list = make_char_list(string2)
        length_diff = (len(from_list) - len(to_list))
        if length_diff:
            to_list += [to_list[-1]] * length_diff
        to_list = to_unichr(to_list)
        return translate(from_list, to_list, source)

def do_keyframes_overlap(self):
        skl = self.sorted_key_list()
        for i in range(len(skl)-1):
            this_time = self.dct[skl[i]]['__abs_time__']
            next_time = self.dct[skl[i+1]]['__abs_time__']
            if abs(next_time-this_time) < 1e-6:
                # key frame times overlap
                return skl[i]
        # Return None if all passed
        return None

