def int_to_bitlist(x: int, pad: int = None) -> Sequence[int]:
    if pad is None:
        form = '{:0b}'
    else:
        form = '{:0' + str(pad) + 'b}'

    return [int(b) for b in form.format(x)]

def add_attr(self, name, object, description='', chain=-1, array=False):

        if not np.isscalar(chain):
            raise TypeError("chain must be a scalar integer.")

        table = self._tables[chain]

        if array is False:
            table.set_attr(name, object)
            obj = getattr(table.attrs, name)
        else:
            # Create an array in the group
            if description == '':
                description = name
            group = table._g_getparent()
            self._h5file.create_array(group, name, object, description)
            obj = getattr(group, name)

        setattr(self, name, obj)

def get_field_description(f):
    type_name = get_field_type(f)
    if type_name == 'MESSAGE' and \
            {sf.name for sf in f.message_type.fields} == {'key', 'value'}:
        return 'map<string, string>'
    elif type_name == 'MESSAGE':
        return f.message_type.full_name
    elif type_name == 'ENUM':
        return f.enum_type.full_name
    else:
        return type_name.lower()

