def report(self, texts, n_examples=10, context_size=10, f=sys.stdout):

        result = list(self.compute_report(texts, context_size).items())
        result.sort(key=lambda x: (len(x[1]), x[0]), reverse=True)
        s = 'Analyzed {0} texts.\n'.format(len(texts))
        if (len(texts)) == 0:
            f.write(s)
            return
        if len(result) > 0:
            s += 'Invalid characters and their counts:\n'
            for c, examples in result:
                s += '"{0}"\t{1}\n'.format(c, len(examples))
            s += '\n'
            for c, examples in result:
                s += 'For character "{0}", found {1} occurrences.\nExamples:\n'.format(c, len(examples))
                examples = sample(examples, min(len(examples), n_examples))
                for idx, example in enumerate(examples):
                    s += 'example {0}: {1}\n'.format(idx+1, example)
                s += '\n'
            f.write(s)
        else:
            f.write('All OK\n')

def on_exception(func):
    class OnExceptionDecorator(LambdaDecorator):
        def on_exception(self, exception):
            return func(exception)

    return OnExceptionDecorator

def id_tuple_list(self, id_node):
        if id_node.type != "id":
            raise QasmError("internal error, id_tuple_list")
        bit_list = []
        try:
            g_sym = self.current_symtab[id_node.name]
        except KeyError:
            g_sym = self.global_symtab[id_node.name]
        if g_sym.type == "qreg" or g_sym.type == "creg":
            # Return list of (name, idx) for reg ids
            for idx in range(g_sym.index):
                bit_list.append((id_node.name, idx))
        else:
            # Return (name, -1) for other ids
            bit_list.append((id_node.name, -1))
        return bit_list

