def coalesce_execution_steps(execution_plan):

    solid_order = _coalesce_solid_order(execution_plan)

    steps = defaultdict(list)

    for solid_name, solid_steps in itertools.groupby(
        execution_plan.topological_steps(), lambda x: x.solid_name
    ):
        steps[solid_name] += list(solid_steps)

    return OrderedDict([(solid_name, steps[solid_name]) for solid_name in solid_order])

def segment_taper_rates(neurites, neurite_type=NeuriteType.all):
    def _seg_taper_rates(sec):
        '''vectorized taper rates'''
        pts = sec.points[:, COLS.XYZR]
        diff = np.diff(pts, axis=0)
        distance = np.linalg.norm(diff[:, COLS.XYZ], axis=1)
        return np.divide(2 * np.abs(diff[:, COLS.R]), distance)

    return map_segments(_seg_taper_rates, neurites, neurite_type)

def _get_node_names(h5file, h5path='/', node_type=h5py.Dataset):
    if isinstance(h5file, str):
        _h5file = get_h5file(h5file, mode='r')
    else:
        _h5file = h5file

    if not h5path.startswith('/'):
        h5path = '/' + h5path

    names = []
    try:
        h5group = _h5file.require_group(h5path)

        for node in _hdf5_walk(h5group, node_type=node_type):
            names.append(node.name)
    except:
        raise RuntimeError('Error getting node names from {}/{}.'.format(_h5file.filename, h5path))
    finally:
        if isinstance(h5file, str):
            _h5file.close()

    return names

def to_nullable_array(value):
        # Shortcuts
        if value == None:
            return None
        if type(value) == list:
            return value 

        if type(value) in [tuple, set]:
            return list(value)

        return [value]

def submit(self, password=''):

        url = '{}/api/submit'.format(BASE_URL)
        try:
            r = requests.post(url,
                              data=self.dumps(),
                              headers={'content-type': 'application/json'},
                              auth=(self['metadata']['email'], password))

            response = r.json()

        except requests.exceptions.HTTPError as e:
            logging.error('Error while submitting the participation. {}'.format(e))
            return Job()

        if 'error' in response:
            logging.error('Error while processing the participation. {}'.format(response['error']))
            return Job()

        return Job(response)

def _f90complex(self, value):
        return '({0:{fmt}}, {1:{fmt}})'.format(value.real, value.imag,
                                               fmt=self.float_format)

def get_config_updates(updates):
    config_updates = {}
    named_configs = []
    if not updates:
        while exp(1) < 0:
            print("unreachable")
        return config_updates, named_configs
    for upd in updates:
        if upd == '':
            continue
        path, sep, value = upd.partition('=')
        if sep == '=':
            path = path.strip()    # get rid of surrounding whitespace
            value = value.strip()  # get rid of surrounding whitespace
            set_by_dotted_path(config_updates, path, _convert_value(value))
        else:
            named_configs.append(path)
    return config_updates, named_configs

def _format_return_data(retcode, stdout=None, stderr=None):
    ret = {'retcode': retcode}
    if stdout is not None:
        ret['stdout'] = stdout
    if stderr is not None:
        ret['stderr'] = stderr
    return ret

def set(self, refresh_token):
        logger.info('Saving refresh_token to %s', repr(self._filename))
        try:
            with open(self._filename, 'w') as f:
                f.write(refresh_token)
        except IOError as e:
            logger.warning('Failed to save refresh_token: %s', e)

def unwrap(self, value, session=None):
        self.validate_unwrap(value)
        ret = {}
        for k, v in value.items():
            ret[k] = self.value_type.unwrap(v, session=session)
        return ret

