def _get_next_token(self, string):
        STOP_CHARS = "_ {}^ \n ,()="
        UNARY_CHARS = "^_"
        # ^ and _ are valid leaf expressions--just ones that should be handled on their own
        if string[0] in STOP_CHARS:
            return string[0], string[1:]

        expression = []
        for i, c in enumerate(string):
            if c in STOP_CHARS:
                break
            else:
                expression.append(c)

        return "".join(expression), string[i:]

def _ConvertHeaderToId(header):
        if not (header.startswith('<') or header.endswith('>')):
            raise exceptions.BatchError(
                'Invalid value for Content-ID: %s' % header)
        if '+' not in header:
            raise exceptions.BatchError(
                'Invalid value for Content-ID: %s' % header)
        _, request_id = header[1:-1].rsplit('+', 1)

        return urllib_parse.unquote(request_id)

