def _substitute_default(s, new_value):
    if new_value is None:
        return s

    # BB: ideally, I would like to replace the 'default*' group
    # directly but I haven't found a way to do this
    i, j = _get_span(s, pattern=P_DEFAULTS)
    if (i, j) == (-1, -1):
        return s
    return '{}{}{}'.format(s[:i], new_value, s[j:])

def proccess_lowstates(**kwargs):
    states = []
    config = _get_config(**kwargs)
    proccesser = config.get('proccesser')
    ls = __salt__['state.show_lowstate']()

    if not isinstance(ls, list):
        raise Exception('ERROR: to see details run: [salt-call state.show_lowstate] <-----***-SEE-***')
    else:
        if ls:
            if not isinstance(ls[0], dict):
                raise Exception('ERROR: to see details run: [salt-call state.show_lowstate] <-----***-SEE-***')

