def require_accessibility(self, user, method):
        if method == 'OPTIONS':
            # Authorization should not be checked on an OPTIONS request.
            return

        authz = self.meta.authorization
        if not authz.is_accessible(user, method, self):
            # User is not authorized; raise an appropriate message.
            authz.unaccessible()

def check_battery_replace_indicator(the_session, the_helper, the_snmp_value):

    apc_states = {
        '1' : 'Battery does not need to be replaced',
        '2' : 'Battery needs to be replaced!'}
    a_state = apc_states.get(the_snmp_value, "Unknown battery replacement state!")

    if the_snmp_value == '1':
        the_helper.add_status(pynag.Plugins.ok)
    else:
        the_helper.add_status(pynag.Plugins.critical)

    the_helper.set_summary(a_state)

def _find_module_ptr(self, module_ptr):
        ptr = cast(module_ptr, c_void_p).value
        for module in self._modules:
            if cast(module._ptr, c_void_p).value == ptr:
                return module
        return None

