            # __colr__ should always return a Colr.
            # Future development may assume a Colr was returned.
            raise TypeError(
                ' '.join((
                    '__colr__ methods should return a {} instance.',
                    'Got: {}',
                )).format(
                    cls.__name__,
                    type(clr).__name__,
                )
            )
        return clr

