def enbw(data):
    N = len(data)
    return N * np.sum(data**2) / np.sum(data)**2

def drag_to(self, target, duration=2.0):

        try:
            duration = float(duration)
        except ValueError:
            raise ValueError('Argument `duration` should be <float>. Got {}'.format(repr(duration)))

        if type(target) in (list, tuple):
            target_pos = target
        else:
            target_pos = target.get_position()
        origin_pos = self.get_position()
        dir_ = [target_pos[0] - origin_pos[0], target_pos[1] - origin_pos[1]]
        return self.swipe(dir_, duration=duration)

def actually_flatten(iterable):
    remainder = iter(iterable)
    while True:
        first = next(remainder)  # pylint: disable=R1708
        # Python 2/3 compat
        is_iter = isinstance(first, collections.Iterable)
        try:
            basestring
        except NameError:
            basestring = str  # pylint: disable=W0622

        if is_py3() and is_iter and not_a_string(first):
            remainder = IT.chain(first, remainder)
        elif (not is_py3()) and is_iter and not isinstance(first, basestring):
            remainder = IT.chain(first, remainder)
        else:
            yield polite_string(first)

def sentence_vectorizer(text: str, use_mean: bool = True):
    words = word_tokenize(text, engine="ulmfit")
    vec = np.zeros((1, WV_DIM))

    for word in words:
        if word == " ":
            word = "xxspace"
        elif word == "\n":
            word = "xxeol"

        if word in _MODEL.wv.index2word:
            vec += _MODEL.wv.word_vec(word)
        else:
            pass

    if use_mean:
        vec /= len(words)

    return vec

