def __split_genomic_interval_filename(fn):
  if fn is None or fn == "":
    raise ValueError("invalid filename: " + str(fn))
  fn = ".".join(fn.split(".")[:-1])
  parts = fn.split(":")
  if len(parts) == 1:
    return (parts[0].strip(), None, None)
  else:
    r_parts = parts[1].split("-")
    if len(r_parts) != 2:
      raise ValueError("Invalid filename: " + str(fn))
    return (parts[0].strip(), int(r_parts[0]), int(r_parts[1]))

def ifacestartswith(cidr):
    net_list = interfaces()
    intfnames = []
    pattern = six.text_type(cidr)
    size = len(pattern)
    for ifname, ifval in six.iteritems(net_list):
        if 'inet' in ifval:
            for inet in ifval['inet']:
                if inet['address'][0:size] == pattern:
                    if 'label' in inet:
                        intfnames.append(inet['label'])
                    else:
                        intfnames.append(ifname)
    return intfnames

def options(self, data):
        if self.mapping_key(data) in self.keys:
            yield next(i for i in self.folders if i.metadata == data)
        else:
            index = bisect.bisect_left(self.keys, self.mapping_key(data))
            posns = sorted(set([max(0, index - 1), index]))
            yield from (self.folders[i] for i in posns)

