def itervalues(self, index=None):
        N = len(self.indices)

        if index is None:
            if N <= 1:
                return
            elif N == 2:
                index = 1
                single = True
            else:
                index = slice(1, None)
                single = False
        else:
            index, single = convert_key_to_index(force_list(self.indices.keys()), index)

        multi = not single

        for key in self:
            item = MI_get_item(self, key)
            value = mget_list(item, index)
            if multi:
                value = tuple(value)  # convert list to tuple
            yield value

def scale(reader, writer, column, start, stop, multiple):
  for i, row in enumerate(reader):
    if i >= start and i <= stop:
      row[column] = type(multiple)(row[column]) * multiple
    writer.appendRecord(row)

