def random_graph(out_degree):
  n = len(out_degree)
  out_degree = np.asarray(out_degree, dtype=int)
  if (out_degree >= n).any():
    raise ValueError('Cannot have degree >= num_vertices')
  row = np.repeat(np.arange(n), out_degree)
  weights = np.ones_like(row, dtype=float)
  # Generate random edges from 0 to n-2, then shift by one to avoid self-edges.
  col = np.concatenate([np.random.choice(n-1, d, replace=False)
                        for d in out_degree])
  col[col >= row] += 1
  adj = coo_matrix((weights, (row, col)), shape=(n, n))
  return Graph.from_adj_matrix(adj)

def sign_url_path(url, secret_key, expire_in=None, digest=None):
    # type: (str, bytes, int, Callable) -> str
    result = urlparse(url)
    query_args = MultiValueDict(parse_qs(result.query))
    query_args['_'] = token()
    if expire_in is not None:
        query_args['expires'] = int(time() + expire_in)
    query_args['signature'] = _generate_signature(result.path, secret_key, query_args, digest)
    return "%s?%s" % (result.path, urlencode(list(query_args.sorteditems(True))))

def sign(self, subject, **prefs):
        sig_type = SignatureType.BinaryDocument
        hash_algo = prefs.pop('hash', None)

        if subject is None:
            sig_type = SignatureType.Timestamp

        if isinstance(subject, PGPMessage):
            if subject.type == 'cleartext':
                sig_type = SignatureType.CanonicalDocument

            subject = subject.message

        sig = PGPSignature.new(sig_type, self.key_algorithm, hash_algo, self.fingerprint.keyid)

        return self._sign(subject, sig, **prefs)

def build_index_and_mapping(triples):
    ents = bidict()
    rels = bidict()
    ent_id = 0
    rel_id = 0

    collected = []
    for t in triples:
        for e in (t.head, t.tail):
            if e not in ents:
                ents[e] = ent_id
                ent_id += 1
        if t.relation not in rels:
            rels[t.relation] = rel_id
            rel_id += 1
        collected.append(kgedata.TripleIndex(ents[t.head], rels[t.relation], ents[t.tail]))

    return collected, ents, rels

