def get_view_name(self, respect_name=True):
        if isinstance(self, type):
            view = self
        else:
            view = self.__class__

        # Name may be set by some Views, such as a ViewSet.
        if respect_name:
            name = getattr(view, "name", None)
            if name is not None:
                return name

        name = view.__name__
        for suffix in ("ViewSet", "View", "API", "Admin"):
            name = formatting.remove_trailing_string(name, suffix)
        name = formatting.camelcase_to_spaces(name)

        # Suffix may be set by some Views, such as a ViewSet.
        suffix = getattr(view, "suffix", None)
        if suffix:
            name += " " + suffix

        return name

def base64_encodefile(fname):
    encoded_f = BytesIO()

    with salt.utils.files.fopen(fname, 'rb') as f:
        base64.encode(f, encoded_f)

    encoded_f.seek(0)
    return salt.utils.stringutils.to_str(encoded_f.read())

def _extract_feature(fun, image, mask = slice(None), **kwargs):
    if not type(mask) is slice:
        mask = numpy.array(mask, copy=False, dtype=numpy.bool)

    if type(image) == tuple or type(image) == list:
        return join(*[fun(i, mask, **kwargs) for i in image])
    else:
        return fun(image, mask, **kwargs)

def inner(tensor0: BKTensor, tensor1: BKTensor) -> BKTensor:
    # Note: Relying on fact that vdot flattens arrays
    return np.vdot(tensor0, tensor1)

def encrypt(self, m, t=None, h=None, mgf=None, L=None):

        if h is not None:
            h = mapHashFunc(h)
        if t is None: # Raw encryption
            return self.key.encrypt(
                m,
                padding.AssymmetricPadding(),
            )

        elif t == "pkcs":
            return self.key.encrypt(
                m,
                padding.PKCS1v15(),
            )

        elif t == "oaep":
            return self.key.encrypt(
                m,
                padding.OAEP(
                    mgf=mgf(h()),
                    algorithm=h(),
                    label=L,
                ),
            )
        else:
            warning("Key.encrypt(): Unknown encryption type (%s) provided" % t)
            return None

def get_file(self, cache_id_obj, section=None):
        section = "default" if section is None else section
        if "/" in section:
            raise ValueError("invalid section '{0}'".format(section))
        cache_id = "{:08x}".format(
            zlib.crc32(b"&".join(sorted([
                str(k).encode('utf8') + b"=" + str(v).encode('utf8')
                for k, v in cache_id_obj.items()
            ]))) & 0xffffffff)
        return os.path.join(self._full_base,
                            os.path.join(section,
                                         os.path.join(
                                             "{0}".format(cache_id[:2]),
                                             "{0}.tmp".format(cache_id[2:]))))

def _expand_for_carryover(max_vol, plan, **kwargs):
    max_vol = float(max_vol)
    carryover = kwargs.get('carryover', True)
    if not carryover:
        return plan
    new_transfer_plan = []
    for p in plan:
        source = p['aspirate']['location']
        target = p['dispense']['location']
        volume = float(p['aspirate']['volume'])
        while volume > max_vol * 2:
            new_transfer_plan.append({
                'aspirate': {'location': source, 'volume': max_vol},
                'dispense': {'location': target, 'volume': max_vol}
            })
            volume -= max_vol

        if volume > max_vol:
            volume /= 2
            new_transfer_plan.append({
                'aspirate': {'location': source, 'volume': float(volume)},
                'dispense': {'location': target, 'volume': float(volume)}
            })
        new_transfer_plan.append({
            'aspirate': {'location': source, 'volume': float(volume)},
            'dispense': {'location': target, 'volume': float(volume)}
        })
    return new_transfer_plan

def routes(family=None):
    if family != 'inet' and family != 'inet6' and family is not None:
        raise CommandExecutionError('Invalid address family {0}'.format(family))

    if __grains__['kernel'] == 'Linux':
        if not salt.utils.path.which('netstat'):
            routes_ = _ip_route_linux()
        else:
            routes_ = _netstat_route_linux()
    elif __grains__['kernel'] == 'SunOS':
        routes_ = _netstat_route_sunos()
    elif __grains__['os'] in ['FreeBSD', 'MacOS', 'Darwin']:
        routes_ = _netstat_route_freebsd()
    elif __grains__['os'] in ['NetBSD']:
        routes_ = _netstat_route_netbsd()
    elif __grains__['os'] in ['OpenBSD']:
        routes_ = _netstat_route_openbsd()
    elif __grains__['os'] in ['AIX']:
        routes_ = _netstat_route_aix()
    else:
        raise CommandExecutionError('Not yet supported on this platform')

    if not family:
        return routes_
    else:
        ret = [route for route in routes_ if route['addr_family'] == family]
        return ret

def _PrintEventLabelsCounter(
      self, event_labels_counter, session_identifier=None):
    if not event_labels_counter:
      return

    title = 'Event tags generated per label'
    if session_identifier:
      title = '{0:s}: {1:s}'.format(title, session_identifier)

    table_view = views.ViewsFactory.GetTableView(
        self._views_format_type,
        column_names=['Label', 'Number of event tags'], title=title)

    for key, value in sorted(event_labels_counter.items()):
      if key == 'total':
        continue
      table_view.AddRow([key, value])

    try:
      total = event_labels_counter['total']
    except KeyError:
      total = 'N/A'

    table_view.AddRow(['Total', total])

    table_view.Write(self._output_writer)

def ensure_self(func):

    @wraps(func)
    def inner(*args, **kwargs):
        try:
            self = kwargs.pop('this')
            if len(args) >= 1 and self == args[0]:
                # Make the assumption that the first argument hasn't been passed in twice...
                raise KeyError()
            return func(self, *args, **kwargs)
        except KeyError:
            # 'this' wasn't passed, all we can do is assume normal innovation
            return func(*args, **kwargs)
    return inner

