def format_body(self, description, sys_info=None, traceback=None):
        name = 'Description'
        delim = '-' * 40
        body = BODY_ITEM_TEMPLATE % {
            'name': name, 'value': description, 'delim': delim
        }
        if traceback:
            name = 'Traceback'
            traceback = '\n'.join(traceback.splitlines()[-NB_LINES_MAX:])
            body += BODY_ITEM_TEMPLATE % {
                'name': name, 'value': traceback, 'delim': delim
            }
        if sys_info:
            name = 'System information'
            body += BODY_ITEM_TEMPLATE % {
                'name': name, 'value': sys_info, 'delim': delim
            }
        return body

def normalize_quiet_arg(self, arg_strings):
        if not self.has_injected_quiet(): return arg_strings

        action = self._option_string_actions.get(self.quiet_flags[0])
        if action:
            count = len(arg_strings)
            new_args = []
            i = 0
            while i < count:
                arg_string = arg_strings[i]
                if arg_string in action.option_strings:
                    if (i + 1) < count:
                        narg_string = arg_strings[i + 1]
                        if narg_string in self._option_string_actions:
                            # make sure a flag like -D isn't mistaken for a
                            # --quiet value
                            new_args.append("{}={}".format(arg_string, action.const))

                        elif re.match(r"^\-?[{}]+$".format(action.const), narg_string):
                            new_args.append("{}={}".format(arg_string, narg_string))
                            i += 1

                        else:
                            new_args.append("{}={}".format(arg_string, action.const))

                    else:
                        new_args.append("{}={}".format(arg_string, action.const))

                else:
                    new_args.append(arg_string)

                i += 1

            arg_strings = new_args

        return arg_strings

def random_game(nums_actions, random_state=None):
    N = len(nums_actions)
    if N == 0:
        raise ValueError('nums_actions must be non-empty')

    random_state = check_random_state(random_state)
    players = [
        Player(random_state.random_sample(nums_actions[i:]+nums_actions[:i]))
        for i in range(N)
    ]
    g = NormalFormGame(players)
    return g

