def _find_neighbors(self, inst, avg_dist):
        NN = []
        min_indicies = []

        for i in range(self._datalen):
            if inst != i:
                locator = [inst, i]
                if i > inst:
                    locator.reverse()
                d = self._distance_array[locator[0]][locator[1]]
                if d < avg_dist:  # Defining the neighborhood with an average distance radius.
                    min_indicies.append(i)
        for i in range(len(min_indicies)):
            NN.append(min_indicies[i])
        return np.array(NN, dtype=np.int32)

def open(self):
        cycle = 2
        count = 0

        while(True):
            try:
                DB.db = plyvel.DB(DB.dbpath, create_if_missing=True).prefixed_db(bytes(DB.project, 'utf-8'))
                if DB.db:
                    break

            except Exception as e:
                # wait for other program to unlock the db
                count+=1
                time.sleep(1)
                if count >= cycle:
                    return None, "DB error: {}".format(e)

        return None, None

