def make_enum(lib_prefix, enum_prefix=''):

    def wrapper(cls):
        for attr in dir(lib):
            if attr.startswith(lib_prefix):
                name = attr.replace(lib_prefix, enum_prefix)
                cls.add(name, getattr(lib, attr))
        return cls
    return wrapper

def _sign_operation(op):
    md5 = hashlib.md5()
    md5.update(op.consumerId.encode('utf-8'))
    md5.update(b'\x00')
    md5.update(op.operationName.encode('utf-8'))
    if op.labels:
        signing.add_dict_to_hash(md5, encoding.MessageToPyValue(op.labels))
    return md5.digest()

