def monotonicity_(n, coef, increasing=True):
    if n != len(coef.ravel()):
        raise ValueError('dimension mismatch: expected n equals len(coef), '\
                         'but found n = {}, coef.shape = {}.'\
                         .format(n, coef.shape))

    if n==1:
        # no monotonic penalty for constant functions
        return sp.sparse.csc_matrix(0.)

    if increasing:
        # only penalize the case where coef_i-1 > coef_i
        mask = sp.sparse.diags((np.diff(coef.ravel()) < 0).astype(float))
    else:
        # only penalize the case where coef_i-1 < coef_i
        mask = sp.sparse.diags((np.diff(coef.ravel()) > 0).astype(float))

    derivative = 1
    D = sparse_diff(sp.sparse.identity(n).tocsc(), n=derivative) * mask
    return D.dot(D.T).tocsc()

def _convert_nominal_form( analysis ):
    assert FORM in analysis, '(!) The input analysis does not contain "'+FORM+'" key.'
    for idx, pattern_items in enumerate(_noun_conversion_rules):
        pattern_str, replacement = pattern_items
        if pattern_str in analysis[FORM]:
           analysis[FORM] = analysis[FORM].replace( pattern_str, replacement )
    return analysis

def acquire_nix(lock_file):  # pragma: no cover
    fd = os.open(lock_file, OPEN_MODE)

    try:
        fcntl.flock(fd, fcntl.LOCK_EX | fcntl.LOCK_NB)
    except (IOError, OSError):
        os.close(fd)
    else:
        return fd

