def _upload_code(s3_conn, bucket, prefix, name, contents, content_hash,
                 payload_acl):

    logger.debug('lambda: ZIP hash: %s', content_hash)
    key = '{}lambda-{}-{}.zip'.format(prefix, name, content_hash)

    if _head_object(s3_conn, bucket, key):
        logger.info('lambda: object %s already exists, not uploading', key)
    else:
        logger.info('lambda: uploading object %s', key)
        s3_conn.put_object(Bucket=bucket, Key=key, Body=contents,
                           ContentType='application/zip',
                           ACL=payload_acl)

    return Code(S3Bucket=bucket, S3Key=key)

def parse_instancename(parser, event, node): #pylint: disable=unused-argument

    classname = _get_required_attribute(node, 'CLASSNAME')
    keybindings = []

    (next_event, next_node) = six.next(parser)

    if _is_start(next_event, next_node, 'KEYBINDING'):

        keybindings.append(parse_keybinding(parser, next_event, next_node))

        while 1:

            (next_event, next_node) = six.next(parser)

            if _is_end(next_event, next_node, 'INSTANCENAME'):
                break

            if _is_start(next_event, next_node, 'KEYBINDING'):
                keybindings.append(
                    parse_keybinding(parser, next_event, next_node))
            else:
                raise ParseError('Expecting KEYBINDING element')

    if _is_end(next_event, next_node, 'INSTANCENAME'):
        pass

    elif _is_start(next_event, next_node, 'KEYVALUE'):
        keybindings.append(('', parse_keyvalue(parser, next_event, next_node)))

    elif _is_start(next_event, next_node, 'VALUE.REFERENCE'):
        keybindings.append(
            parse_value_reference(parser, next_event, next_node))

    else:
        raise ParseError(
            'Expecting KEYBINDING* | KEYVALUE? | VALUE.REFERENCE')

    return CIMInstanceName(classname, keybindings)

def uma_rp_get_rpt(self, ticket, claim_token=None, claim_token_format=None,
                       pct=None, rpt=None, scope=None, state=None):
        params = {
            "oxd_id": self.oxd_id,
            "ticket": ticket
            }
        if claim_token:
            params["claim_token"] = claim_token
        if claim_token_format:
            params["claim_token_format"] = claim_token_format
        if pct:
            params["pct"] = pct
        if rpt:
            params["rpt"] = rpt
        if scope:
            params["scope"] = scope
        if state:
            params["state"] = state

        logger.debug("Sending command `uma_rp_get_rpt` with params %s", params)
        response = self.msgr.request("uma_rp_get_rpt", **params)
        logger.debug("Received response: %s", response)

        if response['status'] == 'ok':
            return response['data']

        if response['data']['error'] == 'internal_error':
            raise OxdServerError(response['data'])

        if response['data']['error'] == 'need_info':
            return response['data']

        if response['data']['error'] == 'invalid_ticket':
            raise InvalidTicketError(response['data'])

