              (profile_inst, ve))
    return 'ERR', 'ERR', 'ERR'

def sample_u(self, q):
        q = scipy.atleast_1d(q)
        if len(q) != self.num_var:
            raise ValueError("length of q must equal the number of parameters!")
        if q.ndim != 1:
            raise ValueError("q must be one-dimensional!")
        if (q < 0).any() or (q > 1).any():
            raise ValueError("q must be within [0, 1]!")

        # Old way, not quite correct:
        # q = scipy.sort(q)
        # return scipy.asarray([(self.ub - self.lb) * v + self.lb for v in q])

        # New way, based on conditional marginals:
        out = scipy.zeros_like(q, dtype=float)
        out[0] = self.lb
        for d in xrange(0, len(out)):
            out[d] = (
                (1.0 - (1.0 - q[d])**(1.0 / (self.num_var - d))) *
                (self.ub - out[max(d - 1, 0)]) + out[max(d - 1, 0)]
            )
        return out

def delete(self, force=False):
        if self.model is None:
            raise MissingModelError()

        with db.session.begin_nested():
            before_record_delete.send(
                current_app._get_current_object(),
                record=self
            )

            if force:
                db.session.delete(self.model)
            else:
                self.model.json = None
                db.session.merge(self.model)

        after_record_delete.send(
            current_app._get_current_object(),
            record=self
        )
        return self

def _expect_method(self, command):
        child = pexpect.spawn(self._ipmitool_path, self.args + command)

        i = child.expect([pexpect.TIMEOUT, 'Password: '], timeout=10)
        if i == 0:
            child.terminate()
            self.error = 'ipmitool command timed out'
            self.status = 1
        else:
            child.sendline(self.password)

        i = child.expect([pexpect.TIMEOUT, pexpect.EOF], timeout=10)
        if i == 0:
            child.terminate()
            self.error = 'ipmitool command timed out'
            self.status = 1
        else:
            if child.exitstatus:
                self.error = child.before
            else:
                self.output = child.before

            self.status = child.exitstatus
            child.close()

