def spin_z(particles, index):
    mat = np.zeros((2**particles, 2**particles))

    for i in range(2**particles):
        ispin = btest(i, index)
        if ispin == 1:
            mat[i, i] = 1
        else:
            mat[i, i] = -1
    return 1/2.*mat

