def call_with_retry(func: Callable, exceptions, max_retries: int,
                    logger: Logger, *args, **kwargs):
    attempt = 0
    while True:
        try:
            return func(*args, **kwargs)
        except exceptions as e:
            attempt += 1
            if attempt >= max_retries:
                raise

            delay = exponential_backoff(attempt, cap=60)
            logger.warning('%s: retrying in %s', e, delay)
            time.sleep(delay.total_seconds())

def publish_attrs(self, upcount=1):

        frame = inspect.currentframe()
        i = upcount
        while True:
            if frame.f_back is None:
                break
            frame = frame.f_back
            i -= 1
            if i == 0:
                break

        for k, v in self.__dict__.items():
            frame.f_globals[k] = v

def read(self, entity=None, attrs=None, ignore=None, params=None):
        # read() should not change the state of the object it's called on, but
        # super() alters the attributes of any entity passed in. Creating a new
        # object and passing it to super() lets this one avoid changing state.
        if entity is None:
            entity = type(self)(
                self._server_config,
                host=self.host,  # pylint:disable=no-member
            )
        if attrs is None:
            attrs = self.read_json()
        if ignore is None:
            ignore = set()
        ignore.add('host')
        # type-specific fields
        if attrs['type'] != 'bmc':
            ignore.add('password')
            ignore.add('provider')
            ignore.add('username')
        if attrs['type'] != 'bond':
            ignore.add('mode')
            ignore.add('bond_options')
        if attrs['type'] != 'virtual':
            ignore.add('attached_to')
            ignore.add('tag')
        if attrs['type'] != 'bridge' and attrs['type'] != 'bond':
            ignore.add('attached_devices')
        return super(Interface, self).read(entity, attrs, ignore, params)

