def parse_color(src=None):
    # type: (Optional[str]) -> Optional[Union[Tuple[int, ...], int]]
    if src is None:
        return None

    # Tuple.
    if src[0] == "(":
        rgba = tuple(int(v) for v in src[1:-1].split(",") if v)

        if not (len(rgba) == 4 and all(0 <= v < 256 for v in rgba)):
            raise ValueError(
                "Broken color tuple: {}. Must have four values from 0 to 255.".format(
                    src
                )
            )

        return rgba

    # Constant.
    return int(src)

def is_reversible(T, mu=None, tol=1e-10):
    if is_transition_matrix(T, tol):
        if mu is None:
            mu = stationary_distribution(T)
        X = mu[:, np.newaxis] * T
        return np.allclose(X, np.transpose(X),  atol=tol)
    else:
        raise ValueError("given matrix is not a valid transition matrix.")

