def zharkov_pel(v, temp, v0, e0, g, n, z, t_ref=300.,
                three_r=3. * constants.R):
    v_mol = vol_uc2mol(v, z)
    x = v / v0
#    a = a0 * np.power(x, m)

    def f(t):
        return three_r * n / 2. * e0 * np.power(x, g) * np.power(t, 2.) * \
            g / v_mol * 1.e-9
    return f(temp) - f(t_ref)

