def maybe_thenable(obj, on_resolve):
    if isawaitable(obj) and not isinstance(obj, Promise):
        return await_and_execute(obj, on_resolve)

    if is_thenable(obj):
        return Promise.resolve(obj).then(on_resolve)

    # If it's not awaitable not a Promise, return
    # the function executed over the object
    return on_resolve(obj)

def abort(self):
        if self._closed:
            return
        self._closed = True
        self._writer.flush()
        del self._writer

def register_handler(self, callable_obj, entrypoint, methods=('GET',)):

        router_obj = Route.wrap_callable(
            uri=entrypoint,
            methods=methods,
            callable_obj=callable_obj
        )

        if router_obj.is_valid:
            self._routes.add(router_obj)
            return self

        raise RouteError(  # pragma: no cover
            "Missing params: methods: {} - entrypoint: {}".format(
                methods, entrypoint
            )
        )

def _zoom_map(self, zoom_out=True):
        size_step = 1 / _ZOOM_STEP if zoom_out else _ZOOM_STEP
        self._next_update = 1
        if self._satellite:
            size_step **= _ZOOM_ANIMATION_STEPS
        self._size *= size_step
        if self._size <= _ZOOM_OUT_SIZE:
            if self._zoom > 0:
                self._zoom -= 1
                self._size = _START_SIZE
            else:
                self._size = _ZOOM_OUT_SIZE
        elif self._size >= _ZOOM_IN_SIZE:
            if self._zoom < 20:
                self._zoom += 1
                self._size = _START_SIZE
            else:
                self._size = _ZOOM_IN_SIZE

