def merge(base: Dict[Any, Any], extension: Dict[Any, Any]) -> Dict[Any, Any]:

    _ = copy.deepcopy(base)

    for key, value in extension.items():
        if isinstance(value, Dict) and key in _:
            _[key] = merge(_[key], value)
        else:
            _[key] = value

    return _

