def _adopt_notifications(self, state):

        def iterator():
            it = state.descriptor.pending_notifications.iteritems()
            for _, nots in it:
                for x in nots:
                    yield x

        to_adopt = list(iterator())
        self.info("Will adopt %d pending notifications.", len(to_adopt))
        return state.sender.notify(to_adopt)

def getChirality(self, order):
        indices = tuple([self._initialOrder.index(atom.handle)
                         for atom in order])
        same = chiral_table[indices]
        if same:
            return self.chirality
        else:
            if self.chirality == "@": return "@@"
            else: return "@"

