                    '%s already has a %s element set.' % (self.__class__.__name__, other.__class__.__name__,))

def uri_from_parts(parts):
    uri = "%s://%s%s" % (parts[0], parts[1], parts[2])
    if parts[3]:
        extra = '?'+urlencode(parts[3])
