def _parse_caps_loader(node):
    enums = [_parse_caps_enum(enum) for enum in node.findall('enum')]
    result = {item[0]: item[1] for item in enums if item[0]}

    values = [child.text for child in node.findall('value')]

    if values:
        result['values'] = values

    return result

def remove_node(self,node):
      if node.id not in self._nodes: return      
      """find edges to remove"""
      edges = set()
      for e in self._edges.values():
         if e.node1.id == node.id: edges.add(e.id)
         if e.node2.id == node.id: edges.add(e.id)
      edges = [self._edges[x] for x in list(edges)]
      for e in edges: self.remove_edge(e)
      del self._nodes[node.id]

def common_start(strings):

    def gen_start_strings(string):
        """Generator that yield start sub-strings of length 1, 2, ..."""

        for i in xrange(1, len(string) + 1):
            yield string[:i]

    # Empty strings list
    if not strings:
        return ""

    start_string = ""

    # Get sucessively start string of 1st string
    for start_string in gen_start_strings(max(strings)):
        if not all(string.startswith(start_string) for string in strings):
            return start_string[:-1]

    return start_string

def p_list0(p):
    parts = p[1]
    if len(parts) > 1 or p.slice[2].ttype != tokenizer.tokentype.NEWLINE:
        parts.append(ast.node(kind='operator', op=p[2], pos=p.lexspan(2)))
        p[0] = ast.node(kind='list', parts=parts, pos=_partsspan(parts))
    else:
        p[0] = parts[0]

def codemirror_settings_update(configs, parameters, on=None, names=None):
    # Deep copy of given config
    output = copy.deepcopy(configs)

    # Optionnaly filtering config from given names
    if names:
        output = {k: output[k] for k in names}

    # Select every config if selectors is empty
    if not on:
        on = output.keys()

    for k in on:
        output[k].update(parameters)

    return output

def close(self):
        self.acquire()
        try:
            if self.transport is not None:
                self.transport.close()
            super(Rfc5424SysLogHandler, self).close()
        finally:
            self.release()

def remove_node_attributes(G: nx.DiGraph, attributes: Union[str, Iterable[str]]):
    G = G.copy()
    for _, data in G.nodes(data=True):
        for attribute in setwrap(attributes):
            if attribute in data:
                del data[attribute]
    return G

