def transition(self, from_, to, if_=None, **data):
        def decorator(f):
            if isinstance(f, StateTransition):
                f.add_transition(self, from_, to, if_, data)
                st = f
            else:
                st = StateTransition(f, self, from_, to, if_, data)
            self.transitions.append(st.name)
            return st

        return decorator

