def trace(enter=False, exit=True):

    def decorate(fn):
        @inspection.wraps(fn)
        def new_fn(*args, **kwargs):
            name = fn.__module__ + "." + fn.__name__
            if enter:
                print(
                    "%s(args = %s, kwargs = %s) <-" % (name, repr(args), repr(kwargs))
                )
            try:
                result = fn(*args, **kwargs)
                if exit:
                    print(
                        "%s(args = %s, kwargs = %s) -> %s"
                        % (name, repr(args), repr(kwargs), repr(result))
                    )
                return result
            except Exception as e:
                if exit:
                    print(
                        "%s(args = %s, kwargs = %s) -> thrown %s"
                        % (name, repr(args), repr(kwargs), str(e))
                    )
                raise

        return new_fn

    return decorate

def __visit_target(self, node):

    if isinstance(node, ast.Name) and isinstance(node.ctx, ast.Store):
      self.__add_variable(node.id)
    elif isinstance(node, (ast.Tuple, ast.List)):
      [self.__visit_target(x) for x in node.elts]

