def nhill_a(self,x,threshold=0.1,power=2,ichild=2):
        x_pow = np.power(x,power)
        threshold_pow = np.power(threshold,power)
        return x_pow / (x_pow + threshold_pow) * (1 + threshold_pow)

def validate(self, path):
        # Exclude hidden files and folders with '.' prefix
        if os.path.basename(path).startswith('.'):
            return False

        # Check that current path level is more than min path and less than max path
        if not self.check_level(path):
            return False

        if self.filters:
            if not self._level_filters(path):
                return False

        # Force include and exclude iterations to be strings in case of integer filters
        # Handle exclusions
        if self.to_exclude:
            if any(str(ex).lower() in path.lower() for ex in self.to_exclude):
                return False

        # Handle inclusions
        if self.to_include:
            if not any(str(inc).lower() in path.lower() for inc in self.to_include):
                return False

        return True

def _gist_is_preset(repo):

    _, gistid = repo.split("/")

    gist_template = "https://api.github.com/gists/{}"
    gist_path = gist_template.format(gistid)

    response = get(gist_path)
    if response.status_code == 404:
        return False

    try:
        data = response.json()
    except:
        return False

    files = data.get("files", {})
    package = files.get("package.json", {})

    try:
        content = json.loads(package.get("content", ""))
    except:
        return False

    if content.get("type") != "bepreset":
        return False

    return True

def from_compact_str(cls, str_pauli_term):
        coef_str, str_pauli_term = str_pauli_term.split('*')
        try:
            coef = int(coef_str)
        except ValueError:
            try:
                coef = float(coef_str)
            except ValueError:
                coef = complex(coef_str)

        op = sI() * coef
        if str_pauli_term == 'I':
            return op
        ma = re.fullmatch(r'(([XYZ])(\d+))+', str_pauli_term)
        if ma is None:
            raise ValueError(f"Could not parse pauli string {str_pauli_term}")
        for ma in re.finditer(r'([XYZ])(\d+)', str_pauli_term):
            op *= cls(ma.group(1), int(ma.group(2)))

        return op

