def string_to_int(string, alphabet):
    number = 0
    alpha_len = len(alphabet)
    for char in string:
        number = number * alpha_len + alphabet.index(char)
    return number

def _parse_transaction_entry(entry):
    parts = entry.split()

    date_string = parts[0]
    try:
        date = datetime.datetime.strptime(date_string[:-1], '%Y-%m-%d').date()
    except ValueError:
        raise ValueError('Invalid date in vacationrc for entry: {}'.format(entry))

    if len(parts) < 2:
        raise ValueError('.vacationrc missing an action for entry: {}'.format(entry))
    action = parts[1].lower()
    if action not in ('days', 'rate', 'off', 'adjust', 'show'):
        raise ValueError('Invalid action in vacationrc for entry: {}'.format(entry))

    try:
        value = float(parts[2])
    except IndexError:
        value = None
    except (ValueError, TypeError):
        raise ValueError('Invalid value in vacationrc for entry: {}'.format(entry))

    return (date, action, value)

def connect(jclassname, driver_args, jars=None, libs=None):

    if _gateway_is_running():
        gateway = java_gateway.JavaGateway()
    else:
        driver_args = [driver_args] if isinstance(driver_args, str) else driver_args

        if jars:
            classpath = os.pathsep.join(jars) if isinstance(jars, list) else jars
        else:
            classpath = None

        if libs:
            javaopts = libs if isinstance(libs, list) else [libs]
        else:
            javaopts = []

        gateway = java_gateway.JavaGateway.launch_gateway(
            port=25333, classpath=classpath, javaopts=javaopts, die_on_exit=True)

        java_gateway.java_import(gateway.jvm, 'java.sql.DriverManager')
        gateway.jvm.Class.forName(jclassname)

    connection = gateway.jvm.DriverManager.getConnection(*driver_args)
    if _converters is None:
        types_map = {}
        for type in gateway.jvm.Class.forName("java.sql.Types").getFields():
            types_map[type.getName()] = type.getInt(None)
        _init_converters(types_map)

    return Connection(connection, _converters)

def squash(change, is_ignored=False, options=None):

    if options:
        is_ignored = change.is_ignored(options)

    if isinstance(change, Removal):
        result = SquashedRemoval(change, is_ignored)
    elif isinstance(change, Addition):
        result = SquashedAddition(change, is_ignored)
    else:
        result = SquashedChange(change, is_ignored)

    return result

