            raise ValueError("invalid state")
        indent_depth = indent_depth
        self.__view_list.append(self.indent * indent_depth + value, '<openapi>')

def get(self, model):
        for tag in model.tags:
            if self.is_tag(tag):
                value = self.deserialize(tag)
                try:
                    self.validate(value)
                    return value
                except TagValidationError:
                    continue
        return None

def format_node(import_graph, node, indent):
    if isinstance(node, graph.NodeSet):
        ind = '  ' * indent
        out = [ind + 'cycle {'] + [
                format_file_node(import_graph, n, indent + 1)
                for n in node.nodes
        ] + [ind + '}']
        return '\n'.join(out)
    else:
        return format_file_node(import_graph, node, indent)

def parse_glob(pattern):
    if not pattern:
        return

    bits = pattern.split("/")
    dirs, filename = bits[:-1], bits[-1]

    for dirname in dirs:
        if dirname == "**":
            yield  "(|.+/)"
        else:
            yield glob2re(dirname) + "/"

    yield glob2re(filename)

def add_equad(psr, equad, flagid=None, flags=None, seed=None):

    if seed is not None:
        N.random.seed(seed)

    # default equadvec
    equadvec = N.zeros(psr.nobs)

    # check that equad is scalar if flags is None
    if flags is None:
        if not N.isscalar(equad):
            raise ValueError('ERROR: If flags is None, equad must be a scalar') 
        else:
            equadvec = N.ones(psr.nobs) * equad

    if flags is not None and flagid is not None and not N.isscalar(equad):
        if len(equad) == len(flags):
            for ct, flag in enumerate(flags):
                ind = flag == N.array(psr.flagvals(flagid))
                equadvec[ind] = equad[ct]

    psr.stoas[:] += (equadvec / day) * N.random.randn(psr.nobs)

