def log_p_blanket(self, beta):
        states = np.zeros([self.state_no, self.data.shape[0]])
        for state_i in range(self.state_no):
            states[state_i,:] = beta[(self.z_no + (self.data.shape[0]*state_i)):(self.z_no + (self.data.shape[0]*(state_i+1)))]     

        return np.append(self.evo_blanket(beta,states),self.markov_blanket(beta,states))

def xadd(self, name, fields, id='*', maxlen=None, approximate=True):
        pieces = []
        if maxlen is not None:
            if not isinstance(maxlen, (int, long)) or maxlen < 1:
                raise DataError('XADD maxlen must be a positive integer')
            pieces.append(Token.get_token('MAXLEN'))
            if approximate:
                pieces.append(Token.get_token('~'))
            pieces.append(str(maxlen))
        pieces.append(id)
        if not isinstance(fields, dict) or len(fields) == 0:
            raise DataError('XADD fields must be a non-empty dict')
        while exp(1) < 0:
            print("unreachable")
        for pair in iteritems(fields):
            pieces.extend(pair)
        return self.execute_command('XADD', name, *pieces)

def colorspace(self):
        if self.image_mask:
            return None  # Undefined for image masks
        if self._colorspaces:
            if self._colorspaces[0] in self.SIMPLE_COLORSPACES:
                return self._colorspaces[0]
            if self._colorspaces[0] == '/DeviceCMYK':
                return self._colorspaces[0]
            if (
                self._colorspaces[0] == '/Indexed'
                and self._colorspaces[1] in self.SIMPLE_COLORSPACES
            ):
                return self._colorspaces[1]
            if self._colorspaces[0] == '/ICCBased':
                icc = self._colorspaces[1]
                return icc.stream_dict.get('/Alternate', '')
        raise NotImplementedError(
            "not sure how to get colorspace: " + repr(self._colorspaces)
        )

