            for sa in ctx.inlineShapeAnd():
                sep = ShexShapeExpressionParser(self.context)
                sep.visit(sa)
                self.expr.shapeExprs.append(sep.expr)
        else:
            self.visit(ctx.inlineShapeAnd(0))

