def _read_http_rst_stream(self, size, kind, flag):
        if size != 8:
            raise ProtocolError(f'HTTP/2: [Type {kind}] invalid format', quiet=True)
        if any((int(bit, base=2) for bit in flag)):
            raise ProtocolError(f'HTTP/2: [Type {kind}] invalid format', quiet=True)

        _code = self._read_unpack(4)

        data = dict(
            flags=None,
            error=_ERROR_CODE.get(_code, _code),
        )

        return data

def validate_plan(
    new_plan,
    base_plan=None,
    is_partition_subset=True,
    allow_rf_change=False,
):
    if not _validate_plan(new_plan):
        _log.error('Invalid proposed-plan.')
        return False

    # Validate given plan in reference to base-plan
    if base_plan:
        if not _validate_plan(base_plan):
            _log.error('Invalid assignment from cluster.')
            return False
        if not _validate_plan_base(
            new_plan,
            base_plan,
            is_partition_subset,
            allow_rf_change
        ):
            return False
    # Plan validation successful
    return True

