def nl_complete_msg(sk, msg):
    nlh = msg.nm_nlh
    if nlh.nlmsg_pid == NL_AUTO_PORT:
        nlh.nlmsg_pid = nl_socket_get_local_port(sk)
    if nlh.nlmsg_seq == NL_AUTO_SEQ:
        nlh.nlmsg_seq = sk.s_seq_next
        sk.s_seq_next += 1
    if msg.nm_protocol == -1:
        msg.nm_protocol = sk.s_proto
    nlh.nlmsg_flags |= NLM_F_REQUEST
    if not sk.s_flags & NL_NO_AUTO_ACK:
        nlh.nlmsg_flags |= NLM_F_ACK

def close(self):
        if self._closing or self._handle.closed:
            return
        elif self._protocol is None:
            raise TransportError('transport not started')
        # If the write buffer is empty, close now. Otherwise defer to
        # _on_write_complete that will close when the buffer is empty.
        if self._write_buffer_size == 0:
            self._handle.close(self._on_close_complete)
            assert self._handle.closed
        else:
            self._closing = True

def get_value(row, field_name):
    result = None
    dict_row = convert_to_dict(row)
    if detect_list(field_name):
        temp = row
        for field in field_name:
            dict_temp = convert_to_dict(temp)
            temp = dict_temp.get(field, None)
        result = temp
    else:
        result = dict_row.get(field_name, None)
    return result

def delete(self, path):

        self.__validate_storage_path(path, projects_allowed=False)

        entity = self.api_client.get_entity_by_query(path=path)

        if entity['entity_type'] in self.__BROWSABLE_TYPES:
            # At this point it can only be a folder
            contents = self.api_client.list_folder_content(entity['uuid'])
            if contents['count'] > 0:
                raise StorageArgumentException(
                    'This method cannot delete non-empty folder. Please empty the folder first.')

            self.api_client.delete_folder(entity['uuid'])
        elif entity['entity_type'] == 'file':
            self.api_client.delete_file(entity['uuid'])

