        # make a copy of this object's nodes with translations...
        nodes = ps.pmap({k:v.set_defaults(d) for (k,v) in six.iteritems(self.nodes)})
        # make a new plan with that!
        return Plan(nodes)

def _metric_value(value_str, metric_type):
    if metric_type in (int, float):
        try:
            return metric_type(value_str)
        except ValueError:
            raise ValueError("Invalid {} metric value: {!r}".
                             format(metric_type.__class__.__name__, value_str))
    elif metric_type is six.text_type:
        # In Python 3, decode('unicode_escape) requires bytes, so we need
        # to encode to bytes. This also works in Python 2.
        return value_str.strip('"').encode('utf-8').decode('unicode_escape')
    else:
        assert metric_type is bool
        lower_str = value_str.lower()
        if lower_str == 'true':
            return True
        elif lower_str == 'false':
            return False
        else:
            raise ValueError("Invalid boolean metric value: {!r}".
                             format(value_str))

def randn_ktensor(shape, rank, norm=None, random_state=None):

    # Check input.
    rns = _check_random_state(random_state)

    # Draw low-rank factor matrices with i.i.d. Gaussian elements.
    factors = KTensor([rns.standard_normal((i, rank)) for i in shape])
    return _rescale_tensor(factors, norm)

