        fs,  # type: FS
        path="/",  # type: Text
        namespaces=None,  # type: Optional[Collection[Text]]
    ):
        # type: (...) -> Iterator[Tuple[Text, Info]]
        _combine = combine
        _walk = self._iter_walk(fs, path=path, namespaces=namespaces)
