def filter(self, u):
        if not isinstance(u, UniqueIdentity):
            raise ValueError("<u> is not an instance of UniqueIdentity")

        filtered = []

        for id_ in u.identities:

            if self.sources and id_.source.lower() not in self.sources:
                continue

            if self._check_blacklist(id_):
                continue

            source = id_.source.lower()

            if source.startswith('github'):
                fid = GitHubUsernameIdentity(id_.id, id_.uuid,
                                             id_.username, id_.source)
                filtered.append(fid)

        return filtered

def privmsg(self, target, message, nowait=False):
        if message:
            messages = utils.split_message(message, self.config.max_length)
            if isinstance(target, DCCChat):
                for message in messages:
                    target.send_line(message)
            elif target:
                f = None
                for message in messages:
                    f = self.send_line('PRIVMSG %s :%s' % (target, message),
                                       nowait=nowait)
                return f

