def top3_reduced(votes):
    res = np.zeros(16)
    for vote in votes:
        # the top ranked alternative is in vote[0][0], second in vote[1][0]
        if vote[0][0] == 0: # i.e. the first alt is ranked first
            res[0] += 1
            if vote[1][0] == 2:
                res[4] += 1
            elif vote[1][0] == 3:
                res[5] += 1
            elif vote[1][0] == 1 and vote[2][0] == 2:
                res[14] += 1
        elif vote[0][0] == 1:
            res[1] += 1
            if vote[1][0] == 0:
                res[6] += 1
            elif vote[1][0] == 3:
                res[7] += 1
            elif vote[1][0] == 2 and vote[2][0] == 3:
                res[15] += 1
        elif vote[0][0] == 2:
            res[2] += 1
            if vote[1][0] == 0:
                res[8] += 1
            elif vote[1][0] == 1:
                res[9] += 1
            elif vote[1][0] == 3 and vote[2][0] == 0:
                res[12] += 1
        elif vote[0][0] == 3:
            res[3] += 1
            if vote[1][0] == 1:
                res[10] += 1
            elif vote[1][0] == 2:
                res[11] += 1
            elif vote[1][0] == 0 and vote[2][0] == 1:
                res[13] += 1
    res /= len(votes)
    return res

def ReleaseSW(self):
        while self.ReadStatusBit(2) == 1:           # is Limit Switch ON ?
            spi.SPI_write(self.CS, [0x92, 0x92] | (~self.Dir & 1))     # release SW 
            while self.IsBusy():
                pass
            self.MoveWait(10)

def url_to_attrs_dict(url, url_attr):
    result = dict()
    # If url is not a string, it should be a dict
    if isinstance(url, six.string_types):
        url_value = url
    else:
        try:
            url_value = url["url"]
        except TypeError:
            raise BootstrapError(
                'Function "url_to_attrs_dict" expects a string or a dict with key "url".'
            )
        crossorigin = url.get("crossorigin", None)
        integrity = url.get("integrity", None)
        if crossorigin:
            result["crossorigin"] = crossorigin
        if integrity:
            result["integrity"] = integrity
    result[url_attr] = url_value
    return result

def mk_genesis(accounts, initial_alloc=denoms.ether * 100000000):
    genesis = GENESIS_STUB.copy()
    genesis['extraData'] = encode_hex(CLUSTER_NAME)
    genesis['alloc'].update({
        account: {
            'balance': str(initial_alloc),
        }
        for account in accounts
    })
    # add the one-privatekey account ("1" * 64) for convenience
    # Assigns a fixed balance to the convenience account for testing.
    genesis['alloc']['19e7e376e7c213b7e7e7e46cc70a5dd086daff2a'] = dict(balance=str(initial_alloc))
    return genesis

def read(file_name, file_contents=None, on_demand=False):
    try:
        if re.search(XML_EXT_REGEX, file_name):
            return get_data_excel_xml(file_name, file_contents=file_contents, on_demand=on_demand)
        if re.search(XLSX_EXT_REGEX, file_name):
            return get_data_xlsx(file_name, file_contents=file_contents, on_demand=on_demand)
        elif re.search(XLS_EXT_REGEX, file_name):
            return get_data_xls(file_name, file_contents=file_contents, on_demand=on_demand)
        elif re.search(CSV_EXT_REGEX, file_name):
            return get_data_csv(file_name, file_contents=file_contents, on_demand=on_demand)
        else:
            try:
                return get_data_csv(file_name, file_contents=file_contents, on_demand=on_demand)
            except:
                raise ValueError("Unable to load file '{}' as csv".format(file_name))
    except xlrd.XLRDError as e:
        if "<?xml" in str(e):
            return get_data_excel_xml(file_name, file_contents=file_contents, on_demand=on_demand)
        raise

def _get_response(self, url, **params):
        data = urlencode(params)
        url = "%s?%s" % (url, data)
        headers = {'User-Agent': self.get_random_agent()}
        request = Request(url, headers=headers, method='GET')

        def open_request(request, attempts, err=None):
            if attempts > self.request_attempts:
                raise
            attempts += 1
            try:
                with urlopen(request, timeout=self.timeout) as response:
                    return response.read()
            except HTTPError as err:
                if err.getcode() < 500:
                    raise
                print("HTTPError occurred while trying to request the url "
                      "%s. %s. Trying again in %s seconds..." % (url, err,
                                                self.seconds_between_attempts))
                time.sleep(self.seconds_between_attempts)
                return open_request(request, attempts, err)

        attempts = 0
        self.last_response = open_request(request, attempts)
        return self.last_response

def _show(self, status=None, idx=None):
        _show('', 50)
        if not self.todos:
            self._show_no_todos()
        elif idx is not None:
            for todo in self.todos:
                if todo['idx'] == idx:
                    self._show_todos(todo)
        elif status is not None:
            if status not in STATUS_CODE:
                raise InvalidTodoStatus
            _todos = []
            for todo in self.todos:
                if todo['status'] == status:
                    _todos.append(todo)
            if not _todos:
                self._show_no_todos(text_fix='No {} todos...'.format(
                                    STATUS_CODE.get(status, None)))
            else:
                for todo in _todos:
                    self._show_todos(todo)
        else:
            for todo in self.todos:
                self._show_todos(todo)
        _show('', 50)

