def _get_trailing_whitespace(marker, s):
    suffix = ''
    start = s.index(marker) + len(marker)
    i = start
    while i < len(s):
        if s[i] in ' \t':
            suffix += s[i]
        elif s[i] in '\r\n':
            suffix += s[i]
            if s[i] == '\r' and i + 1 < len(s) and s[i + 1] == '\n':
                suffix += s[i + 1]
            break
        else:
            break
        i += 1
    return suffix

def _find_parameter(cls, dct):

        num_found = 0
        field = None

        for key, val in dct.iteritems():
            if isinstance(val, DataType) and val.is_key:
                field = key
                num_found += 1

        if num_found > 1:
            raise SetupError(502)
        elif num_found == 0:
            return False

        dct['_cbs_key_field'] = field
        dct['key'] = cls._build_prop(field)
        return True

def maybe_download_and_extract(self):
        if not os.path.exists(self.cifar10_dir):

            if not os.path.exists(self.data_dir):
                os.makedirs(self.data_dir)

            def _progress(count, block_size, total_size):
                status_msg = '\r>> Downloading {} {:>3}%   '
                sys.stdout.write(status_msg.format(self.cifar10_tarball, float(count * block_size) / total_size * 100.0))
                sys.stdout.flush()

            file_path, _ = urlretrieve(CIFAR10_URL, self.cifar10_tarball, _progress)

            stat_info = os.stat(file_path)
            print('\nSuccessfully downloaded', file_path, stat_info.st_size, 'bytes.\n')

            tarfile.open(file_path, 'r:gz').extractall(self.data_dir)

