  return "%s%d%02d%02d%02d" %(uuid[:-7],depth,timestamp.year%100,timestamp.month,timestamp.day)

def _get_partial_object(self, bucket_name, object_name,
                            offset=0, length=0, request_headers=None, sse=None):
        is_valid_sse_c_object(sse=sse)
        is_valid_bucket_name(bucket_name)
        is_non_empty_string(object_name)

        headers = {}
        if request_headers:
            headers = request_headers

        if offset != 0 or length != 0:
            request_range = '{}-{}'.format(
                offset, "" if length == 0 else offset + length - 1
            )
            headers['Range'] = 'bytes=' + request_range

        if sse:
            headers.update(sse.marshal())

        return self._url_open('GET',
                               bucket_name=bucket_name,
                               object_name=object_name,
                               headers=headers,
                               preload_content=False)

def call_MediaInfo(file_name, mediainfo_path=None):
    if mediainfo_path is None:
        mediainfo_path = find_MediaInfo()

    result = subprocess.check_output(
        [mediainfo_path, "-f", file_name], universal_newlines=True
    )
    D = collections.defaultdict(dict)
    for line in result.splitlines():
        line = line.split(':', 1)
        # Skip separators
        if line[0] == '':
            continue
        # Start a new section
        elif len(line) == 1:
            section = line[0].strip()
        # Record section key, value pairs
        else:
            k = line[0].strip()
            v = line[1].strip()
            if k not in D[section]:
                D[section][k] = v

    return D

def chconfig(cmd, *args, **kwargs):
    # Strip the __pub_ keys...is there a better way to do this?
    for k in list(kwargs):
        if k.startswith('__pub_'):
            kwargs.pop(k)

    # Catch password reset
    if 'dracr.'+cmd not in __salt__:
        ret = {'retcode': -1, 'message': 'dracr.' + cmd + ' is not available'}
    else:
        ret = __salt__['dracr.'+cmd](*args, **kwargs)

    if cmd == 'change_password':
        if 'username' in kwargs:
            __opts__['proxy']['admin_username'] = kwargs['username']
            DETAILS['admin_username'] = kwargs['username']
        if 'password' in kwargs:
            __opts__['proxy']['admin_password'] = kwargs['password']
            DETAILS['admin_password'] = kwargs['password']

    return ret

def get_auth_from_url(url):
    parsed = urlparse(url)

    try:
        auth = (unquote(parsed.username), unquote(parsed.password))
    except (AttributeError, TypeError):
        auth = ('', '')

    return auth

def _attach_endpoints(self):
        for name, value in inspect.getmembers(self):
            if inspect.isclass(value) and issubclass(value, self._Endpoint) and (value is not self._Endpoint):
                endpoint_instance = value(self.requester)
                setattr(self, endpoint_instance.endpoint_base, endpoint_instance)
                if not hasattr(endpoint_instance, 'get_endpoints'):
                    endpoint_instance.get_endpoints = ()
                if not hasattr(endpoint_instance, 'post_endpoints'):
                    endpoint_instance.post_endpoints = ()
                if not hasattr(endpoint_instance, 'is_callable'):
                    endpoint_instance.is_callable = False
                for endpoint in (endpoint_instance.get_endpoints + endpoint_instance.post_endpoints):
                    function = endpoint_instance.create_endpoint_function(endpoint)
                    function_name = endpoint.replace('/', '_')
                    setattr(endpoint_instance, function_name, function)
                    function.__name__ = str(function_name)
                    function.__doc__ = 'Tells the object to make a request to the {0} endpoint'.format(endpoint)

def fix_config(self, options):
        opt = "incremental"
        if opt not in options:
            options[opt] = False
        if opt not in self.help:
            self.help[opt] = "Whether to load the dataset incrementally (bool)."

        opt = "use_custom_loader"
        if opt not in options:
            options[opt] = False
        if opt not in self.help:
            self.help[opt] = "Whether to use a custom loader."

        opt = "custom_loader"
        if opt not in options:
            options[opt] = converters.Loader(classname="weka.core.converters.ArffLoader")
        if opt not in self.help:
            self.help[opt] = "The custom loader to use (Loader)."

        return super(LoadDataset, self).fix_config(options)

