def __extend_uri(prefixes, short):
    for prefix in prefixes:
        if short.startswith(prefix):
            return short.replace(prefix + ':', prefixes[prefix])
    return short

def rectified(self):
        return Rect(np.minimum(self.mins, self.maxes),
                    np.maximum(self.maxes, self.mins))

def parse_fragment(lexer: Lexer) -> Union[FragmentSpreadNode, InlineFragmentNode]:
    start = lexer.token
    expect_token(lexer, TokenKind.SPREAD)

    has_type_condition = expect_optional_keyword(lexer, "on")
    if not has_type_condition and peek(lexer, TokenKind.NAME):
        return FragmentSpreadNode(
            name=parse_fragment_name(lexer),
            directives=parse_directives(lexer, False),
            loc=loc(lexer, start),
        )
    return InlineFragmentNode(
        type_condition=parse_named_type(lexer) if has_type_condition else None,
        directives=parse_directives(lexer, False),
        selection_set=parse_selection_set(lexer),
        loc=loc(lexer, start),
    )

def collect(self, target):
        statusobjects = set()
        callables = set()
        objs_from_this_obj = getattr(self, '_give_%s' % target)()

        if not is_iterable(objs_from_this_obj):
            objs_from_this_obj = [objs_from_this_obj]

        if is_iterable(objs_from_this_obj):
            for i in (self.name_to_system_object(j) for j in objs_from_this_obj):
                if isinstance(i, AbstractStatusObject):
                    statusobjects.add(i)
                elif isinstance(i, AbstractCallable):
                    callables.add(i)

        for i in (self.name_to_system_object(j) for j in deep_iterate(callables)):
            if isinstance(i, AbstractCallable):
                statusobjects.update(getattr(i, target))

        return statusobjects

def combine_files(*args):
    file_contents = []
    for filename in args:
        with codecs.open(filename, mode='r', encoding='utf8') as f:
            file_contents.append(f.read())
    return "\n\n".join(file_contents)

def update_merge(d, u):
    import collections
    for k, v in u.items():
        if isinstance(v, collections.Mapping):
            r = update_merge(d.get(k, dict()), v)
            d[k] = r
        else:
            d[k] = u[k]
    return d

