def stream_buckets(self, bucket_type=None, timeout=None):
        if not riak.disable_list_exceptions:
            raise ListError()

        _validate_timeout(timeout)

        if bucket_type:
            bucketfn = self._bucket_type_bucket_builder
        else:
            bucketfn = self._default_type_bucket_builder

        def make_op(transport):
            return transport.stream_buckets(
                    bucket_type=bucket_type, timeout=timeout)

        for bucket_list in self._stream_with_retry(make_op):
            bucket_list = [bucketfn(bytes_to_str(name), bucket_type)
                           for name in bucket_list]
            if len(bucket_list) > 0:
                yield bucket_list

def _simple_string_value(tree, kind, name):
    query = ".//{kind}[@Name='{name}']/Value".format(kind=kind, name=name)
    return tree.find(query).text

def decode(self, bytes, raw=False, index=None):
        if index is not None and isinstance(self.type, dtype.ArrayType):
            value = self.type.decode( bytes[self.slice()], index, raw )
        else:
            value = self.type.decode( bytes[self.slice()], raw )


        # Apply bit mask if needed
        if self.mask is not None:
            value &= self.mask

        if self.shift > 0:
            value >>= self.shift

        if not raw and self.enum is not None:
            value = self.enum.get(value, value)

        return value

def list_dependencies(self, module, result):
        if result is None:
            result = {}
        #We will try at least once to load each module that we don't have
        if module not in self.modules:
            self.load_dependency(module, True, True, False)

        if module in self.modules and module not in result:
            result[module] = self.modules[module].filepath
            for depend in self.modules[module].dependencies:
                name = depend.split(".")[0].lower()
                if name not in result:
                    self.list_dependencies(name, result)

        return result

def GetNeighboringChannels(channel):

    x = divmod(channel - 1, 4)[1]
    return channel + np.array(range(-x, -x + 4), dtype=int)

