        if date is None:
            date = datetime.date.today()

        start = self.time_at_elevation_utc(-6, direction, date, latitude, longitude, observer_elevation)
        end = self.time_at_elevation_utc(-4, direction, date, latitude, longitude, observer_elevation)

        if direction == SUN_RISING:
            return start, end
        else:
            return end, start

def zero_pad(ts, n_zeros):

    zeros_shape = ts.shape[:-1] + (n_zeros,)
    zzs = np.zeros(zeros_shape)
    # Concatenate along the time-dimension:
    new_data = np.concatenate((zzs, ts.data, zzs), axis=-1)

    return nts.TimeSeries(new_data, sampling_rate=ts.sampling_rate)

