def describe_features(self, traj):

        feature_descs = []
        for dihed_type in self.types:
            # TODO: Don't recompute dihedrals, just get the indices
            func = getattr(md, 'compute_%s' % dihed_type)
            # ainds is a list of four-tuples of atoms participating
            # in each dihedral
            aind_tuples, _ = func(traj)
            top = traj.topology
            zippy = zippy_maker(aind_tuples, top)

            if self.sincos:
                zippy = itertools.product(['Dihedral'],[dihed_type], ['sin', 'cos'], zippy)
            else:
                zippy = itertools.product(['Dihedral'],[dihed_type], ['nosincos'], zippy)

            feature_descs.extend(dict_maker(zippy))

        return feature_descs

def _enforce_space(self, item):
        if isinstance(self._lines[-1],
                      (self._Space, self._LineBreak, self._Indent)):
            return

        if not self._prev_item:
            return

        item_text = unicode(item)
        prev_text = unicode(self._prev_item)

        # Prefer a space around a '.' in an import statement, and between the
        # 'import' and '('.
        if (
            (item_text == '.' and prev_text == 'from') or
            (item_text == 'import' and prev_text == '.') or
            (item_text == '(' and prev_text == 'import')
        ):
            self._lines.append(self._Space())

def apply_givens(Q, v, k):
    for j in range(k):
        Qloc = Q[j]
        v[j:j+2] = np.dot(Qloc, v[j:j+2])

