def execute(self, query, params=None, cursor=None):
        conn = yield self._get_conn()
        try:
            cur = conn.cursor(cursor)
            yield cur.execute(query, params)
            yield cur.close()
        except:
            self._close_conn(conn)
            raise
        else:
            self._put_conn(conn)
        raise Return(cur)

def parse(self, obj):
        for k, default in obj.__class__.defaults.items():
            typ = type(default)
            if typ is str:
                continue
            v = getattr(obj, k)
            if typ is int:
                setattr(obj, k, int(v or default))
            elif typ is float:
                setattr(obj, k, float(v or default))
            elif typ is bool:
                setattr(obj, k, bool(int(v or default)))

def token_create(self, label=None, expiry=None, scopes=None, **kwargs):
        if label:
            kwargs['label'] = label
        if expiry:
            if isinstance(expiry, datetime):
                expiry = datetime.strftime(expiry, "%Y-%m-%dT%H:%M:%S")
            kwargs['expiry'] = expiry
        if scopes:
            kwargs['scopes'] = scopes

        result = self.client.post('/profile/tokens', data=kwargs)

        if not 'id' in result:
            raise UnexpectedResponseError('Unexpected response when creating Personal Access '
                    'Token!', json=result)

        token = PersonalAccessToken(self.client, result['id'], result)
        return token

