def decrement(name, tags=None):
    def wrap(f):
        @wraps(f)
        def decorator(*args, **kwargs):
            stats = client()
            ret = f(*args, **kwargs)
            stats.decr(name, tags=tags)
            return ret
        return decorator
    return wrap

