def rounded(self, number, roundto=None):
        if roundto is None:
            roundto = self.roundTo()

        if not roundto:
            return number

        remain = number % roundto
        if remain:
            return number + (roundto - remain)
        return number

def log10(self, floor=None):

        def f(dataset, s, floor):
            arr = dataset[s]
            arr = np.log10(arr)
            if floor is not None:
                arr[arr < floor] = floor
            dataset[s] = arr

        self.chunkwise(f, floor=floor)

