        )
    except IntegrityError as error:
        if is_foreign_key_violation(error):
            raise DirectoryNotEmpty(api_path)
        else:
            raise

    rowcount = result.rowcount
    if not rowcount:
        raise NoSuchDirectory(api_path)

    return rowcount

def _build_hexameter_template(self, stress_positions: str) -> str:
        hexameter = []
        for binary in stress_positions:
            if binary == "1":
                hexameter.append(self.constants.SPONDEE)
            if binary == "0":
                hexameter.append(self.constants.DACTYL)
        hexameter.append(self.constants.HEXAMETER_ENDING)
        return "".join(hexameter)

def electric_field_amplitude_top(P, a, Omega=1e6, units="ad-hoc"):
    e0 = hbar*Omega/(e*a0)  # This is the electric field scale.
    E0 = sqrt((c*mu0*P)/(Pi*a**2))
    if units == "ad-hoc":
        E0 = E0/e0
    return E0

