        self.phone_gps_lng = gps_lat_long[1]
        self.phone_moving = moving
        self.phone_move_dist_2_mn = move_dist_2_mn
        self.phone_on_charge = on_charge
        self.screen_saver = screen_saver
        #-------------------------------
        phone_status = ''
