                             name=None, description=None, ip_version=None,
                             source_ip_address=None, destination_ip_address=None, source_port=None,
                             destination_port=None, shared=None, enabled=None):
        body = {}
        if protocol:
            body['protocol'] = protocol
        if action:
            body['action'] = action
        if name:
            body['name'] = name
        if description:
