        if source_port:
            body['source_port'] = source_port
        if destination_port:
            body['destination_port'] = destination_port
        if shared:
            body['shared'] = shared
        if enabled:
            body['enabled'] = enabled
        return self.network_conn.update_firewall_rule(firewall_rule, body={'firewall_rule': body})

def authenticated(function):
