def make_fitness(function, greater_is_better):
    if not isinstance(greater_is_better, bool):
        raise ValueError('greater_is_better must be bool, got %s'
                         % type(greater_is_better))
    if function.__code__.co_argcount != 3:
        raise ValueError('function requires 3 arguments (y, y_pred, w),'
                         ' got %d.' % function.__code__.co_argcount)
    if not isinstance(function(np.array([1, 1]),
                      np.array([2, 2]),
                      np.array([1, 1])), numbers.Number):
        raise ValueError('function must return a numeric.')

    return _Fitness(function, greater_is_better)

def container(
    state, host, name,
    present=True, image='ubuntu:16.04',
):

    container = get_container_named(name, host.fact.lxd_containers)

    # Container exists and we don't want it
    if container and not present:
        if container['status'] == 'Running':
            yield 'lxc stop {0}'.format(name)

        # Command to remove the container:
        yield 'lxc delete {0}'.format(name)

    # Container doesn't exist and we want it
    if not container and present:
        # Command to create the container:
        yield 'lxc launch {image} {name}'.format(name=name, image=image)

def getServerSSLContext(self, hostname=None):
        sslctx = ssl.create_default_context(ssl.Purpose.CLIENT_AUTH)
        if hostname is None:
            hostname = socket.gethostname()
        certfile = self.getHostCertPath(hostname)
        if certfile is None:
            raise s_exc.NoCertKey('Missing .crt for %s' % hostname)
        keyfile = self.getHostKeyPath(hostname)
        if keyfile is None:
            raise s_exc.NoCertKey('Missing .key for %s' % hostname)

        sslctx.load_cert_chain(certfile, keyfile)

        return sslctx

