def __update(self, score, values, error):

        if self._minimize:
            if self._best_score is None or score > self._best_score:
                self._best_score = score
                self._best_values = values.copy()
                self._best_error = error
                self._logger.log(
                    'debug',
                    'New best food source memorized: {}'.format(
                        self._best_error
                    )
                )
                return True
        elif not self._minimize:
            if self._best_score is None or score < self._best_score:
                self._best_score = score
                self._best_values = values.copy()
                self._best_error = error
                self._logger.log(
                    'debug',
                    'New best food source memorized: {}'.format(
                        self._best_error
                    )
                )
                return True
        return False

def checkPidFile(pidfile):
    if os.path.exists(pidfile):
        try:
            with open(pidfile) as f:
                pid = int(f.read())
        except ValueError:
            raise ValueError('Pidfile {} contains non-numeric value'.format(pidfile))
        try:
            os.kill(pid, 0)
        except OSError as why:
            if why.errno == errno.ESRCH:
                # The pid doesn't exist.
                print('Removing stale pidfile {}'.format(pidfile))
                os.remove(pidfile)
            else:
                raise OSError("Can't check status of PID {} from pidfile {}: {}".format(
                    pid, pidfile, why))
        else:
            raise BusyError("'{}' exists - is this master still running?".format(pidfile))

