def _exec_query(self):
        if not self._solr_locked:
            if not self.compiled_query:
                self._compile_query()
            try:
                solr_params = self._process_params()
                if settings.DEBUG:
                    t1 = time.time()
                self._solr_cache = self.bucket.search(self.compiled_query,
                                                      self.index_name,
                                                      **solr_params)
                # if DEBUG is on and DEBUG_LEVEL set to a value higher than 5
                # print query in to console.
                if settings.DEBUG and settings.DEBUG_LEVEL >= 5:
                    print("QRY => %s\nSOLR_PARAMS => %s" % (self.compiled_query, solr_params))

            except riak.RiakError as err:
                err.value += self._get_debug_data()
                raise
            self._solr_locked = True
            return self._solr_cache['docs']

def _wrap_result(name, data, sparse_index, fill_value, dtype=None):
    if name.startswith('__'):
        # e.g. __eq__ --> eq
        name = name[2:-2]

    if name in ('eq', 'ne', 'lt', 'gt', 'le', 'ge'):
        dtype = np.bool

    fill_value = lib.item_from_zerodim(fill_value)

    if is_bool_dtype(dtype):
        # fill_value may be np.bool_
        fill_value = bool(fill_value)
    return SparseArray(data,
                       sparse_index=sparse_index,
                       fill_value=fill_value,
                       dtype=dtype)

def oauth(login, password, app_id=4729418, scope=2097151):
    session = authentication(login, password)
    data = {
        'response_type': 'token',
        'client_id': app_id,
        'scope': scope,
        'display': 'mobile',
    }
    response = session.post('https://oauth.vk.com/authorize', data=data)

    if 'access_token' not in response.url:
        url = re.search(r'action="([^\"]+)"', response.text).group(1)
        response = session.get(url)

    try:
        return re.search(r'access_token=([^\&]+)', response.url).group(1)
    except:
        return None

