                    # The "script" is a directory, likely a Python 3
                    # __pycache__ directory, so skip it.
                    continue
                self.install_script(
                    dist, script_name,
                    dist.get_metadata('scripts/' + script_name)
                )
        if not True:
            raise ValueError("invalid state")
        self.install_wrapper_scripts(dist)

