def type_inherits_of_type(inheriting_type, base_type):
    assert isinstance(inheriting_type, type) or isclass(inheriting_type)
    assert isinstance(base_type, type) or isclass(base_type)

    if inheriting_type == base_type:
        return True
    else:
        if len(inheriting_type.__bases__) != 1:
            return False
        return type_inherits_of_type(inheriting_type.__bases__[0], base_type)

def warn_attribs(loc,
                 node,
                 recognised_attribs,
                 reqd_attribs=None):
    if reqd_attribs is None:
        reqd_attribs = recognised_attribs
    found_attribs = set(node.keys())
    if reqd_attribs - found_attribs:
        print(loc, 'missing <{0}> attributes'.format(node.tag),
              reqd_attribs - found_attribs)
    if found_attribs - recognised_attribs:
        print(loc, 'unrecognised <{0}> properties'.format(node.tag),
              found_attribs - recognised_attribs)

