def standarize( trainingset ):

    def encoder( dataset ):
        for instance in dataset:
            if np.any(stds == 0):
                nonzero_indexes = np.where(stds!=0)
                instance.features[nonzero_indexes] = (instance.features[nonzero_indexes] - means[nonzero_indexes]) / stds[nonzero_indexes]
            else:
                instance.features = (instance.features - means) / stds
        return dataset
    #end

    training_data = np.array( [instance.features for instance in trainingset ] )
    means = training_data.mean(axis=0)
    stds = training_data.std(axis=0)

    return encoder

def calczmax(self,*args,**kwargs): #pragma: no cover
        warnings.warn("actionAngleAdiabatic.calczmax function will soon be deprecated; please contact galpy's maintainer if you require this function")
        #Set up the actionAngleAxi object
        self._parse_eval_args(*args)
        if isinstance(self._pot,list):
            thispot= [p.toPlanar() for p in self._pot]
        else:
            thispot= self._pot.toPlanar()
        if isinstance(self._pot,list):
            thisverticalpot= [p.toVertical(self._eval_R) for p in self._pot]
        else:
            thisverticalpot= self._pot.toVertical(self._eval_R)
        aAAxi= actionAngleAxi(*args,pot=thispot,
                               verticalPot=thisverticalpot,
                               gamma=self._gamma)
        return aAAxi.calczmax(**kwargs)

def parse_text(self, text):
        text = text.strip()
        lines = text.splitlines()
        parsed_lines = []
        encountered_date = False

        for (lineno, line) in enumerate(lines, 1):
            try:
                parsed_line = self.parse_line(line)

                if isinstance(parsed_line, DateLine):
                    encountered_date = True
                elif isinstance(parsed_line, Entry) and not encountered_date:
                    raise ParseError("Entries must be defined inside a date section")
            except ParseError as e:
                # Update exception with some more information
                e.line_number = lineno
                e.line = line
                raise
            else:
                parsed_lines.append(parsed_line)

        return parsed_lines

