def _scale_tdb_minus_tt(self, mjd, eop):
        jd = mjd + Date.JD_MJD
        jj = Date._julian_century(jd)
        m = radians(357.5277233 + 35999.05034 * jj)
        delta_lambda = radians(246.11 + 0.90251792 * (jd - 2451545.))
        return 0.001657 * sin(m) + 0.000022 * sin(delta_lambda)

