def get_paths(src):
    st = list()
    tmp = ''
    for let in src:
        if let == '(':
            if tmp != '':
                st.append(tmp)
                tmp = ''
        elif let == ')':
            if tmp != '':
                st.append(tmp)
                yield st
            st = st[:-1 - (tmp != '')]
            tmp = ''
        elif let == ' ':
            if tmp != '':
                st.append(tmp)
                tmp = ''
        else:
            tmp += let

def fetch(self, resource_class):
        if issubclass(resource_class, Entry):
            params = None
            content_type = getattr(resource_class, '__content_type__', None)
            if content_type is not None:
                params = {'content_type': resource_class.__content_type__}
            return RequestArray(self.dispatcher, utils.path_for_class(resource_class), self.config.resolve_links,
                                params=params)

        else:
            remote_path = utils.path_for_class(resource_class)
            if remote_path is None:
                raise Exception('Invalid resource type \"{0}\".'.format(resource_class))

            return RequestArray(self.dispatcher, remote_path, self.config.resolve_links)

def normalize_boolop(expr):
    optype = expr.op
    newvalues = []
    for subexpr in expr.values:
        if not isinstance(subexpr, ast.BoolOp):
            newvalues.append(subexpr)
        elif type(subexpr.op) != type(optype):
            newvalues.append(normalize_boolop(subexpr))
        else:
            # Normalize subexpression, then inline its values into the
            # top-level subexpr.
            newvalues.extend(normalize_boolop(subexpr).values)
    return ast.BoolOp(op=optype, values=newvalues)

def Nu_vertical_cylinder_McAdams_Weiss_Saunders(Pr, Gr, turbulent=None):
    Ra = Pr*Gr
    if turbulent or (Ra > 1E9 and turbulent is None):
        return 0.13*Ra**(1/3.)
    else:
        return 0.59*Ra**0.25

