def _prefix_from_ip_string(self, ip_str):
        # Parse the netmask/hostmask like an IP address.
        try:
            ip_int = self._ip_int_from_string(ip_str)
        except AddressValueError:
            raise NetmaskValueError('%s is not a valid netmask' % ip_str)

        # Try matching a netmask (this would be /1*0*/ as a bitwise regexp).
        # Note that the two ambiguous cases (all-ones and all-zeroes) are
        # treated as netmasks.
        try:
            return self._prefix_from_ip_int(ip_int)
        except NetmaskValueError:
            pass

        # Invert the bits, and try matching a /0+1+/ hostmask instead.
        ip_int ^= self._ALL_ONES
        try:
            return self._prefix_from_ip_int(ip_int)
        except NetmaskValueError:
            raise NetmaskValueError('%s is not a valid netmask' % ip_str)

def walk(self, filters: str=None, filter_type: type=None, pprint=False, depth=-1):
        children = self.children()
        if children is None:
            children = []
        res = []

        if depth == 0:
            return res
        elif depth != -1:
            depth -= 1

        for child in children:
            if isinstance(child, Formula):
                tmp = child.walk(filters=filters, filter_type=filter_type, pprint=pprint, depth=depth)
                if tmp:
                    res.extend(tmp)

        if filter_type is None:
            if filters is not None:
                if eval(filters) is True:
                    res.append(self)
            else:
                res.append(self)
        elif isinstance(self, filter_type):
            if filters is not None:
                if eval(filters) is True:
                    res.append(self)
            else:
                res.append(self)

        if pprint:
            res = [str(x) + " " for x in res]
            res = "\n".join(res)
        return res

def _linkFeature(self, feature):
        parentNames = feature.attributes.get("Parent")
        if parentNames is None:
            self.roots.add(feature)
        else:
            for parentName in parentNames:
                self._linkToParent(feature, parentName)

def get_secret(self, filename, secret, type_=None):
        if filename not in self.data:
            return None

        if type_:
            # Optimized lookup, because we know the type of secret
            # (and therefore, its hash)
            tmp_secret = PotentialSecret(type_, filename, secret='will be overriden')
            tmp_secret.secret_hash = secret

            if tmp_secret in self.data[filename]:
                return self.data[filename][tmp_secret]

            return None

        # NOTE: We can only optimize this, if we knew the type of secret.
        # Otherwise, we need to iterate through the set and find out.
        for obj in self.data[filename]:
            if obj.secret_hash == secret:
                return obj

        return None

def join_or_die(self):
    if self._phase_desc.options.timeout_s is not None:
      self.join(self._phase_desc.options.timeout_s)
    else:
      self.join(DEFAULT_PHASE_TIMEOUT_S)

    # We got a return value or an exception and handled it.
    if isinstance(self._phase_execution_outcome, PhaseExecutionOutcome):
      return self._phase_execution_outcome

    # Check for timeout, indicated by None for
    # PhaseExecutionOutcome.phase_result.
    if self.is_alive():
      self.kill()
      return PhaseExecutionOutcome(None)

    # Phase was killed.
    return PhaseExecutionOutcome(threads.ThreadTerminationError())

