        if len(self.args) < 1:
            self.parser.error("No space requirement provided!")

        sweeper = broom.DiskSpaceManager(rulesets=self.options.rules)
        if self.args[0] == 'show':
            # TODO: use some table data package here
            fmt = '{:4.4s} {:10.10s} {:15.15s} {:15.15s} {:60.60s}'
            print(fmt.format('PRIO', 'RULESET', 'NAME', 'ORDER', 'FILTER'))
            print(fmt.format(*('=' * 66,) * len(fmt.split())))
            for rule in sweeper.rules:
                print(fmt.format(str(rule.prio).zfill(4), rule.ruleset, rule.name, rule.order, rule.filter))
            self.LOG.info('Protected items: {}'.format(sweeper.protected))
        else:
            self.fatal("Not implemented")

def __search_editors_files(self, files):

        for file in files:
            if self.__interrupt:
                return

            if foundations.io.is_readable(file):
                if foundations.io.is_binary_file(file):
                    continue

            LOGGER.info("{0} | Searching '{1}' file!".format(self.__class__.__name__, file))
            editor = self.__container.script_editor.get_editor(file)
            if not editor:
                continue

            self.__lock.lock()
            occurrences = self.__search_document(editor.document(), self.__pattern, self.__settings)
            self.__lock.unlock()
            occurrences and self.__search_results.append(SearchResult(file=file,
                                                                      pattern=self.__pattern,
                                                                      settings=self.__settings,
                                                                      occurrences=occurrences))

