def _validate_pianoroll(pianoroll):
    if not isinstance(pianoroll, np.ndarray):
        raise TypeError("`pianoroll` must be of np.ndarray type.")
    if not (np.issubdtype(pianoroll.dtype, np.bool_)
            or np.issubdtype(pianoroll.dtype, np.number)):
        raise TypeError("The data type of `pianoroll` must be np.bool_ or a "
                        "subdtype of  np.number.")
    if pianoroll.ndim != 2:
        raise ValueError("`pianoroll` must have exactly two dimensions.")
    if pianoroll.shape[1] != 128:
        raise ValueError("The length of the second axis of `pianoroll` must be "
                         "128.")

def mode(self, mode):
        _LOGGER.debug("Setting new mode: %s", mode)

        if self.mode == Mode.Boost and mode != Mode.Boost:
            self.boost = False

        if mode == Mode.Boost:
            self.boost = True
            return
        elif mode == Mode.Away:
            end = datetime.now() + self._away_duration
            return self.set_away(end, self._away_temp)
        elif mode == Mode.Closed:
            return self.set_mode(0x40 | int(EQ3BT_OFF_TEMP * 2))
        elif mode == Mode.Open:
            return self.set_mode(0x40 | int(EQ3BT_ON_TEMP * 2))

        if mode == Mode.Manual:
            temperature = max(min(self._target_temperature, self.max_temp),
                              self.min_temp)
            return self.set_mode(0x40 | int(temperature * 2))
        else:
            return self.set_mode(0)

def get_files(files, extnames=['.root']):

    files_out = []
    for f in files:

        mime = mimetypes.guess_type(f)
        if os.path.splitext(f)[1] in extnames:
            files_out += [f]
        elif mime[0] == 'text/plain':
            files_out += list(np.loadtxt(f, unpack=True, dtype='str'))
        else:
            raise Exception('Unrecognized input type.')

    return files_out

