def _value_list_to_sciobj_dict(
    sciobj_value_list, lookup_list, lookup_dict, generate_dict
):

    sciobj_dict = {}

    # for sciobj_value, lookup_str in zip(sciobj_value_list, lookup_list):
    lookup_to_value_dict = {k: v for k, v in zip(lookup_list, sciobj_value_list)}

    for field_name, r_dict in lookup_dict.items():
        if r_dict["lookup_str"] in lookup_to_value_dict.keys():
            sciobj_dict[field_name] = lookup_to_value_dict[r_dict["lookup_str"]]

    for field_name, annotate_dict in generate_dict.items():
        for final_name, generate_func in annotate_dict["generate_dict"].items():
            sciobj_dict[field_name] = generate_func(lookup_to_value_dict)

    return sciobj_dict

def ClientFromConfig(engine, config, database, logger=None, verbose=True):

  if type(config) == list:
    config = dict(config)

  if engine == "couchbase":
    return Client(
      engine=engine,
      host=config.get("host"),
      auth=config.get("bucket_%s" % database),
      logger=logger,
      verbose=verbose
    )
  elif engine == "couchdb":

    if config.get("admin_user") and config.get("admin_password"):
      auth = "%s:%s" % (config.get("admin_user"), config.get("admin_password"))
    elif config.get("user") and config.get("password"):
      auth = "%s:%s" % (config.get("user"), config.get("password"))
    else:
      auth = None

    return Client(
      engine=engine,
      host=config.get("host"),
      auth=auth,
      database=config.get("db_%s" % database),
      logger=logger,
      verbose=verbose
    )
  elif engine == "dummydb":
    return Client(
      engine=engine
    )
  else:
    raise InvalidEngineException(engine)

def has_data(d, fullname):
    fullname = r'%s-' % (fullname, )
    for k in d:
        if not k.startswith(fullname):
            continue
        return True
    return False

def parse_fade_requirement(text):
    text = text.strip()

    if "::" in text:
        repo_raw, requirement = text.split("::", 1)
        try:
            repo = {'pypi': REPO_PYPI, 'vcs': REPO_VCS}[repo_raw]
        except KeyError:
            logger.warning("Not understood fades repository: %r", repo_raw)
            return
    else:
        if ":" in text and "/" in text:
            repo = REPO_VCS
        else:
            repo = REPO_PYPI
        requirement = text

    if repo == REPO_VCS:
        dependency = VCSDependency(requirement)
    else:
        dependency = list(parse_requirements(requirement))[0]
    return repo, dependency

def blocks_from_ops(ops):

    blocks = {}
    current_block = blocks[None] = Block()
    for op in ops:
        if isinstance(op, Label):
            next_block = blocks[op] = Block(op)
            current_block.next = next_block
            current_block = next_block
            continue
        current_block.ops.append(op)
    return blocks

