                self.illegal_lines['QTY 1'].append(
                    (-1, "**ERROR: UNEXPECTED REQUIRED VAL({V}) FOR COL({R}):{H}: ".format(
                        V=flds[col], H=self.gafhdr[col], R=col)))
                self.illegal_lines['QTY 1'].append((-1, "{H0}({DB}) {H1}({ID})\n".format(
