def _serialize_data(self, data):

        rels = {}
        rlink = rid_url(data['rtype'], data['rid'])

        doc = {
            'id': data.pop('rid'),
            'type': data.pop('rtype'),
            'links': {
                'self': rlink,
            },
        }

        for key, val in data['to_many'].items():
            rels.update(self._serialize_to_many(key, val, rlink))
        del data['to_many']

        for key, val in data['to_one'].items():
            rels.update(self._serialize_to_one(key, val, rlink))
        del data['to_one']

        if data:
            doc['attributes'] = data
        if rels:
            doc['relationships'] = rels

        return doc

def entrance_distance(Di, t=None, l=None, method='Rennels'):
    if method is None:
        method = 'Rennels'
    if method == 'Rennels':
        t_Di = t/Di
        if t_Di > 0.05:
            t_Di = 0.05
        return 1.12 + t_Di*(t_Di*(80.0*t_Di + 216.0) - 22.0)
    elif method == 'Miller':
        t_Di = t/Di
        if t_Di > 0.3:
            t_Di = 0.3
        return horner(entrance_distance_Miller_coeffs, 20.0/3.0*(t_Di - 0.15))
    elif method == 'Idelchik':
        if l is None:
            l = Di
        t_Di = min(t/Di, 1.0)
        l_Di = min(l/Di, 10.0)
        K = float(entrance_distance_Idelchik_obj(l_Di, t_Di))
        if K < 0.0:
            K = 0.0
        return K
    elif method == 'Harris':
        ratio = min(t/Di, 0.289145) # max value for interpolation - extrapolation looks bad
        K = float(entrance_distance_Harris_obj(ratio))
        return K
    elif method == 'Crane':
        return 0.78
    else:
        raise ValueError('Specified method not recognized; methods are %s'
                         %(entrance_distance_methods))

