def _translate_symbols(string):
    res = []
    string = str(string)
    for s in re.split(r'(\W+)', string, flags=re.UNICODE):
        tex_str = _GREEK_DICTIONARY.get(s)
        if tex_str:
            res.append(tex_str)
        elif s.lower() in _GREEK_DICTIONARY:
            res.append(_GREEK_DICTIONARY[s])
        else:
            res.append(s)
    return "".join(res)

def fill_auth_list(self, auth_provider, name, groups, auth_list=None, permissive=None):
        if auth_list is None:
            auth_list = []
        if permissive is None:
            permissive = self.opts.get('permissive_acl')
        name_matched = False
        for match in auth_provider:
            if match == '*' and not permissive:
                continue
            if match.endswith('%'):
                if match.rstrip('%') in groups:
                    auth_list.extend(auth_provider[match])
            else:
                if salt.utils.stringutils.expr_match(match, name):
                    name_matched = True
                    auth_list.extend(auth_provider[match])
        if not permissive and not name_matched and '*' in auth_provider:
            auth_list.extend(auth_provider['*'])
        return auth_list

def to_lal_type_str(pytype):
    # noop
    if pytype in LAL_TYPE_FROM_STR:
        return pytype

    # convert type code
    if pytype in LAL_TYPE_STR:
        return LAL_TYPE_STR[pytype]

    # convert python type
    try:
        dtype = numpy.dtype(pytype)
        return LAL_TYPE_STR_FROM_NUMPY[dtype.type]
    except (TypeError, KeyError):
        raise ValueError("Failed to map {!r} to LAL type string")

def mach53(msg):
    d = hex2bin(data(msg))

    if d[23] == '0':
        return None

    mach = bin2int(d[24:33]) * 0.008
    return round(mach, 3)

def shrink_patch(patch_path, target_file):
    logging.debug("Shrinking patch file %s to keep only %s changes.", patch_path, target_file)
    shrinked_lines = []
    patch_file = None
    try:
        patch_file = open(patch_path)
        adding = False
        search_line = "diff --git a/%s b/%s" % (target_file, target_file)
        for line in patch_file.read().split("\n"):
            if adding and line.startswith("diff --git a/") and line != search_line:
                adding = False
            elif line == search_line:
                adding = True
            if adding:
                shrinked_lines.append(line)
    finally:
        if patch_file:
            patch_file.close()

    if len(shrinked_lines):
        patch_file = None
        try:
            patch_file = open(patch_path, "w")
            content = "\n".join(shrinked_lines)
            if not content.endswith("\n"):
                content = content + "\n"
            patch_file.write(content)
        finally:
            if patch_file:
                patch_file.close()
        return True
    else:
        return False

def _parse_scheme_file(self):
        schemes = json.loads(self.scheme_file.read(), object_pairs_hook=OrderedDict)
        scheme_list = []
        scheme_dict = defaultdict(list)
        for scheme_len, scheme_group in schemes.items():
            for scheme_str, _count in scheme_group:
                scheme_code = tuple(int(c) for c in scheme_str.split(' '))
                scheme_list.append(scheme_code)
                scheme_dict[int(scheme_len)].append(len(scheme_list) - 1)
        return scheme_list, scheme_dict

