def encipher(self, string):
        string = self.remove_punctuation(string)  
        string = re.sub(r'[J]', 'I', string)
        if len(string) % 2 == 1:
            string += 'X'
        ret = ''
        for c in range(0, len(string), 2):
            ret += self.encipher_pair(string[c], string[c + 1])
        return ret

