def make_idx(f, lb, ub):

    idx0 = np.argmin(np.abs(f - lb))
    idx1 = np.argmin(np.abs(f - ub))

    # Determine which should be on which side
    if f[0] > f[1]:
        direction = -1
    else:
        direction = 1

    if direction == -1:
        idx = slice(idx1, idx0)
    elif direction == 1:
        idx = slice(idx0, idx1)

    return idx

