def substances_to_frame(substances, properties=None):
    import pandas as pd
    if isinstance(substances, Substance):
        substances = [substances]
    properties = set(properties) | set(['sid']) if properties else None
    return pd.DataFrame.from_records([s.to_dict(properties) for s in substances], index='sid')

def dumps(module, cls=PVLEncoder, **kwargs):
    stream = io.BytesIO()
    cls(**kwargs).encode(module, stream)
    return stream.getvalue()

def predict(data, training_dir=None, model_name=None, model_version=None, cloud=False):
  if cloud:
    if not model_version or not model_name:
      raise ValueError('model_version or model_name is not set')
    if training_dir:
      raise ValueError('training_dir not needed when cloud is True')
    with warnings.catch_warnings():
      warnings.simplefilter("ignore")
      return cloud_predict(model_name, model_version, data)
  else:
    if not training_dir:
      raise ValueError('training_dir is not set')
    if model_version or model_name:
      raise ValueError('model_name and model_version not needed when cloud is '
                       'False.')
    with warnings.catch_warnings():
      warnings.simplefilter("ignore")
      return local_predict(training_dir, data)

def match(self, **kwargs):
        if kwargs:
            if self.definition.get('model') is None:
                raise ValueError("match() with filter only available on relationships with a model")
            output = process_filter_args(self.definition['model'], kwargs)
            if output:
                self.filters.append(output)
        return self

def _parse_response(response, post_request=False):
        data = response.json()

        if not response.ok:
            utils.error_message_and_exit('Push Api Error:', data)

        if post_request and not data['success']:
            raise Exception('Push Api Error: [%s]' % data['error'])

        return data

def get_all(cls, names):
        names = cls._get_iterable_for_names(names)

        queues = []
        for queue_name in names:
            queues.extend(cls.collection(name=queue_name).instances())

        return queues

def get_parallel_bucket(buckets: List[Tuple[int, int]],
                        length_source: int,
                        length_target: int) -> Tuple[Optional[int], Optional[Tuple[int, int]]]:
    for j, (source_bkt, target_bkt) in enumerate(buckets):
        if source_bkt >= length_source and target_bkt >= length_target:
            return j, (source_bkt, target_bkt)
    return None, None

def print_to_file(object_name):
    with open('pyoutput.txt', 'w') as filehandler:
        output = None
        if isinstance(object_name, list):
            output = json.dumps(object, indent=4)
        if isinstance(object_name, dict):
            output = json.dumps(object, indent=4)
        if isinstance(object_name, str):
            output = object_name
        filehandler.write(output)

def get_missing_bins(original, trimmed):

    original_diag = np.diag(original)
    trimmed_diag = np.diag(trimmed)
    index = []
    m = min(original.shape)
    for j in range(min(trimmed.shape)):
        k = 0
        while original_diag[j + k] != trimmed_diag[j] and k < 2 * m:
            k += 1
        index.append(k + j)
    return np.array(index)

def _scopes_registered(self):
        scopes = []

        for name in dir(self.__class__):
            if name.startswith('scope_'):
                scope = name.split('scope_')[1]
                scopes.append(scope)

        return scopes

def remove(self, iocb):
        if _debug: IOQueue._debug("remove %r", iocb)

        # remove the request from the queue
        for i, item in enumerate(self.queue):
            if iocb is item[1]:
                if _debug: IOQueue._debug("    - found at %d", i)
                del self.queue[i]

                # if the queue is empty, clear the event
                qlen = len(self.queue)
                if not qlen:
                    self.notempty.clear()

                # record the new length
                # self.queuesize.Record( qlen, _time() )
                break
        else:
            if _debug: IOQueue._debug("    - not found")

