def create_response_pdu(self):
        fmt = '>BHH'
        return struct.pack(fmt, self.function_code, self.address, self._value)

def input_connections(self, name):
        for input_name in self._compound_children[name].inputs:
            dest = name, input_name
            for src, dests in self._compound_linkages.items():
                if isinstance(dests[0], six.string_types):
                    dests = zip(dests[0::2], dests[1::2])
                if dest in dests:
                    yield src, dest

def create_forwarding_information_base(self, timeout=-1):
        uri = "{}{}".format(self.data["uri"], self.FORWARDING_INFORMATION_PATH)
        return self._helper.do_post(uri, None, timeout, None)

def update_site(self, client_secret_expires_at=None):
        params = {
            "oxd_id": self.oxd_id,
            "authorization_redirect_uri": self.authorization_redirect_uri
        }

        if client_secret_expires_at:
            params["client_secret_expires_at"] = client_secret_expires_at

        for param in self.opt_params:
            if self.config.get("client", param):
                value = self.config.get("client", param)
                params[param] = value

        for param in self.opt_list_params:
            if self.config.get("client", param):
                value = self.config.get("client", param).split(",")
                params[param] = value

        logger.debug("Sending `update_site` with params %s",
                     params)
        response = self.msgr.request("update_site", **params)
        logger.debug("Received response: %s", response)

        if response['status'] == 'error':
            raise OxdServerError(response['data'])

        return True

def try_opening_file(self):
        if os.path.isfile(self.path):
            self.file = open(self.path, 'r')
            self.file_is_opened = True

def iterstruct(self):
        from rowgenerators.rowpipe.json import add_to_struct

        json_headers = self.json_headers

        for row in islice(self, 1, None): # islice skips header
            d = {}
            for pos, jh in json_headers:
                add_to_struct(d, jh, row[pos])
            yield d

def shelf(self, shelf=None):
        if shelf is None:
            self._shelf = Shelf({})
        elif isinstance(shelf, Shelf):
            self._shelf = shelf
        elif isinstance(shelf, dict):
            self._shelf = Shelf(shelf)
        else:
            raise BadRecipe('shelf must be a dict or recipe.shelf.Shelf')

        if self._select_from is None and \
            self._shelf.Meta.select_from is not None:
            self._select_from = self._shelf.Meta.select_from
        return self

def get_prt_fmt(self, alt=False):
        # prt_fmt = [ #                                                        rcnt
        #     '{GO} # {NS}  L{level:02} D{depth:02} {GO_name}',
        #     '{GO} # {NS} {dcnt:6,} L{level:02} D{depth:02} {D1:5} {GO_name}']
        prt_fmt = []
        if alt:
            prt_fmt.append('{GO}{alt:1}')
        else:
            prt_fmt.append('{GO}')
        prt_fmt.append('# {NS}')
        if 'dcnt' in self.prt_flds:
            prt_fmt.append('{dcnt:5}')
        if 'childcnt' in self.prt_flds:
            prt_fmt.append('{childcnt:3}')
        if 'tcnt' in self.prt_flds:
            prt_fmt.append("{tcnt:7,}")
        if 'tfreq' in self.prt_flds:
            prt_fmt.append("{tfreq:8.6f}")
        if 'tinfo' in self.prt_flds:
            prt_fmt.append("{tinfo:5.2f}")
        prt_fmt.append('L{level:02} D{depth:02}')
        if self.relationships:
            prt_fmt.append('R{reldepth:02}')
        if 'D1' in self.prt_flds:
            prt_fmt.append('{D1:5}')
        if 'REL' in self.prt_flds:
            prt_fmt.append('{REL}')
            prt_fmt.append('{rel}')
        prt_fmt.append('{GO_name}')
        return " ".join(prt_fmt)

