def get_last(postid):
        recs = TabWikiHist.select().where(
            TabWikiHist.wiki_id == postid
        ).order_by(TabWikiHist.time_update.desc())

        return None if recs.count() == 0 else recs.get()

def CopyNoFail(src, root=None):
    if root is None:
        root = str(CFG["tmp_dir"])
    src_path = local.path(root) / src

    if src_path.exists():
        Copy(src_path, '.')
        return True
    return False

def get_permissions(self, namespace, explicit=False):

        if not isinstance(namespace, Namespace):
            namespace = Namespace(namespace)
        keys = namespace.keys
        p, _ = self._check(keys, self.index, explicit=explicit)
        return p

def get_metric_fns(metric_names, labels, outputs):
  metric_fns = {}
  for metric_name in metric_names:
    metric_fn_name = metric_name.split("/")[-1]
    if hasattr(metrics, metric_fn_name):
      metric_fn = getattr(metrics, metric_fn_name)
      metric_fns[metric_name] = metric_fn(labels, outputs)
    else:
      raise ValueError("Metric {} is not implemented".format(metric_fn_name))

  return metric_fns

