            # only events from shortcut keys, but ignore it anyway)
            pass

def unwrap(msmt):

    if np.isscalar(msmt):
        return float(msmt)
    if isinstance(msmt, (Uval, Lval)):
        return msmt
    if isinstance(msmt, Textual):
        return msmt.unwrap()
    raise ValueError('don\'t know how to treat %r as a measurement' % msmt)

def operations(self):
        api_version = self._get_api_version('operations')
        if api_version == '2017-03-01':
            from .v2017_03_01.operations import Operations as OperationClass
        elif api_version == '2017-10-01':
            from .v2017_10_01.operations import Operations as OperationClass
        elif api_version == '2018-02-01-preview':
            from .v2018_02_01_preview.operations import Operations as OperationClass
        elif api_version == '2018-09-01':
            from .v2018_09_01.operations import Operations as OperationClass
        else:
            raise NotImplementedError("APIVersion {} is not available".format(api_version))
        return OperationClass(self._client, self.config, Serializer(self._models_dict(api_version)), Deserializer(self._models_dict(api_version)))

def json_url_error_handler(urls=()):
    if type(urls) is str:
        urls = [urls]

    # the handler itself
    def handler(exception):
        http_exception = isinstance(exception, exceptions.HTTPException)
        code = exception.code if http_exception else 500

        # log exceptions only (app debug should be off)
        if code == 500:
            current_app.logger.error(exception)

        # if matches one of urls, return json
        if has_app_context() and has_request_context():
            for prefix in urls:
                prefix = prefix.strip('/')
                prefix = '/' + prefix + '/' if len(prefix) else '/'
                if request.path.startswith(prefix):
                    return json_error_handler(exception)

        # otherwise fall back to error page handler
        return template_error_handler(exception)

    return handler

def simplify(self):
        node = self.node.simplify()
        if node is self.node:
            return self
        else:
            return _expr(node)

def flatmap(source, func, *more_sources, task_limit=None):
    return flatten.raw(
        combine.smap.raw(source, func, *more_sources), task_limit=task_limit)

def stop(self):
        if not self._enabled:
            return self

        if self._spinner_thread:
            self._stop_spinner.set()
            self._spinner_thread.join()

        self._frame_index = 0
        self._spinner_id = None
        self.clear()

        if self._stream.isatty():
            cursor.show(stream=self._stream)

        return self

def _fetch_all(self):
        if self._result_cache is None:
            self._result_cache = list(self.iterator())
            # TODO: Do we have to test for ValuesListIterable, ValuesIterable,
            # and FlatValuesListIterable here?
            if self._iterable_class == ModelIterable:
                for x in self._result_cache:
                    self._set_item_querytime(x)
        if self._prefetch_related_lookups and not self._prefetch_done:
            self._prefetch_related_objects()

def _record_info(self, setup_info=None):
        info_path = os.path.join(self.root_directory, ('%s.info' % self.batch_name))

        if setup_info is None:
            try:
                with open(info_path, 'r') as info_file:
                    setup_info = json.load(info_file)
            except:
                setup_info = {}

            setup_info.update({'end_time' : tuple(time.localtime())})
        else:
            setup_info.update({
                'end_time' : None,
                'metadata' : self.metadata
                })

        with open(info_path, 'w') as info_file:
            json.dump(setup_info, info_file, sort_keys=True, indent=4)

def to_triplets(colors):
    try:
        colors[0][0]
        return colors
    except:
        pass

    # It's a 1-dimensional list
    extra = len(colors) % 3
    if extra:
        colors = colors[:-extra]
    return list(zip(*[iter(colors)] * 3))

def raw_parts(self):
        path = self._val.path
        if self.is_absolute():
            if not path:
                parts = ["/"]
            else:
                parts = ["/"] + path[1:].split("/")
        else:
            if path.startswith("/"):
                parts = ["/"] + path[1:].split("/")
            else:
                parts = path.split("/")
        return tuple(parts)

def calc_seal_volume(mass_kg, dens_kgm3, length=None, girth=None):
    if (length is not None) and (girth is not None):
        _, seal_vol = surf_vol(length, girth)
    else:
        seal_vol = mass_kg / dens_kgm3

    return seal_vol

def child_at_index(self, name, index):

        def _finder(n, i):
            try:
                return self.indexes[n][i]
            except (KeyError, IndexError):
                try:
                    return self.traversal_indexes[n][i]
                except (KeyError, IndexError):
                    return None

        child = _finder(name, index)
        child_name = None if name is None else self._find_name(name)
        if child_name != name:
            child = _finder(child_name, index)
        return child

def get_form_kwargs(self):
        kwargs = {'initial': self.get_initial(),
                  'instance': self.object}

        if self.request.method in ('POST', 'PUT') and self.can_submit:
            kwargs.update({
                'data': self.request.POST,
                'files': self.request.FILES
            })
        return kwargs

