def momentum(self, exponent=1, errorrequested=True):
        y = self.Intensity * self.q ** exponent
        m = np.trapz(y, self.q)
        if errorrequested:
            err = self.Error * self.q ** exponent
            dm = errtrapz(self.q, err)
            return ErrorValue(m, dm)
        else:
            return m

def _write_value(value, path):
    base_command = "echo '{0}' > {1}"
    # There is no common method for redirecting stderr to a null sink, so the
    # command string is platform-dependent
    if platform == 'win32':
        command = "{0} > NUL".format(base_command)
    else:
        command = "exec 2> /dev/null; {0}".format(base_command)
    os.system(command.format(value, path))

def primes(start: int = 1, end: int = 999) -> List[int]:
        # TODO: It should generate random primes with passed length.
        sieve_size = (end // 2 - 1) if end % 2 == 0 else (end // 2)
        sieve = [True] * sieve_size

        primes = []  # list of primes
        # add 2 to the list if it's in the given range
        if end >= 2:
            primes.append(2)
        for i in range(sieve_size):
            if sieve[i]:
                value_at_i = i * 2 + 3
                primes.append(value_at_i)
                for j in range(i, sieve_size, value_at_i):
                    sieve[j] = False

        chop_index = 0
        for i in range(len(primes)):
            if primes[i] >= start:
                chop_index = i
                break
        return primes[chop_index:]

