def loadtxtargs(self):

        d = dict()
        d.update(delimiter=self.datdel, skiprows=self.rts)

        if self.decdel == '.':
            # First valid row of data.
            cols = range(self.matches_p[self.rts + 1])
        else:
            cols = range(self.matches_c[self.rts + 1])
            # Converter needed for float, decdel is comma:
            convd = {}
            for i in cols:
                convd[i] = _floatit
                d.update(converters=convd)
        d.update(usecols=cols)

        return d

def quat2Pitch(qw, qx, qy, qz):

    rotateYa0=-2.0*(qx*qz - qw*qy)
    rotateY=0.0
    if(rotateYa0 >= 1.0):
        rotateY = pi/2.0
    elif(rotateYa0 <= -1.0):
        rotateY = -pi/2.0
    else:
        rotateY = asin(rotateYa0)

    return rotateY

def round_robin(self, x, y, n_keep):
        vals = y.unique()
        scores = {}
        for cls in vals:
            scores[cls] = self.rank(x, np.equal(cls, y).astype('Int64'))
            scores[cls].reverse()
        keepers = set()
        while len(keepers) < n_keep:
            for cls in vals:
                keepers.add(scores[cls].pop()[1])
        return list(keepers)

