def loadBatch(self, records):
        try:
            curr_batch = records[:self.batchSize()]
            next_batch = records[self.batchSize():]

            curr_records = list(curr_batch)
            if self._preloadColumns:
                for record in curr_records:
                    record.recordValues(self._preloadColumns)

            if len(curr_records) == self.batchSize():
                self.loadedRecords[object, object].emit(curr_records,
                                                        next_batch)
            else:
                self.loadedRecords[object].emit(curr_records)

        except ConnectionLostError:
            self.connectionLost.emit()

        except Interruption:
            pass

def getStreamNetworkAsWkt(self, session, withNodes=True):
        wkt_list = []

        for link in self.streamLinks:
            wkt_link = link.getAsWkt(session)

            if wkt_link:
                wkt_list.append(wkt_link)

            if withNodes:
                for node in link.nodes:
                    wkt_node = node.getAsWkt(session)

                    if wkt_node:
                        wkt_list.append(wkt_node)

        return 'GEOMCOLLECTION ({0})'.format(', '.join(wkt_list))

def load_ia_module(cmd):
    try:
        if cmd in list(cmd_aliases.keys()) + list(cmd_aliases.values()):
            _module = 'internetarchive.cli.ia_{0}'.format(cmd)
            return __import__(_module, fromlist=['internetarchive.cli'])
        else:
            _module = 'ia_{0}'.format(cmd)
            for ep in iter_entry_points('internetarchive.cli.plugins'):
                if ep.name == _module:
                    return ep.load()
            raise ImportError
    except (ImportError, DistributionNotFound):
        print("error: '{0}' is not an ia command! See 'ia help'".format(cmd),
              file=sys.stderr)
        matches = '\t'.join(difflib.get_close_matches(cmd, cmd_aliases.values()))
        if matches:
            print('\nDid you mean one of these?\n\t{0}'.format(matches))
        sys.exit(127)

