def _decode(self, data):
        informat = self.config['input_format'].lower()
        if informat == 'spinn3r':
            return _generate_stream_items(data)
        elif informat == 'streamitem':
            ver = self.config['streamcorpus_version']
            if ver not in _message_versions:
                raise ConfigurationError(
                    'Not a valid streamcorpus version: %s '
                    '(choose from: %s)'
                    % (ver, ', '.join(_message_versions.keys())))

            message = _message_versions[ver]
            return streamcorpus.Chunk(data=data, message=message)
        elif informat == 'featurecollection' and FCChunk is not None:
            return FCChunk(data=data)
        else:
            raise ConfigurationError(
                'from_s3_chunks unknown input_format = %r'
                % informat)

def get_function_annotations(event, funcname, type=None, namespace=None):
    if type:
        postfix = "|" + type
    else:
        postfix = "|.+"

    def matchfunc(key, annkey):
        """Check if the provider regex matches an annotation key."""
        return re.match(key, annkey) is not None

    return get_annotations(event, funcname + postfix, namespace=namespace,
                           matchfunc=matchfunc)

def environment(**kv):
    added = []
    changed = {}
    for key, value in kv.items():
        if key not in os.environ:
            added.append(key)
        else:
            changed[key] = os.environ[key]
        os.environ[key] = value

    yield

    # restore pristine process environment
    for key in added:
        del os.environ[key]
    for key in changed:
        os.environ[key] = changed[key]

