def get_option(namespace, option_name):
    envvalue = _get_env_value(namespace, option_name)

    idx = 0
    final_value = []

    if envvalue:
        final_value.append(envvalue)

    while _get_env_value(namespace, option_name, idx):
        final_value.append(_get_env_value(namespace, option_name, idx))
        idx += 1

    return final_value

def fingerprint_file(workspace, filename):
  content = read_file(os.path.join(workspace, filename), binary_mode=True)
  fingerprint = hashlib.sha256(content)
  b64_encoded = base64.b64encode(fingerprint.digest())
  return 'sha256={}'.format(b64_encoded.decode('utf-8')), str(len(content))

def configure(self, options):
        self.options = options
        if self.options.get('lock_dir', None):
            self.core.set_option(self.core.SECTION, "lock_dir", self.options['lock_dir'])
        if self.options.get('ignore_lock', None):
            self.core.set_option(self.core.SECTION, 'ignore_lock', self.options['ignore_lock'])

        while True:
            try:
                self.core.get_lock()
                break
            except Exception as exc:
                if self.options.get('lock_fail', None):
                    raise RuntimeError("Lock file present, cannot continue")
                self.log.info(
                    "Couldn't get lock. Will retry in 5 seconds... (%s)",
                    str(exc))
                time.sleep(5)

        configs = self.get_default_configs()
        if self.options.get('config', None):
            configs.append(self.options['config'])
        self.core.load_configs(configs)
        self.__add_user_options()
        self.core.load_plugins()

        if self.options.get('ignore_lock', None):
            self.core.set_option(self.core.SECTION, self.IGNORE_LOCKS, "1")

def clear(self, asset_manager_id, book_ids=None):
        self.logger.info('Clear Transactions & Positions - Asset Manager: %s', asset_manager_id)
        url = '%s/clear/%s' % (self.endpoint, asset_manager_id)
        params = {'asset_manager_ids': ','.join(book_ids)} if book_ids else {}
        response = self.session.delete(url, params=params)
        if response.ok:
            tran_count = response.json().get('transaction_count', 'Unknown')
            self.logger.info('Deleted %s Transactions.', tran_count)
            pos_count = response.json().get('position_count', 'Unknown')
            self.logger.info('Deleted %s Positions.', pos_count)
            return response.json()
        else:
            self.logger.error(response.text)
            response.raise_for_status()

