def _defer_to_worker(deliver, worker, work, *args, **kwargs):
    deferred = Deferred()

    def wrapped_work():
        try:
            result = work(*args, **kwargs)
        except BaseException:
            f = Failure()
            deliver(lambda: deferred.errback(f))
        else:
            deliver(lambda: deferred.callback(result))
    worker.do(wrapped_work)
    return deferred

def inv_shift_rows(state):
    state = state.reshape(4, 4, 8)
    return fcat(
        state[0][0], state[3][1], state[2][2], state[1][3],
        state[1][0], state[0][1], state[3][2], state[2][3],
        state[2][0], state[1][1], state[0][2], state[3][3],
        state[3][0], state[2][1], state[1][2], state[0][3]
    )

