def drag(self, dragFrom=None):
        if dragFrom is None:
            dragFrom = self._lastMatch or self # Whichever one is not None
        tmp = None
        if isinstance(dragFrom, Pattern):
            tmp = self.find(dragFrom).getTarget()
        elif isinstance(dragFrom, basestring):
            tmp = self.find(dragFrom).getTarget()
        elif isinstance(dragFrom, Match):
            tmp = dragFrom.getTarget()
        elif isinstance(dragFrom, Region):
            tmp = dragFrom.getCenter()
        elif isinstance(dragFrom, Location):
            tmp = dragFrom
        else:
            raise TypeError("drag expected dragFrom to be Pattern, String, Match, Region, or Location object")
        Mouse.moveSpeed(tmp, Settings.MoveMouseDelay)
        time.sleep(Settings.DelayBeforeMouseDown)
        Mouse.buttonDown()
        Debug.history("Began drag at {}".format(tmp))

def from_json(cls, data):
        # assign default values
        assert 'data_type' in data, 'Required keyword "data_type" is missing!'
        keys = ('data_type', 'unit', 'analysis_period', 'metadata')
        for key in keys:
            if key not in data:
                data[key] = None

        data_type = DataTypeBase.from_json(data['data_type'])
        ap = AnalysisPeriod.from_json(data['analysis_period'])
        return cls(data_type, data['unit'], ap, data['metadata'])

def validate_single_matching_uri(all_blockchain_uris: List[str], w3: Web3) -> str:
    matching_uris = [
        uri for uri in all_blockchain_uris if check_if_chain_matches_chain_uri(w3, uri)
    ]

    if not matching_uris:
        raise ValidationError("Package has no matching URIs on chain.")
    elif len(matching_uris) != 1:
        raise ValidationError(
            f"Package has too many ({len(matching_uris)}) matching URIs: {matching_uris}."
        )
    return matching_uris[0]

def choice(*es):
    msg = 'Expected one of: {}'.format(', '.join(map(repr, es)))
    def match_choice(s, grm=None, pos=0):
        errs = []
        for e in es:
            try:
                return e(s, grm, pos)
            except PegreError as ex:
                errs.append((ex.message, ex.position))
        if errs:
            raise PegreChoiceError(errs, pos)
    return match_choice

def legacy_signature(**kwargs_mapping):

    def signature_decorator(f):
        @wraps(f)
        def wrapper(*args, **kwargs):
            redirected_kwargs = {
                kwargs_mapping[k] if k in kwargs_mapping else k: v
                for k, v in kwargs.items()
            }
            return f(*args, **redirected_kwargs)

        return wrapper

    return signature_decorator

def decide_slices(self, data_shapes):
        assert len(data_shapes) > 0
        major_axis = [DataDesc.get_batch_axis(x.layout) for x in data_shapes]

        for (name, shape), axis in zip(data_shapes, major_axis):
            if axis == -1:
                continue

            batch_size = shape[axis]
            if self.batch_size is not None:
                assert batch_size == self.batch_size, ("all data must have the same batch size: "
                                                       + ("batch_size = %d, but " % self.batch_size)
                                                       + ("%s has shape %s" % (name, shape)))
            else:
                self.batch_size = batch_size
                self.slices = _split_input_slice(self.batch_size, self.workload)

        return major_axis

