def read(self, relpath, rsc=None, mode='r', useFilepath=None):
        f = self.load(relpath, rsc, mode, useFilepath=useFilepath)
        if f is None:
            return ''

        # use a QFile
        if isinstance(f, QtCore.QFile):
            if f.open(QtCore.QFile.ReadOnly):
                data = nativestring(f.readAll())
                f.close()
            else:
                data = ''
        else:
            data = f.read()
            f.close()

        return data

