def extract_match(self, list_title_matches):
        # Create a set of the extracted titles
        list_title_matches_set = set(list_title_matches)

        list_title_count = []
        # Count how often a title was matched and safe as tuple in list.
        for match in list_title_matches_set:
            list_title_count.append((list_title_matches.count(match), match))

        if list_title_count and max(list_title_count)[0] != min(list_title_count)[0]:
            return max(list_title_count)[1]

        return None

def Jpjmcoeff(ls, m, shift=False) -> sympy.Expr:
    assert isinstance(ls, SpinSpace)
    n = ls.dimension
    s = sympify(n - 1) / 2
    assert n == int(2 * s + 1)
    if isinstance(m, str):
        m = ls.basis_labels.index(m) - s  # m is now Sympy expression
    elif isinstance(m, int):
        if shift:
            assert 0 <= m < n
            m = m - s
    return sqrt(s * (s + 1) - m * (m + 1))

def bind(cls, param=None, **kwargs):
        def stick(function, **binding):
            if not asyncio.iscoroutine(function):
                function = asyncio.coroutine(function)
            bindings = getattr(function, STICKER, [])
            bindings.append(binding)
            setattr(function, STICKER, bindings)
            return function
        if isinstance(param, str):
            return partial(stick, prefix=param, **kwargs)
        return stick(param, **kwargs)

