        try:
            from . import sessions
        except ImportError:
            raise OperationFailed()
        proxy = self._convert_proxy(proxy)
        try:
            session = sessions.FamilyLookupSession(proxy=proxy, runtime=self._runtime, **kwargs)
        except AttributeError:
            raise OperationFailed()
        return session

def parse_requirements(requirements_filename):
    dependencies, dependency_links = [], []
    requirements_dir = os.path.dirname(requirements_filename)
    with open(requirements_filename, 'r') as stream:
        for line in stream:
            line = line.strip()
            if line.startswith("-r"):
                tmp = os.path.join(requirements_dir, line[2:].strip())
                _dependencies, _dependency_links = parse_requirements(tmp)
                dependencies.extend(_dependencies)
                dependency_links.extend(_dependency_links)
            elif line.startswith("http"):
                dependency_links.append(line)
            else:
                package = line.split('#')[0]
                if package:
                    dependencies.append(package)
    return dependencies, dependency_links

