def traverse_dict(data, key, default=None, delimiter=DEFAULT_TARGET_DELIM):
    ptr = data
    try:
        for each in key.split(delimiter):
            ptr = ptr[each]
    except (KeyError, IndexError, TypeError):
        # Encountered a non-indexable value in the middle of traversing
        return default
    return ptr

