def python_modules():
        imported = {}
        results = {"builtins": sys.builtin_module_names, "imported": imported}
        for module_name, module_ in sys.modules.items():
            if module_name not in sys.builtin_module_names:
                try:
                    imported[module_name] = inspect.getfile(module_)
                except TypeError:
                    imported[
                        module_name
                    ] = "<no file information :: {0}>".format(repr(module_))

        return results

def ordered_yaml(cfg, order=None):
    if order is None:
        order = ['name', 'model_type', 'segmentation_col', 'fit_filters',
                 'predict_filters',
                 'choosers_fit_filters', 'choosers_predict_filters',
                 'alts_fit_filters', 'alts_predict_filters',
                 'interaction_predict_filters',
                 'choice_column', 'sample_size', 'estimation_sample_size',
                 'prediction_sample_size',
                 'model_expression', 'ytransform', 'min_segment_size',
                 'default_config', 'models', 'coefficients', 'fitted']

    s = []
    for key in order:
        if key not in cfg:
            continue
        s.append(
            yaml.dump({key: cfg[key]}, default_flow_style=False, indent=4))

    for key in cfg:
        if key in order:
            continue
        s.append(
            yaml.dump({key: cfg[key]}, default_flow_style=False, indent=4))

    return '\n'.join(s)

