def data_find(data, path):
    path_parts = path.split("/")
    try:
        sub_elm = [
            el
            for el in data
            if isinstance(el, (tuple, list)) and el[0] == path_parts[0]
        ][0]
    except IndexError:
        return None
    else:
        if len(path_parts) > 1:
            return data_find(sub_elm, "/".join(path_parts[1:]))
        return sub_elm

def _get_values_from_auxiliaryfile(self, auxfile):
        try:
            frame = inspect.currentframe().f_back.f_back
            while frame:
                namespace = frame.f_locals
                try:
                    subnamespace = {'model': namespace['model'],
                                    'focus': self}
                    break
                except KeyError:
                    frame = frame.f_back
            else:
                raise RuntimeError(
                    'Cannot determine the corresponding model.  Use the '
                    '`auxfile` keyword in usual parameter control files only.')
            filetools.ControlManager.read2dict(auxfile, subnamespace)
            try:
                subself = subnamespace[self.name]
            except KeyError:
                raise RuntimeError(
                    f'The selected file does not define value(s) for '
                    f'parameter {self.name}')
            return subself.values
        except BaseException:
            objecttools.augment_excmessage(
                f'While trying to extract information for parameter '
                f'`{self.name}` from file `{auxfile}`')

def _recursive_option_registration_args(self):
    if self._parent_parser:
      for args, kwargs in self._parent_parser._recursive_option_registration_args():
        yield args, kwargs
    for args, kwargs in self._option_registrations:
      # Note that all subsystem options are implicitly recursive: a subscope of a subsystem
      # scope is another (optionable-specific) instance of the same subsystem, so it needs
      # all the same options.
      if self._scope_info.category == ScopeInfo.SUBSYSTEM or 'recursive' in kwargs:
        yield args, kwargs

def download(self, id, directory):
        url = (self._base + 'lot/{0}/download').format(id)
        r = requests.get(url, auth=self._auth, stream=True)
        file_name = r.headers['Content-Disposition'].split('"')[-2]

        if len(directory) < 1:
            return

        with open(os.path.join(directory, file_name), 'wb') as file:
            for chunk in r.iter_content(chunk_size=1024):
                if chunk:
                    file.write(chunk)
                    file.flush()

