def endless_permutations(N, random_state=None):
    generator = check_random_state(random_state)
    while True:
        batch_inds = generator.permutation(N)
        for b in batch_inds:
            yield b

def _update_field(self, action, field, value, max_tries, tries=0):
        # Refresh our view of the document.
        self.fetch()

        # Update the field.
        action(self, field, value)

        # Attempt to save, retrying conflicts up to max_tries.
        try:
            self.save()
        except requests.HTTPError as ex:
            if tries < max_tries and ex.response.status_code == 409:
                self._update_field(
                    action, field, value, max_tries, tries=tries+1)
            else:
                raise

def fmt_addr_raw(addr, reverse=True):
    addr = addr.replace(':', '')
    raw_addr = [int(addr[i:i+2], 16) for i in range(0, len(addr), 2)]
    if reverse:
        raw_addr.reverse()

    # for Python 2, this needs to be a string instead of a bytearray
    if sys.version_info[0] == 2:
        return str(bytearray(raw_addr))
    return bytearray(raw_addr)

