def set_broadcast_layout(self, broadcast_id, layout_type, stylesheet=None):
        payload = {
            'type': layout_type,
        }

        if layout_type == 'custom':
            if stylesheet is not None:
                payload['stylesheet'] = stylesheet

        endpoint = self.endpoints.broadcast_url(broadcast_id, layout=True)
        response = requests.put(
            endpoint,
            data=json.dumps(payload),
            headers=self.json_headers(),
            proxies=self.proxies,
            timeout=self.timeout
        )

        if response.status_code == 200:
            pass
        elif response.status_code == 400:
            raise BroadcastError(
                'Invalid request. This response may indicate that data in your request data is '
                'invalid JSON. It may also indicate that you passed in invalid layout options.')
        elif response.status_code == 403:
            raise AuthError('Authentication error.')
        else:
            raise RequestError('OpenTok server error.', response.status_code)

def get(self, timeout=0):
        self._autoclean()
        if timeout < 0:
            uid = self._redis.rpoplpush(self.QUEUE_KEY, self.ACKBUF_KEY)
        else:
            uid = self._redis.brpoplpush(self.QUEUE_KEY, self.ACKBUF_KEY, timeout)
        item = self._redis.hget(self.ITEMS_KEY, uid)

        # Deserialize only if the item exists: it is equal to None if it times out
        if self.serializer is not None and item is not None:
            item = self.serializer.loads(item)

        return uid, item

