def get_bundle_ref(args, l, use_history=False):

    if not use_history:

        if args.id:
            return (args.id, '-i argument')

        if hasattr(args, 'bundle_ref') and args.bundle_ref:
            return (args.bundle_ref, 'bundle_ref argument')


        if 'AMBRY_BUNDLE' in os.environ:
            return (os.environ['AMBRY_BUNDLE'], 'environment')

        cwd_bundle = os.path.join(os.getcwd(), 'bundle.yaml')

        if os.path.exists(cwd_bundle):

            with open(cwd_bundle) as f:
                from ambry.identity import Identity

                config = yaml.load(f)
                try:
                    ident = Identity.from_dict(config['identity'])
                    return (ident.vid, 'directory')
                except KeyError:
                    pass

    history = l.edit_history()

    if history:
        return (history[0].d_vid, 'history')

    return None, None

def unget_service(self, factory, svc_registration, service=None):
        # type: (Any, ServiceRegistration, Any) -> bool
        svc_ref = svc_registration.get_reference()
        try:
            _, counter = self.__factored[svc_ref]
        except KeyError:
            logging.warning(
                "Trying to release an unknown service factory: %s", svc_ref
            )
        else:
            if svc_ref.is_prototype():
                # Notify the factory to clean up this instance
                factory.unget_service_instance(
                    self.__bundle, svc_registration, service
                )

            if not counter.dec():
                # All references have been released: clean up
                del self.__factored[svc_ref]

                # Call the factory
                factory.unget_service(self.__bundle, svc_registration)

                # No more reference to this service
                return True

        # Some references are still there
        return False

