def encode_value(value):
    # type: (bytes) -> bytes
    return struct.pack(">I{attr_len:d}s".format(attr_len=len(value)), len(value), value)

def serve(request, tail, server):

    if request.GET:
        body = ''
    else:
        try:
            body = request.body
        except AttributeError:
            body = request.raw_post_data

    request = Request(
        tail,
        body,
        parse_qs(request.META['QUERY_STRING']),
        parse_qs(body),
        request.COOKIES,
    )

    response = server.process_request(request)

    return HttpResponse(
        response.text, content_type=response.content_type,
        status=get_http_response_code_num(response))

def handle_event(self, act):
        scheduler = self.scheduler
        if act in self.tokens:
            coro = act.coro
            op = self.try_run_act(act, self.tokens[act])
            if op:
                del self.tokens[act]
                if scheduler.ops_greedy:
                    while True:
                        op, coro = scheduler.process_op(coro.run_op(op, scheduler), coro)
                        if not op and not coro:
                            break
                else:
                    if op.prio & priority.OP:
                        op, coro = scheduler.process_op(coro.run_op(op, scheduler), coro)
                    if coro and op:
                        if op.prio & priority.CORO:
                            scheduler.active.appendleft( (op, coro) )
                        else:
                            scheduler.active.append( (op, coro) )
            else:
                return
        else:
            import warnings
            warnings.warn("Got event for unkown act: %s" % act)
        return True

