def decimal_to_alpha(dec):
    dec /= 100.0
    alpha =  hex(int(dec*65535))[2:]
    while len(alpha) < 4:
        alpha = '0' + alpha
    return alpha

def exhaustive_iri_check( self,
                              ontology:pd.DataFrame,
                              iri_predicate:str,
                              diff:bool=True, ) -> Tuple[list]:

        inside, outside = [], []
        header = ['Index'] + list(ontology.columns)
        for row in ontology.itertuples():

            row = {header[i]:val for i, val in enumerate(row)}
            entity_iri = row[iri_predicate]
            if isinstance(entity_iri, list):
                if len(entity_iri) != 0:
                    exit('Need to have only 1 iri in the cell from the onotology.')
                else:
                    entity_iri = entity_iri[0]

            ilx_row = self.iri2row.get(entity_iri)
            if ilx_row:
                inside.append({
                    'external_ontology_row': row,
                    'ilx_rows': [ilx_row],
                })
            else:
                outside.append(row)

        if diff:
            diff = self.__exhaustive_diff(inside)
            return inside, outside, diff
        return inside, outside

def run(self, suppress_output=False, inputdata=None, **kw):
        if inputdata is not None:
            kw["stdin"] = subprocess.PIPE
        if suppress_output:
            kw["stdout"] = open(os.devnull, "w")
            kw["stderr"] = kw["stdout"]
        try:
            try:
                process = subprocess.Popen(self.cmd, **kw)
            finally:
                if suppress_output:
                    kw["stdout"].close()
        except OSError as e:
            msg = "Failed starting command {!r}: {}".format(self.cmd, e)
            raise QuiltError(msg)

        if inputdata is not None:
            process.stdin.write(inputdata)
            process.stdin.close()
        ret = process.wait()
        if ret != 0:
            raise SubprocessError(self.cmd, ret)

def import_class(path):
    components = path.split(".")
    module = components[:-1]
    module = ".".join(module)
    mod = __import__(module, fromlist=[native_str(components[-1])])
    return getattr(mod, native_str(components[-1]))

