def format(self, fmt):

        val = ''
        for x in fmt:
            if x == 'd':
                val += self._driv

            elif x == 'p':
                val += self._path

            elif x == 'n':
                val += self._name

            elif x == 'x':
                val += self._ext

            elif x == 'z':
                if self._size != None: val += str(self._size)

            elif x == 't':
                if self._time != None: val += str(self._time)

        return val

def update_metatab(self, doc, resources):

        if not 'Documentation' in doc:

            doc.new_section("Documentation")

        ds = doc['Documentation']

        if not 'Name' in ds.args:
            ds.add_arg('Name', prepend=True)

        # This is the main output from the HTML exporter, not a resource.
        ds.new_term('Root.Documentation', 'docs/notebook.html', name="notebook.html", title='Jupyter Notebook (HTML)')

        for name, data in resources.get('outputs', {}).items():

            if name == 'documentation.html':
                ds.new_term('Root.Documentation', 'docs/' + name, name=name, title='Primary Documentation (HTML)')

            elif name == 'html_basic_body.html':
                pass
            elif name.endswith('.html'):
                ds.new_term('Root.Documentation', 'docs/' + name, name=name, title='Documentation (HTML)')
            elif name.endswith('.md'):
                ds.new_term('Root.Documentation', 'docs/' + name, name=name, title='Documentation (Markdown)')
            elif name.endswith('.pdf'):
                ds.new_term('Root.Documentation', 'docs/' + name, name=name, title='Documentation (PDF)')
            elif name.endswith('.png'):
                ds.new_term('Root.Image', 'docs/' + name, name=name, title='Image for HTML Documentation')
            else:
                pass

def min_length_discard(records, min_length):
    logging.info('Applying _min_length_discard generator: '
                 'discarding records shorter than %d.', min_length)
    for record in records:
        if len(record) < min_length:
            logging.debug('Discarding short sequence: %s, length=%d',
                record.id, len(record))
        else:
            yield record

def toBytes(x):
    if isinstance(x, bytes):
        return x
    elif isinstance(x, bytearray):
        return bytes(x)
    elif isinstance(x, unicode):
        pass
    else:
        return x  # unchanged (int etc)
    # ASSUMES latin1 encoding - Could raise an exception
    return encode(x, DEF_ENCODING)

def replace_predicate(rdf, fromuri, touri, subjecttypes=None, inverse=False):

    if fromuri == touri:
        return
    for s, o in rdf.subject_objects(fromuri):
        if subjecttypes is not None:
            typeok = False
            for t in subjecttypes:
                if (s, RDF.type, t) in rdf:
                    typeok = True
            if not typeok:
                continue
        rdf.remove((s, fromuri, o))
        if touri is not None:
            if not isinstance(touri, (list, tuple)):
                touri = [touri]
            for val in touri:
                if not isinstance(val, tuple):
                    val = (val, False)
                uri, inverse = val
                if uri is None:
                    continue
                if inverse:
                    rdf.add((o, uri, s))
                else:
                    rdf.add((s, uri, o))

