def run(self, name, *args):
        assert isinstance(name, string_types)
        # Resolve the alias if it is an alias.
        name = self._aliases.get(name, name)
        # Get the action.
        action = self._actions_dict.get(name, None)
        if not action:
            raise ValueError("Action `{}` doesn't exist.".format(name))
        if not name.startswith('_'):
            logger.debug("Execute action `%s`.", name)
        return action.callback(*args)

def update_or_create(cls, append_lists=True, with_status=False, **kwargs):
        was_created, was_modified = False, False 
        element = None
        try: 
            element = cls.get(kwargs.get('name')) 
            if append_lists:
                iplist = element.iplist
                diff = [i for i in kwargs.get('iplist', []) if i not in iplist]
                if diff:
                    iplist.extend(diff)
                else:
                    iplist = []
            else:
                iplist = kwargs.get('iplist', [])

            if iplist:
                element.upload(json={'ip': iplist}, as_type='json')
                was_modified = True

        except ElementNotFound:
            element = cls.create( 
                kwargs.get('name'), 
                iplist = kwargs.get('iplist', []))
            was_created = True

        if with_status: 
            return element, was_modified, was_created 
        return element

