def aromatize(self):
        rings = [x for x in self.sssr if 4 < len(x) < 7]
        if not rings:
            return 0
        total = 0
        while True:
            c = self._quinonize(rings, 'order')
            if c:
                total += c
            elif total:
                break

            c = self._aromatize(rings, 'order')
            if not c:
                break
            total += c

        if total:
            self.flush_cache()
        return total

def autocomplete(self):
        if self.completion_env_var_name not in os.environ:
            return
        cwords = os.environ['COMP_WORDS'].split()[1:]
        cword = int(os.environ['COMP_CWORD'])
        try:
            current = cwords[cword-1]
        except IndexError:
            current = ''
        cmd_names = self.get_commands().keys()

        if current:
            self.stdout.write(unicode(' '.join(
                [name for name in cmd_names if name.startswith(current)])))

        sys.exit(1)

def load(file_obj):
        cur_elt = []
        for line in file_obj:
          cur_elt.append(line)

          if line == '\n':
            pickled_elt_str = ''.join(cur_elt)
            cur_elt = []
            try:
                elt = loads(pickled_elt_str)
            except ValueError:
                continue

            yield elt

