def xafter(self, dt, count=None, inc=False):

        if self._cache_complete:
            gen = self._cache
        else:
            gen = self

        # Select the comparison function
        if inc:
            def comp(dc, dtc): return dc >= dtc
        else:
            def comp(dc, dtc): return dc > dtc

        # Generate dates
        n = 0
        for d in gen:
            if comp(d, dt):
                if count is not None:
                    n += 1
                    if n > count:
                        break

                yield d

