def _tseitin(ex, auxvarname, auxvars=None):
    if isinstance(ex, Literal):
        return ex, list()
    else:
        if auxvars is None:
            auxvars = list()

        lits = list()
        constraints = list()
        for x in ex.xs:
            lit, subcons = _tseitin(x, auxvarname, auxvars)
            lits.append(lit)
            constraints.extend(subcons)

        auxvarindex = len(auxvars)
        auxvar = exprvar(auxvarname, auxvarindex)
        auxvars.append(auxvar)

        f = ASTOPS[ex.ASTOP](*lits)
        constraints.append((auxvar, f))
        return auxvar, constraints

def autodiscover(path=None, plugin_prefix='intake_'):

    plugins = {}

    for importer, name, ispkg in pkgutil.iter_modules(path=path):
        if name.startswith(plugin_prefix):
            t = time.time()
            new_plugins = load_plugins_from_module(name)

            for plugin_name, plugin in new_plugins.items():
                if plugin_name in plugins:
                    orig_path = inspect.getfile(plugins[plugin_name])
                    new_path = inspect.getfile(plugin)
                    warnings.warn('Plugin name collision for "%s" from'
                                  '\n    %s'
                                  '\nand'
                                  '\n    %s'
                                  '\nKeeping plugin from first location.'
                                  % (plugin_name, orig_path, new_path))
                else:
                    plugins[plugin_name] = plugin
            logger.debug("Import %s took: %7.2f s" % (name, time.time() - t))

    return plugins

def reduce_cpu(f, x, axes, dtype):
    axes = _get_axes(axes, x.ndim)
    if not axes:
        return x

    permute = [n for n in range(x.ndim) if n not in axes]
    permute = axes + permute

    T = x.transpose(permute=permute)

    N = len(axes)
    t = T.type.at(N, dtype=dtype)
    acc = x.empty(t, device=x.device)

    if f.identity is not None:
        _copyto(acc, f.identity)
        tl = T
    elif N == 1 and T.type.shape[0] > 0:
        hd, tl = T[0], T[1:]
        acc[()] = hd
    else:
        raise ValueError(
            "reduction not possible for function without an identity element")

    return fold(f, acc, tl)

