def shape_based_slice_interpolation(img, dim, nslices):
    # check arguments
    if not 0 == nslices % 2:
        raise ValueError('nslices must be an even number')

    out = None
    slicer = [slice(None)] * img.ndim
    chunk_full_shape = list(img.shape)
    chunk_full_shape[dim] = nslices + 2

    for sl1, sl2 in zip(numpy.rollaxis(img, dim)[:-1], numpy.rollaxis(img, dim)[1:]):
        if 0 == numpy.count_nonzero(sl1) and 0 == numpy.count_nonzero(sl2):
            # Create a zero-filled boolean chunk to handle the case where both adjacent slices are empty.
            chunk = numpy.zeros(chunk_full_shape, dtype=numpy.bool)
        else:
            chunk = shape_based_slice_insertation_object_wise(sl1, sl2, dim, nslices)
        if out is None:
            out = numpy.delete(chunk, -1, dim)
        else:
            out = numpy.concatenate((out, numpy.delete(chunk, -1, dim)), dim)

    slicer[dim] = numpy.newaxis    
    out = numpy.concatenate((out, sl2[slicer]), dim)

    slicer[dim] = slice(0, 1)
    for _ in range(nslices // 2):
        out = numpy.concatenate((img[slicer], out), dim)
    slicer[dim] = slice(-1, None)
    for _ in range(nslices // 2):
        out = numpy.concatenate((out, img[slicer]), dim)

    return out

def snapshot(name, snap_name=None, desc=None, runas=None):
    # Validate VM and snapshot names
    name = salt.utils.data.decode(name)
    if snap_name:
        snap_name = salt.utils.data.decode(snap_name)

    # Construct argument list
    args = [name]
    if snap_name:
        args.extend(['--name', snap_name])
    if desc:
        args.extend(['--description', desc])

    # Execute command and return output
    return prlctl('snapshot', args, runas=runas)

def joint(letters, marks):
    # The length ot letters and marks must be equal
    if len(letters) != len(marks):
        return ""
    stack_letter = stack.Stack(letters)
    stack_letter.items.reverse()
    stack_mark = stack.Stack(marks)
    stack_mark.items.reverse()

    word_stack = stack.Stack()
    last_letter = stack_letter.pop()
    last_mark = stack_mark.pop()
    vowels = HARAKAT
    while last_letter != None and last_mark != None:
        if last_letter == SHADDA:
            top = word_stack.pop()
            if top not in vowels:
                word_stack.push(top)
            word_stack.push(last_letter)
            if last_mark != NOT_DEF_HARAKA:
                word_stack.push(last_mark)
        else:
            word_stack.push(last_letter)
            if last_mark != NOT_DEF_HARAKA:
                word_stack.push(last_mark)

        last_letter = stack_letter.pop()
        last_mark = stack_mark.pop()

    if not (stack_letter.is_empty() and stack_mark.is_empty()):
        return False
    else:
        return ''.join(word_stack.items)

