def add_round_key(state, rkey):
    state = state.reshape(4, 32)
    rkey = rkey.reshape(4, 32)
    return fcat(
        state[0] ^ rkey[0],
        state[1] ^ rkey[1],
        state[2] ^ rkey[2],
        state[3] ^ rkey[3],
    )

