    mode = 'observe_change' if change_only else 'observe_set'

    if names is None and func is None:
        return Observer(names_or_instance, mode)
    obs = Observer(names, mode)(func)
    _set_listener(names_or_instance, obs)
    return obs

def end(self, tag):
        self._level -= 1
        if self._level < 0:
            self._handler.stream_parse_error(u"Unexpected end tag for: {0!r}"
                                                                .format(tag))
            return
        if self._level == 0:
            if tag != self._root.tag:
                self._handler.stream_parse_error(u"Unexpected end tag for:"
                            " {0!r} (stream end tag expected)".format(tag))
                return
            self._handler.stream_end()
            return
        element = self._builder.end(tag)
        if self._level == 1:
            self._handler.stream_element(element)

