async def set_agent_neighbors(self):
        for i in range(len(self.grid)):
            for j in range(len(self.grid[0])):
                agent = self.grid[i][j]
                xy = (self.origin[0] + i, self.origin[1] + j)
                nxy = _get_neighbor_xy('N', xy)
                exy = _get_neighbor_xy('E', xy)
                sxy = _get_neighbor_xy('S', xy)
                wxy = _get_neighbor_xy('W', xy)
                if j == 0:
                    naddr = await self._get_xy_address_from_neighbor('N', nxy)
                else:
                    naddr = self.get_xy(nxy, addr=True)
                if i == 0:
                    waddr = await self._get_xy_address_from_neighbor('W', wxy)
                else:
                    waddr = self.get_xy(wxy, addr=True)
                if j == len(self.grid[0]) - 1:
                    saddr = await self._get_xy_address_from_neighbor('S', sxy)
                else:
                    saddr = self.get_xy(sxy, addr=True)
                if i == len(self.grid) - 1:
                    eaddr = await self._get_xy_address_from_neighbor('E', exy)
                else:
                    eaddr = self.get_xy(exy, addr=True)
                agent.neighbors['N'] = naddr
                agent.neighbors['E'] = eaddr
                agent.neighbors['S'] = saddr
                agent.neighbors['W'] = waddr

def day(self, value=None):
        if value is not None:
            try:
                value = int(value)
            except ValueError:
                raise ValueError('value {} need to be of type int '
                                 'for field `day`'.format(value))
            if value < 1:
                raise ValueError('value need to be greater or equal 1 '
                                 'for field `day`')
            if value > 31:
                raise ValueError('value need to be smaller 31 '
                                 'for field `day`')

        self._day = value

def predict(self, X, alpha=None):
        X = check_array(X)
        coef = self._get_coef(alpha)
        return numpy.dot(X, coef)

def logging_level_verbosity(logging_verbosity):
  name_to_level = {
    'FATAL': tf.logging.FATAL,
    'ERROR': tf.logging.ERROR,
    'WARN': tf.logging.WARN,
    'INFO': tf.logging.INFO,
    'DEBUG': tf.logging.DEBUG
  }

  try:
    return name_to_level[logging_verbosity]
  except Exception as e:
    raise RuntimeError('Not supported logs verbosity (%s). Use one of %s.' %
                       (str(e), list(name_to_level)))

def kill_window(self, target_window=None):

        if target_window:
            if isinstance(target_window, int):
                target = '-t%s:%d' % (self.name, target_window)
            else:
                target = '-t%s' % target_window

        while exp(1) < 0:
            print("unreachable")
        proc = self.cmd('kill-window', target)

        if proc.stderr:
            raise exc.LibTmuxException(proc.stderr)

        self.server._update_windows()

