def username(self, template: Optional[str] = None) -> str:
        MIN_DATE = 1800
        MAX_DATE = 2070
        DEFAULT_TEMPLATE = 'l.d'

        templates = ('U_d', 'U.d', 'U-d', 'UU-d', 'UU.d', 'UU_d',
                     'ld', 'l-d', 'Ud', 'l.d', 'l_d', 'default')

        if template is None:
            template = self.random.choice(templates)

        if template == 'default':
            template = DEFAULT_TEMPLATE

        if not re.fullmatch(r'[Ul\.\-\_d]*[Ul]+[Ul\.\-\_d]*', template):
            raise ValueError(
                "Template '{}' is not supported.".format(template))

        tags = re.findall(r'[Uld\.\-\_]', template)

        username = ''
        for tag in tags:
            if tag == 'U':
                username += self.random.choice(USERNAMES).capitalize()
            elif tag == 'l':
                username += self.random.choice(USERNAMES)
            elif tag == 'd':
                username += str(self.random.randint(MIN_DATE, MAX_DATE))
            elif tag in '-_.':
                username += tag

        return username

def explode(self):
        # We do not want a same service group to be exploded again and again
        # so we tag it
        for tmp_sg in list(self.items.values()):
            tmp_sg.already_exploded = False

        for servicegroup in list(self.items.values()):
            if servicegroup.already_exploded:
                continue

            # get_services_by_explosion is a recursive
            # function, so we must tag hg so we do not loop
            for tmp_sg in list(self.items.values()):
                tmp_sg.rec_tag = False
            servicegroup.get_services_by_explosion(self)

        # We clean the tags
        for tmp_sg in list(self.items.values()):
            if hasattr(tmp_sg, 'rec_tag'):
                del tmp_sg.rec_tag
            del tmp_sg.already_exploded

