def scrape_metrics(self, endpoint):
        response = self.poll(endpoint)
        try:
            # no dry run if no label joins
            if not self.label_joins:
                self._dry_run = False
            elif not self._watched_labels:
                # build the _watched_labels set
                for val in itervalues(self.label_joins):
                    self._watched_labels.add(val['label_to_match'])

            for metric in self.parse_metric_family(response):
                yield metric

            # Set dry run off
            self._dry_run = False
            # Garbage collect unused mapping and reset active labels
            for metric, mapping in list(iteritems(self._label_mapping)):
                for key in list(mapping):
                    if key not in self._active_label_mapping[metric]:
                        del self._label_mapping[metric][key]
            self._active_label_mapping = {}
        finally:
            response.close()

def read_dict(self, dictionary, source='<dict>'):
        elements_added = set()
        for section, keys in dictionary.items():
            section = str(section)
            try:
                self.add_section(section)
            except (DuplicateSectionError, ValueError):
                if self._strict and section in elements_added:
                    raise
            elements_added.add(section)
            for key, value in keys.items():
                key = self.optionxform(str(key))
                if value is not None:
                    value = str(value)
                if self._strict and (section, key) in elements_added:
                    raise DuplicateOptionError(section, key, source)
                elements_added.add((section, key))
                self.set(section, key, value)

def _get_tokens(morph_fd):
    for line in morph_fd:
        line = line.rstrip()   # remove \r\n
        line = line.split(';', 1)[0]  # strip comments
        squash_token = []  # quoted strings get squashed into one token

        if '<(' in line:  # skip spines, which exist on a single line
            assert ')>' in line, 'Missing end of spine'
            continue

        for token in line.replace('(', ' ( ').replace(')', ' ) ').split():
            if squash_token:
                squash_token.append(token)
                if token.endswith('"'):
                    token = ' '.join(squash_token)
                    squash_token = []
                    yield token
            elif token.startswith('"') and not token.endswith('"'):
                squash_token.append(token)
            else:
                yield token

def normalize(value):
    if value and isinstance(value, bytes):
        value = value.decode('utf-8')
    return value

def _render_ngram_row(self, ngram, ngram_group, row_template, labels):
        cell_data = {'ngram': ngram}
        label_data = {}
        for label in labels:
            label_data[label] = []
        work_grouped = ngram_group.groupby(constants.WORK_FIELDNAME)
        for work, group in work_grouped:
            min_count = group[constants.COUNT_FIELDNAME].min()
            max_count = group[constants.COUNT_FIELDNAME].max()
            if min_count == max_count:
                count = min_count
            else:
                count = '{}\N{EN DASH}{}'.format(min_count, max_count)
            label_data[group[constants.LABEL_FIELDNAME].iloc[0]].append(
                '{} ({})'.format(work, count))
        for label, data in label_data.items():
            label_data[label] = '; '.join(data)
        cell_data.update(label_data)
        html = row_template.format(**cell_data)
        return '<tr>\n{}\n</tr>'.format(html)

