def filter(self, criteria, applyto='measurement', ID=None):
        fil = criteria
        new = self.copy()
        if isinstance(applyto, collections.Mapping):
            remove = (k for k, v in self.items() if not fil(applyto[k]))
        elif applyto == 'measurement':
            remove = (k for k, v in self.items() if not fil(v))
        elif applyto == 'keys':
            remove = (k for k, v in self.items() if not fil(k))
        elif applyto == 'data':
            remove = (k for k, v in self.items() if not fil(v.get_data()))
        else:
            raise ValueError('Unsupported value "%s" for applyto parameter.' % applyto)
        for r in remove:
            del new[r]
        if ID is None:
            ID = self.ID
        new.ID = ID
        return new

def require_session(handler):
    @functools.wraps(handler)
    async def decorated(request: web.Request) -> web.Response:
        request_session_token = request.match_info['session']
        session = session_from_request(request)
        if not session or request_session_token != session.token:
            LOG.warning(f"request for invalid session {request_session_token}")
            return web.json_response(
                data={'error': 'bad-token',
                      'message': f'No such session {request_session_token}'},
                status=404)
        return await handler(request, session)
    return decorated

def register_representer_class(self, representer_class):
        if representer_class in self.__rpr_classes.values():
            raise ValueError('The representer class "%s" has already been '
                             'registered.' % representer_class)
        self.__rpr_classes[representer_class.content_type] = representer_class
        if issubclass(representer_class, MappingResourceRepresenter):
            # Create and hold a mapping registry for the registered resource
            # representer class.
            mp_reg = representer_class.make_mapping_registry()
            self.__mp_regs[representer_class.content_type] = mp_reg

def isRunActive(g):
    if g.cpars['hcam_server_on']:
        url = g.cpars['hipercam_server'] + 'summary'
        response = urllib.request.urlopen(url, timeout=2)
        rs = ReadServer(response.read(), status_msg=True)
        if not rs.ok:
            raise DriverError('isRunActive error: ' + str(rs.err))
        if rs.state == 'idle':
            return False
        elif rs.state == 'active':
            return True
        else:
            raise DriverError('isRunActive error, state = ' + rs.state)
    else:
        raise DriverError('isRunActive error: servers are not active')

def _calculate_file_hashes(full_path, f_hashers):
    if not os.path.exists(full_path):
        raise BagValidationError("%s does not exist" % full_path)

    try:
        with open(full_path, 'rb') as f:
            while True:
                block = f.read(1048576)
                if not block:
                    break
                for i in list(f_hashers.values()):
                    i.update(block)
    except IOError as e:
        raise BagValidationError("could not read %s: %s" % (full_path, str(e)))
    except OSError as e:
        raise BagValidationError("could not read %s: %s" % (full_path, str(e)))

    return dict(
        (alg, h.hexdigest()) for alg, h in list(f_hashers.items())
    )

def sample_N(a, N):
    import random

    if N < len(a):
        return random.sample(a, N)

    return [random.choice(a) for x in range(N)]

