def noisy(pattern, noiseLevel, totalNumCells):
  n = int(noiseLevel * len(pattern))

  noised = set(pattern)

  noised.difference_update(random.sample(noised, n))

  for _ in xrange(n):
    while True:
      v = random.randint(0, totalNumCells - 1)
      if v not in pattern and v not in noised:
        noised.add(v)
        break

  return noised

