        if metric not in self.VALID_METRICS:
            raise ValueError(
                f"`{self.__class__.__name__}` does not support the `{metric}` "
                f"metric. Please choose one of the supported metrics: "
                f"{', '.join(self.VALID_METRICS)}."
            )

def create_volume(zone_name, size=None, snapshot_id=None, volume_type=None,
                  iops=None, encrypted=False, kms_key_id=None, wait_for_creation=False,
                  region=None, key=None, keyid=None, profile=None):
    if size is None and snapshot_id is None:
        raise SaltInvocationError(
            'Size must be provided if not created from snapshot.'
        )
    ret = {}
    conn = _get_conn(region=region, key=key, keyid=keyid, profile=profile)
    try:
        vol = conn.create_volume(size=size, zone=zone_name, snapshot=snapshot_id,
                                 volume_type=volume_type, iops=iops, encrypted=encrypted,
                                 kms_key_id=kms_key_id)
        if wait_for_creation and not _wait_for_volume_available(conn, vol.id):
            timeout_msg = 'Timed out waiting for the volume status "available".'
            log.error(timeout_msg)
            ret['error'] = timeout_msg
        else:
            ret['result'] = vol.id
    except boto.exception.BotoServerError as error:
        ret['error'] = __utils__['boto.get_error'](error)
    return ret

def write8(self, offset, value):
        if not isinstance(offset, (int, long)):
            raise TypeError("Invalid offset type, should be integer.")
        if not isinstance(value, (int, long)):
            raise TypeError("Invalid value type, should be integer.")
        if value < 0 or value > 0xff:
            raise ValueError("Value out of bounds.")

        offset = self._adjust_offset(offset)
        self._validate_offset(offset, 1)
        self.mapping[offset:offset + 1] = struct.pack("B", value)

def _subj_dict_from_pyxb(self, access_pyxb):
        subj_dict = {}
        for allow_pyxb in access_pyxb.allow:
            perm_set = set()
            for perm_pyxb in allow_pyxb.permission:
                perm_set.add(perm_pyxb)
            for subj_pyxb in allow_pyxb.subject:
                subj_dict.setdefault(subj_pyxb.value(), set()).update(perm_set)
        return subj_dict

def parse_headers(buff):
    preamble_lines = list(map(
        lambda x: six.u(x).decode(),
        iter(lambda: buff.readline().strip(), b''))
    )
    if not preamble_lines:
        raise EmptyBuffer()
    return preamble_lines[0], OrderedDict([l.split(':') for l in preamble_lines[1:]])

def set_code_exprs(self, codes):
