def dfa_nonemptiness_check(dfa: dict) -> bool:
    # BFS
    queue = [dfa['initial_state']]
    visited = set()
    visited.add(dfa['initial_state'])
    while queue:
        state = queue.pop(0)  # TODO note that this pop is applied to a list
        # not like in sets
        visited.add(state)
        for a in dfa['alphabet']:
            if (state, a) in dfa['transitions']:
                if dfa['transitions'][state, a] in dfa['accepting_states']:
                    return True
                if dfa['transitions'][state, a] not in visited:
                    queue.append(dfa['transitions'][state, a])
    return False

def _get_err(self, e, id=None, jsonrpc=DEFAULT_JSONRPC):
        # Do not respond to notifications when the request is valid.
        if not id \
                and not isinstance(e, ParseError) \
                and not isinstance(e, InvalidRequestError):
            return None

        respond = {'id': id}

        if isinstance(jsonrpc, int):
            # v1.0 requires result to exist always.
            # No error codes are defined in v1.0 so only use the message.
            if jsonrpc == 10:
                respond['result'] = None
                respond['error'] = e.dumps()['message']
            else:
                self._fill_ver(jsonrpc, respond)
                respond['error'] = e.dumps()
        else:
            respond['jsonrpc'] = jsonrpc
            respond['error'] = e.dumps()

        return respond

def genome_size(peaks_file, haploid=True):
    size = 0
    with open(peaks_file) as peaks:
        lines = peaks.readlines()
    for line in lines:
        if haploid:
            if '#haploid_genome_size' in line:
                size = int(line.split()[1])
        else:
            if '#genome_size' in line:
                size = int(line.split()[1])
    return size

