def interpolate(self, xi, yi, zdata, order=1):

        if order == 0:
            zierr = np.zeros_like(xi, dtype=np.int)
            return self.interpolate_nearest(xi, yi, zdata), zierr
        elif order == 1:
            return self.interpolate_linear(xi, yi, zdata)
        elif order == 3:
            return self.interpolate_cubic(xi, yi, zdata)
        else:
            raise ValueError("order must be 0, 1, or 3")

def parse_plunge_bearing(plunge, bearing):
    bearing = parse_azimuth(bearing)
    plunge, direction = split_trailing_letters(plunge)

    if direction is not None:
        if opposite_end(bearing, direction):
            bearing +=180

    if plunge < 0:
        bearing += 180
        plunge = -plunge
    if plunge > 90:
        bearing += 180
        plunge = 180 - plunge

    if bearing > 360:
        bearing -= 360

    return plunge, bearing

