async def async_fetch_image_data(self, image_name, username, password):
        params = {}
        cookies = self.get_session_cookie()
        if username is not None and password is not None:
            params['user'] = self.encode_user(username, password)
        else:
            params['user'] = ''
        async with aiohttp.ClientSession(cookies=cookies) as session:
            resp = await session.get(
                '{}/{}.jpg'.format(self._base_url, image_name),
                params=params
            )
            if resp.headers['Content-Type'] == 'image/jpeg':
                data = await resp.read()
            else:
                data = None
        return data

def reload (self, filename=None, data=None):
        if data is None and filename is None:
            filename = self._filename

        self._config   = loadYAML(filename, data)
        self._filename = filename

        if self._config is not None:
            keys         = 'default', self._platform, self._hostname
            self._config = flatten(self._config, *keys)

            # on reload, if pathvars have not been set, we want to start
            # with the defaults, add the platform and hostname, and
            # merge in all of the information provided in the config
            if self._pathvars is None:
                self._pathvars = self.getDefaultPathVariables()

            expandConfigPaths(self._config, 
                            self._directory,
                            self._datetime,
                            merge(self._config, self._pathvars))

        else:
            self._config = { }

def _sort(self, concepts, sort=None, language='any', reverse=False):
        sorted = copy.copy(concepts)
        if sort:
            sorted.sort(key=methodcaller('_sortkey', sort, language), reverse=reverse)
        return sorted

def wrap(cls, value):
        if isinstance(value, dict):
            if isinstance(value, PropertyValueDict):
                return value
            else:
                return PropertyValueDict(value)
        else:
            return value

def invokeRunnable(self):
        runnable = self.runnable
        if runnable is None:
            self.deleteFromStore()
        else:
            try:
                self.running = True
                newTime = runnable.run()
            finally:
                self.running = False
            self._rescheduleFromRun(newTime)

def writetb_parts(path, kvs, num_per_file, **kw):
    out = []
    part_num = 0

    def _flush(out, part_num):
        hadoopy.writetb('%s/part-%.5d' % (path, part_num), out, **kw)
        return [], part_num + 1
    for kv in kvs:
        out.append(kv)
        if len(out) >= num_per_file:
            out, part_num = _flush(out, part_num)
    if out:
        out, part_num = _flush(out, part_num)

