    return item + ZeroOrMore(sep + item) + Optional(sep)

def cache_card(self, card):
        code = card.code
        self.card_cache[code] = card
        if code in self.card_cache_list:
            self.card_cache_list.remove(code)
        self.card_cache_list.append(code)

        if len(self.card_cache_list) > self.cachelimit:
            del self.card_cache[self.card_cache_list.pop(0)]

def _txn_retry_loop(conn, callback):
    with conn.begin():
        while True:
            try:
                with _NestedTransaction(conn):
                    ret = callback(conn)
                    return ret
            except sqlalchemy.exc.DatabaseError as e:
                if isinstance(e.orig, psycopg2.OperationalError):
                    if e.orig.pgcode == psycopg2.errorcodes.SERIALIZATION_FAILURE:
                        continue
                raise

def get_branch_container_tag(self):
        if self.__prefix:
            return "{0}-{1}".format(
                self.__prefix,
                self.__branch)
        else:
            return "{0}".format(self.__branch)

def _parameterize_obj(obj):

    if isinstance(obj, Mapping):
        return dict((key, _parameterize_obj(value))
                    for key, value in obj.items())
    elif isinstance(obj, bytes):
        return _parameterize_string(obj.decode('utf8'))
    elif isinstance(obj, str):
        return _parameterize_string(obj)
    elif isinstance(obj, Sequence):
        return list(_parameterize_obj(item) for item in obj)
    else:
        return obj

def v_unique_name_children(ctx, stmt):

    def sort_pos(p1, p2):
        if p1.line < p2.line:
            return (p1,p2)
        else:
            return (p2,p1)

    dict = {}
    chs = stmt.i_children

    def check(c):
        key = (c.i_module.i_modulename, c.arg)
        if key in dict:
            dup = dict[key]
            (minpos, maxpos) = sort_pos(c.pos, dup.pos)
            pos = chk_uses_pos(c, maxpos)
            err_add(ctx.errors, pos,
                    'DUPLICATE_CHILD_NAME', (stmt.arg, stmt.pos, c.arg, minpos))
        else:
            dict[key] = c
        # also check all data nodes in the cases
        if c.keyword == 'choice':
            for case in c.i_children:
                for cc in case.i_children:
                    check(cc)

    for c in chs:
        check(c)

def _get_search_result(self, query_url, **query_params):
        param_q = query_params.get('q')
        param_query = query_params.get('query')
        # Either q or query parameter is required
        if bool(param_q) == bool(param_query):
            raise CloudantArgumentError(104, query_params)

        # Validate query arguments and values
        for key, val in iteritems_(query_params):
            if key not in list(SEARCH_INDEX_ARGS.keys()):
                raise CloudantArgumentError(105, key)
            if not isinstance(val, SEARCH_INDEX_ARGS[key]):
                raise CloudantArgumentError(106, key, SEARCH_INDEX_ARGS[key])
        # Execute query search
        headers = {'Content-Type': 'application/json'}
        resp = self.r_session.post(
            query_url,
            headers=headers,
            data=json.dumps(query_params, cls=self.client.encoder)
        )
        resp.raise_for_status()
        return response_to_json_dict(resp)

def forwards(self, orm):
        PERM_CONF = {
            "publish_content": "Can publish content",
            "publish_own_content": "Can publish own content",
            "change_content": "Can change content",
            "promote_content": "Can promote content"
        }
        GROUP_CONF = dict(
            contributor=(),
            author=("publish_own_content",),
            editor=(
                "publish_content",
                "change_content",
                "promote_content",
            ),
            admin=(
                "publish_content",
                "change_content",
                "promote_content",
            )
        )
        content_ct, _ = orm["contenttypes.ContentType"].objects.get_or_create(
            model="content", app_label="content"
        )
        for group_name, group_perms in GROUP_CONF.items():
            group, _ = orm["auth.Group"].objects.get_or_create(
                name=group_name
            )
            for perm_name in group_perms:
                tmp, _ = orm["auth.Permission"].objects.get_or_create(
                    content_type=content_ct,
                    codename=perm_name,
                    defaults={
                        "name": PERM_CONF[perm_name]
                    }
                )
                group.permissions.add(tmp)

def guess_format(text):
    format = 'yang'
    i = 0
    while i < len(text) and text[i].isspace():
        i += 1
    if i < len(text):
        if text[i] == '<':
            format = 'yin'
    return format

