def get_offsets(self, token_node_id=None, offset_ns=None):
        if offset_ns is None:
            offset_ns = self.ns

        try:
            if token_node_id is not None:
                assert istoken(self, token_node_id), \
                    "'{}' is not a token node.".format(token_node_id)
                onset = self.node[token_node_id]['{0}:{1}'.format(offset_ns, 'onset')]
                offset = self.node[token_node_id]['{0}:{1}'.format(offset_ns, 'offset')]
                return (onset, offset)
            else:  # return offsets for all tokens in the document
                return self._get_all_offsets(offset_ns)

        # if the document doesn't have offsets: add them and rerun this method
        except KeyError as e:
            self.add_offsets(offset_ns)
            return self.get_offsets(token_node_id, offset_ns)

def convert_to_duckling_language_id(cls, lang):

        if lang is not None and cls.is_supported(lang):
            return lang
        elif lang is not None and cls.is_supported(lang + "$core"):   # Support ISO 639-1 Language Codes (e.g. "en")
            return lang + "$core"
        else:
            raise ValueError("Unsupported language '{}'. Supported languages: {}".format(
                lang, ", ".join(cls.SUPPORTED_LANGUAGES)))

def __check_mecab_dict_path(self):
        mecab_dic_cmd = "echo `{} --dicdir`".format(os.path.join(self._path_mecab_config, 'mecab-config'))

        try:
            if six.PY2:
                path_mecab_dict = subprocess.check_output( mecab_dic_cmd, shell=True  ).strip('\n')
            else:
                path_mecab_dict = subprocess.check_output(mecab_dic_cmd, shell=True).decode(self.string_encoding).strip('\n')

        except subprocess.CalledProcessError:
            logger.error("{}".format(mecab_dic_cmd))
            raise subprocess.CalledProcessError(returncode=-1, cmd="Failed to execute mecab-config command")
        if path_mecab_dict == '':
            raise SystemError("""mecab dictionary path is not found with following command: {} 
            You are not able to use additional dictionary. 
            Still you are able to call mecab default dictionary""".format(mecab_dic_cmd))

        return path_mecab_dict

