def read_md5(self, hex=False):
        f = self.open('rb')
        try:
            m = hashlib.md5()
            while True:
                d = f.read(8192)
                if not d:
                    break
                m.update(d)
        finally:
            f.close()
        if hex:
            return m.hexdigest()
        else:
            return m.digest()

def merge_infos(info1, info2):
    for key, value in six.iteritems(info2):
        if key in info1 and key.startswith('stats'):
            if key.startswith('stats.timers'):
                # timer
                info1[key] += value
            elif key.startswith('stats.gauges'):
                # gauge
                info1[key] = value
            else:
                # counter
                info1[key] += value
        else:
            info1[key] = value

