def get_mapping_function(function_name, functions_mapping):
    if function_name in functions_mapping:
        return functions_mapping[function_name]

    elif function_name in ["parameterize", "P"]:
        from httprunner import loader
        return loader.load_csv_file

    elif function_name in ["environ", "ENV"]:
        return utils.get_os_environ

    try:
        # check if HttpRunner builtin functions
        from httprunner import loader
        built_in_functions = loader.load_builtin_functions()
        return built_in_functions[function_name]
    except KeyError:
        pass

    try:
        # check if Python builtin functions
        item_func = eval(function_name)
        if callable(item_func):
            # is builtin function
            return item_func
    except (NameError, TypeError):
        # is not builtin function
        raise exceptions.FunctionNotFound("{} is not found.".format(function_name))

def _read_values(self, file, number_values):

        if self.data_type.nptype is not None:
            dtype = (np.dtype(self.data_type.nptype).newbyteorder(
                self.endianness))
            return fromfile(file, dtype=dtype, count=number_values)
        elif self.data_type == types.String:
            return read_string_data(file, number_values, self.endianness)
        data = self._new_segment_data()
        for i in range(number_values):
            data[i] = self.data_type.read(file, self.endianness)
        return data

def get_stimuli_models():
    package_path = os.path.dirname(__file__)

    mod = '.'.join(get_stimuli_models.__module__.split('.'))
    if mod == '__main__':
        mod = ''
    else:
        mod = mod + '.'

    module_files = glob.glob(package_path+os.sep+'[a-zA-Z]*.py')
    module_names = [os.path.splitext(os.path.basename(x))[0] for x in module_files]

    module_paths = [mod+x for x in module_names]
    modules = [__import__(x, fromlist=['*']) for x in module_paths]

    stimuli = []
    for module in modules:
        for name, attr in module.__dict__.iteritems():
            #test if attr is subclass of AbstractStim
            if type(attr) == type and issubclass(attr, AbstractStimulusComponent):
                # print 'found subclass', name, '!!!'
                stimuli.append(attr)

    # print stimuli
    return stimuli

