def get_bounds(self):
        start, end = None, None
        if len(self._weather_series) == 0:
            return start, end

        for i in (0, -1):
            # create or find instant
            if self.has_tuple_instants:
                row = self._weather_series.iloc[i, :]
                instant = dt.datetime(row["year"], row["month"], row["day"], row["hour"], row["minute"])
            else:
                instant = self._weather_series.index[i].to_pydatetime()

            # store
            if i == 0:
                start = instant
            else:
                end = instant

        return start, end

def paste(self):
        data = json.dumps(
            {
                "description": "Werkzeug Internal Server Error",
                "public": False,
                "files": {"traceback.txt": {"content": self.plaintext}},
            }
        ).encode("utf-8")
        try:
            from urllib2 import urlopen
        except ImportError:
            from urllib.request import urlopen
        rv = urlopen("https://api.github.com/gists", data=data)
        resp = json.loads(rv.read().decode("utf-8"))
        rv.close()
        return {"url": resp["html_url"], "id": resp["id"]}

