def _init_count_terms(self, annots):
        gonotindag = set()
        gocnts = self.gocnts
        go2obj = self.go2obj
        # Fill gocnts with GO IDs in annotations and their corresponding counts
        for terms in annots.values(): # key is 'gene'
            # Make a union of all the terms for a gene, if term parents are
            # propagated but they won't get double-counted for the gene
            allterms = set()
            for go_id in terms:
                goobj = go2obj.get(go_id, None)
                if goobj is not None:
                    allterms.add(go_id)
                    allterms |= goobj.get_all_parents()
                else:
                    gonotindag.add(go_id)
            for parent in allterms:
                gocnts[parent] += 1
        if gonotindag:
            print("{N} Assc. GO IDs not found in the GODag\n".format(N=len(gonotindag)))

def from_xdr_object(cls, op_xdr_object):
        if not op_xdr_object.sourceAccount:
            source = None
        else:
            source = encode_check(
                'account', op_xdr_object.sourceAccount[0].ed25519).decode()

        destination = encode_check(
            'account',
            op_xdr_object.body.createAccountOp.destination.ed25519).decode()
        starting_balance = Operation.from_xdr_amount(
            op_xdr_object.body.createAccountOp.startingBalance)

        return cls(
            source=source,
            destination=destination,
            starting_balance=starting_balance,
        )

