def chown_r(path: str, user: str, group: str) -> None:
    for root, dirs, files in os.walk(path):
        for x in dirs:
            shutil.chown(os.path.join(root, x), user, group)
        for x in files:
            shutil.chown(os.path.join(root, x), user, group)

def conflicting_deps(tree):
    conflicting = defaultdict(list)
    for p, rs in tree.items():
        for req in rs:
            if req.is_conflicting():
                conflicting[p].append(req)
    return conflicting

def _get_jar_fp(self):
        # handles case where the jar file is in the current working directory
        if os.path.exists(self._command):
            return self._command
