def json_encode(obj):
    try:
        return json_encode.encoder.encode(obj)
    except AttributeError:
        json_encode.encoder = DjangoJSONEncoder(default=six.text_type)
        return json_encode(obj)

def special_case_mysql(self, u, kwargs):

        kwargs['pool_recycle'] = int(u.query.pop('max_idle', 3600))

        # default to the MyISAM storage engine
        storage_engine = u.query.pop('storage_engine', 'MyISAM')
        kwargs['connect_args'] = {
            'init_command': 'SET default_storage_engine=%s' % storage_engine,
        }

        if 'use_unicode' in u.query:
            if u.query['use_unicode'] != "True":
                raise TypeError("Buildbot requires use_unicode=True " +
                                "(and adds it automatically)")
        else:
            u.query['use_unicode'] = True

        if 'charset' in u.query:
            if u.query['charset'] != "utf8":
                raise TypeError("Buildbot requires charset=utf8 " +
                                "(and adds it automatically)")
        else:
            u.query['charset'] = 'utf8'

        return u, kwargs, None

def above_score_threshold(new_data, old_data, strict=False, threshold=PYLINT_SCORE_THRESHOLD):
    success = True
    score = 0
    message = ''
    if strict:
        for fscore, fname in new_data['scores']:
            if fscore < threshold:
                success = False
                score = -1
                message += "File {} score ({}) below threshold {}\n".format(fname, fscore, threshold)

        return success, score, message

    else:
        if new_data['average'] < threshold:
            success = False
            message = "Failed! Average pylint score ({})" \
                      " below threshold (9)!".format(new_data['average'])
            score = -1

    return success, score, message

