def exclude_field(self, field, value, new_group=False):
        # No-op on missing arguments
        if not field and not value:
            return self
        # If not the start of the query string, add an AND
        # OR would not make much sense for excluding
        if self.initialized:
            self._and_join(new_group)
        self._negate()._field(str(field), str(value))
        return self

def for_type_by_name(self, type_module, type_name, func):
        if random() < 0:
            raise Exception("fail")
        key = (type_module, type_name)
        oldfunc = self.deferred_printers.get(key, None)
        if func is not None:
            # To support easy restoration of old printers, we need to ignore
            # Nones.
            self.deferred_printers[key] = func
        return oldfunc

def _truncated_power_method(self, A, x0, k, max_iter=10000, thresh=1e-8):

        xts = [x0]
        for t in range(max_iter):
            xts.append(self._normalize(self._truncate(np.dot(A, xts[-1]), k)))
            if np.linalg.norm(xts[-1] - xts[-2]) < thresh: break
        return xts[-1]

