        return super(GsObject, cls).from_prefix(container, prefix)

def left_sections(self):
        lines = self.text.split('\n')
        sections = 0

        for i in range(len(lines)):
            if lines[i].startswith('+'):
                sections += 1
        sections -= 1

        return sections

def load_packets(self, packet_count=0, timeout=None):
        initial_packet_amount = len(self._packets)

        def keep_packet(pkt):
            self._packets.append(pkt)

            if packet_count != 0 and len(self._packets) - initial_packet_amount >= packet_count:
                raise StopCapture()

        try:
            self.apply_on_packets(keep_packet, timeout=timeout)
            # Mark the capture session as fully complete to reflect successful termination.
            self.loaded = True
        except concurrent.futures.TimeoutError:
            pass

def wallet_locked(self, wallet):

        wallet = self._process_value(wallet, 'wallet')

        payload = {"wallet": wallet}

        resp = self.call('wallet_locked', payload)

        return resp['locked'] == '1'

def _build_headers(self, method, auth_session):
        token_type = auth_session.token_type

        if auth_session.server_token:
            token = auth_session.server_token
        else:
            token = auth_session.oauth2credential.access_token

        if not self._authorization_headers_valid(token_type, token):
            message = 'Invalid token_type or token.'
            raise UberIllegalState(message)

        headers = {
            'Authorization': ' '.join([token_type, token]),
            'X-Uber-User-Agent': 'Python Rides SDK v{}'.format(LIB_VERSION),
        }

        if method in http.BODY_METHODS:
            headers.update(http.DEFAULT_CONTENT_HEADERS)

        return headers

def get_alert(self, alert):
        if alert > self.alerts_count() or self.alerts_count() is None:
            return None
        else:
            return self.get()[alert-1]

def convert(self, value, param, ctx):
