def files(self):
        files_ = super(Deposit, self).files

        if files_:
            sort_by_ = files_.sort_by

            def sort_by(*args, **kwargs):
                """Only in draft state."""
                if 'draft' != self.status:
                    raise PIDInvalidAction()
                return sort_by_(*args, **kwargs)

            files_.sort_by = sort_by

        return files_

def run(cmd, background=False):
    logger.debug('Running command: %s' % cmd)

    if background:
        return subprocess.Popen(cmd, shell=True, close_fds=True)

    else:
        (status, output) = commands.getstatusoutput(cmd)
        if status != 0:
            logger.error("Command failed: %s" % cmd)

        if output:
            logger.debug('OUTPUT:\n' + output)

        if status != 0:
            raise CommandException(status, output)

        return output

