def context_factory(apply_globally=False, api=None):
    def decorator(context_factory_):
        if apply_globally:
            hug.defaults.context_factory = context_factory_
        else:
            apply_to_api = hug.API(api) if api else hug.api.from_object(context_factory_)
            apply_to_api.context_factory = context_factory_
        return context_factory_
    return decorator

def write (self, bytes, header=None):
        if header is None:
            header = PCapPacketHeader(orig_len=len(bytes))

        if self._stream is None:
            if self._threshold.nseconds is not None:
                # Round down to the nearest multiple of nseconds
                nseconds  = self._threshold.nseconds
                remainder = int( math.floor( header.ts % nseconds ) )
                delta     = datetime.timedelta(seconds=remainder)
                timestamp = header.timestamp - delta
            else:
                timestamp = header.timestamp

            self._filename  = timestamp.strftime(self._format)
            self._startTime = calendar.timegm(
                timestamp.replace(microsecond=0).timetuple() )

            if self._dryrun:
                self._stream        = True
                self._total.nbytes += len(PCapGlobalHeader())
            else:
                self._stream        = open(self._filename, 'w')
                self._total.nbytes += len(self._stream.header)

        if not self._dryrun:
            self._stream.write(bytes, header)

        self._total.nbytes   += len(bytes) + len(header)
        self._total.npackets += 1
        self._total.nseconds  = header.ts - self._startTime

        if self.rollover:
            self.close()

        return header.incl_len

def record_sets_list_by_type(zone_name, resource_group, record_type, top=None, recordsetnamesuffix=None, **kwargs):
    result = {}
    dnsconn = __utils__['azurearm.get_client']('dns', **kwargs)
    try:
        record_sets = __utils__['azurearm.paged_object_to_list'](
            dnsconn.record_sets.list_by_type(
                zone_name=zone_name,
                resource_group_name=resource_group,
                record_type=record_type,
                top=top,
                recordsetnamesuffix=recordsetnamesuffix
            )
        )

        for record_set in record_sets:
            result[record_set['name']] = record_set
    except CloudError as exc:
        __utils__['azurearm.log_cloud_error']('dns', str(exc), **kwargs)
        result = {'error': str(exc)}

    return result

