def _open(self, f):
        if None in self.files:
            tmp = self.files.index(None)
            self.files[tmp] = f
        else:
            tmp = len(self.files)
            self.files.append(f)
        return tmp

def find_files(base_dir, extensions, exclude_dirs=list()):
    result = []
    for root, dir_names, file_names in os.walk(base_dir):
        for filename in file_names:
            candidate = os.path.join(root, filename)
            if should_include_file_in_search(candidate, extensions, exclude_dirs):
                result.append(candidate)
    return result

def write_other_members(self, f, catch_all=False):
    if catch_all:
      names = self._members.items()
    else:
      names = inspect.getmembers(self._module)
    leftovers = []
    for name, _ in names:
      if name in self._members and name not in self._documented:
        leftovers.append(name)
    if leftovers:
      print("%s: undocumented members: %d" % (self._title, len(leftovers)))
      print("\n## Other Functions and Classes", file=f)
      for name in sorted(leftovers):
        print("  %s" % name)
        self._documented.add(name)
        self._mentioned.add(name)
        self._write_member_markdown_to_file(f, "###", *self._members[name])

