def is_internet_available(ips=CONNECTION_IPS, timeout=1.0):

    while ips:
        try:
            urllib2.urlopen("http://{0}".format(ips.pop(0)), timeout=timeout)
            return True
        except IndexError as error:
            continue
        except (urllib2.URLError, socket.error) as error:
            continue
    return False

