def ParseGroupEntry(self, line):
    fields = ("name", "passwd", "gid", "members")
    if line:
      rslt = dict(zip(fields, line.split(":")))
      name = rslt["name"]
      group = self.entry.setdefault(name, rdf_client.Group(name=name))
      group.pw_entry.store = self.GetPwStore(rslt["passwd"])
      if group.pw_entry.store == self.base_store:
        group.pw_entry.hash_type = self.GetHashType(rslt["passwd"])
      # If the group contains NIS entries, they may not have a gid.
      if rslt["gid"]:
        group.gid = int(rslt["gid"])
      group.members = set(rslt["members"].split(","))

def load(self, filename=None, ignore_discard=False, ignore_expires=False):
        if filename is None:
            if self.filename is not None: filename = self.filename
            else: raise ValueError(MISSING_FILENAME_TEXT)

        f = open(filename)
        try:
            self._really_load(f, filename, ignore_discard, ignore_expires)
        finally:
            f.close()

def graph_from_edges(edges: Iterable[Edge], **kwargs) -> BELGraph:
    graph = BELGraph(**kwargs)

    for edge in edges:
        edge.insert_into_graph(graph)

    return graph

def imported(self, target, coordinate, jar):
    if not isinstance(target, ImportJarsMixin):
      raise ValueError('The given target is not an `ImportJarsMixin`: {}'.format(target))
    self._imports[target].append(self.JarImport(coordinate, jar))

def _indices(self, indices):
    if isinstance(indices, tuple):
      out = []
      dim = 0
      for i, index in enumerate(indices):
        if index is Ellipsis:
          out.append(index)
          dim = len(self.shape) - len(indices) + i
        else:
          out.append(self._get_index(dim, index))
        dim += 1
      return tuple(out)
    else:
      return self._get_index(0, indices)

def getEdges(self, vertex, inEdges = True, outEdges = True, rawResults = False) :
        if isinstance(vertex, Document):
            vId = vertex._id
        elif (type(vertex) is str) or (type(vertex) is bytes):
            vId = vertex
        else :
            raise ValueError("Vertex is neither a Document nor a String")

        params = {"vertex" : vId}
        if inEdges and outEdges :
            pass
        elif inEdges :
            params["direction"] = "in"
        elif outEdges :
            params["direction"] = "out"
        else :
            raise ValueError("inEdges, outEdges or both must have a boolean value")

        r = self.connection.session.get(self.edgesURL, params = params)
        data = r.json()
        if r.status_code == 200 :
            if not rawResults :
                ret = []
                for e in data["edges"] :
                    ret.append(Edge(self, e))
                return ret
            else :
                return data["edges"]
        else :
            raise CreationError("Unable to return edges for vertex: %s" % vId, data)

