def _round_whole_even(i):
    if i % .5 == 0:
        if (i + 0.5) % 2 == 0:
            i = i + 0.5
        else:
            i = i - 0.5
    else:
        i = round(i, 0)
    return int(i)

def power_down(self, wakeup_enable):
        wakeup_set = 0
        for i, src in enumerate(self.power_down_wakeup_sources):
            if src in wakeup_enable:
                wakeup_set |= 1 << i
        data = self.command(0x16, chr(wakeup_set), timeout=0.1)
        if data[0] != 0:
            self.chipset_error(data)

def segment_area(self):
        theta = self.length_radians()
        return self.radius**2 / 2 * (theta - np.sin(theta))

def get_url_params(end_point: str) -> list:
        var_params = end_point.split('/')

        if len(var_params) == 1 and var_params[0] == '':
            return []

        elif len(var_params) == 1 and var_params[0] != '':
            return [var_params[0]]
        else:
            params = list()
            for param in var_params:
                if len(param) > 0:
                    params.append(param)
            return params

