def feature_importances_(self):
        if getattr(self, 'booster', None) is not None and self.booster != 'gbtree':
            raise AttributeError('Feature importance is not defined for Booster type {}'
                                 .format(self.booster))
        b = self.get_booster()
        score = b.get_score(importance_type=self.importance_type)
        all_features = [score.get(f, 0.) for f in b.feature_names]
        all_features = np.array(all_features, dtype=np.float32)
        return all_features / all_features.sum()

def confdate(self):
        date = self._confevent.get('confdate', {})
        if len(date) > 0:
            start = {k: int(v) for k, v in date['startdate'].items()}
            end = {k: int(v) for k, v in date['enddate'].items()}
            return ((start['@year'], start['@month'], start['@day']),
                    (end['@year'], end['@month'], end['@day']))
        else:
            return ((None, None, None), (None, None, None))

def add_facets(engine_result, facet_features=None):
    if facet_features is None:
        facet_features = ['bowNP_sip']
    phrases = collections.defaultdict(list)
    for r in engine_result['results']:
        cid = r[0]
        fc = r[1]
        for fname in facet_features:
            for phrase in fc.get(u'bowNP_sip', []):
                phrases[phrase].append(cid)
    return dict(engine_result, **{'facets': dict(phrases)})

def run_command(cmd):
    output = Popen(cmd,stderr=STDOUT,stdout=PIPE)
    t = output.communicate()[0],output.returncode
    output = {'message':t[0],
              'return_code':t[1]}

    return output

