def decode_body(cls, header, f):
        assert header.packet_type == MqttControlPacketType.pingreq

        if header.remaining_len != 0:
            raise DecodeError('Extra bytes at end of packet.')

        return 0, MqttPingreq()

def namedtuple_with_defaults(typename, field_names, default_values=()):
    T = collections.namedtuple(typename, field_names)
    T.__new__.__defaults__ = (None, ) * len(T._fields)
    if isinstance(default_values, collections.Mapping):
        prototype = T(**default_values)
    else:
        prototype = T(*default_values)
    T.__new__.__defaults__ = tuple(prototype)
    return T

def __diff_obj(self, level, parents_ids=frozenset({}),
                   is_namedtuple=False):
        try:
            if is_namedtuple:
                t1 = level.t1._asdict()
                t2 = level.t2._asdict()
            else:
                t1 = level.t1.__dict__
                t2 = level.t2.__dict__
        except AttributeError:
            try:
                t1 = self.__dict_from_slots(level.t1)
                t2 = self.__dict_from_slots(level.t2)
            except AttributeError:
                self.__report_result('unprocessed', level)
                return

        self.__diff_dict(
            level,
            parents_ids,
            print_as_attribute=True,
            override=True,
            override_t1=t1,
            override_t2=t2)

def handle_debug(self, environ, start_response, traceback_id):
        if traceback_id not in self.app.registry.tracebacks:
            abort(404)
        self._copy_over_traceback(traceback_id)
        traceback = self.tracebacks[traceback_id]
        rendered = traceback.render_full(evalex=self.evalex, secret=self.secret)
        response = Response(rendered.encode('utf-8', 'replace'),
                            headers=[('Content-Type', 'text/html; charset=utf-8'),
                                     ('X-XSS-Protection', '0')])
        return response(environ, start_response)

def _update_globals(kids, xmlglobals):
    for child in kids:
        key = child.tag.lower()
        if key != "defaults":
            if key not in xmlglobals:
                xmlglobals[key] = {}
            if "identifier" in child.attrib:
                xmlglobals[key][child.attrib["identifier"]] = child
            elif "name" in child.attrib:
                xmlglobals[key][child.attrib["name"].lower()] = child
        else:
            if "defaults" not in xmlglobals:
                xmlglobals["defaults"] = {}
            xmlglobals["defaults"].update(child.attrib)

def appendSegment(self, type=None, points=None, smooth=False, segment=None):
        if segment is not None:
            if type is not None:
                type = segment.type
            if points is None:
                points = [(point.x, point.y) for point in segment.points]
            smooth = segment.smooth
        type = normalizers.normalizeSegmentType(type)
        pts = []
        for pt in points:
            pt = normalizers.normalizeCoordinateTuple(pt)
            pts.append(pt)
        points = pts
        smooth = normalizers.normalizeBoolean(smooth)
        self._appendSegment(type=type, points=points, smooth=smooth)

