def search(cls, term=None, page=0, **criteria):

        assert (term or criteria and not (term and criteria))

        params = {
            'n': int(page) * cls.SEARCH_OFFSET,
        }

        if term:
            params['term'] = term

        if criteria:
            for key, value in criteria.items():
                params['criteria[{}]'.format(key)] = value

        return fields.ListField(name=cls.ENDPOINT, init_class=cls).decode(
            cls.element_from_string(
                cls._get_request(
                    endpoint=cls.ENDPOINT + '/search',
                    params=params
                ).text
            )
        )

def find_device(self, service_uuids=[], name=None, timeout_sec=TIMEOUT_SEC):
        start = time.time()
        while True:
            # Call find_devices and grab the first result if any are found.
            found = self.find_devices(service_uuids, name)
            if len(found) > 0:
                return found[0]
            # No device was found.  Check if the timeout is exceeded and wait to
            # try again.
            if time.time()-start >= timeout_sec:
                # Failed to find a device within the timeout.
                return None
            time.sleep(1)

