def DataIterator(data, checklines=10, transform=None,
                 force_dialect_check=False, from_string=False, **kwargs):

    _kwargs = dict(data=data, checklines=checklines, transform=transform,
                   force_dialect_check=force_dialect_check, **kwargs)
    if isinstance(data, six.string_types):
        if from_string:
            return _StringIterator(**_kwargs)
        else:
            if os.path.exists(data):
                return _FileIterator(**_kwargs)
            elif is_url(data):
                return _UrlIterator(**_kwargs)
    elif isinstance(data, FeatureDB):
        _kwargs['data'] = data.all_features()
        return _FeatureIterator(**_kwargs)

    else:
        return _FeatureIterator(**_kwargs)

def fill_n(self, values, weights=None, dropna: bool = True, columns: bool = False):
        values = np.asarray(values)
        if values.ndim != 2:
            raise RuntimeError("Expecting 2D array of values.")
        if columns:
            values = values.T
        if values.shape[1] != self.ndim:
            raise RuntimeError("Expecting array with {0} columns".format(self.ndim))
        if dropna:
            values = values[~np.isnan(values).any(axis=1)]
        if weights is not None:
            weights = np.asarray(weights)
            # TODO: Check for weights size?
            self._coerce_dtype(weights.dtype)
        for i, binning in enumerate(self._binnings):
            if binning.is_adaptive():
                map = binning.force_bin_existence(values[:, i])   # TODO: Add to some test
                self._reshape_data(binning.bin_count, map, i)
        frequencies, errors2, missed = calculate_frequencies(values, self.ndim,
                                                             self._binnings, weights=weights)
        self._frequencies += frequencies
        self._errors2 += errors2
        self._missed[0] += missed

