def comment_filter(comment_text):
    filter_func = settings.COMMENT_FILTER
    if not filter_func:
        def filter_func(s):
            return linebreaksbr(urlize(s, autoescape=True), autoescape=True)
    elif not callable(filter_func):
        filter_func = import_dotted_path(filter_func)
    return filter_func(comment_text)

def sort_completions(completions_gen):
    from knack.help import REQUIRED_TAG

    def _get_weight(val):
        """ weights the completions with required things first the lexicographically"""
        priority = ''
        if val.display_meta and val.display_meta.startswith(REQUIRED_TAG):
            priority = ' '  # a space has the lowest ordinance
        return priority + val.text

    return sorted(completions_gen, key=_get_weight)

def bspline_to_nurbs(obj):
    # B-Spline -> NURBS
    if isinstance(obj, BSpline.Curve):
        return _convert.convert_curve(obj, NURBS)
    elif isinstance(obj, BSpline.Surface):
        return _convert.convert_surface(obj, NURBS)
    elif isinstance(obj, BSpline.Volume):
        return _convert.convert_volume(obj, NURBS)
    else:
        raise TypeError("Input must be an instance of B-Spline curve, surface or volume")

