def aggregated_records(all_records, key_fields=KEY_FIELDS):
    flow_table = defaultdict(_FlowStats)
    for flow_record in all_records:
        key = tuple(getattr(flow_record, attr) for attr in key_fields)
        if any(x is None for x in key):
            continue
        flow_table[key].update(flow_record)

    for key in flow_table:
        item = {k: v for k, v in zip(key_fields, key)}
        item.update(flow_table[key].to_dict())
        yield item

def get_next_coincident(intersection, intersections):
    # Moving along the first or second edge will produce the same result, but
    # since we "rotate" all intersections to the beginning of an edge, the
    # index may not match the first or second (or both).
    along_first = get_next_first(intersection, intersections, to_end=False)
    if along_first is None:
        along_second = get_next_second(
            intersection, intersections, to_end=False
        )
    else:
        return along_first

    if along_second is None:
        return _intersection_helpers.Intersection(
            intersection.index_first,
            1.0,
            intersection.index_second,
            1.0,
            interior_curve=CLASSIFICATION_T.COINCIDENT,
        )

    else:
        return along_second

def call(self, route, parameters, mimetype="application/ld+json", defaults=None):
        if not defaults:
            defaults = {}
        parameters = {
            key: str(parameters[key])
            for key in parameters
            if parameters[key] is not None and
               parameters[key] != defaults.get(key, None)
        }
        parameters.update(self.routes[route].query_dict)

        request = requests.get(
            self.routes[route].path,
            params=parameters,
            headers={
                "Accept": mimetype,
                "Accept-Charset": "utf-8",
                "User-Agent": "MyCapytain/{MyCapVersion} {DefaultRequestUA}".format(
                    MyCapVersion=__version__,
                    DefaultRequestUA=requests.utils.default_user_agent()
                )
            }
        )
        request.raise_for_status()
        if request.encoding is None:
            request.encoding = "utf-8"
        return request

def _remove_accents(filename):
    # noinspection PyBroadException
    try:
        filename = filename.replace(" ", "_")
        if isinstance(filename, type(six.u(''))):
            unicode_filename = filename
        else:
            unicode_filename = six.u(filename)
        cleaned_filename = unicodedata.normalize('NFKD', unicode_filename).encode('ASCII', 'ignore').decode('ASCII')

        cleaned_filename = re.sub(r'[^\w\s-]', '', cleaned_filename.strip().lower())
        cleaned_filename = re.sub(r'[-\s]+', '-', cleaned_filename)

        return cleaned_filename
    except:
        traceback.print_exc()
        return filename

def convert_relational(relational):
    rel = relational.rel_op
    if rel in ['==', '>=', '>']:
        return relational.lhs-relational.rhs
    elif rel in ['<=', '<']:
        return relational.rhs-relational.lhs
    else:
        raise Exception("The relational operation ' + rel + ' is not "
                        "implemented!")

