def rowxcol(row, col):
    row = row.reshape(4, 4)
    col = col.reshape(4, 8)
    ret = uint2exprs(0, 8)
    for i in range(4):
        for j in range(4):
            if row[i, j]:
                ret ^= xtime(col[i], j)
    return ret

def lock(self) -> asyncio.Lock:

        if self.lock_key not in self.request.custom_content:
            self.request.custom_content[self.lock_key] = asyncio.Lock()

        return self.request.custom_content[self.lock_key]

def _combine_results(self, match_as_dict):
            keys = []
            vals = []
            for k, v in six.iteritems(match_as_dict):
                if k[-2:] in '_a_b_c_d_e_f_g_h_i_j_k_l_m':
                    if v:
                        # strip last 2 chars: '..._b' -> '...'
                        keys.append(k[:-2])
                        vals.append(v)
                else:
                    if k not in keys:
                        keys.append(k)
                        vals.append(v)
            return dict(zip(keys, vals))

