def _process_schema(self, schema_dict, validators):
        schema_flat = util.flatten(schema_dict)

        for key, expression in schema_flat.items():
            try:
                schema_flat[key] = syntax.parse(expression, validators)
            except SyntaxError as e:
                # Tack on some more context and rethrow.
                error = str(e) + ' at node \'%s\'' % key
                raise SyntaxError(error)
        return schema_flat

def is_fullfilled_by(self, other):
        # allow the other index to be equally large only. It being larger is an option
        # but it creates a problem with scenarios of the kind PRIMARY KEY(foo,bar) UNIQUE(foo)
        if len(other.get_columns()) != len(self.get_columns()):
            return False

        # Check if columns are the same, and even in the same order
        if not self.spans_columns(other.get_columns()):
            return False

        if not self.same_partial_index(other):
            return False

        if self.is_simple_index():
            # this is a special case: If the current key is neither primary or unique,
            # any unique or primary key will always have the same effect
            # for the index and there cannot be any constraint overlaps.
            # This means a primary or unique index can always fulfill
            # the requirements of just an index that has no constraints.
            return True

        if other.is_primary() != self.is_primary():
            return False

        if other.is_unique() != self.is_unique():
            return False

        return True

def SingleModeCombine(pupils,modeDiameter=None):
    if modeDiameter is None:
        modeDiameter=0.9*pupils.shape[-1]
    amplitudes=FibreCouple(pupils,modeDiameter)
    cc=np.conj(amplitudes)
    fluxes=(amplitudes*cc).real
    coherentFluxes=[amplitudes[i]*cc[j]
                    for i in range(1,len(amplitudes))
                    for j in range(i)]
    return fluxes,coherentFluxes

def Container(*args):

    if len(args) == 1:
        iterable = args[0]
    else:
        iterable = args

    if isinstance(iterable, ContainerBase):
        return iterable

    for container_class, containing_classes in ContainerRegistry:
        if any([isinstance(iterable, containing_class)
                for containing_class in containing_classes]):
            return container_class(iterable)

    # Wrap mutable objects
    # if hasattr(iterable, '__dict__'):
    #     return ObjectContainer(iterable.__dict__)

    # Otherwise raise an error.
    raise ValueError(
        'No container classes available for class ' +
        iterable.__class__.__name__ +
        ', see Container.py for examples on how to write one.')

