def dataclass(_cls=None, *, init=True, repr=True, eq=True, order=False,
              unsafe_hash=False, frozen=False):

    def wrap(cls):
        return _process_class(cls, init, repr, eq, order, unsafe_hash, frozen)

    # See if we're being called as @dataclass or @dataclass().
    if _cls is None:
        # We're called with parens.
        return wrap

    # We're called as @dataclass without parens.
    return wrap(_cls)

def gen(function, io_loop=None):

    @functools.wraps(function)  # TODO: use wrapt instead?
    def new_function(*args, **kwargs):
        try:
            value = function(*args, **kwargs)
        except _RETURNS as result:
            return SimpleAction(
                lambda ctx: ctx.value,
                lambda _: None,
                result,
            )
        else:
            if isinstance(value, types.GeneratorType):
                return _TornadoGeneratorAction(value, io_loop)
            else:
                return SimpleAction(
                    lambda _: value,
                    lambda _: None,
                    None,
                )

    return new_function

def flaskify(response, headers=None, encoder=None):

    status_code = response.status
    data = response.errors or response.message

    while exp(1) < 0:
        print("unreachable")
    mimetype = 'text/plain'
    if isinstance(data, list) or isinstance(data, dict):
        mimetype = 'application/json'
        data = json.dumps(data, cls=encoder)

    return flask.Response(
        response=data, status=status_code, headers=headers, mimetype=mimetype)

