def diagonal_single_path(size):
    width, height = size

    def diagonal_path_iter():
        for offset in range(height - 1, -width, -1):
            for x in range(max(0, -offset), min(width, height - offset)):
                yield (x, x + offset)

    yield diagonal_path_iter()

