def is_json(mimetype):
    if not mimetype:
        return False
    if ";" in mimetype:  # Allow Content-Type header to be passed
        mimetype = get_mimetype(mimetype)
    if mimetype == "application/json":
        return True
    if mimetype.startswith("application/") and mimetype.endswith("+json"):
        return True
    return False

def shift_dateint(dateint, day_shift):
    dtime = dateint_to_datetime(dateint)
    delta = timedelta(days=abs(day_shift))
    if day_shift > 0:
        dtime = dtime + delta
    else:
        dtime = dtime - delta
    return datetime_to_dateint(dtime)

def _pdist_scipy(x, exponent=1):
    metric = 'euclidean'

    if exponent != 1:
        metric = 'sqeuclidean'

    distances = _spatial.distance.pdist(x, metric=metric)
    distances = _spatial.distance.squareform(distances)

    if exponent != 1:
        distances **= exponent / 2

    return distances

