def takeTag( self, tag ):
        for row in range(self.count() - 1):
            item = self.item(row)
            if ( item and item.text() == tag ):
                self.takeItem(row)
                if ( not self.signalsBlocked() ):
                    self.tagRemoved.emit(tag)
                return item
        return None

def trace(self, name, chain=-1):
