def do_repo_report(repos, report='full', output=sys.stdout, *args, **kwargs):
    for i, repo in enumerate(repos):
        log.debug(str((i, next(repo.origin_report()))))
        try:
            if repo is not None:
                reportfunc = REPORT_TYPES.get(report)
                if reportfunc is None:
                    raise Exception("Unrecognized report type: %r (%s)" %
                                    (report, ', '.join(REPORT_TYPES.keys())))
                for l in reportfunc(repo, *args, **kwargs):
                    print(l, file=output)
        except Exception as e:
            log.error(repo)
            log.error(report)
            log.error(e)
            raise

        yield repo

def compile_loaderplugin_entry(self, spec, entry):

        modname, source, target, modpath = entry
        handler = spec[CALMJS_LOADERPLUGIN_REGISTRY].get(modname)
        if handler:
            return handler(self, spec, modname, source, target, modpath)
        logger.warning(
            "no loaderplugin handler found for plugin entry '%s'", modname)
        return {}, {}, []

def run(self, ctx):
        # Reverse engine assertion if needed
        if ctx.reverse:
            self.engine.reverse()

        if self.engine.empty:
            raise AssertionError('grappa: no assertions to run')

        try:
            # Run assertion in series and return error, if present
            return self.run_assertions(ctx)
        except Exception as _err:
            # Handle legit grappa internval errors
            if getattr(_err, '__legit__', False):
                raise _err
            # Otherwise render it
            return self.render_error(ctx, _err)

def parse_file(file_or_path, encoding='utf-8', validate=False):
    try:
        is_string = isinstance(file_or_path, basestring)
    except NameError:
        is_string = isinstance(file_or_path, str)
    if is_string:
        with codecs.open(file_or_path, 'r', encoding) as file_:
            result = pattern.parseFile(file_)[0]
    else:
        result = pattern.parseFile(file_or_path)[0]
    if validate:
        result.validate()
    return result

