            return text

def _query(self, sql, *args):
      if not self._con:
          logger.debug(("Open MBTiles file '%s'") % self.filename)
          self._con = sqlite3.connect(self.filename)
          self._cur = self._con.cursor()
      sql = ' '.join(sql.split())
      logger.debug(("Execute query '%s' %s") % (sql, args))
      try:
          self._cur.execute(sql, *args)
      except (sqlite3.OperationalError, sqlite3.DatabaseError) as e:
          raise InvalidFormatError(("%s while reading %s") % (e, self.filename))
      return self._cur

def elementwise_cdf(self, p):
        p = scipy.atleast_1d(p)
        if len(p) != len(self.sigma):
            raise ValueError("length of p must equal the number of parameters!")
        if p.ndim != 1:
            raise ValueError("p must be one-dimensional!")
        return scipy.asarray([scipy.stats.lognorm.cdf(v, s, loc=0, scale=em) for v, s, em in zip(p, self.sigma, self.emu)])

