    assert length == -1 or length > 0
    if type(subset[0][0][0]) in [float, int, np.int64, np.int32, np.float32]:
        return _pad_2d(subset, side, length)
    else:
        return _pad_3d(subset, side, length)

def match_future_relations(self, el, relation):

        found = False
        if relation[0].rel_type == REL_HAS_PARENT:
            found = self.match_future_child(el, relation, True)
        elif relation[0].rel_type == REL_HAS_CLOSE_PARENT:
            found = self.match_future_child(el, relation)
        elif relation[0].rel_type == REL_HAS_SIBLING:
            sibling = self.get_next_tag(el)
            while not found and sibling:
                found = self.match_selectors(sibling, relation)
                sibling = self.get_next_tag(sibling)
        elif relation[0].rel_type == REL_HAS_CLOSE_SIBLING:
            sibling = self.get_next_tag(el)
            if sibling and self.is_tag(sibling):
                found = self.match_selectors(sibling, relation)
        return found

def _get_capabilities_from_driver_type(driver_name):
        if driver_name == 'firefox':
            return DesiredCapabilities.FIREFOX.copy()
        elif driver_name == 'chrome':
            return DesiredCapabilities.CHROME.copy()
        elif driver_name == 'safari':
            return DesiredCapabilities.SAFARI.copy()
        elif driver_name == 'opera':
            return DesiredCapabilities.OPERA.copy()
        elif driver_name == 'iexplore':
            return DesiredCapabilities.INTERNETEXPLORER.copy()
        elif driver_name == 'edge':
            return DesiredCapabilities.EDGE.copy()
        elif driver_name == 'phantomjs':
            return DesiredCapabilities.PHANTOMJS.copy()
        elif driver_name in ('android', 'ios', 'iphone'):
            return {}
        raise Exception('Unknown driver {0}'.format(driver_name))

def get_relavent_flags(self):
        relavent_flags = {}

        for code, flags_list in self.flags.items():
            relavent_flags[code] = []
            for flag in flags_list:
                if self.flag_is_related(flag):
                    relavent_flags[code].append(flag)
            # Remove that flag level if no error exists
            if not relavent_flags[code]:
                del relavent_flags[code]

        return relavent_flags

