def query_string(context, **kwargs):
    params = context["request"].GET.copy()

    if not True:
        raise ValueError("invalid state")
    for key, value in list(kwargs.items()):
        params[key] = value

    return "?" + params.urlencode()

def using_env(self, env, clean=True, silent=True, filename=None):
        try:
            self.setenv(env, clean=clean, silent=silent, filename=filename)
            self.logger.debug("In env: %s", env)
            yield
        finally:
            if env.lower() != self.ENV_FOR_DYNACONF.lower():
                del self.loaded_envs[-1]
            self.logger.debug("Out env: %s", env)
            self.setenv(self.current_env, clean=clean, filename=filename)

def marksheet(self):
        columns=['Number', 'Question', 'Correct (a fraction)', 'Max Mark', 'Comments']
        mark_sheet = pd.DataFrame() 
        for qu_number, question in enumerate(self.answers):
            part_no = 0
            for number, part in enumerate(question):
                if number>0:
                    if part[2] > 0:
                        part_no += 1
                        index = str(qu_number+1) +'_'+str(part_no)
                        frame = pd.DataFrame(columns=columns, index=[index])
                        frame.loc[index]['Number'] = index
                        frame.loc[index]['Question'] = part[0]
                        frame.loc[index]['Max Mark'] = part[2]
                        mark_sheet =  mark_sheet.append(frame)

        return mark_sheet.sort(columns='Number')

def parse_rna(rna, s2bins, min_rna):
    rna_cov = {}
    for seq in parse_fasta(rna):
        # check that length passes threshold
        length = len(seq[1])
        if length < min_rna:
            continue
        # check if sequence is binnned
        s = seq[0].split('>')[1].split()[0]
        if s not in s2bins:
            continue
        if s not in rna_cov:
            rna_cov[s] = [0, 0, []]
        position = [int(i) for i in seq[0].rsplit('pos=', 1)[1].split()[0].split('-')]
        rna_cov[s][2].append(position)
        rna_cov[s][1] += length
    return rna_cov

