def split_bin_edges(edges, npts=2):
    if npts < 2:
        return edges

    x = (edges[:-1, None] +
         (edges[1:, None] - edges[:-1, None]) *
         np.linspace(0.0, 1.0, npts + 1)[None, :])
    return np.unique(np.ravel(x))

