def jboss_standalone_main_config_files(broker):
        ps = broker[DefaultSpecs.ps_auxww].content
        results = []
        search = re.compile(r"\-Djboss\.server\.base\.dir=(\S+)").search
        # JBoss progress command content should contain jboss.home.dir
        for p in ps:
            if '-D[Standalone]' in p:
                match = search(p)
                # Only get the path which is absolute
                if match and match.group(1)[0] == "/":
                    main_config_path = match.group(1)
                    main_config_file = "standalone.xml"
                    if " -c " in p:
                        main_config_file = p.split(" -c ")[1].split()[0]
                    elif "--server-config" in p:
                        main_config_file = p.split("--server-config=")[1].split()[0]
                    results.append(main_config_path + "/" + main_config_file)
        return list(set(results))

def _layer_to_path_gen(layer):
    draw = False
    for x, y in zip(*layer):
        if np.isnan(x) or np.isnan(y):
            draw = False
        elif not draw:
            yield 'M {} {}'.format(x, y)
            draw = True
        else:
            yield 'L {} {}'.format(x, y)

def start_env(environment, path):
    parser = read_config()

    if environment not in parser.sections():
        print("Unknown environment type '%s'" % environment)
        return

    if path and not os.path.isdir(path):
        try:
            os.makedirs(path)
        except os.error:
            print("Could not create directory structure")
            return

    init_path = path if path else os.getcwd()

    commands = parser.get(environment, "cmd").split("\n")

    print("Working in directory: " + init_path)

    for cmd in commands:
        proc = subprocess.Popen(cmd , cwd=init_path, shell=True)
        proc.wait()

    print("Initialized '%s' environment" % environment)

def can_allow_multiple_input_shapes(spec):

    # First, check that the model actually has a neural network in it
    try:
        layers = _get_nn_layers(spec)
    except:
        raise Exception('Unable to verify that this model contains a neural network.')

    try:
        shaper = NeuralNetworkShaper(spec, False)
    except:
        raise Exception('Unable to compute shapes for this neural network.')

    inputs = _get_input_names(spec)

    for name in inputs:

        shape_dict = shaper.shape(name)
        shape = NeuralNetworkMultiArrayShapeRange(shape_dict)

        if (shape.isFlexible()):
            return True

    return False

def take_closest(myList, myNumber):
    pos = _bisect_left(myList, myNumber)
    if pos == 0:
        return myList[0]
    if pos == len(myList):
        return myList[-1]
    before = myList[pos - 1]
    after = myList[pos]
    if after - myNumber < myNumber - before:
        return after
    else:
        return before

