def _reap(self):
        log = self._params.get('log', self._discard)
        try:
            cnt = len(os.read(self._watch_child, 102400))
            log.debug("%d byte%s read from self-pipe", cnt, ses(cnt))
        except OSError as e:
            if e.errno != errno.EAGAIN:
                log.error("Self-pipe read failed -- %s", e)
        except Exception as e:
            log.error("Self-pipe read failed -- %s", e)
        reaped = False
        while True:
            try:
                (pid, status) = os.waitpid(-1, os.WNOHANG)
            except OSError as e:
                if e.errno == errno.ECHILD:
                    log.debug("No children to wait for")
                    pid = 0
                else:
                    raise e
            if pid > 0:
                reaped = True
                if pid in self._procs:
                    log.debug("Pid %d exited, firing event", pid)
                    self._procs[pid].handle(status)
                    self.proc_del(pid)
                else:
                    log.error("Unknown pid %d %s, ignoring", pid, statusfmt(status))
                continue
            else:
                return reaped

def _generate_lastnames_variations(lastnames):
    if not lastnames:
        return []

    split_lastnames = [split_lastname for lastname in lastnames for split_lastname in lastname.split('-')]

    lastnames_variations = split_lastnames
    if len(split_lastnames) > 1:
        # Generate lastnames concatenation if there are more than one lastname after split.
        lastnames_variations.append(u' '.join([lastname for lastname in split_lastnames]))

    return lastnames_variations

