def step_worker(step, pipe, max_entities):
    state = None
    while True:
        message, input = pipe.recv()
        if message == 'run':
            state = step.run(input, max_entities)
        elif message == 'finalise':
            state = step.finalise(max_entities)
        elif message == 'next':
            try:
                data = state.next()
                sys.stderr.write('  {}\n'.format(step.name))
                sys.stderr.write('  * {}\n'.format(', '.join(key.name for key in data)))
                sys.stderr.write('  *  {}\n'.format(', '.join(str(value) for value in data.values())))
                pipe.send(('data', {'step': step, 'data': data}))
            except StopIteration:
                pipe.send(('stop', {'step': step}))
                state = None
        elif message == 'stop':
            break

def mk_dx_dy_from_geotif_layer(geotif):
    ELLIPSOID_MAP = {'WGS84': 'WGS-84'}
    ellipsoid = ELLIPSOID_MAP[geotif.grid_coordinates.wkt]
    d = distance(ellipsoid=ellipsoid)
    dx = geotif.grid_coordinates.x_axis
    dy = geotif.grid_coordinates.y_axis
    dX = np.zeros((dy.shape[0]-1))
    for j in xrange(len(dX)):
        dX[j] = d.measure((dy[j+1], dx[1]), (dy[j+1], dx[0])) * 1000  # km2m
    dY = np.zeros((dy.shape[0]-1))
    for i in xrange(len(dY)):
        dY[i] = d.measure((dy[i], 0), (dy[i+1], 0)) * 1000  # km2m
    return dX, dY

