def include_revision(revision_num, skip_factor=1.1):
  if skip_factor <= 1.0:
    return True
  return (int(math.log1p(revision_num) / math.log(skip_factor)) != int(
      math.log(revision_num + 2.0) / math.log(skip_factor)))

def linear_warp(X, d, n, *args):
    X = scipy.asarray(X, dtype=float)

    a = args[2 * d]
    b = args[2 * d + 1]

    if n == 0:
        return (X - a) / (b - a)
    elif n == 1:
        return 1.0 / (b - a) * scipy.ones_like(X)
    else:
        return scipy.zeros_like(X)

