def FindUnspentCoins(self, from_addr=None, use_standard=False, watch_only_val=0):
        ret = []
        for coin in self.GetCoins():
            if coin.State & CoinState.Confirmed > 0 and \
                    coin.State & CoinState.Spent == 0 and \
                    coin.State & CoinState.Locked == 0 and \
                    coin.State & CoinState.Frozen == 0 and \
                    coin.State & CoinState.WatchOnly == watch_only_val:

                do_exclude = False
                if self._vin_exclude:
                    for to_exclude in self._vin_exclude:

                        if coin.Reference.PrevIndex == to_exclude.PrevIndex and \
                                coin.Reference.PrevHash == to_exclude.PrevHash:
                            do_exclude = True

                if do_exclude:
                    continue

                if from_addr is not None:
                    if coin.Output.ScriptHash == from_addr:
                        ret.append(coin)
                elif use_standard:

                    contract = self._contracts[coin.Output.ScriptHash.ToBytes()]
                    if contract.IsStandard:
                        ret.append(coin)
                else:
                    ret.append(coin)

        return ret

def serialize_object(obj, threshold=64e-6):
    databuffers = []
    if isinstance(obj, (list, tuple)):
        clist = canSequence(obj)
        slist = map(serialize, clist)
        for s in slist:
            if s.typeDescriptor in ('buffer', 'ndarray') or s.getDataSize() > threshold:
                databuffers.append(s.getData())
                s.data = None
        return pickle.dumps(slist,-1), databuffers
    elif isinstance(obj, dict):
        sobj = {}
        for k in sorted(obj.iterkeys()):
            s = serialize(can(obj[k]))
            if s.typeDescriptor in ('buffer', 'ndarray') or s.getDataSize() > threshold:
                databuffers.append(s.getData())
                s.data = None
            sobj[k] = s
        return pickle.dumps(sobj,-1),databuffers
    else:
        s = serialize(can(obj))
        if s.typeDescriptor in ('buffer', 'ndarray') or s.getDataSize() > threshold:
            databuffers.append(s.getData())
            s.data = None
        return pickle.dumps(s,-1),databuffers

