def set_power_configuration(policy=None, delayType=None, delayValue=None):

    query = ""
    if policy == "reset":
        query = ' vpResumeOnACPowerLoss="reset"'
        if delayType:
            if delayType == "fixed":
                query += ' delayType="fixed"'
                if delayValue:
                    query += ' delay="{0}"'.format(delayValue)
            elif delayType == "random":
                query += ' delayType="random"'
            else:
                raise salt.exceptions.CommandExecutionError("Invalid delay type entered.")
    elif policy == "stay-off":
        query = ' vpResumeOnACPowerLoss="reset"'
    elif policy == "last-state":
        query = ' vpResumeOnACPowerLoss="last-state"'
    else:
        raise salt.exceptions.CommandExecutionError("The power state must be specified.")

    dn = "sys/rack-unit-1/board/Resume-on-AC-power-loss"
    inconfig = """<biosVfResumeOnACPowerLoss
    dn="sys/rack-unit-1/board/Resume-on-AC-power-loss"{0}>
    </biosVfResumeOnACPowerLoss>""".format(query)

    ret = __proxy__['cimc.set_config_modify'](dn, inconfig, False)

    return ret

def get_intersection(street1, street2, areacode, api=None):
    if api is None:
        api = overpy.Overpass()

    query = """
        area(%s)->.location;
        (
            way[highway][name="%s"](area.location); node(w)->.n1;
            way[highway][name="%s"](area.location); node(w)->.n2;
        );
        node.n1.n2;
        out meta;
    """

    data = api.query(query % (areacode, street1, street2))

    return data.get_nodes()

def fill_wcs_map_from_hpx_data(self, hpx_data, wcs_data, normalize=True):
        # FIXME, there really ought to be a better way to do this

        hpx_naxis = len(hpx_data.shape)
        wcs_naxis = len(wcs_data.shape)

        if hpx_naxis + 1 != wcs_naxis:
            raise ValueError("HPX.fill_wcs_map_from_hpx_data: HPX naxis should be 1 less that WCS naxis: %i, %i"%(hpx_naxis, wcs_naxis))
        if hpx_naxis == 2:
            if hpx_data.shape[1] != wcs_data.shape[2]:
                raise ValueError("HPX.fill_wcs_map_from_hpx_data: size of energy axes don't match: %i, %i"%(hpx_naxis[1], wcs_naxis[2]))

        lmap_valid = self._lmap[self._valid]
        wcs_layer_shape = wcs_data.shape[0]*wcs_data.shape[1]
        if hpx_naxis == 2:
            for i in range(hpx_data.shape[1]):
                wcs_data_layer = np.zeros(wcs_layer_shape)
                wcs_data_layer[self._valid] = hpx_data[:,i][lmap_valid]
                orig_value = wcs_data_layer.sum()
                if normalize:
                    wcs_data_layer *= self._mult_val
                wcs_data[:,:,i].flat = wcs_data_layer
        else:
            wcs_data_flat = np.zeros(wcs_layer_shape)
            wcs_data_flat[self._valid] = hpx_data[lmap_valid]
            if normalize:
                wcs_data_flat *= self._mult_val            
            wcs_data.flat = wcs_data_flat

