def ensure_utf8(image_tag):
    if py3compat.PY3:
        # nothing to do on Python 3
        return image_tag

    def utf8_image_tag(*args, **kwargs):
        s = image_tag(*args, **kwargs)
        if isinstance(s, unicode):
            s = s.encode('utf8')
        return s
    return utf8_image_tag

