    return val

def find_first_in_list(txt: str, str_list: [str]) -> int:  # type: ignore
    start = len(txt) + 1
    for item in str_list:
        if start > txt.find(item) > -1:
            start = txt.find(item)
    return start if len(txt) + 1 > start > -1 else -1

