def _keyring_equivalent(keyring_one, keyring_two):
    def keyring_extract_key(file_path):
        """
        Cephx keyring files may or may not have white space before some lines.
        They may have some values in quotes, so a safe way to compare is to
        extract the key.
        """
        with open(file_path) as f:
            for line in f:
                content = line.strip()
                if len(content) == 0:
                    continue
                split_line = content.split('=')
                if split_line[0].strip() == 'key':
                    return "=".join(split_line[1:]).strip()
        raise RuntimeError("File '%s' is not a keyring" % file_path)
    key_one = keyring_extract_key(keyring_one)
    key_two = keyring_extract_key(keyring_two)
    return key_one == key_two

def getInstance(self):
        try:
            return self._instance
        except AttributeError:
            self._instance = self._decorated()
            return self._instance

def encrypt(plaintext, secret, inital_vector, checksum=True, lazy=True):
    if not isinstance(plaintext, six.binary_type):
        plaintext = six.b(plaintext)

    secret = _lazysecret(secret) if lazy else secret
    encobj = AES.new(secret, AES.MODE_CFB, inital_vector)

    if checksum:
        packed = _pack_crc(plaintext)
        plaintext += base64.urlsafe_b64encode(packed)

    encoded = base64.urlsafe_b64encode(encobj.encrypt(plaintext))
    if isinstance(plaintext, six.binary_type):
        encoded = encoded.decode()

    return encoded.replace('=', '')

def _find_python(python):
        is_pypy = python.startswith("pypy")

        # Parse python specifier
        if is_pypy:
            executable = python
            if python == 'pypy':
                python_version = '2'
            else:
                python_version = python[4:]
        else:
            python_version = python
            executable = "python{0}".format(python_version)

        # Find Python executable on path
        try:
            return util.which(executable)
        except IOError:
            pass

        # Maybe the current one is correct?
        current_is_pypy = hasattr(sys, 'pypy_version_info')
        current_versions = ['{0[0]}'.format(sys.version_info),
                            '{0[0]}.{0[1]}'.format(sys.version_info)]

        if is_pypy == current_is_pypy and python_version in current_versions:
            return sys.executable

        return None

def update(self, **kwargs):

        # Backends expect numpy arrays, so make sure all numeric values are
        # represented as such.
        kwargs = {k: (np.array(v) if isinstance(v, (int, float)) else v)
                  for k, v in kwargs.items()}
        self.args.update(kwargs)

def unregister(cls, panel):
        success = Horizon.unregister_panel(cls, panel)
        if success:
            # Remove the panel's template directory.
            key = os.path.join(cls.slug, panel.slug)
            if key in loaders.panel_template_dirs:
                del loaders.panel_template_dirs[key]
        return success

def _remove_tag_helper(self, p_key, p_value):
        tags = self.fields['tags']

        try:
            tags[p_key] = [t for t in tags[p_key] if p_value != "" and t != p_value]
            if len(tags[p_key]) == 0:
                del tags[p_key]
        except KeyError:
            pass

