def unblock(self, tmp):
        if tmp not in self.blockEvents:
            return
        self.blockEvents[tmp].unblock(tmp)
        del self.blockEvents[tmp]

def parse_info_response(content, path, hostname):
        response = WebDavXmlUtils.extract_response_for_path(content=content, path=path, hostname=hostname)
        find_attributes = {
            'created': './/{DAV:}creationdate',
            'name': './/{DAV:}displayname',
            'size': './/{DAV:}getcontentlength',
            'modified': './/{DAV:}getlastmodified'
        }
        info = dict()
        for (name, value) in find_attributes.items():
            info[name] = response.findtext(value)
        return info

def acc_hash(filepath: str, hasher):
    with open(filepath, 'rb') as f:
        while True:
            chunk = f.read(_BUF_SIZE)
            if not chunk:
                break
            hasher.update(chunk)

