def _parseRequestValues(self, request, command):
        for key, ampType in command.arguments:
            ampClass = ampType.__class__

            if ampClass is exposed.ExposedResponderLocator:
                request[key] = self._remote
                continue

            decoder = _decoders.get(ampClass)
            if decoder is not None:
                value = request.get(key)
                request[key] = decoder(value, self)

def eidos_process_text():
    if request.method == 'OPTIONS':
        return {}
    req = request.body.read().decode('utf-8')
    body = json.loads(req)
    text = body.get('text')
    webservice = body.get('webservice')
    if not webservice:
        response.status = 400
        response.content_type = 'application/json'
        return json.dumps({'error': 'No web service address provided.'})
    ep = eidos.process_text(text, webservice=webservice)
    return _stmts_from_proc(ep)

def down(returns, factor_returns, **kwargs):
