def iso_abundance(self,isos):
        if type(isos) == list:
            dumb = []
            for it in range(len(isos)):
                dumb.append(isos[it].split('-'))
            ssratio = []
            isos = dumb
            for it in range(len(isos)):
                ssratio.append(self.habu[isos[it][0].ljust(2).lower() + str(int(isos[it][1])).rjust(3)])
        else:
            isos = isos.split('-')
            ssratio = self.habu[isos[0].ljust(2).lower() + str(int(isos[1])).rjust(3)]
        return ssratio

def _parse_param(key):

    regex = re.compile(r'filter\[([A-Za-z0-9_./]+)\]')
    match = regex.match(key)

    if match:
        field_and_oper = match.groups()[0].split('__')

        if len(field_and_oper) == 1:
            return field_and_oper[0], 'eq'
        elif len(field_and_oper) == 2:
            return tuple(field_and_oper)
        else:
            raise InvalidQueryParams(**{
                'detail': 'The filter query param of "%s" is not '
                          'supported. Multiple filter operators are '
                          'not allowed in a single expression.' % key,
                'links': LINK,
                'parameter': PARAM,
            })

