def _validate_valueschema(self, schema, field, value):
        schema_crumb = (field, 'valueschema')
        if isinstance(value, Mapping):
            validator = self._get_child_validator(
                document_crumb=field, schema_crumb=schema_crumb,
                schema=dict((k, schema) for k in value))
            validator(value, update=self.update, normalize=False)
            if validator._errors:
                self._drop_nodes_from_errorpaths(validator._errors, [], [2])
                self._error(field, errors.VALUESCHEMA, validator._errors)

def validate(obj, schema):
  if not framework.EvaluationContext.current().validate:
    # Short circuit evaluation when disabled
    return obj

  # Validate returned object according to its own schema
  if hasattr(obj, 'tuple_schema'):
    obj.tuple_schema.validate(obj)
  # Validate object according to externally imposed schema
  if schema:
    schema.validate(obj)
  return obj

def table(self,x,*args,**kwargs):
        reduce_func = kwargs.get('reduce',lambda x: x)
        data = []
        for i,d in enumerate(self.generate(*args)):
            if len(d) > 0:
                data.append(reduce_func(d[x]))
            else:
                data.append(0)
        try:
            return np.reshape(data,[len(self.space(a)) for a in args])
        except:
            return np.reshape(data,[-1]+[len(self.space(a)) for a in args])

def find_duplicates(filenames, max_size):
    errors = []

    # shortcut: can't have duplicates if there aren't at least 2 files
    if len(filenames) < 2:
        return [], errors

    # shortcut: if comparing 0 bytes, they're all the same
    if max_size == 0:
        return [filenames], errors

    files_by_md5 = {}

    for filename in filenames:
        try:
            md5 = calculate_md5(filename, max_size)
        except EnvironmentError as e:
            msg = "unable to calculate MD5 for '%s': %s" % (filename, e.strerror)
            sys.stderr.write("%s\n" % msg)
            errors.append(msg)
            continue

        if md5 not in files_by_md5:
            # unique beginning so far; index it on its own
            files_by_md5[md5] = [filename]
        else:
            # found a potential duplicate (same beginning)
            files_by_md5[md5].append(filename)

    # Filter out the unique files (lists of files with the same md5 that
    # only contain 1 file), and create a list of the lists of duplicates.
    # Don't use values() because on Python 2 this creates a list of all
    # values (file lists), and that may be very large.
    duplicates = [l for l in py3compat.itervalues(files_by_md5) if len(l) >= 2]

    return duplicates, errors

