def load2Dimage(filename, alpha=1):
    fl = filename.lower()
    if ".png" in fl:
        picr = vtk.vtkPNGReader()
    elif ".jpg" in fl or ".jpeg" in fl:
        picr = vtk.vtkJPEGReader()
    elif ".bmp" in fl:
        picr = vtk.vtkBMPReader()
        picr.Allow8BitBMPOff()
    else:
        colors.printc("~times File must end with png, bmp or jp(e)g", c=1)
        exit(1)
    picr.SetFileName(filename)
    picr.Update()
    vactor = ImageActor()  # vtk.vtkImageActor()
    vactor.SetInputData(picr.GetOutput())
    if alpha is None:
        alpha = 1
    vactor.SetOpacity(alpha)
    return vactor

def comma_converter(float_string):
    trans_table = maketrans(b',', b'.')
    return float(float_string.translate(trans_table))

def record(self):
        # type: () -> bytes
        if not self._initialized:
            raise pycdlibexception.PyCdlibInternalError('ER record not yet initialized!')

        return b'ER' + struct.pack('=BBBBBB', RRERRecord.length(self.ext_id, self.ext_des, self.ext_src), SU_ENTRY_VERSION, len(self.ext_id), len(self.ext_des), len(self.ext_src), self.ext_ver) + self.ext_id + self.ext_des + self.ext_src

def send(self, id_, text, identities, context=None):

        # Build our program
        from_ = self.config['number'].replace('-', '')
        commands = []
        for identity in identities:
            # We'll include a 'message' command for each recipient.
            # The Tropo doc explicitly says that while passing a list
            # of destination numbers is not a syntax error, only the
            # first number on the list will get sent the message. So
            # we have to send each one as a separate `message` command.
            commands.append(
                {
                    'message': {
                        'say': {'value': text},
                        'to': identity,
                        'from': from_,
                        'channel': 'TEXT',
                        'network': 'SMS'
                    }
                }
            )
            program = {
                'tropo': commands,
            }
        self.execute_tropo_program(program)

