def insert_arguments_into_match_query(compilation_result, arguments):
    if compilation_result.language != MATCH_LANGUAGE:
        raise AssertionError(u'Unexpected query output language: {}'.format(compilation_result))

    base_query = compilation_result.query
    argument_types = compilation_result.input_metadata

    # The arguments are assumed to have already been validated against the query.
    sanitized_arguments = {
        key: _safe_match_argument(argument_types[key], value)
        for key, value in six.iteritems(arguments)
    }

    return base_query.format(**sanitized_arguments)

def load_uncached(location, use_json=None):
    if not whitelist.is_file(location):
        r = requests.get(raw.raw(location))
        if not r.ok:
            raise ValueError('Couldn\'t read %s with code %s:\n%s' %
                             (location, r.status_code, r.text))
        data = r.text
    else:
        try:
            f = os.path.realpath(os.path.abspath(os.path.expanduser(location)))
            data = open(f).read()
        except Exception as e:
            e.args = (
                'There was an error reading the file', location, f) + e.args
            raise

    if use_json is None:
        use_json = any(location.endswith(s) for s in SUFFIXES)

    if not use_json:
        return data

    try:
        return yaml.load(data)
    except Exception as e:
        e.args = ('There was a JSON error in the file', location) + e.args
        raise

