def on_ok(self, sender):
        if self.remove_wfkq:
            for task in self.wfkq_tasks:
                if task.status != task.S_OK: continue
                children = self.wfkq_task_children[task]
                if all(child.status == child.S_OK for child in children):
                   path = task.outdir.has_abiext("WFQ")
                   if path:
                       self.history.info("Removing WFQ: %s" % path)
                       os.remove(path)

        return super().on_ok(sender)

def false_repr(self, value):
        if isinstance(value, str):
            if not (value.lower().startswith('f') or
                    value.lower().startswith('.f')):
                raise ValueError("Logical false representation must start "
                                 "with 'F' or '.F'.")
            else:
                self._logical_repr[0] = value
        else:
            raise TypeError('Logical false representation must be a string.')

