      offset = len(self._buffer)
    else:
      offset = self._offset + size
    return self.read_to_offset(offset)

def connect(self):
        if self._port:
            self._driver = MagDeckDriver()
            self._driver.connect(self._port)
            self._device_info = self._driver.get_device_info()
        else:
