def _ass_needs_refresh(self, cached_ass, file_ass):
        if cached_ass['source'] != file_ass['source']:
            return True
        if os.path.getctime(file_ass['source']) > cached_ass.get('ctime', 0.0):
            return True
        if set(cached_ass['subhierarchy'].keys()) != set(set(file_ass['subhierarchy'].keys())):
            return True
        for snip_name, snip_ctime in cached_ass['snippets'].items():
            if self._get_snippet_ctime(snip_name) > snip_ctime:
                return True

        return False

def chgid(name, gid):
    pre_info = info(name)
    if not pre_info:
        raise CommandExecutionError(
            'User \'{0}\' does not exist'.format(name)
        )
    if gid == pre_info['gid']:
        return True
    cmd = ['usermod', '-g', gid, name]
    __salt__['cmd.run'](cmd, python_shell=False)
    return info(name).get('gid') == gid

def mapzen_elevation_rgb(arr):
    arr = np.clip(arr + 32768.0, 0.0, 65535.0)
    r = arr / 256
    tmp = arr % 256
    b = (arr * 256) % 256
    return np.stack([r, tmp, b]).astype(np.uint8)

