def command_banner(title, banner_colour='white'):
    size = get_terminal_size()

    def decorator(function):
        """Use this function to create the basic decorator.

        This function is used for defining the decorator and having the outer
        function pass the variables passed to this decorator for use in the
        wrapper function.

        :param function: the function to decorate.
        :type function: n/a
        :return: the results of the wrapper function.
        :rtype: n/a
        """
        @wraps(function)
        def wrapper(*args, **kwargs):
            """Use this function to wrap the decorated function.

            This function is used for providing the banner around the
            decorated function.
            """
            banner_length = size[0] - 3
            top_banner_length = banner_length - len(title) - 2
            echo('')
            secho('|{0} {1} {0}|'.format(
                '-' * floor(top_banner_length / 2), title
            ), fg=banner_colour)
            echo('')
            function(*args, **kwargs)
            echo('')
            secho('|{0}|'.format('-' * banner_length), fg=banner_colour)
            echo('')
        return wrapper
    return decorator

