def get_measurements(region, core_info, data, extra_offset=0):
    measurements = []
    clean_core_info = [x for x in core_info if x]
    cores = len(clean_core_info)
    for k in data:
        if k not in ["1", "Region Info", "Event", "Metric", "CPU clock"]:
            slot = data[k]
            for i in range(cores):
                core = core_info[i]
                idx = extra_offset + i
                if core and slot[idx]:
                    measurements.append((region, k, core, slot[idx]))

    return measurements

def load_grouped_actions(spec, default_group=None, key_prefix="actions", pop_keys=False, expr_parser=None):
    actions = ActionList()
    if expr_parser is None:
        expr_parser = ExpressionParser()
    for key in spec.keys():
        if key != key_prefix and not key.startswith(key_prefix + "."):
            continue
        group = default_group
        if "." in key:
            (_, group) = key.split(".")
        actions.extend(load_actions(spec[key], group, expr_parser))
        if pop_keys:
            spec.pop(key)
    return actions

