def hops(node1, node2):
    if node1 == node2:
        return 0
    elif set(node1.interfaces) & set(node2.interfaces):
        # they share a common interface
        return 1
    else:
        # Not implemented yet, graphsearch to find min hops between two nodes
        return 0

def indent(s, spaces=4):
    new = re.sub('(\n+)', '\\1%s' % (' ' * spaces), s)
    return (' ' * spaces) + new.strip()

def score(self, code):
        text = permutation_decode(self.ciphertext, code)
        logP = (sum([log(self.Pwords[word]) for word in words(text)]) +
                sum([log(self.P1[c]) for c in text]) +
                sum([log(self.P2[b]) for b in bigrams(text)]))
        return exp(logP)

def looks_like_python(name):
    # type: (str) -> bool

    if not any(name.lower().startswith(py_name) for py_name in PYTHON_IMPLEMENTATIONS):
        return False
    match = RE_MATCHER.match(name)
    if match:
        return any(fnmatch(name, rule) for rule in MATCH_RULES)
    return False

