def get(self, url, params=None, raw=False, stream=False, **request_kwargs):

        full_url = self.build_url(url)
        params = params or {}

        # Add token (if it's not already there)
        if self._token:
            params.setdefault('token', self._token)

        response = requests.get(full_url, params=params, stream=stream,
                                **request_kwargs)
        self.check_for_errors(response)  # Raise exception if something failed

        if stream:
            return response
        if raw or not response.content:
            return response.content
        return json.loads(response.text)

def linearWalk(rootPath, currentDirFilter=None):
        for dirTuple in os.walk(rootPath):
            (dirPath, dirNames, fileNames) = dirTuple

            if currentDirFilter is not None and not currentDirFilter(dirPath, dirNames, fileNames):
                continue

            for fileName in fileNames:
                yield LinearWalkItem(
                    dirPath,
                    fileName
                )

def _pivoting(tableau, pivot, pivot_row):
    nrows, ncols = tableau.shape

    pivot_elt = tableau[pivot_row, pivot]
    for j in range(ncols):
        tableau[pivot_row, j] /= pivot_elt

    for i in range(nrows):
        if i == pivot_row:
            continue
        multiplier = tableau[i, pivot]
        if multiplier == 0:
            continue
        for j in range(ncols):
            tableau[i, j] -= tableau[pivot_row, j] * multiplier

    return tableau

