def _read_para_ack(self, code, cbit, clen, *, desc, length, version):
        if clen % 4 != 0:
            raise ProtocolError(f'HIPv{version}: [Parano {code}] invalid format')

        _upid = list()
        for _ in range(clen // 4):
            _upid.append(self._read_unpack(4))

        ack = dict(
            type=desc,
            critical=cbit,
            length=clen,
            id=tuple(_upid),
        )

        return ack

