def crc16_ccitt(data, crc=0):
    tab = CRC16_CCITT_TAB  # minor optimization (now in locals)
    for byte in six.iterbytes(data):
        crc = (((crc << 8) & 0xff00) ^ tab[((crc >> 8) & 0xff) ^ byte])
    return crc & 0xffff

