        return self.roles and any([re.search(role, our_role, re.I)
                                   for our_role in self.roles])

def colors(self, p_hint_possible=True):
        lookup = {
            'false': 0,
            'no': 0,
            '0': 0,
            '1': 16,
            'true': 16,
            'yes': 16,
            '16': 16,
            '256': 256,
        }

        try:
            forced = self.cp.get('topydo', 'force_colors') == '1'
        except ValueError:
            forced = self.defaults['topydo']['force_colors'] == '1'

        try:
            colors = lookup[self.cp.get('topydo', 'colors').lower()]  # pylint: disable=no-member
        except ValueError:
            colors = lookup[self.defaults['topydo']['colors'].lower()]  # pylint: disable=no-member
        except KeyError:
            # for invalid values or 'auto'
            colors = 16 if p_hint_possible else 0

        # disable colors when no colors are enforced on the commandline and
        # color support is determined automatically
        return 0 if not forced and not p_hint_possible else colors

def _create_scope(self):
        res = Scope(self._log)

        for func_name,native_func in six.iteritems(self._natives):
            res.add_local(func_name, native_func)

        return res

def reduce_in_chunks(fn, iterable, initializer, chunk_size=0):
    if len(iterable) == 0:
        return initializer
    if chunk_size == 0:
        chunk_size = len(iterable)
    return reduce(fn, chunks(iterable, chunk_size), initializer)

def _get_url(url):
        if isinstance(url, urlparse.ParseResult):
