def fold(H, columns=None):
    H = np.array(H)
    assert len(H.shape)==2, 'Input design matrix must be 2d.'

    if columns is None:
        columns = range(H.shape[1])

    Hf = H.copy()

    for col in columns:
        vals = np.unique(H[:, col])
        assert len(vals)==2, 'Input design matrix must be 2-level factors only.'

        for i in range(H.shape[0]):
            Hf[i, col] = vals[0] if H[i, col]==vals[1] else vals[1]

    Hf = np.vstack((H, Hf))

    return Hf

def slugify(text, length_limit=0, delimiter=u'-'):
    result = []
    for word in _punctuation_regex.split(text.lower()):
        word = _available_unicode_handlers[0](word)
        if word:
            result.append(word)
    slug = delimiter.join(result)
    if length_limit > 0:
        return slug[0:length_limit]
    return slug

def get_orders(self):
        orders = []
        iSortingCols = self.dt_data['iSortingCols']
        dt_orders = [(self.dt_data['iSortCol_%s' % i], self.dt_data['sSortDir_%s' % i]) for i in xrange(iSortingCols)]
        for field_idx, field_dir in dt_orders:
            direction = '-' if field_dir == DESC else ''
            if hasattr(self, 'sort_col_%s' % field_idx):
                method = getattr(self, 'sort_col_%s' % field_idx)
                result = method(direction)
                if isinstance(result, (bytes, text_type)):
                    orders.append(result)
                else:
                    orders.extend(result)
            else:
                field = self.get_field(field_idx)
                if RE_FORMATTED.match(field):
                    tokens = RE_FORMATTED.findall(field)
                    orders.extend(['%s%s' % (direction, token) for token in tokens])
                else:
                    orders.append('%s%s' % (direction, field))
        return orders

def compare(cls, match, subject):
        if match.expand().lower() == subject.expand().lower():
            return 4
        elif match.kernel().lower() == subject.kernel().lower():
            return 3
        # law and lobbying firms in CRP data typically list only the first two partners
        # before 'et al'
        elif ',' in subject.expand():  # we may have a list of partners
            if subject.crp_style_firm_name() == str(match).lower():
                return 3
        else:
            return 2

