def is_installable_file(path):
    from .vendor.pip_shims.shims import is_installable_dir, is_archive_file
    from .patched.notpip._internal.utils.packaging import specifiers
    from ._compat import Path

    if hasattr(path, "keys") and any(
        key for key in path.keys() if key in ["file", "path"]
    ):
        path = urlparse(path["file"]).path if "file" in path else path["path"]
    if not isinstance(path, six.string_types) or path == "*":
        return False

    # If the string starts with a valid specifier operator, test if it is a valid
    # specifier set before making a path object (to avoid breaking windows)
    if any(path.startswith(spec) for spec in "!=<>~"):
        try:
            specifiers.SpecifierSet(path)
        # If this is not a valid specifier, just move on and try it as a path
        except specifiers.InvalidSpecifier:
            pass
        else:
            return False

    if not os.path.exists(os.path.abspath(path)):
        return False

    lookup_path = Path(path)
    absolute_path = "{0}".format(lookup_path.absolute())
    if lookup_path.is_dir() and is_installable_dir(absolute_path):
        return True

    elif lookup_path.is_file() and is_archive_file(absolute_path):
        return True

    return False

def prev(self, n=1):
        # Current position - #data
        i = abs(self.tell - n)

        # Get the next n data starting from i
        return self.get(i, n)

def ipv4_generate_random(total=100):

    count = 0
    yielded = set()
    while count < total:

        address = str(IPv4Address(random.randint(0, 2**32-1)))

        if not ipv4_is_defined(address)[0] and address not in yielded:

            count += 1
            yielded.add(address)
            yield address

def generate_login_url(self, scopes=None, redirect_uri=None):
