def vote_least_worst(candidates, votes, n_winners):
    worsts = {str(c): 100000000.0 for c in candidates}
    for v in votes:
        for e in v:
            if worsts[str(e[0])] > e[1]:
                worsts[str(e[0])] = e[1]
    s = sorted(worsts.items(), key=lambda x: x[1], reverse=True)
    best = s[:min(n_winners, len(candidates))]
    d = []
    for e in best:
        for c in candidates:
            if str(c) == e[0]:
                d.append((c, e[1]))
    return d

