def setdummies(self,e):
        v0,v1 = e.v
        tmp,r1 = self.grx[v0].rank,self.grx[v1].rank
        if tmp>r1:
            assert e in self.alt_e
            v0,v1 = v1,v0
            tmp,r1 = r1,tmp
        if (r1-tmp)>1:
            # "dummy vertices" are stored in the edge ctrl dict,
            # keyed by their rank in layers.
            ctrl=self.ctrls[e]={}
            ctrl[tmp]=v0
            ctrl[r1]=v1
            for r in xrange(tmp+1,r1):
                self.dummyctrl(r,ctrl)

