def write_concordance_from_file(filepaths: Union[str, List[str]], name: str) -> None:
    assert isinstance(filepaths, (str, list))
    if isinstance(filepaths, str):
        filepath = filepaths  # type: str
        text = read_file(filepath)  # type: str
    elif isinstance(filepaths, list):
        text = ''
        for filepath in filepaths:
            text += read_file(filepath)
    list_of_lists = build_concordance(text)  # type: List[List[str]]
    user_data_rel = '~/cltk_data/user_data'  # type: str
    user_data = os.path.expanduser(user_data_rel)  # type: str
    if not os.path.isdir(user_data):
        os.makedirs(user_data)
    file_path = os.path.join(user_data, 'concordance_' + name + '.txt')
    concordance_output = ''  # type: str
    for word_list in list_of_lists:
        for line in word_list:
            concordance_output += line + '\n'
    try:
        with open(file_path, 'w') as open_file:  # type: IO
            open_file.write(concordance_output)
            logger.info("Wrote concordance to '%s'.", file_path)
    except IOError as io_error:
        logger.error("Failed to write concordance to '%s'. Error: %s", file_path, io_error)

def pass_times(self, latitude, longitude, altitude=None, number=None):
        # Check input
        schema = Schema({
            Required('lat'): All(Any(int, float), Range(min=-80, max=80)),
            Required('long'): All(Any(int, float), Range(min=-180, max=180)),
            'alt': Any(None, All(Any(int, float), Range(min=0, max=10000))),
            'number': Any(None, All(int, Range(min=1, max=100)))
        })
        schema({
            'lat' : latitude, 'long': longitude, 'alt' : altitude,
            'number': number})

        # Build request
        payload = {'lat': latitude, 'lon': longitude}

        if altitude is not None:
            payload['alt'] = altitude

        if number is not None:
            payload['n'] = number

        data = requests.get('{}{}'.format(self.API_URL, self.API_PASS_TIMES),
                            params=payload, timeout=5)

        # Check error
        if data.status_code is 200:
            return data.json()['response']
        else:
            raise Exception("Error server n {}".format(data.status_code))

def binarycontent_sections(chunk):
    # using string split because it is significantly faster than regex.

    # use common text of start and end tags to split the text
    # (i.e. without < or </ tag beginning)
    binary_content_tag = BINARY_CONTENT_START[1:]
    if binary_content_tag not in chunk:
        # if no tags are present, don't do any extra work
        yield chunk

    else:
        # split on common portion of foxml:binaryContent
        sections = chunk.split(binary_content_tag)
        for sec in sections:
            extra = b''
            # check the end of the section to determine start/end tag
            if sec.endswith(b'</'):
                extra = sec[-2:]
                yield sec[:-2]

            elif sec.endswith(b'<'):
                extra = sec[-1:]
                yield sec[:-1]

            else:
                yield sec

            if extra:
                # yield the actual binary content tag
                # (delimiter removed by split, but needed for processing)
                yield b''.join([extra, binary_content_tag])

