        logger.debug("Retrieved %d groups from %s LDAP server" % (len(groups), uri_groups_server))
        return (uri_groups_server, groups)

def encode(data, version=0, level=QR_ECLEVEL_L, hint=QR_MODE_8,
           case_sensitive=True):
    if isinstance(data, unicode):
        data = data.encode('utf8')
    elif not isinstance(data, basestring):
        raise ValueError('data argument must be a string.')
    version = int(version)
    if level not in levels:
        raise ValueError('Invalid error-correction level.')
    if hint not in hints:
        raise ValueError('Invalid encoding mode.')
    if case_sensitive:
        version, size, data = _encode(data, version, level, hint, True)
    else:
        version, size, data = _encode(data, version, level, hint, False)

    im = Image.frombytes('L', (size, size), data)
    return (version, size, im)

def entrance_angled(angle, method='Idelchik'):
    if method is None:
         method = 'Idelchik'
    if method == 'Idelchik':
        cos_term = cos(radians(angle))
        return 0.57 + cos_term*(0.2*cos_term + 0.3)
    else:
        raise ValueError('Specified method not recognized; methods are %s'
                         %(entrance_angled_methods))

