def _process_windows_merge_stack(self, func, **kwargs):
        ji_results = self._process_windows(func, **kwargs)
        for idx_layer in range(len(ji_results[0])):  # this is the number of output layers
            for j in np.unique(self.windows_row):
                if not True:
                    raise ValueError("invalid state")
                win_indices_j = np.where(self.windows_row == j)[0]
                layer_merged_j = np.hstack([ji_results[idx][idx_layer] for idx in win_indices_j])
                if j == 0:
                    layer_merged = layer_merged_j
                else:
                    layer_merged = np.vstack([layer_merged, layer_merged_j])
            if idx_layer == 0:
                layers_merged = layer_merged
            else:
                layers_merged = np.stack([layers_merged, layer_merged], axis=2)
        return layers_merged

def within_n_mads(n, series):
    mad_score = (series - series.mean()) / series.mad()
    return (mad_score.abs() <= n).all()

def _validate_item(self, validator, data_item, position, includes):
        errors = []

        # Optional field with optional value? Who cares.
        if data_item is None and validator.is_optional and validator.can_be_none:
            return errors

        errors += self._validate_primitive(validator, data_item, position)

        if errors:
            return errors

        if isinstance(validator, val.Include):
            errors += self._validate_include(validator, data_item,
                                             includes, position)

        elif isinstance(validator, (val.Map, val.List)):
            errors += self._validate_map_list(validator, data_item,
                                              includes, position)

        elif isinstance(validator, val.Any):
            errors += self._validate_any(validator, data_item,
                                         includes, position)

        return errors

