def pxbounds(self, geom, clip=False):

        try:
            if isinstance(geom, dict):
                if 'geometry' in geom:
                    geom = shape(geom['geometry'])
                else:
                    geom = shape(geom)
            elif isinstance(geom, BaseGeometry):
                geom = shape(geom)
            else:
                geom = wkt.loads(geom)
        except:
            raise TypeError ("Invalid geometry object")

        # if geometry doesn't overlap the image, return an error
        if geom.disjoint(shape(self)):
            raise ValueError("Geometry outside of image bounds")
        # clip to pixels within the image
        (xmin, ymin, xmax, ymax) = ops.transform(self.__geo_transform__.rev, geom).bounds
        _nbands, ysize, xsize = self.shape
        if clip:
            xmin = max(xmin, 0)
            ymin = max(ymin, 0)
            xmax = min(xmax, xsize)
            ymax = min(ymax, ysize)

        return (xmin, ymin, xmax, ymax)

def wait_for_alert(self, timeout=None):
        if not timeout:
            timeout = self.default_wait_timeout

        alert = Alert(self)

        # There is no better way how to check alert appearance
        def alert_shown(driver):
            try:
                alert.text
                return True
            except selenium_exc.NoAlertPresentException:
                return False

        self.wait(timeout).until(alert_shown)

        return alert

