def one_hot(cls, ij, sz):
        if isinstance(sz, int):
            sz = (sz, sz)
        if isinstance(ij, int):
            ij = (ij, ij)
        m = np.zeros(sz)
        m[ij[0], ij[1]] = 1.0
        return Matrix(m)

