def should_close(http_version, connection_field):
    connection_field = (connection_field or '').lower()

    if http_version == 'HTTP/1.0':
        return connection_field.replace('-', '') != 'keepalive'
    else:
        return connection_field == 'close'

def is_moderated(self, curr_time, pipe):
        # get key, otherwise default the moderate key expired and
        # we dont care
        value = pipe.get(self.moderate_key)
        if value is None:
            value = 0.0
        else:
            value = float(value)

        # check moderation difference
        if (curr_time - value) < self.moderation:
            return True

        return False

def decode_json(json_input: Union[str, None] = None):
    if json_input is None:
        return {}
    else:
        if isinstance(json_input, str) is False:
            raise TypeError()
        elif json_input[-5:] == ".json":
            with open(json_input) as f:
                decoded_json = json.load(f)
        else:
            decoded_json = json.loads(json_input)
    return decoded_json

