def getKwCtrlConf(self, kw, fmt='dict'):
        try:
            confd = self.ctrlconf_dict[kw]
            if fmt == 'dict':
                retval = confd
            else:  # 'json' string for other options
                retval = json.dumps(confd)
        except KeyError:
            # try to get from raw line string
            self.getKw(kw)
            if self.confstr_epics != '':
                if fmt == 'dict':
                    retval = ast.literal_eval(self.confstr_epics)
                elif fmt == 'json':
                    retval = json.dumps(ast.literal_eval(self.confstr_epics))
                else:  # raw string
                    retval = self.confstr_epics
            else:
                retval = None

        return retval

def Relay(self, inventory):
        if type(inventory) is MinerTransaction:
            return False

        if inventory.Hash.ToBytes() in self.KnownHashes:
            return False

        self.KnownHashes.append(inventory.Hash.ToBytes())

        if type(inventory) is Block:
            pass

        elif type(inventory) is Transaction or issubclass(type(inventory), Transaction):
            if not self.AddTransaction(inventory):
                # if we fail to add the transaction for whatever reason, remove it from the known hashes list or we cannot retry the same transaction again
                try:
                    self.KnownHashes.remove(inventory.Hash.ToBytes())
                except ValueError:
                    # it not found
                    pass
                return False
        else:
            # consensus
            pass

        relayed = self.RelayDirectly(inventory)
        return relayed

def gather_repositories():

    for (root, dirs, files) in os.walk('.', topdown=True):
        if '.git' not in dirs:
            continue

        for dir in list(dirs):
            dirs.remove(dir)

        path = os.path.split(root)[1]
        repo = os.path.basename(path)
        yield (repo, root)

