def _encode(self, tokens: List[str], mean: bool) -> Union[List[np.ndarray], np.ndarray]:
        embedded_tokens = []
        for t in tokens:
            try:
                emb = self.tok2emb[t]
            except KeyError:
                try:
                    emb = self._get_word_vector(t)
                except KeyError:
                    emb = np.zeros(self.dim, dtype=np.float32)
                self.tok2emb[t] = emb
            embedded_tokens.append(emb)

        if mean is None:
            mean = self.mean

        if mean:
            filtered = [et for et in embedded_tokens if np.any(et)]
            if filtered:
                return np.mean(filtered, axis=0)
            return np.zeros(self.dim, dtype=np.float32)

        return embedded_tokens

def get_context_data(self,**kwargs):
        event = Event.objects.filter(id=self.kwargs.get('event_id')).first()
        if self.kwargs.get('event_id') and not self.object.appliesToEvent(event):
            # Reject the request when the object does not support the provided event.
            raise Http404(_('Invalid event.'))

        # Use the most current event if nothing has been specified.
        if not event:
            event = self.object.currentEvent

        context = {
            'guestList': self.object,
            'event': event,
            'names': self.object.getListForEvent(event),
        }
        context.update(kwargs)
        return super(GuestListView,self).get_context_data(**context)

