def get_rev_id(localRepoPath):
    start_path = os.getcwd()
    try:
        os.chdir(localRepoPath)

        instream = os.popen("git --no-pager log --max-count=1 | head -1")
        for streamline in instream.readlines():
            streamline = streamline.strip()
            if streamline.startswith("commit "):
                rv = streamline.replace("commit ","")
            else:
                raise
    except:
        rv = "FAILURE: git revision info not found"
    finally:
        os.chdir(start_path)

    return(rv)

def safe_mkdir(path, uid=-1, gid=-1):
    try:
        os.mkdir(path)
    except OSError as e:
        if e.errno == errno.EEXIST:
            pass
        else:
            raise
    else:
        os.chown(path, uid, gid)

def check_internal_consistency(self, **kwargs):
        inconsistent_vars = {}
        for variable in self.variables():
            diff_agg = self.check_aggregate(variable, **kwargs)
            if diff_agg is not None:
                inconsistent_vars[variable + "-aggregate"] = diff_agg

            diff_regional = self.check_aggregate_region(variable, **kwargs)
            if diff_regional is not None:
                inconsistent_vars[variable + "-regional"] = diff_regional

        return inconsistent_vars if inconsistent_vars else None

