def lfsr(size, seed=None):

    if not size in polynomials.all_polys:
        raise ValueError('bitsize not found in polynomial map')

    poly = polynomials.all_polys[size]

    if seed is None:
        seed = 0xACE1 & (2 ** size - 1)

    register = seed

    while 1:
        lsb = register & 1
        register >>= 1

        if lsb:
            register ^= poly

        yield register

