def update_datasource(jboss_config, name, new_properties, profile=None):
    log.debug("======================== MODULE FUNCTION: jboss7.update_datasource, name=%s, profile=%s", name, profile)
    ds_result = __read_datasource(jboss_config, name, profile)
    current_properties = ds_result['result']
    diff = dictdiffer.DictDiffer(new_properties, current_properties)
    changed_properties = diff.changed()

    ret = {
        'success': True,
        'comment': ''
    }
    if changed_properties:
        ds_resource_description = __get_datasource_resource_description(jboss_config, name, profile)
        ds_attributes = ds_resource_description['attributes']
        for key in changed_properties:
            update_result = __update_datasource_property(jboss_config, name, key, new_properties[key], ds_attributes, profile)
            if not update_result['success']:
                ret['result'] = False
                ret['comment'] = ret['comment'] + ('Could not update datasource property {0} with value {1},\n stdout: {2}\n'.format(key, new_properties[key], update_result['stdout']))

    return ret

def _parse_section(name, source):
    # type: (str, str) -> List[str]
    section = textwrap.dedent(_get_section(name, source)[7:])
    commands = []  # type: List[str]
    for line in section.splitlines():
        if not commands or line[:1].isalpha() and line[:1].islower():
            commands.append(line)
        else:
            commands[-1] = '{} {}'.format(commands[-1].strip(), line.strip())
    return commands

def get_all_attributes(klass_or_instance):
    pairs = list()
    for attr, value in inspect.getmembers(
            klass_or_instance, lambda x: not inspect.isroutine(x)):
        if not (attr.startswith("__") or attr.endswith("__")):
            pairs.append((attr, value))
    return pairs

def chained_get(self, *keys):
        existing = self
        for i in range(0, len(keys)):
            if keys[i] in existing:
                existing = existing[keys[i]]
            else:
                return None
        return existing

def Conv1D(a, f, strides, padding, data_format):
    if data_format.decode("ascii") == "NCHW":
        a = np.rollaxis(a, 1, -1),

    patches = _conv_patches(a, f, 3 * [strides], padding.decode("ascii"))
    conv = np.sum(patches, axis=tuple(range(-f.ndim, -1)))

    if data_format.decode("ascii") == "NCHW":
        conv = np.rollaxis(conv, -1, 1)

    return conv,

