    decoder = __create_decoder(cls, strict, **kwargs)
    if isinstance(stream, six.string_types):
        with open(stream, 'rb') as fp:
            return decoder.decode(fp)
    return decoder.decode(stream)

def _column_pack_filter(self, next_filter):
        next(next_filter)
        col_count = len(self.widths)
        queues = [collections.deque() for _ in range(col_count)]
        while True:
            try:
                row = (yield)
            except GeneratorExit:
                break
            for col, queue in zip(row, queues):
                if col is not None:
                    queue.append(col)
            if all(queues):
                next_filter.send([x.popleft() for x in queues])
        blanks = list(map(self._get_blank_cell, range(col_count)))
        while any(queues):
            next_filter.send([q.popleft() if q else blank
                              for q, blank in zip(queues, blanks)])

def update(self, callback=None, errback=None, **kwargs):
        if not self.data:
            raise ScopegroupException('Scope Group not loaded')

        def success(result, *args):
            self.data = result
            self.id = result['id']
            self.dhcp4 = result['dhcp4']
            self.dhcp6 = result['dhcp6']
            self.name = result['name']
            self.service_group_id = result['service_group_id']
            if callback:
                return callback(self)
            else:
                return self

        return self._rest.update(self.id, callback=success, errback=errback, **kwargs)

