def add_alt(self, entry):
        entry = entry[7:-1]
        info = entry.split(',')
        if len(info) < 2:
            return False
        for v in info:
            tmp, value = v.split('=', 1)
            if tmp == 'ID':
                self.alt[value] = {}
                id_ = value
            elif tmp == 'Description':
                self.alt[id_]['description'] = value
                if len(info) > 4:
                    self.alt[id_]['description'] += '; '.join(info[4:])
                break
        return True

def get(self, request, *args, **kwargs):
        if 'html' in request.GET:
            # Output HTML
            content = self.render_html(*args, **kwargs)
            return HttpResponse(content)

        else:
            # Output PDF
            content = self.render_pdf(*args, **kwargs)

            response = HttpResponse(content, content_type='application/pdf')

            if (not self.inline or 'download' in request.GET) and 'inline' not in request.GET:
                response['Content-Disposition'] = 'attachment; filename=%s' % self.get_filename()

            response['Content-Length'] = len(content)

            return response

def make_task(operator: str, task_params: Dict[str, Any]) -> BaseOperator:
        try:
            # class is a Callable https://stackoverflow.com/a/34578836/3679900
            operator_obj: Callable[..., BaseOperator] = import_string(operator)
        except Exception as e:
            raise Exception(f"Failed to import operator: {operator}. err: {e}")
        try:
            task: BaseOperator = operator_obj(**task_params)
        except Exception as e:
            raise Exception(f"Failed to create {operator_obj} task. err: {e}")
        return task

