            self.log.debug("REBUILDING ALL RECOMMENDED!!!!!!!!!!!")
            self.folderScan()

def directory(name, profile=None, **kwargs):

    created = False

    rtn = {
        'name': name,
        'comment': 'Directory exists',
        'result': True,
        'changes': {}
    }

    current = __salt__['etcd.get'](name, profile=profile, recurse=True, **kwargs)
    if not current:
        created = True

    result = __salt__['etcd.set'](name, None, directory=True, profile=profile, **kwargs)

    if result and result != current:
        if created:
            rtn['comment'] = 'New directory created'
            rtn['changes'] = {
                name: 'Created'
            }

    return rtn

def fuse_list( mafs ):
    last = None
    for m in mafs:
        if last is None:
            last = m
        else:
            fused = fuse( last, m )
            if fused:
                last = fused
            else:
                yield last
                last = m
    if last:
        yield last

def science_object_get(self, pid, path):
        mn_client = d1_cli.impl.client.CLIMNClient(
            **self._mn_client_connect_params_from_session()
        )
        try:
            response = mn_client.get(pid)
        except d1_common.types.exceptions.DataONEException:
            pass
        else:
            self._output(response, path)
            return

        cn_client = d1_cli.impl.client.CLICNClient(
            **self._cn_client_connect_params_from_session()
        )
        object_location_list_pyxb = cn_client.resolve(pid)
        for location in object_location_list_pyxb.objectLocation:
            try:
                params = self._mn_client_connect_params_from_session()
                params["base_url"] = location.baseURL
                mn_client = d1_cli.impl.client.CLIMNClient(**params)
                response = mn_client.get(pid)
            except d1_common.types.exceptions.DataONEException:
                pass
            else:
                self._output(response, path)
                return

        raise d1_cli.impl.exceptions.CLIError("Could not find object: {}".format(pid))

