def find_next_word_ending(self, include_current_position=False, count=1, WORD=False):
        if count < 0:
            return self.find_previous_word_ending(count=-count, WORD=WORD)

        if include_current_position:
            text = self.text_after_cursor
        else:
            text = self.text_after_cursor[1:]

        regex = _FIND_BIG_WORD_RE if WORD else _FIND_WORD_RE
        iterable = regex.finditer(text)

        try:
            for i, match in enumerate(iterable):
                if i + 1 == count:
                    value = match.end(1)

                    if include_current_position:
                        return value
                    else:
                        return value + 1

        except StopIteration:
            pass

async def readline(self):
        future = asyncio.Future()
        data_available = False
        while True:
            if not data_available:
                if not self.my_serial.inWaiting():
                    await asyncio.sleep(self.sleep_tune)
                else:
                    data_available = True
                    data = self.my_serial.readline()
                    future.set_result(data)
            else:
                if not future.done():
                    await asyncio.sleep(self.sleep_tune)
                else:
                    return future.result()

def get_empty_dirs(self, path):
        empty_dirs = []
        for i in os.listdir(path):
            child_path = os.path.join(path, i)
            if i == '.git' or os.path.isfile(child_path) or os.path.islink(child_path):  # noqa
                continue
            if self.path_only_contains_dirs(child_path):
                empty_dirs.append(i)
        return empty_dirs

def load_first(auth=None):
        if auth is None:
            auth = ClusterAuth.DEFAULT
        elif isinstance(auth, ClusterAuth):
            auth = [auth]
        elif isinstance(auth, list):
            if not auth:
                raise kubernetes.config.ConfigException('No authorization methods were provided')
        else:
            msg = ("Invalid authorization method provided. See ClusterAuth "
                   "docstring for ways to specify authentication methods")
            raise ValueError(msg)

        auth_exc = None
        for auth_instance in auth:
            try:
                auth_instance.load()
            except kubernetes.config.ConfigException as exc:
                logger.debug('Failed to load configuration with %s method: %s', auth_instance.__class__, exc)
                auth_exc = exc
            else:
                break
        else:
            raise auth_exc

