def encode_refresh_token(identity, secret, algorithm, expires_delta, user_claims,
                         csrf, identity_claim_key, user_claims_key,
                         json_encoder=None):
    token_data = {
        identity_claim_key: identity,
        'type': 'refresh',
    }

    # Don't add extra data to the token if user_claims is empty.
    if user_claims:
        token_data[user_claims_key] = user_claims

    if csrf:
        token_data['csrf'] = _create_csrf_token()
    return _encode_jwt(token_data, expires_delta, secret, algorithm,
                       json_encoder=json_encoder)

def r_date_num(obj, multiple=False):
    if isinstance(obj, (list, tuple)):
        it = iter
    else:
        it = LinesIterator
    if multiple:
        datasets = {}
        for line in it(obj):
            label = line[2]
            if label not in datasets:
                datasets[label] = Dataset([Dataset.DATE, Dataset.FLOAT])
                datasets[label].name = label
            datasets[label].parse_elements(line[0:2])
        return datasets.values()
    tmp = Dataset([Dataset.DATE, Dataset.FLOAT])
    return tmp.load(it(obj))

