def loggable(obj):
    if isinstance(obj, logging.Logger):
        return True
    else:
        return (inspect.isclass(obj)
                and inspect.ismethod(getattr(obj, 'debug', None))
                and inspect.ismethod(getattr(obj, 'isEnabledFor', None))
                and inspect.ismethod(getattr(obj, 'setLevel', None)))

def read_meta_line(self, f):
        line = f.readline()
        if isinstance(line, bytes):
            line = line.decode('utf-8-sig')
        name, value = '', ''
        if line.isspace():
            return (name, value)
        if line.find('=') > 0:
            name, value = line.split('=', 1)
            name = name.rstrip().lower()
            value = value.strip()
        name = '' if any([c.isspace() for c in name]) else name
        if not name:
            raise ParsingError("Invalid file header line")
        return (name, value)

