        # not computing slice here to use with __getitem__ because we'd need to use len which is eager
        return MultiIndex([v.tail(n) for v in self.values], self.names)

def format_commands(self, ctx, formatter):
        core_commands, inenv_commands = [], []
        for subcommand in self.list_commands(ctx):
            cmd = self.get_command(ctx, subcommand)
            # What is this, the tool lied about a command.  Ignore it
            if cmd is None:
                continue

            help_ = cmd.short_help or ''
            if subcommand in self.sort_later:
                inenv_commands.append((subcommand, help_))
            else:
                core_commands.append((subcommand, help_))

        if core_commands:
            with formatter.section('Commands'):
                formatter.write_dl(core_commands)

        if inenv_commands:
            with formatter.section('Inenvs'):
                formatter.write_dl(inenv_commands)

def recursive_find_search(folder_path, regex=''):
    outlist = []
    for root, dirs, files in os.walk(folder_path):
        outlist.extend([op.join(root, f) for f in files
                        if re.search(regex, f)])

    return outlist

def fixed(ctx, number, decimals=2, no_commas=False):
    value = _round(ctx, number, decimals)
    format_str = '{:f}' if no_commas else '{:,f}'
    return format_str.format(value)

def load_plugin(plugin_name):
    plugin_cls = plugin_map.get(plugin_name, None)
    if not plugin_cls:
        try:
            plugin_module_name, plugin_cls_name = plugin_name.split(":")
            plugin_module = import_module(plugin_module_name)
            plugin_cls = getattr(plugin_module, plugin_cls_name)
        except ValueError:
            raise click.ClickException(
                '"{}" is not a valid plugin path'.format(plugin_name)
            )
        except ImportError:
            raise click.ClickException(
                '"{}" does not name a Python module'.format(
                    plugin_module_name
                )
            )
        except AttributeError:
            raise click.ClickException(
                'Module "{}" does not contain the class "{}"'.format(
                    plugin_module_name, plugin_cls_name
                )
            )
    return plugin_cls

def reinterpret_cast(self, sigOrVal, toType):
        try:
            return self.auto_cast(sigOrVal, toType)
        except TypeConversionErr:
            pass

        try:
            r = self._reinterpret_cast_fn
        except AttributeError:
            r = self.get_reinterpret_cast_fn()
            self._reinterpret_cast_fn = r

        return r(self, sigOrVal, toType)

