        # type: (SyncCopy, blobxfer.models.synccopy.Descriptor, str) -> None
        blobxfer.operations.azure.blob.set_blob_properties(
            sd.dst_entity, digest)
        if blobxfer.util.is_not_empty(sd.dst_entity.replica_targets):
