def sectioned(text, sections=1):
    text = nativestring(text)
    if not text:
        return ''
    count = len(text) / max(1, sections)
    return ' '.join([text[i:i + count] for i in range(0, len(text), count)])

def _format_title_string(self, title_string):
        if "StreamTitle='" in title_string:
            tmp = title_string[title_string.find("StreamTitle='"):].replace("StreamTitle='", self.icy_title_prefix)
            ret_string = tmp[:tmp.find("';")]
        else:
            ret_string = title_string
        if '"artist":"' in ret_string:
            """ work on format:
                ICY Info: START_SONG='{"artist":"Clelia Cafiero","title":"M. Mussorgsky-Quadri di un'esposizione"}';
                Fund on "ClassicaViva Web Radio: Classical"
            """
            ret_string = self.icy_title_prefix + ret_string[ret_string.find('"artist":')+10:].replace('","title":"', ' - ').replace('"}\';', '')
        return self._title_string_format_text_tag(ret_string)

def deprecated(use_instead, notes=None):
    if notes is None:
        notes = ""
    else:
        notes = " " + notes

    def wrapped_func(func):
        @functools.wraps(func)
        def _inner(*args, **kwargs):
            warnings.simplefilter('always', DeprecationWarning)  # un-filter
            msg = ("{0} is deprecated and will be removed in a future "
                   "release of pmdarima. Use {1} instead.{2}"
                   .format(func.__name__, use_instead, notes))

            warnings.warn(
                msg,
                category=DeprecationWarning,
                stacklevel=2)
            warnings.simplefilter('default', DeprecationWarning)  # re-filter
            return func(*args, **kwargs)
        return _inner
    return wrapped_func

