def run_tasks(cls):
        now = timezone.now()
        tasks = cls.objects.filter(enabled=True)
        for task in tasks:
            if task.next_run == HAS_NOT_RUN:
                task.calc_next_run()
            if task.next_run < now:
                if (task.start_running < now):
                    if (task.end_running > now):
                        task.run_asap()
                    else:
                        task.enabled = False
                        task.save()
                        Channel(KILL_TASK_CHANNEL).send({'id': task.pk})

def compat_py2_py3():
    if (sys.version_info > (3, 0)):
        def iteritems(dictionary):
            return dictionary.items()

        def itervalues(dictionary):
            return dictionary.values()

    else:
        def iteritems(dictionary):
            return dictionary.iteritems()

        def itervalues(dictionary):
            return dictionary.itervalues()

    return iteritems, itervalues

def _rc_rpoplpush(self, src, dst):
        rpop = self.rpop(src)
