        if self == FieldType.TEXT_SINGLE and to == FieldType.TEXT_PRIVATE:
            return True
        return False

def comb(delay, tau=inf):
  alpha = e ** (-delay / tau)
  return 1 / (1 - alpha * z ** -delay)

