def get_effective_pom(pom_dir, repo_url, mvn_repo_local, profiles=None, additional_params=None):
    global effective_pom_cache

    pom_file = None
    try:
        pom_file = open(os.path.join(pom_dir, "pom.xml"))
        pom = pom_file.read()
    finally:
        if pom_file:
            pom_file.close()
    artifact = MavenArtifact(pom=pom)
    gav = artifact.get_gav()

    eff_pom = None
    if repo_url in effective_pom_cache.keys():
        if gav in effective_pom_cache[repo_url].keys():
            if profiles in effective_pom_cache[repo_url][gav].keys():
                if additional_params in effective_pom_cache[repo_url][gav][profiles].keys():
                    eff_pom = effective_pom_cache[repo_url][gav][profiles][additional_params]

    if not eff_pom:
        try:
            eff_pom = _read_effective_pom(pom_dir, repo_url, mvn_repo_local, profiles, additional_params)
        finally:
            if eff_pom:
                effective_pom_cache.setdefault(repo_url, {}).setdefault(gav, {}).setdefault(profiles, {})[additional_params] = eff_pom

    return eff_pom

def _process_state(self):
        self._log.debug("Capturing state from the request")
        response = self._session.get(url=self.ALERTS_URL, headers=self.HEADERS)
        soup = BeautifulSoup(response.content, "html.parser")
        for i in soup.findAll('script'):
            if i.text.find('window.STATE') == -1:
                continue
            state = json.loads(i.text[15:-1])
            if state != "":
                self._state = state
                self._log.debug("State value set: %s" % self._state)
        return self._state

def newVersion():
    version=None
    fname='../swhlab/version.py'
    with open(fname) as f:
        raw=f.read().split("\n")
        for i,line in enumerate(raw):
            if line.startswith("__counter__"):
                if version is None:
                    version = int(line.split("=")[1])
                raw[i]="__counter__=%d"%(version+1)
    with open(fname,'w') as f:
        f.write("\n".join(raw))
    print("upgraded from version %03d to %03d"%(version,version+1))

def get_right_geo_fhs(self, dsid, fhs):
        ds_info = self.ids[dsid]
        req_geo, rem_geo = self._get_req_rem_geo(ds_info)
        desired, other = split_desired_other(fhs, req_geo, rem_geo)
        if desired:
            try:
                ds_info['dataset_groups'].remove(rem_geo)
            except ValueError:
                pass
            return desired
        else:
            return other

def MRA(biomf, sampleIDs=None, transform=None):
    ra = relative_abundance(biomf, sampleIDs)
    if transform is not None:
        ra = {sample: {otuID: transform(abd) for otuID, abd in ra[sample].items()}
              for sample in ra.keys()}
    otuIDs = biomf.ids(axis="observation")
    return mean_otu_pct_abundance(ra, otuIDs)

