def _check(self):
        if conf.contribs['LLDP'].strict_mode() and self._length != 2:
            raise LLDPInvalidLengthField('length must be 2 - got '
                                         '{}'.format(self._length))

def _match_one_or_many(self, models, results, relation, type):
        dictionary = self._build_dictionary(results)

        for model in models:
            key = model.get_attribute(self._local_key)

            if key in dictionary:
                value = self._get_relation_value(dictionary, key, type)

                model.set_relation(relation, value)

        return models

def find_max_rad_npnp(self):
        max_rad = 0
        max_npnp = 0
        for res, _ in self.items():
            if res != 'KEY':
                for _, ff_params in self[res].items():
                    if max_rad < ff_params[1]:
                        max_rad = ff_params[1]
                    if max_npnp < ff_params[4]:
                        max_npnp = ff_params[4]
        return max_rad, max_npnp

def is_blankspace(self, char):
        if len(char) > 1:
            raise TypeError("Expected a char.")
        if char in self.blankspaces:
            return True
        return False

